window.EXPL={"법무사2016_22-29-2":{"f":"부기등기는 순위번호에 있어서는 그 기초가 되는 주등기에 따르나, 접수번호에 있어서는 그 주등기에 따르지 않지만 그 순위는 주등기의 순위에 따르므로 별도로 순위를 정할 필요가 없다.","w":"부기등기는 접수번호를 따로 받지만 순위는 주등기의 순위에 따른다. 같은 주등기에 붙은 부기등기끼리만 등기한 순서로 순위가 정해진다(부동산등기법 제5조).","c":"상","v":1},"법무사2018_24-18-5":{"f":"국가 등이 중요 정책사업을 시행하기 위하여 공문 등으로 등기사항증명서의 교부 등을 신청한 경우에도 법률에 수수료를 면제하는 규정이 없으면 이를 면제하지 아니한다.","w":"등기사항증명서 교부 등 수수료는 법률로 정한 납부의무여서, 법률에 면제 규정이 없으면 국가 등이 중요 정책사업 때문에 공문으로 신청해도 면제되지 않는다(등기예규 제1409호).","c":"상","v":1},"법무사2019_25-21-3":{"f":"등기소에서 신청인이 주민등록번호 등이 기재된 등기사항증명서를 발급받고자 하는 경우, 담당직원은 신청인으로 하여금 해당 등기기록상 등기명의인의 주민등록번호 등을 등기사항증명서 교부신청서에 기재하게 하거나 구두나 메모형식 등으로 이를 확인하여야 한다.","w":"담당직원은 신청인에게 등기명의인의 주민등록번호 등을 교부신청서에 적게 하거나, 구두나 메모 형식으로 확인해서 입력한다(「부동산등기기록의 주민등록번호 등 공시제한에 따른 업무처리지침」, 등기예규 제1672호).","c":"상","v":1},"법무사2023_29-22-4":{"f":"매각으로 인한 소유권이전등기 촉탁을 할 때에 매수인이 인수하지 아니하는 전세권등기에 이전등기가 부기되어 있는 경우 집행법원은 주등기인 전세권설정등기만 말소 촉탁하면 되고 그 이전의 부기등기는 따로 말소 촉탁할 필요가 없다.","w":"부기등기는 주등기와 한 몸이어서 주등기를 말소하면 부기등기는 등기관이 직권으로 함께 말소한다. 집행법원은 주등기만 말소 촉탁하면 된다.","c":"중","v":1},"법무사2024_30-26-2":{"f":"건물의 소유권보존등기 시에 그 소재 토지가 여러 등기소의 관할에 걸치는 경우에는 관할 등기소의 지정을 신청하여야 하나, 이미 등기되어 있는 건물이 부속건물의 신축에 의하여 여러 등기소의 관할에 걸치게 된 경우에는 관할 등기소의 지정을 신청할 필요가 없다.","w":"관할등기소 지정은 여러 관할에 걸친 부동산에 대한 최초의 등기를 신청할 때 필요하다(부동산등기규칙 제5조 제1항). 이미 등기된 건물에 부속건물을 신축해 여러 관할에 걸치게 된 때에는 종전 관할 등기소에 건물표시변경등기를 신청한다.","c":"중","v":1},"법무사2026_32-23-5":{"f":"(근)저당권자는 그보다 앞의 순위에 있는 (근)저당권설정등기의 신청정보 및 첨부정보를 열람할 수 있으나, 그보다 나중의 순위에 있는 (근)저당권설정등기의 신청정보 및 첨부정보는 열람할 수 없다.","w":"(근)저당권자는 자기보다 앞선 순위의 (근)저당권설정등기의 신청정보·첨부정보는 열람할 수 있지만, 나중 순위의 것은 열람할 수 없다(등기예규 제1876호).","c":"상","v":1},"법무사2026_32-05-3":{"f":"인천A, 김포B, 부천C 부동산에 대한 소유권이전등기와 김포B, 부천C에 대한 근저당권설정등기의 신청은 김포와 부천에 관련 신청사건으로 동시신청할 수 있다.","w":"근저당권설정등기는 김포B·부천C에 대한 것이어서 소유권이전등기와 함께 관련 신청사건으로 동시신청할 수 있는 곳은 김포와 부천 등기소이다. 인천에는 근저당권설정등기를 관련 신청사건으로 동시신청할 수 없다(「관련 사건의 신청 및 처리에 관한 업무처리지침」 예시).","c":"상","v":1},"법무사2018_24-15-2":{"f":"소유권이전등기신청서에 권리소멸의 약정사항을 기재하여 권리소멸의 약정등기를 신청하는 경우에도 이와 동시에 별개의 신청서에 의해 환매특약의 등기를 신청할 수 있다.","w":"권리소멸약정등기와 환매특약등기는 둘 다 부기등기로 하며, 서로를 배제하지 않는다. 환매특약등기는 소유권이전등기와 동시에 별개 신청서로 신청할 수 있다.","c":"중","v":1},"법무사2020_26-09-3":{"f":"판결주문에 가등기에 의한 본등기라는 취지의 기재가 없는 경우에, 판결의 주문에 피고에게 소유권이전청구권가등기에 의한 본등기 절차의 이행을 명하지 않고 매매로 인한 소유권이전등기 절차의 이행을 명한 경우라도, 판결이유에 의하여 피고의 소유권이전등기 절차의 이행이 가등기에 의한 본등기 절차의 이행임이 명백한 경우에는 그 판결을 원인증서로 하여 가등기에 의한 본등기를 신청할 수 있다.","w":"주문에 본등기라는 말이 없어도 판결이유로 가등기에 의한 본등기 절차의 이행임이 명백하면 그 판결로 가등기에 의한 본등기를 신청할 수 있다. 등기관은 이 경우 판결이유를 볼 수 있다(등기예규 제1849호·제1786호).","c":"상","v":1},"법무사2021_27-24-4":{"f":"등기관은 법원의 촉탁에 의한 등기를 실행하는 경우 촉탁서의 기재내용과 촉탁서에 첨부된 판결의 기재내용이 일치하는지 여부를 심사할 수 있다.","w":"등기관은 실체 판단은 못 하지만 신청서와 첨부정보가 서로 일치하는지는 형식적으로 심사한다. 촉탁서와 첨부 판결의 기재가 일치하는지도 심사 대상이다.","c":"중","v":1},"법무사2021_27-21-2":{"f":"이미 건물은 멸실되었으나 아직 건물멸실등기가 이루어지기 전에 가압류등기가 경료된 경우 등기관은 직권으로 그 가압류등기를 말소할 수 없다.","w":"등기기록상으로는 건물이 존재하므로 그 가압류등기는 등기관이 알 수 있는 사유로 각하할 수 없는 등기였다. 직권말소 사유(제58조)에 해당하지 않아 직권으로 말소할 수 없다.","c":"중","v":1},"법무사2016_22-04-5":{"f":"구분한 각 건물 중 대지권이 있는 건물이 있는 경우 그 구분건물등기기록의 1동의 건물의 표제부에는 대지권의 목적인 토지의 표시란과 등기원인 및 기타사항란을 둔다.","w":"1동의 건물 표제부에는 대지권의 목적인 토지의 표시란을 둔다. 대지권종류란과 대지권비율란은 각 전유부분의 표제부에 있다.","c":"중","v":1},"법무사2026_32-21-3":{"f":"재건축조합은 도시 및 주거환경정비법 제63조에 따라 토지 등을 수용하거나 사용할 수 있는 사업시행자에 해당하지 아니하므로, 재건축조합이 도시 및 주거환경정비법 제63조에 의한 사업을 위하여 등기사항증명서의 발급을 신청하는 경우 수수료 면제 대상에 해당하지 않는다.","w":"재건축사업에는 수용 규정이 적용되지 않아 재건축조합은 수용·사용권을 가진 사업시행자가 아니다. 따라서 그 사업을 위한 등기사항증명서 발급 수수료는 면제되지 않는다.","c":"중","v":1},"법무사2017_23-30-2":{"f":"등기관이 집합건물 중 일부 구분건물의 멸실등기를 할 때에는 표제부의 등기를 말소하는 표시를 하되 그 등기기록을 폐쇄하지 아니한다.","w":"멸실한 건물이 구분건물이면 표제부 등기를 말소하는 표시만 하고 그 등기기록은 폐쇄하지 않는다(부동산등기규칙 제103조 제1항 단서).","c":"상","v":1},"법무사2023_29-12-1":{"f":"등기기록이란 1필의 토지 또는 1개의 건물에 관한 등기정보자료를 의미한다.","w":"1필의 토지 또는 1개의 건물에 관한 등기정보자료는 등기기록이다. 등기부는 이 등기기록을 대법원규칙에 따라 편성한 전체를 가리킨다(부동산등기법 제2조).","c":"상","v":1},"법무사2021_27-10-5":{"f":"명의인별 등기정보자료를 제공받기 위해서는 등기소에 방문 후 신청하여 서면으로 정보제공을 받을 수도 있고, 인터넷등기소를 이용하여 이를 신청하거나 송신받는 방법으로 정보제공을 받을 수도 있다.","w":"명의인별 등기정보자료는 등기소에 가서 서면으로 받을 수도 있고, 인터넷등기소에서 신청해 송신받을 수도 있다(등기예규 제1854호).","c":"상","v":1},"법무사2021_27-12-3":{"f":"“말소사항포함 등기부등본”은 말소된 등기사항을 포함하여 수작업폐쇄등기부에 기재된 사항의 전부를 증명하는 등본을 말한다.","w":"말소사항포함 등기부등본은 말소된 사항까지 포함해 수작업폐쇄등기부에 기재된 사항 전부를 증명하는 등본이다. 전산 등기기록의 전부를 증명하는 것은 등기사항전부증명서(말소사항 포함)이다(「부동산등기사항증명서 발급처리지침」, 등기예규 제1815호).","c":"상","v":1},"법무사2020_26-22-2":{"f":"보존기간이 만료된 등기신청정보 및 첨부정보에 대하여는 아직 법원행정처장의 삭제인가 또는 지방법원장의 폐기인가를 받지 않았다면 그 열람을 신청할 수 있다.","w":"보존기간이 지난 신청정보·첨부정보라도 삭제인가나 폐기인가를 받기 전까지는 열람을 신청할 수 있다(등기예규 제1876호).","c":"상","v":1},"법무사2024_30-10-4":{"f":"채권자가 채무자와 사이에 근저당권설정계약을 체결하였으나 그 계약에 기한 근저당권설정등기가 채권자가 아닌 제3자의 명의로 마쳐지고 그 후 다시 채권자가 위 근저당권설정등기에 대한 부기등기의 방법으로 위 근저당권을 이전받았다면 위 근저당권설정등기는 실체관계에 부합하는 유효한 등기로 볼 수 있다.","w":"판례는 제3자 명의로 설정된 근저당권을 채권자가 부기등기로 이전받아 등기명의와 실체가 일치하게 된 경우 그 근저당권설정등기를 유효로 본다.","c":"중","v":1},"법무사2019_25-22-1":{"f":"하천법상 하천에 대하여는 소유권보존등기나 소유권이전등기를 신청할 수 있고, 저당권설정등기나 신탁등기도 신청할 수 있다.","w":"하천법상 하천도 소유권이전과 저당권설정은 허용되고(하천법 제4조 제2항), 등기예규 제1387호는 신탁등기도 할 수 있는 등기로 든다. 하천에 할 수 없는 것은 지상권·지역권·전세권·임차권에 관한 등기다.","c":"상","v":1},"법무사2023_29-23-1":{"f":"1동의 건물이 여러 개의 건물부분으로 이용상 구분된 구분점포가 구분소유의 목적이 되기 위해서는 그 용도가 건축법상 판매시설 또는 운수시설이고 경계표지와 건물번호표지가 견고하게 설치되어 있어야 하나, 바닥면적의 합계가 1천제곱미터 이상일 것을 요하지 않는다.","w":"구분점포의 바닥면적 합계 1천제곱미터 이상 요건은 2020. 2. 4. 집합건물법 개정으로 삭제되었다. 지금은 용도가 판매시설·운수시설이고 경계표지와 건물번호표지를 견고하게 설치하면 된다(집합건물법 제1조의2 제1항).","c":"상","v":1},"법무사2026_32-22-1":{"f":"건축물대장에 구조가 콘테이너이고 지붕 또한 콘테이너로 등재되어 있는 건축물에 대해서는 소유권보존등기를 할 수 없다.","w":"콘테이너를 구조와 지붕으로 하는 건축물은 토지에 정착한 건물로 볼 수 없어 등기능력이 없다.","c":"중","v":1},"법무사2026_32-22-2":{"f":"주된 건물의 사용에만 제공되는 부속건물도 그 자체를 독립된 하나의 건물로 등기를 할 수 있다.","w":"부속건물은 주된 건물과 1개의 건물로 보존등기하는 것이 원칙이지만, 주된 건물과 부속건물의 건축물대장이 따로 작성되어 있으면 소유자가 부속건물을 독립건물로 보존등기할 수 있다(등기예규 제902호).","c":"상","v":1},"법무사2026_32-22-3":{"f":"개방형 축사가 건축물대장 생성 당시에는 연면적이 200제곱미터를 초과하지 않아 축사의 부동산등기에 관한 특례법에 따른 등기능력이 인정되지 아니하였으나, 이후 대장상 소유권이전등록을 받은 자가 이를 증축하여 연면적이 200제곱미터를 초과하게 되었다면 증축 후 대장에 소유자로 등록된 그 자가 자신의 명의로 소유권보존등기를 신청할 수 있다.","w":"보존등기는 건축물대장상 소유자로 등록된 자가 신청한다. 증축으로 연면적 요건을 갖춘 때의 대장상 소유자가 신청인이고 최초 소유자가 아니다. 현행 축사의 부동산등기에 관한 특례법 제3조 제5호의 연면적 요건은 100제곱미터 초과이다(2019. 8. 20. 개정, 종전 200제곱미터).","c":"중","v":1},"법무사2026_32-22-4":{"f":"가설건축물대장에 등록된 ‘농업용 고정식 비닐온실’이 철근콘크리트 기초 위에 설치됨으로써 토지에 견고하게 정착되어 있고, 경량철골구조 및 내구성 10년 이상의 내재해형 장기성 필름(비닐)에 의하여 벽면과 지붕을 구성하고 있다면 소유권보존등기를 신청할 수 있다.","w":"기초에 정착되고 벽과 지붕이 내구성 있는 구조로 갖춰진 고정식 비닐온실은 건물로 인정되어 소유권보존등기를 신청할 수 있다.","c":"상","v":1},"법무사2025_31-12-3":{"f":"열람신청인은 열람신청을 거부하는 처분에 대하여 이의신청을 할 수 있다. 이의신청은 열람신청을 반려한 등기관이 속한 등기소에 이의신청서를 제출하는 방법으로 하고, 전산정보처리조직을 이용하여 이의신청정보를 보내는 방법으로는 할 수 없다.","w":"열람 거부 처분에 대한 이의신청에는 부동산등기법 제101조 중 전산정보처리조직으로 이의신청정보를 보내는 방법을 적용하지 않는다. 이의신청서를 등기소에 내야 한다(「부동산등기 신청정보 및 첨부정보의 열람에 관한 업무처리지침」 제12조 제2항).","c":"상","v":1},"법무사2020_26-15-3":{"f":"이의신청서류 편철장은 10년간 보존하여야 한다.","w":"이의신청서류 편철장의 보존기간은 10년이다(부동산등기규칙 제25조 제1항 제4호). 5년은 부동산등기신청서 접수장과 신청서 기타 부속서류 편철장의 보존기간이다.","c":"상","v":1},"법무사2019_25-07-4":{"f":"주택건설사업이 완성되어 건설된 주택에 대하여 사업주체가 주택법상 입주예정자 앞으로 소유권이전등기를 신청한 경우, 등기관은 그 소유권이전등기를 실행할 때에 직권으로 주택에 대한 금지사항 부기등기를 말소한다.","w":"사업주체가 입주예정자 앞으로 소유권이전등기를 신청하면 등기관이 그 이전등기를 마친 뒤 금지사항 부기등기를 직권으로 말소한다. 당사자의 신청은 필요 없다(등기예규 제1616호).","c":"상","v":1},"법무사2018_24-10-2":{"f":"중복등기기록 중 어느 한 등기기록의 최종 소유권의 등기명의인이 다른 등기기록의 최종 소유권의 등기명의인으로부터 직접 또는 전전하여 소유권을 이전받은 경우로서, 다른 등기기록이 나중에 개설된 등기기록이거나 소유권 외의 권리 등에 관한 등기가 없는 먼저 개설된 등기기록일 때에는 그 다른 등기기록을 폐쇄한다.","w":"이 경우 폐쇄하는 다른 등기기록은 후등기기록이거나, 소유권 외의 권리 등에 관한 등기가 없는 선등기기록이다(부동산등기규칙 제35조). 먼저 개설된 기록과 나중에 개설된 기록의 자리가 서로 바뀌면 틀린다.","c":"상","v":1},"법무사2023_29-30-3":{"f":"건물의 보존등기명의인이 서로 다른 경우 어느 등기기록상의 등기를 기초로 한 새로운 등기신청이라도 이를 수리한다.","w":"선행 등기기록을 기초로 한 신청만 수리하고 후행 등기기록을 기초로 한 신청은 각하하는 것은 보존등기명의인이 같은 경우이다. 명의인이 서로 다르면 어느 한쪽 등기기록을 기초로 한 새로운 등기신청도 수리한다(「건물 중복등기 정리절차에 관한 업무처리지침」, 등기예규 제1374호).","c":"상","v":1},"법무사2025_31-21-4":{"f":"등기된 토지의 대장상 분할된 일부에 관하여 중복하여 소유권보존등기나 멸실회복등기가 경료된 경우 그 일부토지부분에 관하여는 중복등기로 보아야 한다.","w":"이미 등기된 토지의 대장상 분할된 일부에 다시 보존등기나 멸실회복등기가 된 경우 그 일부 토지 부분은 중복등기로 본다(「중복등기의 정리에 관한 사무처리지침」, 등기예규 제1431호).","c":"상","v":1},"법무사2017_23-03-5":{"f":"법정대리인이 본인을 대리하여 등기를 신청한 경우 등기필정보는 그 법정대리인에게 통지하여야 한다.","w":"법정대리인이 등기를 신청한 경우 등기필정보는 본인이 아니라 그 법정대리인에게 통지한다(부동산등기규칙 제108조 제2항).","c":"상","v":1},"법무사2017_23-08-4":{"f":"공익법인이 기본재산을 처분할 때에 등기원인을 증명하는 서면이 소유권이전등기절차를 이행하라는 확정판결이라도 주무관청의 허가서를 첨부하여 등기신청을 하여야 한다.","w":"공익법인의 기본재산 처분에는 주무관청의 허가를 증명하는 서면이 필요하고, 판결에 따른 소유권이전등기라도 행정관청의 허가를 증명하는 서면은 반드시 제출해야 한다(「판결 등 집행권원에 의한 등기의 신청에 관한 업무처리지침」, 부동산등기특별조치법 제5조 제1항).","c":"상","v":1},"법무사2017_23-09-1":{"f":"재심의 소에 의하여 재심대상 판결이 취소된 경우 그 재심판결로 취소된 판결에 의하여 마쳐진 소유권이전등기의 말소등기를 신청할 수 없다.","w":"재심판결로 종전 판결이 취소되어도 그 판결에 따라 마친 이전등기를 말소하라는 내용이 재심판결에 없으면 재심판결만으로 말소등기를 신청할 수 없다.","c":"중","v":1},"법무사2017_23-09-2":{"f":"판결에 의한 등기신청은 승소한 등기권리자 또는 승소한 등기의무자가 단독으로 신청할 수 있고, 승소한 등기권리자가 신청할 때에는 등기필정보를 제공할 필요가 없으나 승소한 등기의무자가 신청할 때에는 등기필정보를 제공하여야 한다.","w":"승소한 등기권리자의 단독신청에는 등기의무자의 등기필정보가 필요 없다. 승소한 등기의무자가 단독신청하면 자신의 등기필정보를 제공해야 한다.","c":"중","v":1},"법무사2017_23-09-4":{"f":"사해행위취소판결에 의한 등기에 있어서 등기원인은 ‘사해행위취소’이고, 그 연월일은 ‘판결확정일’이다.","w":"사해행위취소는 형성판결이어서 판결이 확정된 때 효력이 생긴다. 등기원인일자는 판결선고일이 아니라 판결확정일이다.","c":"중","v":1},"법무사2017_23-09-5":{"f":"판결의 주문에 등기절차의 이행과 반대급부의 이행이 각각 독립적으로 기재되어 있다면 반대급부의 이행을 증명하기 위한 집행문을 등기신청서에 제공할 필요가 없다.","w":"주문에서 등기절차 이행과 반대급부 이행이 독립적으로 기재되어 있으면 등기는 반대급부와 무관하게 신청할 수 있어 집행문이 필요 없다.","c":"상","v":1},"법무사2017_23-27-4":{"f":"지방자치단체의 관할구역이 변경되어 승계되는 재산에 대하여는 승계받는 지방자치단체 명의로 소유권이전등기를 촉탁하여야 한다.","w":"관할구역 변경으로 재산이 다른 지방자치단체에 승계되면 소유자가 바뀌므로 승계받는 지방자치단체 명의로 소유권이전등기를 촉탁한다. 관리청변경등기는 국유재산의 관리청이 바뀌는 경우에 하는 등기이다.","c":"중","v":1},"법무사2018_24-14-4":{"f":"상속등기를 하지 아니한 부동산에 대하여 상속인을 상대로 한 가압류결정이 있을 때에는 가압류채권자가 대위에 의한 상속등기를 먼저 거친 뒤 가압류등기를 하여야 한다.","w":"상속등기가 되어 있지 않으면 등기의무자 표시가 등기기록과 맞지 않는다. 가압류채권자가 대위하여 상속등기를 먼저 하고 가압류 기입등기를 촉탁한다.","c":"상","v":1},"법무사2018_24-21-4":{"f":"서면으로 등기를 신청한 경우에 등기필정보를 부여받을 사람에게는 등기필정보가 함께 기재된 등기필정보 및 등기완료통지서로 등기완료사실을 통지한다.","w":"서면신청에서 등기필정보를 부여받을 사람에 대한 등기완료통지는 등기필정보를 함께 적은 「등기필정보 및 등기완료통지서」 양식으로 한다(「등기완료통지서의 작성 등에 관한 업무처리지침」). 등기필정보 통지만으로 완료통지를 생략하는 방식이 아니다.","c":"중","v":1},"법무사2019_25-08-4":{"f":"토지에 대한 소유권이전등기 청구사건에서 원고가 판결확정 후 사망한 경우에 원고의 지위를 승계한 상속인은 상속을 증명하는 정보를 첨부하여 직접 상속인 명의로 소유권이전등기를 신청할 수 있다.","w":"승소한 등기권리자가 변론종결 뒤 사망하면 상속인은 상속을 증명하는 서면을 붙여 곧바로 자기 명의로 등기를 신청한다. 피상속인 명의로 먼저 등기할 필요도, 승계집행문도 필요 없다(등기예규 제1786호).","c":"상","v":1},"법무사2021_27-29-4":{"f":"농지에 대한 소유권이전청구권의 보전을 위한 가등기의 신청서에는 농지취득자격증명을 첨부할 필요가 없다.","w":"가등기는 농지를 취득하는 등기가 아니어서 농지취득자격증명을 요구하지 않는다. 본등기를 신청할 때 첨부한다.","c":"상","v":1},"법무사2022_28-16-5":{"f":"가등기가처분명령에 의하여 가등기를 신청하는 경우 가등기의 원인이 토지거래계약허가의 대상이면 토지거래계약허가증을 첨부정보로 제공하여야 한다.","w":"허가구역 토지의 소유권·지상권 이전·설정청구권 가등기를 신청할 때에는 토지거래계약허가증을 첨부해야 하고(등기예규 제1634호), 가등기가처분명령에 의한 신청이라고 해서 이 요건이 빠지지 않는다.","c":"중","v":1},"법무사2023_29-17-2":{"f":"등기관이 착오로 여러 명의 등기권리자 중 일부를 누락하여 직권으로 등기권리자를 추가하는 경정등기를 하는 경우에는 그 추가되는 등기권리자에 대한 등기필정보를 작성하여 통지한다.","w":"권리자를 추가하는 경정등기를 하면 추가된 권리자에 대한 등기필정보를 작성한다. 등기관이 직권으로 경정하는 경우도 같다(등기예규 제1853호).","c":"상","v":1},"법무사2023_29-24-1":{"f":"소유권 외의 권리의 등기명의인이 등기의무자로서 등기필정보가 없어 등기소에 출석하여 등기관으로부터 등기의무자임을 확인받는 때에는 등기의무자의 인감증명을 제출하여야 한다.","w":"소유권 외의 권리의 등기명의인이 등기의무자로서 등기필정보 없이 등기관의 확인을 받아 신청하면 그 등기명의인의 인감증명을 제출해야 한다(부동산등기규칙 제60조 제1항 제3호).","c":"상","v":1},"법무사2023_29-24-2":{"f":"등기신청서에 첨부하는 인감증명은 발행일부터 3개월 이내의 것이어야 한다.","w":"등기신청서에 첨부하는 인감증명은 발행일부터 3개월 이내의 것이어야 한다(부동산등기규칙 제62조).","c":"상","v":1},"법무사2023_29-24-4":{"f":"등기신청서 등에 서명을 하고 본인서명사실 확인 등에 관한 법률에 따라 발급된 본인서명사실확인서를 첨부한 경우에는 인감증명서를 제출한 것으로 본다.","w":"본인서명사실확인서는 인감을 날인한 서면이 아니라 본인이 서명한 서면에 첨부할 때 인감증명서를 대신한다. 인감을 날인하면서 본인서명사실확인서를 붙이는 방식은 인정되지 않는다.","c":"상","v":1},"법무사2023_29-24-5":{"f":"인감을 날인하고 인감증명의 제출이 필요한 경우 교도소에 재감 중인 자라도 인감증명서를 제출하여야 하고, 인감을 날인하여야 하는 서면에 무인하고 교도관의 확인을 받는 방법으로 인감증명의 제출에 갈음할 수 없다.","w":"재감자도 인감증명서를 발급받을 수 있으므로 인감증명을 내야 하고, 무인한 서면에 교도관 확인을 받는 것으로 인감증명 제출을 생략할 수 없다(등기예규 제423호 「재감자의 무인한 위임장의 가부」).","c":"상","v":1},"법무사2024_30-21-1":{"f":"등기필정보는 분실하더라도 재발급되지 않는다.","w":"등기필정보는 분실해도 재발급받을 수 없다. 등기필정보가 없으면 확인서면, 공증, 등기관의 확인조서 중 하나로 대신해 등기의무자임을 확인받는다.","c":"상","v":1},"법무사2021_27-13-4":{"f":"공유물을 분할하는 판결에 의한 등기는 등기권리자 또는 등기의무자가 단독으로 신청할 수 있다.","w":"공유물분할 판결로 하는 지분이전등기는 승소한 등기권리자뿐 아니라 승소한 등기의무자도 단독으로 신청할 수 있다.","c":"상","v":1},"법무사2024_30-20-3":{"f":"관공서가 등기의무자로서 등기를 촉탁하는 경우뿐만 아니라 관공서가 등기권리자로서 등기를 촉탁하는 경우에도 등기의무자의 등기필정보를 제공할 필요가 없다.","w":"관공서가 등기의무자로서 촉탁하든, 부동산에 관한 권리를 취득해 등기권리자로서 촉탁하든 등기의무자의 등기필정보는 제공하지 않는다(「관공서의 촉탁등기에 관한 예규」 4.).","c":"상","v":1},"법무사2020_26-19-4":{"f":"가처분 대상 부동산이 여러 개이고 부동산별로 피보전권리의 채권자가 다르면 1개의 부동산처분금지가처분 결정이 있더라도 1개의 촉탁서로 일괄하여 가처분등기를 촉탁할 수 없다.","w":"피보전권리의 채권자가 부동산마다 다르면 가처분 결정이 하나여도 촉탁서를 따로 작성한다. 일괄촉탁은 등기목적과 원인이 같은 경우에 한한다.","c":"중","v":1},"법무사2026_32-04-4":{"f":"주택도시보증공사는 주택도시기금법 제34조의6에 따라 국세 강제징수의 예에 의하여 압류 및 공매를 하는 경우 그에 따른 등기를 촉탁할 수 있다.","w":"주택도시기금법은 주택도시보증공사가 국세 강제징수의 예에 따라 압류·공매를 할 때 관공서처럼 등기를 촉탁할 수 있게 정해 두었다.","c":"중","v":1},"법무사2020_26-11-2":{"f":"국가나 지방자치단체로부터 농지를 매수하여 소유권이전등기를 신청하는 경우 및 농지전용허가를 받거나 농지전용신고를 한 농지에 대하여 소유권이전등기를 신청하는 경우에도 농지취득자격증명을 첨부하여야 한다.","w":"국가나 지방자치단체로부터 농지를 사는 경우와 농지전용허가를 받거나 전용신고를 한 농지를 취득하는 경우 모두 농지취득자격증명을 첨부해야 한다(등기예규 제1635호). 면제되는 것은 국가나 지방자치단체가 농지를 취득하는 경우다.","c":"상","v":1},"법무사2021_27-06-2":{"f":"금융기관의 지배인이 등기권리자인 법인의 대리인 겸 등기의무자의 대리인으로서 계속 반복적으로 근저당권설정등기 신청업무를 수행하였다면 신청대행수수료를 받지 않았더라도 법무사법 제3조 제1항에 위반된다.","w":"법무사법상 '업으로 한다'는 것은 계속 반복해서 하는 것이고 보수를 받았는지와 무관하다. 대행수수료를 받지 않았다는 사정으로 위반을 면하지 못한다.","c":"중","v":1},"법무사2024_30-03-1":{"f":"지배인은 영업주에 갈음하여 그 영업에 관한 재판상 또는 재판 외의 모든 행위를 할 수 있는 자이지만, 금융기관의 지배인이 신청대행수수료를 받지 않고 등기권리자인 법인의 대리인 겸 등기의무자의 대리인으로서 계속 반복적으로 근저당권설정등기 신청업무를 수행하면 법무사가 아닌 자는 법무사의 업무에 속하는 사무를 업으로 하지 못한다고 규정하는 법무사법 제3조 제1항에 위반된다.","w":"양쪽 당사자를 계속 반복해서 대리해 등기신청을 하면 수수료를 받지 않았어도 법무사 업무를 업으로 한 것이다. 지배인이라는 지위로 이 제한을 벗어나지 못한다.","c":"중","v":1},"법무사2024_30-03-2":{"f":"친권자가 미성년자인 자 소유의 부동산을 채무자인 그 미성년자를 위하여 담보로 제공하거나 제3자에게 처분하는 경우에는 그 미성년자인 자에 관한 특별대리인의 선임이 필요하지 않다.","w":"미성년자 자신의 채무를 위해 그 부동산을 담보로 제공하는 것은 친권자와 미성년자 사이의 이해상반 행위가 아니다. 특별대리인 선임이 필요 없다.","c":"상","v":1},"법무사2024_30-03-4":{"f":"등기권리자와 등기의무자 쌍방으로부터 등기신청 절차의 위임을 받은 법무사는 그 절차가 끝나기 전에 등기의무자로부터 등기신청을 중지해 달라는 요청을 받았더라도 등기의무자에 대한 관계에서 그 요청에 응해야 할 위임계약상의 의무가 없다.","w":"판례는 쌍방 위임을 받은 법무사가 한쪽의 중지 요청에 응할 계약상 의무가 없다고 본다. 등기권리자에 대한 위임도 이행해야 하기 때문이다.","c":"중","v":1},"법무사2024_30-03-5":{"f":"교도소에 수감중인 등기의무자를 대리하여 소유권이전등기를 신청하는 경우에도 위임장에 등기의무자의 인감을 날인하고 인감증명을 첨부하여야 하며, 교도소장의 확인을 받은 위임장으로 이를 갈음할 수 없다.","w":"수감자도 인감증명서를 발급받을 수 있으므로 인감 날인과 인감증명 제출이 필요하고, 교정시설 쪽의 확인으로 인감증명을 갈음하지 못한다(등기예규 제423호 「재감자의 무인한 위임장의 가부」).","c":"중","v":1},"법무사2022_28-15-1":{"f":"채권자는 채무자가 상속을 포기한 경우에는 채무자를 대위하여 상속을 원인으로 하는 소유권이전등기를 신청할 수 없다.","w":"상속을 포기한 사람은 처음부터 상속인이 아니었던 것으로 되므로 그를 대위해 상속등기를 신청할 수 없다.","c":"상","v":1},"법무사2020_26-25-3":{"f":"“원고는 피고에게 명의신탁해지를 원인으로 한 소유권이전등기절차를 이행하라”는 화해권고결정을 받은 원고는 피고에 대하여 별도의 채권이 있다면 승소한 권리자인 피고를 대위하여 위 결정에 따른 소유권이전등기를 신청할 수 있다.","w":"승소한 권리자(피고)가 등기를 하지 않을 때 그에게 채권을 가진 자는 채권자대위권으로 이전등기를 신청할 수 있다. 의무자인 원고도 피고에 대한 채권이 있으면 같다.","c":"중","v":1},"법무사2024_30-13-3":{"f":"1동의 건물에 속하는 구분건물 중 일부만에 관하여 소유권보존등기를 신청하는 경우에는 구분건물의 소유자는 다른 구분건물의 소유자를 대위하여 1동의 건물에 속하는 구분건물 전부에 대하여 건물의 표시에 관한 등기를 신청할 수 있다.","w":"일부 구분건물만 보존등기를 할 때 대위로 신청할 수 있는 것은 나머지 구분건물의 표시에 관한 등기이다. 다른 소유자의 소유권보존등기까지 대위하는 것은 아니다.","c":"중","v":1},"법무사2022_28-18-2":{"f":"등기권리자와 등기의무자가 공동으로 등기신청을 한 경우 등기신청의 취하는 등기권리자와 등기의무자 쌍방이 하여야 한다.","w":"공동신청한 등기는 취하도 공동으로 해야 하고, 일방만으로는 취하할 수 없다.","c":"중","v":1},"법무사2024_30-14-2":{"f":"甲이 소유하는 X 토지와 乙이 소유하는 Y 토지를 丙에게 매도하고 소유권이전등기를 신청하는 경우 X 토지와 Y 토지가 같은 등기소의 관할 내에 있더라도 등기원인이 동일하다고 볼 수 없으므로 1개의 신청서로 일괄신청할 수 없다.","w":"여러 부동산을 한 신청정보로 일괄신청하려면 등기목적과 등기원인이 같아야 한다(부동산등기법 제25조 단서). 소유자가 서로 다른 부동산을 한 사람에게 각각 매도하면 매매 당사자가 달라 등기원인이 같다고 보지 않는다.","c":"중","v":1},"법무사2025_31-06-2":{"f":"같은 부동산에 대하여 둘 이상의 권리에 관한 등기를 동시에 신청하는 경우, 먼저 접수된 신청에 의하여 새로 등기명의인이 되는 자가 나중에 접수된 신청에서 등기의무자가 되는 경우에 나중에 접수된 등기신청에는 등기필정보를 제공하지 않아도 되고, 이는 둘 이상의 권리에 관한 등기신청의 대리인이 서로 다른 경우에도 같다.","w":"동시신청에서 먼저 접수된 신청으로 새 등기명의인이 된 사람이 나중 신청의 등기의무자이면, 대리인이 서로 다르더라도 나중 신청에는 등기필정보를 제공하지 않아도 된다(「등기의무자의 등기필정보 제공에 관한 업무처리지침」, 등기예규 제1647호).","c":"상","v":1},"법무사2022_28-08-2":{"f":"같은 등기소에 동시에 여러 건의 등기신청을 하는 경우에 첨부정보의 내용이 같은 것이 있을 때에는 먼저 접수되는 신청에만 그 첨부정보를 제공하고, 다른 신청에는 먼저 접수된 신청에 그 첨부정보를 제공하였다는 뜻을 신청정보의 내용으로 등기소에 제공하는 것으로 그 첨부정보의 제공을 갈음할 수 있다.","w":"첨부정보를 한 번만 제공하는 이 방법은 같은 등기소에 동시에 하는 신청이면 되고, 여러 신청의 목적 부동산이 같아야 한다는 요건은 없다.","c":"상","v":1},"법무사2022_28-22-4":{"f":"근저당권이전청구권가등기의 말소등기를 등기의무자와 등기권리자가 공동으로 신청하는 경우에는 등기의무자의 인감증명을 첨부정보로 제공할 필요가 없다.","w":"인감증명 제출 대상은 소유권의 등기명의인이 등기의무자인 경우이다. 근저당권이전청구권가등기는 소유권에 관한 가등기가 아니어서 인감증명이 필요 없다.","c":"상","v":1},"법무사2022_28-28-4":{"f":"신탁계약을 원인으로 한 소유권이전등기의 신청과 신탁등기의 신청은 1건의 신청정보로 일괄하여 하여야 한다.","w":"신탁등기는 그 신탁으로 인한 권리의 이전·보존·설정등기 신청과 함께 1건의 신청정보로 일괄하여 신청해야 한다(부동산등기규칙 제139조 제1항). 일괄신청은 선택이 아니라 의무이다.","c":"상","v":1},"법무사2018_24-23-4":{"f":"공정증서인 협의분할계약서에 의하여 상속등기를 신청하는 경우에는 상속인 전원의 인감증명을 제출할 필요가 없다.","w":"상속재산 협의분할서에 상속인 전원의 인감증명이 필요한 것은 사서증서일 때이다. 공정증서이면 제출하지 않는다.","c":"상","v":1},"법무사2020_26-10-2":{"f":"부동산의 매수인이 다수인 경우 인감증명서상의 매수자란 중 성명란에 ○○○외 ○명으로 기재하고 매수인 중 1인의 인적사항만을 기재한 부동산매도용 인감증명서는 나머지 매수인들의 인적사항을 별지에 기재한 경우에만 첨부할 수 있다.","w":"매수인이 여럿이면 성명란에 '○○○외 ○명'으로 적고 첫 매수인의 인적사항만 적을 수 있지만, 나머지 매수인의 인적사항을 별지에 적어야 한다. 별지 없이 '○○○외 ○명'만 적힌 인감증명서를 붙인 신청은 수리하지 않는다(등기예규 제1308호).","c":"상","v":1},"법무사2021_27-19-4":{"f":"공유물분할을 원인으로 소유권을 취득한 자가 등기의무자가 되어 분할된 부동산에 대해 등기신청을 할 때에는 위 공유물분할을 원인으로 한 지분이전등기를 마친 후 수령한 등기필정보뿐만 아니라 공유물분할 이전에 공유자로서 지분을 취득할 당시 수령한 등기필정보도 함께 제공하여야 한다.","w":"분할된 부동산은 종전 지분과 분할로 이전받은 지분으로 이루어져 있어서, 두 지분을 취득할 때 받은 등기필정보를 모두 제공한다(「등기의무자의 등기필정보 제공에 관한 업무처리지침」, 등기예규 제1647호).","c":"상","v":1},"법무사2023_29-08-1":{"f":"계약을 원인으로 소유권이전등기를 신청할 경우 등기원인증명정보가 집행력 있는 판결인 경우에도 판결서 정본에 검인을 받아야 한다.","w":"계약을 원인으로 한 소유권이전등기는 계약서 대신 판결서(화해·인낙·조정조서 포함) 정본을 등기원인증서로 낼 때에도 검인을 받아야 한다(부동산등기특별조치법 제3조, 등기예규 제1727호).","c":"상","v":1},"법무사2026_32-18-5":{"f":"미등기 건물의 매수인이 건축주를 상대로 제기한 소유권이전등기청구소송에서 실시한 감정에 따라 작성된 감정서는 건물의 표시를 증명하는 정보로 인정되지 않아 이를 제공하여 건물에 대한 소유권보존등기를 신청할 수 없다.","w":"보존등기에서 건물의 표시를 증명하는 정보로는 건축물대장 등이 필요하다. 소송 중 감정서는 이를 대신하지 못한다.","c":"하","v":1},"법무사2023_29-11-4":{"f":"일반적으로 등기신청의 위임에는 등기신청의 취하, 복대리인의 선임, 처분위임장의 원본환부 등의 권한에 대한 위임이 포함되지 않는다.","w":"등기신청을 위임하더라도 신청의 취하, 복대리인 선임, 원본환부 같은 권한은 따로 수권이 있어야 대리인이 행사할 수 있다.","c":"중","v":1},"법무사2016_22-06-3":{"f":"등기소의 접수담당자가 등기신청서를 제출받을 때 허가받은 법무사 등의 사무원의 본인 여부 확인은 전자출입증에 의한다.","w":"출입사무원의 본인 여부는 전자출입증(사용할 수 없을 때는 일일출입증)으로 확인한다. 주민등록증·운전면허증 같은 신분증으로 확인하는 것은 당사자 본인이나 그 대리인이 출석한 경우이다(「등기신청서의 제출 및 접수 등에 관한 예규」 제4조 제2항).","c":"중","v":1},"법무사2023_29-18-4":{"f":"등기관이 신청서를 접수하였을 때에는 신청인의 청구가 있는 경우에 그 신청서의 접수증을 발급하여야 한다.","w":"등기관은 신청서를 접수하면 신청인의 청구에 따라 접수증을 발급한다(부동산등기규칙 제65조 제3항). 청구가 없으면 발급할 의무가 없다.","c":"상","v":1},"법무사2024_30-19-4":{"f":"출입사무원이 등기신청서를 제출하는 경우에는 등기신청서 전면 우측 상단 여백에 일정한 양식의 표시인을 찍고 제출자란에 그 사무원의 성명을 기재하여야 하나, 여러 건의 등기신청서를 동시에 제출할 때에는 첫 번째 신청서에만 표시인을 찍고 총 신청건수를 기재하는 방법으로 갈음할 수 있다.","w":"여러 건을 동시에 낼 때는 첫 번째 신청서에만 표시인을 찍고 총 신청건수를 적는 것으로 갈음할 수 있다(「등기신청서의 제출 및 접수 등에 관한 예규」 제3조 제2항).","c":"상","v":1},"법무사2020_26-01-3":{"f":"미성년자의 공동친권자 중 한 사람만이 미성년자인 자와 이해가 상반되는 경우 이해가 상반되는 그 친권자는 미성년자인 자를 대리할 수 없으므로, 이 경우 이해가 상반되지 않는 다른 일방의 친권자와 특별대리인이 공동으로 그 미성년자를 대리한다.","w":"공동친권자 중 한쪽만 이해상반이면 그 친권자는 대리할 수 없고 특별대리인을 선임한다. 이해가 상반되지 않는 다른 친권자는 단독으로 대리하지 못하고 특별대리인과 공동으로 대리한다.","c":"상","v":1},"법무사2016_22-07-5":{"f":"교도소에 재감중인 자가 위임장에 인감인의 날인에 갈음하여 무인을 찍고 교도관이 확인하는 방법으로 작성된 대리권한증서는 적법한 대리권한을 증명하는 정보로 인정되지 않는다.","w":"재감자도 인감증명서를 발급받을 수 있으므로 인감 제출이 필요한 등기신청에서는 인감증명서를 내야 하고, 무인한 위임장을 교도관이 확인하는 것으로 이를 대신할 수 없다(등기예규 제423호 「재감자의 무인한 위임장의 가부」).","c":"상","v":1},"법무사2021_27-18-5":{"f":"영유아보육시설(어린이집 등)은 교육기관이 아니므로, 영유아보육법에 의하여 민간 보육시설로 인가 받아 그 소유건물 전부를 보육시설로 운영 중인 자는 사립학교법 제2조 제3항 소정의 사립학교 경영자에 해당되지 아니하여 그 소유건물에 대하여는 매매 또는 담보제공 등 처분행위를 할 수 있다.","w":"영유아보육시설은 사립학교법상 학교가 아니고 그 운영자도 사립학교 경영자가 아니다. 소유 건물을 처분하는 데 사립학교법의 제한을 받지 않는다.","c":"상","v":1},"법무사2026_32-11-2":{"f":"소유권이전등기를 신청할 때에 등기원인을 증명하는 정보가 집행력 있는 판결로서 행정관청의 허가서 등의 현존사실이 그 판결서에 기재되어 있더라도 행정관청의 허가 등을 증명하는 정보를 제공하여야 한다.","w":"판결서에 허가서 현존사실이 적혀 있으면 허가서 제출이 면제되는 것이 원칙이지만, 소유권이전등기는 예외여서 허가를 증명하는 서면을 반드시 낸다(「판결 등 집행권원에 의한 등기의 신청에 관한 업무처리지침」, 부동산등기특별조치법 제5조 제1항).","c":"상","v":1},"법무사2016_22-08-3":{"f":"등기신청서 또는 위임장에 표시된 등기의무자의 작성부분에 대한 공증을 받는 경우에는 등기의무자 본인이 공증사무소에 출석하여 공증을 받아야 한다.","w":"등기필정보가 없어 신청서나 위임장의 등기의무자 작성부분을 공증받을 때에는 등기의무자 본인이 출석해야 한다. 위임받은 대리인이 출석해 공증받은 서면으로 한 신청은 수리하지 않는다(등기예규 제1851호).","c":"상","v":1},"법무사2025_31-23-5":{"f":"민법 제909조 제4항부터 제6항까지의 규정에 따라 단독친권자로 정하여진 부모의 일방이 사망한 경우 생존하는 부 또는 모의 친권은 당연히 부활하지 않으므로 별도의 친권자 지정 절차를 거쳐야 미성년자인 자를 대리하여 등기신청을 할 수 있다.","w":"단독친권자로 정해진 부모 한쪽이 사망해도 생존한 부모의 친권은 당연히 되살아나지 않는다. 가정법원에서 친권자로 지정받아야 미성년자를 대리해 등기신청을 할 수 있다(민법 제909조의2).","c":"상","v":1},"법무사2018_24-01-5":{"f":"친권자가 미성년자인 자 소유의 부동산을 채무자인 그 미성년자를 위하여 담보로 제공하거나 제3자에게 처분하는 경우에는 그 미성년자인 자에 관한 특별대리인의 선임이 필요하지 않다.","w":"미성년자 자신의 채무를 위한 담보제공은 친권자와 미성년자 사이의 이해상반 행위가 아니어서 특별대리인을 선임하지 않는다.","c":"상","v":1},"법무사2024_30-01-2":{"f":"등기신청서의 성명은 본인서명사실확인서의 서명이 한글, 한자, 영문 어느 것으로 기재되어 있든 한글로 기재하여야 한다.","w":"본인서명사실확인서의 서명이 한자나 영문으로 되어 있어도 등기신청서의 성명은 반드시 한글로 적는다(등기예규 제1780호).","c":"상","v":1},"법무사2019_25-26-2":{"f":"본인서명사실확인서의 서명이 한글이 아닌 문자로 기재되어 있더라도 등기신청서의 성명은 한글로 기재하여야 한다.","w":"서명이 한자나 영문이어도 등기신청서에는 성명을 반드시 한글로 쓴다(등기예규 제1780호).","c":"상","v":1},"법무사2026_32-12-4":{"f":"건물이 멸실된 경우에 그 건물의 소유권의 등기명의인이 그 사실이 있는 때부터 1개월 이내에 멸실등기를 신청하지 아니하면 그 건물대지의 소유자가 건물 소유권의 등기명의인을 대위하여 멸실등기를 신청할 수 있고, 건물이 부존재하는 경우에도 대위로 멸실등기를 신청할 수 있다.","w":"건물이 존재하지 않는 경우에도 등기명의인이 1개월 안에 멸실등기를 신청하지 않으면 건물대지 소유자가 대위해 멸실등기를 신청할 수 있다(부동산등기법 제44조 제2항, 제43조 제2항).","c":"상","v":1},"법무사2018_24-25-1":{"f":"종중이 농지에 대하여 명의신탁 해지를 원인으로 한 소유권이전등기청구소송에서 승소판결을 받았더라도 위토대장에 종중 명의로 등재된 기존 위토가 아니면 종중 명의로 소유권이전등기를 신청할 수 없다.","w":"종중은 원칙적으로 농지를 취득할 수 없어 승소판결을 받아도 종중 명의로 이전등기를 할 수 없다. 농지개혁 당시 위토대장에 종중 명의로 등재된 기존 위토만 그 증명서를 첨부해 신청할 수 있다(「농지의 소유권이전등기에 관한 사무처리지침」, 등기예규 제1635호).","c":"상","v":1},"법무사2018_24-25-2":{"f":"종중이 기존 위토를 처분하고 새로 위토용으로 농지를 매수하거나, 기존 위토인 농지가 수용 또는 공공용지로 협의취득되어 그 보상금으로 새로 다른 농지를 위토용으로 매수할 경우에는 소유권이전등기를 신청할 수 없다.","w":"종중은 원칙적으로 농지를 취득할 수 없어 위토로 쓰려고 새로 농지를 사는 것도 허용되지 않는다. 농지개혁 당시 위토대장에 등재된 기존 위토만 종중 명의로 이전등기를 할 수 있다(등기예규 제1635호).","c":"상","v":1},"법무사2018_24-25-3":{"f":"법인 아닌 사단도 농지에 대한 소유권이전청구권보전을 위한 가등기를 할 수 있다.","w":"가등기는 농지를 취득하는 등기가 아니고 농지취득자격증명도 요구되지 않으므로 법인 아닌 사단도 가등기를 신청할 수 있다.","c":"중","v":1},"법무사2018_24-25-4":{"f":"농지에 관하여 증여계약을 해제하는 약정을 원인으로 하여 소유권이전등기의 말소등기 신청을 하는 경우에는 농지취득자격증명을 첨부할 필요가 없다.","w":"합의해제로 말소등기를 하는 것은 농지를 취득하는 것이 아니므로 농지취득자격증명이 필요 없다.","c":"상","v":1},"법무사2019_25-01-1":{"f":"등기의무자가 법인인 경우에는 그 지배인을 확인하거나 지배인의 작성부분에 관한 공증으로 대표권을 가진 임원 또는 사원의 본인확인 또는 그 작성부분에 관한 공증에 갈음할 수 있다.","w":"등기의무자가 법인이면 지배인을 확인하거나 지배인 작성부분을 공증받는 것으로 대표권 있는 임원·사원의 확인이나 공증을 대신할 수 있다(등기예규 제1355호).","c":"상","v":1},"법무사2019_25-01-2":{"f":"자격자대리인(변호사, 법무사)이 확인서면을 작성하는데 있어서 확인서면에는 등기의무자의 우무인을 날인하여야 하며, 신체적 특징을 기재할 필요는 없다.","w":"확인서면에는 등기의무자의 우무인을 찍게 한다. 신체적 특징을 기재하게 하는 규정은 없다.","c":"중","v":1},"법무사2019_25-01-3":{"f":"소유권 외의 권리의 등기명의인이 등기의무자로서 등기필정보가 없어 등기소에 출석하여 등기관으로부터 등기의무자임을 확인받는 때에는, 등기관이 확인조서를 작성하더라도 등기의무자의 인감증명을 제출하여야 한다.","w":"등기관의 확인을 받는 경우에도 등기의무자의 인감증명을 제출해야 한다. 확인조서를 작성한다고 해서 인감증명이 면제되지 않는다.","c":"중","v":1},"법무사2019_25-01-4":{"f":"등기의무자의 등기필정보가 없어 등기신청서 또는 위임장 중 등기의무자의 작성부분에 대한 공증을 받는 경우에는 등기의무자 본인이 출석하여 공증을 받아야 한다.","w":"공증은 등기의무자 본인이 출석해 받아야 한다. 위임받은 대리인이 출석해 공증받은 경우 등기관은 그 신청을 수리하지 않는다(등기예규 제1851호).","c":"상","v":1},"법무사2018_24-07-5":{"f":"공유자 중 1인이 행방불명되어 주소를 증명하는 서면을 발급받을 수 없는 경우 그 자의 주소가 토지대장에 기재되어 있는 때에는 주소를 증명하는 서면을 제출할 수 없는 사유를 소명하여 그 대장상의 주소를 행방불명된 자의 주소지로 하여 소유권보존등기를 신청할 수 있다.","w":"주소증명서면을 낼 수 없는 사유를 소명하면 대장상 주소로 보존등기를 신청할 수 있다.","c":"상","v":1},"법무사2016_22-20-1":{"f":"지방자치단체에 대한 부동산등기용등록번호는 국토교통부장관이 지정ㆍ고시한다.","w":"국가·지방자치단체·국제기관·외국정부의 부동산등기용등록번호는 국토교통부장관이 지정·고시한다(부동산등기법 제49조 제1항 제1호).","c":"상","v":1},"법무사2016_22-20-2":{"f":"외국정부에 대한 부동산등기용등록번호는 국토교통부장관이 지정ㆍ고시한다.","w":"외국정부의 등록번호도 국가·지방자치단체·국제기관과 같이 국토교통부장관이 지정·고시한다. 외교부장관의 소관이 아니다.","c":"상","v":1},"법무사2016_22-20-4":{"f":"법인 아닌 사단이나 재단의 부동산등기용등록번호는 주된 사무소의 소재지 관할 시장ㆍ군수 또는 구청장이 부여한다.","w":"법인 아닌 사단·재단의 등록번호는 주된 사무소 소재지를 관할하는 시장·군수·구청장이 부여한다(부동산등기법 제49조 제1항 제3호). 등기관이 부여하는 것은 법인의 등록번호다.","c":"상","v":1},"법무사2016_22-20-5":{"f":"주민등록번호가 없는 재외국민에 대한 부동산등기용등록번호는 대법원 소재지 관할 등기소의 등기관이 부여한다.","w":"주민등록번호가 없는 재외국민의 등록번호는 대법원 소재지를 관할하는 등기소의 등기관이 부여한다(부동산등기법 제49조 제1항 제2호).","c":"상","v":1},"법무사2016_22-09-1":{"f":"등기관이 등기신청에 대하여 보정을 명하는 경우에는 보정할 사항을 구체적으로 적시하고 그 근거법령이나 예규, 보정기간 등을 제시하여 매건 조사 완료 후 즉시 구두 또는 전화나 모사전송의 방법에 의하여 등기신청인에게 통지하여야 한다.","w":"보정 통지는 조사를 마친 즉시 구두, 전화, 모사전송으로 한다(「부동산등기신청사건 처리지침」). 서면 통지로 정해져 있지 않다.","c":"상","v":1},"법무사2016_22-09-2":{"f":"보정을 위하여 필요하더라도 신청서 또는 그 부속서류를 신청인에게 반환할 수 없다.","w":"보정은 등기관 앞에서 해야 하고, 보정을 위해 신청서나 부속서류를 신청인에게 돌려줄 수 없다(등기예규 제1839호 부동산등기신청사건 처리지침).","c":"상","v":1},"법무사2016_22-09-4":{"f":"등기신청의 취하는 방문신청의 경우 신청인 또는 그 대리인이 등기신청을 한 등기소에 출석하여 취하서를 제출하는 방법으로 하여야 하고, 구두로는 할 수 없다.","w":"취하는 방문신청이면 등기소에 출석해 취하서를 내고, 전자신청이면 전산정보처리조직으로 취하정보를 보낸다(부동산등기규칙 제51조 제2항). 신청인이 누구든 구두 취하는 인정되지 않는다.","c":"상","v":1},"법무사2016_22-09-5":{"f":"수 개의 부동산에 관한 등기신청을 일괄하여 동일한 신청서에 의하여 한 경우에는 그 중 일부 부동산에 대하여만 등기신청을 취하할 수 있다.","w":"일괄신청한 경우에도 부동산별로 취하할 수 있다. 일부 부동산만 취하하는 것이 허용된다.","c":"상","v":1},"법무사2020_26-17-1":{"f":"등기관이 등기신청에 대하여 보정을 명하는 경우에는 보정할 사항을 구체적으로 적시하고 그 근거법령이나 예규, 보정기간 등을 제시하여 매건 조사 완료 후 즉시 구두 또는 전화나 모사전송의 방법에 의하여 등기신청인에게 통지하여야 한다.","w":"보정 통지는 조사를 마친 즉시 구두, 전화, 모사전송으로 한다(「부동산등기신청사건 처리지침」). 서면 통지로 정해져 있지 않다.","c":"상","v":1},"법무사2020_26-17-3":{"f":"보정을 위하여 필요하더라도 신청서 또는 그 부속서류를 신청인에게 반환할 수 없다.","w":"보정은 등기관 앞에서 해야 하고, 보정을 위해 신청서나 부속서류를 신청인에게 돌려줄 수 없다(등기예규 제1839호).","c":"상","v":1},"법무사2020_26-17-4":{"f":"등기관은 그 직무권한에 있어 독립성을 가지지만, 등기소장은 보정명령의 적정 여부에 관하여 감독을 할 수 있다.","w":"등기관이 독립해 직무를 처리해도 등기소장의 감독은 배제되지 않는다. 예규는 등기소장이 보정명령의 적정 여부를 철저히 감독하도록 정한다(등기예규 제1839호).","c":"상","v":1},"법무사2020_26-17-5":{"f":"등기신청서를 제출할 수 있도록 허가받은 변호사나 법무사의 사무원은 등기신청의 보정을 할 수 있다.","w":"신청서 제출을 허가받은 사무원은 제출뿐 아니라 보정도 할 수 있다.","c":"중","v":1},"법무사2018_24-05-3":{"f":"","w":"(예규 개정 전 기준 X. 현행 등기예규 제1778호는 본국에 인감증명제도가 없는 외국인이 본국 관공서의 증명이나 본국 또는 대한민국 공증인의 인증으로 인감증명을 갈음하게 하고, 대한민국 재외공관의 인증도 여기에 포함한다.) 출제 당시에는 주한 본국 대사관·영사관의 확인서면만 인정되고 대한민국 재외공관의 확인서면은 인정되지 않았다.","c":"중","v":1},"법무사2022_28-09-4":{"f":"법무사법인이 당사자로부터 등기신청을 위임받아 甲법무사가 그 업무에 관하여 지정을 받은 경우 A등기신청서에 담당 법무사로 기재되지 않은 乙법무사는 위 법무사법인 소속 법무사임을 소명하더라도 A등기신청서를 제출할 수 없다.","w":"법무사법인이 위임받은 사건은 지정받은 담당 법무사가 신청서를 제출한다. 같은 법인 소속이라도 신청서에 담당자로 적히지 않은 법무사는 제출하지 못한다.","c":"중","v":1},"법무사2022_28-23-1":{"f":"전자신청의 경우에도 자격자대리인의 자필서명정보를 제공하여야 한다.","w":"자격자대리인이 공동신청 등을 대리할 때 내는 자필서명 정보는 전자신청에서도 제공해야 한다. 전자신청이면 서면을 스캔한 파일에 자격자대리인의 전자서명정보를 붙여 보낸다(부동산등기규칙 제46조 제1항 제8호, 등기예규 제1802호).","c":"상","v":1},"법무사2025_31-15-1":{"f":"승소한 등기권리자가 권리에 관한 등기를 단독으로 신청하는 경우에는 자격자대리인의 자필서명 정보를 제공할 필요가 없다.","w":"자필서명 정보는 공동신청하는 권리에 관한 등기와 승소한 등기의무자가 단독신청하는 등기에서만 낸다(부동산등기규칙 제46조 제1항 제8호). 승소한 등기권리자의 단독신청에는 필요 없다.","c":"상","v":1},"법무사2021_27-04-3":{"f":"재외국민으로부터 소유권의 처분권한을 수여받은 대리인이 본인을 대리하여 매매를 원인으로 하는 소유권이전등기를 신청하는 경우로서 등기신청서에 대리인의 인감을 날인한 경우에 대리인의 인감증명은 매도용으로 발급받을 필요가 없다.","w":"처분권한을 받은 대리인이 매매로 인한 소유권이전등기를 신청할 때 대리인의 인감을 날인하고 인감증명을 내지만, 그 인감증명은 매도용으로 발급받을 필요가 없다(등기예규 제1778호).","c":"상","v":1},"법무사2026_32-28-1":{"f":"미국인 甲이 주한 미국대사관에서 공증받은 문서를 첨부정보로 제출한 경우 그 문서에 아포스티유 확인을 받지 않았더라도 등기관은 보정을 명할 필요가 없다.","w":"외국의 외교·영사기관이 작성하거나 공증한 문서(주한 미국대사관에서 공증받은 문서 등)는 아포스티유 확인이 필요 없다(등기예규 제1778호). 등기관이 보정을 명할 일이 아니다.","c":"하","v":1},"법무사2026_32-28-2":{"f":"미국인 甲이 미국의 권한 있는 기관에서 발행한 신분증 원본을 첨부정보로 제출한 경우 그 신분증에 아포스티유 확인을 받지 않았더라도 등기관은 보정을 명할 필요가 없다.","w":"외국 공문서에 아포스티유나 영사 확인이 없으면 보정을 명하는 것이 원칙이지만, 신분증 원본은 그 예외로 정해져 있다(「재외국민 및 외국인의 부동산등기신청절차에 관한 예규」 제3조).","c":"상","v":1},"법무사2026_32-28-3":{"f":"A 건물의 소유명의인인 미국인 甲이 해당 건물의 처분 권한을 대리인 乙에게 수여하였고 乙이 자격자대리인 丙에게 매매로 인한 소유권이전등기신청을 위임한 경우, 등기신청 위임장에 乙의 인감을 날인하고 인감증명을 발급받아 제출하여야 하나 매도용일 필요는 없다.","w":"처분권한을 받은 대리인 乙은 위임장에 자기 인감을 날인하고 인감증명을 내야 하지만, 매매로 인한 이전등기라도 그 인감증명은 매도용일 필요가 없다(등기예규 제1778호).","c":"상","v":1},"법무사2026_32-28-4":{"f":"외국인이 본국을 떠나 대한민국이 아닌 제3국에 체류하는 경우에 체류국에 주소증명제도가 있다면 체류국 관공서에서 발행한 주소증명정보를 제공할 수 있다. 체류국에 주소증명제도가 없다면 체류국의 공증인이 주소를 공증한 서면을 제공할 수 있다.","w":"제3국에 체류하는 외국인은 체류국에 주소증명제도가 없으면 체류국 공증인이 주소를 공증한 서면을 낼 수 있다. 이때 그 나라의 체류자격을 증명하는 정보를 함께 낸다(등기예규 제1778호).","c":"상","v":1},"법무사2024_30-16-4":{"f":"등록번호 부여신청서에는 재외국민등록법 제7조의 재외국민등록부등본 및 가족관계의 등록 등에 관한 법률 제15조 제1항 제2호의 기본증명서를 첨부하여야 한다.","w":"재외국민의 부동산등기용등록번호 부여신청서에는 재외국민등록부등본과 기본증명서를 첨부한다(등기예규 제1389호). 가족관계증명서가 아니다.","c":"중","v":1},"법무사2021_27-01-5":{"f":"공유물분할판결의 경우와 달리, 현물분할을 내용으로 하는 공유물분할에 관하여 조정이나 화해권고결정이 확정된 후 그 조정이나 화해권고결정에 따른 등기신청 전에 일부 공유자의 지분이 제3자에게 이전된 경우에 다른 공유자는 제3자에 대한 승계집행문을 부여받아 제3자 명의의 지분에 대하여 자신 앞으로의 이전등기를 단독으로 신청할 수 없다.","w":"공유물분할 판결은 형성력이 있어 확정되면 분할이 이루어지지만, 조정이나 화해권고결정은 당사자 사이의 이행의무만 생긴다. 제3자에 대한 승계집행문을 받아 제3자 지분을 이전받을 수 없다.","c":"중","v":1},"법무사2025_31-17-1":{"f":"등기관이 등기를 완료한 때에는 대위신청인과 피대위자에게 등기완료통지를 하고, 등기필정보는 작성·통지하지 아니한다.","w":"채권자대위로 한 등기는 등기권리자가 신청인이 아니어서 등기필정보를 작성하지 않는다. 대위신청인과 피대위자에게 등기완료통지만 한다(부동산등기규칙 제53조 제1항 제2호, 「등기필정보의 작성 및 통지 등에 관한 업무처리지침」).","c":"상","v":1},"법무사2025_31-10-2":{"f":"채무자인 종중 소유의 미등기 건물에 대한 집행법원의 가압류등기촉탁시 정관이나 규약, 대표자나 관리인임을 증명하는 정보, 사원총회의 결의서 등을 첨부할 필요가 없다.","w":"법원이 채무자 소유 미등기 건물에 가압류를 촉탁할 때 채무자는 종중이어도 처분하는 당사자가 아니어서 종중의 정관, 대표자 증명, 총회결의서를 낼 필요가 없다.","c":"중","v":1},"법무사2016_22-11-2":{"f":"공증인 작성의 공정증서는 설령 부동산에 관한 등기신청의무를 이행하기로 하는 조항이 기재되어 있더라도 등기권리자는 이 공정증서에 의하여 단독으로 등기를 신청할 수 없다.","w":"공정증서는 등기절차 이행을 명하는 판결과 달리 의사표시를 갈음하는 효력이 없다. 등기권리자는 공정증서만으로 단독신청하지 못한다.","c":"상","v":1},"법무사2020_26-16-3":{"f":"등기원인에 대하여 행정관청의 허가 등이 필요한 경우 해당 허가서 등의 현존사실이 그 판결서에 기재되어 있는 경우에 한하여 허가서 등의 제출의무가 면제된다. 그러나 소유권이전등기신청의 경우에는 해당 허가서 등의 현존사실이 판결서 등에 기재되어 있더라도 행정관청의 허가 등을 증명하는 서면을 제출하여야 한다.","w":"허가서 현존사실이 판결서에 기재되어 있어도 소유권이전등기를 신청할 때에는 행정관청의 허가 등을 증명하는 서면을 반드시 제출한다(「판결 등 집행권원에 의한 등기의 신청에 관한 업무처리지침」, 부동산등기특별조치법 제5조 제1항).","c":"상","v":1},"법무사2025_31-05-5":{"f":"현물분할을 내용으로 하는 공유물분할에 관하여 화해권고결정이 확정된 후 그 결정에 따른 등기신청 전에 일부 공유자의 지분이 제3자에게 이전된 경우, 다른 공유자는 제3자에 대한 승계집행문을 부여받아 제3자 명의의 지분에 대하여 자신 앞으로의 이전등기를 단독으로 신청할 수 없다.","w":"화해권고결정에는 판결과 같은 형성력이 없어 이행의무만 생긴다. 변론종결 후 승계인에 해당하는 제3자를 상대로 승계집행문을 받아 단독으로 지분이전등기를 신청하지 못한다.","c":"중","v":1},"법무사2022_28-17-1":{"f":"피고의 주소를 허위로 기재하여 소송서류 및 판결정본을 그 곳으로 송달하게 한 사위판결에 의하여 소유권이전등기가 경료된 후 상소심절차에서 그 사위판결이 취소·기각된 경우 그 취소·기각판결에 의하여 소유권이전등기의 말소등기를 신청할 수 없다.","w":"상소심의 취소·기각판결은 종전 판결을 없애는 것일 뿐 등기를 말소하라는 이행을 명한 것이 아니다. 말소등기를 신청하려면 말소를 명한 판결이 따로 있어야 한다.","c":"중","v":1},"법무사2019_25-16-4":{"f":"“피고는 원고로부터 △△부동산에 관한 소유권이전등기 절차를 이행받음과 동시에 원고에게 ○○○원을 지급하라”는 취지의 판결이 확정된 경우, 피고는 위 판결문에 집행문을 부여받더라도 단독으로 △△부동산에 관한 소유권이전등기를 신청할 수 없다.","w":"이 판결은 피고에게 대금 지급을 명한 것이고 원고에게 등기절차의 이행을 명한 것이 아니다. 피고는 판결만으로 단독신청하지 못하고 원고와 공동으로 신청해야 한다.","c":"중","v":1},"법무사2023_29-19-3":{"f":"판결문상에 기재된 피고의 주민등록번호와 등기부상 기재된 등기의무자의 주민등록번호는 동일하나 주소가 서로 다른 경우에는 피고의 주소에 관한 서면을 제출할 필요가 없다.","w":"주민등록번호가 같으면 동일인임이 확인되므로 주소가 달라도 별도 주소증명을 요구하지 않는다.","c":"중","v":1},"법무사2022_28-05-2":{"f":"토지 매매계약 후 매도인 명의의 토지거래계약허가신청서를 제출하였으나 매도인이 사망한 후에 토지거래계약허가증을 교부받은 경우, 상속인은 상속인을 거래당사자로 한 토지거래계약허가증을 새로 발급받을 필요 없이 피상속인으로부터 매수인 앞으로 소유권이전등기를 신청할 수 있다.","w":"매도인이 사망해도 매매계약상 지위는 상속인에게 포괄승계된다. 피상속인 명의로 받은 허가증으로 족하고 상속인 명의 허가증을 다시 받을 필요가 없다.","c":"중","v":1},"법무사2017_23-12-5":{"f":"합유자 중 일부가 교체되는 경우 합유지분을 처분한 합유자와 합유지분을 취득한 합유자, 그리고 나머지 합유자 전원의 공동신청으로 합유명의인변경등기를 신청하여야 한다.","w":"합유자 중 일부가 교체되면 지분을 처분한 합유자, 지분을 취득한 합유자, 남은 합유자가 공동으로 합유명의인 변경등기를 신청하고, 처분한 합유자의 인감증명을 붙인다(「합유등기의 사무처리에 관한 예규」 2. 가.).","c":"상","v":1},"법무사2019_25-05-1":{"f":"토지수용으로 인한 소유권이전등기를 신청할 때에 등기원인은 “수용”으로, 원인일자는 “수용의 개시일”로 한다.","w":"수용으로 인한 소유권이전등기의 등기원인은 '수용', 원인일자는 재결일이 아니라 '수용의 개시일'로 적는다(등기예규 제1782호). 수용자는 수용의 개시일에 소유권을 취득한다.","c":"상","v":1},"법무사2019_25-05-4":{"f":"수용으로 인한 소유권이전등기를 할 때에 수용의 개시일 이후에 마쳐진 소유권이전등기라도 수용의 개시일 이전에 발생한 상속을 원인으로 한 것이면 등기관이 직권으로 말소하지 아니한다.","w":"수용의 개시일 이후에 마친 소유권이전등기는 직권으로 말소하지만, 수용의 개시일 전의 상속을 원인으로 한 소유권이전등기는 말소하지 않는다(등기예규 제1782호).","c":"상","v":1},"법무사2019_25-11-1":{"f":"합유자 중 일부가 나머지 합유자들 전원의 동의를 얻어 그의 합유지분을 처분하여 종전의 합유자 중 일부가 교체되는 경우에는 합유지분을 처분한 합유자와 합유지분을 취득한 합유자, 그리고 나머지 합유자 전원의 공동신청으로 합유명의인 변경등기신청을 하여야 한다.","w":"합유자 중 일부가 교체되면 지분을 처분한 합유자, 지분을 취득한 합유자, 남은 합유자가 공동으로 합유명의인 변경등기를 신청하고, 처분한 합유자의 인감증명을 붙인다(「합유등기의 사무처리에 관한 예규」 2. 가.).","c":"상","v":1},"법무사2019_25-27-1":{"f":"한 필지 전부를 매매의 목적물로 하여 매매계약을 체결함과 동시에 그 목적물의 일부 지분에 대한 환매권을 보류하는 약정의 환매특약등기신청은 할 수 없다.","w":"환매권은 매매 목적물 전부 또는 공유지분 전부에 대해 보류해야 한다. 소유권의 일부 지분에 대해서만 환매권을 보류하는 약정은 민법상 환매특약이 아니어서 등기할 수 없다.","c":"상","v":1},"법무사2020_26-14-3":{"f":"환매권의 행사로 인한 소유권이전등기를 신청할 때 환매특약 등기의 말소는 신청하지 않으며 등기관이 환매권 행사로 인한 소유권이전등기를 하면서 직권으로 말소한다.","w":"환매권 행사로 소유권이전등기를 하면 등기관이 환매특약등기를 직권으로 말소한다(부동산등기규칙 제114조 제1항). 당사자가 따로 말소를 신청하지 않는다.","c":"상","v":1},"법무사2024_30-12-4":{"f":"부동산의 소유권을 포기한 경우 그 소유권을 포기한 자와 국가가 공동으로 소유권이전등기를 신청하여야 하며, 등기상 이해관계 있는 제3자가 있는 때에도 그 자의 승낙이 있음을 증명하는 정보를 제공할 필요는 없다.","w":"소유권 포기는 국가에 귀속되는 소유권이전등기로 하며 포기한 자만이 단독으로 신청하지 못한다. 제3자의 권리는 그대로 존속하므로 승낙은 필요 없다.","c":"중","v":1},"법무사2025_31-13-3":{"f":"환매기간의 연장을 목적으로 하는 환매권 변경등기신청은 당사자 간의 약정이 있더라도 할 수 없다.","w":"환매기간을 정한 때에는 다시 연장하지 못한다(민법 제591조 제2항). 당사자가 합의해도 환매기간 연장을 위한 변경등기는 신청할 수 없다.","c":"상","v":1},"법무사2025_31-16-1":{"f":"등기원인이 매매인 경우에도 등기원인증서가 판결, 조정조서 등 매매계약서가 아닌 때에는 거래가액을 등기하지 않는다.","w":"등기원인이 매매라도 등기원인증서가 판결이나 조정조서처럼 매매계약서가 아니면 거래가액을 등기하지 않는다(등기예규 제1804호).","c":"상","v":1},"법무사2025_31-16-2":{"f":"최초의 피분양자로부터 그 지위 일부지분만이 甲에게 증여로 이전되어 최초의 피분양자와 甲이 공동으로 등기권리자가 된 경우에는 거래가액을 등기하지 않는다.","w":"최초 피분양자의 지위 일부지분만 증여로 甲에게 넘어가 두 사람이 공동 등기권리자가 된 경우에는 거래가액을 등기하지 않는다(등기예규 제1804호).","c":"상","v":1},"법무사2025_31-16-4":{"f":"1개의 계약서에 의해 2개 이상의 부동산을 거래한 경우, 관할 관청이 달라 개개의 부동산에 관하여 각각 거래가액을 신고하였다면 매매목록을 작성하지 않는다.","w":"1개의 계약서로 여러 부동산을 거래했더라도 관할 관청이 달라 부동산마다 따로 신고했으면 매매목록을 작성할 필요가 없다(등기예규 제1804호).","c":"상","v":1},"법무사2025_31-25-2":{"f":"민법 제839조의2 제3항에 따르면 “재산분할청구권은 이혼한 날부터 2년을 경과한 때에는 소멸한다.”고 규정하고 있으나, 협의이혼 당시 재산분할약정을 한 후 15년이 지나 재산분할을 원인으로 소유권이전등기신청을 한 경우에도 등기관은 각하할 수 없다.","w":"2년의 제척기간은 재산분할을 청구하는 권리에 관한 것이다. 이미 약정이 있다면 약정에 따른 이전등기는 이혼 후 오랜 시간이 지나도 신청할 수 있고 등기관은 각하할 수 없다.","c":"상","v":1},"법무사2025_31-27-5":{"f":"부동산의 공유자 중 한 사람은 공유물에 대한 보존행위로서 그 공유물에 관한 원인무효의 등기 전부의 말소를 구할 수 있고, 공유물에 마쳐진 원인무효의 등기에 관하여 각 공유자에게 해당 지분별로 진정명의회복을 원인으로 한 소유권이전등기를 이행할 것을 단독으로 청구할 수도 있다.","w":"판례는 공유자 한 사람이 보존행위로서 원인무효 등기 전부의 말소를 구할 수 있는 것과 같은 이유로, 각 공유자에게 지분별로 진정명의회복을 원인으로 한 소유권이전등기를 하라고 단독으로 청구할 수도 있다고 본다.","c":"중","v":1},"법무사2025_31-16-3":{"f":"등기원인증서에 기재된 사항과 신고필증에 기재된 사항이 서로 다른 경우 신청인이 제출한 자료에 의하여 등기원인증서상 매매와 신고의 대상이 된 매매를 동일한 거래라고 인정할 수 있는 경우에는 등기관은 해당 등기신청을 부동산등기법 제29조 제9호에 의하여 각하하지 아니한다.","w":"기재가 서로 달라도 신청인이 낸 자료로 같은 거래임이 인정되면 각하하지 않는다. 같은 거래라고 인정할 수 없을 때에만 부동산등기법 제29조 제9호로 각하한다(등기예규 제1804호).","c":"상","v":1},"법무사2017_23-11-2":{"f":"등기원인이 매매라도 등기원인증서가 판결서 등인 경우에는 거래가액을 등기하지 않는다.","w":"등기원인이 매매라도 등기원인증서가 판결서 등 매매계약서가 아니면 거래가액을 등기하지 않는다(등기예규 제1804호).","c":"상","v":1},"법무사2016_22-19-1":{"f":"건축물대장에 지분표시가 없이 수인이 공유로 등재되어 있는 건물에 대하여 소유권보존등기를 신청할 수 있다.","w":"대장에 지분표시가 없으면 균등한 지분으로 보아 공유 보존등기를 신청할 수 있다.","c":"중","v":1},"법무사2017_23-02-5":{"f":"기존건물과 별개로 신축된 건물이 기존 건축물대장에 증축으로 함께 등재되어 있는 경우에는 그 신축건물이 기존건물과 물리적으로 별개의 독립한 건물임이 명백하더라도 그 대장을 첨부하여 독립한 건물로 소유권보존등기를 신청할 수 없다.","w":"기존 대장에 증축으로 함께 등재된 신축건물을 독립건물로 보존등기하려면 먼저 기존 대장에서 분리해 따로 건축물대장을 작성하고 그 대장을 첨부해야 한다(등기예규 제902호).","c":"상","v":1},"법무사2023_29-20-2":{"f":"건축물대장이 생성되지 않은 건물에 대하여는 소유권확인판결에 의하여 자기의 소유권을 증명하더라도 소유권보존등기를 신청할 수 없다.","w":"건물 보존등기에는 대장으로 건물의 표시가 증명되어야 한다. 대장이 생성되지 않은 건물은 판결만으로 보존등기를 신청하지 못한다.","c":"중","v":1},"법무사2021_27-27-3":{"f":"권리능력 없는 사단의 소유명의로 된 부동산을 그 구성원들의 합유로 등기하기 위하여는 권리변경등기를 할 수 없고, 권리능력 없는 사단으로부터 그 구성원 전원의 합유로의 소유권이전등기를 신청하여야 한다.","w":"법인 아닌 사단과 구성원은 별개의 주체여서 명의를 합유로 바꾸는 변경등기가 안 된다. 사단에서 구성원 전원으로 소유권이전등기를 해야 한다.","c":"상","v":1},"법무사2020_26-07-3":{"f":"합유등기에 있어서 등기기록상 합유의 표시방법은 각 합유자의 지분을 기록하지 아니한다.","w":"합유는 합유자 각자의 지분이 없으므로 지분을 쓰지 않고 합유라는 뜻만 기록한다.","c":"상","v":1},"법무사2026_32-13-2":{"f":"甲ㆍ乙ㆍ丙 세 사람이 합유로 소유하고 있는 토지를 합유자 전원의 합의로 1/3지분은 甲의 소유로 2/3지분은 乙ㆍ丙의 합유로 하고자 하는 경우, 甲ㆍ乙ㆍ丙 3인의 합유등기를 곧바로 공유자 甲(1/3지분)과 합유자 乙ㆍ丙(2/3지분)으로 하는 소유권변경등기는 수리할 수 없다.","w":"합유에서 공유로의 변경은 합유물을 분할하는 것이어서 합유자 3인의 합유를 곧바로 일부 공유·일부 합유로 하는 변경등기는 허용되지 않는다.","c":"중","v":1},"법무사2018_24-16-3":{"f":"공유물분할을 원인으로 한 소유권이전등기는 각 분필 등기된 부동산 전부에 대하여 동시에 신청할 필요가 없다.","w":"분필된 부동산 중 일부만 먼저 분할 이전등기를 신청해도 되고 전부를 동시에 신청해야 하는 것은 아니다.","c":"중","v":1},"법무사2025_31-02-5":{"f":"甲, 乙, 丙, 丁이 공유하는 토지에 대하여 乙, 丙, 丁이 甲을 상대로 “피고는 원고들에게 위 토지의 특정부분에 대하여 각 지분에 관하여 공유물분할약정을 원인으로 한 이전등기절차를 이행하라”는 확정판결을 받은 경우, 乙, 丙, 丁은 분필등기를 마친 이후 위 판결문을 첨부하여 단독으로 지분이전등기를 신청할 수 있으나, 甲은 위 판결문을 첨부하여 단독으로 위 토지의 나머지 부분에 대한 지분이전등기를 신청할 수 없다.","w":"판결이 이행을 명한 것은 甲이 乙·丙·丁에게 이전하는 부분뿐이다. 甲이 나머지 부분의 지분을 이전받는 것은 판결 내용이 아니므로 그 판결로 단독신청할 수 없다.","c":"중","v":1},"법무사2024_30-09-5":{"f":"A, B, C 3필지의 부동산 중 A, B는 甲·乙·丙 3인의 공유로 되어 있고 C는 甲·乙·丙·丁의 4인의 공유로 되어 있는 경우, 4인의 합의에 의하여 A는 甲의 단독소유로, B는 丁의 단독소유로, C는 乙의 단독소유로 하기로 하는 소유권이전등기신청을 할 수 없다.","w":"공유물분할은 공유관계에 있는 당사자 사이에서만 가능하다. 丁은 A, B필지의 공유자가 아니므로 丁을 포함한 4인이 합의해 A, B를 분할할 수 없다.","c":"상","v":1},"법무사2021_27-15-4":{"f":"피상속인의 소유명의로 등기가 되어 있는 부동산에 대하여 상속인 또는 피상속인을 피수용자로 하여 재결을 하고 상속인에게 보상금을 지급하였더라도 대위에 의한 상속등기를 먼저 한 후 소유권이전등기를 신청하여야 하고, 피상속인 명의에서 사업시행자 명의로 바로 소유권이전등기를 신청할 수는 없다.","w":"상속인에게 보상금을 지급했어도 등기가 피상속인 명의로 남아 있으면 사업시행자가 대위로 상속등기를 먼저 해야 하고, 상속등기 없이 한 소유권이전등기 신청은 수리하지 않는다(「공익사업을 위한 토지 등의 취득 및 보상에 관한 법률에 의한 등기사무처리지침」).","c":"상","v":1},"법무사2024_30-04-4":{"f":"토지수용으로 인한 소유권이전등기신청 시 사업시행자와 토지소유자의 협의서를 첨부정보로 제공한 경우에도 협의성립확인서를 제공하지 않았다면 등기신청을 수리할 수 없다.","w":"수용으로 인한 소유권이전등기신청서에 협의서만 붙였으면 협의성립확인서를 내도록 보정을 명하고, 내지 않으면 수리하지 않는다(등기예규 제1782호).","c":"상","v":1},"법무사2026_32-06-2":{"f":"토지 등 수용을 원인으로 한 소유권이전등기 신청서에는 일반적인 첨부서면 외에 등기원인을 증명하는 정보로 재결에 의한 수용일 때에는 토지수용위원회의 재결서등본을, 협의성립에 의한 수용일 때에는 토지수용위원회의 협의성립확인서 또는 협의성립의 공정증서와 그 수리증명서를 첨부하고, 보상을 증명하는 서면으로 보상금수령증 원본 또는 공탁서 원본을 제공하여야 한다. 수용은 원시취득이므로 등기의무자의 등기필정보는 제공하지 않는다.","w":"수용으로 인한 소유권이전등기에는 재결서등본(협의성립이면 협의성립확인서 등)과 보상금수령증 원본 또는 공탁서 원본을 내지만, 등기의무자의 등기필정보는 제공할 필요가 없다(등기예규 제1782호).","c":"상","v":1},"법무사2020_26-23-4":{"f":"토지수용으로 인한 소유권이전등기를 신청할 때에 첨부정보로서 제공하는 등기원인증서인 재결서 또는 협의성립확인서에는 검인을 받을 필요가 없다.","w":"검인은 계약을 원인으로 하는 소유권이전등기에서 계약서에 받는 것이다. 재결서나 협의성립확인서는 계약서가 아니어서 검인 대상이 아니다.","c":"상","v":1},"법무사2017_23-18-2":{"f":"협의이혼 당시 재산분할약정을 한 후 15년이 경과하더라도 재산분할을 원인으로 소유권이전등기신청을 할 수 있다.","w":"재산분할청구권의 2년 제척기간은 청구권 행사에 관한 것이다. 이미 약정이 있다면 15년이 지나도 약정에 따른 이전등기를 신청할 수 있다.","c":"상","v":1},"법무사2026_32-02-5":{"f":"한국주택금융공사가 한국주택금융공사법 제22조 제1항 제9호의2의 주택담보노후연금보증과 관련된 신탁업무를 수행하기 위하여 신탁을 설정하거나 해지하는 경우에는 검인을 받지 아니한 계약서를 등기원인증서로 제출할 수 있다.","w":"한국주택금융공사가 주택담보노후연금보증과 관련된 신탁을 설정하거나 해지할 때에는 부동산등기 특별조치법 제3조(검인)가 적용되지 않아 검인 없는 계약서를 낼 수 있다(등기예규 제1727호·제1799호).","c":"상","v":1},"법무사2021_27-05-1":{"f":"소유권의 귀속에 관하여 소송이 계속 중인 부동산에 관하여는 특조법이 적용되지 않으나, 등기관은 소송이 계속 중인 부동산인지 여부에 대하여 조사할 권한이 없다.","w":"소송 계속 여부는 확인서를 발급하는 단계에서 확인하는 사항이다. 등기관은 형식적 심사만 하므로 이를 따로 조사하지 않는다.","c":"중","v":1},"법무사2017_23-19-4":{"f":"1필지 부동산의 특정된 부분에 대한 일부이전등기는 신청할 수 없다.","w":"1필지의 특정 부분만 이전하려면 먼저 분필해야 한다. 위치를 특정하는 도면을 붙여도 일부이전등기를 할 수 없다. 지상권 등 용익권은 일부 설정 시 도면을 붙인다.","c":"상","v":1},"법무사2021_27-20-1":{"f":"건축물대장의 소유자표시란이 공란이거나 소유자표시에 일부 누락이 있어 대장상의 소유자를 확정할 수 없는 미등기건물에 관하여 국가를 상대방으로 하여 소유권확인의 판결을 받은 경우 부동산등기법 제65조 제2호의 소유권을 증명하는 판결에 해당하지 않는다.","w":"토지는 대장상 소유자를 특정할 수 없으면 국가를 상대로 한 소유권확인판결로 보존등기를 할 수 있지만, 건물에 대하여 국가를 상대로 받은 소유권확인판결은 부동산등기법 제65조 제2호의 판결에 해당하지 않는다(「미등기부동산의 소유권보존등기 신청인에 관한 업무처리지침」).","c":"상","v":1},"법무사2022_28-01-4":{"f":"협의에 의하여 상속재산을 분할하는 경우 그 상속인 중에 재외국민이 있는 때에는 그 재외국민을 포함한 공동상속인 전원이 협의에 참가하여야 하며, 이때 재외국민이 입국할 수 없는 경우에는 공동상속인 중 한 사람에게도 이를 위임하여 상속재산의 분할협의를 할 수 있다.","w":"상속재산 분할협의는 대리인에게 위임할 수 있고, 본인이 미성년자 등 행위능력제한자가 아니면 공동상속인 중 한 사람을 대리인으로 선임할 수 있다(「상속등기에 관한 업무처리지침」 제18조 제1항).","c":"상","v":1},"법무사2019_25-05-2":{"f":"","w":"수용을 원인으로 한 소유권이전등기는 사업시행자가 단독으로 신청하고, 재결서등본과 보상금을 지급(공탁)했음을 증명하는 서면을 첨부한다(「공익사업을 위한 토지 등의 취득 및 보상에 관한 법률에 의한 등기사무처리지침」).","c":"하","v":1},"법무사2019_25-05-3":{"f":"재결 전에 등기기록상 소유자가 사망한 경우 상속인을 피수용자로 하여 재결하고 상속인에게 보상금을 지급(공탁)하였더라도 상속등기를 먼저 하여야 수용을 원인으로 소유권이전등기를 신청할 수 있다.","w":"상속인을 피수용자로 재결하고 보상금을 줬더라도 등기가 피상속인 명의이면 사업시행자가 대위로 상속등기를 먼저 해야 하고, 상속등기 없이 한 이전등기 신청은 수리하지 않는다(「공익사업을 위한 토지 등의 취득 및 보상에 관한 법률에 의한 등기사무처리지침」).","c":"상","v":1},"법무사2024_30-05-4":{"f":"대장상 소유자미복구인 미등기토지에 대하여 국가를 상대로 한 소송에서 시효취득을 원인으로 한 소유권이전등기절차 이행의 판결을 얻은 경우에는 그 판결이유에서 원고의 소유임이 설시되어 있다면 원고는 직접 자기명의로 소유권보존등기를 신청할 수 있다.","w":"판결이유에 원고의 소유임이 밝혀져 있으면 국가를 대위한 보존등기를 거치지 않고 원고가 직접 자기 명의로 소유권보존등기를 신청할 수 있다.","c":"중","v":1},"법무사2016_22-13-2":{"f":"유증으로 인한 소유권이전등기 전에 상속등기가 이미 마쳐진 경우에도 상속등기를 말소하지 않고 유증으로 인한 소유권이전등기를 신청할 수 있다.","w":"유증으로 인한 소유권이전등기 전에 상속등기가 이미 마쳐졌으면 상속등기를 말소하지 않고 상속인으로부터 수증자에게로 유증을 원인으로 한 소유권이전등기를 신청할 수 있다(등기예규 제1795호).","c":"상","v":1},"법무사2016_22-21-2":{"f":"진정명의 회복을 원인으로 하는 소유권이전등기를 신청하는 경우 신청서에 등기원인일자를 기재하지 아니한다.","w":"진정명의회복은 새로운 권리 변동이 아니라서 등기원인일자를 쓰지 않고 등기원인만 '진정명의회복'으로 적는다.","c":"상","v":1},"법무사2020_26-26-4":{"f":"부동산 거래신고 등에 관한 법률 제11조의 토지거래 허가구역에 있는 토지에 대해 진정명의회복을 원인으로 한 소유권이전등기를 신청할 때에는 토지거래허가증을 첨부정보로 제공할 필요가 없다.","w":"진정명의회복은 거래에 의한 소유권 이전이 아니어서 토지거래허가의 대상이 아니다.","c":"상","v":1},"법무사2018_24-13-3":{"f":"개방형 축사의 소유권보존등기 신청서에는 건물의 표시를 증명하는 건축물대장 등본을 첨부하여야 하며, 건축물대장 등본을 첨부하지 못하는 경우에는 보존등기를 신청할 수 없다.","w":"개방형 축사는 건축물대장에 등록되어 있어야 하고, 건축허가신청서 등으로 대장을 대신하는 방식은 허용되지 않는다.","c":"중","v":1},"법무사2025_31-24-4":{"f":"합유자 중 일부가 나머지 합유자들 전원의 동의를 얻어 그의 합유지분을 다른 자에게 매도하거나 그 밖의 처분을 하여 종전의 합유자 중 일부가 교체되는 경우에는 합유지분을 처분한 합유자와 취득한 합유자, 그리고 나머지 합유자 전원의 공동신청으로 합유명의인 변경등기신청을 하여야 한다.","w":"합유자 중 일부가 교체되면 지분을 처분한 합유자, 지분을 취득한 합유자, 남은 합유자가 공동으로 합유명의인 변경등기를 신청하고, 처분한 합유자의 인감증명을 붙인다(「합유등기의 사무처리에 관한 예규」 2. 가.).","c":"상","v":1},"법무사2024_30-28-5":{"f":"환매권행사로 인한 소유권이전등기를 할 때 등기관은 환매권특약등기만 직권말소하고, 환매권특약의 등기 이후 환매권 행사 전에 경료된 제3자 명의의 소유권 이외의 권리는 직권으로 말소하지 않는다.","w":"환매권 행사로 이전등기를 하면 등기관은 환매특약등기만 직권으로 말소한다. 환매특약등기 뒤 환매권 행사 전에 마친 제3자 명의의 소유권 외의 권리는 일반원칙대로 공동신청으로 말소하고, 그 원인을 '환매권행사로 인한 실효'로 적는다(등기예규 제1359호).","c":"상","v":1},"법무사2016_22-23-3":{"f":"저당권의 이전등기 시 채권양도의 통지를 증명하는 서면 또는 채무자의 승낙서는 첨부할 필요가 없다.","w":"저당권 이전등기를 신청할 때 채권양도의 통지나 승낙을 증명하는 서면은 첨부정보가 아니다. 이전계약서 등을 제공한다.","c":"중","v":1},"법무사2018_24-24-5":{"f":"법원의 촉탁에 의하여 주택임차권등기가 마쳐진 후 등기명의인의 주소, 성명 및 주민등록번호가 변경된 경우에는 등기명의인이 단독으로 등기명의인표시변경등기를 신청하여야 한다.","w":"법원 촉탁으로 주택임차권등기를 마친 뒤 등기명의인의 주소·성명·주민등록번호가 바뀐 경우 등기명의인표시변경등기는 등기명의인이 신청할 수 있다(등기예규 제1064호).","c":"상","v":1},"법무사2018_24-29-2":{"f":"채권자는 동일한 채권의 담보로 甲 부동산에 관한 소유권과 乙 부동산에 관한 지상권에 대하여 공동근저당권설정등기를 신청할 수 있는데, 이때 甲 부동산의 소유자와 乙 부동산의 지상권자는 동일하지 않아도 된다.","w":"공동담보의 요건은 동일한 채권을 담보하는 것이며 설정자가 같을 필요는 없다. 소유권과 지상권이 다른 사람의 것이어도 공동근저당을 설정할 수 있다.","c":"상","v":1},"법무사2019_25-09-5":{"f":"법정지상권은 법률의 규정에 의한 물권 취득이지만 이를 등기하고자 할 때에는 법정지상권을 취득하는 자와 토지소유자가 공동으로 등기를 신청하여야 한다.","w":"법정지상권도 등기하지 않으면 처분할 수 없으므로 등기가 필요하고, 그 등기는 등기권리자와 등기의무자의 공동신청으로 한다.","c":"중","v":1},"법무사2019_25-29-4":{"f":"공장저당법 제6조에 따른 목록의 변경이 기계·기구의 일부 멸실 또는 분리로 인한 경우에는 소유자가 단독으로 목록기재변경등기를 신청한다.","w":"공장저당 목록의 변경등기는 소유자가 신청한다. 기계·기구의 일부 멸실이나 분리로 인한 변경이면 저당권자의 동의를 증명하는 정보(인감증명 포함)를 함께 낸다(등기예규 제1475호). 저당권자와 공동으로 신청하는 것이 아니다.","c":"상","v":1},"법무사2021_27-07-3":{"f":"근저당권부 채권에 대한 질권의 등기를 신청하는 경우 국민주택채권을 매입할 필요가 없다.","w":"국민주택채권 매입 대상은 소유권보존·이전등기, 저당권·근저당권 설정·이전등기 등이고, 근저당권부 채권에 대한 질권의 부기등기는 매입 대상이 아니다.","c":"중","v":1},"법무사2021_27-09-2":{"f":"토지 등기기록에 요역지지역권의 등기가 있는 경우 그 토지에 대한 합필의 등기를 할 수 없다.","w":"합필하려는 토지에 소유권·지상권·전세권·임차권 및 승역지에 하는 지역권의 등기, 모든 토지에 같은 저당권등기 외의 권리에 관한 등기가 있으면 합필할 수 없다(부동산등기법 제37조 제1항). 요역지지역권의 등기는 여기에 들지 않는다.","c":"중","v":1},"법무사2021_27-26-1":{"f":"지상권설정등기를 신청하는 경우 존속기간, 지료 및 지급시기는 임의적 기재사항이므로 약정이 있는 경우에만 신청정보로 제공한다.","w":"지상권설정등기의 필요적 기록사항은 지상권 설정의 목적과 범위이다. 존속기간, 지료와 지급시기는 약정이 있는 경우에만 기록한다(부동산등기법 제69조).","c":"상","v":1},"법무사2022_28-21-5":{"f":"지상권은 타인의 토지를 배타적으로 사용하는 용익물권이지만 이미 지상권설정등기가 경료되어 있는 상태에서 기존 지상권설정등기의 말소를 조건으로 하는 정지조건부 지상권설정등기청구권을 보존하기 위한 조건부지상권설정청구권가등기를 신청할 수 있다.","w":"기존 지상권이 말소되는 것을 정지조건으로 하는 청구권이므로 이중 지상권이 되지 않는다. 가등기로 순위를 보전할 수 있다.","c":"중","v":1},"법무사2022_28-29-3":{"f":"이미 전세권설정등기가 경료된 주택에 대하여 동일인을 권리자로 하는 법원의 주택임차권등기명령에 따른 촉탁등기는 이를 수리할 수 있다.","w":"전세권등기가 있더라도 같은 사람 명의의 임차권등기명령 촉탁등기는 수리할 수 있다. 두 등기가 양립한다.","c":"상","v":1},"법무사2024_30-17-1":{"f":"피담보채권이 확정되기 전에 근저당권의 기초가 되는 기본계약상의 채권자지위의 양도를 원인으로 근저당권이전등기를 신청하는 경우 근저당권설정자가 물상보증인이라도 그의 승낙을 증명하는 정보를 첨부정보로 제공할 필요는 없다.","w":"확정 전 계약양도를 원인으로 근저당권이전등기를 신청할 때 근저당권설정자가 물상보증인이거나 소유자가 제3취득자라도 그의 승낙을 증명하는 정보는 낼 필요가 없다(등기예규 제1867호).","c":"상","v":1},"법무사2024_30-17-2":{"f":"피담보채권이 확정되기 전에 계약양도 등을 원인으로 근저당권이전등기를 신청하는 경우 등기원인을 증명하는 정보인 근저당권이전계약서에는 채무자의 표시와 날인이 있어야 한다.","w":"확정 전 계약양도는 채무자의 지위에도 영향을 주므로 이전계약서에 채무자가 표시되고 날인해야 한다.","c":"하","v":1},"법무사2024_30-17-3":{"f":"확정채권의 대위변제를 원인으로 하는 근저당권이전등기의 경우에는 대위변제증서를 첨부정보로 제공하면 되고 근저당권이전계약서는 필요하지 않다.","w":"대위변제는 법률의 규정에 따라 채권과 근저당권이 이전하는 것이어서 계약서가 없고, 대위변제를 증명하는 서면을 제출한다.","c":"중","v":1},"법무사2024_30-17-5":{"f":"근저당권의 피담보채권이 확정되기 전에 그 피담보채권이 양도 또는 대위변제된 경우에는 이를 원인으로 하여 근저당권이전등기를 신청할 수 없다.","w":"피담보채권이 확정되기 전에 피담보채권이 양도되거나 대위변제되어도 이를 원인으로 근저당권이전등기를 신청할 수 없다. 확정 전에는 계약양도·계약의 일부 양도·계약가입을 원인으로 한다(등기예규 제1867호).","c":"상","v":1},"법무사2026_32-09-4":{"f":"임대차의 존속기간이 만료된 경우와 주택임차권등기 및 상가건물임차권등기가 경료된 경우에는 그 등기에 기초한 임차권이전등기나 임차물전대등기를 할 수 없다.","w":"존속기간이 끝난 임차권과 임차권등기명령에 따른 주택·상가건물 임차권등기에는 이전등기나 전대등기를 할 수 없다.","c":"상","v":1},"법무사2022_28-06-5":{"f":"동일 부동산에 대한 소유권이전청구권 보전의 가등기상의 권리자와 근저당권자가 동일인이었다가 그 가등기에 기한 소유권이전의 본등기가 경료됨으로써 소유권과 근저당권이 동일인에게 귀속된 경우와 같이 근저당권이 혼동으로 소멸한 경우에는 그 근저당권설정등기가 말소되지 아니한 채 제3자 앞으로 다시 소유권이전등기가 경료되었다면 현 소유자와 근저당권자가 공동으로 말소등기를 신청하여야 한다.","w":"혼동으로 소멸한 근저당권은 등기명의인이 단독으로 말소를 신청하지만, 말소 전에 제3자에게 소유권이 넘어갔으면 현 소유자와 근저당권자가 공동으로 신청한다(「근저당권에 관한 등기사무처리지침」).","c":"상","v":1},"법무사2023_29-14-2":{"f":"채권자는 동일한 채권의 담보로 甲 부동산에 관한 소유권과 乙 부동산에 관한 지상권에 대하여 공동근저당권설정등기를 신청할 수 있으며, 이때 甲 부동산의 소유자와 乙 부동산의 지상권자는 동일인이 아니어도 된다.","w":"공동근저당은 같은 채권을 담보한다는 점이 요건이다. 소유자와 지상권자가 같은 사람일 필요가 없다.","c":"상","v":1},"법무사2023_29-29-1":{"f":"토지 또는 건물과 기계·기구의 소유자가 동일하지 않은 경우에는 그 기계·기구를 공장 및 광업재단 저당법에 따른 공장저당의 목적으로 할 수 없다.","w":"공장저당은 토지·건물과 같은 소유자의 기계·기구에 설정된다. 소유자가 다르면 동의서를 받아도 목적물로 삼지 못한다.","c":"중","v":1},"법무사2017_23-14-2":{"f":"1동의 건물을 횡단적으로 구분한 경우에 상층의 건물을 소유하기 위하여 구분지상권의 설정등기는 할 수 없다.","w":"구분지상권은 토지의 상하 일정 범위에 대한 지상권이다. 건물을 위아래로 나누어 상층을 소유하기 위해 설정할 수 없다.","c":"중","v":1},"법무사2019_25-02-4":{"f":"근저당권이전등기를 신청할 때에는 근저당권설정자가 물상보증인이거나 소유자가 제3취득자인 경우에도 그의 승낙을 증명하는 정보를 제공할 필요가 없다.","w":"근저당권이전등기를 신청할 때 근저당권설정자가 물상보증인이거나 소유자가 제3취득자라도 그의 승낙을 증명하는 정보는 낼 필요가 없다(등기예규 제1867호).","c":"상","v":1},"법무사2020_26-27-5":{"f":"채무자변경을 원인으로 하는 근저당권변경등기를 신청하는 경우에는 등기의무자인 근저당권설정자(소유자)의 등기필정보를 제공하여야 한다.","w":"변경등기는 근저당권자가 등기권리자, 설정자(소유자)가 등기의무자이다. 제공하는 등기필정보는 등기의무자인 설정자의 것이다.","c":"중","v":1},"법무사2021_27-08-2":{"f":"근저당설정등기를 함에 있어 그 근저당권의 채권자 또는 채무자가 수인인 경우, 각 채권자 또는 채무자별로 채권최고액을 구분하여 기록할 수 없고 단일한 채권최고액만을 기록하여야 한다.","w":"채권자나 채무자가 여럿이어도 근저당권에는 단일한 채권최고액만 기록하고, 채권자별·채무자별로 나누어 적지 않는다(「근저당권에 관한 등기사무처리지침」 제2조 제1항).","c":"상","v":1},"법무사2026_32-27-2":{"f":"근저당권이 확정된 후에 채무자변경을 원인으로 한 근저당권변경등기를 신청하는 경우에도 채무자의 동의가 있음을 증명하는 정보를 제공할 필요는 없다.","w":"채무자변경으로 인한 근저당권변경등기는 근저당권자와 근저당권설정자가 공동으로 신청하고, 채무자는 등기 당사자가 아니어서 그의 동의를 증명하는 정보를 요구하지 않는다. 확정 후에는 피담보채무를 제3자가 인수한 경우 채무인수로 인한 저당권변경등기에 준해 신청한다(「근저당권에 관한 등기사무처리지침」).","c":"중","v":1},"법무사2026_32-27-3":{"f":"채무자 표시변경을 원인으로 근저당권변경등기를 신청하는 경우에는 등기의무자의 인감증명과 등기필정보를 제공할 필요가 없다.","w":"표시변경은 권리 내용의 변동이 아니라 신청인 표시를 고치는 것이어서 인감증명과 등기필정보가 필요하지 않다.","c":"중","v":1},"법무사2026_32-27-4":{"f":"동일 부동산에 대하여 甲과 乙을 공동채권자로 하는 하나의 근저당권설정계약을 체결한 경우, 각 채권자별로 채권최고액을 구분하여 등기하거나 甲과 乙을 각각 근저당권자로 하는 2개의 동순위의 근저당권설정등기를 신청할 수 없다.","w":"근저당권의 채권자나 채무자가 여럿이어도 단일한 채권최고액만 기록하고 채권자별로 나누어 기록할 수 없다(등기예규 제1867호). 하나의 설정계약이므로 하나의 근저당권설정등기를 신청해야 하고, 채권자마다 동순위 근저당권 2개로 나누어 등기할 수도 없다.","c":"중","v":1},"법무사2026_32-27-5":{"f":"채권최고액을 감액하는 변경등기의 경우 근저당권부 채권에 관한 질권자 또는 가압류권자 등 등기상 이해관계 있는 제3자의 승낙이 있음을 증명하는 정보를 제공하여야 한다.","w":"감액은 근저당권부 채권에 질권이나 가압류를 한 자에게 불이익을 주므로 이해관계 있는 제3자의 승낙이 있어야 한다.","c":"중","v":1},"법무사2025_31-03-2":{"f":"등기원인을 증명하는 정보로 제공하는 재결서에 송전선로의 설치 및 유지를 위하여 공중공간에 대한 재결이 있더라도 구분지상권의 설정을 내용으로 하는 수용 재결이 아닌 경우에는 구분지상권 설정등기를 신청할 수 없다.","w":"구분지상권은 재결서가 구분지상권의 설정을 내용으로 해야 신청할 수 있다. 공중공간에 대한 재결이라는 표현만으로는 부족하다.","c":"중","v":1},"법무사2021_27-30-1":{"f":"미등기건물에 대하여 임차권등기명령에 따른 임차권등기의 촉탁이 있는 경우에는 등기관은 직권으로 소유권보존등기를 할 수 있다.","w":"미등기 주택이나 상가건물에 임차권등기명령에 따른 등기촉탁이 있으면 등기관은 직권으로 소유권보존등기를 한 뒤 임차권등기를 한다(부동산등기법 제66조, 등기예규 제1688호).","c":"상","v":1},"법무사2016_22-24-5":{"f":"","w":"지상권은 토지의 전부나 일부 구역 위에 성립하는 권리이고, 공유지분을 목적으로 설정할 수는 없다.","c":"하","v":1},"법무사2016_22-25-2":{"f":"차임을 가변적인 비율(예를 들어, 연 매출이 400억 미만일 경우 : 차임 없음, 연매출이 400억 이상 500억 미만일 경우 : 연매출의 2.0%,···연매출이 1,000억 원 이상일 경우 : 연매출의 4.2%)로 하는 임차권설정등기신청도 수리할 수 있다.","w":"차임을 정하는 기준이 객관적으로 정해져 있으면 매출액에 따라 달라지는 비율 차임도 임차권설정등기의 차임으로 기록할 수 있다.","c":"중","v":1},"법무사2025_31-08-5":{"f":"채권담보권의 부기등기는 저당권자가 등기의무자가 되고 채권담보권자가 등기권리자가 되어 공동으로 신청하며, 이 경우 저당권자는 법인 또는 부가가치세법에 따라 사업자등록을 한 사람이어야 한다.","w":"채권담보권의 부기등기는 저당권자가 등기의무자, 채권담보권자가 등기권리자가 되어 공동으로 신청하고, 이때 저당권자는 법인 또는 부가가치세법에 따라 사업자등록을 한 사람이어야 한다(등기예규 제1858호).","c":"상","v":1},"법무사2020_26-18-4":{"f":"공동전세권자 甲, 乙, 丙, 丁이 준공유하는 건물전세권을 등기할 때에 그들의 각 지분을 기록하여야 함에도 착오로 이를 누락하였다면 甲, 乙, 丙, 丁은 자신들의 각 지분을 추가 기록하는 경정등기를 신청할 수 있고, 이러한 경정등기는 그 전세권의 존속기간이 만료된 경우에도 신청할 수 있다.","w":"경정등기는 처음 등기할 때부터 있던 착오를 바로잡는 것이어서, 전세권의 존속기간이 만료된 뒤에도 지분을 추가 기록하는 경정등기를 신청할 수 있다.","c":"중","v":1},"법무사2023_29-28-3":{"f":"건물 중 1층 전부 및 2층 일부에 대하여 甲 명의의 전세권설정등기가 경료되고 이어 4층 전부에 대하여 乙 명의의 전세권설정등기가 경료된 상태에서, 甲 명의의 전세권설정등기의 존속기간 연장을 위한 변경등기를 할 경우 乙은 등기상 이해관계 있는 제3자에 해당한다.","w":"건물 일부에 대한 전세권자도 건물 전부의 매각대금에서 우선변제를 받을 수 있어서(민법 제303조 제1항), 먼저 설정된 甲 전세권의 존속기간을 늘리면 뒤에 다른 층에 설정된 乙 전세권자도 불이익을 입는다. 그래서 乙은 등기상 이해관계 있는 제3자이다.","c":"중","v":1},"법무사2026_32-14-4":{"f":"전세권설정등기 후에 제3자 명의의 근저당권설정등기가 경료된 후 전세권설정등기의 변경등기를 신청하는 경우, 그 내용이 전세금의 감액인 경우에는 근저당권자의 승낙서 등을 첨부하지 않아도 부기에 의하여 그 등기를 할 것이나, 전세권의 존속기간 연장과 전세금의 감액을 함께 신청하는 경우에는 각각 별건으로 신청하되 근저당권자의 승낙서 등을 첨부하지 못한 때에는 존속기간 연장은 주등기로, 전세금 감액은 부기로 하여야 한다.","w":"감액은 근저당권자에게 불이익이 없어 승낙 없이도 부기로 하고, 존속기간 연장은 승낙이 없으면 주등기로 한다. 두 가지를 모두 주등기로 하는 것이 아니다.","c":"중","v":1},"법무사2026_32-15-1":{"f":"지상권의 최단기간의 보장에도 불구하고 등기신청 시 그 존속기간을 민법 제280조 제1항의 최단기간보다 단축한 기간으로 등기를 신청한 경우에도 등기관은 그 등기를 각하하지 아니하고 신청서 기재대로 수리하여야 한다.","w":"최단기간보다 짧게 적어 신청해도 그 기간은 민법 제280조 제2항에 따라 법정기간까지 늘어나므로, 등기관은 신청서 기재대로 수리한다(「지상권설정등기의 존속기간에 관한 업무처리지침」).","c":"상","v":1},"법무사2026_32-15-2":{"f":"구분지상권이 설정되어 있는 토지에 대하여도 기존 구분지상권자의 승낙을 증명하는 정보를 첨부정보로서 제공하여 통상의 지상권설정등기를 신청할 수 있다.","w":"구분지상권이 있는 토지에도 기존 구분지상권자의 승낙이 있으면 통상의 지상권설정등기를 할 수 있다.","c":"상","v":1},"법무사2026_32-15-3":{"f":"甲과 乙이 공유하고 있는 토지에 대하여 甲은 乙의 동의를 받더라도 자신의 공유지분만에 대한 지상권설정등기를 신청할 수 없다.","w":"지상권은 토지 전체를 이용하는 권리여서 공유지분만을 목적으로 하는 지상권설정등기는 허용되지 않는다.","c":"상","v":1},"법무사2026_32-15-4":{"f":"지상권이 설정되어 있는 토지 위에 지상권자 아닌 제3자가 건물을 신축한 후 건물에 대한 소유권보존등기를 신청하는 경우에는 그 지상권을 말소하거나 지상권자의 승낙이 있음을 증명하는 정보를 제공할 필요가 없다.","w":"건물 소유권보존등기는 건물에 관한 등기로서 대지의 지상권 등기와 관계가 없어 대지 권리자의 승낙을 요구하지 않는다.","c":"중","v":1},"법무사2024_30-23-5":{"f":"지역권이 설정되어 있는 토지를 대지권의 목적으로 하는 대지권등기를 할 수 있고, 대지권이라는 뜻의 등기가 마쳐진 토지에 대해서도 지역권설정등기를 할 수 있다.","w":"대지권 등기가 된 토지에도 지역권은 설정할 수 있다. 대지권의 일체성에 따라 제한되는 것은 대지사용권만을 따로 처분하는 등기이다.","c":"중","v":1},"법무사2017_23-17-2":{"f":"지역권설정등기를 하는 경우 등록면허세는 요역지의 시가표준액이 과세표준액이 된다.","w":"지역권설정등기의 등록면허세는 승역지가 아니라 요역지의 시가표준액을 과세표준으로 한다.","c":"상","v":1},"법무사2016_22-16-1":{"f":"법정상속분대로 등기된 후 협의분할에 의하여 소유권경정등기를 신청한 경우 또는 협의분할에 의한 상속등기 후 협의해제를 원인으로 법정상속분대로 소유권경정등기를 신청한 경우에는 당사자 사이의 동일성이 인정되므로 등기관은 이러한 등기신청을 수리할 수 있다.","w":"어느 경우나 같은 상속인들 사이의 상속등기를 바로잡는 것이어서 등기의 동일성이 인정된다. 소유권경정등기를 수리할 수 있다.","c":"중","v":1},"법무사2017_23-13-2":{"f":"법인 아닌 사단의 대표자의 성명, 주소 및 주민등록번호를 추가로 기록하는 등기명의인표시 변경등기신청은 할 수 있다.","w":"법인 아닌 사단·재단도 대표자나 관리인의 성명, 주소, 주민등록번호를 등기명의인 표시로 기록하므로 이를 변경하거나 추가하는 변경등기를 신청할 수 있다.","c":"상","v":1},"법무사2017_23-16-4":{"f":"등기의 말소를 신청하는 경우에 그 말소에 대하여 등기상 이해관계 있는 제3자가 있을 때에는 제3자의 승낙이 있어야 하며 이에 따라 등기를 말소할 때에는 등기상 이해관계 있는 제3자 명의의 등기는 등기관이 직권으로 말소한다.","w":"제3자의 승낙서를 첨부하면 그 제3자 명의 등기는 등기관이 직권으로 말소한다. 따로 말소등기를 동시에 신청할 필요가 없다.","c":"상","v":1},"법무사2019_25-30-4":{"f":"소유권이전등기 시 등기명의인의 주소가 도로명주소법에 따른 주소로 변경된 경우 등기관은 직권으로 등기명의인표시변경등기를 하지 아니한다.","w":"소유권이전등기를 할 때 등기의무자의 주소가 전거가 아니라 도로명주소법에 따른 주소로 바뀐 것뿐이면 주소변경의 직권등기를 하지 않는다(「도로명주소법에 따른 부동산등기 사무처리지침」).","c":"상","v":1},"법무사2022_28-02-3":{"f":"동일성을 해하는 등기명의인표시경정등기의 신청임에도 등기관이 이를 간과하여 수리한 경우, 종전 등기명의인으로의 회복등기 신청은 현재의 등기명의인이 단독으로 하거나 종전 등기명의인과 공동으로 하여야 하고, 종전의 등기명의인이 단독으로 할 수는 없다.","w":"이 회복등기는 현재의 등기명의인이 단독으로 하거나 종전 등기명의인과 공동으로 신청한다. 종전 등기명의인이 단독으로 한 신청은 수리하지 않는다(「경정등기절차에 관한 업무처리지침」).","c":"상","v":1},"법무사2026_32-20-4":{"f":"신청서에 기재된 경정등기의 목적이 현재의 등기와 동일성 혹은 유사성을 인정할 수 없는 정도에 이르렀더라도, 같은 부동산에 관하여 따로 소유권보존등기가 존재하지 아니하거나 등기의 형식상 예측할 수 없는 손해를 입을 우려가 있는 이해관계인이 없다면 등기관은 그 경정등기신청을 각하하여서는 아니 된다.","w":"동일성이 없더라도 중복 보존등기가 없고 이해관계인이 손해를 입을 우려도 없다면 경정등기를 허용한다는 취지의 판례가 있다.","c":"하","v":1},"법무사2020_26-12-1":{"f":"경정등기의 형식으로 이루어지나 그 실질이 말소등기(일부말소 의미의)에 해당하는 경우에는 등기상 이해관계 있는 제3자가 있는 때에 그의 승낙서 등을 첨부한 경우에는 부기등기로 하고, 이를 첨부하지 아니한 경우 등기관은 그 등기신청을 수리하여서는 아니 된다.","w":"일부말소 의미의 경정은 제3자의 승낙서가 없으면 아예 수리하지 않는다. 승낙서 없이 주등기로 하는 방식은 인정되지 않는다.","c":"상","v":1},"법무사2017_23-24-4":{"f":"근저당권 설정 후 소유권이 제3자에게 이전된 경우에는 그 제3취득자뿐 아니라 근저당권설정자도 근저당권자와 공동으로 그 말소등기를 신청할 수 있다.","w":"근저당권 설정 뒤 소유권이 제3자에게 넘어갔으면 근저당권설정자와 제3취득자 모두 근저당권자와 공동으로 말소등기를 신청할 수 있다(등기예규 제1867호).","c":"상","v":1},"법무사2022_28-04-4":{"f":"등기관이 소유권이전등기를 할 때에 등기명의인의 주소변경으로 신청정보 상의 등기의무자의 표시가 등기기록과 일치하지 아니하는 경우라도 첨부정보로서 제공된 주소를 증명하는 정보에 등기의무자의 등기기록 상의 주소가 신청정보 상의 주소로 변경된 사실이 명백히 나타나면 직권으로 등기명의인표시의 변경등기를 하여야 하며, 이는 법인의 본점소재지가 변경된 경우에도 마찬가지이다.","w":"직권변경은 자연인의 주소뿐 아니라 법인의 본점 이전에도 적용되고, 변경 사실이 첨부정보에 명백히 나타나면 한다.","c":"중","v":1},"법무사2023_29-01-2":{"f":"甲이 근저당권설정등기를 신청하였으나 등기관의 잘못으로 그 기록을 누락하였고 그 후 乙이 동일 부동산에 대하여 순위 제1번의 근저당권설정등기를 경료하였다면, 직권경정등기절차에 준하여 위 누락된 근저당권설정등기를 순위 제2번으로 기록할 수 있고, 이 경우 乙의 승낙이 있음을 증명하는 정보를 제공할 필요는 없다.","w":"누락된 등기를 乙보다 뒤인 2번으로 기록하면 乙의 순위에 불이익이 없어서 乙의 승낙은 필요 없다.","c":"중","v":1},"법무사2025_31-07-2":{"f":"선행 가처분과 후행 가처분의 피보전권리가 모두 소유권이전등기 말소등기청구권 및 근저당권설정등기 말소등기청구권인 경우에도, 확정판결을 받은 후행 가처분채권자의 말소등기신청에서 선행 가처분채권자는 권리의 목적인 등기가 말소됨에 따라 손해를 입을 우려가 있는 등기상의 권리자로 보아야 한다.","w":"후행 가처분채권자가 말소를 해 버리면 선행 가처분채권자의 피보전권리 실현에 영향이 생긴다. 선행 가처분채권자는 이해관계 있는 제3자이다.","c":"중","v":1},"법무사2016_22-17-5":{"f":"甲에서 乙에게로의 소유권이전등기가 부적법 말소된 후 甲에서 丙으로 소유권이전등기가 마쳐진 경우 乙 명의의 소유권이전등기를 말소회복함에 있어서 丙은 등기상 이해관계 있는 제3자에 해당하지 않는다.","w":"丙 명의의 소유권이전등기는 乙 등기의 회복과 함께 존재할 수 없어 회복에 앞서 말소되어야 할 등기이다. 그래서 丙은 회복등기에 승낙을 해야 하는 이해관계 있는 제3자가 아니라는 것이 판례이다.","c":"중","v":1},"법무사2018_24-03-1":{"f":"甲 소유 부동산에 대하여 마쳐진 乙 명의의 가처분등기가 집행법원의 촉탁착오로 인하여 말소된 후 甲의 상속인 丙 명의의 상속등기가 마쳐진 경우, 집행법원이 말소된 가처분등기의 회복등기를 촉탁할 때에 상속인 丙의 승낙이 있음을 증명하는 정보를 첨부정보로서 제공할 필요가 없다.","w":"상속인은 가처분채무자인 甲의 지위를 포괄승계하는 자라서 가처분 회복등기에서 별도의 이해관계 있는 제3자가 아니다.","c":"중","v":1},"법무사2020_26-03-3":{"f":"가등기에 의한 소유권이전의 본등기가 말소된 다음 乙 명의의 가압류등기가 마쳐진 상태에서 이 본등기의 회복등기를 신청할 때에 가압류권자 乙의 승낙이 있음을 증명하는 정보를 첨부정보로서 제공하여야 하며, 이 경우 등기관이 소유권이전본등기의 회복등기를 할 때에는 위 가압류등기를 직권으로 말소하여야 한다.","w":"본등기가 회복되면 그 순위는 가등기 순위로 돌아가므로, 본등기 말소 뒤 가등기의무자를 상대로 마쳐진 乙의 가압류는 본등기와 양립할 수 없다. 乙은 회복등기에 승낙을 해야 하는 이해관계인이고, 회복등기를 하면서 등기관이 그 가압류등기를 직권으로 말소한다.","c":"중","v":1},"법무사2025_31-14-2":{"f":"회복할 근저당권설정등기가 말소되기 전에 마쳐진 후순위 근저당권의 명의인은 회복등기에 있어 등기상 이해관계 있는 제3자에 해당한다.","w":"선순위 근저당권이 회복되면 말소 전부터 있던 후순위 근저당권자도 그동안 올라가 있던 순위가 다시 밀리는 불이익을 입으므로, 회복등기의 등기상 이해관계 있는 제3자이다(판례).","c":"중","v":1},"법무사2019_25-12-2":{"f":"말소대상인 소유권이전등기 전에 설정된 근저당권에 기한 임의경매개시결정등기가 마쳐진 경우 신청채권자는 등기상 이해관계 있는 제3자에 해당하므로 그의 승낙서 등을 첨부하여야 한다.","w":"승낙서를 첨부하면 소유권이전등기를 말소할 수 있다. 등기관이 경매개시결정등기와 그 근저당권을 직권으로 말소하는 절차까지 요구되는 것은 아니다.","c":"중","v":1},"법무사2018_24-06-4":{"f":"등기상 이해관계 있는 제3자의 등기를 말소하여야 하는 경우에, 甲·乙 공유의 부동산에 대하여 乙 지분에 대해서만 처분제한 또는 담보물권의 등기가 되어 있는 상태에서 甲 단독소유로 하는 경정등기(乙 지분 말소 의미의)를 하는 경우와 같이 등기상 이해관계 있는 제3자의 등기가 경정등기로 인하여 상실되는 지분만을 목적으로 하는 경우에는 그 등기를 등기관이 직권으로 말소한다.","w":"경정등기로 사라지는 지분만을 목적으로 한 제3자의 등기는 신청 없이 등기관이 직권으로 말소한다.","c":"중","v":1},"법무사2023_29-04-1":{"f":"소유권이전등기의 말소소송에서 등기명의인인 종중 등 법인 아닌 사단이 그 실체가 인정되지 아니하여 당사자능력이 없음을 이유로 소각하판결이 확정되고, 위 각하판결정본 등이 등기관에게 제출된 경우에도 등기관은 당사자능력이 없는 위 종중 등 명의의 등기를 직권으로 말소할 수 없다.","w":"당사자능력이 없다는 이유로 소각하판결이 확정되어 그 판결정본을 내더라도 등기관은 그 종중 등 명의의 등기를 부동산등기법 제58조로 직권말소할 수 없다(등기예규 제1380호).","c":"상","v":1},"법무사2017_23-22-5":{"f":"가등기를 명하는 법원의 가처분명령을 등기원인으로 하여 법원이 가등기촉탁을 하는 때에는 이를 각하하여야 한다.","w":"가등기가처분명령에 의한 가등기는 가등기권리자가 그 명령을 등기원인증서로 하여 단독으로 신청한다. 법원이 가처분명령을 등기원인으로 가등기를 촉탁하면 각하한다(등기예규 제1849호).","c":"상","v":1},"법무사2017_23-28-3":{"f":"경매개시결정등기 전에 소유권을 취득한 자가 매수인이 된 경우에는 매각을 원인으로 하는 소유권이전등기를 하지 않으나, 경매개시결정등기 후에 소유권을 취득한 자가 매수인이 된 경우에는 매각을 원인으로 하는 소유권이전등기를 한다.","w":"경매개시결정등기 전에 소유권을 취득한 제3취득자가 매수인이 되면 경매개시결정등기와 인수하지 않는 부담기입의 말소만 촉탁하고 소유권이전등기는 촉탁하지 않는다(등기예규 제1378호). 이 예외는 경매개시결정등기 전에 취득한 자에 한한다.","c":"중","v":1},"법무사2018_24-02-4":{"f":"저당권설정등기청구권을 보전하기 위한 가처분등기가 마쳐진 후 그 가처분채권자가 가처분채무자를 등기의무자로 하여 저당권설정등기를 신청하는 경우에는 그 가처분등기 이후에 마쳐진 제3자 명의의 저당권설정등기의 말소를 단독으로 신청할 수 없다.","w":"가처분 후 마쳐진 등기의 단독 말소 신청은 지상권, 지역권, 전세권, 임차권의 설정등기청구권을 보전하는 가처분에 한해 인정된다. 저당권설정 청구권 가처분은 이에 해당하지 않는다.","c":"상","v":1},"법무사2018_24-27-3":{"f":"채권자 ○○○외 ○인으로 등기된 가압류등기에 대하여 일부 채권자의 해제로 인한 변경등기 촉탁이 있는 경우에는 채권자 전원을 기록하는 경정등기를 한 다음 촉탁에 의한 변경등기를 하여야 한다.","w":"일부 채권자의 해제에 따른 변경등기 촉탁은 각하하지 않는다. ○○○외 ○인으로 등기된 경우 먼저 경정등기를 하고 그 다음 변경등기를 한다(「채권자가 다수인 가압류·가처분등기 및 경매개시결정등기 등에 관한 예규」).","c":"상","v":1},"법무사2021_27-02-1":{"f":"가등기가처분명령을 등기원인으로 하여 법원이 가등기촉탁을 한 경우 등기관은 이를 각하하여야 한다.","w":"가등기가처분명령에 의한 가등기는 가등기권리자가 단독으로 신청하는 것이고, 법원이 가처분명령을 등기원인으로 가등기를 촉탁하면 각하한다(등기예규 제1849호).","c":"상","v":1},"법무사2021_27-11-4":{"f":"토지거래허가구역 내의 민사집행법에 따른 경매의 경우에는 토지거래허가에 관한 규정이 적용되지 않으므로 토지거래허가증명을 첨부할 필요가 없다.","w":"민사집행법에 따른 경매는 토지거래허가 규정의 적용에서 제외되어 매각에 따른 이전등기에 허가증이 필요 없다.","c":"상","v":1},"법무사2021_27-28-2":{"f":"소유권이전등기청구권보전 가등기에 의하여 소유권이전의 본등기를 한 경우 가등기 후 본등기 전에 마쳐진 해당 가등기상 권리를 목적으로 하는 가압류등기는 등기관이 직권으로 말소하지 않는다.","w":"직권말소 대상은 가등기 후 본등기 전에 마쳐진 중간처분 등기이다. 가등기상의 권리 자체를 목적으로 한 가압류는 본등기와 양립하므로 말소 대상이 아니다.","c":"상","v":1},"법무사2022_28-26-1":{"f":"합유자 중 1인의 지분에 대한 가압류등기는 할 수 없으므로 위 촉탁이 있는 경우 이를 각하하여야 하며 합유지분에 대하여 가압류등기가 이미 마쳐져 있다면 등기관은 위 등기를 직권말소 할 수 있다.","w":"합유지분에 대한 가압류는 등기할 수 없는 등기로 보아 이미 마쳐져 있는 경우에도 등기관이 직권말소할 수 있다.","c":"중","v":1},"법무사2023_29-15-3":{"f":"甲 명의 부동산에 대하여 乙 명의의 소유권이전청구권보전을 위한 가등기와 丙 명의의 가압류등기가 순차 경료된 후, 乙이 위 가등기에 기한 본등기절차에 의하지 아니하고 甲으로부터 별도의 소유권이전등기를 경료받은 경우에도 乙의 가등기는 혼동으로 소멸하지 않기 때문에 가등기에 기한 본등기를 할 수 있다.","w":"가등기권리자가 별도로 소유권을 이전받아도 가등기는 소멸하지 않는다. 가등기에 의한 본등기로 가압류에 우선할 수 있기 때문이다.","c":"중","v":1},"법무사2024_30-27-4":{"f":"배우자 명의로 명의신탁한 부동산에 대하여 명의신탁계약의 해지약정에 대한 예약을 하고 장차 명의신탁해지약정의 효력이 발생한 경우 생기는 소유권이전청구권을 보전하기 위한 가등기를 할 수 있다.","w":"배우자 사이의 명의신탁은 조세회피 등의 목적이 없으면 유효하여 해지에 따른 이전청구권을 가등기로 보전할 수 있다.","c":"중","v":1},"법무사2024_30-30-1":{"f":"甲이 소유권이전등기를 신청할 때에는 乙명의의 소유권이전등기의 말소신청을 단독으로 동시에 할 수 있으며, 등기관은 A 부동산 등기기록이 이기된 것인 경우 이기 전의 등기기록까지 조사하여 소유권이전등기의 말소 가능 여부(가처분등기에 우선하는 권리에 기한 것인지 여부)를 판단하여야 한다.","w":"가처분 이후 등기의 말소신청은 소유권이전등기신청과 동시에 하는 것이 원칙이지만, 동시에 하지 않았으면 가처분에 기한 이전등기였다는 소명자료를 붙여 다시 말소를 신청할 수 있다. 등기기록이 이기된 경우 등기관은 폐쇄등기기록까지 조사해 가처분에 우선하는 권리인지 판단한다(등기예규 제1690호).","c":"상","v":1},"법무사2024_30-30-3":{"f":"丙의 경매개시결정등기가 가처분등기보다 이후의 원인으로 마쳐진 경우에, 甲이 가처분에 기한 소유권이전등기만 신청하고 경매개시결정등기에 대한 말소신청을 동시에 하지 않았더라도 그 소유권이전등기가 가처분에 기한 것이라는 소명자료를 첨부하여 추후에 말소등기를 신청할 수 있다.","w":"가처분채권자가 소유권이전등기만 먼저 했더라도, 그 등기가 가처분에 기한 것이라는 소명자료를 붙여 가처분 이후의 등기 말소를 다시 신청할 수 있다(「처분금지가처분채권자가 가처분채무자를 등기의무자로 하여 소유권이전등기를 신청하는 경우의 업무처리지침」).","c":"상","v":1},"법무사2024_30-30-4":{"f":"등기관이 가처분채권자 甲의 단독신청에 의하여 가처분등기 이후의 등기를 말소하였을 때에는 직권으로 당해 가처분등기를 말소하여야 하고, 가처분등기 이후의 등기가 없는 경우로서 甲이 가처분채무자를 상대로 소유권이전등기만 하였을 때에도 등기관이 직권으로 당해 가처분등기를 말소한다.","w":"가처분등기 이후의 등기가 없어서 가처분채무자를 등기의무자로 하는 이전등기만 할 때에도 등기관이 직권으로 가처분등기를 말소한다(부동산등기법 제94조 제2항 후문). 법원의 촉탁을 기다리지 않는다.","c":"상","v":1},"법무사2024_30-30-5":{"f":"가처분채권자 甲이 가처분에 기한 것이라는 소명자료를 첨부하여 가처분채무자와 공동으로 소유권이전등기를 신청한 경우에도 가처분등기에 대항할 수 없는 권리에 관한 말소신청을 할 수 있으며, 말소된 권리의 등기명의인에게 말소등기통지를 하여야 한다.","w":"가처분채권자가 소명자료를 붙여 가처분채무자와 공동으로 이전등기를 신청하는 경우에도 가처분등기 이후의 등기 말소를 신청할 수 있다(등기예규 제1690호). 가처분 이후의 등기를 말소하면 등기관은 말소된 권리의 등기명의인에게 지체 없이 통지해야 하고 생략할 수 없다(부동산등기법 제94조 제3항).","c":"상","v":1},"법무사2025_31-20-5":{"f":"매각대금이 완납된 경우 경매개시결정등기의 말소등기는 집행법원의 촉탁에 따르며, 매각을 원인으로 한 소유권이전등기와 함께 이루어져야 하므로 이전등기를 하지 않고서는 경매개시결정등기만을 말소할 수 없다.","w":"경매개시결정등기의 말소는 매각에 따른 소유권이전등기 촉탁과 함께 이루어진다. 이전등기 없이 말소만 하는 것이 아니다.","c":"중","v":1},"법무사2026_32-19-2":{"f":"등기부상 1필지 토지의 특정된 일부분에 대한 처분금지가처분등기는 할 수 없으므로, 1필지 토지의 특정 일부분에 관한 소유권이전등기청구권을 보전하기 위하여는 바로 분할등기가 될 수 있다는 등 특별한 사정이 없으면 그 1필지 토지 전부에 대한 처분금지가처분결정에 기한 등기촉탁은 수리하여야 한다.","w":"1필지의 특정 일부에는 처분금지가처분등기를 할 수 없으므로, 바로 분할등기가 될 수 있는 등 특별한 사정이 없으면 그 1필지 전부에 대한 가처분등기를 할 수밖에 없다. 그 촉탁은 수리한다(등기예규 제881호).","c":"상","v":1},"법무사2026_32-25-5":{"f":"가압류 청구금액을 잘못 기재하여 이를 경정하는 경우 가압류등기 후 다른 등기권리자가 있더라도 그 권리자의 승낙서 또는 이에 대항할 수 있는 재판이 있음을 증명하는 정보를 첨부할 필요가 없다.","w":"가압류등기의 청구금액은 참고로 기록하는 사항이어서, 착오로 잘못 적은 것을 경정할 때 뒤의 등기권리자가 있어도 승낙서 등이 필요 없고 경정은 언제나 부기등기로 한다(「가압류기입등기시 청구금액 기재에 관한 사무처리지침」).","c":"상","v":1},"법무사2025_31-30-5":{"f":"소유권이전등기청구권보전 가등기에 의하여 본등기를 한 경우 가등기 후 본등기 전에 마쳐진 임의경매개시결정등기가 가등기 전에 마쳐진 전세권에 의한 등기인 경우에는 직권말소 대상이 아니다.","w":"가등기보다 앞선 권리에 기한 경매개시결정등기는 가등기에 대항할 수 있으므로 본등기를 해도 직권말소하지 않는다.","c":"상","v":1},"법무사2023_29-26-5":{"f":"선행 가처분과 후행 가처분의 피보전권리가 모두 소유권이전등기 말소등기청구권 및 근저당권설정등기 말소등기청구권인 경우, 확정판결을 받은 후행 가처분채권자가 말소등기신청을 할 때에는 선행 가처분채권자의 승낙 또는 이에 대항할 수 있는 재판의 등본을 첨부정보로 제공하여야 한다.","w":"선행 가처분채권자는 말소로 손해를 입을 우려가 있는 이해관계 있는 제3자여서 그의 승낙 또는 대항할 수 있는 재판의 등본이 필요하다.","c":"중","v":1},"법무사2016_22-26-3":{"f":"임의경매개시결정 등기촉탁이 있는 경우 등기기록에 위 개시결정에 기재된 소유자로부터 제3자로의 소유권이전등기의 변동사항이 발생하였더라도 등기관은 그 등기촉탁을 수리하여야 한다.","w":"임의경매개시결정등기는 경매개시결정 당시의 소유자에서 제3자로 소유권이전등기가 이루어졌더라도 수리한다.","c":"상","v":1},"법무사2017_23-29-2":{"f":"부동산에 대한 몰수보전등기가 마쳐진 후에 그 대상이 된 권리에 대한 이전등기 등의 신청이 있는 경우에도 등기관은 이를 각하하지 아니하고 수리한다.","w":"몰수보전등기는 처분 자체를 금지하는 것이 아니라 몰수 재판이 확정되면 그 처분을 대항할 수 없게 하는 것이어서 이전등기 신청을 각하하지 않는다.","c":"중","v":1},"법무사2023_29-13-5":{"f":"부동산에 대한 몰수보전등기가 마쳐진 후에 그 대상이 된 권리에 대한 이전등기 등의 신청이 있는 경우에도 등기관은 이를 각하하지 아니하고 수리한다.","w":"몰수보전등기는 처분을 금지하는 것이 아니라 몰수가 확정되면 그 처분을 대항할 수 없게 하는 것이어서 이전등기 신청을 각하하지 않는다.","c":"중","v":1},"법무사2020_26-08-2":{"f":"등기관이 지상권설정등기청구권보전 가등기에 의하여 지상권 설정의 본등기를 한 경우 가등기 후 본등기 전에 마쳐진 저당권설정등기는 직권말소의 대상이 되지 아니한다.","w":"지상권 설정의 본등기를 하면 가등기 후 본등기 전에 마쳐진 지상권, 지역권, 전세권, 임차권 설정등기는 직권말소 대상이지만 저당권설정등기는 아니다.","c":"상","v":1},"법무사2016_22-28-1":{"f":"보전처분 등기가 마쳐진 채무자의 부동산에 대하여 가압류, 가처분 등 보전처분, 강제집행 또는 담보권 실행을 위한 경매, 체납처분에 의한 압류 등의 등기촉탁이 있는 경우에도 등기관은 이를 수리하여야 한다.","w":"회생절차의 보전처분은 채무자의 행위를 제한하는 것이고 제3자의 권리행사를 막는 것이 아니어서, 그 등기가 있어도 가압류·경매·체납처분 압류 등의 촉탁은 수리한다(「채무자 회생 및 파산에 관한 법률에 따른 부동산 등의 등기사무처리지침」).","c":"상","v":1},"법무사2017_23-25-5":{"f":"관리인이 회생계획에 따라 채무자 명의의 부동산을 처분하고 그에 따른 등기를 신청하는 경우에는 법원의 허가서를 첨부할 필요가 없고 회생계획인가결정의 등본 또는 초본을 첨부한다.","w":"회생계획에 따른 처분이면 회생계획인가결정의 등본이나 초본을 붙인다. 법원의 허가서나 허가가 필요 없다는 증명서는 회생계획에 의하지 않고 처분한 경우에 붙인다(「채무자 회생 및 파산에 관한 법률에 따른 부동산 등의 등기사무처리지침」 제14조의2 제1항).","c":"상","v":1},"법무사2019_25-15-5":{"f":"관리인이 채무자 명의의 부동산을 처분하여 제3자 명의로의 소유권이전등기를 신청하는 때에는 보전처분의 등기 이후에 마쳐진 보전처분에 저촉되는 등기의 말소를 동시에 신청하여야 하고, 해당 보전처분의 등기는 법원사무관등의 촉탁에 의하여 말소한다.","w":"저촉되는 등기의 말소를 함께 신청해야 하는 것은 맞다. 다만 제3자 명의의 이전등기가 마쳐지면 보전처분등기는 등기관이 직권으로 지우는 것이 아니라 법원사무관등이 매각을 원인으로 말소를 촉탁한다(「채무자 회생 및 파산에 관한 법률에 따른 부동산 등의 등기사무처리지침」 제14조의2 제2항).","c":"상","v":1},"법무사2024_30-02-3":{"f":"관리인이 회생계획에 따라 채무자 명의의 부동산 등을 처분하고 그에 따른 등기를 신청하는 경우에는 회생계획인가결정의 등본 또는 초본을 그 신청서에 첨부하여야 한다.","w":"회생계획에 따른 처분이면 회생계획인가결정의 등본이나 초본을 붙인다. 법원의 허가서나 허가가 필요 없다는 증명서는 회생계획에 의하지 않고 처분한 경우에 붙인다(「채무자 회생 및 파산에 관한 법률에 따른 부동산 등의 등기사무처리지침」 제14조의2 제1항).","c":"상","v":1},"법무사2022_28-25-3":{"f":"회생절차개시결정의 등기가 된 채무자의 부동산에 관하여 파산선고의 등기, 회생절차개시의 등기의 촉탁이 있는 경우 등기관은 이를 각하하여야 한다.","w":"회생절차개시결정 등기가 있는 부동산에 대한 파산선고나 회생절차개시 촉탁은 중복되는 등기여서 각하한다.","c":"상","v":1},"법무사2022_28-20-2":{"f":"가처분의 피보전권리가 소유권 이외의 권리설정등기청구권으로서 소유명의인을 가처분채무자로 하는 경우에는 그 가처분등기를 등기기록 중 갑구에 한다.","w":"지상권 등 소유권 이외 권리의 설정등기청구권을 보전하는 가처분이라도 채무자가 소유명의인이면 소유권에 관한 사항을 적는 갑구에 가처분등기를 한다.","c":"상","v":1},"법무사2016_22-12-3":{"f":"허무인명의의 등기가 마쳐진 경우 진정한 소유자가 실제 등기행위를 한 자를 상대로 처분금지가처분의 결정을 받았다면 등기관은 그 가처분등기의 촉탁을 수리할 수 있다.","w":"허무인 명의 등기는 실제 등기행위자를 표상하는 등기로 보아, 실제 등기행위자를 상대로 받은 판결로 그 등기를 말소할 수 있다(「허무인 명의 등기의 말소에 관한 예규」). 같은 취지로 실제 등기행위자를 채무자로 한 처분금지가처분 촉탁도 수리한다.","c":"중","v":1},"법무사2016_22-27-4":{"f":"대지에 관하여 이미 근저당권이 설정되어 있는 상태에서 대지권의 등기를 하고 그 후에 구분건물에 관하여 동일 채권의 담보를 위한 근저당권을 추가 설정하려는 경우에는 구분건물과 대지권을 일체로 하여 그에 관한 추가 근저당권설정의 등기를 신청할 수 있다.","w":"대지에 저당권이 설정된 상태에서 대지권등기를 하고 그 뒤 구분건물에 같은 채권을 위한 저당권을 추가설정하려면 구분건물과 대지권을 일체로 하여 추가저당권설정등기를 신청할 수 있다(등기예규 제1470호).","c":"상","v":1},"법무사2017_23-21-1":{"f":"등기관은 신청에 따라 부동산 표시에 관한 등기를 하는 경우 토지나 건물 등기기록의 표제부에 접수연월일을 기록한다.","w":"신청에 따라 부동산 표시에 관한 등기를 하면 표제부에 표시번호, 접수연월일 등을 기록한다(부동산등기규칙 제13조 제1항).","c":"상","v":1},"법무사2020_26-05-1":{"f":"토지의 소유명의인 甲과 그 토지 위에 소재하는 대지권 없는 구분건물의 소유명의인 乙이 위 토지 및 구분건물에 대하여 신탁행위로 인한 소유권이전등기 및 신탁등기를 각 마친 경우, 수탁자가 동일인이더라도 신탁된 토지를 대지권의 목적으로 하여 위 구분건물을 위한 대지권등기를 신청할 수 없다.","w":"토지와 구분건물이 서로 다른 위탁자로부터 따로 신탁되어 각각 별개의 신탁재산이므로, 수탁자가 같아도 그 토지를 구분건물의 대지권으로 등기할 수 없다.","c":"중","v":1},"법무사2022_28-24-5":{"f":"등기기록에 대지권이라는 뜻의 등기를 할 때에 대지권의 목적인 토지의 관할이 다른 등기소에 속할 경우에는 그 토지 관할 등기소의 등기관이 대지권이라는 뜻의 등기를 한다.","w":"(2024 개정 전 기준 X. 현행은 부동산등기법 제7조의2 제2항과 부동산등기규칙 제163조의3 제4호에 따라 대지권등기를 처리한 등기소의 등기관이 다른 등기소 관할 토지에 대지권이라는 뜻의 등기까지 함께 한다.) 개정 전에는 토지 관할 등기소에 통지하고 그 등기소 등기관이 대지권이라는 뜻을 기록했다(구 부동산등기규칙 제89조 제2항).","c":"상","v":1,"old":1,"ow":"(2024 개정 전 기준 X. 현행은 부동산등기법 제7조의2 제2항과 부동산등기규칙 제163조의3 제4호에 따라 대지권등기를 처리한 등기소의 등기관이 다른 등기소 관할 토지에 대지권이라는 뜻의 등기까지 함께 한다.) 개정 전에는 토지 관할 등기소에 통지하고 그 등기소 등기관이 대지권이라는 뜻을 기록했다(구 부동산등기규칙 제89조 제2항)."},"법무사2025_31-04-2":{"f":"甲, 乙, 丙이 대지를 각 4/8, 3/8, 1/8의 지분으로 공유하면서 그 지상에 총 3개 호수의 집합건물을 신축하여 구분건물을 각 단독소유하는 경우에 대지권등기를 할 때, 위 공유지분과 달리 각 구분건물의 전유면적 비율에 따라 대지권 비율을 정하거나 규약을 첨부하여 대지권 비율을 정하여 대지권등기를 할 수 없다.","w":"대지권 비율은 대지의 공유지분과 일치해야 한다. 전유면적 비율이나 규약으로 공유지분과 다르게 정하여 대지권등기를 할 수 없다.","c":"중","v":1},"법무사2022_28-12-2":{"f":"멸실된 건물이 근저당권 등 제3자의 권리의 목적이 된 경우라도 멸실된 사실이 건축물대장에 기록되어 있다면 멸실등기를 신청할 때에 근저당권자 등의 승낙이 있음을 증명하는 정보를 제공할 필요가 없다.","w":"건축물대장에 멸실 사실이 기록되어 있으면 근저당권자의 승낙 없이도 멸실등기를 신청할 수 있다.","c":"상","v":1},"법무사2024_30-06-2":{"f":"건축물대장상 합병이 이루어지고 합병등기를 하기 전에 합병된 건물의 소유자가 달라지거나 건물합병의 제한사유가 있는 경우에는 합병 후의 건물을 공유로 하고 합병제한사유에 해당하는 권리에 관한 등기의 목적을 합병 후의 공유지분으로 변경하는 등기를 할 수 없다.","w":"대장상 합병 후 합병등기 전에 제한사유가 생긴 경우 공유지분으로 바꾸어 합병등기를 할 수 있게 한 특례는 토지 합필에만 있다(부동산등기법 제38조). 건물에는 이런 특례가 없다.","c":"중","v":1},"법무사2025_31-19-3":{"f":"소유권이 대지권인 경우에 대지권이 등기된 구분건물 또는 대지권이라는 뜻의 등기가 되어 있는 토지의 등기기록에는 소유권이전등기청구권 또는 저당권설정등기청구권을 보전하기 위한 가등기는 할 수 없고, 토지에 대한 가압류의 등기도 할 수 없다.","w":"대지권이라는 뜻의 등기가 된 토지는 건물과 따로 처분할 수 없다. 가등기뿐 아니라 토지에 대한 가압류도 허용되지 않는다.","c":"중","v":1},"법무사2016_22-10-4":{"f":"공용부분이라는 뜻을 정한 규약을 폐지한 경우에 공용부분의 취득자는 지체 없이 소유권보존등기를 신청하여야 한다.","w":"공용부분이라는 뜻을 정한 규약을 폐지하면 그 공용부분의 취득자는 지체 없이 소유권보존등기를 신청해야 한다(부동산등기법 제47조 제2항). 공용부분이라는 뜻의 등기를 할 때 갑구·을구의 소유권 등이 말소되었으므로 이전등기가 아니라 보존등기를 한다.","c":"상","v":1},"법무사2017_23-26-5":{"f":"건물 표제부에 있는 토지 등기기록에 별도의 등기가 있다는 뜻의 기록은 그 별도등기 기록의 전제가 된 등기가 말소되었을 때 등기관이 말소한다.","w":"별도등기가 있다는 뜻의 기록은 그 전제가 된 등기가 말소되면 등기관이 함께 말소한다(부동산등기규칙 제90조 제3항). 당사자가 그 기록의 말소를 따로 신청하는 것이 아니다.","c":"상","v":1},"법무사2026_32-07-4":{"f":"대지권이 소유권인 경우 전유부분과 대지사용권 중 일방만을 처분하는 것이 허용되지 않으므로 토지만을 목적으로 하는 지상권설정은 허용되지 않으나, 전유부분에 대한 임차권 또는 전세권의 설정은 허용된다.","w":"전유부분에 대한 전세권이나 임차권은 대지권 처분이 아니라 건물의 사용 문제여서 설정할 수 있다. 금지되는 것은 토지만 따로 처분하는 행위이다.","c":"상","v":1},"법무사2025_31-28-2":{"f":"X 토지의 분할로 인하여 분할 전 설정되어 있던 지상권이 분할 후 Y 토지에 전사된 후 Y 토지의 지상권을 구분지상권으로 변경하기 위해서는 지상권자와 지상권설정자가 공동으로 변경등기를 신청하여야 한다.","w":"지상권을 구분지상권으로 바꾸는 것은 권리의 내용 변경이어서 지상권자와 설정자의 공동신청으로 한다.","c":"중","v":1},"법무사2025_31-28-3":{"f":"합필 대상 토지 중 일부 토지 등기기록에 요역지지역권의 등기가 있다면 그 토지에 대한 합필등기를 할 수 없고 모든 토지의 등기기록에 동일한 내용의 요역지지역권의 등기가 있는 경우에도 합필등기를 할 수 없다.","w":"요역지지역권이 있는 토지는 합필이 허용되는 등기의 범위(소유권, 지상권, 전세권, 임차권, 승역지지역권)에 들지 않아 합필할 수 없다.","c":"중","v":1},"법무사2025_31-28-4":{"f":"甲 소유의 X, Y 토지 중 X 토지의 저당권은 토지 전부를 목적으로 하고 있고 Y 토지의 저당권은 일부 지분만을 목적으로 하고 있는 경우에는 그 저당권의 등기원인 및 그 연월일과 접수번호가 동일하더라도 X 토지를 Y 토지에 합병하는 합필등기를 할 수 없다.","w":"저당권이 있는 토지끼리 합필하려면 목적과 내용이 같아야 한다. 한쪽은 전부, 다른 쪽은 일부 지분만을 목적으로 하면 접수번호가 같아도 합필할 수 없다.","c":"중","v":1},"법무사2025_31-28-5":{"f":"합필의 특례규정(부동산등기법 제38조)에 따른 합필등기 시 토지의 일부에 요역지지역권의 등기가 있는 경우에는 합필 후의 토지 전체를 위한 지역권으로 하는 합필등기를 신청하여야 한다.","w":"요역지지역권이 일부 토지에만 있는 경우 합필 후에는 토지 전체를 위한 지역권으로 해야 하므로 그 변경을 함께 신청한다.","c":"중","v":1},"법무사2021_27-25-4":{"f":"건물이 멸실된 경우에는 그 건물 소유권의 등기명의인은 그 사실이 있는 때부터 1개월 이내에 그 등기를 신청하여야 하며, 1개월 이내에 멸실등기를 신청하지 아니하면 그 건물대지의 소유자가 건물 소유권의 등기명의인을 대위하여 그 등기를 신청할 수 있다.","w":"건물 소유권의 등기명의인이 1개월 안에 멸실등기를 신청하지 않으면 건물대지의 소유자가 대위하여 신청할 수 있다(부동산등기법 제43조 제2항).","c":"상","v":1},"법무사2020_26-29-1":{"f":"건물이 멸실된 경우에는 그 건물 소유권의 등기명의인은 그 사실이 있는 때부터 1개월 이내에 그 등기를 신청하여야 하는데, 이 신청을 게을리 하더라도 과태료를 부과하지 않는다.","w":"멸실등기 신청을 게을리한 경우의 과태료 규정(부동산등기법 제112조)은 2017. 10. 13. 삭제되어 지금은 과태료를 부과하지 않는다.","c":"상","v":1},"법무사2023_29-09-1":{"f":"공용부분이라는 뜻의 등기는 규약에서 공용부분으로 정한 구분건물 또는 부속건물의 소유자가 신청하여야 하며, 미등기인 건물에 대하여는 소유권보존등기를 한 후에 공용부분이라는 뜻의 등기를 하여야 한다.","w":"미등기 건물은 소유권보존등기를 먼저 해야 공용부분이라는 뜻의 등기를 할 수 있다. 곧바로 공용부분 등기를 하지 못한다.","c":"상","v":1},"법무사2016_22-18-4":{"f":"1필의 토지의 특정 일부에 관하여 소유권이전등기를 명하는 판결이 있더라도 토지대장상 토지를 분할함이 없이는 분필등기를 할 수 없다.","w":"분필등기는 대장상 분할이 먼저 있어야 한다. 판결이 특정 일부의 이전을 명했어도 대장 분할 없이 등기부만 분필할 수 없다.","c":"상","v":1},"법무사2021_27-22-3":{"f":"甲 토지에 전세권설정등기가 마쳐져 있고 乙 토지에는 임차권설정등기가 마쳐져 있는 경우에도 甲 토지를 乙 토지에 합병하는 합필등기를 할 수 있다.","w":"합필하려는 토지에 소유권·지상권·전세권·임차권 및 승역지 지역권의 등기만 있으면 합필할 수 있다(부동산등기법 제37조 제1항 제1호). 전세권과 임차권이 서로 다른 토지에 있어도 합필 제한 사유가 아니다.","c":"상","v":1},"법무사2018_24-20-1":{"f":"합필하고자 하는 甲과 乙 토지 중 甲 토지에 환매특약의 등기가 있는 경우에는 합필등기를 신청할 수 없다.","w":"환매특약의 등기가 있는 토지는 합필이 허용되는 등기의 범위에 들지 않아 합필할 수 없다.","c":"중","v":1},"법무사2018_24-20-2":{"f":"甲 토지에 저당권설정등기를 한 후 동일한 채권에 대하여 乙 토지에 추가로 저당권설정등기를 한 경우는 합필등기를 할 수 없다.","w":"추가 설정된 저당권은 등기원인과 접수번호가 달라 합필 요건(동일한 등기원인과 접수번호)을 충족하지 못한다.","c":"상","v":1},"법무사2018_24-20-4":{"f":"甲과 乙 토지가 대장상 합병이 된 후에 甲 토지에 대하여 소유권이전등기가 마쳐진 경우에는 이해관계인의 승낙이 있으면 합필등기를 신청할 수 있다.","w":"대장상 합병을 마친 뒤 합필등기 전에 어느 토지에 소유권이전등기가 되었더라도 이해관계인의 승낙이 있으면 소유권의 등기명의인들이 공유로 하는 합필등기를 신청할 수 있다(부동산등기법 제38조 제1항).","c":"상","v":1},"법무사2018_24-20-5":{"f":"甲과 乙 토지가 대장상 합병이 된 후에 甲 토지에 대하여 가압류가 마쳐진 경우에는 이해관계인의 승낙이 있으면 합필등기를 신청할 수 있다.","w":"대장상 합병 뒤 합필등기 전에 어느 토지에 가압류처럼 합필 제한 사유가 되는 등기가 되었더라도 이해관계인의 승낙이 있으면 합필등기를 신청할 수 있다(부동산등기법 제38조 제2항).","c":"상","v":1},"법무사2019_25-03-3":{"f":"공유토지분할에 관한 특례법 제14조 제5항 및 제37조 제3항의 규정에 의한 합병의 등기를 소관청이 촉탁하는 경우에는 그 합필 전 토지의 공유지분에 대하여 서로 다른 근저당권이 설정되어 있다면 그 근저당권은 분할조서의 확정에 의하여 그 공유자가 취득하는 토지부분에 집중하여 존속하므로 소관청은 합병의 등기를 촉탁할 수 있다.","w":"특례법에 따른 합병에서는 근저당권이 공유자가 취득하는 토지부분에 집중되므로 합병 제한사유가 되지 않는다. 소관청이 합병의 등기를 촉탁할 수 있다.","c":"중","v":1},"법무사2016_22-22-3":{"f":"신탁법 제3조 제1항 제3호에 따라 신탁의 목적, 신탁재산, 수익자 등을 특정하고 자신을 수탁자로 정한 위탁자의 선언에 의한 신탁등기를 신청하는 경우에는 공익신탁을 제외하고는 신탁설정에 관한 공정증서를 첨부정보로서 제공하여야 한다.","w":"위탁자의 선언에 의한 신탁등기에는 신탁설정에 관한 공정증서를 첨부하지만, 공익신탁은 제외된다(부동산등기규칙 제139조의2 제1항).","c":"상","v":1},"법무사2018_24-19-4":{"f":"공동상속인 중 일부 상속인이 상속을 포기하는 경우에는 상속포기신고 수리증명서를 제공하여야 한다.","w":"상속포기는 신고를 접수하는 것만으로 효력이 생기지 않고 가정법원이 신고를 수리해야 한다. 수리를 증명하는 서면을 제공해야 한다.","c":"중","v":1},"법무사2019_25-20-1":{"f":"학교법인의 기본재산에 대하여 담보로 제공할 당시에 관할청의 허가를 받았다면 저당권의 실행으로 매각이 될 때에는 다시 관할청의 허가를 받을 필요가 없다.","w":"담보 제공 단계에서 허가를 받았으면 경매에 의한 매각은 그 연장이므로 다시 허가받지 않는다.","c":"상","v":1},"법무사2020_26-02-2":{"f":"신탁법 제3조 제5항에 따른 재신탁등기를 신청하는 경우에는 수익자의 동의가 있음을 증명하는 정보(인감증명 포함)를 첨부정보로서 제공하여야 한다.","w":"재신탁은 수탁자가 수익자의 동의를 받아 할 수 있으므로(신탁법 제3조 제5항), 재신탁등기에는 수익자의 동의를 증명하는 정보(인감증명 포함)를 낸다. 위탁자의 동의가 아니다.","c":"상","v":1},"법무사2024_30-24-5":{"f":"신탁원부상 신탁조항에 수익자변경권이 위탁자 및 수탁자에게 유보되어 있다는 취지가 기재되어 있다면 수탁자가 수익자의 변경으로 신탁원부 기록의 변경등기를 신청하는 경우 수익자변경을 증명하는 정보 이외에 종전 수익자의 승낙이 있음을 증명하는 정보를 제공할 필요는 없다.","w":"수익자 변경권이 위탁자와 수탁자에게 유보되어 있으면 그 권한으로 변경할 수 있으므로 종전 수익자의 승낙은 필요 없다.","c":"상","v":1},"법무사2026_32-26-2":{"f":"상속인이 한정승인 또는 포기를 할 수 있는 기간 내에도 상속인의 채권자는 대위에 의한 상속등기를 신청할 수 있다.","w":"상속등기의 대위신청은 상속인의 한정승인·포기 기간이 끝나기를 기다릴 필요가 없다.","c":"중","v":1},"법무사2026_32-30-3":{"f":"여러 명의 상속인이 있는 경우에는 공동상속인 전원을 등기권리자로 기재하고 각 상속인별로 상속지분을 반드시 기재하여야 한다. 상속분이 같을 때에도 각 상속인별 상속지분의 기재를 생략할 수 없다.","w":"공유 등기에서는 지분을 반드시 적어야 하므로 상속분이 같더라도 각 상속인의 지분을 기재해야 한다.","c":"상","v":1},"법무사2018_24-11-4":{"f":"공익법인 아닌 재단법인이 기본재산인 부동산에 관하여 지상권설정등기를 신청할 때에는 주무관청의 허가를 증명하는 서면을 첨부할 필요가 없다.","w":"민법상 재단법인은 기본재산의 매매·증여 등 처분을 원인으로 한 소유권이전등기에 주무관청 허가서가 필요하다. 지상권·근저당권 같은 제한물권 설정등기에도 허가서를 요구하는 것은 공익법인의 경우이다(「민법상 법인의 부동산 취득과 처분 등에 따른 등기예규」).","c":"중","v":1},"법무사2020_26-30-2":{"f":"대표자 또는 관리인을 증명하는 서면은 정관 기타의 규약에서 정한 방법에 의하여 대표자 또는 관리인으로 선임되었음을 증명하는 서면을 제출하며, 부동산등기용등록번호대장이나 기타단체등록증명서는 대표자 또는 관리인을 증명하는 서면으로 제출할 수 없다.","w":"부동산등기용등록번호대장이나 기타단체등록증명서는 대표자나 관리인을 증명하는 서면으로 낼 수 없다. 정관 등 규약에서 정한 방법으로 선임되었음을 증명하는 서면을 낸다(등기예규 제1621호).","c":"상","v":1},"법무사2018_24-30-2":{"f":"법인 아닌 사단이나 재단은 법인등기와 같은 공시제도가 없으므로 그 대표자나 관리인을 분명히 하기 위하여 대표자나 관리인의 성명, 주소 및 주민등록번호를 등기사항으로 하고 있다.","w":"법인 아닌 사단·재단 명의로 등기할 때에는 대표자나 관리인의 성명, 주소와 함께 주민등록번호도 기록한다(부동산등기법 제48조 제3항).","c":"상","v":1},"법무사2018_24-30-3":{"f":"총유물의 관리 및 처분은 사원총회의 결의에 의하므로, 법인 아닌 사단이 그 소유의 부동산을 처분하고 등기의무자로서 그 등기를 신청하는 경우에는 사원총회 결의서를 첨부하여야 하나, 정관 등에서 달리 정하고 있는 경우에는 그에 따른다.","w":"법인 아닌 사단이 등기의무자로서 신청할 때에는 사원총회 결의서를 첨부하지만, 정관 등 규약으로 처분에 그 결의가 필요 없다고 정했으면 첨부하지 않는다(부동산등기규칙 제48조 제3호, 등기예규 제1621호).","c":"상","v":1},"법무사2018_24-30-4":{"f":"법인 아닌 사단에 대하여도 임시이사의 선임에 관한 민법 제63조의 규정이 유추적용된다.","w":"대표자가 없는 경우 임시이사를 선임하는 민법 제63조는 법인 아닌 사단에도 유추적용된다는 것이 판례이다.","c":"중","v":1},"법무사2018_24-30-5":{"f":"법인 아닌 사단이 근저당권설정등기의 채무자인 경우에는 그 부동산등기용등록번호나 대표자에 관한 사항을 등기하지 아니한다.","w":"근저당권의 채무자는 명칭과 주소만 기록한다. 법인 아닌 사단이 채무자여도 등록번호나 대표자에 관한 사항은 등기하지 않는다.","c":"중","v":1},"법무사2017_23-01-4":{"f":"폐쇄된 법인 등기기록에 청산인 등기가 되어 있는 경우에 등기의무자로서의 청산인은 그 폐쇄된 법인 등기사항증명서를 첨부하여 부동산등기신청을 할 수 있고, 인감증명의 제출이 필요한 경우에는 인감증명법에 의한 청산인의 개인인감을 첨부할 수 있다.","w":"폐쇄된 법인등기부에 청산인 등기가 있으면 청산인은 개인인감증명을 낼 수 있다. 법인인감인 청산인의 인감을 내야 하는 것은 등기부가 폐쇄되지 않은 경우나 폐쇄된 등기부를 부활해 청산인 등기를 한 경우이다(「청산법인의 부동산등기신청절차에 관한 업무처리지침」).","c":"상","v":1},"법무사2021_27-17-1":{"f":"법인의 대표이사가 등기신청을 자격자대리인에게 위임한 후 그 등기신청 전에 대표이사가 변경된 경우에도 자격자대리인의 등기신청에 관한 대리권한은 소멸하지 않는다.","w":"위임한 주체는 법인이고 대표이사는 그 대표 기관일 뿐이다. 대표이사가 바뀌어도 이미 한 위임의 대리권은 소멸하지 않는다.","c":"상","v":1},"법무사2024_30-25-3":{"f":"甲 회사가 乙 회사로 흡수합병된 후 乙 회사가 乙 회사의 일부를 분할하여 丙 회사를 설립한 경우, 분할계획서에 분할로 인하여 丙 회사로 이전될 재산으로 기재된 甲 회사 명의의 소유권이전등기는 먼저 乙 회사 명의로 합병을 원인으로 한 이전등기를 마친 뒤에 丙 회사가 신청할 수 있다.","w":"합병으로 甲 회사의 재산은 乙 회사에 포괄승계된다. 乙 명의로 합병을 원인으로 한 이전등기를 먼저 마쳐야 그 뒤 분할로 丙에게 이전할 수 있다.","c":"중","v":1},"법무사2021_27-16-5":{"f":"대표자 또는 관리인을 증명하는 서면 등이 결의서로써 그 결의서 작성 당시에 인감이 날인되고 그 인감증명서가 첨부되어 있다면, 이와는 별도로 2인 이상의 성년자가 사실과 상위함이 없다는 취지와 성명 기재 및 인감 날인 등을 할 필요가 없다.","w":"결의서에 인감이 날인되어 있어도 인감증명서까지 첨부되어야 별도 확인서면을 생략할 수 있다. 인감 날인만으로는 부족하다.","c":"중","v":1},"법무사2025_31-09-4":{"f":"상속재산 협의분할에 따라 상속등기를 마친 후에 그 협의를 해제하고 이를 원인으로 상속등기의 경정등기를 신청하는 경우에는 다시 새로운 협의분할을 한 경우를 포함하여 부동산의 관할 등기소가 아닌 등기소도 그 신청에 따른 등기사무를 담당할 수 있다.","w":"협의분할에 따른 상속등기 후 협의를 해제한 경우는 다시 새로운 협의분할을 한 경우까지 포함해 관할 외 등기소에 신청할 수 있다(부동산등기규칙 제164조 제1항 제2호 나목).","c":"상","v":1},"법무사2023_29-02-4":{"f":"상속재산분할협의서를 작성하는데 있어서 친권자와 미성년자인 자 1인이 공동상속인인 경우 친권자가 상속재산을 전혀 취득하지 아니하는 경우에도 미성년자를 위한 특별대리인을 선임하여야 한다.","w":"상속재산 분할협의는 이해상반 여부를 형식적으로 판단하여 친권자와 미성년자 사이에는 항상 이해상반 행위로 본다. 친권자가 재산을 취득하지 않아도 특별대리인이 필요하다.","c":"중","v":1},"법무사2019_25-25-1":{"f":"상속재산분할심판이 확정된 경우에는 법정상속분에 따른 상속등기를 먼저 할 필요 없이 심판정본에 따라 상속등기를 신청할 수 있다.","w":"분할심판은 상속 개시 때로 소급해서 효력이 생기므로 법정상속분 등기를 선행하지 않고 심판에 따른 상속등기를 바로 할 수 있다.","c":"중","v":1},"법무사2017_23-15-1":{"f":"수탁자는 신탁행위로 달리 정한 바가 없으면 신탁 목적의 달성을 위하여 필요한 경우에는 수익자의 동의를 받아 신탁재산을 재신탁할 수 있다.","w":"수탁자는 신탁행위로 달리 정하지 않았으면 신탁 목적 달성에 필요한 경우 수익자의 동의를 받아 재신탁할 수 있다(신탁법 제3조 제5항). 위탁자의 동의가 아니다.","c":"상","v":1},"법무사2022_28-27-2":{"f":"여러 명의 수탁자 중 1인이 신탁행위로 정한 임무종료사유, 사임, 자격상실의 사유로 임무가 종료된 경우에는 나머지 수탁자와 임무가 종료된 수탁자가 공동으로 합유명의인 변경등기를 신청한다.","w":"임무종료사유·사임·자격상실로 임무가 끝난 경우는 나머지 수탁자와 임무가 끝난 수탁자의 공동신청이다. 나머지 수탁자의 단독신청은 사망·파산·해산 등 부동산등기법 제83조의 사유로 임무가 끝난 경우이다(「신탁등기사무처리에 관한 예규」, 부동산등기법 제84조 제2항).","c":"상","v":1},"법무사2019_25-23-2":{"f":"신탁등기가 마쳐진 부동산에 대하여 수탁자를 등기의무자로 하는 등기의 신청이 신탁목적에 부합하지 않는다면 위탁자의 승낙서를 제공하여 신청한 것이라도 이를 수리할 수 없다.","w":"신탁등기가 된 부동산에 수탁자를 등기의무자로 하는 등기신청이 있으면 등기관은 신탁목적에 반하는지 심사하고, 반하면 수리하지 않는다(등기예규 제1799호). 위탁자의 승낙서를 붙였다고 해서 달라지지 않는다.","c":"중","v":1},"법무사2020_26-24-5":{"f":"포괄적 수증자의 소유권보존등기 및 유증으로 인한 소유권이전등기 신청이 상속인의 유류분을 침해하는 경우에도 등기관은 이를 수리하여야 한다.","w":"유류분 침해 여부는 실체관계 판단이어서 등기관이 심사하지 않는다. 유류분을 침해하는 유증이라도 등기신청은 수리한다(등기예규 제1512호).","c":"상","v":1},"법무사2021_27-03-4":{"f":"유증을 등기원인으로 하는 소유권이전등기는 수증자를 등기권리자, 유언집행자를 등기의무자로 하여 공동으로 신청하여야 하며, 공정증서에 의한 유언인 경우에도 마찬가지이다.","w":"유증을 원인으로 한 소유권이전등기는 포괄유증이든 특정유증이든 수증자를 등기권리자, 유언집행자 또는 상속인을 등기의무자로 하여 공동으로 신청한다(등기예규 제1512호). 공정증서 유언이라고 해서 어느 한쪽의 단독신청이 허용되지 않는다.","c":"상","v":1},"법무사2026_32-01-3":{"f":"포괄적 수증자의 소유권보존등기 및 유증으로 인한 소유권이전등기 신청이 상속인의 유류분을 침해하는 내용이라도 등기관은 이를 수리하여야 한다.","w":"등기관은 유류분 침해 여부를 심사할 수 없다.","c":"상","v":1},"법무사2020_26-06-4":{"f":"전통사찰 소유의 전통사찰보존지에 대한 시효취득을 원인으로 한 소유권이전등기를 신청하는 경우에는 문화체육관광부장관의 허가를 증명하는 정보를 첨부정보로서 제공할 필요가 없다.","w":"허가가 필요한 것은 증여 등 법률행위에 의한 처분이다. 시효취득은 법률에 따른 취득이어서 허가를 요하지 않는다.","c":"상","v":1},"법무사2023_29-05-4":{"f":"청산법인이 등기의무자인 때에 폐쇄된 법인등기기록에 청산인 등기가 되어 있는 경우에는 법인등기기록을 부활할 필요 없이 폐쇄된 등기기록의 사항증명서를 첨부하고, 인감증명의 제출이 필요한 경우에는 인감증명법에 의한 청산인의 개인인감을 첨부할 수 있다.","w":"폐쇄된 법인등기기록에 청산인 등기가 되어 있으면 그 폐쇄 등기사항증명서를 청산인임을 증명하는 서면으로 내면 되고 부활할 필요가 없다. 인감증명이 필요하면 청산인의 개인인감을 첨부할 수 있다(등기예규 제1087호).","c":"상","v":1},"법무사2022_28-07-1":{"f":"공동상속인(甲, 乙, 丙, 丁, 戊)의 명의로 법정상속등기가 마쳐진 이후 경매절차에 의하여 공동상속인 중 1인(甲)의 지분이 나머지 공동상속인 중 1인(乙)에게 이전된 경우에는 종전 공동상속인 전원이 이 재산에 대한 협의분할을 하고 이를 등기원인으로 하여 소유권경정등기를 신청할 수 없다.","w":"경매로 甲의 지분이 이미 처분되어 상속재산이 달라졌으므로 공동상속인 전원이 협의분할을 해도 경정등기를 할 수 없다.","c":"중","v":1},"법무사2017_23-05-3":{"f":"도시개발법에 의한 환지처분의 공고가 있으면 종전 토지에 대한 다른 등기를 할 수 없다.","w":"환지처분 공고가 있으면 환지등기가 마쳐질 때까지 종전 토지에 관한 다른 등기를 할 수 없고, 경매개시결정등기라는 예외는 인정되지 않는다.","c":"중","v":1},"법무사2018_24-09-1":{"f":"정비사업시행자는 그 사업시행을 위하여 필요한 때에는 소유권보존등기 또는 상속에 의한 소유권이전등기 등을 각 해당 등기의 신청권자를 대위하여 신청할 수 있는데, 이때에는 사업시행계획 인가를 증명하는 서면을 첨부하여야 한다.","w":"정비사업시행자는 사업시행에 필요하면 소유권보존등기, 상속을 원인으로 한 소유권이전등기 등을 해당 신청권자를 대위하여 신청할 수 있다.","c":"하","v":1},"법무사2021_27-14-4":{"f":"종전 모든 토지의 등기기록에 등기원인 및 그 연월일과 접수번호가 같은 저당권 또는 근저당권의 등기가 있는 경우에 그 등기는 새로 조성된 토지에 관한 소유권보존등기와 함께 1건의 신청정보로 일괄하여 신청할 수 없고 별도로 신청한다.","w":"1건으로 일괄 신청하는 것은 신탁등기와 주택법상 금지사항 부기등기이다. 저당권과 근저당권은 소유권보존등기와 별개의 신청정보로 신청한다.","c":"중","v":1},"법무사2021_27-23-3":{"f":"주소 변경에 따라 등기명의인표시변경등기를 서면에 의한 방문신청으로 하는 경우에도 등기관이 행정정보 공동이용을 통하여 주소정보를 확인할 수 있어 신청인에게 그 제공을 면제할 수 있다.","w":"주소를 증명하는 정보는 행정정보 공동이용으로 확인할 수 있으면 신청 방식과 관계없이 제공을 면제한다.","c":"중","v":1},"법무사2022_28-13-5":{"f":"전자신청에 대한 각하 결정의 고지는 전산정보처리조직을 이용하여 전자우편의 방법으로 할 수 있다.","w":"전자신청의 각하결정은 전자우편으로 고지할 수 있으나, 반드시 전자우편으로만 해야 하는 것은 아니다.","c":"중","v":1},"법무사2025_31-11-3":{"f":"등기의무자가 외국인인 경우에는 주소 변경 사실이 확인되더라도 대법원규칙이 정하는 동일성 인정의 특례가 적용되지 않아 부동산등기법 제29조 제7호에 따라 신청을 각하한다.","w":"주민등록번호는 같고 주소만 다를 때 주소변경 사실이 확인되면 각하하지 않는 특례는 등기의무자가 외국인, 국내에 영업소 등기를 하지 않은 외국법인, 법인 아닌 사단·재단이면 적용하지 않는다(부동산등기규칙 제52조의2 제2항).","c":"상","v":1},"법무사2025_31-18-1":{"f":"국가가 납세담보를 위하여 저당권설정등기를 경료한 후 납세의무자가 세금을 납부함에 따라 해당 저당권설정등기의 말소등기를 촉탁하는 경우에는 등기신청수수료를 납부하여야 한다.","w":"국가의 말소 촉탁 중 수수료가 면제되는 것은 국세압류등기나 공매공고등기처럼 국가가 공권력의 주체로서 촉탁한 등기의 말소이다(「등기신청수수료 징수에 관한 예규」). 납세담보 저당권의 말소 촉탁은 여기에 들지 않는다.","c":"중","v":1},"법무사2025_31-18-2":{"f":"부동산표시변경 및 경정등기 신청의 경우에는 등기신청수수료를 납부하지 않는다.","w":"부동산표시의 변경·경정등기는 등기신청수수료를 받지 않는 등기이다(「등기신청수수료 징수에 관한 예규」).","c":"상","v":1},"법무사2025_31-18-4":{"f":"국가가 국세압류등기의 말소를 촉탁하는 경우에는 등기신청수수료를 납부하지 않는다.","w":"국가가 공권력의 주체로서 촉탁한 등기의 말소(국세압류등기의 말소, 공매공고등기의 말소)는 수수료 면제 대상이다(「등기신청수수료 징수에 관한 예규」).","c":"상","v":1},"법무사2025_31-29-1":{"f":"등기관의 결정 또는 처분에 이의가 있는 자는 그 결정 또는 처분을 한 등기관이 속한 지방법원에 이의신청을 할 수 있다.","w":"이의신청의 관할은 부동산 소재지 법원이 아니라 그 결정·처분을 한 등기관이 속한 지방법원이다(부동산등기법 제100조).","c":"상","v":1},"법무사2018_24-26-3":{"f":"한 필지의 공유토지가 그 일부 지분은 구분건물의 대지권으로서 구분건물 소유자에게, 나머지 지분은 그 밖의 자에게 속하는 경우에도 특례법에 따른 분할을 할 수 있다.","w":"이런 토지에 대해 분할개시등기 촉탁이 있으면 수리한다(「공유토지분할에 관한 특례법 시행에 따른 등기사무처리지침」 제4조 제1항).","c":"상","v":1},"법무사2022_28-03-1":{"f":"“이왕직”, “창덕궁”, “이왕직장관” 소유명의로 등기된 부동산에 대해서는 관리청지정서를 첨부정보로서 제공하여 “1963. 2. 9. 승계”를 원인으로 “국, 관리청 ○○부”로의 소유권이전등기를 촉탁하면 “국” 명의로의 소유권이전등기와 동시에 관리청 명칭도 첨기등기한다.","w":"이왕직 등 명의의 부동산은 1963. 2. 9. 승계를 원인으로 한 소유권이전등기를 촉탁한다. 등기명의인표시변경등기로 처리하는 것은 조선총독부 명의 부동산이다(「국유재산의 관리청 명칭 첨기등기에 관한 예규」).","c":"상","v":1},"법무사2026_32-10-1":{"f":"미등기 상태의 종전 토지에 대하여 환지를 교부하는 경우 환지계획서에 종전 토지대장상 최초의 소유자로부터 이전등록을 받은 자가 환지의 소유자로 기재되어 있다면 사업시행자는 해당 환지에 대하여 소유권보존등기를 촉탁할 수 없다.","w":"환지에 대한 소유권보존등기는 종전 토지의 대장상 소유자로 환지계획서에 기재된 경우에 촉탁한다. 이전등록을 받은 자는 대장상 최초 소유자가 아니다.","c":"중","v":1},"법무사2023_29-27-1":{"f":"사업시행자는 사업시행인가 후에 사업시행을 위하여 환지계획인가의 고시 전이라도 종전 토지에 관한 토지 표시나 등기명의인 표시의 변경 및 경정등기를 대위하여 촉탁할 수 있고, 대위등기를 촉탁하는 경우 등기원인 또는 등기목적이 동일하지 아니한 경우에도 하나의 촉탁정보로 일괄하여 촉탁할 수 있다.","w":"대위촉탁은 등기원인이나 목적이 서로 달라도 하나의 촉탁정보로 일괄해서 할 수 있다.","c":"중","v":1},"법무사2024_30-07-1":{"f":"정비사업시행자(이하 “시행자”라 한다)는 그 사업시행을 위하여 신청권자를 대위하여 부동산의 표시변경(경정)등기와 등기명의인의 표시변경(경정)등기를 신청할 수 있으며, 등기원인 또는 등기의 목적이 동일하지 아니하더라도 일괄 신청할 수 있다.","w":"시행자의 대위신청은 등기원인이나 목적이 같지 않아도 일괄 신청할 수 있다.","c":"중","v":1},"법무사2024_30-07-2":{"f":"시행자로부터 이전고시를 통지받은 등기관은 대지 및 건축물에 관한 등기가 있을 때까지는 권리에 관한 등기뿐만 아니라 표시에 관한 등기도 하여서는 아니 되며, 이에 위반한 등기는 부동산등기법 제58조를 적용하여 직권으로 말소한다.","w":"이전고시 통지 뒤에는 대지와 건축물에 관한 등기가 될 때까지 권리에 관한 등기뿐 아니라 표시에 관한 등기도 할 수 없다(「도시 및 주거환경정비 등기에 관한 업무처리지침」).","c":"상","v":1},"법무사2024_30-07-4":{"f":"등기관은 신청정보의 내용으로 제공된 사항이 첨부정보로 제공된 관리처분계획 및 그 인가를 증명하는 서면, 이전고시를 증명하는 서면의 내용과 일치하는지 여부를 심사하되, 종전 토지 및 건물의 등기기록상 등기사항과 일치하는지 여부는 심사하지 않는다.","w":"등기관의 심사 범위는 첨부정보와의 일치 여부이다. 종전 토지와 건물의 등기기록상 등기사항과의 일치 여부는 심사 대상이 아니다.","c":"중","v":1},"법무사2024_30-07-5":{"f":"담보권등에 관한 권리의 등기를 신청하는 경우에는 신청서에 ‘등기원인’으로 정비사업으로 인한 이전고시가 있었다는 취지를 기재하고, ‘그 연월일’은 이전고시가 있은 다음 날짜를 기재한다. 이 때 접수번호는 소유권보존등기와 별개로 부여한다.","w":"담보권등기는 소유권보존등기와 함께 신청하더라도 별개의 신청이어서 접수번호를 따로 부여한다.","c":"중","v":1},"법무사2020_26-21-1":{"f":"등기관이 새로 조성된 대지와 축조된 건축물에 대하여 소유권보존등기 및 담보권 등에 관한 권리의 등기를 실행할 때에 신청정보의 내용으로 제공된 사항이 첨부정보로 제공된 관리처분계획 및 그 인가를 증명하는 서면과 이전고시를 증명하는 서면의 내용과 일치하는지 여부만 심사하고 종전 토지 및 건물의 등기기록상 등기사항과 일치하는지 여부는 심사하지 않는다.","w":"심사 범위는 신청정보와 관리처분계획 및 이전고시를 증명하는 서면의 일치 여부이다. 종전 등기기록과의 대조는 하지 않는다.","c":"중","v":1},"법무사2025_31-29-2":{"f":"이의의 신청은 등기소에 이의신청서를 제출하거나 인터넷등기소를 통하여 이의신청정보를 보내는 방법으로 할 수 있고, 구술로는 할 수 없다.","w":"이의신청은 결정이나 처분을 한 등기관이 속한 등기소에 이의신청서를 내거나 전산정보처리조직을 이용해 이의신청정보를 보내는 방법으로 하고, 구술로는 할 수 없다(부동산등기법 제101조).","c":"상","v":1},"법무사2025_31-29-4":{"f":"등기신청의 각하결정에 대하여는 등기신청인인 등기권리자 및 등기의무자에 한하여 이의신청을 할 수 있고, 제3자는 이의신청을 할 수 없다.","w":"각하결정에 이의할 수 있는 사람은 등기를 신청한 당사자이다. 제3자는 이의신청 자격이 없다.","c":"상","v":1},"법무사2025_31-29-5":{"f":"이미 마쳐진 등기에 대하여 부동산등기법 제29조 제1호 또는 제2호의 사유로 이의한 경우 등기관은 그 이의가 이유 있다고 인정하면 부동산등기법 제58조의 절차를 거쳐 그 등기를 직권으로 말소한다.","w":"이미 마쳐진 등기는 제29조 제1호·제2호의 사유(관할 위반, 등기할 것이 아닌 때)가 있을 때에만 이의 대상이 되고 제58조 절차로 직권말소한다.","c":"상","v":1},"법무사2017_23-10-3":{"f":"등기관의 결정 또는 처분이 부당하여 이의신청을 하는 경우에는 결정 또는 처분 시를 기준으로 그 때까지 주장하거나 제출되지 아니한 사실이나 증거방법으로써 이의사유를 삼을 수 없다.","w":"새로운 사실이나 새로운 증거방법을 근거로 이의신청을 할 수 없다(부동산등기법 제102조). 새로운지 여부는 등기관이 결정이나 처분을 한 때를 기준으로 본다.","c":"상","v":1},"법무사2019_25-18-5":{"f":"등기신청에 대한 등기관의 각하결정에 대하여 관할 지방법원이 등기관에게 그 등기 실행을 명한 경우 이해관계인이 그 기록명령에 대하여 항고를 하더라도 집행정지의 효력이 없으므로, 해당 등기관은 기록명령에 따른 등기를 실행하여야 한다.","w":"기록명령에 대한 항고에는 집행정지의 효력이 없다. 등기관은 기록명령에 따라 등기를 실행한다.","c":"중","v":1},"법무사2023_29-06-2":{"f":"등기신청의 각하결정에 대하여는 등기신청인에 한하여 이의신청을 할 수 있고, 각하되지 않았다면 실행될 등기에 대한 이해관계 있는 제3자는 이의신청을 할 수 없다.","w":"각하결정에 이의하는 것은 신청인인 등기권리자와 등기의무자의 권리이며 제3자는 이의신청을 할 수 없다.","c":"상","v":1},"법무사2020_26-13-4":{"f":"채권자가 채무자를 대위하여 토지에 대한 소유권보존등기를 신청하는 경우 채권자가 취득세 또는 등록면허세를 납부하여야 하고, 국민주택채권도 매입하여야 한다.","w":"대위 보존등기는 채무자가 직접 신청하는 경우와 다르지 않아 채권자가 세금을 내고 토지이면 국민주택채권도 산다. 등록면허세 미납통지를 하고 채권 매입이 필요 없는 것은 처분제한 촉탁으로 등기관이 직권 보존등기를 한 경우이다(「등기신청시 납부할 취득세 및 등록면허세 등에 관한 예규」).","c":"상","v":1},"법무사2023_29-25-5":{"f":"법원사무관 등이 회생절차, 파산절차, 개인회생절차와 관련하여 보전처분의 등기 등을 촉탁하는 경우에는 등록면허세 및 등기신청수수료를 납부할 필요가 없다.","w":"채무자 회생 및 파산에 관한 법률에 따라 법원사무관 등이 촉탁하는 등기에는 등록면허세와 등기신청수수료가 면제된다.","c":"상","v":1},"법무사2025_31-18-3":{"f":"소유권이전등기와 동시에 신탁등기를 하는 경우 소유권이전등기의 신청수수료 이외에 신탁등기의 신청수수료를 별도로 납부하여야 한다.","w":"소유권이전등기와 동시에 신탁등기를 하는 경우에도 소유권이전등기 신청수수료와 별도로 신탁등기의 신청수수료를 낸다(등기예규 제1861호).","c":"상","v":1},"법무사2017_23-04-1":{"f":"등기할 것이 아닌 사건의 등기신청은 각하하여야 하지만 이미 등기가 마쳐졌다면 등기관은 부동산등기법 제58조의 절차에 따라 직권으로 말소하여야 한다.","w":"등기할 것이 아닌 사건이 이미 등기되었으면 등기관이 바로 지우지 않고, 등기권리자 등에게 1개월 이내의 기간을 정해 이의를 진술하지 않으면 말소한다는 뜻을 통지한 뒤 이의가 없으면 직권으로 말소한다(부동산등기법 제58조).","c":"상","v":1},"법무사2017_23-04-2":{"f":"각하결정을 한 이상 그 결정이 아직 고지되기 전에 보정이 되었더라도 각하결정의 효력에는 영향이 없다.","w":"등기신청이 즉일 보정되지 않아 각하결정을 했으면 그 결정을 고지하기 전에 보정되었더라도 이미 내린 각하결정을 없던 것으로 돌릴 수 없다(등기예규 제124호, 대법원 1968. 7. 8.자 67마300 결정).","c":"상","v":1},"법무사2017_23-04-3":{"f":"각하결정으로 등본을 교부하거나 송달할 때에는 등기신청서 이외의 첨부서류를 함께 교부하거나 송달하여야 한다.","w":"각하결정등본과 함께 돌려주는 것은 등기신청서를 뺀 첨부서류이다. 등기신청서는 돌려주지 않는다(「등기신청의 각하절차에 대한 예규」).","c":"상","v":1},"법무사2017_23-04-5":{"f":"","w":"신청정보와 등기원인을 증명하는 정보가 일치하지 않으면 부동산등기법 제29조 제8호의 각하사유가 된다.","c":"하","v":1},"법무사2026_32-24-3":{"f":"보정은 반드시 등기관의 면전에서 하여야 하며 보정을 위하여 신청서 또는 그 부속서류를 신청인에게 반환할 수 없다.","w":"보정은 반드시 등기관 앞에서 해야 하고, 보정을 위해 신청서나 부속서류를 신청인에게 돌려줄 수 없다(등기예규 제1839호).","c":"상","v":1},"법무사2017_23-06-2":{"f":"법인 아닌 사단이나 재단은 그 사단이나 재단의 명의로 전자신청을 할 수 없다.","w":"법인 아닌 사단이나 재단은 전자신청을 할 수 없다(부동산등기규칙 제67조 제1항 단서). 대표자나 관리인이 직접 하든 대리인에게 맡기든 마찬가지다.","c":"상","v":1},"법무사2022_28-10-2":{"f":"가등기에 의한 본등기를 하고 가등기와 본등기 사이에 이루어진 체납처분으로 인한 압류등기에 대하여 직권말소대상통지를 한 후 이의신청 기간이 지나지 않은 상태에서 본등기에 기초한 등기의 신청이나 촉탁이 있는 경우에는 “사건이 등기할 것이 아닌 때”에 해당하지 않는다.","w":"직권말소대상통지를 한 경우에는 이의신청기간이 지나지 않았더라도 본등기에 기초한 등기의 신청이나 촉탁을 수리한다(「가등기에 관한 업무처리지침」).","c":"상","v":1},"법무사2024_30-29-4":{"f":"등기를 신청할 때에 납부하여야 하는 등기신청수수료에 대하여는 신청방식별로 달리 규정하고 있으나 집행법원이 등기를 전자촉탁하는 경우에는 등기신청수수료가 감액되지 않는다.","w":"등기신청수수료를 줄여 주는 특례는 전자신청과 전자표준양식에 의한 신청에 정해져 있다(「등기신청수수료 징수에 관한 예규」 4의2.). 집행법원의 전자촉탁은 이 특례에 들어 있지 않다.","c":"중","v":1},"법무사2019_25-06-1":{"f":"사용자등록을 하고자 하는 변호사나 법무사는 제출사무원으로 하여금 사용자등록신청서를 제출하도록 할 수 없다.","w":"전자신청을 하려는 당사자나 변호사·법무사는 최초 전자신청 전에 등기소에 직접 출석해 사용자등록을 해야 한다(「사용자등록절차에 관한 업무처리지침」).","c":"상","v":1},"법무사2019_25-06-2":{"f":"전자신청의 대리는 변호사나 법무사, 즉 자격자 대리인만이 할 수 있고, 자격자 대리인이 외국인인 경우에도 당사자를 대리하여 전자신청을 할 수 있다.","w":"국적은 자격자대리인 요건이 아니다. 변호사나 법무사 자격이 있으면 외국인이어도 전자신청을 대리할 수 있다.","c":"중","v":1},"법무사2019_25-06-3":{"f":"사용자가 정지된 사용자등록의 효력회복을 신청하고자 하는 경우 신청서에는 기명날인 또는 서명을 하여야 하나, 인감증명은 첨부할 필요가 없다.","w":"효력회복은 등기소를 방문해 신청하며, 신청서에 기명날인 또는 서명을 하면 되고 인감증명이나 본인서명사실확인서는 따로 첨부하지 않는다(부동산등기규칙 제70조 제3항, 「사용자등록절차에 관한 업무처리지침」).","c":"상","v":1},"법무사2019_25-06-4":{"f":"전자신청의 취하는 전산정보처리조직을 이용해서만 할 수 있다.","w":"전산정보처리조직으로 한 등기신청(전자신청)의 취하는 전산정보처리조직을 이용해서 해야 한다(부동산등기규칙 제51조 제2항 제2호).","c":"상","v":1},"법무사2019_25-13-4":{"f":"새로 조성된 토지에 관한 소유권보존등기, 저당권 또는 근저당권의 설정등기를 신청할 때에는 국민주택채권을 매입할 필요가 없다.","w":"토지개발등기에서 새로 조성된 토지의 소유권보존등기, 저당권·근저당권설정등기를 신청할 때에는 국민주택채권을 매입하지 않는다(「토지개발등기에 관한 업무처리지침」).","c":"상","v":1},"법무사2020_26-04-5":{"f":"주차장법 제19조 제4항에 따라 시설물의 부지 인근에 부설주차장을 공동으로 설치한 경우, 각 시설물의 소유자 전원이 주차장법 제19조의24에 의한 부기등기를 동시에 신청할 필요는 없다.","w":"부기등기는 각 시설물의 소유자가 각각 신청할 수 있으며 전원이 동시에 신청하는 것은 요건이 아니다.","c":"중","v":1},"법무사2026_32-08-4":{"f":"공공기관과 민간사업자가 공동사업주체로서 주택건설사업을 시행하고 건설된 집합건물의 전유부분에 관한 소유명의를 공공기관과 민간사업자의 합유로 등기하는 경우에도 주택법 제61조 제3항 본문에 따른 부기등기를 할 수 있다.","w":"공동사업주체가 전유부분을 합유로 등기한 경우에도 사업주체로서 주택법 제61조 제3항의 금지사항 부기등기를 할 수 있다.","c":"중","v":1},"법무사2016_22-47-4":{"f":"공탁관의 처분에 대한 이의에 의하여 그 처분의 취소 등 상당한 처분을 명하여 줄 것을 구하는 경우, 공탁관이 해당 공탁사무와 관련하여 더 이상 어떠한 처분을 할 수 없게 된 경우에는 이의의 신청을 할 수 없다.","w":"이의는 공탁관에게 상당한 처분을 명하게 하려는 절차이다. 공탁관이 더는 처분할 수 없으면 이의로 얻을 이익이 없어 부적법하다.","c":"상","v":1},"법무사2016_22-48-3":{"f":"공탁금에는 대법원규칙이 정하는 이자를 붙일 수 있고, 공탁금의 이자에 관하여는 공탁금의 이자에 관한 규칙에서 정하는 바에 따르는데, 현재는 ‘연 1만분의 35’로 시행하고 있다.","w":"공탁금 이율은 「공탁금의 이자에 관한 규칙」 제2조가 정하며 여러 차례 바뀌었다. 현행 이율은 연 1만분의 35(2022. 10. 1. 시행)이다.","c":"중","v":1},"법무사2016_22-48-5":{"f":"공탁금 지급청구권에 대한 압류 및 추심명령이 있는 때에 그 명령에 공탁금의 이자에 대한 언급이 없을 때에는 추심채권자는 원칙적으로 압류 전의 공탁금의 이자에 대한 추심권이 없다.","w":"압류의 효력은 압류 시점 이후에 발생하는 이자에 미치고, 압류 이전에 이미 발생한 이자는 따로 압류하지 않는 한 포함되지 않는다.","c":"중","v":1},"법무사2017_23-32-5":{"f":"방문신청의 방법으로 공탁된 사건이라도 공탁금액이 5천만 원 이하이면 전자공탁시스템에 의한 지급청구를 할 수 있다.","w":"금전공탁사건의 신청·청구는 전자공탁시스템으로 할 수 있고, 제외되는 것은 5천만원을 넘는 공탁금의 출급·회수청구뿐이다(공탁규칙 제69조). 공탁을 방문신청으로 했는지는 따지지 않는다.","c":"상","v":1},"법무사2017_23-33-3":{"f":"변제공탁은 채무자 본인이 공탁자가 되는 것이 원칙이나 연대채무자, 보증인은 채무자의 의사에 반하는 경우에도 변제공탁을 할 수 있다.","w":"연대채무자와 보증인은 변제할 정당한 이익이 있는 사람이어서 채무자의 의사에 반해서도 변제할 수 있고 공탁도 할 수 있다.","c":"중","v":1},"법무사2017_23-36-1":{"f":"공탁관이 전자공탁시스템을 이용하여 이루어진 공탁사건에 대한 공탁서 정정신청을 수리하는 경우 전자문서에 그 뜻을 기재하고, 행정전자서명 인증서에 의한 사법전자서명을 하여야 하며, 신청인이 전자공탁시스템에 접속하여 공탁서 정정신청서를 출력할 수 있도록 하여야 한다.","w":"전자공탁 사건의 공탁서 정정을 수리한 공탁관은 신청인이 전자공탁시스템에서 정정신청서를 출력할 수 있게 해야 한다(「전자공탁시스템에 의한 공탁사무처리지침」 제13조 제3항).","c":"상","v":1},"법무사2017_23-36-4":{"f":"기존 반대급부 조건을 철회하는 공탁서 정정은 가능하나 공탁자를 변경하는 정정은 공탁의 동일성을 해하여 허용되지 않으며, 공탁물 출급청구권 행사에 영향을 미치는 중요한 정정인 경우 피공탁자에게 통지함이 바람직하다.","w":"공탁자를 바꾸는 것은 공탁의 동일성을 해하는 정정이라 허용되지 않는다. 반대급부 조건을 철회하는 것은 피공탁자에게 유리하여 허용된다.","c":"중","v":1},"법무사2017_23-36-5":{"f":"특정채권의 귀속에 관하여 ‘甲’과 ‘乙’ 간에 다툼이 있지만 채무자가 ‘甲’을 피공탁자로 하는 변제공탁을 하고, 甲의 채권자 ‘丙’이 甲의 출급청구권을 압류한 상태에서 피공탁자를 정당한 채권자 ‘乙’로 하는 공탁서 정정신청은 허용되지 않는다.","w":"이미 甲의 출급청구권을 압류한 丙의 권리를 해치게 되므로 피공탁자를 乙로 바꾸는 정정은 허용되지 않는다.","c":"중","v":1},"법무사2018_24-33-2":{"f":"공탁신청 당시 제출한 위임장에 ‘회수청구 및 그 수령의 권한’이 명기되어 있는 경우라도 종전의 대리인이 공탁물 회수청구를 할 때에는 별도의 위임장 또는 종전에 위임한 대리권이 소멸되지 않았음을 증명하는 공탁자 본인 작성의 서면을 제출하여야 한다.","w":"공탁 당시의 위임장이 회수청구 권한을 포함하더라도 시간이 지난 뒤 대리권이 유지되고 있는지 확인이 필요하다. 그 증명으로 새 위임장이나 본인 작성 서면을 낸다.","c":"하","v":1},"법무사2018_24-38-5":{"f":"수용대상 토지에 가처분등기가 경료되어 있으나 그 가처분의 피보전권리가 공시되어 있지 않아 사업시행자가 ‘토지소유자 또는 가처분권리자’를 피공탁자로 하는 상대적 불확지공탁을 한 이후에, 그 가처분의 피보전권리가 소유권이전등기청구권임이 확인된 경우에도 기존의 불확지공탁에서 토지소유자를 피공탁자로 하는 확지공탁으로 바꾸는 공탁서 정정은 허용되지 않는다.","w":"가처분 피보전권리가 소유권이전등기청구권으로 확인되었더라도 불확지공탁을 확지공탁으로 바꾸는 공탁서 정정은 공탁의 동일성을 해쳐 허용되지 않는다.","c":"하","v":1},"법무사2018_24-46-2":{"f":"비법인 사단이 판결에 기하여 공탁을 하는 경우에도 판결문만을 첨부하여 공탁할 수 없고, 정관이나 규약과 대표자의 자격을 증명하는 서면을 첨부하여야 한다.","w":"법인 아닌 사단이 공탁할 때에는 정관이나 규약과 대표자 또는 관리인의 자격을 증명하는 서면을 붙여야 한다(공탁규칙 제21조 제1항). 판결에 기해 공탁하면서 판결문에 사단의 실체와 대표자가 표시되어 있어도 이 서면을 생략하지 못한다.","c":"중","v":1},"법무사2018_24-48-5":{"f":"공탁금액이 5천만 원을 초과하는 금전공탁신청은 전자공탁시스템을 이용할 수 있으나, 이에 대한 공탁금 출급 또는 회수 청구는 전자공탁시스템을 이용할 수 없다.","w":"금전공탁 신청은 금액과 관계없이 전자공탁시스템으로 할 수 있다. 전자문서로 할 수 없는 것은 5천만 원을 넘는 공탁금의 출급·회수 청구다(공탁규칙 제69조).","c":"상","v":1},"법무사2019_25-34-3":{"f":"제3채무자가 압류경합을 사유로 하여 집행공탁을 하였으나, 이미 제3채무자가 집행공탁을 하기 이전에 이루어진 채권압류 및 추심명령 또는 채권가압류결정 송달 사실을 공탁원인사실에 착오로 누락하였다는 이유로 이를 추가하는 공탁서 정정신청서를 제출한 경우, 공탁관은 이를 공탁의 동일성을 해하지 않는 것으로 보아 수리할 수 있다.","w":"누락된 압류 사실을 추가하는 것은 공탁의 동일성을 해치지 않는다. 공탁관은 이 정정을 수리할 수 있다.","c":"상","v":1},"법무사2020_26-34-1":{"f":"변제공탁의 공탁당사자가 아닌 제3자가 피공탁자를 상대로 하여 공탁물출급청구권 확인의 소를 제기하여 그 확인판결을 받았더라도, 피공탁자로부터 공탁물출급청구권을 양도받지 않았다면 확인판결을 받은 제3자가 직접 공탁물출급청구를 할 수 없다.","w":"출급청구권은 피공탁자의 권리이므로 제3자가 확인판결을 받았다고 직접 출급할 수 없다. 권리를 양도받아야 한다.","c":"중","v":1},"법무사2020_26-48-3":{"f":"공탁서 정정이 적법하게 수리된 경우에는 정정의 효력은 당초 공탁시로 소급하여 발생하지만, 반대급부조건을 철회하는 공탁서 정정을 수리한 경우에는 그 때부터 정정의 효력이 발생한다.","w":"공탁서 정정의 효력은 원칙적으로 당초 공탁한 때로 소급한다. 반대급부조건을 철회하는 정정은 예외로 정정을 수리한 때부터 효력이 생긴다.","c":"중","v":1},"법무사2021_27-34-1":{"f":"저당채무의 변제와 근저당권설정등기의 말소를 동시이행하기로 하는 특약을 한 사실이 없음에도 특약이 있는 것으로 공탁신청을 한 경우에는 무효이지만 공탁관은 이를 수리하여야 한다.","w":"공탁관은 형식적 요건만 심사하며 특약의 존재 여부 같은 실체 판단은 하지 않는다. 사실과 다른 반대급부 조건이어도 수리한다.","c":"중","v":1},"법무사2021_27-35-1":{"f":"민법 제487조 변제공탁이 성립한 후 피공탁자가 개명한 경우 공탁서 정정신청을 할 필요가 없고 출급청구 시 기본증명서 등을 첨부하면 된다.","w":"개명은 공탁 후에 생긴 사정이어서 공탁서 정정 사유가 아니다. 출급청구 때 개명 사실을 증명하는 서면을 낸다.","c":"중","v":1},"법무사2021_27-42-3":{"f":"1억원의 금전담보공탁은 전자공탁으로 할 수 있다.","w":"금전공탁 신청은 금액 제한 없이 전자공탁으로 할 수 있어 1억 원의 금전담보공탁도 가능하다. 5천만 원을 넘으면 전자로 못 하는 것은 출급·회수 청구다(공탁규칙 제69조).","c":"상","v":1},"법무사2022_28-46-2":{"f":"용인시가 토지수용보상금을 절대적 불확지공탁 한 경우 토지소유자는 공탁자인 용인시를 상대로 공탁서 정정을 청구할 수 있고, 용인시가 이에 응하지 않으면 용인시를 상대로 공탁물출급청구권 확인의 확정판결을 받아 이를 첨부하여 공탁금 출급청구를 할 수 있다.","w":"절대적 불확지공탁의 정정은 공탁자가 하는 것이어서 소유자는 공탁자를 상대로 청구한다. 공탁자가 응하지 않으면 공탁자를 상대로 받은 확인판결로 출급한다. 공탁관(국가)은 상대방이 아니다.","c":"중","v":1},"법무사2022_28-49-3":{"f":"자연인이 사망하면 공탁당사자능력이 소멸하지만 등기기록상 소유자를 피공탁자로 하여 토지수용보상금을 공탁한 경우 피공탁자가 이미 사망하였다면 그 공탁은 상속인들에 대한 공탁으로서 유효하다고 볼 수 있다.","w":"판례는 사망 사실을 모르고 사망자를 피공탁자로 한 공탁을 상속인들에 대한 공탁으로 보아 유효하다고 한다.","c":"중","v":1},"법무사2025_31-38-3":{"f":"공탁서 정정사유가 있더라도 공탁금이 전부 지급된 후에는 공탁서 정정신청을 할 수 없다.","w":"일부만 지급된 경우에는 남은 부분에 관해 정정이 가능하고, 전부 지급되어 공탁관계가 종료된 뒤에만 정정을 할 수 없다.","c":"중","v":1},"법무사2025_31-47-4":{"f":"관할 지방법원은 이의가 이유 있다고 인정하면 공탁관에게 상당한 처분을 할 것을 명하여야 한다.","w":"관할 지방법원은 이의가 이유 있다고 인정하면 공탁관에게 상당한 처분을 할 것을 명하여야 한다(공탁법 제14조 제1항).","c":"상","v":1},"법무사2026_32-41-1":{"f":"공탁법은 공탁당사자능력과 공탁행위능력에 관하여 일반적인 규정을 두고 있지 않다.","w":"공탁법에는 당사자능력과 행위능력에 관한 일반 규정이 없어 민법·민사소송법의 해석에 맡긴다.","c":"중","v":1},"법무사2021_27-43-3":{"f":"","w":"이자소득세 원천징수에 필요한 사항은 공탁금을 계좌입금으로 지급받으려고 신청할 때 공탁물 보관은행을 거쳐 등록한다(행정예규 제1391호 계좌입금에 의한 공탁금출급·회수절차에 관한 업무처리지침). 공탁금을 납입하는 단계의 절차가 아니다.","c":"중","v":1},"법무사2026_32-44-4":{"f":"불수리결정서에는 공탁관의 인감도장을 날인하여야 한다.","w":"불수리결정서에는 공탁규칙 제55조 제2항의 공탁관 인감도장을 찍는다(「공탁 신청 및 출급·회수에 대한 불수리결정 업무처리지침」).","c":"상","v":1},"법무사2023_29-46-4":{"f":"공탁당사자는 전자공탁시스템을 이용하여 전자문서로 제출된 공탁관계서류에 대한 열람을 청구할 수 있는데, 열람을 신청한 자는 공탁관이 열람을 승인한 날부터 1주 이내에 공탁관계서류를 열람할 수 있다.","w":"전자공탁시스템을 이용한 전자기록 열람은 공탁관이 승인한 날부터 1주 이내에 할 수 있다(「전자공탁시스템에 의한 공탁사무처리지침」).","c":"상","v":1},"법무사2024_30-31-1":{"f":"제3채무자가 금전채권의 일부에 대한 민사집행법에 따른 압류를 원인으로 압류에 관련된 금전채권액 전액을 집행공탁(민사집행법 제248조 제1항)하는 경우 공탁관은 피공탁자(압류채무자)에게 공탁통지서를 발송하여야 하나, 압류채권자에게 공탁사실을 통지하지는 않는다.","w":"전액 공탁이면 공탁서에 압류채무자를 피공탁자로 적고 공탁관은 그에게 공탁통지서를 보낸다. 압류에 대해서는 제3채무자가 집행법원에 사유신고를 하고 압류채권자는 집행법원의 지급위탁으로 출급한다. 채권자에게 공탁사실을 통지하는 절차는 가압류나 체납처분 압류를 원인으로 한 공탁에 있다(「제3채무자의 권리공탁에 관한 업무처리절차」).","c":"중","v":1},"법무사2023_29-39-5":{"f":"공탁관은 조사단계에서 서류에 불비한 점이 있거나 공탁사유 또는 지급사유가 없으면 보정이나 취하를 권유할 수 있으나, 신청인이 이에 응하지 않은 경우에도 접수를 거절할 수는 없고 불수리결정을 하여야 한다.","w":"공탁관은 신청이 접수되면 접수 자체를 거절하지 못한다. 신청인이 보정이나 취하를 거부하면 불수리결정을 한다.","c":"상","v":1},"법무사2023_29-38-3":{"f":"공탁금 회수청구권에 대한 압류ㆍ전부채권자가 전부금액에 해당하는 공탁금 회수청구를 하였으나 공탁관이 선행하는 가압류가 존재한다는 이유로 이를 불수리하고 압류의 경합을 이유로 사유신고하여 배당절차가 개시된 경우, 공탁관은 더 이상 해당 공탁사건에 관하여 일정한 처분을 할 지위에 있지 않으므로 위 공탁관의 불수리처분에 대한 이의신청은 그 이익이 없어 부적법하다.","w":"사유신고 뒤 배당절차가 시작되면 공탁관은 지급 처분을 할 지위에서 벗어난다. 이의로 얻을 이익이 없어 이의신청은 부적법하다.","c":"중","v":1},"법무사2016_22-48-2":{"f":"공탁시와 지급시 사이에 이율이 변경된 경우에는 각 기간에 적용되는 이율에 따라 계산하며 지급시의 이율을 공탁시까지 소급하여 적용하지 않는다.","w":"이율은 변경된 시점부터 새 이율을 적용하고, 지급 시 이율을 과거로 소급해 적용하지 않는다.","c":"중","v":1},"법무사2016_22-48-4":{"f":"공탁금 지급청구권에 대한 채권양도가 있는 때에는 양도통지서에 이자청구권의 양도에 관하여 정한 바가 없다면 양도 후의 이자만 양수인에게 지급하여야 함이 원칙이다.","w":"양도통지서에 별도 정함이 없으면 양도 후에 발생한 이자가 양수인에게 가고, 양도 전에 발생한 이자는 양도인에게 속한다.","c":"중","v":1},"법무사2020_26-43-5":{"f":"공탁금 지급청구권에 대한 채권압류 및 전부명령이 확정된 경우 전부명령 송달 후의 이자는 전부채권자에게 귀속하고, 송달 전의 이자는 전부채권자에게 귀속하지 않는다.","w":"전부명령이 확정되면 피압류채권은 전부명령이 제3채무자에게 송달된 때 전부채권자에게 이전한다(민사집행법 제229조 제7항, 제231조). 그래서 송달 뒤에 생긴 공탁금 이자만 전부채권자의 몫이다.","c":"중","v":1},"법무사2016_22-43-1":{"f":"피공탁자 아닌 제3자가 피공탁자를 상대로 하여 공탁물 출급청구권 확인판결을 받았더라도, 그 확인판결을 받은 제3자는 직접 공탁물 출급청구를 할 수 없다.","w":"출급청구권은 피공탁자에게 속하며 확인판결만으로 제3자가 직접 청구하지 못한다. 권리를 양도받아야 한다.","c":"중","v":1},"법무사2023_29-45-3":{"f":"공탁자가 가상계좌에 의한 공탁금 납입을 신청하였는데, 착오납입한 경우 납입당일에 한해 통상 업무시간 전까지 납입취소 신청서에 공탁관의 확인을 받아 납입취소를 요청할 수 있다.","w":"착오납입의 취소는 납입 당일, 통상 업무시간 전까지 신청서에 공탁관의 확인을 받아 요청한다. 언제라도 되는 것은 아니다.","c":"상","v":1},"법무사2023_29-36-3":{"f":"상호가등기를 위한 공탁은 금전으로 하여야 하고, 유가증권으로는 할 수 없다.","w":"상업등기법 제41조는 상호의 가등기를 신청할 때 1천만원 범위에서 대법원규칙이 정한 금액을 공탁하게 하여 금전공탁만 예정한다. 법원이 인정한 유가증권으로 공탁할 수 있다는 규정이 없다.","c":"중","v":1},"법무사2025_31-35-2":{"f":"유가증권공탁에 관하여 대공탁과 부속공탁을 동시에 청구하는 경우에는 하나의 청구서로 할 수 있는데, 이 경우 공탁관은 대공탁과 부속공탁을 별건으로 접수 및 등록하되 1개의 기록을 만든다.","w":"대공탁과 부속공탁을 동시에 청구하면 별건으로 접수·등록하지만 기록은 1개로 만든다(공탁규칙 제31조 제2항).","c":"상","v":1},"법무사2022_28-37-5":{"f":"","w":"담보물변경은 담보권리자의 이익을 해치지 않는 범위에서 법원이 허가한다.","c":"하","v":1},"법무사2016_22-41-4":{"f":"집행공탁을 혼합공탁으로 정정하는 것은 공탁의 동일성을 해하는 내용이므로 허용될 수 없다.","w":"집행공탁과 혼합공탁은 공탁의 성질이 달라 동일성이 없다. 단순한 착오 정정으로 볼 수 없다.","c":"중","v":1},"법무사2017_23-36-2":{"f":"수용보상금을 유가증권으로 공탁한 후 동일한 금액으로 유가증권과 현금으로 공탁물을 변경하는 것은 허용되지 않는다.","w":"공탁물 자체를 바꾸는 것은 정정이 아니라 공탁의 동일성을 해치는 변경이어서 허용되지 않는다.","c":"중","v":1},"법무사2024_30-40-5":{"f":"민법 제487조 후단 소정의 ‘과실 없이 채권자를 알 수 없는 경우’라고 하여 변제공탁을 하였다가 공탁원인사실에 같은 조 전단 소정의 ‘채권자의 수령불능’을 추가하는 것은 공탁의 동일성을 해하는 내용의 정정이므로 허용될 수 없다.","w":"불확지공탁과 수령불능 공탁은 공탁원인이 달라 사유를 바꾸거나 추가하면 공탁의 동일성이 깨진다.","c":"상","v":1},"법무사2021_27-50-1":{"f":"공탁자가 법인 아닌 사단일 경우 판결문에 그 대표자가 표시되어 있더라도 정관이나 규약과 대표자 또는 관리인의 자격을 증명하는 서면을 첨부하여야 한다.","w":"법인 아닌 사단이 공탁할 때에는 정관이나 규약과 대표자 또는 관리인의 자격을 증명하는 서면을 붙여야 한다(공탁규칙 제21조 제1항). 판결에 기해 공탁하면서 판결문에 사단의 실체와 대표자가 표시되어 있어도 이 서면을 생략하지 못한다.","c":"중","v":1},"법무사2021_27-50-2":{"f":"공탁자가 종중인 경우 그 대표자의 자격을 증명하는 서면으로 부동산등기용등록번호를 증명하는 서면을 첨부할 수 없다.","w":"부동산등기용등록번호를 증명하는 서면은 대표자의 자격을 증명하는 서면이 아니다.","c":"중","v":1},"법무사2021_27-50-3":{"f":"변제공탁을 하는 경우 피공탁자의 주소를 소명하는 서면을 첨부해야 하고, 피공탁자의 주소가 불명이라면 그 사유를 소명하는 서면을 첨부하여야 한다.","w":"변제공탁에서 피공탁자의 주소를 적을 때에는 주소를 소명하는 서면을, 주소가 불명이면 불명임을 소명하는 서면을 첨부해야 한다(공탁규칙 제21조 제3항).","c":"상","v":1},"법무사2021_27-50-5":{"f":"같은 사람이 동시에 같은 공탁법원에 여러 건의 공탁을 하는 경우 첨부서면의 내용이 같다면 하나의 공탁서에만 첨부하고 나머지는 그 뜻을 적는 것으로 갈음할 수 있다.","w":"같은 사람이 동시에 같은 공탁법원에 여러 건을 공탁하면서 첨부서면의 내용이 같으면 1건의 공탁서에만 1통을 첨부하고, 다른 공탁서에는 그 뜻을 적으면 된다(공탁규칙 제22조).","c":"상","v":1},"법무사2023_29-40-4":{"f":"금전채권의 일부에 대하여 가압류가 있음을 원인으로 제3채무자가 민사집행법 제291조 및 제248조 제1항에 따라 가압류된 금액만을 공탁하는 경우에도 피공탁자(가압류채무자)를 기재한다.","w":"가압류를 원인으로 한 공탁은 가압류채무자를 피공탁자로 적고, 가압류의 효력은 그의 공탁금출급청구권에 미친다(「제3채무자의 권리공탁에 관한 업무처리절차」). 압류된 금액만 공탁할 때 피공탁자를 적지 않는 것은 본압류의 경우이다.","c":"중","v":1},"법무사2022_28-34-3":{"f":"공탁물 보관자는 오랫동안 보관된 공탁물품이 그 본래의 기능을 다하지 못하게 되는 등의 특별한 사정이 있으면 공탁물(금전, 유가증권 제외)을 수령할 자에게 30일 이상의 기간을 정하여 수령을 최고한 후 이에 응하지 아니하는 경우 법원의 허가를 얻어 공탁물품을 유치권 등에 의한 경매절차에 따라 매각할 수 있고, 그 매각대금에서 매각허가 신청비용, 매각비용 및 공탁물 보관비용을 뺀 나머지를 물품공탁 법원에 공탁하여야 한다.","w":"공탁물보관자는 매각대금에서 매각허가 신청비용, 매각비용, 공탁물 보관비용을 공제한 잔액을 물품공탁 법원에 공탁한다(행정예규 제937호 제7조). 전액을 공탁한 뒤 비용을 따로 출급청구하는 것이 아니다.","c":"상","v":1},"법무사2016_22-44-5":{"f":"토지관할이 없는 공탁소에 한 변제공탁은 일단 수리되더라도 흠결이 치유되지 않으므로 공탁자는 착오에 의한 공탁으로 회수할 수 있다.","w":"관할 없는 공탁소에 한 변제공탁은 수리되었다고 유효해지지 않는다. 공탁자가 착오공탁으로 회수할 수 있다.","c":"중","v":1},"법무사2022_28-45-3":{"f":"국내에 주소나 거소가 없는 외국인이나 재외국민을 위한 변제공탁은 지참채무의 경우라도 다른 법령의 규정이나 당사자의 특약이 없는 한 서울중앙지방법원의 공탁관에게 할 수 있다.","w":"국내에 주소나 거소가 없는 외국인이나 재외국민을 위한 지참채무의 변제공탁은 다른 법령이나 특약이 없으면 서울중앙지방법원 공탁관에게 할 수 있다(공탁규칙 제66조).","c":"상","v":1},"법무사2016_22-32-2":{"f":"법인 아닌 사단이 공탁을 하는 경우 정관이나 규약과 대표자의 자격을 증명하는 서면을 공탁서에 첨부하여야 하고, 판결에 기하여 공탁을 하는 경우에도 판결문에 사단의 실체 및 대표자가 표시되어 있다는 이유만으로 정관이나 규약과 대표자의 자격을 증명하는 서면의 첨부를 생략할 수 없다.","w":"법인 아닌 사단이 공탁할 때에는 정관이나 규약과 대표자 또는 관리인의 자격을 증명하는 서면을 붙여야 한다(공탁규칙 제21조 제1항). 판결에 기해 공탁하면서 판결문에 사단의 실체와 대표자가 표시되어 있어도 이 서면을 생략하지 못한다.","c":"중","v":1},"법무사2016_22-39-3":{"f":"공탁서, 공탁물 출급·회수청구서, 지급위탁서·증명서에 적은 금전에 관한 숫자는 정정, 추가나 삭제하지 못하나, 공탁서의 공탁원인사실과 청구서의 청구사유에 적은 금전에 관한 숫자는 그렇지 않다.","w":"출급·회수청구서에 적은 금전 숫자도 고칠 수 없다. 예외는 공탁서의 공탁원인사실과 청구서의 청구사유에 적은 숫자이다(공탁규칙 제12조 제2항).","c":"상","v":1},"법무사2017_23-31-1":{"f":"금전채권의 일부에 대하여 압류가 있어 제3채무자가 압류된 채권액에 대하여만 공탁하는 경우, 공탁서의 피공탁자란은 기재하지 않는다.","w":"압류된 금액만 공탁하면 공탁서의 피공탁자란을 비워 둔다. 압류명령의 채무자를 피공탁자로 적는 것은 압류와 관련된 금전채권액 전액을 공탁한 경우이다(「제3채무자의 권리공탁에 관한 업무처리절차」 2.).","c":"상","v":1},"법무사2020_26-47-2":{"f":"공탁을 하려는 자는 공탁신청에 관하여는 다른 민원관계의 사무처리와 달리 우편에 의한 공탁신청은 할 수 없다.","w":"공탁은 공탁관에게 출석하는 방식으로 신청한다. 우편으로는 신청할 수 없다.","c":"중","v":1},"법무사2021_27-48-3":{"f":"복수의 채권자들에 대한 개별 채권액을 산정하기 어려운 경우에는 복수의 채권자들을 일괄하여 피공탁자로 표시하여 공탁할 수 있다.","w":"개별 채권액을 알 수 없을 때에는 채권자들을 일괄하여 피공탁자로 기재해 공탁할 수 있다.","c":"하","v":1},"법무사2019_25-48-5":{"f":"공탁자는 공탁수리결정 후 가상계좌로 공탁금을 납입함을 원칙으로 하고, 관할공탁소 공탁관의 보통예금계좌로 납입하는 것은 가상계좌 채번이나 입금이 안 되는 등 부득이한 경우에 한한다.","w":"관할공탁소 외의 공탁소에서 접수한 공탁도 공탁금은 가상계좌로 납입하는 것이 원칙이다. 관할공탁소 공탁관의 보통예금계좌는 가상계좌를 쓸 수 없는 부득이한 경우에 이용한다(「관할공탁소 이외의 공탁소에서의 공탁사건처리 지침」).","c":"상","v":1},"법무사2018_24-49-5":{"f":"공탁금지급청구의 경우에는 금전공탁에 한하여 적용하고, 친구(○○○주식회사 신입사원)의 위임을 받은 대리인이 1,000만 원 이하 금액을 청구하는 경우에는 적용하지 않는다.","w":"이 지침은 공탁금지급청구에서는 금전공탁(유가증권·물품 제외)에만 적용하고, 그것도 공탁규칙 제37조 제3항의 경우(본인 등이 1,000만 원 이하를 직접 청구하는 경우 등)와 법인의 위임을 받은 대리인이 1,000만 원 이하를 청구하는 경우에 한한다(행정예규 제1167호). 개인인 친구의 위임을 받은 대리인의 청구는 해당하지 않는다.","c":"상","v":1},"법무사2023_29-50-1":{"f":"위 지침은 공탁금지급청구의 경우에는 금전공탁에 한하여 적용한다.","w":"이 지침은 공탁금지급청구의 경우 금전공탁에만 적용하고 유가증권·물품공탁에는 적용하지 않는다(행정예규 제1167호).","c":"상","v":1},"법무사2023_29-50-2":{"f":"접수공탁소 및 관할공탁소 모두가 지방법원 본원 또는 지원인 경우에 한하여 적용한다.","w":"이 지침은 접수공탁소와 관할공탁소가 모두 지방법원 본원 또는 지원인 경우에 적용한다(행정예규 제1167호). 본원에 한정되지 않는다.","c":"상","v":1},"법무사2023_29-50-4":{"f":"甲이 乙에 대한 물품대금채무(5백만 원)를 서울중앙지방법원(관할공탁소)에 금전변제공탁한 경우, 피공탁자 乙은 서울북부지방법원(접수공탁소)에 공탁금 출급청구서를 제출할 수 없다.","w":"관할공탁소가 아닌 공탁소에서 공탁사건을 접수하는 지침은 접수공탁소와 관할공탁소가 같은 특별시나 광역시에 있으면 적용하지 않는다(「관할공탁소 이외의 공탁소에서의 공탁사건처리 지침」 3.). 서울중앙지방법원과 서울북부지방법원은 모두 서울특별시에 있다.","c":"상","v":1},"법무사2023_29-50-5":{"f":"위 지침은 민사집행법 제248조 제1항에 따라 제3채무자가 금전채권에 대한 압류가 경합되어 있음을 이유로 집행공탁을 신청하는 경우에는 적용되지 않는다.","w":"이 지침은 공탁신청의 경우 금전변제공탁에만 적용하므로(행정예규 제1167호), 압류경합을 이유로 한 제3채무자의 집행공탁에는 적용되지 않는다.","c":"상","v":1},"법무사2020_26-45-4":{"f":"대공탁을 신청하는 경우에도 부속공탁과 마찬가지로 공탁서 원본을 첨부할 필요가 없다.","w":"대공탁·부속공탁 청구에는 공탁서 원본을 첨부하지 않는다. 공탁규칙 제31조도 청구서 2통 제출만 정하고 있다.","c":"중","v":1},"법무사2026_32-31-4":{"f":"상속이 개시되어 상속인을 피공탁자로 하는 예금채무에 대한 변제공탁은 추심채무에 대한 변제공탁으로 보아 공탁자(채무자)의 영업소 소재지 관할 공탁소에 하여야 한다.","w":"지참채무는 상속인의 주소지, 추심채무는 채무자의 주소지나 영업소 소재지가 관할이다. 예금채무는 상속인의 주소지 관할이 아니라 은행 영업소 소재지 관할로 본다.","c":"중","v":1},"법무사2025_31-44-3":{"f":"피공탁자가 재외국민 또는 외국인일 경우 여권번호, 외국인등록번호 또는 국내거소신고번호의 확인을 위하여 외국인등록 사실증명서, 국내거소신고 사실증명서 등 소명자료를 첨부하여야 한다.","w":"피공탁자가 재외국민이나 외국인이면 여권번호, 외국인등록번호 또는 국내거소신고번호를 확인하기 위해 외국인등록 사실증명서, 국내거소신고 사실증명서 등 소명자료를 첨부하여야 한다(행정예규 제1431호).","c":"상","v":1},"법무사2022_28-50-1":{"f":"공탁자가 법인 아닌 사단인 경우 정관 기타 규약과 대표자나 관리인의 자격을 증명하는 서면을 공탁서에 첨부하여야 하며, 법인 아닌 사단이 판결에 기하여 공탁을 하는 경우에도 판결문상에 사단의 실체 및 대표자가 표시되어 있다는 이유만으로 그 서면의 첨부를 생략할 수 없다.","w":"법인 아닌 사단이 공탁할 때에는 정관이나 규약과 대표자 또는 관리인의 자격을 증명하는 서면을 붙여야 한다(공탁규칙 제21조 제1항). 판결에 기해 공탁하면서 판결문에 사단의 실체와 대표자가 표시되어 있어도 이 서면을 생략하지 못한다.","c":"중","v":1},"법무사2022_28-50-2":{"f":"공탁자가 법인 아닌 사단인 종중인 경우 부동산등기용 등록번호를 증명하는 서면인 종중등록증명서는 대표자의 자격을 증명하는 서면이 될 수 없다.","w":"종중등록증명서는 단체의 등록을 증명할 뿐 대표자가 누구인지를 증명하는 서면이 아니다.","c":"중","v":1},"법무사2022_28-50-3":{"f":"피공탁자의 주소를 소명하는 서면으로서 주민등록표 등·초본 등 관공서에서 발급받은 서면은 발급일로부터 3개월 이내의 것이어야 한다.","w":"관공서 발급 서면은 발급일부터 3개월 이내의 것이어야 한다.","c":"중","v":1},"법무사2022_28-50-4":{"f":"재결서나 판결문에 피공탁자의 주소가 표시되어 있고, 표시된 주소가 피공탁자의 주민등록등ㆍ초본상의 주소와 일치된다고 하더라도, 그 재결서나 판결문은 직접 주소를 소명하는 서면으로 볼 수 없다.","w":"재결서나 판결문의 주소 표시는 소송 당시의 것이어서 주소를 소명하는 서면이 되지 못한다. 주민등록표 등·초본 같은 서면이 필요하다.","c":"상","v":1},"법무사2016_22-33-1":{"f":"당사자 사이에 양도금지의 특약이 있는 채권에 대하여 압류 및 전부명령이 확정된 경우, 채무자는 채권자 불확지 변제공탁을 할 수 없다.","w":"양도금지 특약이 있어도 압류 및 전부명령은 유효하여 채무자는 전부채권자에게 변제하면 되고, 채권자를 알 수 없는 경우가 아니어서 불확지공탁을 할 수 없다.","c":"하","v":1},"법무사2017_23-45-1":{"f":"임대차관계가 종료되는 경우에 그 임대차보증금 중에서 목적물을 반환받을 때까지 생긴 연체차임 등 임대차관계에서 당연히 발생하는 모든 채무를 공제한 나머지 금액에 대한 변제공탁은 유효하다.","w":"보증금에서 연체차임 등 당연히 공제될 금액은 보증금 채무에서 이미 빠지므로 나머지 금액만 공탁해도 유효하다.","c":"상","v":1},"법무사2017_23-45-2":{"f":"수용의 효과를 발생시키는 보상금의 공탁은 특별한 사정이 없는 한 보상금 전액을 공탁하여야 하므로 사업시행자가 피수용자의 전기요금 등을 대납하였다 하더라도 그만큼을 공제한 차액만을 공탁할 수는 없다.","w":"수용보상금은 전액을 공탁해야 수용의 효과가 생긴다. 대납한 금액을 빼고 공탁하면 일부 공탁이 된다.","c":"상","v":1},"법무사2017_23-45-3":{"f":"경매부동산을 매수한 제3취득자가 그 부동산으로 담보하는 채권최고액과 경매비용을 변제공탁하였다면 일부 공탁에 해당되지 않아 그 변제공탁은 원칙적으로 유효하다.","w":"제3취득자는 채권최고액과 경매비용을 변제하면 근저당권을 소멸시킬 수 있다. 이 금액의 공탁은 일부 공탁이 아니라 유효하다.","c":"중","v":1},"법무사2017_23-45-5":{"f":"채무자의 채무액이 근저당 채권최고액을 초과하는 경우에 채무자 겸 근저당권설정자가 그 채무의 일부인 채권최고액과 지연손해금 및 집행비용만을 변제공탁하였다면 일부 공탁에 해당되어 그 변제공탁은 원칙적으로 무효이다.","w":"채무자 본인은 채권최고액을 넘는 채무 전체를 변제해야 한다. 최고액만 공탁하면 일부 공탁이어서 무효이다. 최고액만 내면 되는 사람은 제3취득자이다.","c":"상","v":1},"법무사2020_26-50-5":{"f":"변제공탁이 유효하려면 채무 전부에 대한 변제의 제공 및 채무전액에 대한 공탁이 있어야 하고 채무전액이 아닌 일부에 대한 공탁은 그 부분에 관하여서도 효력이 생기지 않으나, 채권자가 공탁금을 채권의 일부에 충당한다는 유보의 의사표시를 하고 이를 수령한 때에는 그 공탁금은 채권의 일부의 변제에 충당되고, 그 경우 유보의 의사표시는 반드시 명시적으로 할 필요는 없다.","w":"일부 공탁도 채권자가 일부 변제로 받겠다는 뜻을 유보하고 수령하면 충당된다. 그 의사표시는 반드시 명시적일 필요가 없다.","c":"중","v":1},"법무사2024_30-41-2":{"f":"양도금지의 특약이 있는 채권에 대한 전부명령이 확정된 경우 전부채권자가 양도금지의 특약이 있는 사실을 알았더라도 채무자는 채권자 불확지공탁을 할 수 없다.","w":"양도금지 특약은 압류·전부명령의 효력에 영향을 주지 않는다. 전부채권자의 선의·악의와 관계없이 채무자는 전부채권자에게 지급해야 하며 채권자 불확지공탁을 할 수 없다.","c":"중","v":1},"법무사2025_31-31-4":{"f":"군사법원에 계속 중인 형사사건에 관하여도 공탁규칙 중 형사공탁의 특례 규정을 적용한다.","w":"공탁규칙 제88조는 군사법원에 계속 중인 형사사건에도 형사공탁 특례(제8장)를 적용하고, 이때 법원은 군사법원으로, 검찰은 군검찰로 본다고 정한다.","c":"상","v":1},"법무사2025_31-37-2":{"f":"이의유보 의사표시의 상대방은 공탁관 또는 공탁자이다.","w":"이의를 유보하고 공탁금을 수령한다는 의사표시는 공탁관에게도 공탁자에게도 할 수 있다.","c":"중","v":1},"법무사2026_32-33-2":{"f":"","w":"이 공탁에서 공탁자는 공탁서의 피공탁자 주소란에 본안사건법원과 그 사건번호를 적는다.","c":"하","v":1},"법무사2026_32-34-4":{"f":"공탁통지서의 발송은, 법원이 직권으로 소송상의 서류를 소송당사자 기타 이해관계인에게 송달하는 경우에 적용되는, 민사소송법상의 송달에 관한 규정이 적용되지 않으므로 공시송달의 방법에 의해서 공탁통지서를 발송할 수 없다.","w":"공탁통지서는 우편 등 공탁관이 발송하는 것이고 소송서류 송달이 아니다. 민사소송법 송달 규정이 적용되지 않아 공시송달할 수 없다.","c":"상","v":1},"법무사2026_32-47-3":{"f":"장래의 불확정채권에 대하여 수개의 전부명령이 존재하고, 그 후 확정된 피압류채권액이 각 전부금액의 합계액에 미달하는 경우에는 채권자 불확지공탁을 할 수 있다.","w":"전부채권자 중 누구에게 얼마를 지급할지 알 수 없는 경우이므로 채권자 불확지공탁을 할 수 있다.","c":"하","v":1},"법무사2023_29-49-1":{"f":"공탁자는 피공탁자의 인적사항을 모르는 경우 공탁서의 피공탁자란에 해당 형사사건의 사건번호 등을 기재할 수 있고, 인적사항을 아는 경우에도 피공탁자의 주소와 주민등록번호는 기재하지 아니한다.","w":"형사공탁의 공탁서에는 공소장 등에 적힌 피해자의 성명과 형사사건이 계속 중인 법원·사건번호 등을 적고, 피공탁자의 주소와 주민등록번호는 적지 않는다(공탁규칙 제82조).","c":"상","v":1},"법무사2023_29-49-2":{"f":"형사공탁은 피공탁자의 주소지 관할법원 소재 공탁소에 신청하여야 하는 것은 아니다.","w":"형사공탁은 해당 형사사건이 계속 중인 법원 소재지의 공탁소에 할 수 있다(공탁법 제5조의2 제1항). 피공탁자 주소지 관할 공탁소에 해야 하는 것이 아니다.","c":"상","v":1},"법무사2023_29-49-3":{"f":"기소되지 않은 형사사건의 피의자는 형사공탁을 할 수 없다.","w":"형사공탁은 형사사건의 피고인이 피해자의 인적사항을 알 수 없을 때 하는 변제공탁이다(공탁법 제5조의2 제1항). 기소되지 않은 피의자는 할 수 없다.","c":"하","v":1},"법무사2023_29-49-5":{"f":"공탁관은 공탁물보관자로부터 공탁물 납입사실의 전송을 받은 때 전자공탁 홈페이지에 형사공탁의 공고를 하되, 피공탁자의 주소지로 공탁통지서를 발송하지는 않는다.","w":"형사공탁의 공탁서에는 피공탁자의 주소와 주민등록번호를 적지 않고(공탁규칙 제82조 단서), 피공탁자에 대한 공탁통지는 전자공탁홈페이지 공고로 한다(공탁규칙 제84조).","c":"상","v":1},"법무사2024_30-33-4":{"f":"사망한 피해자를 피공탁자로 한 형사공탁의 경우 법원 또는 검찰에서 발급한 피공탁자 동일인 확인 증명서에는 사망한 피해자의 인적사항이 기재되어 있으면 되고 상속인의 인적사항이 함께 기재되어 있어야 하는 것은 아니다.","w":"사망한 피해자를 피공탁자로 한 형사공탁에서 동일인 확인 증명서에는 사망한 피해자의 인적사항이 있으면 된다.","c":"하","v":1},"법무사2021_27-41-2":{"f":"공탁통지서의 송달은 민사소송법 제190조 제1항에 따른 집행관에 의한 휴일 특별송달방법에 의할 수 없다.","w":"공탁통지서는 소송서류가 아니어서 민사소송법상 특별송달 방법을 쓸 수 없다.","c":"중","v":1},"법무사2026_32-49-4":{"f":"채권증서의 반환은 변제와 동시이행의 관계에 있지 않으므로, 채권증서의 반환을 반대급부 조건으로 하여 공탁할 수 없다.","w":"채권증서 반환은 변제를 마친 뒤에 청구할 수 있는 것으로 동시이행 관계가 아니다. 반대급부 조건부 공탁의 조건이 될 수 없다.","c":"중","v":1},"법무사2023_29-44-5":{"f":"공탁자가 공탁물수령자로부터 공탁자 앞으로의 소유권이전등기에 필요한 일체의 서류를 공탁자에게 교부하라는 반대급부 조건을 붙여 변제공탁한 후 이와는 별도로 같은 부동산에 관한 소유권이전등기절차이행의 소를 제기하여 승소확정판결을 받은 경우 위 판결은 반대급부이행 증명서면에 해당하지 않는다.","w":"서류 교부라는 조건을 이행한 것이 아니라 소송으로 등기를 갖게 된 것이어서 조건 이행을 증명하는 서면이 아니다.","c":"중","v":1},"법무사2020_26-42-1":{"f":"본래의 채권에 부착하고 있지 않은 조건을 붙여서 한 공탁은 채권자가 이를 수락하지 않는 한 무효이다.","w":"조건 없는 채무에 조건을 붙인 공탁은 조건만 무효로 되는 것이 아니라 공탁 전체가 무효이다.","c":"상","v":1},"법무사2020_26-42-2":{"f":"수용보상금 공탁의 경우 반대급부조건부 공탁을 할 수 없다.","w":"수용보상금은 전액을 조건 없이 공탁해야 수용의 효과가 생긴다.","c":"상","v":1},"법무사2020_26-42-4":{"f":"반대급부의 이행이 증명되지 않은 동안에도 피공탁자가 공탁수락을 하면 공탁자의 회수청구를 막을 수 있다.","w":"채권자가 공탁을 승인하거나 공탁소에 수락의 의사를 표시하면 공탁자는 공탁물을 회수할 수 없다(민법 제489조 제1항). 반대급부 이행의 증명은 피공탁자가 공탁물을 출급할 때의 요건이다.","c":"상","v":1},"법무사2020_26-42-5":{"f":"반대급부조건부 수용보상금 공탁을 하고 나서 수용개시일 이후에 반대급부 없는 공탁으로 정정하였다면 이러한 공탁은 정정한 때부터 유효하고 소급하여 유효하게 되지 않는다.","w":"정정은 수리한 때부터 효력이 있고 이미 지나간 수용개시일에 소급하지 않는다.","c":"중","v":1},"법무사2017_23-50-5":{"f":"채권자가 채무액에 대해서만 이의를 유보한 것이 아니라 채무자의 공탁원인인 부당이득반환채무금과 다른 손해배상채무금으로서 공탁금을 수령한다는 이의를 유보하고 수령하더라도 공탁원인인 부당이득반환채무의 일부 소멸의 효과는 발생하지 않는다.","w":"공탁원인과 다른 채무의 변제로 받는다는 이의를 유보하고 수령하면, 그 수령으로 공탁원인인 부당이득반환채무가 일부 소멸하는 효과는 생기지 않는다(판례).","c":"중","v":1},"법무사2023_29-31-4":{"f":"채권자가 채무액에 대해서만 이의를 유보한 것이 아니라 공탁원인인 부당이득반환채무금과 다른 손해배상채무금으로서 공탁금을 수령한다는 이의를 유보하고 수령한 경우, 공탁원인인 부당이득반환채무의 일부소멸의 효과는 발생하지 않고 손해배상채무의 일부변제로서의 효과도 발생하지 않는다.","w":"공탁원인과 다른 채무의 변제로 받는다는 이의를 유보하고 수령하면, 공탁원인 채무가 일부 소멸하는 효과도, 유보한 취지대로 손해배상채무를 일부 변제한 효과도 생기지 않는다(판례).","c":"중","v":1},"법무사2026_32-39-2":{"f":"채권자가 미리 명시적으로 수령거절의 의사를 표명하지 않은 경우라도, 채권자의 태도로 보아 채무자가 설령 채무의 이행제공을 하였더라도 채권자가 그 수령을 거절하였을 것이 명백한 경우에는 채무자는 이행제공을 하지 않고도 변제공탁을 할 수 있다.","w":"채권자가 어차피 받지 않을 것이 명백하면 이행제공이라는 형식은 생략할 수 있어 바로 변제공탁을 할 수 있다는 것이 판례이다.","c":"상","v":1},"법무사2016_22-49-4":{"f":"조세채무나 국민연금법에 의한 연금보험료채무도 민법 제487조에 의한 변제공탁의 목적이 될 수 있다.","w":"조세채무와 국민연금 보험료채무도 채권자가 수령을 거절하는 때에는 변제공탁의 대상이 될 수 있다.","c":"하","v":1},"법무사2019_25-37-4":{"f":"채무자가 채무액의 일부만을 변제공탁 하였으나 그 후 부족분을 추가로 공탁하였다면 그때부터는 전 채무액에 대하여 유효한 공탁이 이루어진 것으로 볼 수 있고, 채권자가 공탁물수령의 의사표시를 하기 전이라면 추가공탁을 하면서 제1차 공탁시에 지정된 공탁의 목적인 채무의 내용을 변경하는 것도 허용될 수 있다.","w":"판례는 채권자가 공탁물을 받겠다는 의사를 표시하기 전이라면 공탁자가 추가공탁을 하면서 처음 공탁 때 지정한 채무의 내용을 바꿀 수 있다고 본다.","c":"중","v":1},"법무사2022_28-35-1":{"f":"변제공탁의 목적인 채무는 현존하는 확정채무임을 요하나, 채권자와 채무자 사이에 손해배상채무액에 대해 다툼이 있어 소송이 진행되는 경우 그 판결이 확정되기 전에 채무자가 가집행선고부 판결의 주문에 표시된 금액에 대하여는 채권자의 수령거절 등의 변제공탁사유가 있다면 변제공탁을 할 수 있다.","w":"가집행선고부 판결의 주문에 표시된 금액은 현존하는 채무로 보아 수령거절 등 공탁사유가 있으면 변제공탁을 할 수 있다는 취지의 판례가 있다.","c":"중","v":1},"법무사2024_30-35-5":{"f":"수용 전 토지에 대하여 체납처분에 의하여 압류한 체납처분청이 다시 수용보상금에 대하여 체납처분에 의한 압류를 하였더라도 물상대위의 법리에 의한 수용 전 토지에 대한 체납처분 우선권이 수용금채권에 대한 배당절차에서 종전 순위대로 유지되지는 않는다.","w":"토지에 대한 체납처분 압류는 담보물권이 아니어서 수용보상금에 물상대위가 인정되지 않는다. 보상금에 다시 압류해도 종전 토지 압류의 순위를 이어받지 못한다(판례).","c":"중","v":1},"법무사2018_24-31-1":{"f":"수용개시일까지 소유권이전등기를 마치지 않았다면, 수용개시일 이전에 乙이 甲으로부터 해당 토지를 매수하여 소유권이전등기청구권을 취득하였더라도 등기부상 소유자인 甲을 피공탁자로 하여 보상금을 공탁하여야 한다.","w":"수용의 효과를 받는 피수용자는 소유권자이다. 매수인은 이전등기청구권만 있는 채권자에 불과해 등기부상 소유자 甲이 피공탁자가 된다.","c":"상","v":1},"법무사2018_24-31-2":{"f":"甲 소유 토지에 대한 수용재결이 있은 후 수용개시일 이전에 丙이 甲으로부터 위 토지의 소유권을 승계하였다면, 丙이 소유권을 취득하기 전에 乙이 甲의 손실보상금 채권을 가압류하였더라도 丙을 피공탁자로 하여 보상금을 공탁할 수 있다.","w":"수용개시일 전에 소유권을 승계한 丙이 수용 당시의 소유자이므로 丙을 피공탁자로 공탁할 수 있고, 乙의 가압류는 공탁금에 대한 권리 제한으로 처리한다.","c":"하","v":1},"법무사2018_24-31-3":{"f":"사업인정고시 후 수용재결 전에 甲에서 乙로 소유권변동이 있었다면, 종전 소유자인 甲을 상대로 수용재결이 이루어졌더라도 승계인 乙을 피공탁자로 하여 보상금을 공탁하여야 한다.","w":"사업인정고시 후 재결 전에 소유권이 바뀌었는데도 사업인정 당시의 소유자를 피수용자로 재결하고 보상금을 지급한 경우, 그에 따른 소유권이전등기 신청은 수리하지 않는다(「공익사업을 위한 토지 등의 취득 및 보상에 관한 법률에 의한 등기사무처리지침」).","c":"중","v":1},"법무사2018_24-31-4":{"f":"甲 소유 토지에 대하여 사해행위취소에 따른 소유권등기말소청구권을 피보전권리로 하는 乙 명의의 처분금지가처분등기가 마쳐져 있더라도 甲을 피공탁자로 하여 보상금을 공탁하여야 한다.","w":"소유권등기말소청구권 가처분이 있으면 소유자 또는 가처분채권자를 피공탁자로 하는 상대적 불확지공탁을 할 수 있지만, 사해행위취소에 따른 말소청구권 가처분은 제외된다(「토지수용 등의 보상금의 공탁에 관한 사무처리지침」 제5조 제1항 제1호 단서).","c":"상","v":1},"법무사2019_25-33-5":{"f":"이행의무가 없는 반대조건을 붙여 무효가 된 공탁을 수용의 개시일이 지난 후에 반대급부 없는 공탁으로 정정하더라도 소급하여 유효하게 되지 않으므로 재결은 효력을 상실한다.","w":"정정은 수리한 때부터 효력이 있다. 수용개시일까지 유효한 공탁이 없었으므로 수용재결은 실효된다.","c":"중","v":1},"법무사2022_28-42-1":{"f":"소유권이전등기청구권을 피보전권리로 하는 처분금지가처분등기가 경료되어 있는 수용대상토지에 대한 소유권의 귀속에 관하여 다툼이 있는 경우에도 피공탁자의 상대적 불확지를 이유로 공탁할 수 없다.","w":"소유권이전등기청구권 보전을 위한 가처분등기가 있는 경우에는 상대적 불확지공탁을 할 수 없다(「토지수용 등의 보상금의 공탁에 관한 사무처리지침」 제5조 제2항 제1호).","c":"상","v":1},"법무사2025_31-41-3":{"f":"사업시행자는 피수용자에게 손실보상금을 지급함에 있어 국세징수법 제107조 제1항에 따라 납세증명서의 제출을 요구할 수 있으나 납세증명서의 제출을 조건으로 하는 손실보상금의 공탁은 무효이다.","w":"수용보상금 공탁은 조건 없이 전액을 해야 한다. 납세증명서 제출을 조건으로 붙인 공탁은 무효이다.","c":"중","v":1},"법무사2022_28-47-3":{"f":"수용대상토지에 저당권이 등기된 경우에도 ‘공탁으로 인하여 소멸하는 질권, 전세권, 저당권란’에 그 취지의 기재를 하지 아니한다.","w":"수용대상 토지에 설정된 지상권·전세권·저당권 등은 공탁서의 ‘공탁으로 인하여 소멸하는 질권, 전세권, 저당권’란에 적을 사항이 아니고, 그 권리자를 피공탁자로 적어서도 안 된다(「토지수용 등의 보상금의 공탁에 관한 사무처리지침」 제7조 제2항).","c":"상","v":1},"법무사2023_29-37-5":{"f":"이행의무가 없는 반대조건을 붙여 무효가 된 공탁을 수용개시일 이후에 반대급부가 없는 공탁으로 정정하더라도 소급하여 유효하게 되지 않으므로 재결의 효력은 상실된다.","w":"수용개시일 이후의 정정은 소급효가 없어 수용개시일까지 공탁이 없었던 것이 된다. 재결은 실효된다.","c":"중","v":1},"법무사2026_32-46-3":{"f":"근저당권의 피담보채무에 관하여 전액이 아닌 일부에 대하여 공탁한 이상 그 피담보채무가 계속적인 금전거래에서 발생하는 다수 채무의 집합체라고 하더라도 공탁금액에 상응하는 범위에서 채무소멸의 효과가 발생하는 것은 아니다.","w":"근저당의 피담보채무는 전체가 하나의 채무로 취급되므로 일부 공탁은 효력이 없고 공탁액만큼 채무가 소멸하지 않는다.","c":"상","v":1},"법무사2025_31-36-1":{"f":"채무의 이행확보를 위하여 어음을 발행한 경우 그 채무의 이행과 어음의 반환은 동시이행관계에 있으므로 그 채무를 변제공탁하면서 어음의 반환을 반대급부 조건으로 한 것은 유효하다.","w":"어음을 담보 목적으로 발행한 경우 변제와 어음 반환은 동시이행관계에 있어 반대급부 조건으로 붙일 수 있다.","c":"상","v":1},"법무사2026_32-50-5":{"f":"공탁물 수령을 위한 피공탁자 동일인 확인은 형사공탁에 관한 내용을 통지받은 법원 또는 검찰이 지체 없이 피공탁자 동일인 확인 증명서를 발급하여 공탁소에 송부하는 방식으로 한다.","w":"동일인 확인 증명서는 공탁물을 받을 사람이 직접 발급받아 내는 것이 원칙이 아니라 법원이나 공소청(2026. 3. 24. 개정 전에는 검찰)이 발급해 공탁소에 보낸다. 발급·송부되지 않았을 때 수령하려는 사람이 발급·송부를 요청할 수 있다(공탁법 제5조의2 제4항, 행정예규 제1444호).","c":"상","v":1},"법무사2021_27-46-4":{"f":"회생위원이 미신고 채권자에게 공탁하는 경우에도 공탁예정통지서를 발송하여야 한다.","w":"회생위원이 미신고 채권자에게 공탁하는 경우에도 공탁예정통지서를 발송해야 한다.","c":"하","v":1},"법무사2016_22-35-3":{"f":"","w":"혼합공탁금 중 집행공탁에 해당하는 부분은 집행법원의 배당절차를 거쳐 지급된다.","c":"하","v":1},"법무사2016_22-37-4":{"f":"금전채권에 대하여 민사집행법에 따른 압류와 체납처분에 의한 압류가 있는 경우(선후 불문) 제3채무자는 민사집행법 제248조 제1항에 따른 압류와 관련된 금전채권액 전액을 공탁할 수 있다.","w":"두 압류가 함께 있으면 선후와 관계없이 제3채무자는 민사집행법 제248조 제1항에 따라 압류와 관련된 금전채권액 전액을 집행공탁할 수 있다(「금전채권에 대하여 민사집행법에 따른 압류와 체납처분에 의한 압류가 있는 경우의 공탁절차 등에 관한 업무처리지침」).","c":"상","v":1},"법무사2017_23-42-4":{"f":"채권양도가 유효한 경우에 丙은 甲의 승낙서 또는 甲에 대한 공탁금 출급청구권확인 승소확정판결 이외에 가압류채권자의 승낙서 또는 그에 대한 확인 승소확정판결을 제출하여야 공탁금의 출급을 청구할 수 있다.","w":"양수인은 양도인의 승낙서나 확인판결만으로 부족하고 가압류채권자의 승낙서나 가압류채권자에 대한 확인판결도 함께 낸다.","c":"중","v":1},"법무사2017_23-46-4":{"f":"가압류채무자가 가압류해방공탁을 하더라도 가압류채권자는 본안승소의 확정판결을 첨부하여 그 공탁금에 관한 출급청구를 할 수 없다. 해방공탁금 회수청구권에 대한 압류·전부 등의 집행이 필요하다.","w":"가압류해방공탁금은 가압류의 목적물이 된 채무자의 회수청구권으로 대체된다. 가압류채권자는 판결이 있어도 직접 출급하지 못하고 그 회수청구권에 집행해야 한다.","c":"중","v":1},"법무사2017_23-48-4":{"f":"압류를 원인으로 한 甲의 공탁이 성립된 후에 丙의 압류가 실효되었더라도, 甲은 공탁원인이 소멸되었음을 이유로 공탁금의 회수를 청구할 수 없다.","w":"민사집행법 제248조 제1항에 따라 공탁한 뒤 압류가 실효되면 채무자가 집행법원의 지급위탁을 받아 공탁금을 출급한다(「제3채무자의 권리공탁에 관한 업무처리절차」 5. 가.). 제3채무자인 공탁자가 회수하는 것이 아니다.","c":"상","v":1},"법무사2018_24-37-2":{"f":"민사집행법에 따른 압류와 체납처분에 의한 압류금액의 총액이 피압류채권액을 초과한 경우, 민사집행법에 따른 압류채권자는 직접 공탁관에게 공탁금의 출급을 청구할 수 없다.","w":"압류 총액이 피압류채권액을 초과하면 개별 압류채권자가 직접 출급하지 못하고 배당절차를 거친다.","c":"중","v":1},"법무사2018_24-37-3":{"f":"제3채무자는 금전채권에 대하여 민사집행법에 따른 압류와 체납처분에 의한 압류가 있다는 사유만으로는 체납자(압류채무자)를 피공탁자로 하여 민법 제487조에 의한 변제공탁은 할 수 없으나 민사집행법 제248조 제1항에 의한 집행공탁은 할 수 있다.","w":"압류와 체납처분 압류가 함께 있어도 제3채무자는 집행공탁을 할 수 있다. 체납자를 피공탁자로 한 변제공탁만 허용되지 않는다.","c":"중","v":1},"법무사2018_24-37-4":{"f":"민사집행법에 따른 압류와 체납처분에 의한 압류금액의 총액이 피압류채권액을 초과하는 경우(선후 불문) 공탁서의 피공탁자란은 기재하지 아니한다.","w":"압류 총액이 피압류채권액을 초과하는 경우에는 공탁서의 피공탁자란을 기재하지 않는다. 초과하지 않으면 사정이 다르다.","c":"중","v":1},"법무사2018_24-37-5":{"f":"금전채권에 대하여 민사집행법에 따른 압류와 체납처분에 의한 압류가 있고(선후 불문) 그 압류금액의 총액이 피압류채권액을 초과하는 경우에 민사집행절차에서 압류 및 추심명령을 받은 채권자는 제3채무자로부터 압류채권을 직접 추심할 수 없고 배당절차를 통하여 채권의 만족을 얻는다.","w":"압류 총액이 채권액을 초과하면 압류채권자는 직접 추심하지 못하고 공탁 후 배당절차를 통해 만족을 얻는다.","c":"중","v":1},"법무사2019_25-31-1":{"f":"재판상 담보공탁금에 대하여 채권자(피공탁자)가 출급청구를 한 경우, 공탁관은 피공탁자가 자신의 공탁금출급청구권에 기하여 청구한 것인지 아니면 공탁자의 공탁금회수청구권에 대한 압류 및 추심명령이나 확정된 전부명령을 받아 청구한 것인지 확인하여야 하며, 각각의 경우에 요구되는 서면이 확인되지 않으면 보정을 명하거나 불수리결정을 할 수 있다.","w":"공탁관은 형식적 심사권만 있어도 청구 권원에 따라 필요한 서면이 갖춰졌는지 확인해야 하며, 갖춰지지 않으면 보정을 명하거나 불수리할 수 있다.","c":"중","v":1},"법무사2020_26-35-3":{"f":"유가증권인도청구권이 가압류된 경우 제3채무자로서는 가압류를 이유로 집행공탁을 할 수 없다.","w":"집행공탁은 금전채권에 대한 압류·가압류에서만 인정된다. 유가증권인도청구권 가압류에는 적용되지 않는다.","c":"상","v":1},"법무사2021_27-33-3":{"f":"금전채권에 대한 가압류를 이유로 제3채무자가 민사집행법 제291조 및 제248조 제1항에 의하여 공탁한 후에, 가압류명령이 취소되거나 신청의 취하 등으로 인하여 가압류가 실효되었다면 가압류채무자는 집행법원의 지급위탁 없이 공탁통지서와 가압류가 실효되었음을 증명하는 서면을 첨부하여 공탁관에게 공탁금의 출급을 청구할 수 있다.","w":"가압류가 실효되면 가압류채무자는 공탁통지서와 실효를 증명하는 서면을 붙여 공탁관에게 직접 출급을 청구한다. 집행법원의 지급위탁을 거치는 것은 본압류가 실효된 경우이다(「제3채무자의 권리공탁에 관한 업무처리절차」 5.).","c":"상","v":1},"법무사2021_27-33-5":{"f":"제3채무자가 가압류와 관련된 금전채권 전액을 공탁을 한 경우 가압류의 효력이 미치지 않는 부분에 대하여는 변제공탁의 예에 따른 피공탁자(가압류채무자)의 공탁금 출급청구가 인정된다.","w":"제3채무자가 가압류된 금전채권 전액을 공탁하면, 가압류 효력이 미치지 않는 부분은 변제공탁의 예에 따라 피공탁자(가압류채무자)가 출급을 청구할 수 있다(행정예규 제1018호).","c":"상","v":1},"법무사2021_27-36-4":{"f":"혼합공탁에서 피공탁자가 공탁물의 출급을 청구하려면 다른 피공탁자에 대한 관계에서 공탁물출급청구권이 있음을 증명하는 서면을 갖추는 것으로는 부족하고, 집행채권자에 대한 관계에서도 공탁물출급청구권이 있음을 증명하는 서면을 구비·제출하여야 한다.","w":"혼합공탁에서는 다른 피공탁자에 대한 관계에서 권리를 증명하는 것만으로 부족하고, 집행채권자에 대한 관계에서도 권리가 있음을 증명하는 서면을 제출한다.","c":"상","v":1},"법무사2021_27-49-2":{"f":"가처분채무자로서는 파산관재인을 상대로 담보공탁금의 피담보채권인 손해배상청구권의 존부에 관한 확인의 소를 제기하여 확인판결을 받는 등의 방법에 의하여 피담보채권이 발생하였음을 증명하는 서면을 확보할 수 있다.","w":"가처분채권자가 파산하면 파산재단에 관한 소송의 당사자는 파산관재인이다(채무자회생법 제359조). 피담보채권 존부 확인의 소도 가처분채권자가 아니라 파산관재인을 상대로 낸다.","c":"중","v":1},"법무사2021_27-49-3":{"f":"가처분채무자는 손해배상청구권이 파산채권이므로 이행의 소를 제기할 수는 없다.","w":"가처분채권자가 파산하면 가처분채무자의 손해배상청구권은 파산채권이 되어 파산절차에 의하지 않고는 행사할 수 없다(채무자회생법 제424조). 그래서 이행의 소가 아니라 피담보채권 존부 확인의 소로 증명서면을 마련한다.","c":"중","v":1},"법무사2021_27-49-4":{"f":"가처분채무자는 담보공탁금에 대하여 질권자와 동일한 권리가 있다.","w":"담보제공자는 가처분채권자이고 담보권리자는 가처분채무자이다. 담보공탁금에 대해 질권자와 같은 권리를 갖는 사람은 담보권리자인 가처분채무자이다(민사소송법 제123조).","c":"중","v":1},"법무사2021_27-49-5":{"f":"가처분채권자가 제공한 담보공탁금에 대한 회수청구권에 관한 권리는 파산재단에 속한다.","w":"담보를 제공한 가처분채권자가 파산하면 그 공탁금 회수청구권은 파산자의 재산으로서 파산재단에 속한다.","c":"중","v":1},"법무사2022_28-32-1":{"f":"위 공탁이 성립한 후 甲은 공탁금 중 압류의 효력이 미치지 않는 부분에 한하여 민법 제489조에 근거하여 공탁금을 회수할 수 있다.","w":"압류나 가압류의 효력이 미치는 부분은 회수할 수 없고, 효력이 미치지 않는 부분에 대해서만 민법 제489조 제1항으로 회수할 수 있다.","c":"중","v":1},"법무사2022_28-32-3":{"f":"위 공탁이 성립한 후 공탁금출급청구권에 대하여 丙의 가압류로부터 본압류로 이전하는 채권압류ㆍ추심명령(집행채권액 : 1천만 원)이 송달되어 丙이 추심청구를 하는 경우 공탁관은 이에 응할 수 없고 집행법원에 사유신고를 하여야 한다.","w":"가압류를 원인으로 공탁한 뒤 그 가압류를 본압류로 이전하는 압류명령이 오면 공탁관은 사유신고를 해야 하고(「공탁관의 사유신고에 관한 업무처리지침」), 가압류채권자는 집행법원의 지급위탁을 받아 출급한다(「제3채무자의 권리공탁에 관한 업무처리절차」).","c":"중","v":1},"법무사2022_28-32-4":{"f":"위 공탁이 성립한 후 공탁금출급청구권에 대하여 丁의 채권압류ㆍ추심명령(집행채권액 : 1천만 원)이 송달되어 丁이 추심청구를 하는 경우 공탁관은 이에 응할 수 없고 집행법원에 사유신고를 하여야 한다.","w":"가압류를 원인으로 공탁한 뒤 피공탁자의 출급청구권에 다른 채권자의 압류가 들어와 압류가 경합하면 공탁관은 추심에 응하지 않고 먼저 송달된 압류명령의 발령법원에 사유신고를 한다(「공탁관의 사유신고에 관한 업무처리지침」).","c":"중","v":1},"법무사2023_29-33-2":{"f":"제3채무자가 민사집행법 제248조 제1항에 따라 압류가 경합되어 있음을 이유로 한 집행공탁이 유효하려면 피압류채무에 해당하는 채무 전액을 공탁하여야 하나, 제3채무자가 채무 전액을 공탁하지 않아 집행공탁의 효력이 인정되지 않는 경우에도 그 공탁이 수리된 후 공탁된 금원에 대한 배당절차가 종결되었다면 그 공탁되어 배당된 금원에 대하여는 변제의 효력이 생긴다.","w":"집행공탁이 전액 공탁이 아니어서 효력이 인정되지 않는 경우에도 배당절차가 종결되어 배당된 금원에는 변제의 효력이 생긴다는 것이 판례이다.","c":"중","v":1},"법무사2024_30-32-3":{"f":"공탁금 중에서 가압류의 효력이 미치지 않는 부분에 대하여는, 변제공탁의 예에 따라 피공탁자는 출급청구를 할 수 있고, 공탁자는 회수청구할 수 있다.","w":"가압류 효력이 미치지 않는 부분은 변제공탁의 예에 따라 피공탁자가 출급청구를 할 수 있고, 공탁자도 회수청구를 할 수 있다(행정예규 제1018호).","c":"상","v":1},"법무사2024_30-34-4":{"f":"양수인(丙)이 제3채무자(甲)를 상대로 양수금청구소송에서 얻은 집행권원으로 제3채무자(甲)의 다른 책임재산에 대한 강제집행에 의하여 채권만족을 얻은 경우에는, 제3채무자(甲)는 공탁원인 소멸을 이유로 하는 공탁금 회수청구를 할 수 있다.","w":"양수인이 제3채무자의 다른 재산에 강제집행으로 채권을 만족받아 채무가 소멸했다면 공탁원인이 소멸한 것이어서 제3채무자가 회수를 청구할 수 있다.","c":"중","v":1},"법무사2024_30-36-4":{"f":"처분금지가처분이 금전채권을 목적으로 하는 경우, 제3채무자로서는 채권자불확지에 의한 변제공탁만 할 수 있고 처분금지가처분을 이유로 한 집행공탁은 할 수 없다.","w":"집행공탁은 금전채권에 대한 압류·가압류가 있을 때 인정된다. 처분금지가처분만으로는 집행공탁을 할 수 없다.","c":"상","v":1},"법무사2024_30-47-4":{"f":"공탁금 지급청구권에 대한 압류의 경합으로 공탁관이 집행법원에 사유신고를 한 이후에 다른 채권자로부터 압류나 가압류 등이 있는 경우에는 추가로 사유신고를 할 필요가 없다.","w":"사유신고를 한 뒤에 들어온 압류나 가압류에 대해서는 추가로 사유신고를 하지 않는다(「공탁관의 사유신고에 관한 업무처리지침」 5.).","c":"상","v":1},"법무사2025_31-45-1":{"f":"확정일자 있는 증서에 의한 채권양도가 이루어진 후 양도된 채권에 대하여 사해행위취소에 따른 원상회복청구권을 피보전권리로 하는 채권처분금지가처분결정이 제3채무자에게 송달된 다음 양도인을 채무자로 하는 채권압류 및 추심명령이 제3채무자에게 송달된 경우, 채권압류 및 추심명령 당시 피압류채권이 이미 대항요건을 갖추어 양도되어 위 채권압류 및 추심명령이 효력이 없는 것으로 되었다면 제3채무자는 혼합공탁을 할 수 없다.","w":"채권압류 당시 이미 양도가 대항요건을 갖췄으면 그 압류는 효력이 없어 압류가 유효함을 전제로 한 혼합공탁은 할 수 없다.","c":"중","v":1},"법무사2026_32-37-1":{"f":"제3채무자가 혼합공탁을 하고 그 공탁사유신고를 한 후에 채무자의 공탁금출급청구권에 대하여 압류 및 추심명령을 받은 채권자는 집행공탁에 해당하는 부분으로부터 배당받은 사람에 대하여 배당이의의 소를 제기할 원고적격이 없다.","w":"혼합공탁 뒤 출급청구권에 압류·추심한 채권자는 집행공탁 부분의 배당절차 당사자가 아니어서 배당이의의 소를 제기할 원고적격이 없다는 취지의 판례가 있다.","c":"하","v":1},"법무사2016_22-42-4":{"f":"甲은 공탁 후 압류명령이 취소된 경우에도 원인소멸을 이유로 8천만 원에 대하여 회수청구를 할 수 없다.","w":"민사집행법 제248조 제1항에 따라 공탁한 뒤 압류가 실효되면 채무자가 집행법원의 지급위탁을 받아 압류된 금액을 출급한다(「제3채무자의 권리공탁에 관한 업무처리절차」 5. 가.). 제3채무자인 공탁자가 회수하는 것이 아니다.","c":"상","v":1},"법무사2019_25-39-5":{"f":"가압류채권자 丙은 가압류를 본압류로 이전하는 압류명령을 얻었더라도 집행법원의 지급위탁이 있어야 공탁금의 출급을 청구할 수 있다.","w":"가압류를 본압류로 이전하는 압류명령을 받아도 공탁금의 출급은 집행법원의 지급위탁이 있어야 청구할 수 있다.","c":"중","v":1},"법무사2022_28-39-4":{"f":"가압류채권자(甲)가 가집행선고부 판결을 받아 해방공탁금의 회수청구권을 압류 및 전부받은 경우에, 전부채권자(甲)가 해방공탁금을 회수하기 전에 가압류채무자(乙)가 항소심에서 전부 승소판결을 받아 사정변경에 의한 가압류결정취소결정을 받았다면 ‘乙’은 전부된 회수청구권을 다시 양도(부당이득의 원상회복)받아야 해방공탁금을 회수할 수 있다.","w":"전부채권자에게 넘어간 해방공탁금 회수청구권은 가압류취소만으로 돌아오지 않는다. 가압류채무자는 부당이득 반환으로 회수청구권을 되돌려 받아야 회수할 수 있다.","c":"중","v":1},"법무사2025_31-39-5":{"f":"집행한 가압류를 취소시키기 위해 해방공탁을 하였으나 공탁금액이 가압류명령에 정한 해방금액 전부가 아니라 그 일부에 불과하다면 그 공탁은 ‘착오로 공탁을 한 경우’에 해당한다.","w":"해방금액의 일부만 공탁하면 가압류집행을 취소받을 수 없어 공탁의 목적을 이룰 수 없으므로 착오로 한 공탁에 해당하고, 공탁자는 이를 회수할 수 있다.","c":"중","v":1},"법무사2025_31-48-4":{"f":"집행채권에 대한 압류 등이 있은 후에 집행채권자가 채무자의 채권에 대하여 압류명령을 받음에 따라 채권압류명령의 제3채무자가 민사집행법에 따른 공탁을 한 후 집행법원에 사유신고를 하였더라도 이는 부적법한 사유신고이어서 채권배당절차가 실시될 수 없다.","w":"집행채권에 대한 압류 등이 있은 뒤 집행채권자의 압류명령에 따른 공탁과 사유신고는 부적법하여 배당절차가 실시될 수 없다는 취지의 판례가 있다.","c":"하","v":1},"법무사2017_23-47-5":{"f":"경합된 압류명령이 서로 다른 법원에 의하여 발하여진 경우에는, 공탁관은 먼저 송달된 압류명령을 발령한 법원에 사유신고를 하여야 한다.","w":"경합된 압류명령이 서로 다른 법원에서 발령되었으면 공탁관은 먼저 송달된 압류명령을 발령한 법원에 사유신고를 한다(민사집행규칙 제172조 제3항, 행정예규 제1225호).","c":"상","v":1},"법무사2018_24-43-4":{"f":"공탁금지급청구권에 대한 압류의 경합으로 공탁관이 집행법원에 사유신고를 한 이후에 다른 채권자로부터 압류나 가압류 등이 있는 경우 공탁관은 집행법원에 추가로 사유신고를 할 필요가 없다.","w":"압류 경합으로 사유신고를 한 뒤에 다른 채권자의 압류나 가압류가 들어와도 공탁관은 추가로 사유신고를 할 필요가 없다(행정예규 제1225호).","c":"상","v":1},"법무사2021_27-37-5":{"f":"금전공탁이 아닌 유가증권 또는 물품공탁의 지급청구권에 대하여 압류가 경합된 경우에는 공탁관은 집행법원에 사유신고를 하지 않는다.","w":"금전공탁이 아닌 유가증권이나 물품공탁의 지급청구권에 압류가 경합된 경우는 공탁관이 사유신고를 하지 않는 경우로 정해져 있다(행정예규 제1225호).","c":"상","v":1},"법무사2022_28-38-1":{"f":"상대적 불확지 변제공탁에 있어서 피공탁자 중 일방의 공탁금출급청구권에 대하여 압류의 경합이 있는 경우에는 해당 피공탁자에게 공탁금출급청구권이 있음을 증명하는 서면이 제출되기 전에는 공탁관은 사유신고를 하지 않는다.","w":"누가 출급청구권자인지 정해지기 전에는 압류가 경합해도 사유신고를 할 수 없다. 권리 귀속을 증명하는 서면이 제출된 뒤에 사유신고를 한다.","c":"중","v":1},"법무사2016_22-40-3":{"f":"가압류해방공탁금의 회수청구권에 대하여 압류명령이 송달되었으나, 가압류로부터 본압류로 이전된 것이 명백하고 다른 (가)압류의 경합이 없는 경우에는 사유신고를 할 필요가 없다.","w":"가압류가 본압류로 이전된 것이 명백하고 다른 압류의 경합이 없으면 압류의 경합이 아니어서 사유신고를 하지 않는다.","c":"중","v":1},"법무사2025_31-49-5":{"f":"민사집행법 제248조 제1항에 의하여 공탁한 후에 압류명령이 취소되거나 신청의 취하 등으로 인하여 압류가 실효된 경우, 채무자는 압류된 채권액에 대하여 집행법원의 지급위탁에 의하여 공탁금을 출급할 수 있다.","w":"압류가 실효된 경우 채무자는 압류된 채권액에 대하여 집행법원의 지급위탁을 받아 출급한다. 공탁관에게 직접 청구하는 것은 가압류가 실효된 경우이다(「제3채무자의 권리공탁에 관한 업무처리절차」 5.).","c":"상","v":1},"법무사2021_27-33-2":{"f":"둘 이상의 가압류가 있는 경우 제3채무자는 민사집행법 제291조 및 제248조 제1항 공탁을 한 후 즉시 공탁서를 첨부하여 먼저 송달된 가압류명령의 발령법원에 공탁사유신고를 하여야 하나 그로 인하여 배당절차가 개시되는 것은 아니다.","w":"가압류만 경합한 경우에는 배당할 대상이 확정되지 않아 사유신고가 있어도 배당절차가 개시되거나 배당요구종기가 도래하지 않는다. 본압류로 이전되어야 배당절차가 시작된다.","c":"중","v":1},"법무사2021_27-33-4":{"f":"가압류채권자가 가압류를 본압류로 이전하는 압류명령을 얻은 경우에도 집행법원의 지급위탁이 있어야 공탁소로부터 공탁금을 출급할 수 있다.","w":"가압류가 본압류로 이전되어도 가압류해방공탁금의 출급은 집행법원의 지급위탁을 거쳐야 한다.","c":"중","v":1},"법무사2025_31-50-3":{"f":"가압류채무자가 가압류이의를 신청하여 가압류를 취소하는 결정을 받았다면 가압류채무자는 공탁통지서와 가압류취소결정정본 및 그 송달증명을 첨부하면 되고, 가압류취소결정의 확정증명을 별도로 첨부할 필요는 없다.","w":"가압류이의에 따른 취소결정은 확정되지 않아도 효력이 있고, 즉시항고가 있어도 효력정지 결정이 따로 있어야 멈춘다(민사집행법 제286조, 제289조). 그래서 출급청구에 확정증명을 요구하지 않는다.","c":"중","v":1},"법무사2018_24-47-2":{"f":"채권이 몰수보전된 후 그 몰수보전의 대상이 된 채권에 대하여 강제집행에 의한 압류명령을 송달받아 제3채무자가 공탁한 경우 집행법원은 공탁된 금원 중에서 몰수보전된 금전채권의 금액에 상당하는 부분에 관하여는 몰수 재판이 확정된 후에 배당 절차를 시작하거나 변제금의 지급을 실시한다.","w":"몰수보전된 부분은 몰수 재판이 확정될 때까지 배당을 보류한다.","c":"중","v":1},"법무사2026_32-45-5":{"f":"제3채무자가 민사집행법 제248조 제3항에 따른 공탁의무를 위반하였더라도 공탁청구 채권자에게 배당될 수 있었던 금액 상당의 손해가 현실적·확정적으로 발생해야 불법행위로 인한 손해배상책임을 부담한다.","w":"민사집행법 제248조 제3항은 압류가 겹친 경우 압류·가압류채권자가 청구하면 제3채무자가 채권 전액을 공탁하도록 정한다.","c":"하","v":1},"법무사2019_25-43-1":{"f":"금전채권의 일부만이 압류되었으나 제3채무자가 압류에 관련된 금전채권 전액을 공탁한 경우, 제3채무자는 압류의 효력이 미치지 않는 부분에 대하여 별도의 변제공탁 사유가 없더라도 압류와 관련된 금전채권 전액을 1건으로 공탁할 수 있다.","w":"민사집행법 제248조 제1항은 압류에 관련된 금전채권 전액을 공탁하도록 허용한다. 압류가 미치지 않는 부분에 별도 변제공탁 사유가 없어도 1건으로 공탁할 수 있다.","c":"상","v":1},"법무사2019_25-43-2":{"f":"금전채권의 일부만이 압류되었으나 제3채무자가 압류에 관련된 금전채권 전액을 공탁한 경우, 압류의 효력이 미치는 부분에 대하여는 공탁서상의 피공탁자란에 압류채무자를 기재하지 않는다.","w":"압류의 효력이 미치는 부분은 집행공탁이어서 피공탁자란을 비워 둔다. 압류가 미치지 않는 부분만 압류채무자를 피공탁자로 한다.","c":"중","v":1},"법무사2019_25-43-3":{"f":"민사집행법 제248조 제1항에 의하여 채권압류를 원인으로 한 공탁이 성립된 후에 그 공탁원인이 된 압류명령의 효력이 실효된 경우에도 제3채무자는 공탁원인 소멸을 이유로 회수청구권을 행사할 수 없다.","w":"압류가 실효돼도 이미 성립한 집행공탁은 제3채무자가 회수할 수 없다. 공탁금은 채무자 등에게 지급되는 방식으로 정리된다.","c":"중","v":1},"법무사2019_25-43-5":{"f":"금전채권에 대하여 압류경합이 있는 경우 압류채권액의 총액이 피압류채권액보다 많은 경우에는 금전채권 전액을 공탁하여야 하고 일부만 공탁할 수는 없다.","w":"압류의 총액이 피압류채권액보다 많으면 제3채무자는 채권 전액을 공탁하여야 하고 일부만 공탁할 수 없다.","c":"중","v":1},"법무사2019_25-40-1":{"f":"배당금수령채권이 단일압류되어 있는 경우에는 집행공탁이 아니라 압류채권자에게 배당금을 지급한다.","w":"배당금수령채권에 단일 압류가 있으면 공탁이 아니라 압류채권자에게 지급한다. 집행공탁은 경합이 있는 경우의 절차이다.","c":"하","v":1},"법무사2019_25-40-2":{"f":"배당금수령채권에 대해 단일의 압류·추심명령이 발령된 경우에는 집행공탁이 아니라 추심채권자에게 지급한다.","w":"단일 압류·추심명령은 경합이 아니므로 집행공탁이 아니라 추심채권자에게 지급한다.","c":"하","v":1},"법무사2019_25-40-3":{"f":"저당권이 있는 채권에 대한 압류의 효력은 저당권자의 배당금청구권에 미치므로, 저당권자를 피공탁자로 하여 공탁을 할 수 있다.","w":"저당권이 있는 채권에 대한 압류의 효력은 저당권자의 배당금청구권에도 미치므로 저당권자를 피공탁자로 공탁할 수 있다.","c":"하","v":1},"법무사2019_25-40-4":{"f":"배당금수령채권에 대해 단일의 추심명령이 존재하는 경우로서 추심채권자가 배당기일에 출석하지 않은 경우에는 민사집행법 제160조 제2항에 따라 공탁할 수 있다.","w":"단일 추심명령만 있어도 추심채권자가 불출석한 경우 민사집행법 제160조 제2항에 따라 공탁할 수 있다.","c":"하","v":1},"법무사2025_31-33-4":{"f":"공탁의무가 발생한 경우 제3채무자는 집행공탁이 아닌 정당한 추심권자 1인에게 직접 변제하는 등의 방법으로는 공탁청구한 채권자에게 채무의 소멸을 주장할 수 없다.","w":"공탁의무가 생긴 제3채무자가 한 사람에게 직접 변제하면 공탁을 청구한 다른 채권자에게는 채무 소멸을 주장하지 못한다.","c":"상","v":1},"법무사2017_23-38-2":{"f":"공탁자의 공탁금 회수청구권이 제3자에게 양도된 경우에도 피공탁자가 담보권을 실행하면 피공탁자에게 공탁금을 지급한다. 다만 담보취소결정정본 및 확정증명이 이미 제출된 경우에는 그러하지 아니하다.","w":"공탁자의 공탁금 회수청구권이 제3자에게 양도되었거나 압류되었더라도 피공탁자가 담보권을 실행하면 피공탁자에게 공탁금을 지급한다. 다만 담보취소결정정본과 확정증명이 이미 제출되었으면 그렇지 않다(행정예규 제952호).","c":"상","v":1},"법무사2020_26-37-1":{"f":"법원의 담보제공명령에 의하여 현금공탁을 한 후에도 법원은 담보물을 변환하는 것에 관한 재량이 있으므로 이를 유가증권으로 변경하는 것이 허용될 수 있다.","w":"담보제공자의 신청으로 법원의 허가를 받으면 담보물을 변경할 수 있다.","c":"상","v":1},"법무사2021_27-47-1":{"f":"담보제공명령의 당사자가 아닌 제3자도 담보제공의무자를 대신하여 공탁할 수 있고 법원의 허가나 담보권리자의 동의를 요하지 않는다.","w":"제3자도 담보제공의무자를 대신해 공탁할 수 있고, 이때 법원의 허가나 담보권리자의 동의는 요하지 않는다.","c":"중","v":1},"법무사2021_27-47-2":{"f":"금전 및 이에 대한 지연손해금의 지급을 명한 가집행선고부 판결에 대한 강제집행정지를 위하여 담보공탁을 한 경우 집행의 정지가 효력이 있는 기간내에 발생한 지연손해금에는 담보권의 효력이 미치나 원금에는 담보권의 효력이 미치지 않는다.","w":"가집행선고부 판결에 대한 강제집행정지 담보는 정지로 채권자에게 생길 손해를 담보하는 것이고 정지 대상인 기본채권 자체를 담보하지 않는다(행정예규 제952호). 정지 기간의 지연손해금에는 미치지만 원금에는 미치지 않는다.","c":"상","v":1},"법무사2021_27-47-4":{"f":"피공탁자가 피담보채권에 기하여 민사집행법 제273조에서 정한 채권에 대한 강제집행절차에 따라 공탁자의 공탁금회수청구권을 압류 및 추심명령을 얻어 공탁금 출급청구를 하는 경우에는 담보취소결정을 받을 필요가 없다.","w":"피공탁자가 담보권 실행으로 공탁자의 회수청구권을 압류·추심(또는 전부)하여 출급을 청구할 때에는 압류명령·추심명령 정본 등을 내면 되고, 담보권의 존재가 이미 증명되므로 따로 담보취소결정을 받을 필요가 없다(행정예규 제952호).","c":"상","v":1},"법무사2021_27-47-5":{"f":"제1심에서 가집행의 정지를 위하여 제공된 담보의 경우 항소심에서 제1심 판결이 취소되었더라도 그 항소심판결이 확정되어야 담보사유가 소멸한다.","w":"항소심 판결이 미확정인 상태에서는 담보사유가 소멸했다고 보지 않는다. 판결이 확정되어야 담보사유가 소멸한다.","c":"중","v":1},"법무사2024_30-39-1":{"f":"근저당권에 기한 경매절차의 정지를 위한 담보공탁의 경우 근저당권설정등기말소소송의 소송비용에는 담보권의 효력이 미치지 않는다.","w":"근저당권설정등기말소소송의 소송비용은 경매절차 정지로 인한 손해가 아니어서 담보권의 효력이 미치지 않는다.","c":"중","v":1},"법무사2026_32-36-4":{"f":"제1심 판결과 항소심 판결에 대한 강제집행정지를 위하여 담보공탁을 두 차례에 걸쳐 한 경우, 2차에 걸친 공탁은 각기 해당 심급에 관한 채권자의 손해를 담보하는 것이므로, 제1심에서 제공한 담보에 관하여는 항소심에서 다시 담보가 제공되었더라도 담보사유가 소멸되었다고 할 수 없다.","w":"제1심 담보는 항소심에서 다시 담보가 제공되었다고 사라지지 않고 각 심급의 손해를 따로 담보한다.","c":"중","v":1},"법무사2023_29-35-2":{"f":"강제집행정지를 위하여 법원의 명령으로 제공된 공탁금은 채권자가 강제집행정지 자체로 인하여 입은 손해배상금채권을 담보하는 것이고, 담보제공자의 권리행사최고에 따라 담보권리자가 권리행사를 위하여 제기한 소송의 소송비용은 강제집행정지로 인하여 입은 통상손해에 해당하므로 위 소송비용은 담보공탁금의 피담보채권에 해당한다.","w":"권리행사 최고에 따라 담보권리자가 제기한 소송의 비용은 강제집행정지로 입은 통상손해에 해당한다는 판례가 있어 담보공탁금의 피담보채권에 해당한다.","c":"하","v":1},"법무사2024_30-48-1":{"f":"권리행사 최고기간의 만료에 따른 담보취소결정이 있은 후, 위 담보취소결정이 확정되기 전에 담보권리자가 권리행사를 하고 이를 증명한다면 위 담보취소결정을 취소할 수 있다.","w":"담보취소결정이 확정되기 전에 담보권리자가 권리행사를 증명하면 그 결정을 취소할 수 있다.","c":"중","v":1},"법무사2026_32-38-1":{"f":"가집행선고부 제1심판결이 항소심판결에 의하여 취소된 경우 제1심에서 가집행의 정지를 위해 제공된 담보는 위 항소심판결이 확정되어야 담보사유가 소멸된다.","w":"항소심판결이 미확정인 상태에서는 제1심에서 제공한 가집행정지 담보의 담보사유가 소멸되지 않는다.","c":"중","v":1},"법무사2020_26-40-1":{"f":"전부명령이 발령되어도 확정되기 전이라면 제3채무자는 민사집행법 제248조 제1항에 따라 권리공탁을 할 수 있다.","w":"전부명령이 확정되기 전에는 아직 압류 단계이므로 제3채무자는 민사집행법 제248조 제1항에 따라 권리공탁을 할 수 있다.","c":"중","v":1},"법무사2020_26-40-2":{"f":"압류가 중복되어 경합하는 경우 경합한 집행채권의 합계액보다 피압류채권의 총액이 더 적은 때에는 채권자의 청구가 있으면 공탁할 의무가 있다.","w":"압류가 경합하고 피압류채권액이 집행채권 합계액보다 적으면 채권자의 청구가 있을 때 제3채무자는 공탁할 의무가 있다.","c":"중","v":1},"법무사2020_26-40-4":{"f":"제3채무자의 집행공탁 전에 다른 채권자의 압류·가압류명령이 발령되었더라도, 제3채무자의 집행공탁 후에야 그에게 송달된 경우, 압류·가압류명령은 효력이 없다.","w":"압류명령은 제3채무자에게 송달되어야 효력이 생긴다. 공탁 뒤에 송달됐다면 이미 채무가 공탁으로 소멸한 뒤여서 효력이 없다.","c":"중","v":1},"법무사2020_26-40-5":{"f":"제3채무자가 공탁의무를 이행하지 않을 때에는 압류명령만을 받은 채권자는 민사집행법 제249조 제1항에 따라 소로써 공탁을 명하는 추심소송을 제기할 원고적격이 없다.","w":"추심소송은 추심명령을 받은 채권자가 제기하는 것이다. 압류명령만 받은 채권자는 추심권한이 없어 소를 제기할 수 없다.","c":"상","v":1},"법무사2020_26-39-2":{"f":"혼합공탁 후 채권양도가 무효로 판명되어야 가압류를 본압류로 이전하는 압류명령이 송달되었을 때 공탁관이 사유신고를 할 수 있다.","w":"혼합공탁 후 채권양도가 무효로 판명되어 압류가 유효해져야 공탁관이 사유신고를 할 수 있다.","c":"중","v":1},"법무사2021_27-44-5":{"f":"가압류채권자는 가압류해방공탁금에 관하여 우선변제권을 행사할 수 없다.","w":"가압류채권자는 가압류해방공탁금에 대해 우선변제권을 갖지 못하고 다른 채권자와 동일하게 취급된다.","c":"중","v":1},"법무사2025_31-40-4":{"f":"채권가압류를 원인으로 민사집행법 제291조 및 제248조 제1항에 따라 집행공탁한 후 피공탁자에 대한 체납처분에 의한 압류통지가 이루어진 경우, 체납처분에 의한 압류채권자는 위 채권가압류가 근로기준법에 의한 우선변제권을 가지는 임금 등의 채권에 기한 것이라 하더라도 공탁금을 추심할 수 있다.","w":"체납처분에 의한 압류채권자는 가압류가 임금채권에 기한 것이어도 공탁금을 추심할 수 있다.","c":"하","v":1},"법무사2026_32-48-2":{"f":"체납처분에 의하여 압류된 채권에 대하여 민사집행절차에서 압류 및 추심명령을 받은 채권자(추심채권자)가 제3채무자로부터 압류채권을 추심한 경우, 추심채권자는 민사집행법 제236조 제2항에 따라 공탁할 의무가 발생한다.","w":"체납처분으로 압류된 채권을 추심한 추심채권자는 압류가 경합하는 형태가 되어 민사집행법 제236조 제2항에 따라 공탁할 의무가 있다.","c":"중","v":1},"법무사2024_30-38-2":{"f":"채무자의 다른 채권자가 가압류해방공탁금 회수청구권에 대하여 압류명령을 받은 경우, 가압류채권자의 가압류는 해당 해방공탁의 원인이 되었더라도 해방공탁금에 대하여 우선변제권을 갖지 못한다.","w":"가압류채권자의 가압류가 해방공탁의 원인이 되었더라도 다른 채권자가 회수청구권을 압류하면 가압류채권자가 우선변제권을 갖지 못한다.","c":"중","v":1},"법무사2022_28-36-5":{"f":"채무자가 채권양도 및 압류경합을 공탁사유로 공탁을 하면서 피공탁자 내지 채권자 불확지의 취지를 기재하지 않고 공탁근거조문으로 집행공탁에 관한 근거조항만 기재한 경우, 위 공탁은 새로운 채권자에 대한 변제공탁으로서의 효력이 없다고 보아야 한다.","w":"공탁서에 불확지 취지를 기재하지 않고 집행공탁 근거만 적은 공탁은 새로운 채권자에 대한 변제공탁으로서 효력이 없다는 판례가 있다.","c":"중","v":1},"법무사2024_30-37-4":{"f":"동일채권에 대하여 가압류명령이 송달된 이후 채권양도의 통지가 도달되어 제3채무자가 혼합공탁을 한 경우, 가압류채권자는 가압류에서 본압류로 이전하는 채권압류 및 추심명령을 받더라도 집행법원의 지급위탁절차를 거쳐야 공탁금을 출급받을 수 있다.","w":"혼합공탁에서 집행공탁 부분은 집행법원의 지급위탁절차를 거쳐서 출급하며 공탁소에 바로 출급청구할 수 없다.","c":"중","v":1},"법무사2018_24-44-3":{"f":"채권이 이중으로 양도된 경우의 양수인 상호간의 우열은 통지 또는 승낙이 채무자에게 도달한 일시의 선후에 의하여 결정하여야 한다.","w":"확정일자 있는 통지의 우열은 확정일자의 선후가 아니라 채무자에게 도달한 일시를 기준으로 한다.","c":"중","v":1},"법무사2021_27-39-1":{"f":"피공탁자가 공탁금회수동의서를 공탁소에 제출하였더라도 공탁금이 회수되지 않은 상태라면 피공탁자는 공탁금 출급청구를 할 수 있다.","w":"회수동의서를 제출했더라도 실제로 공탁금이 회수되기 전이면 피공탁자는 출급청구를 할 수 있다. 피공탁자가 회수에 동의하면 공탁자는 공탁법 제9조의2 제1항 제1호에 따라 회수할 수 있지만, 실제로 회수되기 전에는 피공탁자의 출급청구권이 남아 있다.","c":"중","v":1},"법무사2024_30-50-4":{"f":"토지수용보상금 공탁이 부적법하여 토지수용재결의 효력이 상실되었다는 판결이 확정된 경우 사업시행자(공탁자)는 확정판결을 첨부하여 공탁금 회수청구를 할 수 있고, 이때 사업시행자 명의의 소유권이전등기가 말소된 수용대상토지의 등기사항증명서를 첨부할 필요는 없다.","w":"재결 실효 판결 확정에 따른 회수청구에는 판결 외에 등기사항증명서를 따로 첨부할 필요가 없다.","c":"하","v":1},"법무사2017_23-34-2":{"f":"국가, 지방자치단체는 전국공통 포괄계좌 입금신청을 할 수 있으며, 이를 해지하고자 할 때에는 전국공통 포괄계좌 입금신청을 한 공탁소에 해지신청서를 제출하여야 한다.","w":"현행 지침에서 전국공통 포괄계좌 입금신청을 할 수 있는 것은 국가와 지방자치단체이고 금융기관은 들어 있지 않다. 해지는 입금신청을 한 공탁소에 해지신청서를 내서 한다(「계좌입금에 의한 공탁금출급·회수절차에 관한 업무처리지침」 제3조의2).","c":"중","v":1},"법무사2020_26-44-2":{"f":"전국공통 포괄계좌 입금신청은 전국 모든 공탁소에 할 수 있으나, 그 입금신청을 해지하는 경우에는 전국공통 포괄계좌 입금신청을 한 공탁소에 하여야 한다.","w":"전국공통 포괄계좌 입금신청의 해지는 그 입금신청을 한 공탁소에 해지신청서를 내서 한다(「계좌입금에 의한 공탁금출급·회수절차에 관한 업무처리지침」 제3조의2 제2항).","c":"상","v":1},"법무사2025_31-43-5":{"f":"공탁금 출급청구권을 갖는 것을 증명하는 서면인 소유권 증명서류를 보증지급의 보증서로 갈음할 수 없다.","w":"출급청구권을 증명하는 소유권 증명서류와 보증지급의 보증서는 서로 다른 서면이어서 갈음할 수 없다.","c":"중","v":1},"법무사2021_27-45-1":{"f":"같은 사람이 여러 건의 공탁에 관하여 전자공탁시스템을 이용하여 출급청구를 하는 경우에는 그 사유가 같더라도 하나의 청구서로 일괄청구할 수 없다.","w":"서면 청구에서는 사유가 같으면 공탁종류에 따라 하나의 청구서로 일괄청구할 수 있지만(공탁규칙 제35조), 전자문서로 제출하는 경우에는 제35조를 적용하지 않는다(공탁규칙 제73조 제5항).","c":"상","v":1},"법무사2021_27-45-3":{"f":"공탁관의 불수리결정에 대하여 불복하는 자는 공탁관의 처분에 대한 이의를 신청할 수 있으며, 이의신청서는 공탁소에 제출한다.","w":"공탁관의 불수리결정에 불복하는 사람은 관할 지방법원에 이의신청을 할 수 있고, 이의신청은 공탁소에 이의신청서를 제출하는 방법으로 한다(공탁법 제12조). 즉시항고의 대상이 아니다.","c":"상","v":1},"법무사2021_27-45-4":{"f":"변제공탁금 출급청구에 대하여 공탁관의 인가를 받은 공탁금출급청구서를 공탁금보관자에게 제출하기 전에 피공탁자가 분실한 경우 공탁관은 이미 한 출급청구에 대한 인가를 취소할 필요 없이 인가사실에 대한 사실증명서를 발급하여 공탁금을 지급받게 한다.","w":"인가받은 청구서를 잃어버리면 청구인이 인가 사실에 대한 사실증명을 신청하고, 공탁물보관자는 그 사실증명서를 받아 공탁물을 지급한다(「인가받은 공탁물출급·회수청구서를 분실한 경우 공탁물 지급에 관한 공탁사무처리지침」). 인가를 취소하는 절차가 아니다.","c":"중","v":1},"법무사2021_27-45-5":{"f":"피공탁자가 공탁물 출급청구서에 공탁통지서를 첨부할 수 없는 경우 공탁물 출급청구에 대하여 이해관계를 가지고 있는 자의 승낙서를 첨부하여 출급청구를 할 수 있는데 이 때 위 이해관계인의 인감증명서를 제출하여야 한다.","w":"공탁통지서 대신 이해관계인의 승낙서를 내는 경우 그 승낙서가 진정한 것임을 인감증명서로 확인한다.","c":"중","v":1},"법무사2016_22-46-5":{"f":"공탁금 지급청구권에 대해 압류, 가압류, 가처분이 있는 경우에도 공탁금 지급청구권의 시효는 중단되지 않는다.","w":"공탁금지급청구권에 대한 압류, 가압류, 가처분은 그 공탁금지급청구권의 시효중단사유가 되지 않는다(행정예규 제948호). 제3자의 압류 등은 권리자가 자기 권리를 행사한 것이 아니다.","c":"상","v":1},"법무사2025_31-46-5":{"f":"일괄 공탁한 공탁금의 일부에 대해 출급 또는 회수청구를 인가한 경우 나머지 잔액에 대하여도 소멸시효가 중단된다.","w":"일괄 공탁한 전체에 대한 권리 행사로 보아 일부 지급을 인가하면 잔액에 대해서도 시효가 중단된다.","c":"중","v":1},"법무사2024_30-44-3":{"f":"양도증서를 공증받아 제출하는 경우에는 양도인의 인감증명서 제출 없이도 양수인은 공탁금 지급청구를 할 수 있다.","w":"양도증서의 진정성을 공증으로 확인했으면 양도인의 인감증명서를 따로 요구하지 않는다.","c":"중","v":1},"법무사2022_28-43-3":{"f":"채무자인 공탁자가 변제공탁을 하면서 공탁서에 불가분채권자 2인을 피공탁자로 기재한 경우 피공탁자 중 1인이 공탁자의 출급동의서를 첨부하였더라도 단독으로 공탁금 출급청구를 할 수 없고, 피공탁자 전원이 함께 청구하거나 피공탁자 1인이 나머지 피공탁자의 위임을 받아 청구하여야 한다.","w":"실체법상 불가분채권자 1인이 모든 채권자를 위해 단독으로 이행을 청구할 수 있더라도, 공탁서에 불가분채권자 2인이 피공탁자로 적혀 있으면 공탁자의 출급동의서가 있어도 1인이 단독으로 출급청구를 할 수 없다. 피공탁자 전원이 함께 청구하거나 1인이 나머지 피공탁자의 위임을 받아 청구한다(같은 쟁점 2026년 기출 O 문장).","c":"상","v":1},"법무사2026_32-42-5":{"f":"법인 아닌 사단이 출급청구하는 공탁금액이 3,000만 원인 경우에는 공탁통지서를 첨부하여야 한다.","w":"출급청구하는 공탁금액이 5,000만 원 이하이면 공탁통지서를 첨부하지 않아도 되지만, 청구인이 관공서나 법인 아닌 사단·재단이면 1,000만 원 이하인 경우에만 면제된다(공탁규칙 제33조 제1호 가목). 3,000만 원을 청구하는 법인 아닌 사단은 공탁통지서를 첨부해야 한다.","c":"상","v":1},"법무사2024_30-46-2":{"f":"채무자가 확정판결에 따라 甲과 乙을 피공탁자(지분 각 1/2)로 하여 판결에서 지급을 명한 금액을 변제공탁한 경우, 甲과 乙은 각자 위 공탁금의 1/2 지분에 해당하는 공탁금을 출급청구할 수 있으나 각자의 지분을 초과하는 지분에 대하여는 상대방을 상대로 공탁금출급청구권의 확인을 청구할 수 없다.","w":"각자의 몫은 판결에서 정해진 1/2이고, 이를 넘는 부분에 대해 상대방을 상대로 권리 확인을 구할 이익이 없다.","c":"중","v":1},"법무사2024_30-42-2":{"f":"공탁물 회수청구를 하는 사람이 비법인재단인 경우에는 공탁금액이 1,000만 원 이하인 때에만 공탁서를 첨부하지 않을 수 있다.","w":"회수청구 때 공탁서 첨부를 생략할 수 있는 기준은 5천만원 이하이지만, 청구인이 관공서이거나 법인 아닌 사단·재단이면 1천만원 이하이다(공탁규칙 제34조 제1호 가목).","c":"상","v":1},"법무사2024_30-42-3":{"f":"회수청구권에 대한 강제집행에 의하여 추심명령 또는 전부명령을 얻은 추심채권자 또는 전부채권자가 공탁물 회수청구를 하는 경우에는 공탁물 회수청구서에 공탁서를 첨부할 필요가 없다.","w":"강제집행이나 체납처분에 따라 공탁물 회수청구를 하는 경우에는 공탁서를 첨부하지 않아도 된다(공탁규칙 제34조 제1호 다목).","c":"상","v":1},"법무사2024_30-42-4":{"f":"공탁물회수청구권에 대한 압류 및 전부명령을 받은 자는 원래의 공탁물회수청구권자의 지위를 넘어서 공탁물을 회수할 수 없으므로, 공탁물 회수청구 시 회수청구권을 갖는 것을 증명하는 서면을 첨부하여야 한다.","w":"전부채권자는 원래 권리자의 지위를 그대로 승계할 뿐이어서, 회수청구권을 갖는다는 증명서면을 첨부해야 한다.","c":"상","v":1},"법무사2024_30-42-5":{"f":"집행법원이 집행공탁금의 배당을 실시하기 전에 공탁자가 집행공탁의 원인이 없음에도 착오로 집행공탁을 한 것임을 이유로 공탁사유신고를 철회한 경우, 그 집행공탁이 원인이 없는 것으로서 무효임이 명백하여 집행법원이 공탁사유신고를 불수리하는 결정을 하였다면, 공탁자는 공탁관에게 집행법원의 위 결정을 제출하여 공탁금을 회수할 수 있다.","w":"집행공탁이 처음부터 무효임이 명백하여 집행법원이 사유신고를 불수리한 경우 공탁자는 그 결정을 제출해 공탁금을 회수할 수 있다.","c":"상","v":1},"법무사2017_23-44-2":{"f":"채권자의 수령불능을 원인으로 한 변제공탁 및 절대적 불확지 변제공탁의 경우에는 공탁금출급청구권의 소멸시효는 공탁일부터 기산하지 않고 피공탁자가 공탁사실을 안 날(공탁통지서 수령일)부터 기산한다.","w":"수령불능을 원인으로 한 공탁과 절대적 불확지공탁에서 출급청구권의 소멸시효는 공탁서 정정 등으로 공탁통지서를 받아 피공탁자가 공탁사실을 안 날부터 기산한다(행정예규 제948호).","c":"상","v":1},"법무사2017_23-44-3":{"f":"공탁관이 공탁자 또는 피공탁자에 대하여 당해 사건의 공탁금을 지급할 수 있다는 취지를 구두로 답한 경우에도 소멸시효 진행이 중단된다.","w":"공탁관이 공탁자나 피공탁자에게 그 사건의 공탁금을 지급할 수 있다고 구두로 답한 경우도 소멸시효 중단사유가 된다(행정예규 제948호).","c":"상","v":1},"법무사2017_23-44-4":{"f":"일괄 공탁한 공탁금의 일부에 대해 출급 또는 회수청구를 공탁관이 인가한 경우 나머지 잔액에 대해서도 소멸시효 진행이 중단된다.","w":"일괄 공탁에서 일부를 인가하면 잔액에 대해서도 권리 행사가 있었던 것으로 본다.","c":"중","v":1},"법무사2017_23-44-5":{"f":"공탁금회수청구권에 대한 시효중단은 출급청구권의 시효진행에 영향을 미치지 않고, 그 반대의 경우도 동일하다.","w":"공탁금회수청구권에 대한 시효중단은 출급청구권의 시효진행에 영향을 미치지 않고, 반대도 같다(행정예규 제948호).","c":"상","v":1},"법무사2018_24-50-2":{"f":"착오공탁의 경우 공탁금회수청구권의 소멸시효는 공탁일부터 기산한다.","w":"착오공탁의 경우 공탁금회수청구권의 소멸시효는 착오를 안 날이 아니라 공탁일부터 기산한다(행정예규 제948호).","c":"상","v":1},"법무사2020_26-46-4":{"f":"공탁금의 지급청구에 대해 첨부서면의 불비를 이유로 불수리 결정을 한 것도 소멸시효 진행의 중단사유로 볼 수 있다.","w":"첨부서면이 모자라 지급청구를 불수리한 경우도 소멸시효 중단사유로 본다(「공탁금지급청구권의 소멸시효와 국고귀속절차」 3. 가.).","c":"상","v":1},"법무사2026_32-32-3":{"f":"피공탁자의 불확지로 공탁통지를 하지 못한 상태에서는 소멸시효기간이 진행되지 않는다.","w":"절대적 불확지공탁에서는 공탁서 정정 등으로 공탁통지서를 받아 피공탁자가 공탁사실을 안 날부터 출급청구권의 소멸시효를 기산한다(행정예규 제948호). 불확지여서 공탁통지를 못 한 동안에는 시효가 진행하지 않는다.","c":"상","v":1},"법무사2023_29-43-3":{"f":"변제공탁에 대해 피공탁자로부터 제출된 수락서를 공탁관이 받은 경우에도 그것만으로 출급청구권의 시효가 중단되지는 않는다.","w":"변제공탁에 대해 피공탁자가 낸 수락서를 공탁관이 받았다는 것만으로는 출급청구권의 시효가 중단되지 않는다(행정예규 제948호).","c":"상","v":1},"법무사2022_28-48-5":{"f":"공탁금출급청구권에 대한 소멸시효가 완성된 경우에는 공탁관은 국고수입 납부 전이라도 공탁금 출급청구가 있는 경우 이를 인가하여서는 안 된다.","w":"소멸시효가 완성된 공탁금은 국고수입 납부 전이라도 지급을 인가하지 않는다. 시효 완성 뒤에는 공탁사실증명서도 내주지 않고, 착오로 내주면 시효이익을 포기한 것으로 처리한다(「공탁금지급청구권의 소멸시효와 국고귀속절차」). 인가해도 되는 것은 시효 완성 여부가 불분명한 경우이다.","c":"중","v":1},"법무사2019_25-49-1":{"f":"공탁관이 공탁금의 지급청구를 인가한 경우에는 공탁물보관자에게 지급인가의 취지와 계좌입금 지시를 전송하고, 청구인에게는 당해 청구서를 교부하지 아니한다.","w":"계좌입금 방식이면 공탁관은 공탁물보관자에게 인가 취지와 입금 지시를 전송하고 청구인에게는 청구서를 내주지 않는다(「계좌입금에 의한 공탁금출급·회수절차에 관한 업무처리지침」 제4조 제3항).","c":"상","v":1},"법무사2016_22-36-1":{"f":"상속인 중 1인이 다른 상속인들 중 일부로부터 출급청구권을 양도받아 공탁금 출급청구권자가 된 경우, 공탁금 출급청구권을 양도받은 사실을 이유로 국가를 상대로 공탁금수령권한이 있다는 확인판결을 받았더라도, 양도인이 국가에게 양도사실을 별도로 통지하지 않았다면 공탁금을 출급할 수 없다.","w":"확인판결이 있어도 채권양도는 채무자인 국가에 통지해야 대항력이 생긴다. 통지가 없으면 출급할 수 없다.","c":"중","v":1},"법무사2016_22-36-2":{"f":"공탁금 회수청구권의 양도통지가 검찰청을 거치지 않고 공탁관에게 직접 도달된 경우에도 그 통지는 효력이 있다.","w":"양도통지는 국가에 대한 통지이면 되고 반드시 검찰청을 거쳐야 하는 것은 아니다. 공탁관에게 직접 도달해도 효력이 있다.","c":"중","v":1},"법무사2016_22-36-4":{"f":"변제공탁의 경우 공탁관에게 도달된 공탁금 출급청구권의 양도통지서에 공탁수락의 의사표시가 명시적으로 기재되어 있지 않더라도 적극적인 불수락의 의사표시가 없다면, 그 양도통지서가 도달하면 그에 의하여 공탁자의 민법 제489조 제1항에 의한 회수청구권이 소멸된다고 볼 수 있다.","w":"양도통지서는 공탁수락의 의사를 포함한 것으로 본다. 불수락의 뜻이 없으면 도달과 동시에 공탁수락이 성립하여 공탁자의 회수청구권이 소멸한다.","c":"상","v":1},"법무사2016_22-36-5":{"f":"공탁물 출급청구권의 양도통지를 한 후 그 양도계약이 해제된 경우, 양도인이 일방적으로 해제사실을 통지하는 것만으로는 채무자 기타 제3자에게 대항할 수 없고 양수인이 동의하였다고 볼 사정이 있어야 한다.","w":"이미 한 양도통지를 양도인이 혼자서 철회하거나 해제를 통지해도 양수인이 동의했다고 볼 증거가 없으면 효력이 생기지 않는다.","c":"중","v":1},"법무사2020_26-32-4":{"f":"법인의 대표자가 직접 또는 다른 사람에게 위임하여 공탁물을 출급ㆍ회수청구하는 경우 출급ㆍ회수청구서와 위임장에 사용인감을 날인하고 사용인감확인서 및 법인의 인감증명서를 첨부하여 공탁금 출급ㆍ회수청구를 할 수 있다.","w":"법인의 사용인감 사용에는 법인의 인감증명서를 첨부한다. 법인 대표자 개인의 인감증명서가 아니다.","c":"중","v":1},"법무사2018_24-41-1":{"f":"절대적 불확지공탁을 한 경우 공탁자가 후에 피공탁자를 알게 되었는데도 공탁서를 정정하는 절차를 취하지 않을 경우에는 공탁자(국가가 아님)를 상대로 하여 공탁물 출급청구권이 자신에게 있다는 확인판결을 받은 자가 그 판결정본 및 확정증명서를 출급청구권을 증명하는 서면으로 첨부하여 공탁금을 직접 청구할 수 있다.","w":"공탁물 출급청구권 확인의 소는 공탁자를 상대로 해야 하고, 공탁관이 속한 국가는 확인의 상대방이 아니다. 이 확인판결과 확정증명서가 출급청구권을 증명하는 서면이 된다.","c":"중","v":1},"법무사2018_24-41-3":{"f":"매각허가결정에 대한 항고가 기각되기 전에 항고인의 공탁금 회수청구권에 대하여 압류 및 전부명령이 있었더라도 위 공탁금의 출급청구를 받은 공탁관으로서는 공탁금 회수청구권에 대한 압류 및 전부명령이 있었다는 이유로 그 출급을 거부할 수 없다.","w":"담보 성격의 항고보증공탁은 압류·전부명령이 있어도 출급을 거부할 수 없다는 취지로 정리돼 있다.","c":"중","v":1},"법무사2018_24-41-4":{"f":"피공탁자로부터 출급청구권을 양도받은 양수인은 공탁금 출급청구권을 양도받은 사실을 이유로 국가를 상대로 공탁금수령권한이 있다는 확인판결을 받은 것만으로는 공탁금을 출급할 수 없고 양도사실을 국가에 통지하여야 한다.","w":"확인판결은 대항요건을 대신하지 못한다. 양수인은 국가에 양도사실이 통지된 뒤에야 출급할 수 있다.","c":"중","v":1},"법무사2018_24-41-5":{"f":"배당이나 그 밖에 관공서의 지급위탁에 의하여 1,000만 원 이하의 공탁금을 지급받을 사람 본인이나 법정대리인이 직접 공탁물의 출급청구를 하는 경우에는 공탁통지서와 인감증명서는 제출하지 않아도 되지만, 법정대리인의 자격에 관한 증명서는 제출하여야 한다.","w":"본인이나 법정대리인이 1,000만원 이하를 직접 청구하고 신분증으로 확인되면 인감증명서는 내지 않아도 되고(공탁규칙 제37조 제3항 제1호), 공탁통지서도 생략 사유가 있다(제33조 제1호). 법정대리인의 자격을 증명하는 서면까지 생략되는 것은 아니다.","c":"중","v":1},"법무사2016_22-50-2":{"f":"동일한 청구자가 동일한 청구사유로 금전공탁과 물품공탁을 지급청구하는 경우에는 일괄청구를 할 수 없다.","w":"일괄청구는 공탁의 종류가 같은 경우에 허용되고 금전공탁과 물품공탁을 함께 청구하는 것은 허용되지 않는다.","c":"중","v":1},"법무사2016_22-45-1":{"f":"법인의 지배인은 인감증명서를 첨부하여야 하는 경우 지배인을 선임한 법인의 인감증명서와 지배인 사용인감확인서를 첨부하여 직접 공탁물 출급·회수를 할 수 있다.","w":"지배인을 선임한 주체는 법인이고 인감증명서는 법인의 것을 낸다. 법인 대표자 개인의 인감증명서가 아니다.","c":"중","v":1},"법무사2018_24-35-5":{"f":"임의대리인이 공탁금 1,000만 원 이하를 위임받아 청구하는 경우에는 본인의 인감증명서를 제출하여야 한다.","w":"인감증명서 제출을 생략할 수 있는 것은 본인이 직접 청구하는 경우이다. 임의대리인이 청구하면 위임을 확인하기 위해 본인의 인감증명서가 필요하다.","c":"상","v":1},"법무사2017_23-41-2":{"f":"토지수용보상금의 피공탁자가 공탁자에게 공탁금을 수령하지 아니한다는 의사를 표시하더라도, 공탁자는 민법 제489조에 따라 공탁금을 회수할 수 없다.","w":"수용보상금 공탁은 수용의 효력을 발생시키는 것이어서 피공탁자가 수령을 거절해도 공탁자는 회수할 수 없다.","c":"중","v":1},"법무사2016_22-31-4":{"f":"공탁물 회수청구권에 대한 압류 및 전부명령을 받은 자는 공탁물 회수청구 시 회수청구권을 갖는 것을 증명하는 서면을 제출하여야 한다.","w":"압류·전부명령을 받은 사람은 그 명령의 근거를 포함해 회수청구권을 갖는다는 증명서면을 내야 한다.","c":"상","v":1},"법무사2019_25-46-2":{"f":"혼합공탁에서 피공탁자가 공탁물의 출급을 청구하는 경우, 다른 피공탁자에 대한 관계에서뿐 아니라 집행채권자에 대한 관계에서도 공탁물출급청구권이 있음을 증명하는 서면을 구비·제출하여야 한다.","w":"혼합공탁은 두 종류의 공탁이 결합된 것이어서 피공탁자는 집행채권자와의 관계에서도 권리가 있음을 증명해야 한다.","c":"중","v":1},"법무사2021_27-38-5":{"f":"피공탁자 아닌 제3자가 피공탁자를 상대로 하여 공탁물출급청구권 확인판결을 받더라도 직접 공탁물출급청구를 할 수는 없다.","w":"확인판결만으로는 제3자가 직접 출급을 청구하지 못한다.","c":"중","v":1},"법무사2024_30-43-3":{"f":"변제공탁으로 인한 채권소멸의 효력을 소급적으로 소멸시키는 공탁물의 회수에는 공탁자에 의하여 이루어진 회수의 경우뿐 아니라, 제3자가 공탁자에 대하여 가지는 별도 채권의 집행권원으로써 공탁자의 회수청구권에 대하여 압류 및 추심명령을 받아 그 집행으로 공탁물을 회수한 경우도 포함된다.","w":"공탁자가 직접 회수한 경우만이 아니라 제3자가 압류·추심으로 회수한 경우도 공탁이 소급적으로 소멸하는 회수에 포함된다.","c":"중","v":1},"법무사2026_32-35-2":{"f":"공탁물출급청구권과 공탁물회수청구권 행사의 선후관계는 공탁관의 지급 인가 시점이 아니라 청구가 이루어진 시점을 기준으로 결정하여야 한다.","w":"출급청구와 회수청구 가운데 어느 쪽이 먼저인지는 공탁관이 인가한 때가 아니라 청구서가 접수된 때를 기준으로 정한다.","c":"중","v":1},"법무사2017_23-37-2":{"f":"제3채무자가 공탁관(국가)인 경우의 공탁금 회수청구권 또는 출급청구권 압류의 통지는 공탁관에게 직접 송달되어도 효력이 있다.","w":"국가를 제3채무자로 하는 압류·양도 통지는 공탁관에게 직접 송달되어도 효력이 있다.","c":"중","v":1},"법무사2020_26-36-1":{"f":"상속인 중의 1인이 다른 상속인들 중 일부로부터 출급청구권을 양도받아 공탁금 출급청구권자가 된 경우에는 공탁금 출급청구권을 양도받은 사실을 이유로 국가를 상대로 공탁금수령권한이 있다는 확인판결을 받았더라도 별도로 국가에 그 양도사실을 통지하여야 공탁금을 출급청구할 수 있다.","w":"확인판결을 받아도 국가에 양도사실을 통지해야 대항력이 생겨 출급청구를 할 수 있다.","c":"중","v":1},"법무사2026_32-40-1":{"f":"추심채권자가 집행채권을 제3자에게 양도한 경우 해당 추심채권자로서의 지위는 집행채권의 양도에 수반하여 양수인에게 이전된다.","w":"추심채권자의 지위는 집행채권에 부수하므로 집행채권을 양도하면 양수인에게 함께 이전된다.","c":"중","v":1},"법무사2019_25-50-1":{"f":"공탁소에 대한 공탁수락의 의사표시는 서면으로 하여야 한다.","w":"공탁소에 대한 공탁수락의 의사표시는 서면으로 해야 하며 구두로는 할 수 없다.","c":"중","v":1},"법무사2019_25-50-2":{"f":"공탁금출급청구의 경우와 마찬가지로 공탁금회수청구의 경우에도 인감증명서와 자격증명서면을 첨부하여야 한다.","w":"공탁물 출급청구뿐 아니라 회수청구를 하는 사람도 청구서 등에 찍힌 인감의 인감증명서를 제출해야 하고(공탁규칙 제37조 제1항), 대표자·대리인 등의 자격을 증명하는 서면도 같이 낸다.","c":"상","v":1},"법무사2019_25-50-4":{"f":"형사사건과 관련하여 보상금이 변제공탁된 후 피공탁자가 공탁금회수동의서를 공탁소에 제출한 경우에도 공탁금이 회수되지 않은 상태라면 피공탁자는 출급청구를 할 수 있다.","w":"피공탁자가 회수동의서를 제출했더라도 실제로 회수되기 전까지는 출급청구를 할 수 있다. 피공탁자가 회수에 동의하면 공탁자는 공탁법 제9조의2 제1항 제1호에 따라 회수할 수 있지만, 실제로 회수되기 전에는 피공탁자의 출급청구권이 남아 있다.","c":"중","v":1},"법무사2019_25-50-5":{"f":"청산금채권이 압류된 경우에 채권자(가등기담보권자)는 청산기간이 경과한 후 이에 해당하는 청산금을 공탁하여 그 범위에서 채무를 면할 수 있다. 채권자가 이와 같이 공탁을 한 경우에는 채무자등의 공탁금출급청구권이 압류된 것으로 본다.","w":"청산금을 공탁하면 압류의 효력은 채무자등의 공탁금출급청구권으로 옮겨 가고, 채권자는 공탁금을 회수할 수 없다(가등기담보 등에 관한 법률 제8조).","c":"상","v":1},"법무사2023_29-47-4":{"f":"공탁자에 대한 공탁수락의 의사표시는 구두나 서면으로 할 수 있으나 공탁소에 대한 공탁수락의 의사표시는 서면으로 하여야 한다.","w":"공탁자에게 하는 수락은 구두나 서면으로 가능하나, 공탁소에 하는 수락은 서면이어야 한다.","c":"중","v":1},"법무사2025_31-42-2":{"f":"상대적 불확지 변제공탁의 피공탁자 중 1인을 채무자로 하여 그의 공탁물출급청구권에 대하여 채권압류 및 추심명령을 받은 추심채권자는 공탁물을 출급하기 위하여 자기의 이름으로 다른 피공탁자를 상대로 공탁물출급청구권이 추심채권자의 채무자에게 있음을 확인한다는 확인의 소를 제기할 수 있다.","w":"추심채권자는 추심권능에 기초해 자기 이름으로 채무자의 권리를 확인하는 소를 제기할 수 있다.","c":"중","v":1},"법무사2020_26-49-5":{"f":"안내문은 공탁서 또는 공탁통지서를 대신하여 공탁금 출급·회수청구시의 첨부서류가 될 수 없다.","w":"소멸시효 완성 전에 보내는 안내문은 공탁서나 공탁통지서를 대신하는 첨부서류가 될 수 없다.","c":"중","v":1},"법무사2016_22-34-3":{"f":"매수인이 매도인을 상대로 토지소유권이전등기절차 이행의 승소판결을 받고 그에 따른 소유권이전등기를 수용의 개시일 이후에 경료한 경우, 그 매수인은 판결문과 등기사항증명서를 첨부하더라도 직접 공탁금 출급청구를 할 수 없다.","w":"수용개시일 이후에 이전등기를 마친 매수인은 사업시행자에게 소유권을 주장할 수 없어 공탁금을 직접 출급하지 못한다.","c":"상","v":1},"법무사2018_24-39-1":{"f":"사업시행자가 토지수용보상금을 공탁하고, 수용개시일 이후에 부동산소유권 이전등기 등에 관한 특별조치법에 의하여 이전등기를 마친 자는 공탁된 수용보상금을 직접 출급청구할 수 없다.","w":"수용개시일 이후에 특조법으로 이전등기를 마친 사람은 수용 당시의 소유자가 아니다. 수용보상금을 직접 출급청구하지 못한다.","c":"상","v":1},"법무사2018_24-39-3":{"f":"소유권이전등기의무의 목적 부동산이 수용되어 그 소유권이전등기의무가 이행불능이 된 경우, 수용보상금청구권 자체가 등기청구권자에게 당연히 귀속되는 것은 아니다.","w":"이행불능이 되어도 보상금청구권이 등기청구권자에게 자동으로 넘어가지 않는다. 등기청구권자는 대상청구권을 행사해 넘겨받아야 한다.","c":"상","v":1},"법무사2018_24-39-4":{"f":"공탁자가 토지를 수용하면서 가처분권자가 있어서 그 토지의 합유자들과 위 가처분권자를 피공탁자로 한 상대적 불확지공탁을 한 경우에 합유자들은 공탁 이후의 가처분취하증명원이 아니라 가처분권자의 승낙서(인감증명서 첨부) 등을 첨부하여야 공탁금을 출급할 수 있다.","w":"가처분을 취하했다는 증명만으로는 출급청구권이 있음이 증명되지 않는다. 가처분권자의 승낙서에 인감증명서를 붙여 낸다.","c":"상","v":1},"법무사2018_24-39-5":{"f":"종중이 명의수탁자를 피고로 하여 명의신탁의 해지를 이유로 공탁금 출급청구권 확인판결을 받았더라도 종중은 그 판결에 기하여 직접 공탁금 출급청구를 할 수는 없다.","w":"수용보상금의 피공탁자는 수용 당시 등기부상 소유자인 수탁자이다. 종중이 신탁 해지로 받은 확인판결만으로는 직접 출급하지 못한다.","c":"중","v":1},"법무사2021_27-32-2":{"f":"수용보상금의 공탁서에 공탁물을 수령할 자로 甲, 乙로 기재되어 있다면, 甲은 수용대상토지가 자신의 단독 소유임을 증명하는 서류를 첨부하더라도 단독으로 공탁관에게 공탁금출급청구를 할 수 없다.","w":"공탁서에 피공탁자로 기재된 사람들이 기준이다. 일방이 단독 소유임을 증명하는 서류로는 공탁서 기재를 바꿀 수 없다.","c":"중","v":1},"법무사2021_27-32-3":{"f":"사업시행자가 이미 사망한 사람을 피공탁자로 하여 공탁하였더라도 이는 상속인들에 대한 공탁으로서 유효하므로, 그 피공탁자의 상속인들이 직접 공탁금을 출급청구할 수 있다.","w":"사망한 사람을 피공탁자로 한 공탁도 상속인들에 대한 공탁으로서 유효하여 상속인들이 직접 출급청구를 할 수 있다.","c":"중","v":1},"법무사2021_27-32-4":{"f":"매수인이 매도인을 상대로 매매를 원인으로 한 토지소유권이전등기 절차 이행의 승소판결을 받았으나 그에 따른 소유권이전등기를 마치지 않고 있던 중 사업시행자가 해당 토지를 수용하고 매도인 앞으로 수용보상금을 공탁함으로써 수용의 효력이 발생한 경우 그 수용을 원인으로 한 소유권이전등기가 마쳐지기 전에 매수인이 자기 명의로 소유권이전등기를 마쳤다 하더라도 그 매수인은 직접 공탁금의 출급청구를 할 수 없다.","w":"수용개시일 이후에 이전등기를 마친 매수인은 수용 당시 소유자가 아니므로 직접 출급청구를 할 수 없다.","c":"중","v":1},"법무사2021_27-32-5":{"f":"종중이 수용대상 토지에 관한 명의신탁을 해지하였으나 수용시기 전에 소유권등기를 회복하지 못했다면, 종중이 명의수탁자를 상대로 명의신탁의 해지를 이유로 공탁금 출급청구권 확인판결을 받았더라도 종중은 위 확인판결에 기하여 직접 공탁금 출급청구를 할 수 없다.","w":"명의신탁 해지로 종중이 받은 확인판결만으로는 수용 당시 소유자가 아닌 종중이 직접 출급하지 못한다.","c":"중","v":1},"법무사2026_32-43-2":{"f":"사업시행자가 토지의 일부를 수용하고 수용보상금을 그 토지의 공유자 전원을 피공탁자로 하여 공탁한 경우에는 공유토지에 대한 수용보상 공탁금이 가분채권이므로 공유자 각자가 자기의 등기부상 지분에 해당하는 공탁금을 출급청구할 수 있다.","w":"보상금채권은 가분채권이어서 공유자는 각자의 지분에 해당하는 공탁금을 단독으로 청구할 수 있다.","c":"상","v":1},"법무사2017_23-43-1":{"f":"재외국민이 귀국하여 직접 공탁금 지급청구를 하는 때에는 주소를 소명할 필요가 있는 경우 재외국민등록부 등본이나 주민등록표 등·초본 등을 제출하게 할 수 있다.","w":"재외국민의 주소는 재외국민등록부등본, 주민등록표 등·초본, 재외공관이 없는 나라에서는 체류국 공증인이 공증한 서면으로 소명한다(「재외국민 등의 공탁에 관한 업무처리지침」 제6조 제1항). 국내거소신고 사실증명은 외국인의 주소 소명서면이다.","c":"중","v":1},"법무사2016_22-38-5":{"f":"보상금에 대하여 다른 일반채권자가 먼저 가압류나 압류의 집행을 하였더라도 담보물권자는 물상대위권을 행사하여 우선변제를 받을 수 있다.","w":"담보물권자는 보상금이 지급되기 전에 압류하는 방법으로 물상대위권을 행사할 수 있고, 다른 채권자의 앞선 압류 때문에 우선권을 잃지 않는다.","c":"중","v":1},"법무사2017_23-35-5":{"f":"저당권에 기한 물상대위권을 갖는 채권자가 동시에 집행권원을 가지고 있으면서 집행권원에 의한 강제집행의 방법을 선택하여 채권의 압류 및 전부명령을 얻은 경우, 그 전부명령이 압류가 경합된 상태에서 발부되었다면 이를 무효로 본다.","w":"물상대위권자가 일반 집행권원으로 강제집행을 선택하면 일반 채권자와 같은 지위에 있다. 압류가 경합된 상태에서 얻은 전부명령은 무효이다.","c":"중","v":1},"법무사2022_28-32-5":{"f":"위 공탁이 성립한 후 乙은 가압류의 효력이 소멸하였음을 증명하는 서면을 첨부하여야 공탁금을 출급할 수 있다.","w":"가압류를 원인으로 한 집행공탁에서 가압류의 효력은 乙의 공탁금출급청구권에 그대로 미친다. 집행채권액 2천만 원이 공탁금 1천만 원을 넘어 전액이 가압류된 상태이므로, 乙은 가압류의 해제나 취소를 증명해야 출급할 수 있다.","c":"중","v":1},"법무사2017_23-49":{"w":"1번이 틀리다. 공탁소 외의 기관·법인·단체가 전자본인서명확인서를 열람한 사실이 확인되면 그 확인서는 지정된 용도 외로 사용된 것이어서 공탁관은 해당 청구를 수리하지 않는다.","c":"중","v":1},"법무사2018_24-36":{"w":"3번이 틀리다. 형사재판 과정에서 피공탁자가 공탁금 수령을 거절했다는 사정만으로는 공탁금 회수에 동의한 것으로 보지 않는다. 지금은 공탁법 제9조의2 제1항에 따라 형사사건 피해자를 위한 변제공탁은 민법 제489조(공탁법 제9조 제2항 제1호)로 회수할 수 없다. 피공탁자가 회수에 동의하거나 수령거절 의사를 공탁소에 통고한 경우, 무죄판결이 확정되거나 불기소 결정(기소유예 제외)이 있는 경우에만 회수할 수 있다.\n2번 토지수용보상금 공탁은 간접적으로 강제된 공탁이라 민법 제489조의 회수가 허용되지 않는다. 5번 공탁사유신고가 불수리되면 착오공탁으로 보아 공탁법 제9조 제2항 제2호로 회수할 수 있다.","c":"상","v":1},"법무사2019_25-32":{"w":"3번이 틀리다. 소멸시효가 완성된 공탁금은 국고에 귀속하기 전이라도 출급·회수청구를 인가해서는 안 된다(공탁규칙 제61조).\n1번 시효완성 뒤 착오로 공탁사실증명서를 교부하면 시효이익을 포기한 것으로 처리한다(행정예규 제948호). 2번 지급절차를 일반적으로 설명한 것은 시효중단 사유가 아니다. 5번은 공탁법 제9조 제4항 그대로이다.","c":"상","v":1},"법무사2019_25-35":{"w":"A 없다, B 있다, C 없다, D 없다, E 없다.\nA 형사재판 과정에서 한 수령거절 의사표시는 회수 동의로 보지 않는다. 지금은 공탁법 제9조의2 제1항이 형사사건 피해자를 위한 변제공탁의 민법 제489조 회수를 막는다.\nB 피공탁자가 회수동의서를 냈더라도 공탁자가 회수하기 전이면 피공탁자의 출급청구를 인가한다.\nC 출급청구권 양도통지서가 도달하면 공탁수락의 의사표시가 있는 것으로 보아 회수할 수 없다.\nD 공탁으로 저당권이 소멸한 경우에는 민법 제489조 제1항의 회수를 적용하지 않는다(같은 조 제2항).\nE 피공탁자가 공탁수락서를 제출했으므로 민법 제489조로는 회수할 수 없다. 차액은 공탁원인 소멸(공탁법 제9조 제2항 제3호)로 회수할 문제이다.","c":"상","v":1},"법무사2019_25-41":{"w":"5번이 틀리다. 자격자대리인(변호사·법무사)이 출급·회수청구를 대리하는 경우에는 자격자대리인 명의의 보증서만 내면 되고 재산증명서와 신분증 사본은 필요하지 않다.","c":"하","v":1},"법무사2020_26-38":{"w":"옳은 것은 ㄱ뿐이다.\nㄱ O. 사업시행자가 발행하는 채권(債券)으로 공탁된 경우 전부채권자는 이를 직접 출급청구할 수 없다.\nㄴ X. 집행채권의 양수인은 다시 압류·추심명령을 받을 필요 없이 승계집행문을 받아 출급청구할 수 있다.\nㄷ X. 전부명령이 확정되면 경합은 소멸하고 전부채권자의 출급청구를 허용한다.\nㄹ X. 압류금지채권을 변제공탁한 경우에도 압류금지의 성질이 유지되어 전부채권자가 출급할 수 없다.","c":"하","v":1},"법무사2022_28-33":{"w":"정답은 4번 ㄴ, ㄷ이다. 공탁규칙 제37조 제3항 제1호는 본인이 직접 청구하고 금액이 1,000만 원 이하이며 신분증으로 본인임을 확인할 수 있으면 인감증명서 제출을 면제한다. 이 금액은 이자를 뺀 공탁서상 공탁금액으로 따진다. 피공탁자가 여럿이면 각자의 지분액으로 따진다.\nㄱ 친구가 위임을 받아 대리 청구하므로 면제되지 않는다.\nㄴ 공탁금액이 990만 원이므로 이자를 더해 1,000만 원을 넘어도 면제된다.\nㄷ 乙의 지분액이 750만 원이므로 면제된다.\nㄹ 공탁금액이 2,000만 원이면 일부만 청구해도 면제되지 않는다.\nㅁ 유가증권 총 액면금액이 2,000만 원이라 면제되지 않는다.","c":"중","v":1},"법무사2022_28-41":{"w":"정답은 1번 ㄴ, ㅁ이다. 공탁규칙 제34조 제1호에 따라 회수청구 금액(유가증권은 총 액면금액)이 5,000만 원 이하이면 공탁서를 첨부하지 않아도 된다. 청구인이 관공서이거나 법인 아닌 사단·재단이면 1,000만 원 이하여야 한다. 강제집행이나 체납처분에 따른 회수청구도 공탁서가 필요 없다.\nㄱ 6,000만 원이라 면제되지 않는다.\nㄴ 액면 4,000만 원이라 면제된다.\nㄷ·ㄹ 비법인사단과 관공서(용인시)는 1,000만 원을 넘으므로 면제되지 않는다.\nㅁ 압류·추심채권자의 회수청구는 강제집행에 따른 청구라 면제된다.","c":"상","v":1},"법무사2025_31-34":{"w":"2번이 틀리다. 채권자가 공탁을 승인하거나 수령을 통고하거나 공탁유효의 판결이 확정되기 전에 변제자가 공탁물을 회수하면 공탁하지 않은 것으로 본다(민법 제489조 제1항).","c":"상","v":1},"법무사2018_24-45":{"w":"4번이 틀리다. 미성년자는 단독으로 출급청구를 할 수 없고 법정대리인이 대리해야 한다.","c":"중","v":1},"법무사2019_25-36":{"w":"5번이 틀리다. 공탁법 제12조의 이의신청으로 다툴 수 있는 것은 공탁관의 불수리 처분이다. 이미 수리하거나 인가한 처분은 이의신청 대상이 아니다.\n1번은 공탁법 제12조, 3번은 제13조 제2항 그대로이다.","c":"중","v":1},"법무사2019_25-42":{"w":"(2025 예규 개정 전 기준) 출제 당시에는 ㄱ부터 ㅁ까지 모두 옳아 정답이 5번이었다. ㄱ은 공탁법 제5조 제1항(대법원 소재지 공탁소), ㄴ은 날인 제도가 없는 나라 외국인의 서명, ㄹ은 재외국민 상속재산 분할협의서의 인감증명을 재외공관 인증이나 공정증서로 대신하는 것, ㅁ은 외국 공문서의 영사확인·아포스티유이다.\n지금의 「재외국민 등의 공탁에 관한 업무처리지침」(행정예규 제1431호) 제8조는 재외국민에게 「인감증명법」에 따른 인감증명서를 내게 하고 위임장에 재외공관 인증을 받으면 이를 갈음하게 한다. 일본 관공서가 발행한 인감증명을 첨부하는 ㄷ의 방법은 이 지침에 없다.","c":"중","v":1,"old":1,"ow":"(2025 예규 개정 전 기준) 출제 당시에는 ㄱ부터 ㅁ까지 모두 옳아 정답이 5번이었다. ㄱ은 공탁법 제5조 제1항(대법원 소재지 공탁소), ㄴ은 날인 제도가 없는 나라 외국인의 서명, ㄹ은 재외국민 상속재산 분할협의서의 인감증명을 재외공관 인증이나 공정증서로 대신하는 것, ㅁ은 외국 공문서의 영사확인·아포스티유이다.\n지금의 「재외국민 등의 공탁에 관한 업무처리지침」(행정예규 제1431호) 제8조는 재외국민에게 「인감증명법」에 따른 인감증명서를 내게 하고 위임장에 재외공관 인증을 받으면 이를 갈음하게 한다. 일본 관공서가 발행한 인감증명을 첨부하는 ㄷ의 방법은 이 지침에 없다."},"법무사2020_26-33":{"w":"정답은 5번(ㄱ부터 ㅁ 모두)이다.\nㄱ 공탁규칙 제21조 제3항 그대로이다.\nㄴ 처분금지가처분권자가 권리 귀속을 다투면 가처분채무자 또는 가처분채권자를 피공탁자로 하는 상대적 불확지공탁을 할 수 있다.\nㄷ 수용대상토지의 담보물권자·가압류채권자·경매신청인은 피공탁자로 기재하지 않는다.\nㄹ 압류된 채권액만 집행공탁하는 경우 피공탁자란은 기재하지 않는다.\nㅁ 가압류를 원인으로 한 제3채무자의 집행공탁은 가압류채무자를 피공탁자로 기재한다.","c":"중","v":1},"법무사2021_27-40":{"w":"정답은 5번 ㄱ, ㄹ, ㅁ이다. 공탁규칙 제2조는 시·군법원 공탁관의 직무를 해당 시·군법원 사건과 관련된 소액사건 등의 변제공탁, 재판상 보증공탁, 민사집행법 제282조의 가압류해방금액 공탁, 민사소송법 제299조 제2항의 소명에 갈음하는 보증금 공탁으로 한정한다. 압류 경합이나 가압류를 이유로 한 민사집행법 제248조 집행공탁(ㄴ, ㄷ)은 여기에 없다.","c":"상","v":1},"법무사2023_29-41":{"w":"옳은 것은 ㄱ, ㄷ, ㅁ이다.\nㄱ 공탁소에 출석해야 하는 것은 예규로 정한 법인회원과 변호사·법무사회원이다(공탁규칙 제70조 제3항·제4항). 개인회원은 출석하지 않고 등록한다.\nㄴ X. 5,000만 원을 넘는 공탁금의 출급·회수청구는 전자공탁시스템으로 할 수 없다(공탁규칙 제69조 단서).\nㄷ 공탁신청에는 이런 금액 제한이 없다.\nㄹ X. 변호사·법무사회원이 전자문서로 출급·회수를 청구하면 청구인의 전자서명도 함께 제출해야 한다(공탁규칙 제79조 제2항).\nㅁ 출급청구서를 출력해 보관은행에 내고 받을 수 있다.","c":"상","v":1},"법무사2017_23-39":{"w":"(2023 예규 개정 전 기준) 출제 당시 예규는 ㄱ부터 ㅁ까지 모두 절대적 불확지공탁 사례로 보아 정답이 4번이었다.\n지금의 「토지수용 등의 보상금의 공탁에 관한 사무처리지침」 제6조는 미등기토지의 대장상 소유자란이 공란인 경우(ㄱ), 성명만 있고 주소(번지 포함)가 없는 경우(ㄴ), 등기기록상 소유자를 특정할 수 없는 경우(ㄷ), 상속인의 전부나 일부를 알 수 없는 경우를 절대적 불확지공탁으로 둔다. 상속인은 알지만 정당한 상속지분을 모르는 경우는 제5조 제1항 제4호에 따라 상속인 전부를 피공탁자로 하는 상대적 불확지공탁을 한다. 그래서 ㅁ을 통째로 절대적 불확지공탁 사례라고 할 수 없다.","c":"하","v":1,"old":1,"ow":"(2023 예규 개정 전 기준) 출제 당시 예규는 ㄱ부터 ㅁ까지 모두 절대적 불확지공탁 사례로 보아 정답이 4번이었다.\n지금의 「토지수용 등의 보상금의 공탁에 관한 사무처리지침」 제6조는 미등기토지의 대장상 소유자란이 공란인 경우(ㄱ), 성명만 있고 주소(번지 포함)가 없는 경우(ㄴ), 등기기록상 소유자를 특정할 수 없는 경우(ㄷ), 상속인의 전부나 일부를 알 수 없는 경우를 절대적 불확지공탁으로 둔다. 상속인은 알지만 정당한 상속지분을 모르는 경우는 제5조 제1항 제4호에 따라 상속인 전부를 피공탁자로 하는 상대적 불확지공탁을 한다. 그래서 ㅁ을 통째로 절대적 불확지공탁 사례라고 할 수 없다."},"법무사2018_24-34":{"w":"옳은 것은 ㄱ, ㄴ이다.\nㄱ 피공탁자가 특정되려면 공탁관의 판단이 개입할 여지가 없고 통지서 송달에 지장이 없어야 한다.\nㄴ 이 사례는 절대적 불확지공탁이 허용된다.\nㄷ X. 불확지공탁으로 피공탁자 지정의무를 다한 것이 아니다.\nㄹ X. 진정한 수령권자는 공탁자를 상대로 한 확인판결로 출급청구를 할 수 있다.","c":"하","v":1},"법무사2018_24-42":{"w":"A 유효하다, B 유효하다, C 무효이다, D 없다, E 없다.\n어음 반환과 전세권 말소는 채무 변제와 동시이행 관계에 있어 반대급부 조건이 유효하다. 건물 명도 확인서를 요구하는 조건은 무효이고, 임차권등기 말소나 채권증서 반환을 반대급부로 하는 공탁은 할 수 없다.","c":"하","v":1},"법무사2019_25-44":{"w":"정답은 4번 ㄱ, ㄷ, ㄹ, ㅁ이다.\nㄱ 양도통지가 철회되는 등으로 양도 여부가 불분명하면 채권자 불확지 변제공탁을 할 수 있다.\nㄴ X. 이중양수인 사이의 우열은 확정일자의 선후가 아니라 확정일자 있는 통지가 채무자에게 도달한 일시(또는 확정일자 있는 승낙의 일시)의 선후로 정한다(대법원 1994. 4. 26. 선고 93다24223 전원합의체 판결).\nㄷ 양도금지 특약이 있는 채권도 전부명령으로 전부채권자의 선의·악의를 묻지 않고 이전되므로 불확지공탁을 할 수 없다.\nㄹ 사해행위취소에 따른 원상회복청구권을 피보전권리로 한 처분금지가처분이면 가처분채무자를 피공탁자로 지정해 공탁한다.\nㅁ 증권예탁결제원이 선량한 관리자의 주의를 다해도 주권을 반환할 상대방을 알 수 없으면 채권자 불확지 변제공탁을 할 수 있다.","c":"하","v":1},"법무사2022_28-44":{"w":"5번이다. 사업시행자가 상속등기 대위신청 비용을 공제하고 일부만 공탁한 것은 유효한 변제공탁이 되지 않는다.","c":"중","v":1},"법무사2024_30-49":{"w":"5번이 틀리다. 채권자가 수령을 거절할 것이 명백히 예상되는 경우에는 이행의 제공 없이도 변제공탁을 할 수 있다.","c":"중","v":1},"법무사2017_23-40":{"w":"옳지 않은 것은 ㄹ, ㅁ이다.\nㄹ X. 금전채권의 일부만 압류되어도 전액을 공탁할 수 있고, 압류 효력이 미치지 않는 부분에 별도의 변제공탁 사유가 있어야 하는 것이 아니다.\nㅁ X. 700만 원만 압류했더라도 제3채무자는 1,000만 원 전액을 공탁할 수 있다(민사집행법 제248조 제1항).","c":"하","v":1},"법무사2018_24-32":{"w":"3번이 옳다. 피공탁자가 직접 출급청구를 하는 경우에는 공탁원인 사실에 기재된 피담보채권이 발생했음을 증명하는 서면이 제출되어야 공탁금을 지급한다.","c":"중","v":1},"법무사2018_24-40":{"w":"5번이 옳다. 재판상 담보공탁에서 공탁자의 채권자가 한 회수청구권 압류가 경합된 경우, 공탁원인 소멸을 증명하는 서면이 제출되면 먼저 송달된 압류명령의 집행법원에 사유신고를 한다.","c":"하","v":1},"법무사2019_25-38":{"w":"정답은 2번 ㄱ, ㄴ, ㄷ이다.\nㄱ 체납처분에 의한 압류도 민사집행법 제229조 제5항의 '다른 채권자의 압류', 제236조 제2항의 '다른 압류'에 해당한다.\nㄴ 체납처분 압류 뒤에 가압류가 경합했다는 사유로는 제3채무자가 변제공탁이나 집행공탁을 할 수 없다.\nㄷ 가압류를 원인으로 집행공탁한 뒤 체납처분 압류통지가 오면 체납처분 압류채권자의 추심청구를 공탁관이 거절할 수 없다.\nㄹ X. 가압류의 집행채권이 우선변제권 있는 임금채권이어도 가압류만으로는 우선변제를 받지 못하므로 추심청구를 거절할 수 없다.\nㅁ X. 가압류와 체납처분 압류가 경합했다는 이유의 사유신고에는 배당요구를 차단하는 효력이 없다.","c":"중","v":1},"법무사2019_25-45":{"w":"3번이 옳다. 가압류채무자가 집행취소를 신청하려면 가압류명령에서 정한 해방금액 전부를 공탁해야 한다. 일부만 공탁하고 가압류집행의 일부 취소를 구할 수는 없다.\n1번 가압류의 효력은 해방공탁금 자체가 아니라 채무자의 공탁금 회수청구권에 미친다. 2번 가압류된 부동산의 제3취득자는 해방공탁을 할 수 없다. 4번 해방공탁으로 가압류등기가 말소되어도 이미 진행 중인 강제경매개시결정을 취소할 사유가 되지 않는다.","c":"중","v":1},"법무사2019_25-47":{"w":"정답은 4번 ㄱ, ㄴ, ㄷ, ㄹ이다. 가압류끼리 경합, 가압류와 체납처분의 경합, 양도 후의 경합은 공탁관이 사유신고를 하지 않는 경우이다. 체납처분 압류가 선행하고 강제집행 압류가 후행하는 경우(ㅁ)에는 사유신고를 한다.","c":"하","v":1},"법무사2020_26-31":{"w":"정답은 1번 ㄱ, ㄴ이다.\nㄱ 압류된 1억 원만 민사집행법 제248조 제1항으로 공탁하면 피공탁자란은 기재하지 않는다.\nㄴ 집행공탁을 하면 압류명령을 발령한 법원에 반드시 사유신고를 해야 한다.\nㄷ X. 처분금지가처분은 금전채권의 압류가 아니어서 제248조 제1항 집행공탁 사유가 되지 않는다.\nㄹ·ㅁ X. 사유신고로 배당절차가 시작된 뒤에는 공탁금이 집행법원의 지급위탁으로만 지급된다. 압류가 실효되어도 甲이 공탁원인 소멸로 회수하거나 乙이 공탁관에게 직접 출급청구할 수 없다.","c":"중","v":1},"법무사2020_26-41":{"w":"3번이 옳다. 항고인용 재판이 확정되면 공탁자는 공탁서와 그 확정을 증명하는 서면을 첨부해 보증금을 회수하고 담보취소절차는 필요 없다(행정예규 제980호 제2조).\n1번 법원이 인정한 유가증권으로도 보증을 제공할 수 있다(민사집행법 제130조 제3항). 2번 채무자나 소유자가 한 항고가 기각되면 보증으로 제공한 금전 전부가 배당할 금액에 포함된다(민사집행법 제147조 제1항 제3호). 4번 항고 기각 뒤 경매신청이 취하되면 보증이 배당할 금액에 포함될 필요가 없어져 반환받을 수 있다. 5번 그 보증이 배당할 금액에 포함될 필요가 없게 되었음을 증명하는 서면으로도 회수할 수 있다(같은 예규 제2조).","c":"상","v":1},"법무사2021_27-31":{"w":"정답은 2번 ㄴ, ㄷ이다.\nㄱ X. 압류채권액 합계 1,500만 원을 넘는 500만 원 부분은 변제공탁의 성질을 가지므로 피공탁자란에 乙을 기재한다.\nㄴ 압류가 여럿이면 먼저 송달된 압류명령(丙)을 발령한 집행법원에 사유신고한다.\nㄷ 압류 효력이 미치지 않는 500만 원 부분은 민법 제489조 제1항으로 회수할 수 있다.\nㄹ X. 乙이 지급위탁 없이 출급할 수 있는 것은 압류 효력이 미치지 않는 500만 원 부분이다. 압류된 1,500만 원은 집행법원의 절차를 거쳐야 한다.\nㅁ X. 戊의 압류는 압류 효력이 미치지 않는 부분의 출급청구권에 대한 단독 압류라 경합이 없으므로 사유신고 대상이 아니다.","c":"중","v":1},"법무사2022_28-31":{"w":"2번이 틀리다. 몰수보전이 된 뒤 (가)압류명령을 송달받아 공탁한 경우에는 공탁서를 몰수보전명령을 발한 법원에 제출한다. (가)압류된 금전채권에 몰수보전이 있어 공탁한 경우에는 공탁서를 (가)압류명령을 발한 법원에 제출한다. 두 경우 모두 몰수보전 법원에 제출하는 것이 아니다.\n1번은 제3채무자의 공탁, 3번은 추징보전 채권의 공탁으로 피고인의 출급청구권에 추징보전이 집행된 것으로 보는 규정, 4번·5번은 추징보전해방금 공탁 후 추징재판이 확정된 경우의 처리 그대로이다.","c":"중","v":1},"법무사2022_28-40":{"w":"정답은 2번 ㄱ, ㄴ, ㄷ, ㅁ이다. 용인시는 자기 압류분 10만 원을, 乙은 압류 없는 60만 원을 직접 출급청구할 수 있고, 丙은 집행법원의 지급위탁에 따라 받는다.","c":"하","v":1},"법무사2023_29-32":{"w":"정답은 4번 ㄷ, ㄹ이다.\nㄱ X. 가압류가 효력을 유지하는 동안 피공탁자 乙은 공탁금을 출급할 수 없다.\nㄴ X. 집행공탁은 민법 제489조로 회수할 수 없다.\nㄷ 가압류채무자 乙의 공탁금출급청구권에 대한 압류로 압류가 경합하면 공탁관은 집행법원에 사유신고를 한다(행정예규 제1225호 1. 나. (1)).\nㄹ 가압류 집행공탁 뒤 체납처분 압류통지가 오면 고양시는 공탁금을 직접 출급청구할 수 있다.\nㅁ X. 가압류를 본압류로 이전하는 압류명령이 오면 공탁관이 사유신고를 하므로 丙은 집행법원의 지급위탁으로 받는다.","c":"상","v":1},"법무사2023_29-34":{"w":"정답은 1번이다. ㄱ, ㄴ, ㄹ, ㅁ, ㅂ은 압류 등이 경합해도 사유신고 대상이 아니고, 체납처분 압류가 선행하고 강제집행 압류가 후행한 경우(ㄷ)만 사유신고 대상이다.","c":"하","v":1},"법무사2023_29-42":{"w":"정답은 3번 ㄱ, ㄹ이다.\nㄱ 혼합공탁은 민법 제487조 후단과 민사집행법 제248조 제1항을 근거법령으로 하고 피공탁자란에는 양도인 乙 또는 양수인 丙을 기재한다. 집행채권자 丁은 기재하지 않는다(금전채권의 혼합공탁에 관한 사무처리지침 제5조).\nㄴ X. 압류명령을 이유로 혼합공탁을 하면 공탁관이 아니라 제3채무자 甲이 지체 없이 압류명령 발령법원에 사유신고를 한다(같은 지침 제7조 제1항).\nㄷ X. 집행채권자 丁은 집행법원의 지급위탁절차로 출급한다(같은 지침 제9조 제3항).\nㄹ 피공탁자 丙은 다른 피공탁자 乙과 압류채권자 丁을 상대로 한 확인판결을 첨부해 직접 출급할 수 있다(같은 지침 제9조 제1항).","c":"상","v":1},"법무사2023_29-48":{"w":"정답은 2번 ㄴ, ㄹ이다.\nㄱ X. 가압류해방공탁은 금전으로만 한다.\nㄴ 가압류해방공탁은 가압류채무자만 할 수 있고 제3자가 대신 할 수 없다.\nㄷ X. 가압류와 체납처분에 의한 압류만 있는 경우는 사유신고 대상이 아니다(행정예규 제1225호 1. 다.). 사유신고를 하더라도 가압류 발령법원이 아니라 압류 발령법원에 한다.\nㄹ 공탁금 회수청구권에 대한 압류가 가압류와 경합하면 압류명령을 발령한 집행법원에 사유신고를 한다.","c":"상","v":1},"법무사2024_30-45":{"w":"정답은 3번 ㄴ, ㄹ이다.\nㄱ X. 丁이 압류나 배당요구를 하지 않았다면 乙에게 공탁할 의무가 없다.\nㄴ 배당요구서를 송달받은 제3채무자는 압류된 부분에 해당하는 금액을 공탁해야 하므로(민사집행법 제248조 제2항) 600만 원이다.\nㄷ X. 압류 범위를 제한하지 않았으면 압류 효력이 채권 전액에 미치므로 1,000만 원을 공탁해야 한다.\nㄹ 丁의 압류는 압류되지 않은 부분(400만 원)을 넘는 거듭된 압류이다. 압류채권자가 청구하면 제3채무자는 채권 전액 1,000만 원을 공탁해야 한다(민사집행법 제248조 제3항).\n문항의 '민사소송법 제248조'는 민사집행법 제248조를 가리킨다.","c":"상","v":1},"법무사2025_31-32":{"w":"정답은 2번 ㄴ, ㄷ이다.\nㄱ X. 가집행이 지연되어 생긴 손해에는 집행정지 기간 동안의 지연손해금 상당 손해도 포함되므로 강제집행정지 담보공탁의 피담보채권이 될 수 있다.\nㄴ 피담보채권을 집행채권으로 회수청구권을 압류한 담보권리자의 담보취소신청은 담보권 실행의 방법으로 본다.\nㄷ 최고를 받은 담보권리자가 담보공탁금 일부에 대해서만 권리를 행사하면 초과 부분은 담보취소에 동의한 것으로 보아 일부 담보를 취소한다.\nㄹ X. 제3자도 당사자를 대신해 공탁한다는 뜻을 공탁서에 적고 담보를 공탁할 수 있다.","c":"중","v":1},"법무사2016_22-01":{"w":"5번이다. 전세권, 구분지상권, 저당권부채권에 대한 근질권은 부동산등기법상 등기할 수 있는 권리이다. 유치권, 점유권, 분묘기지권, 사용대차권은 등기할 수 없다.","c":"상","v":1},"법무사2016_22-02":{"w":"2번이다. 기타 문서 접수장은 10년, 신청서 기타 부속서류 편철장은 5년이다(부동산등기규칙 제25조 제1항).\n1번 신탁원부·매매목록과 5번 도면·공동담보목록은 모두 영구 보존한다. 3번 결정원본 편철장과 이의신청서류 편철장은 모두 10년, 4번 열람신청서류 편철장과 제증명신청서류 편철장은 모두 1년이다.","c":"상","v":1},"법무사2016_22-03":{"w":"5번이다. 각하결정 원본은 신청서 기타 부속서류 편철장이 아니라 결정원본 편철장에 편철한다.","c":"중","v":1},"법무사2020_26-20":{"w":"4번이다. 소유권이전청구권보전 가등기는 소유권 변경이 아니어서 지적소관청이나 건축물대장 소관청에 알리지 않는다.","c":"중","v":1},"법무사2020_26-28":{"w":"2번 접수번호는 표제부에 기록하지 않는다. 토지 표제부에는 표시번호, 접수연월일, 소재와 지번, 지목, 면적, 등기원인 및 기타사항을 기록한다.","c":"중","v":1},"법무사2022_28-11":{"w":"1번이다. 채권담보권과 부동산환매권은 부동산등기법상 등기할 수 있다. 유치권과 분묘기지권은 등기할 수 없다.","c":"중","v":1},"법무사2023_29-03":{"w":"5개가 모두 옳다.\nA 소유권보존등기를 말소하면 그 등기기록을 폐쇄한다.\nB 폐쇄한 등기기록은 영구 보존한다(부동산등기법 제20조 제2항).\nC 폐쇄할 때에는 표제부의 등기를 말소하는 표시를 하고 등기원인 및 기타사항란에 폐쇄의 뜻과 연월일을 기록한다.\nD 중복등기기록 정리 요건 그대로이다.\nE 등기기록을 옮길 때에는 현재 효력이 있는 등기만 새 등기기록에 옮겨 기록할 수 있다(부동산등기법 제33조).","c":"중","v":1},"법무사2023_29-10":{"w":"3번이다. 신청서 기타 부속서류 송부부는 나머지 장부와 보존기간이 다르다.","c":"하","v":1},"법무사2024_30-15":{"w":"부기로 하는 등기는 ㄱ, ㅂ 2개이다.\nㄱ 소유권 외의 권리를 목적으로 하는 권리에 관한 등기는 부기로 한다(부동산등기법 제52조 제3호).\nㄴ 소유권에 대한 처분제한 등기는 주등기이다. 부기로 하는 것은 소유권 외의 권리에 대한 처분제한 등기이다(같은 조 제4호).\nㄷ 권리의 변경등기는 이해관계 있는 제3자의 승낙이 없으면 주등기로 한다(같은 조 단서).\nㄹ 신탁등기는 주등기이다.\nㅁ 가등기에 의한 본등기는 가등기의 순위번호를 사용해 하는 것이지 부기로 하지 않는다.\nㅂ 일부 등기사항만 말소된 경우의 회복등기는 부기로 한다(부동산등기규칙 제118조 단서).","c":"상","v":1},"법무사2025_31-26":{"w":"1번이 틀리다. 도로법 제4조와 하천법 제4조 제2항은 도로·하천에 사권을 행사할 수 없게 하면서 소유권 이전과 저당권 설정만 예외로 둔다. 그래서 소유권이전·저당권설정 등기는 할 수 있어도 지상권설정등기는 할 수 없다.\n2번은 등기능력 있는 물건 여부의 판단에 관한 업무처리지침 내용 그대로이다. 3번은 축사의 부동산등기에 관한 특례법의 요건이다. 4번 선박을 H빔 기둥에 고정한 것은 토지에 견고하게 정착한 건물이 아니다. 5번 관리사무소·노인정처럼 독립된 건물 요건을 갖춘 공용부분은 독립하여 등기할 수 있다.","c":"중","v":1},"법무사2026_32-29":{"w":"정답은 5번이다. ㄱ부터 ㅂ까지 모두 등기관이 직권으로 한다.\nㄱ 승역지에 지역권설정등기를 하면 요역지 등기기록에 직권으로 기록한다(부동산등기법 제71조).\nㄴ 대지권의 목적인 토지의 표시경정등기를 마치면 건물 표제부의 해당 표시를 직권으로 경정한다(부동산등기규칙 제94조의2).\nㄷ·ㄹ 권리소멸 등기나 환매에 따른 권리취득 등기를 하면 권리소멸약정등기·환매특약등기를 말소한다(같은 규칙 제114조).\nㅁ 신탁재산이 소유권이면 거래 주의사항을 신탁등기에 부기등기로 기록한다(같은 규칙 제139조의4).\nㅂ 규약 폐지로 소유권보존등기를 하면 공용부분이라는 뜻의 등기를 말소하는 표시를 한다(같은 규칙 제104조 제5항).","c":"상","v":1},"법무사2016_22-05":{"w":"2번이다. 소유권이전청구권 보전의 가등기는 처분행위가 아니므로 관할청 허가를 증명하는 정보를 제공하지 않는다.","c":"하","v":1},"법무사2016_22-14":{"w":"3개이다.\n가 O. 미성년자가 친권자에게 매매·증여하는 행위는 이해상반행위이다.\n나 O. 친권자와 미성년자인 자가 공동상속인인 상속재산 협의분할이다.\n다 X. 미성년자를 위해 담보로 제공하는 것은 이해상반이 아니다.\n라 X. 제3자에게 증여하는 것은 이해상반이 아니다.\n마 O. 공유부동산을 친권자의 채무 담보로 제공하는 행위이다.","c":"중","v":1},"법무사2017_23-07":{"w":"1번이다. 단독신청할 수 있는 포괄승계는 법인 분할로 분할 전 법인이 소멸하는 경우이다(부동산등기규칙 제42조 제1호). 분할 전 법인이 존속하면 공동으로 신청한다.\n2번 수용은 사업시행자가 단독으로(법 제99조), 3번 신탁등기의 말소는 수탁자가 단독으로, 4번 소유권보존등기의 말소는 등기명의인이 단독으로(법 제23조 제2항), 5번은 가등기명의인의 승낙을 받은 이해관계인이 단독으로(법 제93조 제2항) 신청한다.","c":"상","v":1},"법무사2018_24-12":{"w":"3번이 옳다. 허가대상 토지를 공유지분으로 나누어 처분하면 지분 비율에 따른 면적이 허가대상 면적 미만이어도 최초 지분이전등기를 신청할 때 토지거래계약허가증을 첨부해야 한다(등기예규 제1634호).\n2번 허가구역 지정 뒤 분할된 토지는 분할된 각 토지의 분할 후 최초 거래가 허가 대상이다. 乙 토지와 丙 토지 중 먼저 거래하는 것만 허가를 받는 것이 아니다. 4번 신탁재산 귀속이 대가에 의한 것이면 허가증을 첨부해야 한다. 허가증이 필요 없는 것은 증여처럼 대가가 없는 경우이다.","c":"중","v":1},"법무사2018_24-17":{"w":"5번이 틀리다. 취하서가 제출되면 등기관은 접수장 비고란에 취하의 뜻을 기록하고 신청서에 붙은 접수번호표에 '취하'라고 주서한 다음 신청서와 부속서류를 환부한다. 접수번호표를 떼어 내는 것이 아니다. 취하서는 신청서기타부속서류편철장의 해당 자리에 편철한다(등기예규 제1643호).\n1·2·4번은 같은 예규 그대로이다. 3번 방문신청의 취하는 등기소에 출석해 취하서를 제출하는 방법으로 한다.","c":"상","v":1},"법무사2019_25-28":{"w":"3번이 틀리다. 채무자회생법에 따른 부인등기의 말소는 관리인·파산관재인의 신청이 아니라 법원의 촉탁으로 한다.","c":"중","v":1},"법무사2022_28-14":{"w":"1번이 적절하지 않다. 본국에 거주하는 외국인이 입국했다고 해서 국내 공증인의 주소 공증으로 갈음하는 것은 허용되지 않는다.","c":"하","v":1},"법무사2022_28-19":{"w":"5번이다. 소유권이전청구권 가등기를 가등기가처분명령으로 단독 신청한 경우에는 등기권리자에게 등기필정보를 작성·통지한다.","c":"하","v":1},"법무사2023_29-21":{"w":"4번이다. 경매절차에서 소유권이전 등기, 인수하지 않은 부담의 말소등기, 경매개시결정등기의 말소등기는 한 장의 촉탁서로 촉탁할 수 있다.","c":"중","v":1},"법무사2024_30-18":{"w":"공동신청이 불가능한 것은 ㄱ, ㄷ 2개이다.\nㄱ 가압류등기는 법원의 촉탁으로 하므로 그 말소도 촉탁으로 한다.\nㄴ 공동신청으로 한 등기의 경정등기는 공동으로 신청한다.\nㄷ 미등기 건물의 소유권보존등기는 단독신청이다. 乙은 甲을 대위해 보존등기를 신청할 수 있다.\nㄹ 불법 말소된 제한물권의 회복등기는 말소 당시의 소유자를 등기의무자로 하여 공동으로 신청한다. 그 뒤의 소유자는 등기상 이해관계인이다.","c":"중","v":1},"법무사2026_32-16":{"w":"정답은 3번(3개, ㄱ·ㄷ·ㄹ)이다.\nㄱ 소유권 외의 권리 명의인이 등기필정보 없이(법 제51조) 등기의무자로 신청하므로 인감증명이 필요하다(부동산등기규칙 제60조 제1항 제3호).\nㄴ X. 지배인이 법인을 위해 신청하는 경우에는 대표자 甲의 인감증명이 아니라 신청한 지배인의 인감증명을 제출한다.\nㄷ 토지합병 후 합필등기 전에 가압류등기가 된 경우 가압류권자의 승낙을 받아 합필등기를 하므로(법 제38조 제2항) 승낙한 제3자의 인감증명이 필요하다(같은 규칙 제60조 제1항 제7호).\nㄹ 소유권의 등기명의인이 등기의무자인 경우는 위임장을 공증받아도 인감증명을 갈음할 수 없다. 공증으로 갈음할 수 있는 것은 같은 규칙 제60조 제4항의 제4호부터 제7호까지의 서면이다.\nㅁ X. 상속을 포기한 사람은 상속인이 아니므로 분할협의에 참가하지 않고 인감증명도 필요 없다.","c":"중","v":1},"법무사2026_32-17":{"w":"정답은 1번(없음)이다.\nㄱ 매매계약 무효 확인판결은 이행판결이 아니어서 말소등기를 신청할 수 없다.\nㄴ 재심판결로 원판결이 취소되었다는 것만으로는 그 판결로 마친 등기의 말소를 신청할 수 없다. 말소를 명하는 판결이 따로 있어야 한다.\nㄷ 실종선고취소 심판서만으로 실종선고를 원인으로 취득한 자 명의의 등기를 단독으로 말소할 수 없다.\nㄹ '양도한다'는 화해조서 문구는 등기절차의 이행을 명한 것이 아니다.\nㅁ 근저당권설정등기에는 채무자가 등기사항이므로 주문에 채무자가 없는 판결로는 신청할 수 없다.\nㅂ 공유물분할에 관한 화해권고결정은 확정판결과 달리 형성적 효력이 없어 지분을 넘겨받은 제3자에 대한 승계집행문으로 단독 신청할 수 없다.","c":"중","v":1},"법무사2018_24-08":{"w":"5번이 틀리다. 공유물분할판결이 확정되어 대지권이 소멸한 경우에는 그 판결이 대지권 소멸을 증명하는 정보가 된다. 분리처분가능규약을 따로 제공하지 않는다.","c":"중","v":1},"법무사2016_22-30":{"w":"3번이 틀리다. 소유권이전 본등기를 할 때 가등기 후 본등기 전에 마쳐진 체납처분에 의한 압류등기는 바로 직권말소하지 않는다. 등기기록만으로는 가등기가 담보가등기인지 알 수 없으므로 직권말소대상통지 절차를 거쳐 처리한다(가등기에 관한 업무처리지침, 등기예규 제1849호 5. 가. 2)).\n1번·2번은 같은 지침이 직권말소에서 빼는 등기이다. 4번 전세권설정 본등기를 하면 가등기 후 동일 부분에 마쳐진 전세권설정등기는 직권말소한다. 5번 소유권이전등기는 전세권 본등기와 양립하므로 말소하지 않는다.","c":"하","v":1},"법무사2018_24-22":{"w":"1번이 틀리다. 가등기권자의 상속인은 상속등기를 거치지 않고 상속인임을 증명하는 서면을 첨부해 본등기를 신청할 수 있다.","c":"하","v":1},"법무사2018_24-28":{"w":"5번이 틀리다. 공매공고등기와 그 말소등기를 촉탁할 때 등록면허세는 누가 촉탁하든 내지 않는다. 등기신청수수료가 면제되는 것은 세무서장과 이를 대행하는 한국자산관리공사가 촉탁하는 경우이다. 그 밖의 기관은 수수료만 낸다(국세징수법에 따른 공매공고 등기 사무처리지침 제6조).\n1번의 근거 조문은 지금 국세징수법 제103조이다. 4번 공매공고등기는 압류등기에 부기등기로 하고 납세담보 부동산은 갑구에 주등기로 한다(같은 지침 제5조).","c":"상","v":1},"법무사2019_25-10":{"w":"4번이 틀리다. 가등기명의인이 단독으로 말소를 신청하는 경우에도 가등기에 관한 등기필정보를 제공해야 한다.","c":"하","v":1},"법무사2016_22-15":{"w":"1번이다. 농업기반등정비확정도 또는 도시개발정비도는 반드시 제공해야 하는 첨부정보가 아니다.","c":"하","v":1},"법무사2017_23-20":{"w":"1번이다. 수용개시일 이전의 상속을 원인으로 한 소유권이전등기는 수용개시일 이후에 마쳐졌더라도 등기관이 직권으로 말소하지 않는다.","c":"중","v":1},"법무사2018_24-04":{"w":"1번이 틀리다. 미등기 건물에 대한 아파트 분양계약서도 계약서 검인의 대상이다.","c":"하","v":1},"법무사2019_25-04":{"w":"4번이 틀리다. 등기원인증서와 거래계약신고필증의 기재가 달라도 같은 거래로 인정할 수 있으면 각하하지 않는다.","c":"하","v":1},"법무사2019_25-24":{"w":"5번이 틀리다. 처분제한등기 촉탁으로 등기관이 직권으로 한 소유권보존등기는 보존등기 명의인의 말소신청이나 말소를 명하는 확정판결로만 말소할 수 있다. 처분제한을 발한 법원의 말소촉탁으로는 말소할 수 없다(등기예규 제1353호).","c":"상","v":1},"법무사2023_29-16":{"w":"1번이다. 공유물분할 조정이 성립한 경우의 물권변동은 등기를 해야 효력이 생긴다. 수용, 매각대금 완납, 상속, 농지분배는 법률의 규정에 의한 물권변동으로 등기 없이 효력이 생긴다.","c":"중","v":1},"법무사2019_25-14":{"w":"3번이 틀리다. 대장 면적을 정정한 경우 대장상 면적이 등기기록상 면적보다 커도 경정등기를 할 수 있다.","c":"하","v":1},"법무사2024_30-11":{"w":"정답은 4번 ㄱ, ㄴ, ㄹ, ㅁ이다(재외국민 및 외국인의 부동산등기신청절차에 관한 예규 제6조).\nㄱ 분할 대상 부동산과 대리인의 인적사항을 특정한 위임장을 제공한다.\nㄴ 위임장에는 인감을 날인하고 인감증명을 내는 것이 원칙이고 재외공관 인증으로 갈음할 수 있다(부동산등기규칙 제61조 제3항).\nㄷ X. 재외국민등록부등본은 소유권 등기명의인 등이 등기의무자로 신청하는 경우(같은 규칙 제60조 제1항 제1호부터 제3호까지)에 제공한다. 상속재산분할협의 위임은 여기에 해당하지 않는다.\nㄹ 대리인은 대리인임을 현명하고 대리인 자격으로 분할협의서를 작성한다.\nㅁ 분할협의서에는 대리인의 인감증명을 내되 대리인이 작성했다는 공증을 받으면 필요 없다.","c":"상","v":1},"법무사2025_31-22":{"w":"정답은 1번 ㄱ, ㄹ이다.\nㄱ 저당권 설정 뒤 소유자가 사망하면 경매개시결정 기입등기 전에 상속등기가 먼저 되어야 한다.\nㄴ X. 가등기에 의한 본등기와 가등기의 말소는 상속등기 없이 상속을 증명하는 정보를 첨부해 신청한다.\nㄷ X. 피상속인이 생전에 부담한 등기의무를 상속인이 이행하는 경우처럼 상속인을 등기의무자로 한 가처분은 상속등기 없이 피상속인 명의 부동산에 기입할 수 있다.\nㄹ 사망한 공유자의 상속인들에 대한 공유물분할판결로 등기하려면 상속등기를 먼저 해야 한다.\nㅁ X. 상속재산 파산관재인이 하는 형식적 경매나 임의매각에 따른 이전등기는 상속등기를 거치지 않는다.","c":"중","v":1},"법무사2017_23-23":{"w":"5번이 틀리다. 기계·기구의 일부 멸실이나 분리로 목록이 변경된 때에도 목록기재변경등기는 소유자가 신청한다. 저당권자가 신청하는 것이 아니다.","c":"하","v":1},"법무사2024_30-22":{"w":"4번이 틀리다. 공동저당 대위등기를 선순위저당권자가 등기의무자, 차순위저당권자가 등기권리자로서 공동으로 신청하는 것은 맞다. 그러나 (4)는 채무자를 기록하는 자리이므로 등기의무자인 박강남을 적지 않는다.","c":"중","v":1},"법무사2019_25-19":{"w":"1번이 사건이 등기할 것이 아닌 경우에 해당하지 않는다. 방문신청은 당사자나 대리인이 등기소에 출석해야 하므로 신청서를 우편으로 보내면 부동산등기법 제29조 제4호로 각하한다.\n2번 농지 전세권, 3번 일부지분 보존등기, 4번 가처분등기의 공동신청 말소, 5번 분묘기지권 설정은 모두 같은 조 제2호의 사건이 등기할 것이 아닌 경우이다.","c":"상","v":1},"법무사2022_28-30":{"w":"4번이다. 기록명령에 따른 등기를 할 수 없는 경우는 부동산등기규칙 제161조 제1항에 열거되어 있다. 1번은 제1호(제3자 명의 권리이전등기), 2번은 제2호(동일 부분의 임차권설정등기), 3번은 제3호(말소등기 전 이해관계인 발생), 5번은 제4호(첨부정보 재제공 명령 불응)에 해당한다. 소유권이전등기 기록명령 뒤 제3자 명의 근저당권설정등기가 된 4번은 여기에 없으므로 기록명령에 따른 등기를 할 수 있다.","c":"상","v":1},"법무사2023_29-07":{"w":"2번이다. 신청정보와 등기원인을 증명하는 정보(매매계약서)의 권리자가 다른 것은 부동산등기법 제29조 제8호의 각하 사유이다.\n1번 법령에 근거 없는 특약, 3번 촉탁으로 해야 할 등기의 신청, 4번 농지 전세권, 5번 일부지분 보존등기는 모두 같은 조 제2호의 사건이 등기할 것이 아닌 경우이다.","c":"상","v":1},"법무사2026_32-03":{"w":"정답은 4번 ㄴ, ㄷ, ㅁ이다.\nㄱ X. 소유권보존등기에서 국민주택채권을 매입하는 것은 토지이다. 건물의 소유권보존등기는 매입 대상이 아니다.\nㄴ 토지 소유권보존등기이므로 매입한다.\nㄷ 진정명의 회복을 원인으로 한 소유권이전등기도 국민주택채권을 매입한다(등기예규 제1631호).\nㄹ X. 저당권설정등기는 설정금액이 2,000만 원 이상일 때 매입하므로 1,000만 원이면 매입하지 않는다.\nㅁ 가액배상을 하고 다른 공유자의 지분을 넘겨받는 것은 지분 취득이므로 소유권이전등기에 따른 매입 대상이다.","c":"중","v":1},"법무사2016_22-04-1":{"w":"부동산등기법 제15조 제2항은 등기기록에 부동산의 표시에 관한 사항을 기록하는 표제부와 소유권에 관한 사항을 기록하는 갑구, 소유권 외의 권리에 관한 사항을 기록하는 을구를 두도록 정한다.","c":"상","v":1},"법무사2016_22-04-2":{"w":"부동산등기규칙 제13조 제1항은 토지등기기록의 표제부에 표시번호란·접수란·소재지번란·지목란·면적란·등기원인 및 기타사항란을 두도록 정한다. 건물 표제부에는 소재지번·건물명칭 및 건물번호란과 건물내역란을 둔다.","c":"상","v":1},"법무사2016_22-04-3":{"w":"부동산등기규칙 제13조 제2항이 갑구와 을구에 순위번호란·등기목적란·접수란·등기원인란·권리자 및 기타사항란을 두도록 정한다.","c":"상","v":1},"법무사2016_22-04-4":{"w":"부동산등기규칙 제14조 제1항: 1동의 건물을 구분한 건물은 1동 전체에 1개의 등기기록을 쓰되 1동의 건물에 대한 표제부를 두고 전유부분마다 표제부·갑구·을구를 둔다.","c":"상","v":1},"법무사2016_22-29-1":{"w":"부동산등기법 제52조 제6호·제7호는 제53조의 환매특약등기와 제54조의 권리소멸약정등기를 부기로 하도록 정한다.","c":"상","v":1},"법무사2016_22-29-3":{"w":"부동산등기규칙 제2조가 부기등기를 할 때 어느 등기에 기초한 것인지 알 수 있도록 주등기 또는 부기등기의 순위번호에 가지번호(1-1, 1-1-1 등)를 붙이도록 정한다.","c":"상","v":1},"법무사2016_22-29-4":{"w":"채권최고액 증액으로 근저당권보다 뒤에 마쳐진 압류등기의 권리자는 불이익을 받으므로 등기상 이해관계 있는 제3자다. 부동산등기법 제52조 제5호 단서에 따라 그 처분청의 승낙이 있으면 변경등기를 부기로 한다.","c":"중","v":1},"법무사2016_22-29-5":{"w":"증액되는 근저당권과 후순위 근저당권의 권리자가 같으면 증액으로 손해를 볼 제3자가 없으므로 그 후순위 근저당권자는 이해관계인이 아니다(등기선례). 다른 이해관계인이 없으면 승낙정보 없이 부기등기로 한다(부동산등기법 제52조 제5호).","c":"중","v":1},"법무사2017_23-30-1":{"w":"부동산등기법 제20조 제1항: 등기관이 등기기록에 등기된 사항을 새로운 등기기록에 옮겨 기록한 때에는 종전 등기기록을 폐쇄한다. 폐쇄한 등기기록은 영구히 보존한다(같은 조 제2항).","c":"상","v":1},"법무사2017_23-30-3":{"w":"부동산등기규칙 제34조: 최종 소유권 등기명의인이 같으면 후등기기록을 폐쇄하는 것이 원칙이고 후등기기록에만 소유권 외의 권리 등에 관한 등기가 있으면 선등기기록을 폐쇄한다.","c":"상","v":1},"법무사2017_23-30-4":{"w":"부동산등기규칙 제55조 제2항은 등기기록을 폐쇄할 때 표제부의 등기를 말소하는 표시를 하고 등기원인 및 기타사항란에 폐쇄의 뜻과 그 연월일을 기록하도록 정한다.","c":"상","v":1},"법무사2017_23-30-5":{"w":"부동산등기규칙 제79조 제2항: 합필등기를 마치면 갑 토지 등기기록 표제부에 을 토지 등기기록에 옮겨 기록한 뜻을 적고 표제부의 등기를 말소하는 표시를 한 뒤 그 등기기록을 폐쇄한다.","c":"상","v":1},"법무사2018_24-10-1":{"w":"부동산등기규칙 제34조가 정하는 정리 방법이다. 최종 소유권 등기명의인이 같으면 후등기기록 폐쇄가 원칙이고 후등기기록에만 소유권 외의 권리 등에 관한 등기가 있으면 선등기기록을 폐쇄한다.","c":"상","v":1},"법무사2018_24-10-3":{"w":"부동산등기규칙 제36조 제1항: 최종 소유권 등기명의인이 다른 경우 어느 한 등기기록에만 원시취득사유나 분배농지 상환완료를 원인으로 한 소유권이전등기가 있으면 그 등기기록만 남기고 나머지를 폐쇄한다. 이 정리에는 지방법원장의 허가가 필요하다(제38조).","c":"상","v":1},"법무사2018_24-10-4":{"w":"부동산등기규칙 제39조 제1항: 중복등기기록 중 어느 한 등기기록의 최종 소유권 등기명의인은 자기 명의의 등기기록을 폐쇄하도록 신청할 수 있고 등기상 이해관계인이 있으면 그 승낙정보를 제공해야 한다.","c":"상","v":1},"법무사2018_24-10-5":{"w":"존치할 등기기록의 명의인도 폐쇄될 등기기록의 최종 소유권 등기명의인과 이해관계인의 승낙서를 붙이면 그 등기기록의 폐쇄를 신청할 수 있다(중복등기기록 정리에 관한 등기예규). 부동산등기규칙 제39조의 정리신청을 넓힌 것이다.","c":"중","v":1},"법무사2018_24-15-1":{"w":"부동산등기법 제54조는 「등기원인에」 권리소멸의 약정이 있을 경우에 그 등기를 신청할 수 있게 한다. 등기원인행위와 별개의 계약으로 맺은 소멸약정은 이에 해당하지 않아 등기할 수 없다.","c":"중","v":1},"법무사2018_24-15-3":{"w":"부동산등기법 제54조는 신청인이 권리소멸약정의 등기를 「신청할 수 있다」고 정할 뿐이어서 그 약정을 반드시 신청정보에 담아야 하는 것은 아니다. 등기하지 않으면 제3자에게 대항하지 못할 뿐이다.","c":"상","v":1},"법무사2018_24-15-4":{"w":"부동산등기법 제52조 제7호에 따라 권리소멸약정등기는 그 권리취득등기에 부기한다. 부기등기는 주등기에 종속되므로 주등기인 권리취득등기를 말소하면 등기관이 부기된 약정등기도 직권으로 말소한다.","c":"중","v":1},"법무사2018_24-15-5":{"w":"부동산등기법 제55조: 사람의 사망이나 법인의 해산으로 권리가 소멸한다는 약정이 등기되어 있고 실제로 그 사유로 권리가 소멸하면 등기권리자는 그 사실을 증명하여 단독으로 말소를 신청할 수 있다.","c":"상","v":1},"법무사2018_24-18-1":{"w":"「국가 등이 등기사항증명서의 교부 등을 신청하는 경우 수수료 면제」(등기예규 제1409호)는 세무공무원의 과세자료 조사나 지적소관청 공무원의 지적공부·등기기록 부합 확인을 위한 열람에 열람수수료를 면제한다.","c":"상","v":1},"법무사2018_24-18-2":{"w":"등기예규 제1409호는 수수료 면제를 법률 규정이 있는 경우로 한정한다. 국가 등이 소송수행에 쓰려고 신청하더라도 면제 규정이 없으면 수수료를 받는다.","c":"상","v":1},"법무사2018_24-18-3":{"w":"등기예규 제1409호는 국유재산관리사무를 위임·위탁받은 자가 그 사무에 필요하다는 사실을 소명하여 등기사항증명서 교부 등을 신청하면 수수료를 면제한다.","c":"상","v":1},"법무사2018_24-18-4":{"w":"등기예규 제1409호는 다른 법률에 면제 규정이 있어도 무인발급기 발급과 인터넷을 통한 등기사항증명서 교부·등기기록 열람의 수수료는 면제하지 않는다고 정한다.","c":"상","v":1},"법무사2019_25-07-1":{"w":"부기등기는 독립한 순위번호 없이 주등기의 순위번호에 가지번호를 붙여 기록하고(부동산등기규칙 제2조) 순위도 주등기에 따른다(부동산등기법 제5조). 주등기가 말소되면 부기등기도 직권으로 말소되는 종속관계다.","c":"중","v":1},"법무사2019_25-07-2":{"w":"부동산등기규칙 제143조는 신탁재산이 수탁자의 고유재산이 되었을 때 그 뜻의 등기를 주등기로 하도록 정한다. 이 등기는 권리 자체의 이전에 해당하는 성질이라 부기로 하지 않는다.","c":"중","v":1},"법무사2019_25-07-3":{"w":"부동산등기법 제52조 제6호(제53조의 환매특약등기)와 제7호(제54조의 권리소멸약정등기)가 이를 부기로 하도록 정한다.","c":"상","v":1},"법무사2019_25-07-5":{"w":"전세권변경등기는 권리의 변경등기로서 부동산등기법 제52조 제5호에 따라 부기로 하되, 같은 조 단서에 따라 등기상 이해관계 있는 제3자의 승낙이 없으면 주등기로 한다.","c":"상","v":1},"법무사2019_25-21-1":{"w":"「부동산등기기록의 주민등록번호 등 공시제한에 따른 업무처리지침」(등기예규 제1672호)은 공시제한을 하지 않는 사유를 소명하는 서면(공문·신분증·소송자료 등)을 확인하고 전산 입력 후 신청인에게 즉시 반환하도록 정한다.","c":"상","v":1},"법무사2019_25-21-2":{"w":"등기예규 제1672호는 공시제한 대상을 개인과 법인 아닌 사단·재단의 대표자의 주민등록번호 등으로 한정하고 법인·법인 아닌 사단이나 재단·국가·지방자치단체 등 단체의 등록번호는 공시를 제한하지 않는다.","c":"상","v":1},"법무사2019_25-21-4":{"w":"등기예규 제1672호는 등기명의인이 법인 아닌 사단·재단인 경우 그 대표자의 주민등록번호 등의 일부를 공시제한 대상으로 삼는다. 단체 자체의 부동산등기용등록번호는 제한하지 않는다.","c":"상","v":1},"법무사2019_25-21-5":{"w":"등기예규 제1672호는 공시제한 범위를 등기명의인 표시 중 주민등록번호 등의 뒷부분 7자리 숫자로 정하고 이를 가려서 등기사항증명서를 발급하고 열람에 제공한다.","c":"상","v":1},"법무사2019_25-22-2":{"w":"등기할 수 있는 토지는 대한민국 영토 안에 있어야 한다. 공해상의 수중암초나 구조물은 우리 법의 지배를 받는 토지가 아니어서 등기 대상이 아니다(등기할 물건에 관한 등기예규·선례).","c":"중","v":1},"법무사2019_25-22-3":{"w":"건물로 등기하려면 지붕과 주벽을 갖추고 토지에 견고하게 정착해 쉽게 해체·이동할 수 없어야 한다(등기할 수 있는 물건의 판단에 관한 등기예규). 유류저장탱크도 이 요건을 갖추면 건물로 보존등기할 수 있다.","c":"중","v":1},"법무사2019_25-22-4":{"w":"철근콘크리트 기초에 고정되어 토지에 정착하고 경량철골구조와 내구성 10년 이상의 장기성 필름으로 지붕·벽면을 갖춘 비닐온실은 건물의 요건(외기분단성·정착성·용도성)을 갖추어 보존등기를 할 수 있다는 것이 등기선례다.","c":"중","v":1},"법무사2019_25-22-5":{"w":"군사분계선 이북 지역은 대한민국의 행정력이 미치지 않아 토지대장 등으로 소유권을 증명할 수 없으므로 소유권보존등기를 신청할 수 없다는 것이 등기선례다.","c":"중","v":1},"법무사2020_26-09-1":{"w":"등기관은 형식적 심사권만 가지므로 신청정보와 첨부정보, 등기기록에 의하여 신청이 부동산등기법 등 법령에 맞는지를 조사한다(부동산등기법 제29조, 등기관의 심사에 관한 등기예규).","c":"중","v":1},"법무사2020_26-09-2":{"w":"등기관의 심사에 관한 등기예규는 첨부서면이 위조된 것으로 의심되면 신청인이나 대리인에게 알려 진위를 확인한 뒤 처리하도록 정한다. 위조가 확인되면 수사기관에 고발한다.","c":"중","v":1},"법무사2020_26-09-4":{"w":"부동산등기법 제65조 제2호의 「판결」은 소유권확인판결에 한정되지 않는다. 형성판결이나 이행판결도 이유에서 신청인의 소유임을 확정하는 내용이면 해당한다(판결에 의한 소유권보존등기에 관한 등기예규).","c":"중","v":1},"법무사2020_26-09-5":{"w":"상속등기는 상속인 전원을 위해 상속재산 전부에 대해 해야 하므로 공동상속인 일부가 자기 지분만 상속등기를 신청하면 부동산등기법 제29조 제2호의 「사건이 등기할 것이 아닌 경우」로 각하한다(등기예규·선례).","c":"중","v":1},"법무사2020_26-15-1":{"w":"부동산등기규칙 제23조는 신청서·촉탁서·통지서·허가서·참여조서·확인조서·취하서 등 부속서류를 접수번호 순서에 따라 신청서 기타 부속서류 편철장에 편철하도록 정한다. 제111조의 확인조서도 여기에 편철한다.","c":"상","v":1},"법무사2020_26-15-2":{"w":"각종 통지부(부동산등기규칙 제21조 제1항 제8호)에는 통지사항과 통지받을 자, 통지서 발송 연월일을 적는다(장부 관리에 관한 등기예규). 보존기간은 1년이다(제25조 제1항 제8호).","c":"중","v":1},"법무사2020_26-15-4":{"w":"부동산등기규칙 제25조 제3항: 보존기간이 만료된 장부나 서류는 지방법원장의 인가를 받아 보존기간이 만료되는 해의 다음해 3월 말까지 폐기한다.","c":"상","v":1},"법무사2020_26-15-5":{"w":"부동산등기규칙 제22조 제1항은 접수장 기재사항으로 접수연월일·접수번호, 등기의 목적, 신청인의 성명 또는 명칭, 부동산의 개수, 등기신청수수료, 취득세 등을 정할 뿐 등기원인과 그 연월일은 넣지 않는다.","c":"상","v":1},"법무사2020_26-22-1":{"w":"「부동산등기 신청정보 및 첨부정보의 열람에 관한 업무처리지침」(등기예규 제1876호)은 단순히 부동산을 매수하려는 자나 소유권 등기명의인에게 금전채권을 가진 데 불과한 자는 이해관계인이 아니어서 열람할 수 없다고 정한다.","c":"상","v":1},"법무사2020_26-22-3":{"w":"등기예규 제1876호는 수사기관이라도 법관이 발부한 영장을 제시하지 않으면 신청정보와 첨부정보를 열람할 수 없다고 정한다.","c":"상","v":1},"법무사2020_26-22-4":{"w":"등기예규 제1876호는 유증자의 상속인이 유언집행자와 수증자가 공동으로 신청한 유증 원인 소유권이전등기의 신청정보·첨부정보를 열람할 수 있다고 정한다. 유증으로 상속인의 지위에 직접 영향이 있기 때문이다.","c":"상","v":1},"법무사2020_26-22-5":{"w":"등기예규 제1876호에 따르면 등기를 마친 자격자대리인은 열람 위임이 따로 없으면 자신이 작성·제출한 신청정보·위임장·확인서면(현행 예규는 자필서명정보 포함, 방문열람에 한함)만 볼 수 있고 나머지 첨부정보는 열람할 수 없다.","c":"중","v":1},"법무사2021_27-10-1":{"w":"부동산등기법 제19조 제1항: 누구든지 수수료를 내고 등기기록의 열람과 등기사항증명서 발급을 청구할 수 있으나 등기기록의 부속서류는 이해관계 있는 부분만 열람을 청구할 수 있다.","c":"상","v":1},"법무사2021_27-10-2":{"w":"부동산등기규칙 제30조 제4항: 등기신청이 접수된 부동산은 등기를 마칠 때까지 등기사항증명서를 발급하지 못하지만 등기신청사건이 접수되어 처리 중이라는 뜻을 표시하여 발급할 수는 있다.","c":"상","v":1},"법무사2021_27-10-3":{"w":"부동산등기규칙 제30조 제1항 후단은 등기기록 중 갑구 또는 을구의 기록이 없을 때 증명문에 그 뜻을 기록하도록 정한다.","c":"상","v":1},"법무사2021_27-10-4":{"w":"명의인별로 작성된 등기정보자료는 등기명의인이나 그 포괄승계인만 받을 수 있다(부동산등기법 제109조의2 제2항 단서). 부동산등기규칙은 그 제공 범위를 등기명의인의 부동산 소유현황으로 한정한다.","c":"중","v":1},"법무사2021_27-12-1":{"w":"부동산등기규칙 제29조 제2호의 등기사항전부증명서(현재 유효사항)는 말소된 사항을 빼고 현재 효력이 있는 등기사항과 그와 관련된 사항만 증명하는 증명서다(등기사항증명서 발급에 관한 등기예규).","c":"중","v":1},"법무사2021_27-12-2":{"w":"부동산등기규칙 제29조 제4호의 등기사항일부증명서(현재 소유현황)는 현재 소유자나 공유자만 밝히고 공유이면 공유지분을 증명한다(등기사항증명서 발급에 관한 등기예규).","c":"중","v":1},"법무사2021_27-12-4":{"w":"부동산등기규칙 제29조가 정한 다섯 종류, 곧 전부증명서(말소사항 포함)·전부증명서(현재 유효사항)·일부증명서(특정인 지분·현재 소유현황·지분취득 이력)를 인터넷으로도 발급한다(인터넷에 의한 등기기록 열람 등에 관한 등기예규).","c":"중","v":1},"법무사2021_27-12-5":{"w":"부동산등기규칙 제30조 제2항: 신탁원부·공동담보(전세)목록·도면·매매목록은 그 사항의 증명도 함께 신청하는 뜻을 표시한 경우에만 등기사항증명서에 포함하여 발급한다. 공장저당목록도 등기예규로 같게 다룬다.","c":"상","v":1},"법무사2021_27-21-1":{"w":"부동산등기법 제32조 제2항: 등기의 착오나 빠진 부분이 등기관의 잘못으로 생긴 것이면 등기관이 지체 없이 직권으로 경정하되, 등기상 이해관계 있는 제3자가 있으면 그 승낙이 있어야 한다.","c":"상","v":1},"법무사2021_27-21-3":{"w":"부동산등기법 제57조: 말소에 대해 등기상 이해관계 있는 제3자가 있으면 그 승낙이 있어야 하며(제1항) 그 등기를 말소할 때 제3자 명의의 등기는 등기관이 직권으로 말소한다(제2항).","c":"상","v":1},"법무사2021_27-21-4":{"w":"부동산등기법 제85조의2 제1호: 수탁자의 변경으로 인한 이전등기를 할 때 등기관은 직권으로 신탁원부 기록의 변경등기를 한다.","c":"상","v":1},"법무사2021_27-21-5":{"w":"부동산등기법 제99조 제4항: 수용으로 인한 소유권이전등기를 하면 소유권·소유권 외의 권리·처분제한 등기를 직권으로 말소하되, 그 부동산을 위한 지역권 등기와 토지수용위원회 재결로 존속이 인정된 권리의 등기는 남긴다.","c":"상","v":1},"법무사2021_27-24-1":{"w":"판례는 등기관에게 실체 권리관계와 맞는지를 따질 실질적 심사권은 없고 신청서·첨부서류와 등기부만으로 등기요건을 갖추었는지 심사하는 형식적 심사권과 그 책무가 있다고 본다.","c":"중","v":1},"법무사2021_27-24-2":{"w":"등기관은 제출된 서면 자체를 검토하고 등기부와 대조하는 방법으로만 심사하며 그 결과 위조된 서면에 의한 신청으로 인정되면 각하할 직무상 의무가 있다는 것이 판례다. 이를 게을리하면 국가배상책임이 생길 수 있다.","c":"중","v":1},"법무사2021_27-24-3":{"w":"부동산등기법 제29조 본문과 단서: 각 호에 해당하는 경우에만 이유를 적은 결정으로 각하하되, 보정할 수 있는 잘못을 신청인이 보정명령일 다음 날까지 보정하면 각하하지 않는다.","c":"상","v":1},"법무사2021_27-24-5":{"w":"판례는 등기관의 심사 기준시점을 신청서류 제출 때가 아니라 등기부에 기록하려는 때, 곧 등기를 실행하는 때로 본다. 그래서 접수 후 실행 전에 생긴 사유(처분금지가처분 등)도 심사에 반영된다.","c":"중","v":1},"법무사2023_29-12-2":{"w":"부동산등기법 제15조 제1항 단서: 1부동산 1등기기록이 원칙이지만 1동의 건물을 구분한 건물은 1동의 건물에 속하는 전부에 대하여 1개의 등기기록을 사용한다.","c":"상","v":1},"법무사2023_29-12-3":{"w":"부동산등기법 제36조 제1항: 지적소관청이 공간정보관리법 제88조 제3항에 따라 불일치 사실을 통지하고 제35조의 1개월 안에 등기명의인의 신청이 없으면 등기관은 통지서 내용대로 직권으로 변경등기를 한다.","c":"상","v":1},"법무사2023_29-12-4":{"w":"부동산등기법 제40조 제1항 제3호는 건물 표제부에 건물의 종류·구조·면적을 기록하고 부속건물이 있으면 그 종류·구조·면적도 함께 기록하도록 정한다.","c":"상","v":1},"법무사2023_29-12-5":{"w":"부동산등기법 제14조 제4항: 부속서류는 전쟁·천재지변 등을 피하기 위한 경우 외에는 등기소 밖으로 옮기지 못하지만 신청서나 그 밖의 부속서류는 법원의 명령·촉탁이 있거나 법관이 발부한 영장으로 압수할 때 옮길 수 있다.","c":"상","v":1},"법무사2023_29-22-1":{"w":"근저당권 이전의 부기등기는 기존 근저당권을 승계한 것을 공시할 뿐이다. 이전 원인만 무효·취소·해제된 경우에는 주등기가 아닌 부기등기인 이전등기만 말소한다는 것이 판례·예규다.","c":"중","v":1},"법무사2023_29-22-2":{"w":"민법 제348조: 저당권으로 담보한 채권을 질권의 목적으로 한 때에는 그 저당권등기에 질권의 부기등기를 하여야 질권의 효력이 저당권에 미친다. 부동산등기법 제52조 제3호도 이를 부기로 한다.","c":"상","v":1},"법무사2023_29-22-3":{"w":"가등기상 권리는 양도할 수 있고 그 이전등기는 양도인과 양수인이 공동신청한다(부동산등기법 제23조 제1항). 소유권 외의 권리의 이전등기처럼 가등기에 부기하는 형식으로 한다(판례·등기예규).","c":"중","v":1},"법무사2023_29-22-5":{"w":"부동산등기규칙 제2조는 주등기뿐 아니라 부기등기의 순위번호에도 가지번호를 붙일 수 있게 한다. 부기등기의 부기등기(예: 근저당권 이전의 부기등기에 다시 변경등기)가 그 예다.","c":"상","v":1},"법무사2023_29-23-2":{"w":"「축사의 부동산등기에 관한 특례법」 제3조가 개방형 축사를 건물로 보는 요건으로 토지에 견고하게 정착할 것, 소를 사육할 용도로 계속 사용할 수 있을 것, 지붕과 견고한 구조를 갖출 것, 건축물대장에 축사로 등록될 것, 연면적 100제곱미터 초과를 정한다.","c":"중","v":1},"법무사2023_29-23-3":{"w":"구분소유권이 성립하려면 구조상·이용상 독립성이 있어야 한다. 이를 갖추지 못한 건물 부분에 관한 구분건물 등기는 대장 등재나 경매 매각허가가 있었더라도 그 자체로 무효여서 매수인이 소유권을 취득하지 못한다는 것이 판례다.","c":"중","v":1},"법무사2023_29-23-4":{"w":"공유수면은 국가가 관리하는 바다·바닷가·하천 등으로서 사권의 객체인 토지가 아니다. 구획하더라도 부동산이 아니어서 소유권이전등기를 구할 수 없다는 것이 판례다.","c":"중","v":1},"법무사2023_29-23-5":{"w":"구조상 공용부분(복도·계단 등)은 구분소유권의 목적이 될 수 없어 독립한 등기기록을 개설할 수 없다. 규약상 공용부분만 공용부분이라는 뜻의 등기를 한다(부동산등기법 제47조).","c":"중","v":1},"법무사2023_29-30-1":{"w":"부동산등기법 제21조와 부동산등기규칙 제33조~제41조의 중복등기기록 정리 규정은 같은 「토지」를 대상으로 한다. 건물 중복등기는 등기예규(건물 중복등기 정리에 관한 업무처리지침)로 처리한다.","c":"중","v":1},"법무사2023_29-30-2":{"w":"존재하지 않는 토지에 관한 등기기록은 중복등기기록이 아니므로 규칙상 폐쇄 대상이 아니다. 진정한 등기기록의 명의인이 그 등기기록의 명의인을 대위하여 멸실등기에 준하는 등기를 신청해 정리한다(중복등기기록 정리에 관한 등기예규).","c":"중","v":1},"법무사2023_29-30-4":{"w":"부동산등기규칙 제36조 제1항: 최종 소유권 등기명의인이 다르고 어느 한 등기기록에만 원시취득사유나 분배농지 상환완료를 원인으로 한 소유권이전등기가 있으면 그 등기기록을 남기고 나머지를 폐쇄한다.","c":"상","v":1},"법무사2023_29-30-5":{"w":"최종 소유권 명의인이 같으면 규칙 제34조에 따라 등기관이 바로 정리한다. 1개월 이상 기간을 정해 명의인과 이해관계인에게 통지하는 절차는 명의인이 다른 경우의 제37조에만 있다.","c":"상","v":1},"법무사2024_30-10-1":{"w":"토지는 지적공부에 등록되어야 특정된다. 지적공부가 멸실된 경우가 아닌데 지적공부에 등록되지 않은 토지에 관한 보존등기는 존재하지 않거나 특정되지 않은 토지에 관한 등기여서 무효라는 것이 판례다.","c":"중","v":1},"법무사2024_30-10-2":{"w":"구조상·이용상 독립성이 없는 건물 부분은 구분소유권의 객체가 될 수 없으므로 대장과 등기부에 구분건물로 등재되어 경매로 매각되었더라도 그 등기는 무효이고 매수인은 소유권을 취득하지 못한다는 것이 판례다.","c":"중","v":1},"법무사2024_30-10-3":{"w":"환지처분이 공고되면 환지는 종전 토지로 보므로 공고 당시 종전 토지에 있던 등기가 환지에 대한 등기로 효력을 가진다. 공고 뒤 환지등기 전에 종전 토지에 한 등기는 환지에 대한 등기로 효력이 없다는 것이 판례다.","c":"중","v":1},"법무사2024_30-10-5":{"w":"가등기에 의한 본등기를 금지하는 가처분은 등기청구권 행사를 막는 것이어서 법률상 허용되지 않는다. 그런 촉탁으로 등기가 되었더라도 아무 효력이 없다는 것이 판례다.","c":"중","v":1},"법무사2024_30-26-1":{"w":"부동산등기법 제7조 제1항이 부동산 소재지를 관할하는 지방법원·지원·등기소가 등기사무를 담당한다고 정하고 법원조직법 제3조 등에 따라 대법원장은 어느 등기소의 관할 사무를 다른 등기소에 위임하게 할 수 있다.","c":"중","v":1},"법무사2024_30-26-3":{"w":"부동산등기규칙 제5조 제2항·제3항: 관할등기소 지정신청서는 부동산 소재지를 관할하는 등기소 중 어느 한 곳에 내고 그 등기소가 상급법원의 장에게 보내면 상급법원의 장이 관할등기소를 지정한다.","c":"상","v":1},"법무사2024_30-26-4":{"w":"관할 위반은 부동산등기법 제29조 제1호 각하사유다. 이를 간과해 마친 등기는 절대적 무효여서 제58조에 따라 등기관이 통지 후 직권으로 말소한다.","c":"상","v":1},"법무사2024_30-26-5":{"w":"부동산등기규칙 제6조 제1항: 부동산 소재지가 다른 등기소 관할로 바뀌면 종전 관할등기소는 전산정보처리조직으로 등기기록 등의 처리권한을 넘겨주는 조치를 한다. 상급법원의 장의 결정은 필요 없다.","c":"상","v":1},"법무사2025_31-12-1":{"w":"「부동산등기 신청정보 및 첨부정보의 열람에 관한 업무처리지침」(등기예규 제1876호)은 인터넷 열람 신청인을 주민등록번호가 기록된 해당 등기신청의 당사자와 그로부터 열람을 위임받은 자격자대리인으로 한정한다. 신청을 대리했을 뿐인 자격자대리인은 방문 열람만 할 수 있다.","c":"중","v":1},"법무사2025_31-12-2":{"w":"등기예규 제1876호는 인터넷 열람을 등기기록에 주민등록번호(부동산등기용등록번호)가 기록된 당사자에게만 허용한다. 본인 인증으로 열람 자격을 확인해야 하기 때문이다.","c":"상","v":1},"법무사2025_31-12-4":{"w":"등기예규 제1876호 제5조 제1항: 등기신청이 접수된 후 등기가 완료되기 전의 신청정보와 첨부정보는 열람을 신청할 수 없다.","c":"상","v":1},"법무사2025_31-12-5":{"w":"등기예규 제1876호는 수사기관이라도 법관이 발부한 영장을 제시하지 않으면 신청정보와 첨부정보를 열람할 수 없다고 정한다.","c":"상","v":1},"법무사2025_31-21-1":{"w":"1부동산 1등기기록 원칙(부동산등기법 제15조) 때문에 이미 보존등기된 부동산에 다시 보존등기를 하면 중복등기가 된다. 그러한 신청은 제29조 제2호의 「사건이 등기할 것이 아닌 경우」로 각하한다.","c":"중","v":1},"법무사2025_31-21-2":{"w":"중복등기기록 정리에 관한 등기예규는 중복등기를 같은 부동산에 2개 이상 마쳐진 보존등기나 멸실회복등기로 한정한다. 기재 착오나 존재하지 않는 토지의 등기로 지번만 같아진 등기기록은 중복등기로 처리하지 않는다.","c":"중","v":1},"법무사2025_31-21-3":{"w":"부동산등기규칙 제33조 제2항은 중복등기기록 정리가 실체 권리관계에 영향을 미치지 않는다고 정하고 부동산등기법 제21조 제2항은 폐쇄된 등기기록의 부활 신청을 허용한다. 판결로 등기 자체를 말소하는 것과 다르다.","c":"상","v":1},"법무사2025_31-21-5":{"w":"두 등기기록의 최종 소유권 명의인이 모두 甲으로 같고 선등기기록에만 丙의 근저당권 등기가 있으므로 부동산등기규칙 제34조 본문에 따라 후등기기록을 폐쇄한다.","c":"상","v":1},"법무사2026_32-05-1":{"w":"「관련 사건의 신청 및 처리에 관한 업무처리지침」(등기예규 제1834호)은 등기원인의 당사자가 같아야 관련 신청사건이 된다고 정한다. 같은 소유자의 부동산을 여러 사람이 나누어 매수하면 당사자가 달라 하나의 등기소에 함께 신청할 수 없다(예규의 부부 예시).","c":"상","v":1},"법무사2026_32-05-2":{"w":"등기예규 제1834호 제7조: 여러 부동산에 대해 동일한 여러 등기의무자로부터 동일한 여러 등기권리자에게 이전하면 당사자가 동일하므로 관할이 다른 부동산도 그중 한 등기소에 함께 신청할 수 있다(부동산등기법 제7조의2 제1항).","c":"상","v":1},"법무사2026_32-05-4":{"w":"등기예규 제1834호 제6조는 여러 부동산 중 일부에만 제3자의 허가·동의·승낙이나 등기상 이해관계인의 승낙이 필요하더라도 등기원인은 동일하다고 본다.","c":"상","v":1},"법무사2026_32-05-5":{"w":"등기예규 제1834호 제5조는 등기할 사항의 유형이 같으면 등기목적이 같다고 본다. A는 전부, B는 1/2 지분이라도 모두 「소유권 이전」이므로 등기목적이 동일하다.","c":"상","v":1},"법무사2026_32-21-1":{"w":"등기예규 제1672호는 공익사업의 사업시행자 등이 신청과 이해관계가 있음을 소명하면 주민등록번호 등이 가려지지 않은 등기사항증명서를 발급하게 한다. 사업시행자로부터 보상업무를 위탁받은 한국감정원(현 한국부동산원)도 위탁 사실을 소명하면 같다.","c":"중","v":1},"법무사2026_32-21-2":{"w":"「국가 등이 등기사항증명서의 교부 등을 신청하는 경우 수수료 면제」(등기예규 제1409호)는 다른 법률에 면제 규정이 있어도 무인발급기와 인터넷을 통한 교부·열람 수수료는 면제하지 않는다고 정한다.","c":"상","v":1},"법무사2026_32-21-4":{"w":"「인터넷에 의한 등기기록의 열람 등에 관한 업무처리지침」(등기예규 제1806호)은 인터넷등기소에서 이미지폐쇄등기부나 신탁원부 같은 영구보존문서의 열람을 신청할 수 있게 한다.","c":"중","v":1},"법무사2026_32-21-5":{"w":"등기예규 제1409호는 수수료 면제를 법률에 근거가 있는 경우로 한정한다. 국가 등이 소송에 쓰더라도 면제 규정이 없으면 수수료를 받는다.","c":"상","v":1},"법무사2026_32-22-5":{"w":"하천법 제4조 제2항은 하천을 구성하는 토지에 사권 행사를 제한하되 소유권 이전·저당권 설정 등은 허용한다. 「하천법 제4조 제2항에 따른 등기할 사항의 범위 등」 등기예규는 신탁등기도 할 수 있는 등기로 정한다.","c":"중","v":1},"법무사2026_32-23-1":{"w":"등기예규 제1876호는 장래 가등기에 의한 본등기를 할 때 직권말소될 등기의 명의인을 이해관계인으로 보아 그 가등기의 신청정보와 첨부정보를 열람할 수 있게 한다.","c":"상","v":1},"법무사2026_32-23-2":{"w":"등기예규 제1876호는 (근)저당권설정자가 그 (근)저당권 이전등기의 신청정보와 첨부정보를 열람할 수 있다고 정한다. 설정자는 누가 채권자가 되는지에 직접 이해관계가 있다.","c":"상","v":1},"법무사2026_32-23-3":{"w":"부동산등기규칙 제26조 제3항: 전자문서로 작성된 신청서나 그 밖의 부속서류의 열람은 관할 등기소가 아닌 다른 등기소에서도 신청할 수 있다.","c":"상","v":1},"법무사2026_32-23-4":{"w":"등기예규 제1876호는 유증자의 상속인이 유언집행자와 수증자가 공동신청한 유증 원인 소유권이전등기의 신청정보·첨부정보를 열람할 수 있다고 정한다.","c":"상","v":1},"법무사2016_22-06-1":{"w":"부동산등기규칙 제3조 제2항이 같은 토지 위의 여러 구분건물에 대한 등기를 동시에 신청하면 건물의 소재와 지번에 관한 정보가 전산정보처리조직에 저장된 때 접수된 것으로 본다고 정한다. 일반적인 경우의 접수시기는 부동산을 구별할 수 있는 정보가 저장된 때다(제1항).","c":"상","v":1},"법무사2016_22-06-2":{"w":"부동산등기규칙 제65조 제2항: 같은 부동산에 관하여 동시에 여러 개의 등기신청이 있으면 같은 접수번호를 부여한다. 같은 접수번호의 등기는 같은 순위가 된다.","c":"상","v":1},"법무사2016_22-06-4":{"w":"부동산등기법 제6조 제2항: 등기관이 등기를 마치면 그 등기는 접수한 때부터 효력이 생긴다. 등기 실행 시점이 아니라 접수 시점으로 소급한다.","c":"상","v":1},"법무사2016_22-06-5":{"w":"전자신청은 신청정보가 전산정보처리조직에 저장되면 자동으로 접수번호가 부여되어 접수된다(부동산등기법 제6조 제1항, 전자신청에 관한 등기예규). 접수담당자가 따로 접수절차를 밟지 않는다.","c":"중","v":1},"법무사2016_22-07-1":{"w":"상속재산협의분할서는 상속인 전원의 합의를 증명하는 서면이므로 여러 장이면 작성자 전원이 간인해야 한다(등기예규·선례). 신청서와 달리 1명의 간인으로 갈음하지 않는다.","c":"중","v":1},"법무사2016_22-07-2":{"w":"부동산등기규칙 제56조 제2항: 신청서가 여러 장이면 신청인이나 대리인이 간인하며 등기권리자나 등기의무자가 여러 명이면 그중 1명이 간인하는 방법으로 한다.","c":"상","v":1},"법무사2016_22-07-3":{"w":"부동산등기규칙 제59조 제2호: 인감증명·법인등기사항증명서·주민등록표등본·대장등본처럼 별도의 방법으로 다시 취득할 수 있는 서류는 원본 환부를 청구할 수 없다.","c":"상","v":1},"법무사2016_22-07-4":{"w":"부동산등기규칙 제62조가 인감증명·법인등기사항증명서·주민등록표등본·초본·가족관계등록사항별증명서·건축물대장 등 대장 등본을 발행일부터 3개월 이내의 것으로 제한한다.","c":"상","v":1},"법무사2016_22-08-1":{"w":"「등기필정보가 없는 경우 확인조서 등에 관한 업무처리지침」(등기예규)은 자격자대리인이 확인서면을 작성할 때 신분증 사본을 붙이게 하는데 그 신분증에 주민등록증 발급신청 확인서도 포함한다.","c":"중","v":1},"법무사2016_22-08-2":{"w":"확인서면 제도는 자격자대리인이 제3자로서 등기의무자 본인을 확인하는 것이다(부동산등기법 제51조). 법무사가 등기의무자 본인이면 자기에 대한 확인서면을 스스로 작성할 수 없다는 것이 등기예규다.","c":"중","v":1},"법무사2016_22-08-4":{"w":"「법인이 등기필증을 멸실한 경우 지배인의 확인으로 갈음할 수 있는지」 등기예규는 등기의무자가 법인이면 확인조서·확인서면·공정증서를 작성할 때 그 지배인을 확인하는 방법도 허용한다.","c":"상","v":1},"법무사2016_22-08-5":{"w":"확인서면에는 등기의무자의 우무인을 찍게 하되 우무인을 찍을 수 없는 특별한 사정이 있으면 좌무인을 찍고 특기사항란에 그 취지와 사유를 적을 수 있다(등기필정보가 없는 경우의 확인서면에 관한 등기예규).","c":"중","v":1},"법무사2016_22-09-3":{"w":"보정명령은 보정이 없으면 각하할 수밖에 없는 경우에 한다(부동산등기법 제29조 단서, 보정에 관한 등기예규). 등기관은 그 사유를 전산정보처리조직에 등록한 뒤 보정을 명한다.","c":"중","v":1},"법무사2016_22-11-1":{"w":"중재판정이나 외국판결은 그 자체로 집행력이 없고 집행판결을 받아야 집행할 수 있다(중재법 제37조, 민사집행법 제26조). 그래서 판결에 의한 등기신청(부동산등기법 제23조 제4항)으로 단독신청하려면 집행판결을 함께 제공해야 한다.","c":"중","v":1},"법무사2016_22-11-3":{"w":"가처분결정은 임시적인 보전처분이어서 등기절차 이행을 명하는 조항이 있어도 부동산등기법 제23조 제4항의 확정판결에 해당하지 않는다(판결에 의한 등기신청에 관한 등기예규). 단독신청의 근거가 되지 못한다.","c":"중","v":1},"법무사2016_22-11-4":{"w":"등기절차 이행을 명하는 확정판결은 집행을 위한 것이 아니라 의사표시를 갈음하는 것이어서 소멸시효나 집행기간의 제한을 받지 않는다. 확정 후 10년이 지나도 그 판결로 등기를 신청할 수 있다(판결에 의한 등기신청에 관한 등기예규).","c":"중","v":1},"법무사2016_22-11-5":{"w":"의사표시를 명하는 판결은 확정되어야 의사표시가 있는 것으로 보므로(민사집행법 제263조 제1항) 가집행선고가 붙은 미확정 판결로는 등기를 신청할 수 없다. 이러한 신청은 각하한다(판결에 의한 등기신청에 관한 등기예규).","c":"중","v":1},"법무사2016_22-20-3":{"w":"「남북 주민 사이의 가족관계와 상속 등에 관한 특례법」 제13조 제3항·제4항: 법무부장관이 북한주민등록대장에 등록된 북한주민에게 북한주민등록번호를 부여하며 남한 부동산을 등기할 때 이를 부동산등기용등록번호로 본다.","c":"상","v":1},"법무사2017_23-03-1":{"w":"부동산등기법 제2조 제4호는 등기필정보를 등기부에 새로운 권리자가 기록되는 경우 그 권리자를 확인하려고 등기관이 작성한 정보로 정의한다.","c":"상","v":1},"법무사2017_23-03-2":{"w":"부동산등기법 제50조 제1항 제2호: 국가나 지방자치단체가 등기권리자이면 등기필정보를 작성·통지하지 않는다.","c":"상","v":1},"법무사2017_23-03-3":{"w":"부동산등기규칙 제109조 제2항 제4호: 채권자가 등기권리자를 대위하여 등기신청을 한 경우에는 등기필정보를 작성·통지하지 않는다. 신청인과 권리자가 달라 통지할 상대가 맞지 않기 때문이다.","c":"상","v":1},"법무사2017_23-03-4":{"w":"등기필정보는 새로운 권리자가 등기부에 기록될 때 작성한다(부동산등기법 제50조 제1항). 甲 단독소유를 甲·乙 공유로 경정하거나 합유자를 추가하면 乙 등이 새로 권리자로 기록되므로 그에게 등기필정보를 작성·통지한다(등기필정보에 관한 등기예규).","c":"중","v":1},"법무사2017_23-08-1":{"w":"부재자 재산관리인은 민법 제118조의 관리행위만 할 수 있고 처분행위는 민법 제25조에 따라 법원의 허가를 받아야 한다. 처분에 관한 등기를 신청할 때 그 허가서를 첨부한다.","c":"중","v":1},"법무사2017_23-08-2":{"w":"향교재산법 제11조 제1항이 향교재단이 부동산을 처분하거나 담보로 제공할 때 대통령령에 따라 시·도지사(특별자치도지사 포함)의 허가를 받도록 정한다.","c":"중","v":1},"법무사2017_23-08-3":{"w":"전통사찰의 보존 및 지원에 관한 법률 제9조 제1항이 전통사찰보존지 안의 사찰 또는 소속 단체 소유 부동산을 양도할 때 사찰이 속한 단체 대표자의 승인서를 붙여 문화체육관광부장관의 허가를 받도록 정한다.","c":"중","v":1},"법무사2017_23-08-5":{"w":"재단법인 기본재산의 처분은 정관변경 사항이어서 주무관청의 허가가 효력요건이다(민법 제42조 제2항, 제45조 제3항). 등기신청에는 그 허가서만 첨부하면 되고 정관이나 이사회 회의록은 필요 없다는 것이 등기선례다.","c":"중","v":1},"법무사2017_23-09-3":{"w":"조정조서와 화해조서는 성립과 동시에 확정판결과 같은 효력이 있어 확정증명이 필요 없다. 조정에 갈음하는 결정과 화해권고결정은 송달 후 2주 안에 이의가 없어야 확정되므로 확정증명서를 함께 낸다(판결에 의한 등기신청에 관한 등기예규).","c":"중","v":1},"법무사2017_23-27-1":{"w":"관공서의 촉탁은 우편으로도 할 수 있으며 촉탁서 제출을 법무사 등에게 위임할 수도 있다. 이때 위임받았음을 증명하는 서면을 붙인다(관공서의 촉탁등기에 관한 등기예규).","c":"중","v":1},"법무사2017_23-27-2":{"w":"부동산등기법 제98조 제1항: 국가나 지방자치단체가 등기권리자이면 등기의무자의 승낙을 받아 지체 없이 등기소에 촉탁해야 한다.","c":"상","v":1},"법무사2017_23-27-3":{"w":"관공서가 등기의무자이든 등기권리자이든 촉탁으로 등기하는 경우에는 등기의무자의 등기필정보를 제공하지 않아도 된다(관공서의 촉탁등기에 관한 등기예규). 관공서의 촉탁은 공무원의 직무상 행위여서 진정성이 담보되기 때문이다.","c":"중","v":1},"법무사2017_23-27-5":{"w":"교육비특별회계 소관 공유재산의 소관청은 교육감인데, 조례로 취득·처분 권한이 교육장에게 위임되었다면 교육장이 위임 근거규정을 밝혀 등기를 촉탁할 수 있다는 것이 등기선례다.","c":"중","v":1},"법무사2018_24-01-1":{"w":"민법 제909조 제2항·제3항: 혼인 중 친권은 부모가 공동으로 행사하되 한쪽이 행사할 수 없으면 다른 한쪽이 행사한다. 그래서 그 사유를 증명하는 서면을 붙여 한 사람이 단독으로 미성년자를 대리해 등기를 신청할 수 있다.","c":"중","v":1},"법무사2018_24-01-2":{"w":"민법 제921조: 친권자와 자 사이 또는 같은 친권에 따르는 여러 자 사이에 이해가 상반되는 행위는 친권자가 법원에 특별대리인 선임을 청구해 그 특별대리인이 대리한다.","c":"상","v":1},"법무사2018_24-01-3":{"w":"미성년자 2인의 공유물분할은 서로 이해가 상반되므로 민법 제921조 제2항에 따라 한쪽에 특별대리인을 선임해야 한다. 나머지 한 명은 친권자가 대리하므로 특별대리인은 1인만 있으면 된다(미성년자의 대리에 관한 등기예규).","c":"중","v":1},"법무사2018_24-01-4":{"w":"친권자와 미성년자를 공동채무자로 하거나 미성년자만 채무자로 하여 저당권을 설정하는 것은 친권자에게 이익이 되고 자에게 불이익이 되는 관계가 아니어서 이해상반행위가 아니라는 것이 등기예규다. 특별대리인을 선임할 필요가 없다.","c":"중","v":1},"법무사2018_24-05-1":{"w":"「재외국민 및 외국인의 부동산등기신청절차에 관한 예규」(등기예규 제1778호)에 따르면 인감제도가 있는 나라의 외국인은 본국 관공서의 인감증명을 내면 되고 매도용일 필요가 없다. 재외국민은 인감증명법상 부동산 매도용 인감증명을 내야 한다.","c":"중","v":1},"법무사2018_24-05-2":{"w":"등기예규 제1778호에 따르면 외국국적동포는 국내거소신고번호를 부동산등기용등록번호로 쓸 수 있다(재외동포법 제9조). 재외국민은 주민등록번호가 있으면 이를 쓰고 없으면 등기관이 부여한 부동산등기용등록번호를 쓴다.","c":"중","v":1},"법무사2018_24-05-4":{"w":"등기예규 제1778호: 본국에 주소증명서나 거주사실증명서를 발급하는 기관이 없는 외국인은 주소를 공증한 서면을 낼 수 있는데 이는 본국 공증인이 공증한 서면을 말한다.","c":"중","v":1},"법무사2018_24-05-5":{"w":"등기예규 제1778호는 재외국민이 상속재산 협의분할서에 한 서명이나 날인이 본인의 것임을 증명하는 재외공관의 확인서나 공정증서로 인감증명을 갈음할 수 있게 한다. 부동산등기규칙 제61조 제3항도 재외공관 공증법에 따른 인증으로 인감증명을 갈음하게 한다.","c":"중","v":1},"법무사2018_24-07-1":{"w":"부동산등기규칙 제122조: 소유권이전등기를 할 때 주소증명정보로 등기의무자의 등기기록상 주소가 신청정보상 주소로 바뀐 사실이 명백하면 등기관이 직권으로 등기명의인표시 변경등기를 한다.","c":"상","v":1},"법무사2018_24-07-2":{"w":"부동산등기규칙 제46조 제1항 제6호는 새로 등기명의인이 되는 경우 등기권리자의 주소증명정보를, 소유권이전등기이면 등기의무자의 주소증명정보도 내게 한다. 말소등기는 새 명의인이 생기지 않으며 가등기는 소유권이전등기가 아니어서 등기의무자의 주소증명정보가 필요 없다.","c":"중","v":1},"법무사2018_24-07-3":{"w":"주소증명정보는 주민등록표등본·초본 등 주소를 증명하는 공적 서면이어야 한다. 인감증명서에 같은 인적사항이 적혀 있거나 매수인의 주민등록증을 대조하더라도 이를 갈음하지 못한다는 것이 등기선례다.","c":"중","v":1},"법무사2018_24-07-4":{"w":"미수복지구 호적을 가진 자와 혼인해 제적된 사실만 확인되고 다른 주소를 알 수 없으면 제적사유에 적힌 혼가의 본적지를 주소로 하고 그 제적부나 호적등본을 상속증명서면 겸 주소증명서면으로 낼 수 있다는 것이 등기선례다.","c":"하","v":1},"법무사2018_24-14-1":{"w":"부동산등기법 제28조: 채권자는 민법 제404조에 따라 채무자를 대위해 등기를 신청할 수 있다. 상속인에 대한 이전등기 승소판결을 받은 매수인은 그 판결정본을 대위원인 증명서면으로 하여 상속등기를 대위신청한다.","c":"중","v":1},"법무사2018_24-14-2":{"w":"부동산등기법 제46조 제1항·제2항: 구분건물 일부만 보존등기를 신청하면 나머지 구분건물의 표시에 관한 등기를 동시에 신청해야 하는데 이때 신청인은 다른 구분건물의 소유자를 대위해 그 표시등기를 신청할 수 있다.","c":"상","v":1},"법무사2018_24-14-3":{"w":"부동산등기법 제43조 제1항·제2항: 건물이 멸실되면 소유권 등기명의인이 1개월 안에 멸실등기를 신청해야 하며 이를 하지 않으면 건물대지의 소유자가 대위해 신청할 수 있다.","c":"상","v":1},"법무사2018_24-14-5":{"w":"부동산등기법 제96조: 관공서가 체납처분으로 인한 압류등기를 촉탁할 때 등기명의인이나 상속인 등을 갈음해 부동산 표시·등기명의인 표시의 변경·경정이나 상속 등 포괄승계로 인한 권리이전등기를 함께 촉탁할 수 있다.","c":"상","v":1},"법무사2018_24-21-1":{"w":"부동산등기규칙 제53조 제1항 제2호: 대위자의 등기신청에서 피대위자, 곧 등기권리자에게 등기완료통지를 한다.","c":"상","v":1},"법무사2018_24-21-2":{"w":"부동산등기규칙 제53조 제1항 제4호: 법 제66조에 따른 직권 소유권보존등기(처분제한 등기 촉탁 시)에서 등기명의인에게 등기완료통지를 한다.","c":"상","v":1},"법무사2018_24-21-3":{"w":"부동산등기규칙 제53조 제1항 제3호: 등기필정보 없이 법 제51조의 확인정보 등을 제공한 등기신청에서 등기의무자에게 등기완료통지를 한다. 본인 모르게 등기가 되는 것을 막기 위해서다.","c":"상","v":1},"법무사2018_24-21-5":{"w":"「등기완료통지서의 작성 등에 관한 업무처리지침」(등기예규 제1860호)은 공동신청의 등기의무자에게는 신청서에 통지를 원한다는 의사표시가 적혀 있을 때만 등기완료통지를 하도록 정한다.","c":"상","v":1},"법무사2018_24-23-1":{"w":"등기필정보가 없어 법인 지배인이 확인을 받아 법인 명의 근저당권말소를 신청하면 지배인 자격증명서면과 함께 지배인의 인감증명을 낸다(등기예규). 부동산등기규칙 제60조 제1항 제3호는 소유권 외의 권리 명의인이 법 제51조로 신청할 때 인감증명을 요구한다.","c":"중","v":1},"법무사2018_24-23-2":{"w":"부동산등기규칙 제60조 제1항 제1호는 소유권 등기명의인이 등기의무자일 때 인감증명을 요구한다. 근저당권자는 소유권 외의 권리자여서 등기필정보를 제공하는 통상의 경우 인감증명을 내지 않는다(제3호의 법 제51조 신청만 예외).","c":"상","v":1},"법무사2018_24-23-3":{"w":"부동산등기규칙 제60조 제1항 제2호: 소유권에 관한 가등기명의인이 가등기 말소를 신청하면 가등기명의인의 인감증명을 제출한다. 가등기명의인 단독으로 말소할 수 있으므로(부동산등기법 제93조) 진정성을 인감으로 확인한다.","c":"상","v":1},"법무사2018_24-23-5":{"w":"인감증명법 제3조 제3항은 출입국관리법에 따라 외국인등록을 한 외국인도 체류지 관할 행정청에 인감을 신고할 수 있게 한다. 그러므로 인감증명법상 인감증명을 발급받아 낼 수 있다(등기예규 제1778호).","c":"중","v":1},"법무사2018_24-25-5":{"w":"농어촌정비법에 따른 농지의 교환·분할·합병에 따른 등기는 농지법 제8조 제1항 단서의 농지취득자격증명이 필요 없는 경우로 등기예규에 열거되어 있다. 종중이 시행한 경우에도 같다.","c":"중","v":1},"법무사2019_25-01-5":{"w":"관공서가 등기의무자로서 촉탁하거나 권리를 취득해 등기권리자로서 촉탁하는 경우 등기의무자의 등기필정보를 제공할 필요가 없다(관공서의 촉탁등기에 관한 등기예규). 관공서의 촉탁은 진정성이 담보되기 때문이다.","c":"중","v":1},"법무사2019_25-08-1":{"w":"부동산등기법 제27조: 등기원인이 생긴 뒤 등기권리자나 등기의무자에게 상속 등 포괄승계가 있으면 포괄승계인이 그 등기를 신청할 수 있다. 상대방과 공동으로 신청한다.","c":"상","v":1},"법무사2019_25-08-2":{"w":"부동산등기법 제23조 제3항: 상속, 법인의 합병, 그 밖에 대법원규칙으로 정하는 포괄승계에 따른 등기는 등기권리자가 단독으로 신청한다.","c":"상","v":1},"법무사2019_25-08-3":{"w":"등기는 권리변동 과정을 그대로 반영해야 하므로 상속인으로부터 매수한 경우 먼저 상속을 원인으로 상속인 앞으로 이전등기를 한 뒤 매수인 앞으로 이전등기를 한다. 등기원인 발생 전에 상속이 있었으므로 제27조의 포괄승계인 신청은 쓸 수 없다.","c":"중","v":1},"법무사2019_25-08-5":{"w":"부동산등기규칙 제49조는 상속 등 포괄승계에 따른 등기를 신청할 때 포괄승계 사실을 증명하는 정보(가족관계등록사항별증명서 등)를 제공하도록 정한다.","c":"중","v":1},"법무사2019_25-16-1":{"w":"채권자대위소송에서 채무자가 소송 계속을 알았다면 판결의 효력이 채무자에게 미치므로 채무자도 그 판결로 단독으로 등기를 신청할 수 있다. 다른 채권자도 그 판결로 채무자를 대위해 신청할 수 있다(판결에 의한 등기신청에 관한 등기예규).","c":"중","v":1},"법무사2019_25-16-2":{"w":"조정조서의 등기절차 이행 조항은 원고의 대금 지급과 상환 조건이 아니라 별개 조항으로 되어 있어 반대급부가 조건으로 붙어 있지 않다. 그러므로 집행문 없이 조서정본만으로 원고가 단독신청한다(판결에 의한 등기신청에 관한 등기예규).","c":"중","v":1},"법무사2019_25-16-3":{"w":"순차 이행판결로 丙이 乙을 대위해 甲→乙 이전등기를 신청하면 새 명의인이 되는 乙의 주소증명서면이 필요하다(부동산등기규칙 제46조 제1항 제6호). 乙에게 공시송달했다면 판결에 적힌 乙의 최후 주소를 증명하는 서면을 낸다(등기예규).","c":"중","v":1},"법무사2019_25-16-5":{"w":"판결이나 화해조서에 의한 단독신청(부동산등기법 제23조 제4항)은 그 집행권원의 당사자인 승소 등기권리자만 할 수 있다. 화해조서의 당사자가 아닌 乙·丙은 이를 근거로 단독신청하지 못한다.","c":"중","v":1},"법무사2019_25-26-1":{"w":"「본인서명사실 확인 등에 관한 법률에 따른 등기사무처리지침」(등기예규)은 본인서명사실확인서와 신청서 등의 서명을 본인 고유의 필체로 자신의 성명을 알아볼 수 있게 쓰도록 정한다.","c":"중","v":1},"법무사2019_25-26-3":{"w":"본인서명사실확인서에는 용도와 거래상대방이 기재되므로 거래상대방과 등기권리자의 인적사항이 다르면 수리하지 않는다(본인서명사실확인서 등기사무처리지침).","c":"중","v":1},"법무사2019_25-26-4":{"w":"본인서명사실확인서로 대리신청하면 위임받은 사람란에 대리인의 성명·주소가 있어야 하지만 자격자대리인이면 「법무사 홍길동」처럼 자격명과 성명만 있으면 주소는 없어도 된다(본인서명사실확인서 등기사무처리지침).","c":"중","v":1},"법무사2019_25-26-5":{"w":"본인서명사실 확인 등에 관한 법률과 본인서명사실확인서 등기사무처리지침(등기예규)은 인감증명을 내야 하는 경우 인감 날인 대신 서명하고 본인서명사실확인서를 제출할 수 있게 한다.","c":"중","v":1},"법무사2020_26-01-1":{"w":"부동산등기법 제24조 제1항 제1호: 방문신청은 신청인이나 대리인이 등기소에 출석해 서면을 제출하되, 대리인이 변호사나 법무사이면 대법원규칙으로 정하는 사무원을 출석시켜 제출할 수 있다.","c":"상","v":1},"법무사2020_26-01-2":{"w":"법인 대표자가 등기신청을 위임한 뒤 대표자가 바뀌어도 위임은 법인이 한 것이어서 대리권이 소멸하지 않는다(민법 제127조의 소멸사유도 아님). 그래서 새 대표이사 명의로 위임장을 다시 받을 필요가 없다는 것이 등기선례다.","c":"중","v":1},"법무사2020_26-01-4":{"w":"쌍방으로부터 등기신청을 위임받은 법무사의 위임은 등기권리자의 이익도 위한 것이어서 등기의무자 한쪽이 마음대로 해지할 수 없다. 그래서 법무사는 의무자의 중지 요청을 거부할 위임계약상 의무가 있다는 것이 판례다.","c":"중","v":1},"법무사2020_26-01-5":{"w":"학교는 교육시설에 불과해 권리능력이 없으므로 학교 명의로는 등기권리자도 등기의무자도 될 수 없다. 설립자(학교법인·국가·지방자치단체 등) 명의로 등기해야 한다는 것이 판례·등기예규다.","c":"중","v":1},"법무사2020_26-10-1":{"w":"부동산등기규칙 제60조와 인감증명법 시행령은 매매로 인한 소유권이전등기에 부동산매도용 인감증명을 요구한다. 매매 외의 등기는 인감증명서에 적힌 용도와 등기목적이 달라도 수리한다는 것이 등기예규다.","c":"중","v":1},"법무사2020_26-10-3":{"w":"부동산등기규칙 제60조 제1항 제6호: 협의분할에 의한 상속등기를 신청하면 상속인 전원의 인감증명을 낸다. 해당 부동산을 취득하는 상속인도 협의서 작성자이므로 포함된다.","c":"상","v":1},"법무사2020_26-10-4":{"w":"인감증명서의 주소가 현주소와 달라도 주민등록표의 주소이동 내역에 종전 주소로 나오거나 성명·주민등록번호로 동일인임이 확인되면 수리한다는 것이 등기예규다. 인감증명은 본인 의사 확인용이어서 동일인이면 충분하다.","c":"중","v":1},"법무사2020_26-10-5":{"w":"부동산등기규칙 제62조가 인감증명의 유효기간을 발행일부터 3개월로 정한다. 기간은 민법 기간 규정에 따라 초일을 산입하지 않으며(제157조) 말일이 공휴일이면 다음 날 만료한다(제161조).","c":"중","v":1},"법무사2020_26-11-1":{"w":"농지법 제2조 제1호 가목: 농지는 전·답·과수원, 그 밖에 법적 지목을 불문하고 실제로 농작물 경작지 또는 대통령령으로 정하는 다년생식물 재배지로 이용되는 토지를 말한다.","c":"중","v":1},"법무사2020_26-11-3":{"w":"농지법 제8조 제1항 단서와 농지취득자격증명에 관한 등기예규는 상속·포괄유증·상속인에 대한 특정유증·취득시효·공유물분할·진정명의회복을 원인으로 한 이전등기에 농지취득자격증명을 요구하지 않는다.","c":"중","v":1},"법무사2020_26-11-4":{"w":"취득시효 원인 등기에 농지취득자격증명이 필요 없다는 것은 농지를 소유할 수 있는 자에 대한 절차상 면제일 뿐이다. 농지 소유가 제한되는 종교법인은 농지법 제6조 제2항의 예외에 해당하지 않으면 승소판결이 있어도 그 이전등기를 할 수 없다는 것이 등기선례다.","c":"중","v":1},"법무사2020_26-11-5":{"w":"지목이 농지라도 실제로 경작에 쓰이지 않는다는 사실이 관할관청이 발급한 서면으로 증명되면 농지가 아니므로 농지취득자격증명 없이 소유권이전등기를 신청할 수 있다(농지취득자격증명에 관한 등기예규).","c":"중","v":1},"법무사2020_26-16-1":{"w":"공유물분할판결은 형성판결로서 확정되면 각 공유자가 분할된 부분의 단독소유권을 취득한다(민법 제187조). 부동산등기법 제23조 제4항에 따라 공유물분할판결에 의한 등기는 등기권리자나 등기의무자가 단독으로 신청한다.","c":"상","v":1},"법무사2020_26-16-2":{"w":"근저당권설정등기에는 채권최고액과 채무자가 필수 기록사항이다(부동산등기법 제75조 제2항). 판결 주문에 이것이 없으면 판결로 등기할 내용을 특정할 수 없어 그 판결로는 신청할 수 없다(판결에 의한 등기신청에 관한 등기예규).","c":"중","v":1},"법무사2020_26-16-4":{"w":"판결에 의한 등기신청에 관한 등기예규는 화해조서 등에 등기원인과 연월일이 없으면 등기원인을 「화해」「인낙」「화해권고결정」「조정」「조정에 갈음하는 결정」 등으로, 연월일을 조서기재일이나 결정확정일로 적게 한다.","c":"중","v":1},"법무사2020_26-16-5":{"w":"말소등기를 명하는 집행권원의 효력은 그 주문에 적힌 등기에만 미친다. 丙 명의 상속등기 말소를 명한 강제조정으로는 그 등기만 말소할 뿐 그에 따라 회복되는 乙 명의 이전등기까지 말소할 수는 없다는 것이 등기선례다.","c":"중","v":1},"법무사2020_26-17-2":{"w":"위임장에 공동 대리 특약이 없으면 합동사무소 법무사 각자가 대리권을 가진다(민법 제119조 각자대리). 그래서 한 법무사가 제출한 신청이라도 위임장에 적힌 다른 법무사가 보정할 수 있다는 것이 등기선례다.","c":"중","v":1},"법무사2020_26-19-1":{"w":"국가·지방자치단체가 아닌 공사 등은 법령에 등기촉탁 규정이 있어야 촉탁할 수 있다. 관공서의 촉탁은 출석이 필요 없어 우편으로도 할 수 있다(관공서의 촉탁등기에 관한 등기예규).","c":"중","v":1},"법무사2020_26-19-2":{"w":"관공서가 거래 주체로서 촉탁할 수 있는 경우에도 촉탁은 공동신청에 갈음하는 편의 제도일 뿐이다. 관공서는 일반 당사자처럼 상대방과 공동으로 신청할 수도 있다(관공서의 촉탁등기에 관한 등기예규).","c":"중","v":1},"법무사2020_26-19-3":{"w":"매각이나 공매처분을 원인으로 관공서가 소유권이전등기를 촉탁할 때는 등기의무자의 주소증명정보를 제공할 필요가 없다(관공서의 촉탁등기에 관한 등기예규). 등기의무자의 의사와 무관한 강제적 이전이기 때문이다.","c":"중","v":1},"법무사2020_26-19-5":{"w":"관공서의 촉탁에는 부동산등기법 제29조 제11호(대장과 부동산 표시 불일치)를 적용하지 않는다는 것이 관공서 촉탁등기에 관한 등기예규다. 그래서 대장과 표시가 맞지 않아도 수리한다.","c":"중","v":1},"법무사2020_26-25-1":{"w":"민법 제404조의 채권자대위권은 특정채권뿐 아니라 금전채권을 보전하기 위해서도 행사할 수 있다. 부동산등기법 제28조도 채권의 종류를 제한하지 않는다. 금전채권자는 채무자의 무자력이 요건이지만 등기관은 이를 심사하지 않는다.","c":"중","v":1},"법무사2020_26-25-2":{"w":"근저당권자가 임의경매를 신청하려면 상속인 명의로 소유권을 정리해야 하므로 상속인을 대위해 상속등기를 신청할 수 있다(부동산등기법 제28조). 근저당권자는 피보전채권을 가진 채권자로 대위원인이 있다.","c":"중","v":1},"법무사2020_26-25-4":{"w":"대위신청에는 대위원인을 증명하는 정보를 내야 한다(부동산등기규칙 제50조). 이 서면은 매매계약서 같은 사서증서여도 되고 공정증서일 필요는 없다는 것이 등기예규다.","c":"중","v":1},"법무사2020_26-25-5":{"w":"부동산등기법 제28조 제2항: 대위신청으로 등기할 때 등기관은 대위자의 성명 또는 명칭, 주소 또는 사무소 소재지, 대위원인을 기록한다.","c":"상","v":1},"법무사2021_27-01-1":{"w":"부동산등기법 제23조 제4항: 판결에 의한 등기는 승소한 등기권리자나 승소한 등기의무자가 단독으로 신청한다. 공유물을 분할하는 판결에 의한 등기는 등기권리자 또는 등기의무자가 단독으로 신청한다.","c":"상","v":1},"법무사2021_27-01-2":{"w":"변론종결 뒤 제3자 앞으로 이전등기가 되었더라도 그가 변론종결 후 승계인이면 판결의 기판력이 미친다(민사소송법 제218조 제1항). 승계집행문을 받으면 그 제3자를 등기의무자로 하여 바로 판결에 따른 이전등기를 단독신청할 수 있다(판결에 의한 등기신청에 관한 등기예규).","c":"중","v":1},"법무사2021_27-01-3":{"w":"판결에 의한 등기신청에 관한 등기예규는 공유물분할판결의 등기원인을 「공유물분할」, 그 연월일을 판결확정일로 적게 한다. 공유물분할판결은 확정으로 효력이 생기는 형성판결이다.","c":"중","v":1},"법무사2021_27-01-4":{"w":"공유물분할판결의 변론종결 뒤 확정 전에 지분을 넘겨받은 제3자는 변론종결 후 승계인이어서 판결의 효력이 미친다. 승계집행문을 받으면 그 제3자는 다른 공유자 명의 지분을 곧바로 자기 앞으로 이전등기하도록 단독신청할 수 있다(등기예규).","c":"중","v":1},"법무사2021_27-04-1":{"w":"「재외국민 및 외국인의 부동산등기신청절차에 관한 예규」(등기예규 제1778호)는 재외국민·외국인이 처분권한을 대리인에게 줄 때 처분대상 부동산, 처분 목적인 권리, 대리인 인적사항을 구체적으로 특정한 처분위임장을 내게 한다.","c":"중","v":1},"법무사2021_27-04-2":{"w":"부동산등기규칙 제61조 제4항 단서: 본국에 인감제도가 없고 인감증명법상 인감증명도 받을 수 없는 외국인은 신청서나 위임장 등에 본인이 서명·날인했다는 뜻의 본국 관공서 증명이나 공증을 받으면 된다. 등기예규 제1778호는 대한민국 공증인의 인증도 허용한다.","c":"중","v":1},"법무사2021_27-04-4":{"w":"등기예규 제1778호는 외국 공문서나 외국 공증인이 공증한 문서를 첨부할 때 재외공관 공증법 제30조 제1항에 따른 영사 확인이나 아포스티유 협약에 따른 아포스티유를 붙이게 한다.","c":"중","v":1},"법무사2021_27-04-5":{"w":"부동산등기법 제49조 제1항 제2호: 주민등록번호가 없는 재외국민의 부동산등기용등록번호는 대법원 소재지 관할 등기소, 곧 서울중앙지방법원 등기국의 등기관이 부여한다. 등기권리자가 되면 그 번호를 증명하는 정보를 낸다.","c":"상","v":1},"법무사2021_27-06-1":{"w":"부동산등기규칙 제46조 제1항 제5호: 대리인이 등기를 신청하면 그 권한을 증명하는 정보(위임장 등)를 첨부정보로 제공한다.","c":"상","v":1},"법무사2021_27-06-3":{"w":"쌍방으로부터 위임받은 법무사의 위임은 상대방의 이익도 위한 것이어서 한쪽 당사자가 일방적으로 철회하지 못한다. 등기의무자의 중지 요청을 거부할 위임계약상 의무가 있다는 것이 판례다.","c":"중","v":1},"법무사2021_27-06-4":{"w":"민법 제124조 단서는 채무의 이행에는 자기계약·쌍방대리를 허용한다. 등기신청은 이미 성립한 법률관계의 이행이어서 등기권리자가 등기의무자의 대리인이 되거나 한 사람이 쌍방을 대리할 수 있다.","c":"중","v":1},"법무사2021_27-06-5":{"w":"등기필정보는 등기신청의 결과로 통지되는 것이어서 등기신청 대리권에는 등기필정보 수령 권한이 포함된다고 본다(등기필정보에 관한 등기예규). 그래서 대리인이 등기필정보를 받아 본인에게 전달한다.","c":"중","v":1},"법무사2021_27-13-1":{"w":"부동산등기법 제23조 제2항: 소유권보존등기 또는 소유권보존등기의 말소등기는 등기명의인으로 될 자나 등기명의인이 단독으로 신청한다.","c":"상","v":1},"법무사2021_27-13-2":{"w":"부동산등기법 제89조는 가등기권리자가 가등기의무자의 승낙이나 가등기가처분명령을 받으면 단독으로 가등기를 신청할 수 있게 한다. 제93조 제1항은 가등기명의인이 단독으로 가등기 말소를 신청할 수 있게 한다.","c":"상","v":1},"법무사2021_27-13-3":{"w":"부동산등기법 제23조 제6항: 등기명의인표시의 변경이나 경정의 등기는 해당 권리의 등기명의인이 단독으로 신청한다.","c":"상","v":1},"법무사2021_27-13-5":{"w":"부동산등기법 제99조 제1항: 수용으로 인한 소유권이전등기는 제23조 제1항의 공동신청 원칙에도 불구하고 등기권리자가 단독으로 신청할 수 있다.","c":"상","v":1},"법무사2021_27-18-1":{"w":"사립학교법 제28조 제2항과 시행령 제12조는 학교교육에 직접 사용되는 학교법인의 재산을 매도하거나 담보로 제공할 수 없게 한다. 같은 법 제51조가 사립학교경영자에게 이를 준용하므로 경영자 개인 소유라도 같다.","c":"중","v":1},"법무사2021_27-18-2":{"w":"판례는 허가구역 안의 토지를 허가 없이 매매하면 허가 전에는 채권적 효력도 없는 무효 상태지만 허가를 받으면 소급해 유효해지므로 그 사이를 유동적 무효로 본다.","c":"중","v":1},"법무사2021_27-18-3":{"w":"등기관이 직권말소할 수 있는 것은 부동산등기법 제29조 제1호·제2호에 해당하는 등기뿐이다(제58조). 허가가 나중에 취소된 것은 등기 당시 각하사유가 아니므로 직권말소할 수 없고 당사자가 말소를 신청해야 한다.","c":"중","v":1},"법무사2021_27-18-4":{"w":"사립학교법 제28조 제1항은 학교법인의 기본재산을 처분할 때 관할청의 허가를 받게 한다. 공유물분할도 지분의 교환·처분에 해당하므로 학교법인이 공유자이면 관할청 허가서를 첨부한다는 것이 등기선례다.","c":"중","v":1},"법무사2021_27-19-1":{"w":"합병된 甲 토지의 등기기록은 폐쇄되고 그 권리관계가 乙 토지 등기기록에 옮겨지므로 합병 후 乙 토지에 대한 신청에는 乙 토지의 등기필정보만 제공하면 된다는 것이 등기선례다.","c":"중","v":1},"법무사2021_27-19-2":{"w":"부동산등기규칙 제109조 제2항 제3호·제4호: 승소한 등기의무자의 등기신청과 채권자의 대위신청에서는 등기필정보를 작성·통지하지 않는다. 신청인이 등기권리자가 아니기 때문이다.","c":"상","v":1},"법무사2021_27-19-3":{"w":"2011년 전부개정 부동산등기법 부칙과 등기필정보에 관한 등기예규에 따라 개정법 시행 전에 등기필증을 받은 사람은 지금 등기의무자로 신청할 때 등기필정보 대신 그 등기필증을 낸다.","c":"중","v":1},"법무사2021_27-19-5":{"w":"판례는 구법의 등기필증 「멸실」에 분실은 포함하지만 등기필증이 다른 사람이 가지고 있어서 돌려받기 어려운 경우는 포함하지 않는다고 보았다. 그 경우에는 반환을 청구해야 한다.","c":"중","v":1},"법무사2021_27-29-1":{"w":"농지법 제8조 제1항은 농지를 취득하는 자에게 면적과 무관하게 농지취득자격증명을 받도록 한다. 그래서 종전 농지를 처분한 뒤 새로 매수하는 경우에도 매수 농지의 이전등기에 이를 첨부한다(농지취득자격증명에 관한 등기예규).","c":"중","v":1},"법무사2021_27-29-2":{"w":"농지법 제6조 제2항 제1호·제8조 제1항 제1호는 국가나 지방자치단체가 농지를 소유하는 경우 농지취득자격증명 없이 취득할 수 있게 한다.","c":"중","v":1},"법무사2021_27-29-3":{"w":"같은 세대 안 친족 간 매매라도 농지를 새로 취득하는 것이어서 농지법 제8조 제1항의 면제사유에 해당하지 않는다. 그래서 농지취득자격증명을 첨부한다(농지취득자격증명에 관한 등기예규).","c":"중","v":1},"법무사2021_27-29-5":{"w":"농지법 제8조 제1항 단서와 제6조 제2항 제7호에 따라 토지보상법에 따른 수용·협의취득은 농지취득자격증명 없이 취득할 수 있다(농지취득자격증명에 관한 등기예규).","c":"중","v":1},"법무사2022_28-05-1":{"w":"매매계약 후 매도인이 사망했으므로 등기원인 발생 뒤의 포괄승계다. 부동산등기법 제27조에 따라 상속인은 상속등기 없이 상속을 증명하는 정보를 붙여 피상속인 명의에서 바로 매수인에게 이전등기를 신청한다.","c":"상","v":1},"법무사2022_28-05-3":{"w":"말소 원인이 합병 전에 생겼다면 부동산등기법 제27조의 포괄승계인 신청에 해당한다. 신설법인 丙은 합병으로 인한 근저당권이전등기 없이 합병 증명 정보를 내고 곧바로 말소등기를 신청할 수 있다(등기예규).","c":"중","v":1},"법무사2022_28-05-4":{"w":"법률에 종전 법인 명의를 승계법인 명의로 본다는 간주 규정이 있으면 등기기록상 명의가 이미 승계법인 명의로 취급된다. 그래서 등기명의인표시 변경등기 없이 다른 등기를 신청할 수 있다는 것이 등기예규다.","c":"중","v":1},"법무사2022_28-05-5":{"w":"부동산등기법 제29조 제7호 본문은 등기의무자 표시 불일치를 각하사유로 하지만 같은 호 가목은 제27조에 따라 포괄승계인이 신청하는 경우를 제외한다.","c":"상","v":1},"법무사2022_28-08-1":{"w":"상속·포괄유증·공유물분할·진정명의회복은 농지를 새로 사들이는 행위가 아니어서 농지취득자격증명에 관한 등기예규상 첨부가 필요 없는 원인이다(농지법 제8조 제1항 단서 참조).","c":"중","v":1},"법무사2022_28-08-3":{"w":"부동산등기규칙 제46조 제1항 제2호는 등기원인에 제3자의 허가가 필요하면 그 허가 증명정보를 내게 한다. 판결에 의한 등기신청에 관한 등기예규는 판결서에 허가서 존재 사실이 적혀 있어도 허가 증명서면을 따로 내도록 정한다(소유권이전등기의 경우).","c":"중","v":1},"법무사2022_28-08-4":{"w":"사립학교법 제28조 제1항: 학교법인이 기본재산을 매도·증여·교환하거나 담보로 제공하려면 관할청의 허가를 받아야 한다. 이 허가가 등기원인의 효력요건이므로 증명서면을 첨부한다.","c":"중","v":1},"법무사2022_28-08-5":{"w":"처분제한등기 촉탁에 따른 직권 보존등기(부동산등기법 제66조)에서 건물 표시 증명정보는 집행법원이 인정한 건물의 소재·지번·구조·면적이 적힌 서면이어야 한다는 것이 등기예규다. 건축사나 측량기술자가 작성한 서면은 이에 해당하지 않는다.","c":"중","v":1},"법무사2022_28-09-1":{"w":"부동산등기규칙 제58조와 등기예규는 법무사법인이 대리인이면 담당 법무사가 누구든 그 법인 소속으로 허가받은 사무원이 신청서 제출·보정·등기필정보 수령을 할 수 있게 한다.","c":"중","v":1},"법무사2022_28-09-2":{"w":"확인서면은 자격자대리인이 제3자로서 등기의무자를 확인하는 제도다(부동산등기법 제51조). 법무사 자신이 등기의무자이면 스스로 자기에 대한 확인서면을 작성할 수 없다는 것이 등기예규다.","c":"중","v":1},"법무사2022_28-09-3":{"w":"자격자대리인 출석 확인에 관한 등기예규는 접수담당자가 변호사·법무사 신분증 외에 자격확인증으로도 출석 여부를 확인할 수 있게 한다.","c":"중","v":1},"법무사2022_28-09-5":{"w":"쌍방 위임은 등기권리자의 이익도 위한 것이므로 등기의무자가 일방적으로 철회하지 못한다. 법무사는 의무자의 중지 요청을 거부할 위임계약상 의무가 있다는 것이 판례다.","c":"중","v":1},"법무사2022_28-15-2":{"w":"甲의 금전채권자는 민법 제404조에 따라 甲의 등기신청권을 대위할 수 있다. 소비대차계약서 등 대위원인 증명서면과 甲의 승소판결을 붙여 甲 명의 이전등기를 대위신청한다(부동산등기법 제28조, 등기예규).","c":"중","v":1},"법무사2022_28-15-3":{"w":"부동산등기법 제96조: 체납처분으로 인한 압류등기를 촉탁할 때 관공서는 등기명의인이나 상속인을 갈음해 부동산 표시·명의인 표시의 변경·경정이나 상속등기를 함께 촉탁할 수 있다.","c":"상","v":1},"법무사2022_28-15-4":{"w":"사업시행자는 협의가 성립하거나 수용 효력이 생겨야 소유권이전등기청구권 등 대위원인을 갖는다. 그 전에는 토지소유자를 대위해 토지표시변경등기를 신청할 수 없다는 것이 등기선례다.","c":"중","v":1},"법무사2022_28-15-5":{"w":"경매개시결정등기는 상속인 명의로 소유권이 등기되어 있어야 할 수 있으므로 어느 방식으로 경매를 신청하든 근저당권자는 상속인을 대위해 상속등기를 해야 한다는 것이 등기선례다(부동산등기법 제28조).","c":"중","v":1},"법무사2022_28-16-1":{"w":"허가구역 지정이 해제되면 그 사이에는 허가 없이도 계약이 확정적으로 유효해진다는 것이 판례다. 그래서 다시 지정된 뒤 이전등기를 신청하더라도 토지거래계약허가증을 낼 필요가 없다(등기선례).","c":"중","v":1},"법무사2022_28-16-2":{"w":"가등기 신청 때 그 원인인 계약이나 예약에 대한 토지거래계약허가증을 이미 냈으면 본등기 신청 때 다시 낼 필요가 없다는 것이 토지거래허가에 관한 등기예규다.","c":"중","v":1},"법무사2022_28-16-3":{"w":"허가대상 토지를 여러 사람에게 공유지분으로 나누어 처분하는 것은 사실상 분할 처분과 같다. 그래서 토지거래허가에 관한 등기예규는 지분 면적이 허가 기준면적에 못 미쳐도 최초 지분이전등기에 토지거래계약허가증을 내게 한다.","c":"중","v":1},"법무사2022_28-16-4":{"w":"허가받은 매매계약 일부를 해제하는 것은 허가받은 계약 내용을 바꾸는 것이어서 변경허가 대상이다(부동산 거래신고 등에 관한 법률 제11조 제1항 후단). 그래서 일부말소 의미의 경정등기에도 토지거래계약허가증을 낸다는 것이 등기선례다.","c":"중","v":1},"법무사2022_28-17-2":{"w":"부동산등기법 제23조 제4항의 판결은 등기절차 이행을 명하는 확정판결이나 이와 같은 효력이 있는 조서를 말한다. 공정증서는 금전 등 지급에 관해서만 집행권원이 되고 의사표시를 갈음하지 못하므로 그것으로 단독신청할 수 없다(판결에 의한 등기신청에 관한 등기예규).","c":"중","v":1},"법무사2022_28-17-3":{"w":"판결에 의한 등기신청에 관한 등기예규는 판결에 등기권리자·등기의무자와 등기의 종류·원인·연월일 등 신청정보 사항이 명시되어야 한다고 정한다. 전세권설정등기는 전세금과 전세권 범위가 필수 기록사항이므로(부동산등기법 제72조 제1항) 주문에 있어야 한다.","c":"중","v":1},"법무사2022_28-17-4":{"w":"승소한 등기권리자는 판결에서 등기절차 이행을 명받은 상대방에 대한 권리자를 말하므로 원고에 한하지 않는다. 반소를 제기한 피고나 당사자참가인도 승소하면 단독신청할 수 있다(판결에 의한 등기신청에 관한 등기예규).","c":"중","v":1},"법무사2022_28-17-5":{"w":"사해행위취소판결의 원상회복 등기는 채무자 명의로 돌아가는 것이지만 채권자는 판결 당사자로서 채무자를 대위해 단독신청할 수 있다. 신청서에는 등기권리자 「丙 대위신청인 乙」, 등기의무자 「甲」으로 적는다(판결에 의한 등기신청에 관한 등기예규).","c":"중","v":1},"법무사2022_28-18-1":{"w":"임의대리인이 신청을 취하하려면 취하에 관한 특별수권이 있어야 한다는 것이 등기신청 취하에 관한 등기예규다. 취하는 신청의 효과를 없애는 행위여서 신청 위임만으로는 부족하다.","c":"중","v":1},"법무사2022_28-18-3":{"w":"부동산등기규칙 제51조 제1항은 취하를 등기관이 등기를 마치기 전까지 할 수 있게 한다. 각하결정이 있으면 사건이 끝나므로 그 뒤에는 취하할 수 없다(등기신청 취하에 관한 등기예규).","c":"상","v":1},"법무사2022_28-18-4":{"w":"일괄신청은 여러 개의 신청을 한 신청서로 한 것일 뿐이어서 그중 일부 부동산에 대해서만 취하할 수 있다는 것이 등기신청 취하에 관한 등기예규다.","c":"중","v":1},"법무사2022_28-18-5":{"w":"부동산등기규칙 제51조 제2항 제1호: 방문신청의 취하는 신청인이나 대리인이 신청한 등기소에 출석해 취하서를 제출하는 방법으로 한다. 우편으로는 취하할 수 없다.","c":"상","v":1},"법무사2022_28-22-1":{"w":"부동산등기규칙 제61조 제1항: 인감증명을 내야 하는 자가 법인 아닌 사단이나 재단이면 그 대표자나 관리인의 인감증명을 낸다.","c":"상","v":1},"법무사2022_28-22-2":{"w":"인감증명은 부동산등기규칙 제60조 제1항 각 호에 해당할 때만 요구된다. 그 밖의 등기를 대리 신청하면 위임장만으로 대리권을 증명하고 등기의무자의 인감증명은 따로 붙이지 않는다는 것이 등기선례다.","c":"중","v":1},"법무사2022_28-22-3":{"w":"부동산등기규칙 제74조는 토지 일부에 지상권 등이 있을 때 분필하면 권리가 존속할 토지 표시를 신청정보로 내고 권리자의 확인 증명정보를 붙이게 한다. 제60조 제1항 제5호는 그 확인서를 낸 권리자의 인감증명도 요구한다.","c":"상","v":1},"법무사2022_28-22-5":{"w":"부동산등기규칙 제60조 제3항: 인감증명을 내야 할 자가 국가나 지방자치단체이면 인감증명을 낼 필요가 없다. 관공서가 동의·승낙 권한을 가진 경우도 같다는 것이 등기예규다.","c":"중","v":1},"법무사2022_28-23-2":{"w":"자격자대리인의 등기의무자 확인 및 자필서명정보 제공에 관한 등기예규는 관공서가 등기의무자나 등기권리자인 경우에도 자필서명정보 제공을 면제하지 않는다. 부동산등기규칙 제46조 제1항 제8호도 관공서 당사자를 제외하지 않는다.","c":"중","v":1},"법무사2022_28-23-3":{"w":"부동산등기규칙 제46조 제1항 제8호의 자필서명정보는 자격자대리인이 위임인이 등기의무자인지 확인한 사실을 담는 것이다. 자격자대리인이 등기의무자 본인이면 확인할 위임인이 없으므로 자기에 대한 자필서명정보를 따로 낼 필요가 없다(등기예규).","c":"중","v":1},"법무사2022_28-23-4":{"w":"부동산등기규칙 제47조 제2항은 같은 등기소에 동시에 여러 건을 신청할 때 같은 첨부정보는 먼저 접수되는 신청에만 내고 나머지는 그 뜻을 신청정보로 적어 갈음하게 한다. 자필서명정보도 등기의무자와 목적이 같으면 이 방법을 쓰되 부동산 전부를 적는다(등기예규).","c":"중","v":1},"법무사2022_28-23-5":{"w":"부동산등기규칙 제46조 제1항 제8호는 공동신청뿐 아니라 승소한 등기의무자의 단독신청에서도 자격자대리인이 등기의무자 여부를 확인하고 자필서명정보를 내게 한다.","c":"중","v":1},"법무사2022_28-28-1":{"w":"부동산등기규칙 제47조 제1항 제1호: 같은 채권의 담보를 위해 소유자가 다른 여러 부동산에 저당권설정등기를 신청하면 1건의 신청정보로 일괄신청할 수 있다.","c":"상","v":1},"법무사2022_28-28-2":{"w":"부동산등기법 제25조 단서는 등기목적과 등기원인이 같으면 여러 부동산에 관한 신청정보를 일괄 제공할 수 있게 한다. 소유자가 같은 여러 부동산의 공동저당 설정은 목적(저당권설정)과 원인(같은 설정계약)이 같아 이에 해당한다.","c":"상","v":1},"법무사2022_28-28-3":{"w":"여러 근저당권의 채무자 변경계약 당사자가 같으면 등기목적(근저당권변경)과 원인이 같으므로 부동산등기법 제25조 단서에 따라 한 신청서에 모두 적어 함께 신청할 수 있다는 것이 등기선례다.","c":"중","v":1},"법무사2022_28-28-5":{"w":"같은 사람 명의의 여러 근저당권에 대한 주소변경은 등기목적(등기명의인표시변경)과 원인(주소변경)이 같다. 그래서 부동산등기법 제25조 단서에 따라 한 신청서로 일괄신청할 수 있다(등기선례).","c":"중","v":1},"법무사2023_29-08-2":{"w":"매매로 인한 소유권이전등기청구권은 양도가 제한되는 성질이어서 양도하려면 매도인의 승낙이 필요하다는 것이 판례다. 그래서 가등기 이전등기에 소유명의인의 승낙 증명정보와 그 인감증명을 낸다(부동산등기규칙 제60조 제1항 제7호).","c":"중","v":1},"법무사2023_29-08-3":{"w":"부동산 거래신고 등에 관한 법률 제11조는 허가구역 안 토지의 소유권·지상권을 이전·설정하는 계약(예약 포함)에 허가를 받게 한다. 그 청구권 보전 가등기를 신청할 때에도 허가증을 낸다(토지거래허가에 관한 등기예규).","c":"중","v":1},"법무사2023_29-08-4":{"w":"학교법인에 신탁한 부동산의 신탁 해지로 인한 이전등기는 학교법인 재산의 처분에 해당한다. 사립학교법 제28조 제1항에 따라 관할청 허가를 증명하는 서면을 붙인다는 것이 등기선례다.","c":"중","v":1},"법무사2023_29-08-5":{"w":"전통사찰보존법 제9조의 허가는 사찰이 스스로 양도하는 경우에 필요하다. 민사집행법에 따른 매각은 법원이 하는 강제 환가이므로 문화체육관광부장관의 허가 증명이 필요 없다는 것이 등기선례다.","c":"중","v":1},"법무사2023_29-11-1":{"w":"등기신청의 대리인 자격에는 제한이 없다(다만 업으로 하려면 법무사·변호사여야 함). 민법 제124조 단서에 따라 채무 이행에 해당하는 등기신청은 당사자 한쪽이 상대방을 대리할 수 있다.","c":"중","v":1},"법무사2023_29-11-2":{"w":"민법 제909조 제2항은 부모가 혼인 중이면 친권을 공동으로 행사하게 한다. 그래서 미성년자를 대리한 등기신청도 원칙적으로 부모가 공동으로 한다.","c":"중","v":1},"법무사2023_29-11-3":{"w":"민법 제949조의3은 후견인과 피후견인 사이 이해상반행위에 제921조를 준용하되 후견감독인이 있으면 그가 대리한다. 후견감독인이 없으면 법원이 선임한 특별대리인이 피성년후견인을 대리한다.","c":"중","v":1},"법무사2023_29-11-5":{"w":"법무사법 제3조 제1항은 법무사가 아닌 자가 법무사 업무를 업으로 하지 못하게 한다. 법인 직원이 위임을 받아 반복적으로 등기신청을 대리하면 보수 여부와 관계없이 업으로 한 것이 되어 위반이라는 것이 판례·선례다.","c":"중","v":1},"법무사2023_29-17-1":{"w":"등기필정보통지서는 등기소에서 교부하는 것이 원칙이지만 방문신청인이 송부용 우편봉투를 함께 내면 우편으로 보낸다(등기필정보의 작성 및 통지에 관한 등기예규).","c":"중","v":1},"법무사2023_29-17-3":{"w":"등기필정보가 없으면 등기의무자나 그 법정대리인이 출석해 등기관의 확인을 받는다(부동산등기법 제51조). 법인이 등기의무자이면 그 지배인이 출석해 지배인임을 확인받는 방법도 허용된다는 것이 등기예규다.","c":"중","v":1},"법무사2023_29-17-4":{"w":"부동산등기법 제51조: 등기필정보가 없으면 신청을 위임받은 변호사·법무사가 등기의무자나 법정대리인으로부터 위임받았음을 확인한 정보를 제공할 수 있다. 등기관 확인조서나 공정증서로도 갈음한다.","c":"상","v":1},"법무사2023_29-17-5":{"w":"분양자가 대지권등기 없이 건물만 이전한 뒤 수분양자와 대지사용권 이전등기를 공동신청하는 경우(부동산등기법 제60조 제1항) 등기필정보를 제공하지 않아도 된다는 것이 대지권 등기에 관한 등기예규다. 부동산등기규칙 제46조 제4항은 이 등기에 등기원인 증명정보와 주소증명정보도 면제한다.","c":"중","v":1},"법무사2023_29-18-1":{"w":"부동산등기법 제6조 제1항과 부동산등기규칙 제3조 제1항: 등기신청은 해당 부동산이 다른 부동산과 구별될 수 있게 하는 정보가 전산정보처리조직에 저장된 때 접수된 것으로 본다.","c":"상","v":1},"법무사2023_29-18-2":{"w":"부동산등기규칙 제3조 제2항: 같은 토지 위 여러 구분건물에 대한 등기를 동시에 신청하면 건물의 소재와 지번에 관한 정보가 저장된 때 접수된 것으로 본다.","c":"상","v":1},"법무사2023_29-18-3":{"w":"등기의 순위는 법원 접수 순서가 아니라 등기소 접수 순서에 따른다(부동산등기법 제4조, 제6조). 등기관이 두 촉탁서를 동시에 받으면 같은 접수번호를 부여하고(부동산등기규칙 제65조 제2항) 두 등기는 같은 순위가 된다.","c":"상","v":1},"법무사2023_29-18-5":{"w":"부동산등기규칙 제65조 제2항: 같은 부동산에 관하여 동시에 여러 개의 등기신청이 있으면 같은 접수번호를 부여한다.","c":"상","v":1},"법무사2023_29-19-1":{"w":"부동산등기법 제50조 제2항 후문: 승소한 등기의무자가 단독으로 권리에 관한 등기를 신청할 때에도 등기의무자의 등기필정보를 제공해야 한다. 승소한 등기권리자의 신청과 다르다.","c":"상","v":1},"법무사2023_29-19-2":{"w":"채권최고액은 근저당권설정등기의 필수 기록사항이다(부동산등기법 제75조 제2항 제1호). 판결 주문에 이것이 없으면 그 판결로 등기 내용을 정할 수 없어 단독신청을 할 수 없다(판결에 의한 등기신청에 관한 등기예규).","c":"중","v":1},"법무사2023_29-19-4":{"w":"패소한 등기의무자는 판결에 의한 단독신청 권한이 없다(부동산등기법 제23조 제4항). 등기권리자에 대한 채권자도 아니어서 대위할 근거도 없다. 그래서 승소한 등기권리자를 대위해 등기를 신청할 수 없다(등기예규).","c":"중","v":1},"법무사2023_29-19-5":{"w":"등기절차 이행을 명하는 판결은 의사표시를 갈음하는 것이어서 확정 후 오랜 시간이 지나도 등기신청에 쓸 수 있다. 확정 후 10년이 지났더라도 등기관은 수리한다(판결에 의한 등기신청에 관한 등기예규).","c":"중","v":1},"법무사2023_29-24-3":{"w":"부동산매도용 인감증명은 매매 원인 소유권이전등기에 필요한 것이다. 다른 등기에 매도용 인감증명을 붙여도 본인 의사 확인에는 지장이 없으므로 수리한다는 것이 인감증명에 관한 등기예규다.","c":"중","v":1},"법무사2024_30-01-1":{"w":"본인서명사실확인서 등기사무처리지침(등기예규)은 서명을 본인 고유 필체로 성명을 알아볼 수 있게 쓰게 하며 등기관이 알아볼 수 없게 쓴 경우에는 수리하지 않도록 정한다.","c":"중","v":1},"법무사2024_30-01-3":{"w":"본인서명사실확인서 등기사무처리지침은 확인서상 주소가 주민등록표의 주소이동 내역에 없더라도 성명·주민등록번호로 같은 사람임이 인정되면 각하하지 않도록 정한다.","c":"중","v":1},"법무사2024_30-01-4":{"w":"본인서명사실확인서 등기사무처리지침은 자격자대리인이 대리하면 「위임받은 사람」란에 자격명과 성명이 있으면 주소는 없어도 된다고 정한다.","c":"중","v":1},"법무사2024_30-01-5":{"w":"본인서명사실확인서 등기사무처리지침은 확인서의 위임받은 사람과 위임장의 수임인이 같아야 하고 확인서 「용도」란과 위임장의 위임취지가 맞아야 한다고 정한다.","c":"중","v":1},"법무사2024_30-03-3":{"w":"미성년자 2인의 공유물분할은 민법 제921조 제2항의 이해상반행위여서 한쪽에 특별대리인을 선임해야 한다. 나머지 한 명은 친권자가 대리하므로 특별대리인은 1인만 있으면 된다(등기예규).","c":"중","v":1},"법무사2024_30-13-1":{"w":"특정채권(소유권이전등기청구권)을 보전하기 위한 채권자대위권은 채무자의 무자력을 요건으로 하지 않는다는 것이 판례다. 대위등기신청에서도 마찬가지다.","c":"중","v":1},"법무사2024_30-13-2":{"w":"주택법 제61조 제3항의 금지사항 부기등기는 입주예정자를 보호하려는 것이므로 입주예정자가 없다는 것이 증명되면 말소할 수 있다. 가압류채권자는 소유자를 대위해 말소를 신청할 수 있다는 것이 등기선례다.","c":"중","v":1},"법무사2024_30-13-4":{"w":"보존등기 말소는 등기명의인이 단독으로 신청하는 등기다(부동산등기법 제23조 제2항). 그래서 진정한 소유자 甲은 판결을 대위원인 증명정보로 하여 乙을 대위해 乙 명의 보존등기 말소를 신청한다는 것이 등기예규다.","c":"중","v":1},"법무사2024_30-13-5":{"w":"부동산등기규칙 제53조 제1항: 등기완료통지는 신청인과 대위신청의 피대위자에게 한다. 같은 규칙 제109조 제2항 제4호에 따라 대위신청에서는 등기필정보를 작성·통지하지 않는다.","c":"상","v":1},"법무사2024_30-14-1":{"w":"부동산등기규칙 제47조 제2항: 같은 등기소에 동시에 여러 건을 신청할 때 같은 첨부정보는 먼저 접수되는 신청에만 내고 다른 신청에는 그 뜻을 신청정보로 적어 갈음할 수 있다.","c":"상","v":1},"법무사2024_30-14-3":{"w":"甲과 乙의 지분은 각각 별개의 권리여서 이를 丙·丁에게 넘기는 것은 등기의무자가 다른 여러 개의 이전이다. 부동산등기법 제25조 본문에 따라 1개의 신청서로 함께 신청할 수 없다는 것이 등기선례다.","c":"중","v":1},"법무사2024_30-14-4":{"w":"부동산등기법 제82조 제1항: 신탁등기의 신청은 해당 부동산에 관한 권리의 설정·보존·이전·변경등기의 신청과 동시에 해야 한다. 수익자나 위탁자의 대위신청은 예외다(제2항).","c":"상","v":1},"법무사2024_30-14-5":{"w":"부동산등기규칙 제47조 제1항 제1호는 같은 채권을 담보하려고 소유자가 다른 여러 부동산에 저당권을 설정하면 일괄신청을 허용한다. 창설적 공동근저당도 이에 해당한다.","c":"상","v":1},"법무사2024_30-16-1":{"w":"부동산등기법 제49조 제1항 제2호: 주민등록번호가 없는 재외국민의 등록번호는 대법원 소재지 관할 등기소의 등기관이 부여한다. 「관할 외 등기소에서의 재외국민의 부동산등기용등록번호 부여신청 등」 등기예규는 관할 외 등기소가 신청서를 심사한 뒤 관할 등기소에 모사전송하게 한다.","c":"상","v":1},"법무사2024_30-16-2":{"w":"관할 외 등기소 재외국민 등록번호 부여신청에 관한 등기예규는 이미 등록번호를 받은 사람이 다시 부여신청을 하면 등록번호증명서 발급신청으로 보아 처리할 수 있게 한다.","c":"상","v":1},"법무사2024_30-16-3":{"w":"재외국민 부동산등기용등록번호 부여에 관한 등기예규는 재외국민등록번호부와 재외국민부동산등기용등록번호카드를 영구 보존하도록 정한다.","c":"중","v":1},"법무사2024_30-16-5":{"w":"재외국민 부동산등기용등록번호 부여에 관한 등기예규는 등기관이 등록번호부의 오류를 정정하면 그 재외국민과 행정안전부장관·국세청장에게 정정 사실을 통지하게 한다.","c":"중","v":1},"법무사2024_30-19-1":{"w":"전자신청은 신청정보가 전산정보처리조직에 저장되면 자동으로 접수된다(부동산등기법 제6조 제1항). 그래서 접수담당자가 따로 접수절차를 진행하지 않는다(전자신청에 관한 등기예규).","c":"중","v":1},"법무사2024_30-19-2":{"w":"부동산등기규칙 제65조 제2항: 같은 부동산에 관하여 동시에 여러 개의 등기신청이 있으면 같은 접수번호를 부여한다.","c":"상","v":1},"법무사2024_30-19-3":{"w":"부동산등기법 제6조 제1항과 부동산등기규칙 제3조 제1항은 접수시기를 부동산을 구별할 수 있는 정보가 전산정보처리조직에 저장된 때로 정한다. 신청서를 건넸어도 저장 전이면 접수된 것이 아니다.","c":"상","v":1},"법무사2024_30-19-5":{"w":"부동산등기규칙 제58조와 출입사무원에 관한 등기예규는 명의대여나 부당한 사건유치 등 비위가 있거나 업무에 적정하지 않은 행위를 한 경우 지방법원장이 출입사무원 허가를 취소할 수 있게 한다.","c":"중","v":1},"법무사2024_30-20-1":{"w":"관공서의 촉탁등기에 관한 등기예규에서 촉탁할 수 있는 관공서는 원칙적으로 국가와 지방자치단체이며 공사 등은 법령에 촉탁 특별규정이 있을 때만 촉탁할 수 있다.","c":"중","v":1},"법무사2024_30-20-2":{"w":"관공서의 촉탁등기에 관한 등기예규는 촉탁에 부동산등기법 제29조 제11호(대장 불일치)를 적용하지 않는다. 그래서 등기기록과 대장의 표시가 맞지 않아도 수리한다.","c":"중","v":1},"법무사2024_30-20-4":{"w":"매각이나 공매처분으로 관공서가 소유권이전등기를 촉탁하면 등기의무자 주소증명정보를 낼 필요가 없다(관공서의 촉탁등기에 관한 등기예규). 등기의무자의 협력 없이 하는 강제적 이전이기 때문이다.","c":"중","v":1},"법무사2024_30-20-5":{"w":"인감증명은 본인 의사를 확인하려는 것이다. 수용이나 환지처분으로 귀속된 도로의 이전등기를 관공서가 촉탁할 때는 등기의무자의 의사가 문제되지 않아 인감증명이 필요 없다는 것이 등기예규다.","c":"중","v":1},"법무사2024_30-21-2":{"w":"2011년 개정법 시행 뒤의 등기에는 등기필정보만 작성하고 등기필증은 발급하지 않는다(부동산등기법 제50조). 하나의 등기에 둘을 함께 주는 경우는 없다.","c":"중","v":1},"법무사2024_30-21-3":{"w":"등기필정보 일련번호와 함께 주는 50개 비밀번호는 한 번 쓰면 다시 쓸 수 없고 50개를 모두 쓴 뒤에만 재사용할 수 있다(등기필정보의 작성 및 통지에 관한 등기예규).","c":"중","v":1},"법무사2024_30-21-4":{"w":"부동산등기법 제50조 제1항 제1호: 등기권리자가 등기필정보의 통지를 원하지 않으면 작성·통지하지 않는다. 이 경우 신청할 때 그 뜻을 신청정보로 내야 한다(부동산등기규칙 제109조 제1항).","c":"상","v":1},"법무사2024_30-21-5":{"w":"등기필정보는 새로운 권리자가 기록될 때 작성한다(부동산등기법 제50조 제1항). 채권최고액 증액이나 전세금·기간 변경은 권리자가 바뀌지 않아 작성하지 않으므로 말소할 때에는 설정 당시의 등기필정보를 낸다(등기필정보에 관한 등기예규).","c":"중","v":1},"법무사2025_31-05-1":{"w":"판결에 의한 등기신청에 관한 등기예규는 등기원인이 무효·부존재이거나 취소·해제로 소멸했음을 이유로 말소를 명한 판결이면 등기원인을 「확정판결」, 연월일을 판결선고일로 적게 한다. 판결 주문에 따로 원인이 없기 때문이다.","c":"중","v":1},"법무사2025_31-05-2":{"w":"부동산등기법 제50조 제2항: 공동신청과 승소한 등기의무자의 단독신청에는 등기의무자의 등기필정보를 낸다. 승소한 등기권리자의 단독신청은 이 조항에 없어 등기필정보를 내지 않는다.","c":"상","v":1},"법무사2025_31-05-3":{"w":"판결에 반대급부와의 상환 조건이 붙어 있으면 집행문이 필요하다(민사집행법 제263조 제2항). 등기절차 이행과 반대급부 이행이 독립 조항으로 되어 있으면 조건이 아니므로 집행문 없이 신청한다(판결에 의한 등기신청에 관한 등기예규).","c":"중","v":1},"법무사2025_31-05-4":{"w":"변론종결 뒤 소유권이전등기를 받은 자는 변론종결 후 승계인으로 기판력이 미친다(민사소송법 제218조 제1항). 원고는 그에 대한 승계집행문을 받아 그 명의 등기까지 말소를 신청할 수 있다(판결에 의한 등기신청에 관한 등기예규).","c":"중","v":1},"법무사2025_31-06-1":{"w":"관공서의 촉탁은 공동신청이 아니어서 등기필정보 제공 규정(부동산등기법 제50조 제2항)이 적용되지 않는다. 관공서의 촉탁등기에 관한 등기예규는 관공서가 법무사에게 위임해 신청하는 경우에도 등기필정보를 내지 않아도 된다고 정한다.","c":"중","v":1},"법무사2025_31-06-3":{"w":"부동산등기법 제51조 단서는 신청서나 위임장 중 등기의무자 작성 부분에 공증을 받으면 등기필정보 제공을 갈음하게 한다. 이 공증은 그 기명날인 등이 등기의무자 본인의 것임을 공증하는 것이다(등기필정보가 없는 경우에 관한 등기예규).","c":"상","v":1},"법무사2025_31-06-4":{"w":"「재외국민 및 외국인의 부동산등기신청절차에 관한 예규」(등기예규 제1778호)는 처분위임장으로 신청하면서 등기필정보가 없으면 처분위임장에 그 뜻도 적어 공증을 받게 한다. 부동산등기법 제51조 단서의 공증 방식을 쓰는 것이다.","c":"중","v":1},"법무사2025_31-06-5":{"w":"공유물분할로 단독소유가 된 부분에는 종전 자기 지분과 분할로 넘겨받은 지분이 섞여 있다. 그래서 다시 이전할 때 분할등기의 등기필정보와 공유자로 등기할 때 받은 등기필정보를 함께 낸다(등기필정보에 관한 등기예규).","c":"중","v":1},"법무사2025_31-10-1":{"w":"유증 목적물 일부를 생전에 처분하면 그 부분만 유언이 철회된 것으로 본다(민법 제1109조). 나머지 지분에는 유언이 유효하므로 원래 유언공정증서를 등기원인증명정보로 낼 수 있다는 것이 등기선례다.","c":"중","v":1},"법무사2025_31-10-3":{"w":"합의해제로 인한 말소등기는 매도인이 농지를 새로 취득하는 것이 아니라 원래 상태로 돌아가는 것이다. 그래서 농지취득자격증명이 필요 없다(농지취득자격증명에 관한 등기예규).","c":"중","v":1},"법무사2025_31-10-4":{"w":"신탁원부의 내용은 등기된 것으로 보아 제3자에게도 효력이 있다(부동산등기법 제81조 제3항). 중도해지에 우선수익자 동의를 요한다는 약정이 기록되어 있으면 그 동의 증명정보와 인감증명(부동산등기규칙 제60조 제1항 제7호)을 낸다(등기선례).","c":"중","v":1},"법무사2025_31-10-5":{"w":"가등기된 소유권이전등기청구권도 양도할 수 있고 그 이전은 가등기에 부기한다. 매매로 인한 이전등기청구권의 양도는 매도인의 승낙이 있어야 매도인에게 효력이 있으므로 승낙 증명정보와 인감증명을 낸다(판례·등기선례).","c":"중","v":1},"법무사2025_31-15-2":{"w":"등기의무자는 등기가 실행되면 등기기록 형식상 권리를 잃거나 불이익을 받는 자다. 지배인이 위임해도 권리를 잃는 것은 법인이므로 자필서명정보의 등기의무자란에는 법인을 적는다(자필서명정보 제공에 관한 등기예규).","c":"중","v":1},"법무사2025_31-15-3":{"w":"자필서명정보 제공에 관한 등기예규는 구분건물과 대지권이 함께 신청 대상이면 자필서명정보에 대지권이 포함된다는 취지는 적어야 한다고 정한다. 대지권의 구체적 표시까지는 필요 없다.","c":"중","v":1},"법무사2025_31-15-4":{"w":"자필서명정보 제공에 관한 등기예규는 관공서가 등기의무자나 등기권리자인 경우에도 자격자대리인의 자필서명정보 제공을 면제하지 않는다.","c":"중","v":1},"법무사2025_31-15-5":{"w":"자필서명정보는 자격자대리인이 위임인이 등기의무자 본인인지 확인한 결과를 담는다(부동산등기규칙 제46조 제1항 제8호). 자격자대리인 자신이 등기의무자이면 확인할 대상이 없어 따로 낼 필요가 없다(등기예규).","c":"중","v":1},"법무사2025_31-17-2":{"w":"채무자가 대위소송이 제기된 것을 알았으면 판결의 효력이 채무자에게도 미친다는 것이 판례다. 그래서 채무자나 다른 채권자도 그 승소판결로 단독신청할 수 있다(판결에 의한 등기신청에 관한 등기예규).","c":"중","v":1},"법무사2025_31-17-3":{"w":"대위등기는 채무자 명의로 권리를 보전하는 것이 목적이어서 채무자로부터 채권자 자신에게로의 등기를 동시에 신청하지 않아도 수리한다(채권자대위에 의한 등기에 관한 등기예규).","c":"중","v":1},"법무사2025_31-17-4":{"w":"상속등기가 안 된 부동산은 피상속인 명의여서 상속인에 대한 가압류를 기입할 수 없다(부동산등기법 제29조 제7호). 그래서 가압류채권자가 먼저 상속인을 대위해 상속등기를 한 뒤 기입등기를 촉탁한다(등기예규).","c":"중","v":1},"법무사2025_31-17-5":{"w":"가처분채권자가 본안에서 승소해 말소등기를 신청하면 그 가처분등기는 목적을 다해 등기관이 직권으로 말소한다(부동산등기법 제94조). 대위소송 주문에 대위 사실이 없더라도 가처분 피보전권리를 실현한 것이면 같다는 것이 등기선례다.","c":"중","v":1},"법무사2025_31-23-1":{"w":"미성년자 2인의 공유물분할은 서로 이해가 상반되므로 민법 제921조 제2항에 따라 한쪽에 특별대리인을 선임한다. 다른 한 명은 친권자가 대리하므로 특별대리인은 1인이면 된다(등기예규).","c":"중","v":1},"법무사2025_31-23-2":{"w":"친권자만을 채무자로 하여 미성년자 지분까지 담보신탁하면 친권자의 채무를 위해 자의 재산을 내놓는 것이어서 민법 제921조의 이해상반행위다. 미성년자를 위한 특별대리인을 선임해야 한다(등기선례).","c":"중","v":1},"법무사2025_31-23-3":{"w":"친권자와 자를 공동채무자로 하거나 자만 채무자로 한 저당권 설정은 친권자에게 이익이고 자에게 불이익인 구조가 아니어서 이해상반행위가 아니라는 것이 등기예규다. 특별대리인을 선임하지 않는다.","c":"중","v":1},"법무사2025_31-23-4":{"w":"민법 제949조의3은 후견인과 피후견인의 이해상반행위에 제921조를 준용하되, 후견감독인이 있으면 특별대리인 대신 후견감독인이 피후견인을 대리하게 한다(제940조의6 제3항).","c":"중","v":1},"법무사2026_32-04-1":{"w":"신탁법 제22조 제1항은 신탁 전의 원인으로 생긴 권리나 신탁사무 처리상 생긴 권리가 아니면 신탁재산에 강제집행이나 체납처분을 하지 못하게 한다. 위탁자에 대한 부담금 채권으로는 수탁자 명의 신탁부동산을 압류할 수 없다(등기선례).","c":"중","v":1},"법무사2026_32-04-2":{"w":"촉탁할 수 있는 관공서는 국가·지방자치단체이며 공사 등은 법률에 촉탁 특별규정이 있어야 한다(관공서의 촉탁등기에 관한 등기예규). 지방공기업법에는 지방공사의 등기촉탁 규정이 없어 촉탁할 수 없다.","c":"중","v":1},"법무사2026_32-04-3":{"w":"공유토지분할에 관한 특례법에 따른 분할등기는 지적소관청의 촉탁으로만 한다. 이 법은 당사자 신청 절차를 두지 않으므로 지적소관청이 촉탁하지 않아도 당사자가 직접 신청할 수 없다(등기선례).","c":"중","v":1},"법무사2026_32-04-5":{"w":"관공서가 등기의무자로서 촉탁하거나 권리를 취득해 등기권리자로서 촉탁하면 등기의무자의 등기필정보를 낼 필요가 없다(관공서의 촉탁등기에 관한 등기예규). 촉탁은 공동신청이 아니기 때문이다.","c":"중","v":1},"법무사2026_32-11-1":{"w":"부동산등기규칙 제130조 제3항: 임대인 동의가 있다는 뜻의 등기가 없을 때 임차권 이전이나 전대 등기를 신청하면 임대인의 동의 증명정보를 낸다(민법 제629조).","c":"상","v":1},"법무사2026_32-11-3":{"w":"매매로 인한 소유권이전등기청구권은 매도인의 동의나 승낙이 있어야 양도의 효력을 매도인에게 주장할 수 있다는 것이 판례다. 승낙이 없었다면 양수인 앞 가등기 이전 부기등기와 그에 기한 본등기는 원인무효다.","c":"중","v":1},"법무사2026_32-11-4":{"w":"농지전용협의를 마친 농지는 농지법 제8조 제1항 제2호 등에 따라 농지취득자격증명 없이 취득할 수 있다. 이를 취득한 사업시행자가 신탁하는 경우에도 전용협의 완료 증명서면으로 충분하다(등기선례).","c":"중","v":1},"법무사2026_32-11-5":{"w":"신탁 종료에 따른 신탁재산 귀속이 대가를 받는 것이면 부동산 거래신고 등에 관한 법률 제11조의 유상 이전 계약에 해당한다. 위탁자 아닌 수익자나 제3자에게 귀속시킬 때 토지거래계약허가증을 낸다(등기선례).","c":"중","v":1},"법무사2026_32-12-1":{"w":"부동산등기법 제41조 제3항: 구분건물의 대지권에 변경이나 소멸이 있으면 구분건물 소유권 등기명의인은 같은 1동의 다른 구분건물 명의인을 대위해 그 등기를 신청할 수 있다.","c":"상","v":1},"법무사2026_32-12-2":{"w":"부동산등기법 제46조 제1항·제2항: 구분건물 일부만 보존등기를 신청하면 나머지 구분건물 표시등기를 동시에 신청해야 하며 이때 다른 구분건물 소유자를 대위할 수 있다.","c":"상","v":1},"법무사2026_32-12-3":{"w":"부동산등기법 제82조 제2항: 수익자나 위탁자는 수탁자를 대위해 신탁등기를 신청할 수 있다. 이때는 권리 등기와 동시에 신청해야 한다는 제1항이 적용되지 않는다.","c":"상","v":1},"법무사2026_32-12-5":{"w":"부동산등기법 제99조 제2항: 수용으로 인한 이전등기를 신청하는 등기권리자는 등기명의인이나 상속인 등을 갈음해 부동산 표시·명의인 표시의 변경·경정이나 상속 등 포괄승계로 인한 이전등기를 신청할 수 있다.","c":"상","v":1},"법무사2026_32-18-1":{"w":"유언집행자를 지정하지 않으면 상속인이 유언집행자가 된다(민법 제1095조). 유언집행자가 여럿이면 임무 집행은 과반수로 결정하므로(제1102조) 상속인 과반수가 유증 이전등기를 신청한다(유증 등기에 관한 등기예규).","c":"중","v":1},"법무사2026_32-18-2":{"w":"토지개발사업 완료에 따른 등기에서 지적공부 확정시행 공고 증명정보는 사업 완료와 지적 확정을 증명하는 것이다. 공고상 사업시행자가 토지소유자가 아니어도 수리한다는 것이 등기예규·선례다.","c":"중","v":1},"법무사2026_32-18-3":{"w":"부동산등기 특별조치법 제3조는 계약을 원인으로 소유권이전등기를 신청할 때 검인계약서를 내게 한다. 이전등기를 생략하고 증여자가 규약상 공용부분 취지 등기를 하더라도 실질이 증여계약에 의한 이전이어서 검인받은 계약서 원본을 낸다(등기선례).","c":"중","v":1},"법무사2026_32-18-4":{"w":"실종선고취소심판이 가족관계등록부에 정리되었으면 가족관계등록사항별증명서로 그 사실이 증명된다. 그래서 실종선고취소에 따른 등기에 심판 정본을 따로 붙일 필요가 없다는 것이 등기선례다.","c":"중","v":1},"법무사2026_32-28-5":{"w":"「재외국민 및 외국인의 부동산등기신청절차에 관한 예규」(등기예규 제1778호) 제8조의2: 재외국민이나 외국인이 등기의무자로서 유상계약(부담부증여 포함)으로 소유권이전등기를 신청하면 소득세법 제108조에 따른 부동산양도신고확인서를 낸다.","c":"상","v":1},"법무사2016_22-13-1":{"w":"유언집행자가 여럿이면 임무 집행은 과반수로 정한다(민법 제1102조). 그래서 과반수 유언집행자가 동의하면 수증자 명의 이전등기를 신청할 수 있다(유증 등기에 관한 등기예규).","c":"중","v":1},"법무사2016_22-13-3":{"w":"유증 등기는 수증자와 유언집행자(또는 상속인)가 공동으로 신청하는 권리에 관한 등기여서 부동산등기법 제50조 제2항에 따라 유증자의 등기필정보(등기필증)를 낸다(유증 등기에 관한 등기예규).","c":"중","v":1},"법무사2016_22-13-4":{"w":"유언은 유언자가 사망해야 효력이 생기므로(민법 제1073조) 생존 중에는 수증자에게 보전할 청구권이 없다. 그래서 유증을 원인으로 한 가등기는 사망 뒤에만 수리한다(유증 등기에 관한 등기예규).","c":"중","v":1},"법무사2016_22-13-5":{"w":"포괄적 수증자는 상속인과 같은 권리의무가 있지만(민법 제1078조) 수증자가 여럿이면 각자 자기 지분만 따로 이전등기를 신청할 수 있다는 것이 유증 등기에 관한 등기예규다.","c":"중","v":1},"법무사2016_22-19-2":{"w":"부속건물은 주된 건물과 함께 1개의 건물로 등기하는 것이 원칙이다. 독립건물로 보존등기를 하려면 주된 건물과 부속건물의 건축물대장이 따로 작성되어 있어야 한다(건물 등기에 관한 등기예규).","c":"중","v":1},"법무사2016_22-19-3":{"w":"건물은 국가가 소유권을 다툴 지위에 있지 않고 건축허가명의인도 대장 소유자가 아니다. 그래서 대장상 소유자를 알 수 없더라도 이들을 상대로 한 확인판결은 부동산등기법 제65조 제2호의 소유권 증명 판결이 아니라는 것이 판례·등기예규다.","c":"하","v":1},"법무사2016_22-19-4":{"w":"판례는 시장·군수·구청장을 상대로 한 소유권확인판결로 건물 보존등기를 하려면 그 건물에 대한 건축물대장이 작성되어 있어야 한다고 본다. 대장이 없으면 그 지방자치단체장이 소유권을 다툴 지위에 있지 않기 때문이다.","c":"중","v":1},"법무사2016_22-19-5":{"w":"토지에 설정된 지상권은 토지에 관한 권리여서 건물 보존등기와 이해가 충돌하지 않는다. 그래서 지상권을 말소하거나 지상권자의 승낙을 받지 않고도 건물 보존등기를 할 수 있다는 것이 등기선례다.","c":"중","v":1},"법무사2016_22-21-1":{"w":"진정명의회복을 원인으로 한 소유권이전등기에 관한 등기예규는 이미 자기 명의로 소유권 등기가 있었거나 법률 규정으로 소유권을 취득한 자가 현재 명의인을 상대로 그 판결을 받아 신청하면 수리하게 한다. 판례도 말소등기 대신 이 방법을 허용한다.","c":"중","v":1},"법무사2016_22-21-3":{"w":"진정명의회복은 원래 소유자에게 소유권을 되돌리는 것이지 새 거래가 아니므로 토지거래계약허가 대상이 아니다(진정명의회복 등기에 관한 등기예규).","c":"중","v":1},"법무사2016_22-21-4":{"w":"진정명의회복은 진정한 소유자에게 권리를 되돌리는 것이어서 농지를 새로 취득하는 것이 아니다. 그래서 농지취득자격증명을 낼 필요가 없다(진정명의회복 등기에 관한 등기예규).","c":"중","v":1},"법무사2016_22-21-5":{"w":"진정명의회복 등기에 관한 등기예규는 종전 소유권 등기명의인이나 지적공부상 소유자로서 보존등기를 신청할 수 있는 자가 현재 명의인과 공동으로 진정명의회복 원인 이전등기를 신청하면 수리하게 한다.","c":"중","v":1},"법무사2017_23-02-1":{"w":"부속건물은 주된 건물의 대장에 함께 등재해 1개 건물로 보존등기하는 것이 원칙이지만 대장을 따로 만들면 독립건물로 보존등기할 수도 있다(건물 등기에 관한 등기예규).","c":"중","v":1},"법무사2017_23-02-2":{"w":"「등기할 수 있는 물건 여부의 판단에 관한 업무처리지침」(등기예규)은 대장 등으로 건물 요건을 알 수 없으면 사진이나 도면을 소명자료로 받아 정착성·외기분단성·용도성을 종합 판단하게 한다.","c":"하","v":1},"법무사2017_23-02-3":{"w":"「축사의 부동산등기에 관한 특례법」 제3조는 둘레에 벽이 없는 개방형 축사도 토지 정착, 지붕과 견고한 구조, 대장 등록, 연면적 100제곱미터 초과 등 요건을 갖추면 건물로 보아 보존등기를 할 수 있게 한다.","c":"중","v":1},"법무사2017_23-02-4":{"w":"관리사무소·노인정처럼 독립 건물 요건을 갖춘 공용부분은 별개 건물로 보존등기할 수 있다. 그 뒤 규약상 공용부분이라는 뜻을 등기한다(부동산등기법 제47조, 집합건물법 제3조 제4항).","c":"중","v":1},"법무사2017_23-11-1":{"w":"거래가액 등기는 부동산 거래신고 대상 계약을 원인으로 한 이전등기에 한다(부동산등기법 제68조). 거래가액 등기에 관한 등기예규는 거래신고제 시행(2006. 1. 1.) 전에 작성된 매매계약서로 신청하면 거래가액을 등기하지 않는다고 정한다.","c":"중","v":1},"법무사2017_23-11-3":{"w":"부동산등기법 제68조는 거래가액을 「소유권이전등기」에 기록하게 한다. 소유권이전청구권가등기는 소유권이전등기가 아니어서 거래가액을 등기하지 않는다(거래가액 등기에 관한 등기예규). 본등기할 때 기록한다.","c":"중","v":1},"법무사2017_23-11-4":{"w":"등기원인증서와 거래계약신고필증의 기재가 달라 같은 거래로 볼 수 없으면 신청정보와 첨부정보가 맞지 않는 것이어서 수리하지 않는다(부동산등기법 제29조 제9호, 거래가액 등기에 관한 등기예규).","c":"중","v":1},"법무사2017_23-11-5":{"w":"부동산등기규칙 제124조 제2항: 거래부동산이 2개 이상이거나 1개라도 여러 매도인과 여러 매수인 사이의 매매이면 매매목록을 첨부정보로 낸다.","c":"상","v":1},"법무사2017_23-12-1":{"w":"조합 사업으로 생긴 지방세는 조합원 전원의 채무이고 조합재산은 조합원의 합유다. 그래서 그 지방세에 기해 조합재산을 압류할 수 있다는 것이 등기선례다.","c":"중","v":1},"법무사2017_23-12-2":{"w":"합유자가 사망하면 특약이 없는 한 그 지분은 상속되지 않고 잔존 합유자에게 귀속된다(판례, 민법 제719조 참조). 2인 중 1인이 사망하면 잔존 합유자는 사망 증명정보를 붙여 자기 단독소유로 하는 합유명의인 변경등기를 신청한다(합유 등기에 관한 등기예규).","c":"중","v":1},"법무사2017_23-12-3":{"w":"합유물 처분이나 변경은 합유자 전원의 동의로 한다(민법 제272조). 전원이 합의하면 합유를 공유로 바꾸는 소유권변경등기를 할 수 있다(합유 등기에 관한 등기예규).","c":"중","v":1},"법무사2017_23-12-4":{"w":"합유자들과 법인 아닌 사단은 서로 다른 권리주체다. 그래서 명의를 사단으로 바꾸는 것은 명의인 표시 변경이 아니라 권리 이전이어서 소유권이전등기 방식으로 한다(등기선례).","c":"중","v":1},"법무사2017_23-18-1":{"w":"국토계획법상 주거지역 안의 농지는 농지법 제8조 제1항 단서 등에 따라 농지취득자격증명 없이 취득할 수 있다. 농지 소유 제한도 받지 않으므로 종중 명의로 이전등기할 수 있다는 것이 등기선례다.","c":"중","v":1},"법무사2017_23-18-3":{"w":"사인증여에는 유증 규정이 준용되므로(민법 제562조) 유언집행자가 등기의무자로서 수증자와 공동신청한다. 유언집행자가 여럿이면 과반수로 신청한다(민법 제1102조, 등기선례).","c":"중","v":1},"법무사2017_23-18-4":{"w":"부동산 거래신고 등에 관한 법률 제11조의 토지거래허가는 대가를 받고 소유권 등을 이전하는 계약에 필요하다. 부담 없는 증여는 대가가 없으므로 허가증을 붙이지 않는다(토지거래허가에 관한 등기예규).","c":"중","v":1},"법무사2017_23-18-5":{"w":"현물출자에 따른 소유권이전등기는 현물출자계약서가 등기원인증서이고 원인일자는 그 계약 성립일이라는 것이 등기선례다.","c":"중","v":1},"법무사2017_23-19-1":{"w":"지분 일부에 저당권 등이 있는 상태에서 지분 일부를 이전하면 이전 지분이 부담 있는 부분인지 아닌지에 따라 권리관계가 달라진다. 그래서 그 여부를 신청정보로 낸다(부동산등기규칙 제123조, 등기예규).","c":"중","v":1},"법무사2017_23-19-2":{"w":"지분 일부 이전등기의 기록 방법에 관한 등기예규는 「甲지분 ○분의○ 중 일부(○분의○) 이전」으로 적되 이전 지분을 부동산 전체에 대한 지분으로 괄호 안에 쓰게 한다.","c":"중","v":1},"법무사2017_23-19-3":{"w":"여러 공유자가 여러 사람에게 지분을 이전하면 등기의무자별로 각각 별개의 등기원인이 되므로 부동산등기법 제25조 본문에 따라 1개의 신청정보로 할 수 없다. 함께 신청하면 각하한다(등기선례).","c":"중","v":1},"법무사2017_23-19-5":{"w":"특정 부분을 매수하고 지분등기를 한 것은 구분소유적 공유(상호명의신탁)다. 판례에 따라 각자 상호명의신탁 해지를 원인으로 자기 특정 부분에 대한 지분이전등기를 할 수 있다.","c":"중","v":1},"법무사2018_24-13-1":{"w":"「축사의 부동산등기에 관한 특례법」에 따른 보존등기를 하면 등기관은 표제부의 등기원인 및 기타사항란에 그 특례법에 따른 등기라는 뜻을 기록한다(같은 법과 축사 등기에 관한 등기예규).","c":"중","v":1},"법무사2018_24-13-2":{"w":"축사 특례법 제3조의 연면적 요건(100제곱미터 초과)은 대장에 함께 등록된 퇴비사·착유사 등 부속건물을 포함해 판단한다. 축사와 부속건물 연면적이 200제곱미터를 넘으면 요건을 갖춘다(축사 등기에 관한 등기예규).","c":"중","v":1},"법무사2018_24-13-4":{"w":"「축사의 부동산등기에 관한 특례법」 제2조: 개방형 축사는 소의 질병을 예방하고 통기성을 확보할 수 있도록 둘레에 벽을 갖추지 않고 소를 사육하는 용도로 쓰는 건축물이다.","c":"중","v":1},"법무사2018_24-13-5":{"w":"1부동산 1등기기록 원칙에 따라 건축물대장이 축사마다 따로 작성되었으면 대장별로 각각 보존등기를 신청한다(축사 등기에 관한 등기예규).","c":"중","v":1},"법무사2018_24-16-1":{"w":"공유물분할판결은 형성판결이어서 확정되면 등기 없이도 분할된 부분의 단독소유권을 취득한다(민법 제187조). 판결에 의한 물권변동이기 때문이다.","c":"상","v":1},"법무사2018_24-16-2":{"w":"판례는 공유물분할 소송에서 조정이 성립한 것은 공유자들의 협의에 의한 분할과 같아서 등기를 마쳐야 단독소유권을 취득한다고 본다(민법 제186조). 형성판결과 다르다.","c":"중","v":1},"법무사2018_24-16-4":{"w":"공유물분할소송에서 확정된 강제조정은 판결과 같은 효력이 있으므로 부동산등기법 제23조 제4항에 따라 원고·피고를 가리지 않고 등기권리자가 단독으로 공유물분할 원인 지분이전등기를 신청할 수 있다(등기예규).","c":"중","v":1},"법무사2018_24-16-5":{"w":"공유물분할은 종전 공유지분을 특정 부분으로 바꾸는 것이어서 농지를 새로 취득하는 행위로 보지 않는다. 취득 면적이 지분 비율과 달라도 농지취득자격증명이 필요 없다(농지취득자격증명에 관한 등기예규).","c":"중","v":1},"법무사2019_25-05-5":{"w":"수용재결로 사업시행자는 소유권을 원시취득한다. 사업계획이 바뀌어 불필요해졌어도 재결이 실효되지 않는 한 수용 효력은 그대로이고 환매 등 별도 절차를 거쳐야 하므로 말소등기를 신청할 수 없다(등기선례).","c":"중","v":1},"법무사2019_25-11-2":{"w":"합유자 개인의 채권자는 합유지분을 압류할 수 없지만 합유물 전체에 대한 집행권원이 있으면 합유물 전체를 경매할 수 있다. 그 경매개시결정 기입등기는 할 수 있다(합유 등기에 관한 등기예규).","c":"중","v":1},"법무사2019_25-11-3":{"w":"합유자 일부가 지분을 잔존 합유자에게 넘기고 탈퇴하면 탈퇴자와 잔존 합유자들이 공동신청해 잔존 합유자의 합유로 하는 합유명의인 변경등기를 한다(합유 등기에 관한 등기예규).","c":"중","v":1},"법무사2019_25-11-4":{"w":"공유를 합유로 바꾸는 것은 소유형태 변경이어서 합유로 하려는 공유자들이 공동신청해 합유로의 변경등기를 한다(합유 등기에 관한 등기예규).","c":"중","v":1},"법무사2019_25-11-5":{"w":"합유지분은 특약이 없으면 상속되지 않고 잔존 합유자에게 귀속된다(판례). 그래서 잔존 합유자가 사망 증명정보를 붙여 자기 단독소유로 하는 합유명의인 변경등기를 신청한다(합유 등기에 관한 등기예규).","c":"중","v":1},"법무사2019_25-27-2":{"w":"환매특약은 매매계약과 동시에 해야 하므로(민법 제590조 제1항) 그 등기도 매매로 인한 이전등기와 동시에 신청한다. 부동산등기법 제52조 제6호에 따라 매수인의 권리취득 등기에 부기한다.","c":"상","v":1},"법무사2019_25-27-3":{"w":"환매특약이 등기되면 제3자에게도 효력이 있다(민법 제592조). 그래서 환매 목적물이 양도되었으면 현재 소유명의인인 제3취득자를 등기의무자로 하여 환매로 인한 이전등기를 한다(환매등기에 관한 등기예규).","c":"중","v":1},"법무사2019_25-27-4":{"w":"환매권에 가압류·가처분이 되어 있으면 그 권리자는 환매특약등기 말소로 손해를 보는 등기상 이해관계인이다. 부동산등기법 제57조 제1항에 따라 그 승낙이나 이에 대항할 수 있는 재판이 있어야 말소할 수 있다.","c":"중","v":1},"법무사2019_25-27-5":{"w":"환매특약 등기 뒤 환매 전에 마쳐진 소유권 외 권리의 등기는 환매로 효력을 잃지만 직권말소 규정이 없다. 그래서 일반 원칙대로 공동신청으로 말소한다(환매등기에 관한 등기예규).","c":"중","v":1},"법무사2020_26-07-1":{"w":"공유자 1인은 보존행위로 공유자 전원을 위한 보존등기를 신청할 수 있다(민법 제265조 단서). 자기 지분만 보존등기하면 1부동산의 일부만 등기되는 결과가 되어 허용되지 않는다(등기예규).","c":"중","v":1},"법무사2020_26-07-2":{"w":"공유물분할은 같은 공유물의 공유자 사이에서 하는 것이다. A·B필지의 공유자가 아닌 丁이 참여하거나 다른 필지와 섞어서 나누면 공유물분할이 아니라 교환 등이어서 공유물분할을 원인으로 등기할 수 없다(등기선례).","c":"중","v":1},"법무사2020_26-07-4":{"w":"처분금지가처분은 가처분채권자에 대한 관계에서만 처분을 무효로 하는 상대적 효력만 있다. 그래서 가처분등기가 있어도 공유자 전원이 공동신청해 합유로 변경등기를 할 수 있다(등기선례).","c":"중","v":1},"법무사2020_26-07-5":{"w":"특약이 없으면 사망한 합유자의 지분은 잔존 합유자에게 귀속하고 상속되지 않는다는 것이 판례다. 그래서 상속인끼리 받은 상속지분 이전 판결로 합유지분을 이전등기할 수 없다(등기선례).","c":"중","v":1},"법무사2020_26-14-1":{"w":"환매특약등기에는 처분금지 효력이 없고 환매권을 제3자에게 대항할 수 있게 할 뿐이다(민법 제592조). 그래서 소유자는 환매특약 등기 뒤에도 전매하고 이전등기를 신청할 수 있다(등기선례).","c":"중","v":1},"법무사2020_26-14-2":{"w":"환매권 행사는 매도인이 다시 매수하는 것이어서 환매로 인한 이전등기는 매도인(환매권자)이 등기권리자, 매수인(또는 현재 소유자)이 등기의무자로 공동신청한다(환매등기에 관한 등기예규).","c":"중","v":1},"법무사2020_26-14-4":{"w":"환매권자가 다른 원인으로 소유권을 취득하면 환매권은 혼동으로 소멸한다(민법 제191조). 혼동에 의한 말소는 권리자와 의무자가 같아 환매권자가 단독으로 신청할 수 있다(등기선례).","c":"중","v":1},"법무사2020_26-14-5":{"w":"민법 제590조는 매도인이 매매계약과 동시에 환매할 권리를 보류하는 것이다. 환매권자는 매도인에 한정되므로 제3자를 환매권자로 하는 환매특약등기는 할 수 없다(등기선례).","c":"중","v":1},"법무사2020_26-23-1":{"w":"부동산등기 특별조치법 제3조의 검인은 계약을 원인으로 한 소유권이전등기를 신청할 때 필요하다. 가등기는 이전등기가 아니어서 검인이 없어도 된다(검인에 관한 등기예규). 본등기할 때 검인을 받는다.","c":"중","v":1},"법무사2020_26-23-2":{"w":"검인은 당사자의 계약서에 받는 것이다(부동산등기 특별조치법 제3조). 경매 매각은 계약서가 없는 법원의 처분이어서 검인이 필요 없다(검인에 관한 등기예규).","c":"중","v":1},"법무사2020_26-23-3":{"w":"부동산등기 특별조치법 시행규칙과 검인에 관한 등기예규는 계약 당사자 한쪽이 국가나 지방자치단체이면 검인을 받지 않아도 되게 한다.","c":"중","v":1},"법무사2020_26-23-5":{"w":"부동산 거래신고 등에 관한 법률 제20조는 토지거래계약허가증을 받으면 부동산등기 특별조치법 제3조의 검인을 받은 것으로 본다.","c":"중","v":1},"법무사2020_26-26-1":{"w":"진정명의회복 등기에 관한 등기예규는 종전 소유권 등기명의인이나 법률 규정으로 소유권을 취득한 자가 현재 명의인을 상대로 진정명의회복 원인 이전등기 판결을 받아 신청하면 수리하게 한다.","c":"중","v":1},"법무사2020_26-26-2":{"w":"진정명의회복 원인 이전등기도 소유권이전등기이므로 주택도시기금법 제8조와 시행령 제8조에 따라 국민주택채권을 매입한다(진정명의회복 등기에 관한 등기예규).","c":"중","v":1},"법무사2020_26-26-3":{"w":"진정명의회복 등기에 관한 등기예규는 종전 소유권 등기명의인이나 지적공부상 소유자로서 보존등기를 신청할 수 있는 자가 현재 명의인과 공동으로 신청하면 수리하게 한다.","c":"중","v":1},"법무사2020_26-26-5":{"w":"진정명의회복은 특정 일자의 법률행위로 생기는 것이 아니어서 등기원인 일자를 적지 않는다(진정명의회복 등기에 관한 등기예규).","c":"중","v":1},"법무사2021_27-05-2":{"w":"부동산소유권 이전등기 등에 관한 특별조치법은 대장에 소유자가 등록되지 않은 미등기 부동산의 사실상 소유자가 확인서로 대장에 복구등록하면 그 대장정보로 자기 명의 보존등기를 신청할 수 있게 한다(특조법 등기에 관한 등기예규).","c":"중","v":1},"법무사2021_27-05-3":{"w":"특조법은 확인서를 발급받은 사실상 양수인이 단독으로 소유권이전등기를 신청할 수 있게 한다. 확인서가 공동신청을 갈음한다.","c":"중","v":1},"법무사2021_27-05-4":{"w":"특조법에 따른 이전등기는 확인서로 단독신청하는 것이어서 등기의무자의 등기필정보·주소증명정보·인감증명이 필요 없다(특조법 등기에 관한 등기예규).","c":"중","v":1},"법무사2021_27-05-5":{"w":"특조법은 등기절차의 특례일 뿐 세금 면제 규정이 없다. 그래서 취득세나 등록면허세를 내고 국민주택채권을 매입해야 하며 기준시점은 등기신청 때다(특조법 등기에 관한 등기예규).","c":"중","v":1},"법무사2021_27-15-1":{"w":"사업인정 고시 전 협의취득은 사법상 매매여서 공동신청이 원칙이다. 공공용지 취득협의서를 등기원인증서로 하고 등기의무자의 인감증명을 낸다(토지보상법 관련 등기예규, 부동산등기규칙 제60조 제1항 제1호).","c":"중","v":1},"법무사2021_27-15-2":{"w":"미등기 토지는 대장상 최초 소유자가 먼저 보존등기를 해야(부동산등기법 제65조 제1호) 그로부터 이전등기를 받을 수 있다. 사업인정 전 협의취득은 승계취득이어서 등기를 순차로 한다(등기예규).","c":"중","v":1},"법무사2021_27-15-3":{"w":"사업인정 고시 후 협의가 성립하고 토지수용위원회의 확인을 받으면 재결로 보므로(토지보상법 제29조 제4항) 수용과 같이 사업시행자가 단독신청한다(부동산등기법 제99조). 수용 등기에는 등기의무자의 인감증명이 필요 없다(등기예규).","c":"중","v":1},"법무사2021_27-15-5":{"w":"수용 재결이 실효되면 사업시행자의 소유권취득도 효력을 잃는다. 토지수용 등기에 관한 등기예규는 그 말소를 공동신청으로 하게 한다. 말소하면 등기관은 수용 때 직권말소했던 등기를 직권으로 회복한다.","c":"중","v":1},"법무사2021_27-20-2":{"w":"철근콘크리트 기초로 토지에 정착하고 경량철골구조와 내구성 10년 이상 장기성 필름으로 지붕·벽면을 갖춘 비닐온실은 정착성·외기분단성·용도성을 갖추어 건물로 보존등기를 할 수 있다는 것이 등기선례다.","c":"중","v":1},"법무사2021_27-20-3":{"w":"부동산등기법 제66조 제1항: 미등기 부동산에 법원의 촉탁으로 소유권 처분제한 등기(가압류·가처분·경매개시결정)를 할 때 등기관은 직권으로 소유권보존등기를 한다.","c":"상","v":1},"법무사2021_27-20-4":{"w":"부동산등기법 제46조 제3항: 구분건물이 아닌 건물에 접속해 구분건물을 신축하면 그 보존등기를 신청할 때 기존 건물을 구분건물로 바꾸는 표시변경등기를 동시에 신청한다.","c":"상","v":1},"법무사2021_27-20-5":{"w":"부동산등기법 제46조 제1항·제2항: 구분건물 일부만 보존등기를 신청하면 나머지 구분건물의 표시등기를 동시에 신청해야 하며 다른 구분건물 소유자를 대위해 신청할 수 있다.","c":"상","v":1},"법무사2021_27-27-1":{"w":"합유자 일부가 탈퇴해 1인만 남으면 탈퇴자와 잔존 합유자가 공동신청해 잔존 합유자의 단독소유로 하는 합유명의인 변경등기를 한다(합유 등기에 관한 등기예규). 탈퇴자는 권리를 잃으므로 그 인감증명을 붙인다.","c":"중","v":1},"법무사2021_27-27-2":{"w":"협의분할은 공유자 전원이 참여해야 하지만 분할 방법은 자유이므로 지분비율과 다르게 나눌 수 있다(민법 제268조, 제269조). 그래서 자기 지분비율을 넘는 분할을 원인으로도 이전등기를 신청할 수 있다(등기선례).","c":"중","v":1},"법무사2021_27-27-4":{"w":"지분 일부에 가등기가 있으면 남은 지분을 이전할 때 그것이 가등기된 지분인지에 따라 본등기 시 효력이 달라진다. 그래서 신청할 때 이를 특정해야 한다(부동산등기규칙 제123조, 등기예규).","c":"중","v":1},"법무사2021_27-27-5":{"w":"단독소유를 여러 사람의 합유로 넘기는 것은 소유권 이전이므로 단독소유자(등기의무자)와 합유자들(등기권리자)이 공동신청한다(합유 등기에 관한 등기예규).","c":"중","v":1},"법무사2022_28-01-1":{"w":"상속재산 협의분할은 공동상속인 사이 이해상반행위다. 처가 상속을 포기하지 않았으면 자신이 재산을 받지 않더라도 공동상속인 지위에 있으므로 미성년자를 대리할 수 없고 특별대리인을 선임해야 한다(민법 제921조, 판례·등기예규).","c":"중","v":1},"법무사2022_28-01-2":{"w":"판결 이유에서 순차 상속과 협의분할로 甲이 소유자가 된 사실이 확정되었으므로 그 판결이 상속을 증명한다. 그래서 별도 상속증명서면이 필요 없다는 것이 진정명의회복 등기에 관한 등기선례다.","c":"중","v":1},"법무사2022_28-01-3":{"w":"판결 이유에 피상속인의 시효취득과 원고들의 청구권 공동상속 사실이 나와 있으면 공동상속인들은 그 청구권을 협의분할할 수 있다. 판결정본과 협의분할서(전원 인감증명)·상속증명서면으로 1인 단독 명의 이전등기를 신청할 수 있다(등기선례).","c":"중","v":1},"법무사2022_28-01-5":{"w":"가등기 뒤 가등기권자가 사망하면 등기원인 후의 포괄승계이므로 부동산등기법 제27조에 따라 상속인이 상속등기 없이 상속증명정보를 붙여 가등기의무자와 공동으로 본등기를 신청한다(가등기에 관한 등기예규).","c":"중","v":1},"법무사2023_29-20-1":{"w":"회사분할로 분할계획서에 따라 재산이 신설·승계회사에 포괄승계되므로 부동산등기법 제65조 제1호의 「최초 소유자의 포괄승계인」에 해당한다. 분할 후 회사는 승계를 증명해 바로 자기 명의로 보존등기를 신청할 수 있다(등기선례).","c":"중","v":1},"법무사2023_29-20-3":{"w":"건물은 국가가 소유권을 다툴 지위에 있지 않고 건축허가명의인도 대장 소유자가 아니어서 이들을 상대로 한 확인판결은 부동산등기법 제65조 제2호의 소유권 증명 판결에 해당하지 않는다는 것이 판례·등기예규다.","c":"중","v":1},"법무사2023_29-20-4":{"w":"토지 지상권은 건물 보존등기와 등기상 이해관계가 없다. 지상권자 아닌 제3자가 신축한 건물도 지상권 말소나 지상권자 승낙 없이 보존등기를 할 수 있다는 것이 등기선례다.","c":"중","v":1},"법무사2023_29-20-5":{"w":"부동산등기규칙 제121조 제1항: 소유권보존등기를 신청할 때는 법 제65조 각 호 중 어느 것에 따라 신청하는지를 적고 등기원인과 그 연월일은 신청정보로 내지 않는다.","c":"상","v":1},"법무사2024_30-04-1":{"w":"사업인정 전 공공용지 협의취득은 사법상 매매여서 일반 원칙(부동산등기법 제23조 제1항)대로 사업시행자와 등기의무자가 공동신청한다(토지보상법 관련 등기예규).","c":"중","v":1},"법무사2024_30-04-2":{"w":"부동산등기법 제99조 제3항은 국가나 지방자치단체가 등기권리자이면 수용 등기를 촉탁하게 한다. 등기예규는 관공서인 사업시행자가 등기의무자와 공동신청하더라도 수리할 수 있다고 본다.","c":"중","v":1},"법무사2024_30-04-3":{"w":"토지보상법 제45조에 따라 사업시행자는 수용 개시일에 소유권을 원시취득하고 다른 권리는 소멸한다. 부동산등기법 제99조 제4항에 따라 재결로 존속이 인정된 권리가 아니면 환매특약등기도 직권말소한다.","c":"중","v":1},"법무사2024_30-04-5":{"w":"관공서가 등기권리자로서 촉탁할 수 있는 경우에도 촉탁 대신 신청 방식을 택할 수 있다. 신청은 자격자대리인에게 위임할 수도 있다(관공서의 촉탁등기에 관한 등기예규).","c":"중","v":1},"법무사2024_30-05-1":{"w":"민법 제245조 제1항은 점유취득시효 완성자가 「등기함으로써」 소유권을 취득한다고 정해 제187조의 예외를 둔다. 그래서 현재 등기기록상 소유자를 등기의무자로 하여 공동신청한다(시효취득 등기에 관한 등기예규).","c":"중","v":1},"법무사2024_30-05-2":{"w":"시효취득 등기에 관한 등기예규는 등기원인을 「시효취득」, 원인일자를 점유개시일로 적게 한다. 취득시효로 인한 소유권취득은 점유를 시작한 때로 소급하기 때문이다(민법 제247조 제1항).","c":"중","v":1},"법무사2024_30-05-3":{"w":"취득시효는 법률 규정에 의한 취득이어서 농지 매매처럼 농지취득자격증명을 받는 대상이 아니라는 것이 농지취득자격증명에 관한 등기예규다.","c":"중","v":1},"법무사2024_30-05-5":{"w":"시효완성 뒤 등기 전에 종전 소유자가 설정한 저당권 등은 유효하며 시효취득자의 이전등기로 직권말소되지 않는다(판례). 그래서 일반 말소절차인 공동신청이나 판결에 의한 단독신청으로만 말소한다(등기예규).","c":"중","v":1},"법무사2024_30-09-1":{"w":"甲 지분에 설정된 근저당권은 분할 후에도 분할된 각 토지 위의 甲 지분 비율 범위에 그대로 남는다는 것이 판례다. 그래서 乙 단독소유 토지에도 전사되어 효력이 있고 통상의 말소절차로만 말소한다.","c":"중","v":1},"법무사2024_30-09-2":{"w":"변론종결 전에 지분을 넘겨받은 제3자는 변론종결 후 승계인이 아니어서 판결 효력이 미치지 않는다. 공유물분할은 공유자 전원이 당사자여야 하는 필수적 공동소송이어서 그 판결로는 분할등기를 할 수 없다(등기선례).","c":"중","v":1},"법무사2024_30-09-3":{"w":"공유물분할 등기는 먼저 지적 분할과 대장 정리를 거쳐 분필등기를 한 뒤 한다. 분필된 각 부동산별로 공유물분할 이전등기를 따로 신청할 수 있고 동시에 할 필요는 없다(등기선례).","c":"중","v":1},"법무사2024_30-09-4":{"w":"공유물분할로 받은 단독소유 부분에는 종전 자기 지분과 분할로 이전받은 지분이 함께 있다. 그래서 다시 처분할 때 분할등기의 등기필정보와 공유자로 등기할 때의 등기필정보를 함께 낸다(등기필정보에 관한 등기예규).","c":"중","v":1},"법무사2024_30-12-1":{"w":"판결로 특정된 토지 일부의 말소를 명받은 자는 분할 주문이 없어도 그 판결을 근거로 대위 분필등기를 거쳐 해당 부분 이전등기를 말소할 수 있다는 것이 판결에 의한 등기신청에 관한 등기예규다.","c":"중","v":1},"법무사2024_30-12-2":{"w":"유류분반환은 당사자 사이 합의로도 할 수 있고 등기관은 실체 판단을 하지 않는다. 그래서 유류분 초과 여부를 확인하는 정보를 반드시 내야 하는 것은 아니라는 것이 등기선례다.","c":"중","v":1},"법무사2024_30-12-3":{"w":"공유자 1인은 보존행위로 전원 명의 보존등기를 신청할 수 있다(민법 제265조 단서). 자기 지분만 보존등기하면 1부동산 일부만 등기되는 결과가 되어 허용되지 않는다(등기예규).","c":"중","v":1},"법무사2024_30-12-5":{"w":"법정상속등기 후 공동상속인 1인이 사망하면 그 지분은 다시 그의 상속인에게 상속되어 원래 상속등기와 권리관계가 달라진다. 그래서 원래 상속등기를 협의분할에 의한 경정등기로 바로잡을 수 없다는 것이 등기선례다.","c":"중","v":1},"법무사2024_30-28-1":{"w":"환매특약등기는 매매로 인한 소유권이전등기와 동시에 신청하되(민법 제590조) 이전등기와는 별개의 신청서로 한다(환매등기에 관한 등기예규). 등기목적과 원인이 달라 일괄신청 대상이 아니다.","c":"중","v":1},"법무사2024_30-28-2":{"w":"환매특약등기는 매도인이 등기권리자, 매수인이 등기의무자로 공동신청한다. 환매권은 매도인이 보류하는 것이어서(민법 제590조) 제3자를 환매권자로 등기할 수 없다(환매등기에 관한 등기예규).","c":"중","v":1},"법무사2024_30-28-3":{"w":"환매등기에 관한 등기예규: 환매로 인한 이전등기는 매도인이 등기권리자, 매수인이 등기의무자로 공동신청한다. 환매권이 양도되었으면 양수인이, 목적물이 양도되었으면 현재 소유명의인이 각각 등기권리자·등기의무자가 된다.","c":"중","v":1},"법무사2024_30-28-4":{"w":"환매로 인한 이전등기를 하면 환매특약등기를 말소해야 한다(부동산등기규칙 제114조 제1항). 환매권에 가압류·가처분·가등기 부기등기가 있어 그 말소가 안 되면 환매특약등기를 말소할 수 없으므로 이전등기도 할 수 없다(등기예규).","c":"중","v":1},"법무사2025_31-02-1":{"w":"협의에 의한 공유물분할은 분할 방법이 자유로워 일부 필지를 여러 공유자의 공유로 남기는 것도 가능하다. 이런 분할계약서로 공유물분할 원인 등기를 신청할 수 있다(등기선례).","c":"중","v":1},"법무사2025_31-02-2":{"w":"협의분할은 공유자 전원의 합의가 필요하지만 분할 비율은 자유이므로 지분비율을 넘는 분할도 가능하다. 그 분할을 원인으로 이전등기를 신청할 수 있다(등기선례).","c":"중","v":1},"법무사2025_31-02-3":{"w":"판결 확정 뒤 마쳐진 丙의 가압류는 변론종결 후 승계인에 준해 판결 효력을 받는다. 甲은 승계집행문을 받아 가압류등기 말소와 지분이전등기를 단독신청하되 두 등기를 동시에 신청한다(판결에 의한 등기신청에 관한 등기예규).","c":"중","v":1},"법무사2025_31-02-4":{"w":"공유물분할 등기는 지적 분할 후 대장에 따라 분필등기를 먼저 한다. 분할 원인 이전등기는 분필된 부동산별로 따로 신청할 수 있고 동시 신청이 필수가 아니다(등기선례).","c":"중","v":1},"법무사2025_31-13-1":{"w":"부동산등기법 제53조 단서: 환매특약등기의 기록사항 중 환매기간(제3호)은 등기원인에 정해져 있는 경우에만 기록한다. 약정이 없으면 신청정보로 낼 필요가 없다.","c":"상","v":1},"법무사2025_31-13-2":{"w":"환매특약등기는 부동산등기법 제52조 제6호에 따라 매수인의 권리취득 등기에 부기한다. 매매 이전등기와 동시에 신청하므로 같은 접수번호를 부여한다(부동산등기규칙 제65조 제2항, 환매등기에 관한 등기예규).","c":"중","v":1},"법무사2025_31-13-4":{"w":"환매특약등기는 제3자에게 환매권을 대항하게 할 뿐(민법 제592조) 처분을 막지 않는다. 그래서 소유자는 전매하고 이전등기를 할 수 있다(등기선례).","c":"중","v":1},"법무사2025_31-13-5":{"w":"민법 제590조의 환매는 매도한 목적물 자체를 되사는 권리다. 필지 전부를 팔면서 일부 지분만 환매권을 보류하는 약정은 민법상 환매특약이 아니어서 환매특약등기를 할 수 없다는 것이 등기선례다.","c":"중","v":1},"법무사2025_31-16-5":{"w":"거래가액 등기에 관한 등기예규는 매매예약 가등기에 의한 본등기를 할 때 매매계약서를 따로 내지 않더라도 거래신고필증에 따라 거래가액을 등기하게 한다. 본등기는 매매를 원인으로 한 소유권이전등기이기 때문이다(부동산등기법 제68조).","c":"중","v":1},"법무사2025_31-24-1":{"w":"합유자 2인 중 1인이 사망하면 특약이 없는 한 지분은 잔존 합유자에게 귀속되어 단독소유가 된다(판례). 사망 증명정보로 합유명의인 변경등기를 신청하며 잔존 합유자는 등기기록에 「소유자」로 기록된다(합유 등기에 관한 등기예규).","c":"중","v":1},"법무사2025_31-24-2":{"w":"민법 제278조는 소유권 외의 재산권에 합유 규정을 준용한다. 제273조 제1항은 합유자가 전원의 동의 없이 지분을 처분하지 못하게 한다. 준합유하는 전세권 지분도 같다.","c":"중","v":1},"법무사2025_31-24-3":{"w":"농지취득자격증명은 취득자별로 받으므로(농지법 제8조) 합유자 전원이 받았다면 합유로 하는 이전등기를 할 수 있다는 것이 등기선례다.","c":"중","v":1},"법무사2025_31-24-5":{"w":"처분금지가처분은 상대적 효력만 있어 가처분 뒤의 처분도 등기할 수 있다. 공유자 전원이 공유를 합유로 바꾸는 변경등기도 가처분권자 승낙 없이 허용된다(등기선례).","c":"중","v":1},"법무사2025_31-25-1":{"w":"사인증여에는 유증 규정이 준용되므로(민법 제562조) 유언집행자가 등기의무자다. 유언집행자가 여럿이면 과반수로 신청하며(제1102조) 수증자와 공동신청한다(등기선례).","c":"중","v":1},"법무사2025_31-25-3":{"w":"양도담보는 소유권을 이전하는 계약이어서 부동산등기 특별조치법 제3조의 검인 대상이다. 대가성 있는 이전이므로 허가구역 안 토지는 토지거래허가도 받는다(등기예규).","c":"중","v":1},"법무사2025_31-25-4":{"w":"현물출자에 따른 이전등기의 등기원인증서는 현물출자계약서다. 정관이나 이사회의사록은 회사 내부 절차 자료여서 첨부정보로 낼 필요가 없다는 것이 등기선례다.","c":"중","v":1},"법무사2025_31-25-5":{"w":"계약해제의 원상회복은 말소등기로 하는 것이 원칙이지만 판례와 등기예규는 「계약해제」를 원인으로 한 이전등기 방식도 허용한다. 진정명의회복 원인 이전등기를 허용하는 것과 같은 취지다.","c":"중","v":1},"법무사2025_31-27-1":{"w":"진정명의회복 등기에 관한 등기예규는 지적공부상 소유자로 등록되어 보존등기를 신청할 수 있는 자가 현재 명의인과 공동으로 진정명의회복 원인 이전등기를 신청할 수 있게 한다.","c":"중","v":1},"법무사2025_31-27-2":{"w":"변론종결 후 피고로부터 지분을 넘겨받은 제3자는 기판력이 미치는 승계인이다(민사소송법 제218조 제1항). 원고는 승계집행문을 받아 그를 등기의무자로 진정명의회복 이전등기를 신청할 수 있다(등기예규).","c":"중","v":1},"법무사2025_31-27-3":{"w":"진정명의회복은 특정 일자의 법률행위로 생기는 것이 아니어서 공동신청이든 판결에 의한 신청이든 등기원인일자를 내지 않는다(진정명의회복 등기에 관한 등기예규).","c":"중","v":1},"법무사2025_31-27-4":{"w":"공동신청은 소유권 등기명의인이 등기의무자로 신청하는 것이어서 부동산등기규칙 제60조 제1항 제1호에 따라 등기의무자의 인감증명을 낸다.","c":"상","v":1},"법무사2026_32-02-1":{"w":"부동산등기 특별조치법 제3조 제2항은 등기원인증서가 집행력 있는 판결서나 같은 효력이 있는 조서이면 그 판결서 등에 검인을 받게 한다. 공유물분할·재산분할 판결도 계약에 갈음하는 것이어서 검인 대상이다(검인에 관한 등기예규).","c":"중","v":1},"법무사2026_32-02-2":{"w":"검인은 계약을 원인으로 한 이전등기에 받는다(부동산등기 특별조치법 제3조). 경매 매각이나 공매는 계약이 아닌 공법상 처분이어서 검인이 필요 없다(검인에 관한 등기예규).","c":"중","v":1},"법무사2026_32-02-3":{"w":"가등기는 소유권이전등기가 아니어서 부동산등기 특별조치법 제3조의 검인 대상이 아니다. 본등기를 신청할 때 검인을 받는다(검인에 관한 등기예규).","c":"중","v":1},"법무사2026_32-02-4":{"w":"검인은 계약서 원본에 받는 것이 원칙이지만 검인에 관한 등기예규는 분양계약서 원본을 잃어버리면 쌍방이 사본에 원본 분실과 사본이 원본과 같다는 취지를 적고 날인해 그 사본에 검인을 받게 한다.","c":"중","v":1},"법무사2026_32-06-1":{"w":"부동산등기법 제99조 제1항에 따라 수용 등기는 사업시행자가 단독으로 신청한다. 사업시행자는 수용 개시일에 소유권을 취득하므로(토지보상법 제45조 제1항) 등기원인은 「수용」, 원인일자는 수용의 개시일로 적는다(등기예규).","c":"중","v":1},"법무사2026_32-06-3":{"w":"수용 재결이 실효되면 수용으로 인한 이전등기의 원인이 없어진다. 토지수용 등기에 관한 등기예규는 그 말소를 공동신청으로 하게 한다. 말소하면 등기관은 수용 때 직권말소한 등기를 직권으로 회복한다.","c":"중","v":1},"법무사2026_32-06-4":{"w":"수용재결로 생긴 소유권취득은 재결이 실효되지 않는 한 유지된다. 사업계획 변경으로 필요가 없어졌으면 환매(토지보상법 제91조) 등으로 해결할 문제여서 바로 말소등기를 신청할 수 없다(등기선례).","c":"중","v":1},"법무사2026_32-06-5":{"w":"토지보상법 제75조 제1항 단서의 물건 가격 보상은 이전비 대신 지급하는 손실보상일 뿐이다. 수용재결을 거치지 않았다면 그 보상만으로 사업시행자가 지장물 소유권을 취득하지 않는다는 것이 판례다.","c":"중","v":1},"법무사2026_32-13-1":{"w":"협의분할은 공유자 전원이 참여해야 하지만 분할 비율은 자유이므로 지분비율을 넘는 분할을 원인으로도 이전등기를 신청할 수 있다(등기선례).","c":"중","v":1},"법무사2026_32-13-3":{"w":"총유에는 분할청구 규정이 없고 구성원은 지분이 없다(민법 제275조, 제276조). 사단 소유를 구성원 공동소유로 하려면 사단에서 각 구성원에게 소유권 일부를 이전하는 등기를 한다(등기선례).","c":"중","v":1},"법무사2026_32-13-4":{"w":"법인 아닌 사단과 그 구성원은 별개의 권리주체다. 그래서 사단 소유를 구성원 합유로 하려면 권리변경등기가 아니라 사단에서 구성원 전원의 합유로 소유권이전등기를 신청한다(등기선례).","c":"중","v":1},"법무사2026_32-13-5":{"w":"특약이 없으면 사망한 합유자의 지분은 잔존 합유자에게 귀속하고 상속인에게 승계되지 않는다는 것이 판례다. 상속인끼리 받은 상속지분 이전 판결로는 합유지분 이전등기를 할 수 없다(등기선례).","c":"중","v":1},"법무사2016_22-23-1":{"w":"근저당권 이전등기를 하려면 등기의무자 표시가 등기기록과 일치해야 한다(부동산등기법 제29조 제7호). 그래서 취급지점이 바뀌었으면 먼저 등기명의인표시변경등기를 한 뒤 이전등기를 신청한다(등기선례).","c":"중","v":1},"법무사2016_22-23-2":{"w":"부동산등기법 제79조와 부동산등기규칙 제137조: 채권 일부의 양도나 대위변제로 저당권 일부이전등기를 하면 양도액이나 변제액을 기록하므로 신청정보로 낸다.","c":"상","v":1},"법무사2016_22-23-4":{"w":"저당권은 소유권 외의 권리이므로 그 이전등기는 부동산등기법 제52조 제2호에 따라 언제나 부기등기로 한다. 이해관계인 승낙 여부에 따라 주등기가 되는 경우가 없다.","c":"상","v":1},"법무사2016_22-23-5":{"w":"근저당권은 하나의 채권최고액 범위에서 담보하는 권리여서 채권자나 채무자가 여럿이라도 각자 채권액을 나누어 기록하지 않는다는 것이 근저당권 등기에 관한 등기예규다(부동산등기법 제75조 제2항).","c":"중","v":1},"법무사2016_22-24-1":{"w":"농지법 제23조는 농지 임대차를 제한하고 판례·등기예규는 농지를 원칙적으로 전세권의 목적으로 할 수 없다고 본다(민법 제303조 제2항 참조). 그래서 농지 전세권설정 신청은 부동산등기법 제29조 제2호로 각하한다.","c":"중","v":1},"법무사2016_22-24-2":{"w":"전세권은 물건을 점유·사용하는 권리여서 공유지분에는 설정할 수 없다(전세권 등기에 관한 등기예규). 층별 면적 비율로 지분을 나누어 가져도 지분은 관념적 비율이므로 자기 지분만을 목적으로 전세권을 등기할 수 없다.","c":"중","v":1},"법무사2016_22-24-3":{"w":"공유물 전체를 임대하는 것은 공유자 과반수 지분으로 할 수 있지만(민법 제265조) 임차권등기는 공유자 전원의 소유권에 부담을 지우는 처분행위다. 그래서 공유자 전원이 등기의무자로 신청한다(등기예규).","c":"중","v":1},"법무사2016_22-24-4":{"w":"부동산등기법 제69조 제6호·제72조 제1항 제6호·제74조 제6호는 지상권·전세권·임차권 범위가 부동산 일부이면 그 도면 번호를 기록하게 한다. 부동산 일부에 설정할 수 있다는 전제다.","c":"상","v":1},"법무사2016_22-25-1":{"w":"부동산등기규칙 제130조 제2항(제128조 제2항 준용)은 일부에 대한 임차권설정이면 도면을 내게 한다. 등기예규는 범위가 건물의 특정층 전부이면 층으로 특정되므로 도면을 내지 않아도 된다고 정한다.","c":"중","v":1},"법무사2016_22-25-3":{"w":"임차권은 부동산을 점유·사용하는 권리여서 관념적 지분에 대해서는 성립할 수 없다. 그래서 공유지분에 대한 주택임차권등기 촉탁은 수리하지 않는다(임차권등기명령에 관한 등기예규).","c":"중","v":1},"법무사2016_22-25-4":{"w":"토지의 상하 범위를 정한 구분 권리는 지상권에 대해서만 민법 제289조의2가 인정한다. 임차권에는 그런 규정이 없어 송수관 매설용 구분임차권등기를 신청할 수 없다(등기선례).","c":"중","v":1},"법무사2016_22-25-5":{"w":"전세권과 주택임차권은 별개의 권리이고 대항력·우선변제권 확보 수단이 다르다. 그래서 같은 사람이 전세권등기를 한 주택이라도 임차권등기명령에 따른 촉탁을 수리한다(등기선례).","c":"중","v":1},"법무사2017_23-14-1":{"w":"민법 제289조의2 제1항은 구분지상권을 「건물 기타 공작물」을 소유하기 위해서만 설정할 수 있게 한다. 수목 소유를 목적으로는 설정할 수 없다(구분지상권 등기에 관한 등기예규).","c":"중","v":1},"법무사2017_23-14-3":{"w":"부동산등기법 제69조 제5호는 민법 제289조의2 제1항 후단의 약정(구분지상권 행사를 위한 토지 사용 제한)을 등기사항으로 정한다. 그래서 그 약정이 있으면 신청정보에 넣는다(부동산등기규칙 제126조 제1항).","c":"상","v":1},"법무사2017_23-14-4":{"w":"통상의 지상권을 구분지상권으로 바꾸는 것은 권리의 변경등기다. 부동산등기법 제52조 제5호에 따라 등기상 이해관계인이 없거나 그 승낙이 있으면 부기등기로 한다.","c":"중","v":1},"법무사2017_23-14-5":{"w":"도시철도법은 도시철도건설자가 수용재결로 취득한 구분지상권이 경매 매각으로 소멸하지 않는다고 정한다. 그래서 먼저 등기된 강제경매에 의한 매각 이전등기 촉탁이 있어도 그 구분지상권은 말소하지 않는다(등기예규).","c":"중","v":1},"법무사2017_23-17-1":{"w":"지역권설정등기는 승역지 등기기록에 하므로 승역지 관할 등기소에 신청한다. 부동산등기법 제71조 제1항에 따라 요역지 등기기록에는 등기관이 직권으로 기록한다.","c":"상","v":1},"법무사2017_23-17-3":{"w":"부동산등기법 제70조는 지역권 등기사항으로 목적·범위·요역지 등을 정하고 지역권자를 넣지 않는다. 지역권은 요역지 소유권에 붙어 있어 요역지 소유자가 곧 권리자이기 때문이다.","c":"상","v":1},"법무사2017_23-17-4":{"w":"통행권 확인판결은 주위토지통행권 같은 법정 권리를 확인한 것이어서 지역권설정 의사표시를 갈음하지 않는다. 그래서 그 판결로 지역권설정등기를 할 수 없다(등기선례).","c":"중","v":1},"법무사2017_23-17-5":{"w":"민법 제292조 제1항: 지역권은 요역지 소유권에 부종하여 이전한다. 그래서 요역지 소유권이전등기만 있으면 지역권 이전등기 없이도 지역권이 함께 이전된다.","c":"상","v":1},"법무사2018_24-24-1":{"w":"임차권등기는 공유자 전원의 소유권에 부담을 지우는 처분이므로 공유자 전원이 계약당사자인 임대차계약서를 원인증서로 하여 전원이 등기의무자로 신청한다(등기예규).","c":"중","v":1},"법무사2018_24-24-2":{"w":"임차권등기명령에 따른 주택임차권등기는 처분제한 등기에 준하므로 미등기 주택이면 부동산등기법 제66조를 유추해 등기관이 직권으로 보존등기를 한 뒤 임차권등기를 한다(임차권등기명령에 관한 등기예규).","c":"중","v":1},"법무사2018_24-24-3":{"w":"촉탁서상 등기의무자 표시가 등기기록과 맞지 않으면 부동산등기법 제29조 제7호 각하사유다. 결정 후 소유권이 넘어갔는데 전 소유자를 의무자로 적은 촉탁은 각하한다(임차권등기명령에 관한 등기예규).","c":"중","v":1},"법무사2018_24-24-4":{"w":"전세권과 임차권은 별개의 권리이므로 같은 사람이 전세권등기를 한 주택에도 임차권등기명령에 따른 등기를 할 수 있다(등기선례).","c":"중","v":1},"법무사2018_24-29-1":{"w":"공장저당은 공장 소유자의 토지·건물과 그에 설치된 기계 등을 함께 담보로 하는 것이다(공장저당법 제4조~제6조). 토지 소유자가 다르면 건물만 공장저당으로 하고 토지는 보통 근저당으로 하여 공동담보로 설정할 수 있다(등기선례).","c":"중","v":1},"법무사2018_24-29-3":{"w":"부동산등기규칙 제47조 제1항 제1호는 같은 채권을 담보하려고 소유자가 다른 여러 부동산에 저당권을 설정하면 일괄신청을 허용한다. 창설적 공동근저당도 이에 해당한다.","c":"상","v":1},"법무사2018_24-29-4":{"w":"추가 공동담보는 종전 근저당권과 같은 채권을 담보해야 하므로 채무자 표시가 같아야 한다. 주소가 다르면 먼저 종전 근저당권의 채무자 주소 변경등기를 한다(공동담보 등기에 관한 등기예규).","c":"중","v":1},"법무사2018_24-29-5":{"w":"추가 근저당권설정은 새 부동산 소유자가 등기의무자이므로 그 부동산의 등기필정보를 낸다. 종전 부동산이나 종전 근저당권의 등기필정보는 필요 없다(등기예규).","c":"중","v":1},"법무사2019_25-02-1":{"w":"전세권변경이 주등기로 되었으면 증액 부분은 2번 근저당권보다 후순위인 별개 등기로 공시된다. 전세권을 목적으로 하는 근저당권은 본래 전세권인 1번 등기에 부기한다(부동산등기법 제52조 제3호, 등기선례).","c":"중","v":1},"법무사2019_25-02-2":{"w":"판례는 근저당권 설정 후 소유권이 제3자에게 넘어간 경우 근저당권설정자도 계약상 권리로, 제3취득자도 소유권에 기해 말소를 청구할 수 있다고 본다. 그래서 어느 쪽이든 근저당권자와 공동으로 말소를 신청할 수 있다(등기예규).","c":"중","v":1},"법무사2019_25-02-3":{"w":"채권최고액 증액은 뒤에 압류한 처분청에 불이익하므로 처분청은 등기상 이해관계인이다. 승낙정보가 없으면 부동산등기법 제52조 제5호 단서에 따라 주등기로 한다.","c":"중","v":1},"법무사2019_25-02-5":{"w":"혼동 말소는 근저당권자 겸 소유자가 단독신청한다. 그런데 甲 사망 뒤 근저당권은 공동상속인 전원에게 상속되었으므로 협의분할로 소유권만 받은 乙 혼자서 근저당권 말소를 신청할 수는 없다는 것이 등기선례다.","c":"중","v":1},"법무사2019_25-09-1":{"w":"구분지상권이 설정된 토지에도 그 구분지상권자의 승낙이 있으면 통상의 지상권을 설정할 수 있다(민법 제289조의2 제2항 참조, 구분지상권 등기에 관한 등기예규).","c":"중","v":1},"법무사2019_25-09-2":{"w":"민법 제280조의 존속기간은 최단기간 제한이므로 더 긴 기간이나 철탑 존속기간 같은 불확정기간도 약정할 수 있다는 것이 판례·등기선례다. 그래서 그런 기간으로 등기를 신청할 수 있다.","c":"중","v":1},"법무사2019_25-09-3":{"w":"구분지상권은 토지의 상하 범위를 정해 설정하므로 범위가 서로 다른 구분지상권은 한 토지에 여러 개 등기할 수 있다(구분지상권 등기에 관한 등기예규).","c":"중","v":1},"법무사2019_25-09-4":{"w":"토지 지상권은 건물 보존등기와 등기상 이해관계가 없으므로 지상권 말소나 지상권자 승낙 없이 제3자가 신축한 건물의 보존등기를 할 수 있다(등기선례).","c":"중","v":1},"법무사2019_25-29-1":{"w":"공장 및 광업재단 저당법 제4조·제5조에 따른 공장저당 등기에는 그 토지·건물이 같은 법 제2조의 공장에 속한다는 것을 증명하는 정보를 낸다(공장저당 등기에 관한 등기예규).","c":"중","v":1},"법무사2019_25-29-2":{"w":"공장저당법 제6조는 저당권 목적이 되는 기계·기구 등의 목록을 제출하게 한다. 저당권 효력은 공장 소유자의 물건에 미치므로(제3조) 목록 물건은 공장소유자 것이어야 한다(등기예규).","c":"중","v":1},"법무사2019_25-29-3":{"w":"공장저당법 제6조 제2항은 목록 기록사항의 변경을 소유자가 신청하게 한다. 기계·기구를 추가하는 목록기재변경등기는 소유자가 단독으로 신청한다(공장저당 등기에 관한 등기예규).","c":"중","v":1},"법무사2019_25-29-5":{"w":"목록 변경은 목록 자체를 고치는 방법으로 하므로 을구에 부기등기를 하지 않는다. 목록을 모두 폐지해 일반 저당권으로 바꾸는 경우에만 을구에 변경등기를 한다(공장저당 등기에 관한 등기예규).","c":"중","v":1},"법무사2020_26-18-1":{"w":"농지는 원칙적으로 전세권 목적이 될 수 없지만 국토계획법상 도시지역 안의 농지(녹지지역은 도시·군계획시설사업에 필요한 농지만)는 농지법상 제한이 풀려 전세권을 설정할 수 있다(전세권 등기에 관한 등기예규).","c":"중","v":1},"법무사2020_26-18-2":{"w":"전세권은 건물 일부에도 설정할 수 있다(부동산등기법 제72조 제1항 제6호). 보존등기된 건물의 옥상도 건물 일부이므로 그 전부나 일부를 쓰기 위한 전세권을 등기할 수 있다(등기선례).","c":"중","v":1},"법무사2020_26-18-3":{"w":"부동산등기규칙 제128조 제2항은 일부에 대한 전세권이면 도면을 내게 한다. 등기예규는 범위가 건물의 특정층 전부이면 층으로 특정되므로 도면을 내지 않아도 된다고 정한다.","c":"중","v":1},"법무사2020_26-18-5":{"w":"법정갱신(민법 제312조 제4항)은 등기 없이 효력이 있지만 이를 처분하려면 등기해야 한다(민법 제187조 단서). 그래서 갱신된 전세권을 이전하려면 먼저 존속기간 변경등기를 한다(판례·등기예규).","c":"중","v":1},"법무사2020_26-27-1":{"w":"채무자 사망 후 상속인 1인만 채무자로 하려면 계약인수나 확정채무의 면책적 인수를 원인으로 근저당권자와 설정자(또는 소유자)가 공동으로 채무자 변경등기를 신청한다(근저당권 등기에 관한 등기예규).","c":"중","v":1},"법무사2020_26-27-2":{"w":"하나의 설정계약에 따른 근저당권은 하나의 권리여서 채권최고액을 나누어 여러 개 근저당권으로 등기할 수 없다는 것이 근저당권 등기에 관한 등기예규다.","c":"중","v":1},"법무사2020_26-27-3":{"w":"근저당권설정계약의 당사자는 근저당권자와 설정자이고 채무자는 당사자가 아니다. 그래서 계약서에 채무자 표시만 있으면 되고 채무자 날인은 필요 없다(등기선례).","c":"중","v":1},"법무사2020_26-27-4":{"w":"외국통화로 채권최고액을 정하면 그 외화표시 금액을 채권최고액으로 기록한다(근저당권 등기에 관한 등기예규). 원화로 환산하지 않는다.","c":"중","v":1},"법무사2021_27-07-1":{"w":"민법 제348조와 부동산등기법 제52조 제3호에 따라 저당권부 채권에 대한 질권 등기는 소유권 외의 권리를 목적으로 하는 권리의 등기로서 근저당권등기에 부기한다.","c":"상","v":1},"법무사2021_27-07-2":{"w":"근저당권부 채권에 대한 질권 등기는 근저당권자(질권설정자)가 등기의무자, 질권자가 등기권리자로 공동신청한다(부동산등기법 제23조 제1항).","c":"중","v":1},"법무사2021_27-07-4":{"w":"부동산등기법 제76조 제1항 제1호는 저당권부 채권에 대한 질권 등기에 채권액 또는 채권최고액을 기록하게 한다.","c":"상","v":1},"법무사2021_27-07-5":{"w":"질권자는 질물을 전질할 수 있다(민법 제336조). 저당권부 채권 질권을 전질하면 질권 이전의 부기등기를 할 수 있다(등기선례).","c":"중","v":1},"법무사2021_27-08-1":{"w":"공동근저당권은 하나의 채권최고액으로 여러 부동산을 함께 담보하는 하나의 권리다. 이를 부동산별로 나누어 별개 근저당권으로 만드는 변경등기는 이해관계인이 없어도 할 수 없다(근저당권 등기에 관한 등기예규).","c":"중","v":1},"법무사2021_27-08-3":{"w":"근저당권 등기에 관한 등기예규는 채무자가 여럿이면 연대채무자라도 「연대채무자」가 아니라 단순히 「채무자」로 기록하게 한다(부동산등기법 제75조 제2항 제2호).","c":"중","v":1},"법무사2021_27-08-4":{"w":"하나의 근저당권설정계약은 하나의 근저당권을 만든다. 공동채권자별로 최고액을 구분하거나 2개의 동순위 근저당권으로 나누어 등기할 수 없다(근저당권 등기에 관한 등기예규).","c":"중","v":1},"법무사2021_27-08-5":{"w":"피담보채권이 확정되면 근저당권은 보통 저당권처럼 채권에 수반한다. 확정 후 양도·대위변제는 저당권이전에 준해 이전등기를 하고 원인을 「확정채권 양도」 등으로 적는다(근저당권 등기에 관한 등기예규).","c":"중","v":1},"법무사2021_27-09-1":{"w":"부동산등기법 제70조: 승역지에 지역권설정등기를 할 때 지역권설정의 목적·범위·요역지를 기록한다.","c":"상","v":1},"법무사2021_27-09-3":{"w":"부동산등기규칙 제127조 제2항은 지역권 범위가 승역지 일부이면 제126조 제2항을 준용해 그 부분을 표시한 지적도를 내게 한다.","c":"상","v":1},"법무사2021_27-09-4":{"w":"부동산등기법 제71조 제1항: 승역지에 지역권설정등기를 하면 등기관이 직권으로 요역지 등기기록에 순위번호·등기목적·승역지·목적·범위·등기연월일을 기록한다.","c":"상","v":1},"법무사2021_27-26-2":{"w":"지상권은 토지 일부에도 설정할 수 있다(부동산등기법 제69조 제6호). 이때 부동산등기규칙 제126조 제2항에 따라 그 부분을 표시한 지적도를 첨부정보로 낸다.","c":"상","v":1},"법무사2021_27-26-3":{"w":"민법 제280조는 지상권 존속기간의 최단기간만 정하고 최장기간 제한이 없다. 그래서 100년·120년처럼 긴 확정기간으로도 지상권설정등기를 할 수 있다(판례·등기선례).","c":"중","v":1},"법무사2021_27-26-4":{"w":"민법 제289조의2 제1항: 지하나 지상 공간은 상하 범위를 정해 건물 기타 공작물을 소유하기 위한 지상권의 목적으로 할 수 있다. 등기할 때 그 상하 범위를 기록한다(부동산등기법 제69조 제2호).","c":"상","v":1},"법무사2021_27-26-5":{"w":"부동산 거래신고 등에 관한 법률 제11조 제1항은 허가구역 안 토지의 소유권·지상권을 대가를 받고 이전하거나 설정하는 계약에 허가를 받게 한다. 그래서 유상 지상권 설정등기에는 허가서를 붙인다.","c":"중","v":1},"법무사2021_27-30-2":{"w":"「임차권등기명령 절차에 관한 규칙」은 임차권등기명령의 효력이 생기면 법원사무관등이 지체 없이 촉탁서에 재판서 등본을 붙여 등기관에게 임차권등기 기입을 촉탁하게 한다(주택임대차보호법 제3조의3).","c":"중","v":1},"법무사2021_27-30-3":{"w":"결정 후 소유권이 이전되었는데 촉탁서에 전 소유자를 등기의무자로 적으면 등기기록과 맞지 않아 부동산등기법 제29조 제7호 각하사유가 된다(임차권등기명령에 관한 등기예규).","c":"중","v":1},"법무사2021_27-30-4":{"w":"임차권등기명령에 관한 등기예규는 주택임대차보호법에 따른 임차권등기의 등기목적을 「주택임차권」으로 기록하게 한다. 상가건물은 「상가건물임차권」으로 한다.","c":"중","v":1},"법무사2021_27-30-5":{"w":"부동산등기규칙 제53조 제1항 제6호: 관공서가 촉탁하는 등기에서는 그 관공서에 등기완료통지를 한다. 법원이 촉탁한 임차권등기도 촉탁법원에 완료통지서를 보낸다.","c":"상","v":1},"법무사2022_28-06-1":{"w":"판례는 「어음할인, 대부, 보증 기타 일체의 채무」를 담보한다는 포괄근저당도 유효하다고 본다. 그래서 그런 내용의 설정계약을 원인으로 근저당권설정등기를 할 수 있다(등기선례).","c":"중","v":1},"법무사2022_28-06-2":{"w":"확정 전 근저당권 준공유 지분은 기본계약상 지위와 함께 이전되므로 나머지 준공유자 동의가 필요하다. 확정채권 양도를 원인으로 할 때는 확정 증명서면이나 나머지 근저당권자 전원의 동의서(인감증명 포함)를 낸다(근저당권 등기에 관한 등기예규).","c":"중","v":1},"법무사2022_28-06-3":{"w":"확정 후 근저당권은 채권과 함께 이전되므로 여러 양수인에게 나누어 넘기면 채권 일부 양도와 같다. 부동산등기규칙 제137조 제2항·부동산등기법 제79조에 따라 양수인별 양도액을 특정한다(등기예규).","c":"중","v":1},"법무사2022_28-06-4":{"w":"채권최고액 감액은 근저당권자에게 불리하고 설정자에게 유리한 변경이다. 그래서 설정자가 등기권리자, 근저당권자가 등기의무자로 공동신청한다(부동산등기법 제23조 제1항, 등기예규).","c":"중","v":1},"법무사2022_28-21-1":{"w":"토지 지상권은 토지 등기기록에서 양립할 수 없는 용익물권(지상권·전세권 등)이 있는지만 문제된다. 지상에 등기된 건물이 있어도 그런 권리가 없으면 지상권설정등기를 할 수 있다(등기선례).","c":"중","v":1},"법무사2022_28-21-2":{"w":"민법 제280조 제2항은 최단기간보다 짧게 정한 존속기간을 최단기간까지 연장한다. 신청서에 짧은 기간이 적혀 있어도 법률이 자동으로 늘리므로 등기관은 그대로 수리한다(지상권 등기에 관한 등기예규).","c":"중","v":1},"법무사2022_28-21-3":{"w":"통상 지상권을 구분지상권으로 바꾸는 것은 권리 변경등기다. 부동산등기법 제52조 제5호와 단서에 따라 이해관계인이 없거나 그 승낙·대항 재판이 있으면 부기로 한다.","c":"중","v":1},"법무사2022_28-21-4":{"w":"구분지상권은 토지의 지하·지상 공간을 상하로 나누는 권리다(민법 제289조의2). 구분건물의 특정 계층 구분소유를 목적으로 하는 것은 토지 공간이 아니라 건물에 관한 것이어서 구분지상권으로 설정할 수 없다(등기예규).","c":"중","v":1},"법무사2022_28-29-1":{"w":"존속기간이 끝난 임차권은 이전·전대할 대상이 없다. 주택·상가건물 임차권등기명령에 따른 등기는 대항력·우선변제권 유지를 위한 담보적 등기여서 이에 기초한 이전이나 전대 등기도 할 수 없다(임차권등기에 관한 등기예규).","c":"중","v":1},"법무사2022_28-29-2":{"w":"임차권은 건물 일부에도 설정할 수 있으므로(부동산등기법 제74조 제7호) 지붕·옥상에도 할 수 있다. 그 일부만이면 부동산등기규칙 제130조 제2항에 따라 그 부분을 표시한 도면을 낸다(등기선례).","c":"중","v":1},"법무사2022_28-29-4":{"w":"판례는 불확정기간을 존속기간으로 하는 임대차도 허용한다. 그래서 선하부지 임대차를 「송전선이 존속하는 기간」으로 정한 임차권설정등기도 할 수 있다(등기선례).","c":"중","v":1},"법무사2022_28-29-5":{"w":"사립학교법 제28조 제1항과 시행령 제11조는 학교법인이 기본재산에 의무를 부담하게 하는 행위에도 관할청 허가를 받게 한다. 임차권 설정도 이에 해당해 허가 증명서면을 낸다(등기선례).","c":"중","v":1},"법무사2023_29-14-1":{"w":"저당권의 목적은 부동산과 지상권·전세권으로 한정된다(민법 제356조, 제371조). 토지임차권은 저당권 목적이 될 수 없어 대지권이 임차권이면 건물과 대지권을 공동저당 목적으로 할 수 없다(등기선례).","c":"중","v":1},"법무사2023_29-14-3":{"w":"공동저당은 하나의 채권을 여러 부동산이 함께 담보하는 것이다. 일부 부동산만 따로 채무자를 바꾸면 같은 채권이 아니게 되므로 공동저당관계가 유지되는 한 그런 변경등기는 할 수 없다(등기선례).","c":"중","v":1},"법무사2023_29-14-4":{"w":"대지에 저당권이 있는 상태에서 대지권등기를 하고 같은 채권을 위해 구분건물에 저당권을 추가하면 구분건물과 대지권을 일체로 한 추가저당권설정등기를 신청할 수 있다(대지권 등기에 관한 등기예규).","c":"중","v":1},"법무사2023_29-14-5":{"w":"민법 제368조 제2항의 차순위저당권자 대위등기는 선순위저당권자가 등기의무자, 대위자가 등기권리자로 공동신청한다. 부동산등기법 제80조와 등기예규에 따라 배당표 정보를 첨부한다.","c":"중","v":1},"법무사2023_29-28-1":{"w":"토지와 건물은 별개 부동산이어서 건물에 전세권이 있어도 대지 전부를 목적으로 별도 전세권을 설정할 수 있다(등기선례).","c":"중","v":1},"법무사2023_29-28-2":{"w":"존속기간은 설정계약에 따르므로 시작일이 신청 접수일 이전이라도 등기관은 이를 이유로 각하하지 않는다(전세권 등기에 관한 등기선례). 형식적 심사권만 있는 등기관이 계약 내용을 고칠 수 없다.","c":"중","v":1},"법무사2023_29-28-4":{"w":"민법 제306조: 전세권자는 설정행위로 금지하지 않는 한 존속기간 내에서 전세권을 양도하거나 목적물을 전전세할 수 있다. 설정자의 동의가 필요 없다.","c":"상","v":1},"법무사2023_29-28-5":{"w":"존속기간 만료 후의 전세권도 전세금반환채권을 담보하는 담보물권으로 남는다는 것이 판례다. 그래서 설정행위로 금지하지 않았으면 전세금반환채권과 함께 전세권 이전등기를 할 수 있다(등기예규).","c":"중","v":1},"법무사2023_29-29-2":{"w":"공장 및 광업재단 저당법 제6조 제2항은 제출된 기계·기구 목록을 등기부의 일부로 보고 그 기록을 등기된 것으로 본다.","c":"중","v":1},"법무사2023_29-29-3":{"w":"공장저당 등기에 관한 등기예규는 토지나 건물이 공장저당법상 공장에 속한다는 것을 증명하는 정보를 내게 한다. 공장 사용 사실을 아는 채권자 명의의 증명서면이 그 예다.","c":"중","v":1},"법무사2023_29-29-4":{"w":"기계·기구 일부가 멸실·분리되면 저당권의 담보 범위가 줄어든다. 그래서 그 목록 변경을 신청할 때 저당권자의 동의나 이에 대항할 수 있는 재판 증명정보를 낸다(공장저당법 제6조, 공장저당 등기에 관한 등기예규).","c":"중","v":1},"법무사2023_29-29-5":{"w":"기계·기구를 모두 새것으로 바꾸는 것은 목록 일부 변경이 아니다. 그래서 목록폐지로 공장저당을 보통저당으로 바꾼 뒤 새 목록을 제출해 다시 공장저당으로 바꾸는 두 단계 변경등기를 한다(공장저당 등기에 관한 등기예규).","c":"중","v":1},"법무사2024_30-17-4":{"w":"채무자에 대한 양도통지나 승낙은 채무자에 대한 대항요건일 뿐 등기요건이 아니다. 대위변제도 같다. 그래서 근저당권이전등기에는 이를 증명하는 정보가 필요 없다(근저당권 등기에 관한 등기예규).","c":"중","v":1},"법무사2024_30-23-1":{"w":"지역권설정등기는 승역지 등기기록에 하므로 승역지 관할 등기소에 신청한다. 요역지 기록은 부동산등기법 제71조 제1항에 따라 등기관이 직권으로 한다.","c":"상","v":1},"법무사2024_30-23-2":{"w":"지역권은 요역지의 편익을 위한 권리여서 요역지를 사용할 권리를 가진 지상권자·전세권자·임차권자도 지역권을 설정받을 수 있다는 것이 등기예규다. 그래서 지상권자도 등기권리자가 된다.","c":"중","v":1},"법무사2024_30-23-3":{"w":"요역지 지상권자 등은 그 지역권의 편익을 누리므로 지역권 말소에 대해 등기상 이해관계가 있다. 부동산등기법 제57조 제1항에 따라 그 동의 증명정보를 낸다(등기예규).","c":"중","v":1},"법무사2024_30-23-4":{"w":"지방세법 제28조 제1항 제1호 다목 3): 지역권 설정·이전 등기의 등록면허세는 요역지 가액의 1천분의 2다. 과세표준이 요역지 가액이다.","c":"상","v":1},"법무사2025_31-03-1":{"w":"도시철도법 등에 의한 구분지상권 등기에 관한 등기예규는 도시철도건설자 등이 구분지상권 설정을 내용으로 하는 수용·사용재결을 받으면 재결서와 보상·공탁 증명정보를 붙여 단독으로 구분지상권설정등기를 신청하게 한다.","c":"중","v":1},"법무사2025_31-03-3":{"w":"사용재결로 단독신청할 수 있는 것은 재결 내용인 구분지상권 설정뿐이다. 그래서 통상의 지상권설정등기는 신청할 수 없다(도시철도법 등에 의한 구분지상권 등기에 관한 등기예규).","c":"중","v":1},"법무사2025_31-03-4":{"w":"이미 등기된 구분지상권을 수용하는 재결을 받으면 재결서와 보상·공탁 증명정보를 붙여 단독으로 권리수용을 원인으로 하는 구분지상권이전등기를 신청한다(부동산등기법 제99조 제5항, 등기예규).","c":"중","v":1},"법무사2025_31-03-5":{"w":"도시철도법 등은 수용·사용재결로 취득한 구분지상권이 경매로 소멸하지 않는다고 정한다. 그래서 먼저 등기된 경매개시결정에 의한 매각 이전등기 촉탁이 있어도 말소하지 않는다(등기예규).","c":"중","v":1},"법무사2025_31-08-1":{"w":"저당권부 채권담보권 등기에 관한 등기예규는 등기목적을 「저당권부 채권담보권 설정」으로 하고 목적 저당권을 접수일자·접수번호·순위번호로 특정하게 한다(부동산등기규칙 제132조 제2항).","c":"중","v":1},"법무사2025_31-08-2":{"w":"부동산등기규칙 제132조 제2항과 부동산등기법 제76조 제2항: 저당권에 대한 채권담보권 등기를 신청할 때 목적 채권을 담보하는 저당권의 표시, 채권액 또는 채권최고액, 채무자 표시, 변제기·이자 약정을 신청정보로 낸다.","c":"상","v":1},"법무사2025_31-08-3":{"w":"동산채권담보법 제37조가 준용하는 민법 제348조에 따라 저당권부 채권의 담보권이 저당권에 미치려면 부기등기가 필요하다. 그 전제로 채권담보권등기가 되었다는 등기사항증명서와 설정계약서를 낸다(등기예규).","c":"중","v":1},"법무사2025_31-08-4":{"w":"국민주택채권 매입 대상은 주택도시기금법 시행령 별표에 열거된 등기다. 저당권부 채권담보권 부기등기는 이에 없어 매입하지 않는다(등기예규).","c":"중","v":1},"법무사2026_32-09-1":{"w":"판례·등기선례는 등기된 임차권이 용익권능과 보증금반환채권 담보권능을 함께 가지는 반면 임차권등기명령에 따른 등기는 이미 얻은 대항력·우선변제권 유지가 주목적이라고 본다. 그래서 전세권등기와 양립한다.","c":"중","v":1},"법무사2026_32-09-2":{"w":"임차권등기명령에 의한 촉탁은 처분제한 등기에 준하므로 미등기 주택·상가건물이면 부동산등기법 제66조에 따라 직권으로 보존등기를 한 뒤 임차권등기를 한다(임차권등기명령에 관한 등기예규).","c":"중","v":1},"법무사2026_32-09-3":{"w":"상속인을 피신청인으로 한 임차권등기명령은 피상속인 명의 부동산에 대해 상속관계를 표시해 촉탁할 수 있다. 관공서 촉탁이고 상속인이 의무를 승계했으므로 상속등기가 없어도 수리한다(등기선례).","c":"중","v":1},"법무사2026_32-09-5":{"w":"묵시적 갱신은 존속기간이 끝난 다음 날부터 같은 조건으로 다시 임대차한 것으로 본다(주택임대차보호법 제6조, 상가건물임대차보호법 제10조 제4항). 그래서 원인은 「묵시의 갱신」, 원인일자는 만료일 다음 날로 적는다(등기예규).","c":"중","v":1},"법무사2026_32-14-1":{"w":"민법 제191조 제1항 단서에 따라 혼동으로 소멸할 권리가 본인이나 제3자의 권리 목적이면 소멸하지 않는다. 준공유 전세권에서 甲 지분은 乙과의 공동 관계에 묶여 있어 혼동을 원인으로 乙 단독 전세권으로 바꾸는 변경등기는 할 수 없다(등기선례).","c":"중","v":1},"법무사2026_32-14-2":{"w":"법정갱신(민법 제312조 제4항)은 법률 규정에 의한 물권변동이어서 등기 없이 주장할 수 있다(판례). 다만 그 뒤 존속기간·전세금 변경등기를 하려면 먼저 법정갱신을 원인으로 한 변경등기를 한다(등기예규).","c":"중","v":1},"법무사2026_32-14-3":{"w":"합의 갱신은 기존 등기된 기간 안의 임의의 날을 시기로 정할 수 있다. 건물 전세권은 만료 시 법정갱신되므로(민법 제312조 제4항) 만료 후 새로 기간을 정하면 법정갱신일(만료일 다음 날)부터 기산한다(등기예규).","c":"중","v":1},"법무사2026_32-14-5":{"w":"부동산등기법 제72조 제1항 단서: 전세권 존속기간은 등기원인에 약정이 있는 경우에만 기록한다. 약정이 없으면 신청정보에 넣지 않아도 제29조 제5호 각하사유가 아니다.","c":"상","v":1},"법무사2026_32-15-5":{"w":"일부 공유자의 근저당권을 위해 함께 설정된 지상권은 피담보채무가 소멸하면 목적을 잃는다. 그 말소는 공유물 보존행위(민법 제265조 단서)여서 일부 공유자가 지상권자와 공동으로 지분 전부에 대한 말소를 신청할 수 있다(등기선례).","c":"중","v":1},"법무사2026_32-27-1":{"w":"채권최고액 통화를 외화에서 원화로 바꾸면 담보 범위가 달라질 수 있어 권리 변경등기다. 부동산등기법 제52조 제5호 단서에 따라 이해관계인 승낙이 있으면 부기, 없으면 주등기로 한다(등기선례).","c":"중","v":1},"법무사2016_22-16-2":{"w":"경정등기는 등기 당시부터 등기와 실체가 어긋난 착오나 빠진 부분을 바로잡는 것이다(부동산등기법 제32조 참조). 등기 후에 생긴 사유는 변경등기 대상이어서 경정등기로 할 수 없다(경정등기에 관한 등기예규).","c":"중","v":1},"법무사2016_22-16-3":{"w":"부동산등기법 제23조 제5항: 부동산표시의 변경·경정등기는 소유권 등기명의인이 단독으로 신청한다. 등기예규는 명의인이 여럿이면 1인도 신청할 수 있고 대장 등 경정사유 소명서면만 내면 된다고 본다.","c":"중","v":1},"법무사2016_22-16-4":{"w":"부동산등기법 제23조 제6항: 등기명의인표시의 변경이나 경정의 등기는 해당 권리의 등기명의인이 단독으로 신청한다.","c":"상","v":1},"법무사2016_22-16-5":{"w":"일부말소 의미의 경정은 실질이 말소여서 부동산등기법 제57조처럼 이해관계인의 승낙이 필수다. 승낙정보가 있으면 부기로 하고 없으면 주등기로 할 수도 없어 수리하지 않는다(경정등기에 관한 등기예규).","c":"중","v":1},"법무사2016_22-17-1":{"w":"판례는 불법 말소된 근저당권의 회복등기의무자를 말소 당시의 소유자로 본다. 그 뒤 소유권을 취득한 제3자는 회복의무자가 아니라 등기상 이해관계인이다(부동산등기법 제59조).","c":"중","v":1},"법무사2016_22-17-2":{"w":"회복등기는 말소된 방식과 같은 방식으로 한다. 법원의 촉탁으로 말소된 등기는 그 법원의 촉탁으로 회복한다는 것이 말소회복등기에 관한 등기예규·판례다.","c":"중","v":1},"법무사2016_22-17-3":{"w":"부동산등기법 제59조에 따라 가등기 회복에는 이해관계인 승낙이 필요하다. 판례는 원인무효로 말소된 가등기 뒤에 등기한 제3자는 선의·악의와 관계없이 회복에 승낙할 의무가 있다고 본다.","c":"중","v":1},"법무사2016_22-17-4":{"w":"예고등기 제도는 2011년 폐지되었다. 그래서 폐쇄등기기록의 말소된 등기는 회복을 명하는 확정판결에 따른 신청이나 공동신청이 있을 때 회복한다(말소회복등기에 관한 등기예규).","c":"중","v":1},"법무사2017_23-13-1":{"w":"법률에 해산법인의 등기명의를 신설법인 명의로 본다는 간주 규정이 있으면 권리 이전 없이 명의만 바꾸면 된다. 그래서 이전등기가 아니라 등기명의인표시 변경등기를 한다(등기예규).","c":"중","v":1},"법무사2017_23-13-3":{"w":"취급지점은 근저당권자 표시의 일부여서 지점이 바뀌었으면 먼저 명의인표시 변경등기를 해야 등기기록과 신청정보가 맞는다(부동산등기법 제29조 제7호). 그 뒤 채무자 변경등기를 신청한다(등기선례).","c":"중","v":1},"법무사2017_23-13-4":{"w":"법인 아닌 사단과 법인은 서로 다른 인격이다. 명의인표시 변경은 동일인의 표시만 바꾸는 것이어서 사단을 법인으로 바꾸는 신청은 수리하지 않는다(등기예규). 이전등기로 해야 한다.","c":"중","v":1},"법무사2017_23-13-5":{"w":"부동산등기법 제23조 제6항은 등기명의인표시 변경을 해당 권리의 명의인이 단독신청하게 한다. 법원 촉탁으로 된 가압류·임차권등기도 그 명의인이 직접 표시변경을 신청할 수 있다는 것이 등기선례다.","c":"중","v":1},"법무사2017_23-16-1":{"w":"부동산등기법 제55조: 사람의 사망이나 법인의 해산으로 권리가 소멸한다는 약정이 등기되어 있고 그 사유로 권리가 소멸하면 등기권리자는 그 사실을 증명해 단독으로 말소를 신청할 수 있다.","c":"상","v":1},"법무사2017_23-16-2":{"w":"환매로 효력을 잃는 제3자 권리 등기에 대해서는 직권말소 규정이 없다. 그래서 일반 원칙대로 공동신청으로 말소한다(환매등기에 관한 등기예규).","c":"중","v":1},"법무사2017_23-16-3":{"w":"부동산등기규칙 제116조 제1항: 등기를 말소할 때에는 말소의 등기를 한 뒤 해당 등기를 말소하는 표시를 한다.","c":"상","v":1},"법무사2017_23-16-5":{"w":"판결 주문의 여러 말소등기는 각각 별개 등기여서 그중 일부만 신청할 수 있다. 근저당권말소만 신청해도 된다는 것이 판결에 의한 등기신청에 관한 등기예규다.","c":"중","v":1},"법무사2017_23-24-1":{"w":"수산업협동조합법 부칙에 수협은행이 중앙회의 권리를 승계하고 등기명의를 수협은행 명의로 본다는 간주 규정이 있다. 그래서 이전등기 없이 수협은행 명의로 말소를 신청할 수 있다(등기선례).","c":"중","v":1},"법무사2017_23-24-2":{"w":"말소 원인이 합병등기 전에 생겼으면 존속·신설회사는 포괄승계인으로서 부동산등기법 제27조에 따라 근저당권 이전등기 없이 말소를 신청할 수 있다(등기예규).","c":"중","v":1},"법무사2017_23-24-3":{"w":"근저당권이 이전되었으면 현재 권리자인 양수인이 등기의무자다. 그래서 양수인이 설정자나 제3취득자와 공동으로 말소를 신청한다(근저당권 등기에 관한 등기예규).","c":"중","v":1},"법무사2017_23-24-5":{"w":"부동산등기법 제56조: 등기의무자의 소재불명으로 공동신청할 수 없으면 민사소송법에 따라 공시최고를 신청하고 제권판결이 있으면 등기권리자가 그 사실을 증명해 단독으로 말소를 신청할 수 있다.","c":"상","v":1},"법무사2018_24-03-2":{"w":"말소회복등기는 부적법하게 말소된 등기를 되살리는 것이다. 관리청이 스스로 압류를 해제해 말소했다면 부적법 말소가 아니어서 회복등기를 할 수 없다(등기선례).","c":"중","v":1},"법무사2018_24-03-3":{"w":"부동산등기법 제59조의 이해관계인은 회복등기 당시 등기기록을 기준으로 정한다. 회복할 저당권보다 후순위 저당권자는 회복으로 순위가 밀리므로 그 설정 시점과 관계없이 승낙 증명정보를 낸다(등기선례).","c":"중","v":1},"법무사2018_24-03-4":{"w":"가등기명의인이 스스로 혼동을 원인으로 말소했다면 부적법 말소가 아니다. 그래서 그 가등기의 말소회복등기는 할 수 없다(등기선례).","c":"중","v":1},"법무사2018_24-03-5":{"w":"근저당권이 회복되면 현재 소유자는 그 부담을 지게 되므로 회복등기에 관해 등기상 이해관계 있는 제3자다(부동산등기법 제59조, 판례). 회복등기의무자는 말소 당시 소유자다.","c":"중","v":1},"법무사2018_24-06-1":{"w":"甲 단독을 甲·乙 공유로, 甲·乙 공유를 乙 단독으로 바꾸는 것은 일부말소 의미의 경정이다. 등기 전후로 권리주체 일부가 같아 동일성이 유지되므로 공동신청이나 판결에 의한 단독신청으로 할 수 있다(경정등기에 관한 등기예규).","c":"중","v":1},"법무사2018_24-06-2":{"w":"일부말소 의미의 경정등기는 실질이 말소여서 이해관계인 승낙이나 대항 재판 증명정보가 있어야만 부기등기로 한다(경정등기에 관한 등기예규). 없으면 수리하지 않는다.","c":"중","v":1},"법무사2018_24-06-3":{"w":"일부말소 의미의 경정으로 이해관계인 권리를 경정·말소하는데 그것이 가압류·가처분 같은 법원 촉탁 등기이면 등기관은 지체 없이 집행법원에 그 뜻을 통지한다(경정등기에 관한 등기예규).","c":"중","v":1},"법무사2018_24-06-5":{"w":"등기관의 잘못으로 생긴 착오는 부동산등기법 제32조 제2항에 따라 직권 경정하되 이해관계인이 있으면 그 승낙이 있어야 한다. 근저당권자의 승낙이나 대항 재판이 있어야 직권으로 일부말소 의미의 경정을 한다.","c":"중","v":1},"법무사2019_25-12-1":{"w":"선행 가처분과 후행 가처분의 피보전권리가 같으면 후행 가처분채권자의 말소로 선행 가처분채권자가 권리를 잃게 된다. 그래서 선행 가처분채권자는 등기상 이해관계인이고 그 승낙이나 대항 재판이 필요하다(등기예규).","c":"중","v":1},"법무사2019_25-12-3":{"w":"사해행위 취소를 위한 가처분채권자는 자신이 받은 판결이 아닌 수익자·채무자의 공동신청 말소로 원상회복 이익을 잃을 수 있다. 그래서 등기상 이해관계인으로 그 승낙이나 대항 재판을 낸다(등기예규).","c":"중","v":1},"법무사2019_25-12-4":{"w":"변론종결 뒤 말소대상 등기를 전제로 등기한 자는 민사소송법 제218조 제1항의 변론종결 후 승계인이다. 판결 효력이 직접 미치므로 이해관계인 승낙이 아니라 승계집행문으로 처리한다(판결에 의한 등기신청에 관한 등기예규).","c":"중","v":1},"법무사2019_25-12-5":{"w":"계약해제를 원인으로 한 새 소유권이전등기는 말소가 아니어서 부동산등기법 제57조의 이해관계인 승낙 문제가 생기지 않는다. 압류등기도 그대로 남으므로 체납처분권자 승낙이 필요 없다(등기선례).","c":"중","v":1},"법무사2019_25-30-1":{"w":"등기명의인표시 변경등기는 현재 표시를 맞추는 것이므로 주소가 여러 번 바뀌었으면 중간 변경을 생략하고 최종 주소로 바로 변경등기를 할 수 있다(등기명의인표시 변경에 관한 등기예규).","c":"중","v":1},"법무사2019_25-30-2":{"w":"조직변경은 회사의 법인격이 그대로 유지되는 것이어서 권리 이전이 없다(상법 제604조). 그래서 「조직변경」을 원인으로 등기명의인표시 변경등기를 한다(등기선례).","c":"중","v":1},"법무사2019_25-30-3":{"w":"부동산등기법 제23조 제6항에 따라 명의인표시 변경은 그 권리의 명의인이 단독신청한다. 법원 촉탁으로 된 가압류등기도 그 명의인이 직접 표시변경을 신청할 수 있다(등기선례).","c":"중","v":1},"법무사2019_25-30-5":{"w":"말소되는 등기의 명의인 표시는 말소로 사라지므로 따로 변경등기를 할 실익이 없다. 그래서 변경을 증명하는 정보만 내면 명의인표시 변경등기를 생략할 수 있다(등기명의인표시 변경에 관한 등기예규).","c":"중","v":1},"법무사2020_26-03-1":{"w":"가등기가 회복되면 그 뒤 소유권을 취득한 丙은 본등기 시 소유권을 잃을 수 있으므로 등기상 이해관계 있는 제3자다(부동산등기법 제59조, 판례).","c":"중","v":1},"법무사2020_26-03-2":{"w":"말소회복등기는 부적법하게 말소된 등기를 소급해 되살리는 등기다(부동산등기법 제59조). 당사자가 자발적으로 말소한 것은 부적법 말소가 아니어서 회복등기를 할 수 없다는 것이 판례·등기예규다.","c":"중","v":1},"법무사2020_26-03-4":{"w":"회복등기는 말소된 방식에 맞춘다. 신청으로 말소된 것은 신청으로, 촉탁으로 말소된 것은 촉탁으로, 직권으로 말소된 것은 직권으로 회복한다(말소회복등기에 관한 등기예규).","c":"중","v":1},"법무사2020_26-03-5":{"w":"부동산등기규칙 제118조: 말소된 등기 전부를 회복하면 회복등기를 한 뒤 말소된 등기와 같은 등기를 다시 한다. 순위를 유지하기 위해 종전과 같은 순위번호를 쓴다(등기예규).","c":"중","v":1},"법무사2020_26-12-2":{"w":"경정등기는 권리의 경정이면 부동산등기법 제52조 제5호에 따라 이해관계인이 없거나 승낙이 있으면 부기, 이해관계인이 있는데 승낙이 없으면 같은 조 단서에 따라 주등기로 한다.","c":"상","v":1},"법무사2020_26-12-3":{"w":"명의인표시 경정은 같은 사람의 표시만 바로잡는 것이어서 경정 전후 인격의 동일성이 있어야 한다. 법인 아닌 사단을 법인으로 바꾸는 것은 다른 인격이어서 수리하지 않는다(등기예규).","c":"중","v":1},"법무사2020_26-12-4":{"w":"부동산등기법 제57조: 말소에 대해 등기상 이해관계 있는 제3자가 있으면 그 승낙이 있어야 하며 말소할 때 그 제3자 명의 등기는 등기관이 직권으로 말소한다.","c":"상","v":1},"법무사2020_26-12-5":{"w":"소유권경정으로 지분이 줄어드는 자는 사실상 소유권을 잃는 등기의무자다. 부동산등기규칙 제60조 제1항 제1호에 따라 그 인감증명을 낸다(경정등기에 관한 등기예규).","c":"중","v":1},"법무사2022_28-02-1":{"w":"경정등기는 경정 전후 권리주체에 동일성이 있어야 한다. 甲·乙에서 전혀 다른 丙·丁으로 바꾸는 것은 동일성이 없어 경정으로 할 수 없다(경정등기에 관한 등기예규).","c":"중","v":1},"법무사2022_28-02-2":{"w":"명의인표시 경정은 현재 효력 있는 등기의 명의인에 대해 하는 것이다. 이미 권리를 이전한 종전 명의인이나 사망한 명의인에 대해서는 경정의 실익이 없어 수리하지 않는다(등기예규).","c":"중","v":1},"법무사2022_28-02-4":{"w":"법인 아닌 사단과 법인은 인격이 다르므로 사단을 법인으로 바꾸는 명의인표시 경정은 동일성을 해쳐 수리하지 않는다(경정등기에 관한 등기예규).","c":"중","v":1},"법무사2022_28-02-5":{"w":"경정등기는 등기사항의 착오를 바로잡는 것이지 권리 자체를 바꾸는 것이 아니다. 저당권을 전세권으로 바꾸는 신청은 동일성이 없어 수리하지 않는다(경정등기에 관한 등기예규).","c":"중","v":1},"법무사2022_28-04-1":{"w":"취급지점이 바뀌면 근저당권자 표시가 등기기록과 맞지 않게 된다. 그래서 먼저 명의인표시 변경등기를 해야 채무자 변경 등 근저당권 변경등기를 신청할 수 있다(등기선례).","c":"중","v":1},"법무사2022_28-04-2":{"w":"부동산등기규칙 제122조의 직권 변경은 「주소변경」으로 등기의무자 표시가 맞지 않는 경우에만 한다. 개명 등 다른 사유는 등기명의인이 직접 변경등기를 신청해야 한다.","c":"상","v":1},"법무사2022_28-04-3":{"w":"옛 등기에는 주민등록번호가 없는 경우가 있다. 현재 효력 있는 권리의 명의인은 주민등록번호를 추가로 기록하는 명의인표시 변경등기를 신청할 수 있다(등기예규).","c":"중","v":1},"법무사2022_28-04-5":{"w":"국적 변경은 등기명의인 표시의 변경이다. 등기예규는 시민권증서 등 국적변경 증명정보를 내고 원인은 「국적변경」, 연월일은 새 국적 취득일로 적게 한다.","c":"중","v":1},"법무사2023_29-01-1":{"w":"사해행위취소를 위한 가처분채권자 丙은 다른 사람의 신청으로 乙 명의 등기가 말소되면 자신의 취소·원상회복 이익에 영향을 받는다. 그래서 등기상 이해관계인이다(등기예규).","c":"중","v":1},"법무사2023_29-01-3":{"w":"증여 해제를 원인으로 한 새 이전등기는 말소가 아니어서 이해관계인 승낙이 필요 없다. 압류등기는 그대로 남는다(등기선례).","c":"중","v":1},"법무사2023_29-01-4":{"w":"전세금이 줄면 전세권을 목적으로 하는 근저당권자나 가압류권자의 담보 가치가 줄어든다. 그래서 이들은 전세금 감액 변경등기에 등기상 이해관계인이다(부동산등기법 제52조 제5호).","c":"중","v":1},"법무사2023_29-01-5":{"w":"보존등기가 말소되면 그 소유권을 목적으로 한 근저당권도 함께 효력을 잃는다. 그래서 근저당권자는 등기상 이해관계인이고 그 승낙이 있어야 한다(부동산등기법 제57조).","c":"중","v":1},"법무사2023_29-04-2":{"w":"허무인은 존재하지 않는 사람이어서 그 명의 등기는 무효다. 판결로 말소할 때 명의 경정을 거칠 필요가 없고 원인은 「확정판결」, 연월일은 판결선고일로 적는다(등기예규).","c":"중","v":1},"법무사2023_29-04-3":{"w":"사망자 명의 등기의 의무는 상속인 전원에게 승계된다. 그래서 상속인 전원이 등기의무자로 공동신청하거나 전원을 상대로 말소판결을 받아야 한다(등기예규).","c":"중","v":1},"법무사2023_29-04-4":{"w":"허무인 명의 등기는 실제 신청한 자가 말소의무자다. 국가는 실제 신청한 甲을 상대로 말소판결을 받아야 그 판결로 乙 명의 등기를 말소할 수 있다(판례·등기선례).","c":"중","v":1},"법무사2023_29-04-5":{"w":"판결이 사망자 명의 등기를 상속인을 표상하는 원인무효 등기로 보고 말소를 명했다면 그 판결로 사망자 명의 등기를 말소할 수 있다는 것이 등기선례다.","c":"중","v":1},"법무사2025_31-07-1":{"w":"말소대상 소유권이전등기 전에 설정된 근저당권에 기한 경매라도 그 경매개시결정 등기는 현 소유자 명의 위에 되어 있다. 말소되면 경매절차에 영향을 받으므로 신청채권자는 등기상 이해관계인이다(등기선례).","c":"중","v":1},"법무사2025_31-07-3":{"w":"채권최고액이 증액되면 그 뒤 압류한 처분청의 배당이 줄 수 있다. 그래서 처분청은 근저당권변경등기의 등기상 이해관계인이다(부동산등기법 제52조 제5호, 등기선례).","c":"중","v":1},"법무사2025_31-07-4":{"w":"변론종결 전에 마쳐진 가압류채권자에게는 말소판결 효력이 미치지 않으므로 전세권 말소로 불이익을 받는 등기상 이해관계인이다. 부동산등기법 제57조에 따라 그 승낙이나 대항 재판이 필요하다(등기예규).","c":"중","v":1},"법무사2025_31-07-5":{"w":"일부말소 의미의 경정은 실질이 말소여서 이해관계인 승낙이나 대항 재판 증명정보가 있으면 부기로 하며 없으면 수리하지 않는다(경정등기에 관한 등기예규).","c":"중","v":1},"법무사2025_31-14-1":{"w":"근저당권이 회복되면 현 소유자 丙은 그 부담을 지게 되므로 등기상 이해관계인이다(부동산등기법 제59조, 판례).","c":"중","v":1},"법무사2025_31-14-3":{"w":"회복등기는 말소된 방식에 따른다. 보존등기(부동산등기법 제23조 제2항)나 가등기(제93조)를 명의인이 단독신청으로 말소했으면 그가 단독으로 회복을 신청할 수 있다(등기예규).","c":"중","v":1},"법무사2025_31-14-4":{"w":"판례는 말소등기가 위조 서류로 이루어졌더라도 그 말소가 실체관계에 부합하면 유효하다고 본다. 그래서 회복등기를 청구할 수 없다.","c":"중","v":1},"법무사2025_31-14-5":{"w":"등기관의 착오로 잘못 말소한 것은 직권으로 회복한다(부동산등기법 제32조 유추, 말소회복등기에 관한 등기예규). 이해관계인의 신청은 직권 발동을 촉구하는 의미로 받는다.","c":"중","v":1},"법무사2026_32-20-1":{"w":"경정은 등기사항의 착오를 바로잡는 것이어서 권리 자체를 바꾸는 경정(소유권이전을 저당권설정으로 등)은 동일성이 없어 허용되지 않는다(경정등기에 관한 등기예규).","c":"중","v":1},"법무사2026_32-20-2":{"w":"「국 관리청 OO군」의 권리주체는 국가이고 「OO군」은 지방자치단체여서 인격이 다르다. 명의인표시 경정은 동일성이 있어야 하므로 이런 경정은 허용되지 않는다(등기선례).","c":"중","v":1},"법무사2026_32-20-3":{"w":"일부말소 의미의 경정은 실질이 말소여서 이해관계인 승낙이나 대항 재판이 있으면 부기로 하며 없으면 수리하지 않는다(경정등기에 관한 등기예규).","c":"중","v":1},"법무사2026_32-20-5":{"w":"직권보존등기 후 집합건축물대장이 작성되면 등기와 대장이 맞지 않게 된다. 현재 소유권 명의인인 수탁자 乙은 부동산등기법 제23조 제5항에 따라 신탁목적에 반하지 않는 한 구분건물로 부동산표시 경정등기를 신청할 수 있다(등기선례).","c":"중","v":1},"법무사2016_22-12-1":{"w":"가등기상 권리도 재산권이므로 그 처분을 금지하는 가처분은 등기할 수 있다. 가등기에 의한 본등기를 금지하는 가처분은 등기청구권 행사 자체를 막는 것이어서 허용되지 않는다는 것이 판례·등기예규다.","c":"중","v":1},"법무사2016_22-12-2":{"w":"부동산등기법 제23조 제6항에 따라 명의인표시 변경은 해당 권리의 명의인이 단독신청한다. 법원 촉탁으로 된 가압류등기도 그 명의인이 직접 주소변경 등기를 신청할 수 있다(등기선례).","c":"중","v":1},"법무사2016_22-12-4":{"w":"부동산등기법 제96조는 체납처분 압류등기를 촉탁하는 관공서에게만 상속등기 등을 대위 촉탁할 수 있게 한다. 법원의 처분제한 촉탁에는 그런 규정이 없어 상속등기를 대위 촉탁할 수 없다. 채권자가 대위신청해야 한다(등기예규).","c":"중","v":1},"법무사2016_22-12-5":{"w":"가압류등기에 관한 등기예규는 채권자 전부를 기록하게 하며 선정당사자가 있으면 선정자 목록에 따라 채권자 전부를 채권자로 기록하게 한다.","c":"중","v":1},"법무사2016_22-26-1":{"w":"민사집행법 제94조 제1항: 법원이 경매개시결정을 하면 법원사무관등은 즉시 그 사유를 등기기록에 기입하도록 등기관에게 촉탁해야 한다.","c":"중","v":1},"법무사2016_22-26-2":{"w":"가압류 후 소유권이 넘어가도 가압류채권자는 가압류 당시 소유자를 채무자로 한 집행권원으로 그 부동산을 경매할 수 있다(처분금지효). 그래서 등기의무자를 전 소유자 甲으로 적은 강제경매개시결정 촉탁도 수리한다(등기예규).","c":"중","v":1},"법무사2016_22-26-4":{"w":"경매개시결정 등기에 관한 등기예규는 채권자가 여럿이면 전부를 채권자로 기록하게 하고 「○○○ 외 ○인」처럼 일부만 적지 못하게 한다.","c":"중","v":1},"법무사2016_22-26-5":{"w":"경매개시결정 등기에 관한 등기예규는 촉탁서 등기목적란에 가압류의 본압류 이행이라는 취지가 있으면 등기목적을 「강제경매개시결정(○번 가압류의 본압류로의 이행)」으로 기록하게 한다.","c":"중","v":1},"법무사2016_22-28-2":{"w":"채무자회생법 제26조 제1항: 등기원인 행위나 등기가 부인되면 관리인·파산관재인·개인회생절차 부인권자가 부인의 등기를 신청한다. 법원 판결로 부인이 확정된 것이어서 단독으로 신청한다.","c":"중","v":1},"법무사2016_22-28-3":{"w":"부인등기가 되면 부인된 등기의 명의인은 채무자 재산에 대해 권리가 없는 것으로 다루어진다. 그래서 그를 등기의무자로 하는 신청은 각하한다(채무자회생법 관련 등기예규).","c":"중","v":1},"법무사2016_22-28-4":{"w":"회생절차개시 등기가 된 부동산에는 채무자회생법 제58조 등에 따라 파산선고나 다른 회생절차개시를 할 수 없다. 그 촉탁은 각하한다(채무자회생법 관련 등기예규).","c":"중","v":1},"법무사2016_22-28-5":{"w":"회생계획인가 등기는 회생절차개시 등기를 전제로 한다. 개시 등기가 없는 부동산에 대한 인가 등기 촉탁은 부인등기가 된 경우 말고는 각하한다(채무자회생법 관련 등기예규).","c":"중","v":1},"법무사2017_23-22-1":{"w":"부동산등기법 제90조 제1항: 가등기를 명하는 가처분명령은 부동산 소재지 관할 지방법원이 가등기권리자의 신청으로 가등기 원인사실이 소명되면 한다.","c":"상","v":1},"법무사2017_23-22-2":{"w":"가등기가처분명령으로 된 가등기도 일반 가등기와 효력이 같다. 그래서 근저당권설정청구권 가등기도 부기등기로 이전등기를 할 수 있다(가등기에 관한 등기예규).","c":"중","v":1},"법무사2017_23-22-3":{"w":"가처분명령에 의한 가등기는 부동산등기법 제89조에 따른 가등기권리자의 단독신청이다. 등기필정보 제공(제50조 제2항)은 공동신청 등에 요구되는 것이어서 필요 없다(등기예규).","c":"중","v":1},"법무사2017_23-22-4":{"w":"부동산등기법 제90조 제2항: 가등기가처분명령 신청을 각하한 결정에 대하여는 즉시항고를 할 수 있다. 그 즉시항고에는 비송사건절차법을 준용한다(제3항).","c":"상","v":1},"법무사2017_23-25-1":{"w":"지방세법 제26조 제2항 제1호는 채무자회생법 제26조 제1항에 따른 부인의 등기에 등록면허세를 부과하지 않는다.","c":"상","v":1},"법무사2017_23-25-2":{"w":"회생절차개시 등기 촉탁은 처분제한 등기 촉탁과 같은 성질이어서 미등기부동산이면 부동산등기법 제66조를 따라 직권으로 보존등기를 한 뒤 촉탁된 등기를 한다(채무자회생법 관련 등기예규).","c":"중","v":1},"법무사2017_23-25-3":{"w":"회생절차개시 등기는 다른 처분제한이나 가등기가 먼저 있어도 할 수 있다. 개시결정으로 강제집행 등은 중지되거나 효력을 잃는 관계가 되기 때문이다(채무자회생법 관련 등기예규).","c":"중","v":1},"법무사2017_23-25-4":{"w":"파산관재인의 처분은 법원의 감독 아래 하는 법정 처분이어서 등기의무자인 채무자의 등기필정보를 낼 필요가 없다는 것이 채무자회생법 관련 등기예규다. 대신 법원 허가서 등을 낸다.","c":"중","v":1},"법무사2017_23-28-1":{"w":"가압류의 처분금지 효력 때문에 가압류 뒤 제3취득자가 있어도 가압류채권자는 가압류 당시 소유자를 상대로 강제경매를 할 수 있다. 그래서 가압류 당시 소유명의인이 등기의무자가 된다(등기예규).","c":"중","v":1},"법무사2017_23-28-2":{"w":"임의경매는 담보권 실행이어서 개시결정 뒤 소유권이 바뀌어도 경매절차에 영향이 없다. 개시결정 기입 촉탁 전에 소유자가 바뀌었어도 수리한다(경매 등기에 관한 등기예규).","c":"중","v":1},"법무사2017_23-28-4":{"w":"매각으로 소멸하는 저당권보다 뒤에 된 가등기는 매수인이 인수하지 않는 부담이다(민사집행법 제91조 제3항). 그래서 매각에 따른 말소대상이다(등기예규).","c":"중","v":1},"법무사2017_23-28-5":{"w":"민사집행법 제91조 제3항·제4항과 주택임대차보호법 제3조의5: 주택임차권은 경매로 소멸하는 것이 원칙이지만 보증금이 전액 변제되지 않은 대항력 있는 임차권은 소멸하지 않아 말소대상이 아니다.","c":"중","v":1},"법무사2017_23-29-1":{"w":"「공무원범죄에 관한 몰수 특례법」과 그 등기에 관한 등기예규에 따르면 부동산 몰수보전등기는 검사가 등기목적을 「몰수보전」, 등기권리자를 「국」으로 하여 촉탁한다.","c":"중","v":1},"법무사2017_23-29-3":{"w":"몰수특례법 관련 등기예규는 저당권부채권에 대한 몰수보전명령이 있으면 검사의 신청에 따라 그 명령을 한 법원이 저당권부채권 압류등기 촉탁의 예에 따라 등기를 촉탁하게 한다.","c":"중","v":1},"법무사2017_23-29-4":{"w":"몰수보전은 가처분 뒤에 되었더라도 가처분채권자의 권리를 침해하는 일반 등기와 다르게 취급된다. 등기예규는 가처분권자가 승소해도 몰수보전등기는 직권이나 가처분권자 신청으로 말소할 수 없다고 정한다.","c":"중","v":1},"법무사2017_23-29-5":{"w":"추징보전명령은 가압류와 같은 효력을 가지므로 등기목적은 「가압류」, 원인은 「○○지방법원의 추징보전명령에 기한 검사의 명령」으로 하고 검사의 집행명령 등본을 붙여 검사의 신청으로 법원이 촉탁한다(등기예규).","c":"중","v":1},"법무사2018_24-02-1":{"w":"소유권 외 권리 설정등기청구권을 보전하는 가처분은 소유권에 대한 처분을 제한하는 것이어서 갑구에 기록한다(가처분등기에 관한 등기예규).","c":"중","v":1},"법무사2018_24-02-2":{"w":"부동산등기법 제94조 제1항: 이전등기청구권 보전 가처분 뒤 가처분채권자가 채무자를 상대로 이전등기를 신청하면 가처분 뒤에 된 등기로서 채권자의 권리를 침해하는 등기의 말소를 단독으로 신청할 수 있다.","c":"상","v":1},"법무사2018_24-02-3":{"w":"부동산등기법 제94조 제1항과 부동산등기규칙 제153조: 지상권설정청구권 보전 가처분이면 가처분 뒤 같은 부분에 된 지상권·지역권·전세권·임차권 설정등기처럼 양립할 수 없는 등기의 말소를 단독으로 신청할 수 있다.","c":"중","v":1},"법무사2018_24-02-5":{"w":"부동산등기법 제94조 제2항: 가처분채권자의 신청으로 가처분 뒤 등기를 말소할 때 등기관은 직권으로 그 가처분등기도 말소한다.","c":"상","v":1},"법무사2018_24-27-1":{"w":"가압류등기에 관한 등기예규는 채권자가 선정당사자인 경우에도 선정자 목록에 따라 채권자 전부를 채권자로 기록하게 한다.","c":"중","v":1},"법무사2018_24-27-2":{"w":"가압류등기에 관한 등기예규는 일부 채권자의 해제신청에 따른 촉탁이면 「일부채권자 해제」를 원인으로 변경등기를 하며 청구금액 변경이 함께 있으면 청구금액 변경등기도 하게 한다.","c":"중","v":1},"법무사2018_24-27-4":{"w":"가압류등기 전부에 대한 말소촉탁이면 채권자가 「○○○ 외 ○인」으로 기록되어 있더라도 그 촉탁에 따라 말소할 수 있다(가압류등기에 관한 등기예규).","c":"중","v":1},"법무사2018_24-27-5":{"w":"가압류가 본압류로 이행되어 강제집행이 진행 중이면 가압류 효력은 본집행에 흡수되어 함께 유지된다는 것이 판례다. 그래서 본집행이 유효한 동안 가압류등기만 말소하는 촉탁은 각하한다(등기예규).","c":"중","v":1},"법무사2019_25-15-1":{"w":"채무자회생법 제24조 제1항 제2호·제3호와 제3항: 채무자 재산이나 이사·감사 등 임원 재산에 대한 보전처분의 등기는 법원사무관등이 직권으로 촉탁한다.","c":"중","v":1},"법무사2019_25-15-2":{"w":"채무자회생법 관련 등기예규는 보전처분 등기 촉탁서에 목적을 「보전처분」, 원인을 「○○지방법원의 재산보전처분」, 일자를 결정 연월일로 적고 결정서 등본이나 초본을 붙이게 한다(같은 법 제24조).","c":"중","v":1},"법무사2019_25-15-3":{"w":"보전처분 등기는 다른 처분제한이나 가등기가 먼저 되어 있어도 할 수 있다(채무자회생법 관련 등기예규). 보전처분은 채무자의 처분을 막는 것이어서 기존 등기와 양립한다.","c":"중","v":1},"법무사2019_25-15-4":{"w":"채무자회생법 제24조 제1항 후문 등은 보전처분이 효력을 잃으면 법원사무관등이 그 등기를 촉탁하게 한다. 신청 기각결정으로 효력을 잃으면 촉탁으로 보전처분등기를 말소한다.","c":"중","v":1},"법무사2020_26-08-1":{"w":"형식상 매매예약이더라도 언제든 본등기를 해 주기로 약정했으면 예약완결권 행사가 필요 없다. 이 경우 매매계약서 없이 본등기를 신청할 수 있다는 것이 등기선례다.","c":"중","v":1},"법무사2020_26-08-3":{"w":"부동산등기규칙 제147조 제2항은 가등기 후 본등기 전의 체납처분 압류등기를 바로 말소하지 않고 직권말소대상 통지를 한 뒤 이의가 있으면 그 당부를 판단하게 한다. 압류가 가등기 전 원인에 기한 것일 수 있기 때문이다.","c":"상","v":1},"법무사2020_26-08-4":{"w":"부동산 거래신고 등에 관한 법률 제11조는 소유권 이전이나 대가 있는 지상권 설정 계약(예약 포함)에 허가를 받게 한다. 그래서 소유권이전청구권 가등기와 지료 약정 있는 지상권설정청구권 가등기에 허가서를 붙인다(등기예규).","c":"중","v":1},"법무사2020_26-08-5":{"w":"가등기권자가 다른 원인으로 소유권을 취득해도 그 사이에 제3자 처분제한 등기가 있으면 가등기는 혼동으로 소멸하지 않는다(민법 제191조 제1항 단서). 그래서 그 가등기로 다시 본등기를 할 수 있다(등기선례).","c":"중","v":1},"법무사2021_27-02-2":{"w":"가등기가처분명령에 따른 가등기도 일반 가등기와 효력이 같다. 그래서 근저당권설정청구권 가등기의 이전등기도 할 수 있다(가등기에 관한 등기예규).","c":"중","v":1},"법무사2021_27-02-3":{"w":"가등기가처분명령은 가등기 신청 방법에 관한 것일 뿐 민사집행법상 보전처분이 아니다. 그래서 가등기 말소는 일반 가등기 말소절차로 하고 가처분 이의로 다투지 못한다는 것이 판례다.","c":"중","v":1},"법무사2021_27-02-4":{"w":"부동산등기법 제90조 제1항: 가등기가처분명령은 부동산 소재지 관할 지방법원이 가등기권리자의 신청과 가등기 원인사실 소명이 있으면 한다.","c":"상","v":1},"법무사2021_27-02-5":{"w":"가등기가처분명령에 따른 가등기도 순위보전 효력이 있다. 본등기가 되면 가등기 뒤의 제3자 소유권이전등기는 부동산등기법 제92조 제1항에 따라 직권말소한다.","c":"상","v":1},"법무사2021_27-11-1":{"w":"매각으로 인한 이전등기 촉탁에 관한 등기예규는 매수인이 여럿이면 촉탁서에 송부·교부받을 자로 지정된 자에게 등기필정보통지서를 보내거나 교부하게 한다.","c":"중","v":1},"법무사2021_27-11-2":{"w":"농지 매각에서 농지취득자격증명은 집행법원이 매각허부 결정에서 조사한다(민사집행규칙). 그래서 매각 이전등기 촉탁에 농지취득자격증명을 붙일 필요가 없다(경매 등기에 관한 등기예규).","c":"중","v":1},"법무사2021_27-11-3":{"w":"공유자가 매수인이 되면 자기 지분은 이미 그의 소유여서 이전할 필요가 없다. 그래서 나머지 지분에 대해서만 공유지분이전등기를 촉탁하고 개시결정등기와 인수하지 않는 부담은 말소 촉탁한다(등기예규).","c":"중","v":1},"법무사2021_27-11-5":{"w":"부기등기는 주등기에 종속되므로 주등기가 말소되면 등기관이 직권으로 함께 말소한다. 집행법원은 주등기 말소만 촉탁하면 된다(경매 등기에 관한 등기예규).","c":"중","v":1},"법무사2021_27-28-1":{"w":"부동산등기법 제88조 후문: 청구권이 시기부·정지조건부이거나 그 밖에 장래에 확정될 것인 경우에도 가등기를 할 수 있다.","c":"상","v":1},"법무사2021_27-28-3":{"w":"가등기담보법 제3조·제4조는 청산금 평가액 통지가 도달한 뒤 2개월 청산기간이 지나고 청산금을 지급해야 소유권을 취득하게 한다. 그래서 본등기 신청에 통지 도달 증명과 청산금 지급·공탁 증명을 낸다(담보가등기에 관한 등기예규).","c":"중","v":1},"법무사2021_27-28-4":{"w":"가등기 뒤 소유권이 이전되어도 본등기 의무는 가등기 당시 소유자에게 있다는 것이 판례다. 그래서 본등기의 등기의무자는 가등기 당시 소유자이고 제3취득자 등기는 본등기 후 직권말소한다(등기예규).","c":"중","v":1},"법무사2021_27-28-5":{"w":"판례는 담보가등기 여부를 등기부상 원인(매매예약·대물변제예약)이 아니라 실제로 채권담보 목적인지로 판단한다.","c":"중","v":1},"법무사2022_28-20-1":{"w":"증축·부속건물 신축의 표시변경등기는 소유권 등기명의인이 신청하는 등기다(부동산등기법 제41조). 집행법원은 처분제한 촉탁과 함께 표시변경을 촉탁할 권한이 없으므로 수리하지 않는다(등기선례).","c":"중","v":1},"법무사2022_28-20-3":{"w":"처분제한 촉탁에 따른 직권보존등기는 등기관이 직권으로 하는 것이어서 국민주택채권 매입 의무가 문제되지 않는다. 매입하지 않았다는 이유로 촉탁을 각하할 수 없다(등기선례).","c":"중","v":1},"법무사2022_28-20-4":{"w":"국세징수법상 공매공고 등기는 공매하는 압류재산에 하는 것이어서 압류등기에 부기한다. 납세담보 부동산은 압류 없이 공매하므로 갑구에 주등기로 한다(공매공고 등기에 관한 등기예규).","c":"중","v":1},"법무사2022_28-20-5":{"w":"피상속인과의 원인행위로 생긴 등기청구권은 상속인이 의무를 승계한다. 상속인을 상대로 한 가처분이면 상속관계를 표시해 피상속인 명의 부동산에 촉탁할 수 있고 상속등기를 거치지 않아도 된다(등기예규).","c":"중","v":1},"법무사2022_28-25-1":{"w":"채무자회생법은 개인회생 개시결정이나 변제계획인가결정의 등기 규정을 두지 않는다. 보전처분(제24조 제6항)과 부인등기(제26조 제1항)만 등기할 수 있다.","c":"중","v":1},"법무사2022_28-25-2":{"w":"채무자회생법 관련 등기예규는 파산관재인이 법인 아닌 개인 채무자의 부동산을 임의매각하면 파산관재인의 인감증명법상 인감증명을 내게 한다. 파산법원이 발급한 사용인감 증명은 법인 채무자의 경우에만 쓸 수 있다.","c":"중","v":1},"법무사2022_28-25-4":{"w":"회생절차개시 등기는 먼저 된 가압류·가처분·경매·압류·가등기·파산선고 등기가 있어도 할 수 있다(채무자회생법 관련 등기예규).","c":"중","v":1},"법무사2022_28-25-5":{"w":"회생절차개시 후 강제집행 등이 허용되는지는 집행법원이 판단할 사항이다. 등기관은 형식적 심사만 하므로 회생개시 등기가 있어도 그 촉탁을 수리한다(채무자회생법 관련 등기예규).","c":"중","v":1},"법무사2022_28-26-2":{"w":"가압류등기에 관한 등기예규는 채권자 전부를 기록하게 하고 「○○○ 외 ○인」처럼 일부만 적지 못하게 하며 선정당사자이면 선정자 목록으로 전부를 기록하게 한다.","c":"중","v":1},"법무사2022_28-26-3":{"w":"가압류등기에 관한 등기예규는 일부 채권자 해제 촉탁이면 「일부채권자 해제」를 원인으로 변경등기를 하게 하며 청구금액 변경이 있으면 그 변경등기도 하게 한다.","c":"중","v":1},"법무사2022_28-26-4":{"w":"가압류등기가 법원 촉탁 외의 사유(가등기 본등기에 따른 직권말소 등)로 말소되면 집행법원은 그 사실을 알아야 하므로 등기관이 지체 없이 통지한다(가압류등기에 관한 등기예규).","c":"중","v":1},"법무사2022_28-26-5":{"w":"채권에 대한 가압류는 원칙적으로 등기 대상이 아니지만 소유권이전등기청구권이 가등기되어 있으면 그 가등기에 부기하는 방법으로 가압류를 공시할 수 있다(가압류등기에 관한 등기예규).","c":"중","v":1},"법무사2023_29-13-1":{"w":"공무원범죄 몰수특례법 관련 등기예규에 따라 부동산 몰수보전등기는 검사가 목적 「몰수보전」, 권리자 「국」으로 촉탁한다.","c":"중","v":1},"법무사2023_29-13-2":{"w":"추징보전은 가압류 효력이 있으므로 등기목적은 「가압류」, 원인은 「○○지방법원의 추징보전명령에 기한 검사의 명령」으로 하여 검사의 신청으로 법원이 촉탁한다(등기예규).","c":"중","v":1},"법무사2023_29-13-3":{"w":"저당권부 채권에 대한 몰수보전명령이 있으면 검사의 신청으로 그 명령을 한 법원이 저당권부채권 압류등기 촉탁의 예에 따라 촉탁한다(몰수특례법 관련 등기예규).","c":"중","v":1},"법무사2023_29-13-4":{"w":"몰수특례법 관련 등기예규는 가처분 뒤의 몰수보전등기를 가처분권자가 승소해도 그의 신청으로 말소하지 못하게 한다. 몰수보전은 국가 형벌권 실현을 위한 것이어서 부동산등기법 제94조의 대상으로 보지 않는다.","c":"중","v":1},"법무사2023_29-15-1":{"w":"부동산등기법 제88조: 가등기는 권리의 설정·이전·변경·소멸 청구권을 보전하려고 한다. 부동산표시나 명의인표시 변경은 권리 변동이 아니어서 가등기 대상이 아니다.","c":"상","v":1},"법무사2023_29-15-2":{"w":"가등기보다 먼저 된 가압류는 가등기에 우선하므로 그에 기한 강제경매개시결정등기는 가등기 뒤에 기입되었어도 가등기 권리를 침해하지 않는다. 부동산등기규칙 제147조 제1항 제2호도 이를 직권말소 대상에서 뺀다.","c":"상","v":1},"법무사2023_29-15-4":{"w":"말소되는 가등기의 명의인 표시는 말소로 사라지므로 변경·경정 증명정보만 내면 명의인표시 변경·경정등기를 생략할 수 있다(가등기에 관한 등기예규).","c":"중","v":1},"법무사2023_29-15-5":{"w":"부동산등기규칙 제148조 제2항 제4호: 지상권·전세권·임차권 설정청구권 가등기에 의한 본등기를 해도 가등기 후 본등기 전의 저당권설정등기는 직권말소 대상이 아니다. 용익권과 저당권은 양립하기 때문이다.","c":"상","v":1},"법무사2023_29-26-1":{"w":"부동산등기법 제94조의 단독 말소는 가처분채권자가 가처분채무자를 등기의무자로 이전·말소·설정등기를 신청할 때만 할 수 있다. 가액배상 판결로는 그런 등기를 할 수 없으므로 뒤의 근저당권 말소도 신청할 수 없다(등기선례).","c":"중","v":1},"법무사2023_29-26-2":{"w":"가처분등기는 집행법원의 촉탁으로 된 것이어서 말소도 집행법원의 촉탁으로 한다. 가처분 해제 조정이 있으면 채무자는 그 조서로 집행법원에 해제를 신청해 촉탁을 받아야 한다(등기선례).","c":"중","v":1},"법무사2023_29-26-3":{"w":"1필지 일부에는 분필 전에 독립한 등기를 할 수 없다. 그래서 특정 일부에 대한 가처분이라도 곧바로 분할등기를 할 수 있는 등 특별한 사정이 없으면 토지 전부에 가처분등기를 한다(등기선례).","c":"중","v":1},"법무사2023_29-26-4":{"w":"부동산등기규칙 제153조 제1항은 전세권 등 설정청구권 가처분이면 뒤에 된 같은 부분의 지상권·지역권·전세권·임차권만 말소하게 한다. 저당권은 전세권과 양립하므로 말소하지 않는다.","c":"상","v":1},"법무사2024_30-02-1":{"w":"보전처분 등기는 법원사무관등이 촉탁한다(채무자회생법 제24조). 보전처분은 채무자의 처분만 막는 것이어서 그 뒤 가압류·경매·압류 등의 촉탁도 수리한다(채무자회생법 관련 등기예규).","c":"중","v":1},"법무사2024_30-02-2":{"w":"채무자회생법 제26조 제1항에 따라 부인권자가 부인의 등기를 신청한다. 부인등기 후에는 부인된 등기의 명의인이 권리자로 다루어지지 않으므로 그를 등기의무자로 하는 신청은 각하한다(등기예규).","c":"중","v":1},"법무사2024_30-02-4":{"w":"회생법원이 채무자회생법 제58조 제5항으로 강제집행 등의 취소를 명하면 그 집행 등기 말소는 집행법원이 촉탁해도 무방하다. 등기관은 촉탁 기관을 문제 삼지 않고 수리한다(채무자회생법 관련 등기예규).","c":"중","v":1},"법무사2024_30-02-5":{"w":"회생절차종결 등기는 개시·인가 등기를 전제로 한다. 둘 다 없는 부동산에 대한 종결등기 촉탁은 부인등기가 된 경우 말고는 각하한다(채무자회생법 관련 등기예규).","c":"중","v":1},"법무사2024_30-27-1":{"w":"사인증여는 증여자 사망으로 효력이 생기는 정지조건부 계약이다. 부동산등기법 제88조 후문에 따라 이런 조건부 청구권도 가등기할 수 있다(등기선례). 유증과 달리 계약이어서 생전에도 가능하다.","c":"중","v":1},"법무사2024_30-27-2":{"w":"가등기도 공동신청이 원칙이다(부동산등기법 제23조 제1항). 제89조는 가등기의무자의 승낙이나 가처분명령이 있으면 가등기권리자가 단독으로 신청할 수 있게 한다.","c":"상","v":1},"법무사2024_30-27-3":{"w":"가등기가처분명령은 가등기권리자의 단독신청 근거일 뿐이다(부동산등기법 제89조). 법원이 이를 촉탁하는 규정은 없어 법원의 가등기 촉탁은 각하한다(가등기에 관한 등기예규).","c":"중","v":1},"법무사2024_30-27-5":{"w":"형식상 매매예약 가등기라도 언제든 본등기를 해 주기로 약정했으면 예약완결권 행사 없이 본등기를 신청할 수 있고 매매계약서도 필요 없다는 것이 등기선례다.","c":"중","v":1},"법무사2024_30-30-2":{"w":"가처분 뒤의 경매개시결정 등기도 가처분채권자의 권리를 침해하면 부동산등기법 제94조에 따라 동시에 단독으로 말소를 신청한다. 다만 가처분보다 먼저 된 가압류에 기한 경매는 가처분채권자에게 대항할 수 있어 말소 신청을 수리하지 않는다(등기예규).","c":"중","v":1},"법무사2025_31-20-1":{"w":"경매개시결정보다 먼저 된 가등기라도 그보다 앞선 소멸 담보권이 있으면 그 담보권과 함께 매각으로 소멸한다(민사집행법 제91조 제3항). 그래서 말소대상이다(경매 등기에 관한 등기예규).","c":"중","v":1},"법무사2025_31-20-2":{"w":"가압류 뒤 소유권이 바뀌어도 가압류채권자는 가압류 당시 소유자를 상대로 강제경매를 할 수 있다(처분금지효). 그래서 그를 등기의무자로 적은 촉탁도 수리한다(경매 등기에 관한 등기예규).","c":"중","v":1},"법무사2025_31-20-3":{"w":"대지권이 등기된 구분건물은 전유부분만 따로 이전할 수 없다(부동산등기법 제61조, 집합건물법 제20조). 매각허가에 대지 표시가 없으면 먼저 대지권 변경(말소)등기를 해야 전유부분만 이전등기를 할 수 있다(등기선례).","c":"중","v":1},"법무사2025_31-20-4":{"w":"공유자가 매수인이 되면 자기 지분은 이미 그의 소유다. 그래서 나머지 지분만 이전등기를 촉탁하고 개시결정등기와 인수하지 않는 부담은 말소를 촉탁한다(경매 등기에 관한 등기예규).","c":"중","v":1},"법무사2025_31-30-1":{"w":"지분 가등기 뒤 토지 전부에 설정된 지상권은 가등기된 지분에 대한 본등기와 양립할 수 없다. 지상권은 지분에만 따로 존속할 수 없어 전부를 직권말소한다(가등기에 관한 등기예규).","c":"중","v":1},"법무사2025_31-30-2":{"w":"부동산등기규칙 제148조 제1항 제3호: 지상권설정청구권 가등기에 의한 본등기를 하면 가등기 후 본등기 전에 같은 부분에 마쳐진 전세권설정등기를 직권말소한다.","c":"상","v":1},"법무사2025_31-30-3":{"w":"부동산등기규칙 제148조 제2항 제4호: 임차권설정청구권 가등기에 의한 본등기를 해도 가등기 후 본등기 전의 저당권설정등기는 직권말소하지 않는다.","c":"상","v":1},"법무사2025_31-30-4":{"w":"부동산등기규칙 제148조 제3항: 저당권설정청구권 가등기에 의한 본등기를 해도 가등기 후 본등기 전에 마쳐진 등기는 직권말소 대상이 아니다. 저당권은 순위만 정하면 다른 권리와 양립한다.","c":"상","v":1},"법무사2026_32-19-1":{"w":"상속인은 피상속인의 등기의무를 승계하므로 상속인을 채무자로 한 가처분은 피상속인 명의 부동산에 상속관계를 표시해 촉탁할 수 있다. 상속등기를 거치지 않아도 된다(등기예규).","c":"중","v":1},"법무사2026_32-19-3":{"w":"가등기상 권리의 처분금지 가처분은 등기할 수 있다. 본등기 금지 가처분은 등기청구권 행사를 막는 것이어서 가등기상 권리의 처분제한이 아니므로 수리하지 않는다(판례·등기예규).","c":"중","v":1},"법무사2026_32-19-4":{"w":"일괄촉탁은 등기목적과 원인이 같아야 한다(부동산등기법 제25조 단서). 부동산별로 피보전권리의 채권자가 다르면 원인이 달라 부동산마다 따로 촉탁한다(가처분등기에 관한 등기예규).","c":"중","v":1},"법무사2026_32-19-5":{"w":"부동산등기법 제23조 제6항에 따라 명의인표시 변경은 그 권리의 명의인이 단독신청한다. 법원 촉탁으로 된 가처분등기의 명의인도 직접 신청할 수 있다(등기선례).","c":"중","v":1},"법무사2026_32-25-1":{"w":"처분제한 촉탁에 따른 직권보존등기(부동산등기법 제66조 제1항)는 종중이 신청하는 것이 아니어서 총유물 관리·처분이 아니다. 그래서 정관·대표자 증명·총회결의서 등 부동산등기규칙 제48조의 첨부정보가 필요 없다(등기선례).","c":"중","v":1},"법무사2026_32-25-2":{"w":"본집행 진행 중 가압류등기만 말소하는 촉탁은 각하사유지만 잘못 말소되었더라도 가압류 효력은 본압류에 이어져 있다. 그래서 그 뒤 매각에 따른 후순위 등기 말소촉탁은 수리할 수 있다(등기선례).","c":"중","v":1},"법무사2026_32-25-3":{"w":"등기이전청구권 가압류는 그 청구권이 가등기된 때만 부기등기로 할 수 있다(가압류등기에 관한 등기예규). 가처분의 피보전권리는 가등기가 아니어서 「가처분소유권이전등기청구권가압류」는 등기할 수 없다.","c":"중","v":1},"법무사2026_32-25-4":{"w":"상속등기 전 부동산은 피상속인 명의여서 상속인 상대 가압류 촉탁은 등기의무자 표시가 맞지 않는다(부동산등기법 제29조 제7호). 그래서 채권자가 먼저 대위 상속등기를 한다(등기예규).","c":"중","v":1},"법무사2016_22-10-1":{"w":"부동산등기규칙 제104조 제3항: 공용부분이라는 뜻의 등기는 그 등기기록 표제부에 공용부분이라는 뜻을 기록하는 방법으로 한다.","c":"상","v":1},"법무사2016_22-10-2":{"w":"부동산등기법 제47조 제1항: 규약상 공용부분이라는 뜻의 등기는 그 건물의 소유권 등기명의인이 신청한다. 상대방이 없는 등기여서 단독으로 신청한다.","c":"상","v":1},"법무사2016_22-10-3":{"w":"집합건물법 제10조 제1항은 공용부분을 구분소유자 전원의 공유로 하며 제13조 제1항은 공용부분 지분이 전유부분의 처분에 따르게 한다.","c":"중","v":1},"법무사2016_22-10-5":{"w":"부동산등기규칙 제104조 제3항: 공용부분이라는 뜻의 등기를 할 때 표제부에 그 뜻을 기록하고 각 구의 소유권과 그 밖의 권리에 관한 등기를 말소하는 표시를 한다.","c":"상","v":1},"법무사2016_22-18-1":{"w":"부동산등기법 제35조(토지)와 제41조 제1항(건물): 분할·합병 등이 있으면 소유권 등기명의인은 그 사실이 있는 때부터 1개월 이내에 등기를 신청해야 한다.","c":"상","v":1},"법무사2016_22-18-2":{"w":"부동산등기규칙 제96조 제1항: 甲 건물의 부속건물을 분할해 乙 건물로 하면 乙 건물 등기기록을 개설하고 표제부에 건물 표시와 甲 건물 등기기록에서 옮겨 기록한 뜻을 적는다.","c":"상","v":1},"법무사2016_22-18-3":{"w":"부동산등기규칙 제96조 제3항은 건물분할에 토지분필 규정인 제76조를 준용한다. 그래서 乙 건물 등기기록 해당 구에 甲 건물의 소유권과 그 밖의 권리 등기를 전사한다.","c":"상","v":1},"법무사2016_22-18-5":{"w":"공간정보의 구축 및 관리 등에 관한 법률 제89조 제1항: 지적소관청은 토지 분할 등으로 토지 표시 변경등기가 필요하면 지체 없이 관할 등기관서에 그 등기를 촉탁한다.","c":"중","v":1},"법무사2016_22-27-1":{"w":"대지권 등기에 관한 등기예규는 1동 건물 대지 중 일부 토지만 대지권의 목적이면 대지권 목적 토지 표시에 그 토지만 기록하게 한다(부동산등기법 제40조 제3항).","c":"중","v":1},"법무사2016_22-27-2":{"w":"구분소유자마다 대지사용권이 미치는 토지가 다르면 각자 그 토지만 목적으로 대지권등기를 한다. 1동 건물 표제부의 대지권 목적 토지 표시에는 토지 전부를 적는다(대지권 등기에 관한 등기예규).","c":"중","v":1},"법무사2016_22-27-3":{"w":"부동산등기법 제40조 제4항: 대지권등기를 하면 등기관은 직권으로 대지권 목적 토지의 등기기록에 소유권·지상권·전세권·임차권이 대지권이라는 뜻을 기록한다.","c":"상","v":1},"법무사2016_22-27-5":{"w":"규약으로 대지권이 생기면 1동 전체의 대지권 표시가 바뀌므로 구분소유자 전원이 신청하거나 일부가 다른 소유자를 대위해 일괄 신청한다(부동산등기법 제41조 제3항, 대지권 등기에 관한 등기예규).","c":"중","v":1},"법무사2017_23-21-2":{"w":"부동산등기법 제35조: 토지의 분할·합병이 있거나 표제부 등기사항에 변경이 있으면 소유권 등기명의인은 그 사실이 있는 때부터 1개월 이내에 등기를 신청해야 한다.","c":"상","v":1},"법무사2017_23-21-3":{"w":"부동산등기법 제37조 제1항 제2호는 모든 토지에 등기원인·연월일·접수번호가 동일한 저당권 등기가 있는 경우에만 합필을 허용한다. 추가설정으로 접수번호가 다르면 합필할 수 없다.","c":"상","v":1},"법무사2017_23-21-4":{"w":"부동산등기법 제40조 제2항: 구분건물이면 1동 건물 표제부에 소재·지번·건물명칭·번호를, 전유부분 표제부에 건물번호를 기록한다.","c":"상","v":1},"법무사2017_23-21-5":{"w":"부동산등기규칙 제97조 제1항: 구분건물이 아닌 甲 건물을 구분해 甲·乙 건물로 하면 구분 후의 甲·乙 건물 모두에 등기기록을 새로 개설하고 종전 등기기록은 폐쇄한다(제2항).","c":"상","v":1},"법무사2017_23-26-1":{"w":"대지사용권은 구분소유자가 전유부분을 소유하기 위해 대지에 대해 가지는 권리다(집합건물법 제2조 제6호). 부동산등기법 제40조 제4항도 소유권 외에 지상권·전세권·임차권을 대지권으로 예정한다.","c":"상","v":1},"법무사2017_23-26-2":{"w":"집합건물법 제21조 제1항과 제12조: 구분소유자가 여러 전유부분을 가지면 규약으로 달리 정하지 않는 한 각 전유부분에 따른 대지사용권 비율은 전유부분 면적 비율에 따른다.","c":"중","v":1},"법무사2017_23-26-3":{"w":"부동산등기법 제40조 제4항: 건물 등기기록에 대지권을 등기하면 등기관이 직권으로 대지권 목적 토지 등기기록에 어느 권리가 대지권이라는 뜻을 기록한다.","c":"상","v":1},"법무사2017_23-26-4":{"w":"부동산등기규칙 제90조 제2항(제1항 준용): 대지권이라는 뜻의 등기 뒤 토지 등기기록에만 새 등기를 하면 전유부분 표제부에 토지 등기기록에 별도 등기가 있다는 뜻을 기록한다.","c":"상","v":1},"법무사2018_24-20-3":{"w":"부동산등기법 제37조 제1항은 소유권·지상권·전세권·임차권·승역지 지역권, 동일한 저당권, 동일한 신탁등기만 합필 제한의 예외로 둔다. 가압류·가처분은 원인과 접수번호가 같아도 예외가 아니어서 합필할 수 없다.","c":"상","v":1},"법무사2019_25-03-1":{"w":"공간정보의 구축 및 관리 등에 관한 법률 제80조 제3항과 시행령 제66조는 소유자나 지분이 다른 토지의 합병을 허용하지 않는다. 공유자는 같아도 지분 비율이 다르면 합병할 수 없다.","c":"중","v":1},"법무사2019_25-03-2":{"w":"부동산등기법 제38조 제1항: 토지합병절차를 마친 뒤 합필등기 전에 어느 토지에 소유권이전등기가 되었어도 이해관계인의 승낙이 있으면 명의인들이 합필 후 토지를 공유로 하는 합필등기를 신청할 수 있다.","c":"상","v":1},"법무사2019_25-03-4":{"w":"부동산등기법 제37조 제1항 제2호는 저당권 등기의 원인·연월일·접수번호가 모두 같아야 합필을 허용한다. 추가설정 저당권은 접수번호가 달라 합필할 수 없다.","c":"상","v":1},"법무사2019_25-03-5":{"w":"합필 전 1필지에 대한 저당권이 합필 후 특정 일부에 존속하는 것으로 등기되었으면 경매 대상을 특정해야 한다. 그래서 먼저 그 부분을 다시 분필한 뒤 경매개시결정 기입등기를 한다(등기선례).","c":"중","v":1},"법무사2020_26-05-2":{"w":"각 구분소유자가 자기 토지에 대해서만 대지사용권을 가지면 그 토지만을 자기 전유부분의 대지권으로 등기할 수 있다(대지권 등기에 관한 등기예규·선례).","c":"중","v":1},"법무사2020_26-05-3":{"w":"대지권 등기 후에도 토지 소유권 귀속 분쟁이 있으면 대지권 표시 경정 없이 전유부분 소유자의 토지 지분에 대해 처분금지가처분을 등기할 수 있다는 것이 등기예규다(부동산등기법 제61조 제4항 단서 취지).","c":"중","v":1},"법무사2020_26-05-4":{"w":"저당권은 부동산과 지상권·전세권만 목적으로 할 수 있어(민법 제356조, 제371조) 토지임차권 대지권은 저당 목적이 될 수 없다. 그래서 건물만 저당권을 설정하고 건물만에 관한 것이라는 뜻을 부기한다(부동산등기규칙 제92조 참조, 등기예규).","c":"중","v":1},"법무사2020_26-05-5":{"w":"대지권은 법정대지나 규약상 대지에 대한 대지사용권이면 되고(집합건물법 제2조 제5호·제6호, 제4조) 지목이 「대」일 필요는 없다. 잡종지도 대지권 목적이 될 수 있다(등기선례).","c":"중","v":1},"법무사2020_26-29-2":{"w":"건물이 멸실하면 그 위의 권리도 소멸한다. 부동산등기법 제45조는 제3자 승낙 대신 이의 진술 통지 절차를 두고 있어 신청에 승낙서를 붙일 필요가 없다.","c":"중","v":1},"법무사2020_26-29-3":{"w":"부동산등기법 제43조 제2항: 건물 소유권 등기명의인이 1개월 이내에 멸실등기를 신청하지 않으면 건물대지의 소유자가 대위해 신청할 수 있다.","c":"상","v":1},"법무사2020_26-29-4":{"w":"멸실등기는 등기기록의 건물과 실제 멸실된 건물이 같기만 하면 된다. 증축 부분 미등기로 면적이 조금 달라도 동일성이 인정되면 표시변경 없이 곧바로 멸실등기를 할 수 있다(등기선례).","c":"중","v":1},"법무사2020_26-29-5":{"w":"부동산등기법 제44조 제1항: 존재하지 않는 건물에 대한 등기가 있으면 소유권 등기명의인은 지체 없이 멸실등기를 신청해야 한다.","c":"상","v":1},"법무사2021_27-22-1":{"w":"부동산등기법 제36조 제1항: 지적소관청으로부터 공간정보관리법 제88조 제3항의 불일치 통지를 받고 제35조의 1개월 안에 등기명의인의 신청이 없으면 등기관은 통지 내용대로 직권으로 변경등기를 한다.","c":"상","v":1},"법무사2021_27-22-2":{"w":"부동산등기법 제37조 제1항 제2호는 합필하려는 모든 토지에 같은 저당권 등기가 있을 때만 합필을 허용한다. 한쪽은 토지 전부, 다른 쪽은 일부 지분이 목적이면 저당권 범위가 달라 합필할 수 없다(등기선례).","c":"중","v":1},"법무사2021_27-22-4":{"w":"부동산등기규칙 제79조 제1항: 甲 토지를 乙 토지에 합병하면 乙 토지 표제부에 합병 후 표시와 甲 토지에서 옮겨 기록한 뜻을 적고 종전 표시는 말소하는 표시를 한다.","c":"상","v":1},"법무사2021_27-22-5":{"w":"부동산등기규칙 제73조: 토지 표시변경등기는 새 표시를 주등기로 기록하고 종전 표시에 관한 등기를 말소하는 표시를 한다. 표제부에는 부기등기가 없다.","c":"중","v":1},"법무사2021_27-25-1":{"w":"전유부분 구획을 세로에서 가로로 바꾸면 위치와 범위가 전혀 달라져 면적이 같아도 종전 건물과 동일성이 없다. 그래서 표시변경등기로 할 수 없다(등기선례).","c":"중","v":1},"법무사2021_27-25-2":{"w":"부동산등기법 제31조는 행정구역이나 그 명칭이 바뀌면 등기기록에도 변경등기가 있는 것으로 본다. 부동산등기규칙 제54조는 등기관이 직권으로 표시변경등기를 하게 한다.","c":"중","v":1},"법무사2021_27-25-3":{"w":"부동산등기법 제35조: 토지의 분할·합병이 있으면 소유권 등기명의인은 그 사실이 있는 때부터 1개월 이내에 등기를 신청해야 한다.","c":"상","v":1},"법무사2021_27-25-5":{"w":"부동산등기법 제46조 제1항: 구분건물 일부만 보존등기를 신청하면 나머지 구분건물의 표시등기를 동시에 신청해야 한다.","c":"상","v":1},"법무사2022_28-12-1":{"w":"부동산등기규칙 제103조 제1항: 멸실등기는 표제부에 멸실 뜻과 원인(또는 부존재)을 적고 표제부 등기를 말소 표시한 뒤 등기기록을 폐쇄한다. 구분건물은 1동의 다른 전유부분과 같은 등기기록이어서 폐쇄하지 않는다.","c":"상","v":1},"법무사2022_28-12-3":{"w":"채권자는 민법 제404조에 따라 채무자의 등기신청권을 대위할 수 있다(부동산등기법 제28조). 멸실등기도 대위원인 증명정보와 건축물대장 등 멸실 증명정보(부동산등기규칙 제102조)로 대위신청할 수 있다.","c":"중","v":1},"법무사2022_28-12-4":{"w":"부동산등기법 제43조 제3항: 구분건물이 속한 1동 전부가 멸실되면 구분건물 소유권 등기명의인은 다른 구분건물 명의인을 대위해 1동 전부의 멸실등기를 신청할 수 있다.","c":"상","v":1},"법무사2022_28-12-5":{"w":"부동산등기법 제44조 제2항은 존재하지 않는 건물에 제43조 제2항(대지 소유자의 대위)을 준용한다. 다만 제44조 제1항은 「지체 없이」 신청하게 할 뿐 1개월 기간이 없으므로 대지 소유자는 기간 경과를 기다리지 않고 대위신청할 수 있다(등기선례).","c":"중","v":1},"법무사2022_28-24-1":{"w":"부동산등기법 제40조 제4항: 대지권등기를 하면 등기관이 직권으로 대지권 목적 토지 등기기록에 소유권·지상권·전세권·임차권이 대지권이라는 뜻을 기록한다.","c":"상","v":1},"법무사2022_28-24-2":{"w":"부동산등기법 제41조 제3항: 구분건물의 대지권에 변경이나 소멸이 있으면 구분건물 소유권 명의인은 같은 1동의 다른 구분건물 명의인을 대위해 그 등기를 신청할 수 있다.","c":"상","v":1},"법무사2022_28-24-3":{"w":"부동산등기규칙 제90조 제1항: 대지권이라는 뜻의 등기를 한 토지 등기기록에 소유권보존·이전 외의 소유권 등기나 소유권 외 권리 등기가 있으면 전유부분 표제부에 토지 등기기록에 별도 등기가 있다는 뜻을 기록한다.","c":"상","v":1},"법무사2022_28-24-4":{"w":"부동산등기법 제60조 제3항: 분양자와 현 구분건물 소유자의 대지사용권 이전등기(제1항·제2항)는 대지권에 관한 등기와 동시에 신청해야 한다.","c":"상","v":1},"법무사2023_29-09-2":{"w":"부동산등기규칙 제104조 제3항: 공용부분이라는 뜻의 등기는 표제부에 그 뜻을 기록하고 각 구의 소유권과 그 밖의 권리 등기를 말소하는 표시를 한다.","c":"상","v":1},"법무사2023_29-09-3":{"w":"부동산등기법 제47조 제1항 후문과 부동산등기규칙 제104조 제1항: 공용부분인 건물에 소유권 외 권리 등기가 있으면 그 명의인의 승낙이나 대항 재판을 증명하는 정보를 낸다.","c":"상","v":1},"법무사2023_29-09-4":{"w":"집합건물법 제13조: 공유자의 공용부분 지분은 전유부분과 분리해 처분할 수 없으며(제2항) 공용부분에 관한 물권 득실변경은 등기가 필요 없다(제3항).","c":"중","v":1},"법무사2023_29-09-5":{"w":"부동산등기법 제47조 제2항: 공용부분이라는 뜻을 정한 규약을 폐지하면 공용부분의 취득자는 지체 없이 소유권보존등기를 신청해야 한다.","c":"상","v":1},"법무사2024_30-06-1":{"w":"부동산등기법 제42조 제1항은 건물합병에 제37조와 같은 제한을 두되 모든 건물에 원인·연월일·접수번호가 같은 저당권이 있으면 합병을 허용한다. 공시에 혼란이 없으므로 저당권자 승낙도 필요 없다(등기예규).","c":"중","v":1},"법무사2024_30-06-3":{"w":"부동산등기법 제43조 제2항: 멸실 건물 소유권 명의인이 1개월 이내에 멸실등기를 신청하지 않으면 건물대지 소유자가 대위해 신청할 수 있다.","c":"상","v":1},"법무사2024_30-06-4":{"w":"부동산등기법 제45조 제1항 단서: 건축물대장에 멸실 뜻이 기록되어 있으면 소유권 외 권리 명의인에 대한 이의진술 통지 없이 멸실등기를 한다. 승낙 증명정보도 필요 없다.","c":"상","v":1},"법무사2024_30-06-5":{"w":"대장과 등기의 건물 표시를 맞추는 표시변경등기는 소유권 명의인이 단독으로 신청한다(부동산등기법 제23조 제5항, 제41조). 소유자가 같고 합병 제한사유가 없으면 이전등기 뒤라도 표시변경을 신청할 수 있다(등기선례).","c":"중","v":1},"법무사2025_31-04-1":{"w":"대지권은 전유부분과 분리해 처분할 수 없으므로(집합건물법 제20조) 일부를 넘기려면 규약으로 그 부분을 대지권이 아닌 권리로 한 뒤 대지권 변경등기를 한 다음 분리된 권리를 지분이전등기한다(대지권 등기에 관한 등기예규).","c":"중","v":1},"법무사2025_31-04-3":{"w":"대지권 비율은 규약이나 등기된 비율에 따르므로 공용부분 일부가 전유부분에 편입되어 면적이 늘어도 비율은 그대로다. 그래서 규약 없이 집합건축물대장만으로 면적 표시변경등기를 신청할 수 있다(등기선례).","c":"중","v":1},"법무사2025_31-04-4":{"w":"건물이 없는 쪽으로 분할된 토지는 법정대지가 아니게 되어 간주규약상 대지도 아니게 된다. 그 토지가 수용되면 규약 폐지 증명 없이 대지권 표시변경등기를 신청할 수 있다(등기선례).","c":"중","v":1},"법무사2025_31-04-5":{"w":"토지임차권은 저당권의 목적이 될 수 없으므로(민법 제356조, 제371조) 건물과 공동저당으로 할 수 없다. 건물만 저당권을 설정하고 건물만에 관한 것이라는 뜻을 부기한다(대지권 등기에 관한 등기예규).","c":"중","v":1},"법무사2025_31-19-1":{"w":"부동산등기법 제46조 제1항·제2항: 구분건물 일부만 보존등기를 신청하면 나머지 구분건물의 표시등기를 동시에 신청해야 하며 다른 구분건물 소유자를 대위할 수 있다.","c":"상","v":1},"법무사2025_31-19-2":{"w":"부동산등기법 제41조 제3항: 대지권의 변경이나 소멸이 있으면 구분건물 소유권 명의인은 같은 1동의 다른 구분건물 명의인을 대위해 그 등기를 신청할 수 있다.","c":"상","v":1},"법무사2025_31-19-4":{"w":"부동산등기법 제40조 제4항은 대지권이라는 뜻의 등기를 등기관이 직권으로 하게 한다. 직권으로 한 등기여서 그 경정도 등기관이 직권으로 한다(대지권 등기에 관한 등기예규).","c":"중","v":1},"법무사2025_31-19-5":{"w":"부동산등기법 제46조 제3항: 구분건물이 아닌 건물에 접속해 구분건물을 신축하면 신축건물 보존등기 때 기존 건물을 구분건물로 바꾸는 표시변경등기를 동시에 신청한다.","c":"상","v":1},"법무사2025_31-28-1":{"w":"토지 분할은 지적공부에 등록해야 효력이 생긴다. 대장상 분할이 없는데 분필등기를 했으면 무효이고 등기와 대장을 맞추기 위해 소유자가 신청착오를 원인으로 분필등기 말소를 신청할 수 있다(등기선례).","c":"중","v":1},"법무사2026_32-07-1":{"w":"집합건물법 제2조 제6호는 대지사용권을 구분소유자가 전유부분을 소유하려고 건물 대지에 대해 가지는 권리로 정의한다. 부동산등기법 제40조 제3항은 그중 건물과 분리해 처분할 수 없는 것을 대지권이라 한다(집합건물법 제20조 제2항 단서의 규약이 없는 것).","c":"상","v":1},"법무사2026_32-07-2":{"w":"판례는 대지사용권이 반드시 등기된 권리일 필요가 없다고 본다. 매매계약으로 대지를 점유·사용할 권리를 가진 경우에도 대지사용권이 된다.","c":"중","v":1},"법무사2026_32-07-3":{"w":"대지권은 전유부분과 일체로 처분되는 대지사용권이면 된다. 대지 소유권에 지상권설정등기나 신탁등기가 있어도 소유권 자체는 대지권이 될 수 있다(대지권 등기에 관한 등기예규·선례).","c":"중","v":1},"법무사2026_32-07-5":{"w":"판례는 분리처분 규약이 없으면 대지사용권이 전유부분의 종된 권리여서 전유부분에 대한 가압류 효력이 대지사용권에도 미친다고 본다. 그래서 경매 매수인은 전유부분과 함께 대지사용권을 취득한다(집합건물법 제20조).","c":"중","v":1},"법무사2016_22-22-1":{"w":"재신탁(신탁법 제3조 제5항)은 신탁행위로 달리 정하지 않았으면 수익자의 동의를 받아야 한다. 조합원별로 따로 맺은 신탁이어서 각 신탁의 수익자 전원 동의서를 내야 하고 수익자집회 결의로 갈음할 수 없다는 것이 신탁등기에 관한 등기예규다.","c":"중","v":1},"법무사2016_22-22-2":{"w":"부동산등기규칙 제139조 제1항: 신탁등기는 그 신탁으로 인한 권리의 이전·보존·설정등기 신청과 함께 1건의 신청정보로 일괄해서 한다.","c":"상","v":1},"법무사2016_22-22-4":{"w":"자본시장법 제8조 제7항·제11조는 인가를 받지 않은 자의 신탁업 영위를 금지한다. 신탁에 관한 등기예규는 신탁업 인가를 받은 신탁회사가 아닌 영리회사를 수탁자로 하는 신탁등기를 수리하지 않는다.","c":"중","v":1},"법무사2016_22-22-5":{"w":"신탁법 제27조로 신탁재산이 된 부동산의 이전등기와 신탁등기를 일괄신청하면(부동산등기규칙 제139조 제2항) 이전등기의 명의인은 수탁자를 「소유자」나 「공유자」로 표시하고 공유이면 지분도 기록한다(신탁등기에 관한 등기예규).","c":"중","v":1},"법무사2017_23-01-1":{"w":"외국법인도 권리능력이 있어 등기당사자가 될 수 있다. 국내 사무소 등기가 없으면 부동산등기법 제49조 제1항 제3호에 따라 시장·군수·구청장이 부여한 등록번호 증명서와 그 법인의 존재를 인정할 서면을 내고 신청한다(등기예규).","c":"중","v":1},"법무사2017_23-01-2":{"w":"각자대표이면 대표이사 각자가 회사를 대표하므로(상법 제389조) 대표이사 A가 체결한 계약에 따른 등기를 대표이사 B가 신청해도 된다(등기선례).","c":"중","v":1},"법무사2017_23-01-3":{"w":"청산사무가 남아 있으면 청산법인은 등기기록이 폐쇄되어도 존속한다. 등기권리자로 신청하려면 폐쇄된 법인 등기기록을 부활해 청산인 등기가 된 등기사항증명서로 청산인 자격을 증명한다(청산법인 등기신청에 관한 등기예규).","c":"중","v":1},"법무사2017_23-01-5":{"w":"청산인 등기 없이 법인 등기기록이 폐쇄되었으면 청산인 자격을 증명할 길이 없다. 그래서 등기기록을 부활해 청산인 등기를 한 뒤 그 증명서를 내고 인감증명은 법인인감인 청산인 인감으로 낸다(청산법인 등기신청에 관한 등기예규).","c":"중","v":1},"법무사2017_23-15-2":{"w":"담보권신탁에서 피담보채권이 이전되면 신탁원부의 수익자 등 기록이 바뀐다. 그래서 수탁자가 신탁원부 기록의 변경등기를 신청한다(부동산등기법 제86조, 신탁등기에 관한 등기예규).","c":"중","v":1},"법무사2017_23-15-3":{"w":"신탁법 제27조에 따라 신탁재산의 처분 등으로 수탁자가 얻은 재산은 신탁재산이 된다. 신탁등기에 관한 등기예규는 이 경우 등기목적을 「소유권이전 및 신탁재산처분에 의한 신탁」으로 적게 한다.","c":"중","v":1},"법무사2017_23-15-4":{"w":"부동산등기법 제87조 제1항·제2항은 신탁재산 처분이나 신탁 종료로 권리가 이전되면 신탁등기 말소를 그 이전등기와 동시에 신청하게 한다. 등기예규는 이를 1건의 신청정보로 일괄신청하게 한다.","c":"중","v":1},"법무사2017_23-15-5":{"w":"부동산등기법 제84조의2 제2호 가목: 신탁법 제34조 제2항에 따라 신탁재산을 고유재산에 귀속시키는 것이 허용되면 수탁자가 단독으로 권리변경등기를 신청할 수 있다. 신탁행위로 허용한 사실을 증명하는 정보를 낸다(등기예규).","c":"중","v":1},"법무사2018_24-11-1":{"w":"재단법인 기본재산 처분에 관한 등기예규는 매매·증여·교환·신탁해지·공유물분할 등 기본재산인 부동산의 소유권을 양도하는 모든 경우를 처분으로 보고 주무관청 허가서를 요구한다.","c":"중","v":1},"법무사2018_24-11-2":{"w":"재단법인의 기본재산은 정관 기재사항이어서(민법 제43조, 제40조) 그 처분은 정관변경을 수반하고 정관변경은 주무관청 허가가 있어야 효력이 생긴다(제42조 제2항, 제45조 제3항). 그래서 그 허가서를 첨부한다(판례·등기예규).","c":"중","v":1},"법무사2018_24-11-3":{"w":"기본재산 처분 이전등기에는 주무관청의 처분 허가서만 첨부하면 되고 정관이나 이사회 회의록은 필요 없다는 것이 등기예규다.","c":"중","v":1},"법무사2018_24-11-5":{"w":"보통재산 처분은 정관변경이 아니어서 주무관청 허가가 필요 없다. 다만 기본재산이 아님을 증명해야 하므로 정관을 첨부한다(재단법인 기본재산 처분에 관한 등기예규).","c":"중","v":1},"법무사2018_24-19-1":{"w":"2순위 이하 상속인이 상속하려면 1순위인 직계비속이 없어야 한다. 입양된 자녀도 직계비속이므로 피상속인의 입양관계증명서를 내 양자가 없음을 확인한다(상속등기에 관한 등기예규).","c":"중","v":1},"법무사2018_24-19-2":{"w":"진정명의회복 판결 이유에서 상속 관계가 이미 확정되었으므로 판결로 상속이 증명된다. 그래서 별도 상속증명서면이 필요 없다는 것이 등기선례다.","c":"중","v":1},"법무사2018_24-19-3":{"w":"협의분할서상 주소와 인감증명서 주소가 다르면 동일인임을 확인해야 한다. 실무는 주민등록표 등·초본을 내게 한다(상속등기에 관한 등기예규).","c":"중","v":1},"법무사2018_24-19-5":{"w":"주소증명정보(부동산등기규칙 제46조 제1항 제6호)를 얻을 수 없는 사정이 소명되면 제적부상 본적지나 가족관계등록부상 등록기준지를 주소로 하여 상속등기를 신청할 수 있다는 것이 등기예규다.","c":"중","v":1},"법무사2018_24-30-1":{"w":"판례는 규약에 따른 의사결정·집행기관을 갖추고 다수결로 운영되며 구성원 변동과 관계없이 단체가 존속하면 법인 아닌 사단으로 본다. 그런 단체는 부동산등기법 제26조에 따라 자기 명의로 등기할 수 있다.","c":"중","v":1},"법무사2019_25-20-2":{"w":"사립학교법 제28조 제2항과 시행령 제12조는 교지·교사·체육장 등 학교교육에 직접 쓰이는 재산을 매도하거나 담보로 제공할 수 없게 한다. 관할청 허가로도 풀 수 없는 절대적 금지다.","c":"중","v":1},"법무사2019_25-20-3":{"w":"사립학교법 제28조·제51조의 제한은 학교법인과 사립학교경영자의 재산에 적용된다. 유치원 건물이라도 소유자가 사립학교경영자가 아니면 허가 없이 매도·담보 제공할 수 있다(등기선례).","c":"중","v":1},"법무사2019_25-20-4":{"w":"학교법인 명의 신탁재산의 신탁해지 이전등기도 학교법인 재산의 처분에 해당한다. 사립학교법 제28조 제1항에 따라 관할청 허가 증명정보를 낸다(등기선례).","c":"중","v":1},"법무사2019_25-20-5":{"w":"판례는 사립학교경영자가 교지·교사로 쓰려고 출연한 부동산은 개인 명의로 남아 있어도 사립학교법 제28조 제2항·제51조 취지상 강제집행 대상이 되지 않는다고 본다.","c":"중","v":1},"법무사2019_25-23-1":{"w":"신탁등기에 관한 등기예규는 수탁자를 등기의무자로 하는 신청이 신탁목적에 맞는지 심사하게 한다. 신탁원부는 등기기록의 일부여서(부동산등기법 제81조 제3항) 그 목적에 반하는 신청은 각하한다.","c":"중","v":1},"법무사2019_25-23-3":{"w":"수탁자는 신탁재산의 소유명의인이다. 그래서 수탁자를 등기의무자로 하는 처분제한·강제경매·임의경매 촉탁은 수리한다(신탁등기에 관한 등기예규). 신탁법 제22조 위반 여부는 이의 등으로 다툰다.","c":"중","v":1},"법무사2019_25-23-4":{"w":"신탁법 제22조 제1항 단서는 신탁 전의 원인으로 생긴 권리에 기한 강제집행을 허용한다. 그래서 신탁 전 담보물권이나 가압류에 기한 경매 촉탁은 위탁자를 등기의무자로 해도 수리한다(신탁등기에 관한 등기예규).","c":"중","v":1},"법무사2019_25-23-5":{"w":"신탁등기된 토지를 분필하면 분필된 토지도 같은 신탁재산이다. 그래서 등기관은 분필 전 신탁원부와 같은 내용의 신탁원부를 만든다(신탁등기에 관한 등기예규).","c":"중","v":1},"법무사2019_25-25-2":{"w":"친권자와 여러 미성년 자녀 사이의 협의분할은 민법 제921조의 이해상반행위다. 판례는 미성년자 각자마다 특별대리인을 선임해야 한다고 본다.","c":"중","v":1},"법무사2019_25-25-3":{"w":"협의분할 상속등기 뒤 재협의분할을 하면 경정등기를 하되 원인은 「협의분할로 인한 상속」, 원인일자는 재협의분할일로 적는다(상속등기에 관한 등기예규).","c":"중","v":1},"법무사2019_25-25-4":{"w":"상속등기 전에 공동상속인 1인이 사망하면 그 상속인이 그 지위를 승계한다. 그래서 나머지 상속인과 사망자의 상속인들이 피상속인 재산에 대해 협의분할을 할 수 있다(등기예규).","c":"중","v":1},"법무사2019_25-25-5":{"w":"상속재산 협의분할은 공동상속인 전원의 합의로 해제할 수 있다는 것이 판례다. 그래서 협의해제를 원인으로 법정상속분대로 소유권경정등기를 할 수 있다(등기예규).","c":"중","v":1},"법무사2020_26-02-1":{"w":"근저당권자 여럿 중 1인 지분만 신탁재산처분에 의한 신탁등기를 하면 근저당권설정등기와 신탁등기의 대상과 권리자가 달라 1건의 신청정보로 묶을 수 없다. 각각 신청한다(등기선례).","c":"중","v":1},"법무사2020_26-02-3":{"w":"부동산등기법 제83조 제1호는 신탁법 제12조 제1항 사유(사망·파산 등)로 수탁자 임무가 끝나면 신수탁자가 단독으로 권리이전등기를 신청하게 한다. 이에 해당하지 않는 자격 상실 등은 일반 원칙대로 신·구 수탁자가 공동신청한다(등기예규).","c":"중","v":1},"법무사2020_26-02-4":{"w":"부동산등기규칙 제139조 제3항은 신탁등기에 부동산등기법 제81조 제1항의 사항을 신탁원부 작성정보로 내게 한다. 일괄신청이라도 부동산별로 신탁원부를 작성하므로 부동산별로 정보를 낸다. 부동산 표시는 신청정보로 내므로 원부 작성 정보가 아니다(등기예규).","c":"중","v":1},"법무사2020_26-02-5":{"w":"신탁법은 종료사유와 잔여재산 귀속권리자를 신탁행위로 정할 수 있게 한다(제98조, 제101조). 그래서 위탁자 사망을 종료사유로, 수탁자를 귀속권리자로 정한 신탁등기도 신청할 수 있다(등기선례).","c":"중","v":1},"법무사2020_26-06-1":{"w":"종단에 소속된 전통사찰은 종단의 정관·규약에 따라 운영되므로 사찰 자체 규약과 함께 소속종단 정관·규약도 낸다(전통사찰 등기에 관한 등기예규).","c":"중","v":1},"법무사2020_26-06-2":{"w":"종단 규약상 종단 대표자가 주지 임면권을 가지면 주지 자격은 종단 대표자가 증명한다. 그래서 종단 대표자 명의의 주지재직증명과 그 직인 인영정보를 낸다(전통사찰 등기에 관한 등기예규).","c":"중","v":1},"법무사2020_26-06-3":{"w":"전통사찰보존법 제9조 제2항은 전통사찰보존지 부동산을 대여하거나 담보로 제공할 때 시·도지사의 허가를 받게 한다. 근저당권 설정은 담보 제공이어서 그 허가 증명정보를 낸다.","c":"중","v":1},"법무사2020_26-06-5":{"w":"전통사찰보존법 제9조 제1항은 전통사찰보존지 부동산을 양도할 때 문화체육관광부장관의 허가를 받게 한다. 증여도 양도여서 그 허가 증명정보를 낸다.","c":"중","v":1},"법무사2020_26-24-1":{"w":"1필지 일부는 분필 전에 이전등기할 수 없다. 그래서 특정 일부 유증이면 유언집행자가 그 부분을 분할등기한 뒤 수증자 명의로 이전등기를 신청한다(유증 등기에 관한 등기예규).","c":"중","v":1},"법무사2020_26-24-2":{"w":"민법 제1102조: 유언집행자가 여럿이면 임무 집행은 과반수로 정한다. 그래서 과반수가 동의하면 수증자 명의 이전등기를 신청할 수 있다(유증 등기에 관한 등기예규).","c":"중","v":1},"법무사2020_26-24-3":{"w":"유증 등기는 수증자와 유언집행자가 공동으로 하는 권리에 관한 등기여서 부동산등기법 제50조 제2항에 따라 유증자의 등기필정보를 제공한다(유증 등기에 관한 등기예규).","c":"중","v":1},"법무사2020_26-24-4":{"w":"특정유증의 수증자는 상속인에 대한 채권적 청구권만 가진다. 그래서 미등기 부동산이면 부동산등기법 제65조의 보존등기 신청인이 아니어서 상속인 명의로 보존등기를 한 뒤 유증 이전등기를 한다(유증 등기에 관한 등기예규).","c":"중","v":1},"법무사2020_26-30-1":{"w":"부동산등기법 제26조 제1항: 대표자나 관리인이 있는 법인 아닌 사단·재단은 그 명의로 등기권리자·등기의무자가 된다. 사단의 실체를 갖추었지만 법인등기를 하지 않은 단체가 이에 해당한다.","c":"상","v":1},"법무사2020_26-30-3":{"w":"부동산등기규칙 제48조 제2호 단서: 대표자나 관리인임을 증명하는 정보는 등기되어 있는 대표자나 관리인이 신청하면 제공하지 않아도 된다.","c":"상","v":1},"법무사2020_26-30-4":{"w":"부동산등기법 제48조 제3항은 사단·재단 명의 등기에 대표자·관리인의 성명·주소·주민등록번호를 기록하게 한다. 이것이 빠진 옛 등기는 명의인표시 변경등기로 추가할 수 있다(등기예규).","c":"중","v":1},"법무사2020_26-30-5":{"w":"법인 아닌 사단의 등기신청에 관한 등기예규는 대표자 증명서면과 총회결의서에 성년자 2인 이상의 사실 확인과 인감 날인·인감증명을 요구한다. 변호사·법무사가 대리하면 그가 확인 취지를 적고 기명날인하는 것으로 갈음할 수 있다.","c":"중","v":1},"법무사2021_27-03-1":{"w":"乙은 상속등기 전에 사망했으므로 먼저 甲의 상속인과 乙의 상속인 앞으로 상속등기를 해야 乙 지분이 특정된다. 그 뒤 乙의 상속인이나 유언집행자가 수증자 丙과 공동으로 유증 이전등기를 신청한다(등기선례).","c":"중","v":1},"법무사2021_27-03-2":{"w":"포괄수증자가 여럿이면 전원이 함께 또는 각자 자기 지분만 신청할 수 있다. 포괄수증자 외에 다른 상속인이 있으면 유증과 상속은 원인이 달라 각각 따로 이전등기를 신청한다(유증 등기에 관한 등기예규).","c":"중","v":1},"법무사2021_27-03-3":{"w":"수증자는 유증자 사망 후 유증의 전부나 일부를 포기할 수 있다(민법 제1074조). 특정 일부를 포기하면 유언집행자가 그 부분을 분할등기한 뒤 포기하지 않은 부분만 이전등기를 신청한다(등기예규).","c":"중","v":1},"법무사2021_27-03-5":{"w":"포괄수증자는 상속인과 같은 권리의무가 있어(민법 제1078조) 부동산등기법 제65조 제1호의 포괄승계인에 해당한다. 그래서 미등기 부동산이면 대장상 최초 소유자의 포괄수증자가 단독으로 보존등기를 신청할 수 있다(유증 등기에 관한 등기예규).","c":"중","v":1},"법무사2021_27-16-1":{"w":"부동산등기법 제26조 제2항: 법인 아닌 사단이나 재단에 속하는 부동산의 등기는 그 사단이나 재단의 명의로 대표자나 관리인이 신청한다.","c":"상","v":1},"법무사2021_27-16-2":{"w":"종중 사무소가 여러 번 바뀌었으면 신·구 규약으로 이전 경과를 증명하고 등기기록상 주소에서 바로 최후 주소로 명의인표시 변경등기를 할 수 있다는 것이 등기선례다.","c":"중","v":1},"법무사2021_27-16-3":{"w":"계는 규약상 사단의 실체를 갖추면 법인 아닌 사단으로 등기할 수 있다. 계원 개성이 운영에 반영되고 지위가 상속되는 등 조합적 성격이면 단체 명의 등기를 할 수 없어 각하한다(부동산등기법 제29조 제2호, 등기선례).","c":"중","v":1},"법무사2021_27-16-4":{"w":"아파트 입주자대표회의는 대표자가 있는 법인 아닌 사단이어서 부동산등기법 제26조에 따라 그 명의로 대표자가 등기를 신청할 수 있다(등기선례).","c":"중","v":1},"법무사2021_27-17-2":{"w":"부동산등기규칙 제46조 제5항: 법인 등기사항증명정보는 법인 본점·지점 소재지와 부동산 소재지가 같은 등기소 관할이면 제공을 생략할 수 있다. 대표자 자격 증명정보도 이에 해당한다.","c":"중","v":1},"법무사2021_27-17-3":{"w":"해산간주등기만 되고 등기기록이 폐쇄되지 않은 회사는 청산 중인 회사다. 청산인이 대표하므로 청산인 선임등기를 먼저 하고 인감은 법인인감인 청산인 인감을 낸다(청산법인 등기신청에 관한 등기예규).","c":"중","v":1},"법무사2021_27-17-4":{"w":"청산인 등기가 된 뒤 등기기록이 폐쇄되었으면 폐쇄 등기기록으로 청산인 자격이 증명된다. 법인인감 증명을 받을 수 없으므로 청산인 개인의 인감증명법상 인감을 낸다(청산법인 등기신청에 관한 등기예규).","c":"중","v":1},"법무사2021_27-17-5":{"w":"국내 영업소 등기가 없는 외국법인도 권리능력이 있다. 부동산등기법 제49조 제1항 제3호에 따라 시장·군수·구청장이 부여한 등록번호와 법인 존재를 인정할 정보를 내고 근저당권자로 신청할 수 있다(등기예규).","c":"중","v":1},"법무사2022_28-07-2":{"w":"판례는 한정승인 전에 한 협의분할과 그에 따른 상속등기의 효력이 한정승인으로 사라지지 않는다고 본다. 한정승인은 책임 범위를 제한할 뿐이어서 이를 원인으로 상속등기를 말소하거나 경정할 수 없다.","c":"중","v":1},"법무사2022_28-07-3":{"w":"상속등기 전에 공동상속인 1인이 사망하면 그의 상속인이 그 지위를 이어받는다. 그래서 나머지 상속인과 사망자의 상속인들이 협의분할을 할 수 있다(등기예규).","c":"중","v":1},"법무사2022_28-07-4":{"w":"상속을 포기한 자는 처음부터 상속인이 아니므로(민법 제1042조) 협의에 참여하지 않고 인감증명도 필요 없다. 대신 포기 사실을 증명하려고 상속포기 수리 심판정본을 낸다(상속등기에 관한 등기예규).","c":"중","v":1},"법무사2022_28-07-5":{"w":"상속재산 협의분할을 전원 합의로 해제하고 새로 분할한 경우 상속등기의 경정등기를 하며 원인은 「재협의분할」, 연월일은 재협의 성립일로 적는다는 것이 등기선례다.","c":"중","v":1},"법무사2022_28-27-1":{"w":"신탁가등기는 신탁 원인의 소유권이전청구권 보전 가등기와 같은 방식으로 신청하되 장래 신탁등기를 위해 신탁원부 작성 정보도 낸다(신탁등기에 관한 등기예규).","c":"중","v":1},"법무사2022_28-27-3":{"w":"수탁자·신탁재산·신탁목적이 같으면 위탁자가 여럿이어도 하나의 신탁으로 볼 수 있다. 그래서 1건의 신청정보로 일괄해 신탁등기를 신청할 수 있다(신탁등기에 관한 등기예규).","c":"중","v":1},"법무사2022_28-27-4":{"w":"수익자변경권이 위탁자·수탁자에게 유보되어 있다는 신탁조항이 신탁원부에 있으면 그 권한 행사로 수익자가 바뀐다. 종전 수익자의 승낙은 필요 없고 변경 증명정보만 낸다(등기선례).","c":"중","v":1},"법무사2022_28-27-5":{"w":"공익신탁법 제11조는 공익신탁의 수탁자 변경에 법무부장관 인가를 받게 한다. 그래서 수탁자 변경 등기에 인가 증명정보를 낸다(신탁등기에 관한 등기예규).","c":"중","v":1},"법무사2023_29-02-1":{"w":"민법 제1003조 제2항: 대습상속에서 상속인이 될 직계비속이나 형제자매의 배우자는 대습상속인이 된다. 처가 부모보다 먼저 사망했으면 그 남편은 처의 부모에 대한 대습상속인이다. 재혼하면 인척관계가 끝나 대습상속을 못한다(판례).","c":"중","v":1},"법무사2023_29-02-2":{"w":"상속등기 전에 상속인이 사망해 다시 상속이 개시되면 최종 상속인 앞으로 1건으로 상속등기를 할 수 있고 상속개시일을 순차로 모두 적는다(상속등기에 관한 등기예규).","c":"중","v":1},"법무사2023_29-02-3":{"w":"경정등기는 경정 전후 명의인에 동일성이 있어야 한다. 재협의로 甲·乙이 모두 빠지고 丙만 남으면 상속인 전부가 바뀌어 동일성이 없으므로 경정등기를 할 수 없다(등기선례).","c":"중","v":1},"법무사2023_29-02-5":{"w":"실종기간이 상속개시 전에 끝났으면 실종자는 그때 사망한 것으로 보아(민법 제28조) 처음부터 상속인이 아니다. 실종자의 상속인과 이해관계인이 없으면 신청착오를 원인으로 나머지 상속인들이 경정등기를 신청할 수 있다(등기선례).","c":"중","v":1},"법무사2023_29-05-1":{"w":"청산종결등기를 했어도 청산사무가 끝나지 않았으면 청산법인은 그 범위에서 존속한다는 것이 판례다. 그래서 등기당사자능력이 있다.","c":"중","v":1},"법무사2023_29-05-2":{"w":"등기기록이 폐쇄되지 않은 청산법인은 청산인이 대표하므로 청산인 등기가 된 법인등기사항증명서로 자격을 증명하고 법인인감인 청산인 인감을 낸다(청산법인 등기신청에 관한 등기예규).","c":"중","v":1},"법무사2023_29-05-3":{"w":"청산법인 등기기록이 폐쇄되었는데 등기권리자로 신청하면 폐쇄 기록을 부활해 청산인 등기가 된 증명서를 낸다(청산법인 등기신청에 관한 등기예규).","c":"중","v":1},"법무사2023_29-05-5":{"w":"폐쇄 기록에 청산인 등기가 없으면 청산인 자격을 증명할 방법이 없다. 그래서 등기기록을 부활해 청산인 등기를 한 뒤 그 증명서를 내고 법인인감인 청산인 인감을 낸다(청산법인 등기신청에 관한 등기예규).","c":"중","v":1},"법무사2024_30-24-1":{"w":"부동산등기법 제86조: 수탁자는 신탁원부 기록사항(수익자·신탁관리인 등)이 바뀌면 지체 없이 신탁원부 기록의 변경등기를 신청해야 한다.","c":"중","v":1},"법무사2024_30-24-2":{"w":"신탁법 제10조 제2항: 신탁행위로 방법을 정하지 않았으면 위탁자 지위 이전에 수탁자와 수익자의 동의가 필요하고 위탁자가 여럿이면 다른 위탁자 동의도 필요하다. 그래서 이를 증명하는 정보를 낸다(등기예규).","c":"중","v":1},"법무사2024_30-24-3":{"w":"부동산등기법 제85조 제1항: 법원이 수탁자 해임이나 신탁관리인 선임·해임 재판을 하면 지체 없이 신탁원부 기록의 변경등기를 촉탁하고 등기관은 그 촉탁에 따라 변경한다.","c":"상","v":1},"법무사2024_30-24-4":{"w":"부동산등기법 제85조의2 제1호·제2호: 수탁자 변경으로 인한 이전등기나 여러 수탁자 중 1인의 임무 종료로 인한 변경등기를 하면 등기관이 직권으로 신탁원부 기록을 변경한다.","c":"상","v":1},"법무사2024_30-25-1":{"w":"합병으로 소멸회사의 재산은 존속·신설회사에 포괄승계되어 권리 주체가 바뀐다(상법 제235조). 그래서 명의인표시 변경이 아니라 소유권이전등기를 한다(등기예규).","c":"중","v":1},"법무사2024_30-25-2":{"w":"연속 합병은 포괄승계가 이어진 것이어서 중간 등기를 생략하고 甲 회사에서 최종 丙 회사로 바로 이전등기를 할 수 있다(상속등기의 순차 상속과 같은 취지, 등기선례).","c":"중","v":1},"법무사2024_30-25-4":{"w":"소멸회사는 합병으로 없어져 존속회사가 소멸회사 명의 표시변경을 할 수 없다. 상호 변경 사실이 나타난 법인등기사항증명서를 내 동일성을 증명하고 바로 합병 원인 이전등기를 한다(등기선례).","c":"중","v":1},"법무사2024_30-25-5":{"w":"회사분할에 따른 이전은 분할계획에 따른 포괄승계여서 부동산 거래신고 등에 관한 법률 제11조의 토지거래 계약이 아니다. 그래서 허가증이 필요 없다(등기선례).","c":"중","v":1},"법무사2025_31-09-1":{"w":"부동산등기법 제7조의3 제1항: 상속이나 유증으로 인한 등기신청은 부동산 관할 등기소가 아닌 등기소도 그 등기사무를 담당할 수 있다.","c":"상","v":1},"법무사2025_31-09-2":{"w":"부동산등기법 제7조의3 제2항에 따라 대법원규칙이 정한 관할 특례 대상은 상속·유증 등기신청이다. 관공서가 압류·수용 촉탁과 함께 상속등기를 대위 촉탁하는 경우는 본 등기와 함께 처리해야 하므로 관할 외 등기소에서 처리할 수 없다(관할 특례에 관한 등기예규).","c":"중","v":1},"법무사2025_31-09-3":{"w":"유증 등기는 상속등기를 거치지 않고 유증자에게서 수증자에게 직접 한다. 이미 상속등기가 되었으면 말소하지 않고 상속인에서 수증자로 이전할 수 있으며 이것도 유증으로 인한 등기여서 관할 외 등기소에 신청할 수 있다(부동산등기법 제7조의3, 등기예규).","c":"중","v":1},"법무사2025_31-09-5":{"w":"채권자가 대위신청하는 상속등기도 상속으로 인한 등기신청이어서 부동산등기법 제7조의3의 관할 특례가 적용된다. 관할 외 등기소에 신청할 수 있다(등기예규).","c":"중","v":1},"법무사2026_32-01-1":{"w":"상속등기 뒤 제3자에게 신탁 이전등기가 되었으면 등기의무자가 상속인이 아니어서 유증 이전등기를 할 수 없다. 그 신탁등기가 정당하게 말소되어 소유권이 상속인에게 돌아오면 유증 이전등기를 신청할 수 있다(등기선례).","c":"중","v":1},"법무사2026_32-01-2":{"w":"유언 뒤 재건축으로 부동산 표시가 바뀌었어도 동일성이 소명되면 유언 효력이 새 부동산에 미친다. 그래서 동일성 소명자료와 공정증서로 유언집행자나 상속인이 수증자와 공동으로 이전등기를 신청할 수 있다(등기선례).","c":"중","v":1},"법무사2026_32-01-4":{"w":"특정유증 수증자는 채권적 청구권만 있어 부동산등기법 제65조의 보존등기 신청인이 아니다. 그래서 유언집행자가 상속인 명의로 보존등기를 한 뒤 유증 이전등기를 신청한다(유증 등기에 관한 등기예규).","c":"중","v":1},"법무사2026_32-01-5":{"w":"유증 등기에 관한 등기예규는 포괄·특정 유증 모두 유증자에게서 수증자에게 직접 등기하게 한다. 이미 상속등기가 되었으면 말소하지 않고 상속인에서 수증자로 이전등기를 할 수 있다.","c":"중","v":1},"법무사2026_32-26-1":{"w":"대법원 2023. 3. 23.자 2020그42 전원합의체 결정은 배우자와 자녀 중 자녀 전부가 포기하면 손자녀가 아니라 배우자가 단독상속인이 된다고 보았다(민법 제1043조). 배우자는 단독으로 상속등기를 신청한다.","c":"중","v":1},"법무사2026_32-26-3":{"w":"등기관은 형식적 심사만 하므로 피상속인 명의 등기가 사망 후에 마쳐진 것으로 기록되어 있어도 그것만으로 무효로 단정할 수 없다. 다른 각하사유가 없으면 그에 기초한 상속등기를 수리한다(등기선례).","c":"중","v":1},"법무사2026_32-26-4":{"w":"상속등기 뒤 일부 상속인이 지분을 처분했으면 그 이전등기가 남아 있는 한 협의분할 경정으로 그 지분을 줄일 수 없다. 먼저 정당한 사유로 그 이전등기를 말소한 뒤 경정한다(등기선례).","c":"중","v":1},"법무사2026_32-26-5":{"w":"협의분할 경정으로 甲 지분이 줄면 甲 지분 위의 가압류권자는 불이익을 받는 등기상 이해관계인이다. 부동산등기법 제52조 제5호·제57조 취지에 따라 그 승낙 증명정보를 낸다(등기선례).","c":"중","v":1},"법무사2026_32-30-1":{"w":"대습상속은 피상속인 사망으로 개시되므로 등기원인 연월일은 피상속인이 사망한 날로 한다(상속등기에 관한 등기예규).","c":"중","v":1},"법무사2026_32-30-2":{"w":"민법 제1001조는 대습상속인을 상속인이 될 자의 직계비속으로 한정한다. 그래서 대습상속인이 될 자가 먼저 사망했어도 그의 직계존속(양부모)은 재대습상속을 할 수 없다(등기선례).","c":"중","v":1},"법무사2026_32-30-4":{"w":"사업시행자는 재결서에 정한 수용개시일에 소유권을 취득한다(토지보상법 제45조 제1항). 개시일이 휴일이어도 그날이 취득일이므로 등기원인일도 재결서상 수용개시일로 적는다(등기선례).","c":"중","v":1},"법무사2026_32-30-5":{"w":"파산관재인의 임의매각은 법원의 감독 아래 하는 처분이어서 채무자 명의 등기필정보 제공이 필요 없다는 것이 채무자회생법 관련 등기예규다. 대신 법원 허가서 등을 낸다.","c":"중","v":1},"법무사2017_23-04-4":{"w":"「등기신청수수료 징수에 관한 예규」는 각하된 신청의 수수료는 돌려주지 않고 취하된 신청의 수수료는 신청인이나 대리인에게 환급하게 한다. 각하는 등기관이 심사를 마친 처분이기 때문이다.","c":"상","v":1},"법무사2017_23-05-1":{"w":"도시개발법은 환지계획 작성(제28조), 인가(제29조), 공사 완료와 환지처분 공고(제40조), 환지 등기 촉탁(제43조) 순서로 절차를 정한다.","c":"중","v":1},"법무사2017_23-05-2":{"w":"도시개발법 제43조와 그 등기에 관한 등기규칙은 사업시행자가 사업 시행을 위해 필요하면 환지처분 공고 전에도 종전 토지에 상속 등 이전등기를 소유자를 대위해 촉탁할 수 있게 한다.","c":"중","v":1},"법무사2017_23-05-4":{"w":"환지처분으로 생긴 권리 변동은 등기로 공시되어야 하므로 일부 환지의 등기 촉탁이 빠졌으면 사업시행자가 그 환지에 대해 다시 촉탁할 수 있다는 것이 환지등기에 관한 등기예규다.","c":"중","v":1},"법무사2017_23-05-5":{"w":"환지는 종전 토지로 보므로(도시개발법 제42조 제1항) 환지를 받은 자가 등기의무자가 되면 종전 토지 소유자로서 받은 등기필정보를 낸다(환지등기에 관한 등기예규).","c":"중","v":1},"법무사2017_23-06-1":{"w":"부동산등기규칙 제67조 제1항 본문: 전자신청은 당사자가 직접 하거나 자격자대리인이 당사자를 대리하여 한다.","c":"상","v":1},"법무사2017_23-06-3":{"w":"부동산등기규칙 제68조 제5항: 법인이 상업등기규칙에 따라 전자증명서 이용등록을 하면 사용자등록을 한 것으로 본다.","c":"상","v":1},"법무사2017_23-06-4":{"w":"부동산등기규칙 제67조 제1항 단서: 외국인이 전자신청을 하려면 출입국관리법상 외국인등록이나 재외동포법상 국내거소신고 요건을 갖추어야 한다.","c":"상","v":1},"법무사2017_23-06-5":{"w":"부동산등기규칙 제67조 제3항과 전자신청에 관한 등기예규는 자격자대리인이 서면을 스캐닝해 원본과 같다는 부가정보와 자격자대리인의 인증서 정보를 붙여 송신할 수 있게 한다(현재는 공인인증서 대신 지정 인증서).","c":"중","v":1},"법무사2017_23-10-1":{"w":"부동산등기법 제29조 제3호 이하의 사유는 등기가 마쳐지면 이의로 말소할 수 없다(부동산등기규칙 제159조 제3항). 권한 없는 자의 신청(제3호)으로 된 등기는 소송으로 말소를 구한다(판례·등기예규).","c":"중","v":1},"법무사2017_23-10-2":{"w":"각하결정으로 불이익을 받는 것은 신청인뿐이어서 등기권리자와 등기의무자만 이의신청을 할 수 있다(부동산등기법 제100조, 이의신청에 관한 등기예규). 제3자는 이의의 이익이 없다.","c":"중","v":1},"법무사2017_23-10-4":{"w":"부동산등기법 제104조는 이의에 집행정지 효력이 없다고 정한다. 이의신청 기간 규정이 없어 이의의 이익이 있는 한 언제든 신청할 수 있다(이의신청에 관한 등기예규).","c":"상","v":1},"법무사2017_23-10-5":{"w":"기록명령에 따른 등기 전에 제3자 명의 이전등기가 되었으면 등기의무자 표시가 맞지 않게 되어 그 명령대로 등기할 수 없다(이의신청에 관한 등기예규).","c":"중","v":1},"법무사2018_24-09-2":{"w":"도시정비법 제88조 제3항은 이전고시 후에는 등기가 있을 때까지 다른 등기를 하지 못하게 한다. 「도시 및 주거환경정비 등기규칙」상 종전 토지에는 권리 등기뿐 아니라 표시 등기도 할 수 없다.","c":"중","v":1},"법무사2018_24-09-3":{"w":"도시 및 주거환경정비 등기규칙은 새 건축시설이 구분건물이면 1동 전체 구분건물에 대해 같은 신청서로 보존등기를 하게 한다. 일부만 보존등기는 허용되지 않는다.","c":"중","v":1},"법무사2018_24-09-4":{"w":"도시 및 주거환경정비 등기규칙은 새 대지·건축시설에 존속하는 저당권 등기를 신청할 때 종전 저당권등기의 원인·연월일과 이전고시가 있었다는 취지·연월일을 적게 한다.","c":"중","v":1},"법무사2018_24-09-5":{"w":"도시 및 주거환경정비 등기규칙은 이전고시에 따른 등기신청서의 등기사항마다 적힌 순서대로 따로 접수번호를 부여하게 한다. 순위를 정하기 위해서다.","c":"중","v":1},"법무사2018_24-26-1":{"w":"공유토지분할에 관한 특례법상 분할개시결정 등기에는 다른 등기를 정지하는 효력이 없다. 그래서 그 토지에 대한 다른 등기신청도 수리한다(공유토지분할 등기에 관한 등기예규).","c":"중","v":1},"법무사2018_24-26-2":{"w":"공유토지분할 특례법에 따른 분할등기 촉탁은 분할 대상 토지 전부에 대해 같은 촉탁서로 한다(공유토지분할 등기에 관한 등기예규). 분할 결과를 한꺼번에 공시하기 위해서다.","c":"중","v":1},"법무사2018_24-26-4":{"w":"지적소관청의 분할등기 촉탁이 있으면 등기관은 분할된 토지마다 새 등기기록을 개설한다(공유토지분할 등기에 관한 등기예규).","c":"중","v":1},"법무사2018_24-26-5":{"w":"분할로 단독소유가 된 토지는 종전 공유지분이 바뀐 것이어서 그 소유자가 등기의무자가 되면 분할 전 지분을 취득할 때 받은 등기필정보를 낸다(공유토지분할 등기에 관한 등기예규).","c":"중","v":1},"법무사2019_25-06-5":{"w":"전자신청에 관한 등기예규는 법인등기부·부동산등기부처럼 등기소가 직접 확인할 수 있는 정보는 그 표시만 하고 첨부를 생략하게 한다.","c":"중","v":1},"법무사2019_25-13-1":{"w":"토지개발 등기규칙은 지적확정측량과 확정시행 공고로 지적공부가 정리된 범위에서 종전 토지 말소와 새 토지 보존등기를 하게 한다. 측량에서 제외된 토지는 그대로 두고 대상 토지만 신청할 수 있다(등기선례).","c":"중","v":1},"법무사2019_25-13-2":{"w":"토지개발 등기규칙은 종전 토지에 지상권 등이 있어도 종전 토지 말소와 새 토지 보존등기를 하게 한다. 그리고 그 권리는 보존등기 다음에 별개 신청정보로 설정등기를 하게 한다.","c":"중","v":1},"법무사2019_25-13-3":{"w":"토지개발 등기규칙에 따른 등기는 지번별조서와 정리된 지적공부에 따른다. 구역별로 조서가 작성되고 지적공부가 정리되었으면 각 구역 소유명의인이 각각 말소·보존등기를 신청할 수 있다(등기선례).","c":"중","v":1},"법무사2019_25-13-5":{"w":"토지개발 등기규칙에 따라 종전 토지의 지상권·전세권·임차권·근저당권 등기를 새 토지에 다시 할 때는 같은 권리를 이어가는 것이어서 종전 등기의 원인과 연월일을 기록한다.","c":"중","v":1},"법무사2019_25-18-1":{"w":"각하결정의 불이익은 신청인에게만 있으므로 등기권리자와 등기의무자만 이의신청을 할 수 있다(이의신청에 관한 등기예규).","c":"중","v":1},"법무사2019_25-18-3":{"w":"부동산등기규칙 제159조 제3항: 이미 마쳐진 등기에 대해 법 제29조 제1호·제2호 외의 사유로 이의하면 등기관은 직권말소하지 못하고 이의신청서를 관할 지방법원에 보낸다.","c":"상","v":1},"법무사2019_25-18-4":{"w":"기록명령에 따른 등기에 필요한 첨부정보를 다시 제공하라는 등기관의 명령에 신청인이 응하지 않으면 등기를 실행할 수 없다(이의신청에 관한 등기예규).","c":"중","v":1},"법무사2020_26-04-1":{"w":"주택법 제61조 제3항의 금지사항 부기등기는 대지에 대해 하는 것이다. 대지권등기가 남아 있으면 토지만 따로 등기할 수 없으므로 먼저 분리처분가능 규약으로 대지권 변경등기를 한다(등기선례).","c":"중","v":1},"법무사2020_26-04-2":{"w":"보조금법 제35조의2의 금지사항 등기는 소유권등기에 부기하는 것이 원칙이다. 그런데 그 뒤에 금지 대상인 저당권 등이 이미 있으면 부기로는 순위가 앞서게 되어 주등기로 한다(등기선례).","c":"중","v":1},"법무사2020_26-04-3":{"w":"한국주택금융공사법상 금지사항 부기등기도 매수인이 인수하지 않는 부담이면 매각으로 효력을 잃는다. 그래서 집행법원이 이전등기 촉탁과 함께 말소를 촉탁한다(민사집행법 제144조, 등기선례).","c":"중","v":1},"법무사2020_26-04-4":{"w":"구 임대주택법 제18조의 부기등기는 양도를 금지하는 것이 아니라 일정한 제한을 공시하는 것이다. 그래서 신탁을 원인으로 주택도시보증공사 명의의 이전등기와 신탁등기를 할 수 있다(등기선례).","c":"중","v":1},"법무사2020_26-13-1":{"w":"지방세법 제7조 제13항은 상속등기 후 협의분할로 특정 상속인이 당초 상속분을 넘어 취득한 부분을 증여 취득으로 보아 취득세를 부과한다(신고기한 내 분할 등 예외 제외).","c":"상","v":1},"법무사2020_26-13-2":{"w":"지방세법 제28조 제1항 제1호 다목 2): 저당권 설정 등기의 등록면허세는 채권금액의 1천분의 2다. 근저당권은 등기되는 채권최고액을 채권금액으로 보아 과세한다(지방세 실무).","c":"중","v":1},"법무사2020_26-13-3":{"w":"지방세법 제9조 제3항 제1호는 신탁으로 수탁자에게 이전되는 재산의 취득을 비과세한다. 신탁등기 자체는 지방세법 제28조 제1항 제1호 마목의 그 밖의 등기로 건당 등록면허세를 낸다.","c":"상","v":1},"법무사2020_26-13-5":{"w":"국민주택채권 매입 의무는 주택도시기금법 제8조와 시행령이 정하는 것이어서 지방세가 면제되었다고 함께 면제되지 않는다. 같은 법령의 면제사유가 있어야 매입하지 않는다(등기예규).","c":"중","v":1},"법무사2020_26-21-2":{"w":"도시정비법 부칙은 종전 법에 따라 승인받은 사업도 정비법에 따라 후속 절차를 진행하면 정비법을 적용하게 한다. 그래서 등기도 도시정비법 제88조와 도시 및 주거환경정비 등기규칙을 따른다(등기선례).","c":"중","v":1},"법무사2020_26-21-3":{"w":"새 대지에 대한 등기는 관리처분계획을 기준으로 한다(도시정비법 제87조). 채무 상환으로 소멸했어도 말소되지 않은 채 관리처분계획에 적힌 근저당권이면 보존등기와 함께 신청해야 한다(등기선례).","c":"중","v":1},"법무사2020_26-21-4":{"w":"도시정비법 제88조 제3항은 이전고시 후 등기가 있을 때까지 저당권 등 다른 등기를 하지 못하게 한다. 이전고시 통지 후에는 조합 명의 신탁부동산의 신탁해지 등에 따른 이전·신탁말소등기도 신청할 수 없다(등기선례).","c":"중","v":1},"법무사2020_26-21-5":{"w":"정비사업으로 축조된 건축물은 도시정비법 제88조와 정비 등기규칙에 따라 사업시행자가 일괄해 보존등기를 한다. 그래서 집행법원의 처분제한 촉탁이 있어도 등기관이 직권보존등기를 할 수 없다(등기선례).","c":"중","v":1},"법무사2021_27-14-1":{"w":"토지개발 등기규칙은 지적확정측량과 확정시행 공고가 있으면 종전 토지의 말소등기와 새 토지의 보존등기를 동시에 신청하게 한다.","c":"중","v":1},"법무사2021_27-14-2":{"w":"토지개발 등기규칙은 종전 토지 말소등기를 모든 토지에 대해 1건으로, 새 토지 보존등기도 모든 토지에 대해 1건으로 일괄 신청하게 한다.","c":"중","v":1},"법무사2021_27-14-3":{"w":"토지개발 등기규칙은 종전 모든 토지에 같은 내용의 신탁등기나 주택법 제61조 제3항 금지사항 부기등기가 있으면 새 토지 보존등기와 1건으로 일괄해 그 등기를 신청하게 한다.","c":"중","v":1},"법무사2021_27-14-5":{"w":"토지개발 등기규칙은 종전 토지의 지상권·전세권·임차권 등기를 새 토지에 다시 하려면 소유명의인과 그 권리 명의인이 공동으로 신청하게 한다.","c":"중","v":1},"법무사2021_27-23-1":{"w":"부동산등기규칙 제63조와 제139조 제4항: 자연인·법인 아닌 사단·재단이 직접 신청하거나 자격자대리인이 아닌 사람에게 위임한 경우 외에는 방문신청이라도 도면·신탁원부 작성 정보는 전자문서로 송신해야 한다.","c":"상","v":1},"법무사2021_27-23-2":{"w":"부동산등기규칙 제56조 제2항: 신청서가 여러 장이면 신청인이나 대리인이 간인하고 등기권리자나 등기의무자가 여럿이면 그중 1명이 간인한다.","c":"상","v":1},"법무사2021_27-23-4":{"w":"부동산등기규칙 제64조: 방문신청인은 신청서 제출 전에 전산정보처리조직에 신청정보를 입력하고 이를 출력한 서면(전자표준양식)을 제출하는 방법으로 신청할 수 있다.","c":"상","v":1},"법무사2021_27-23-5":{"w":"부동산등기규칙 제66조: 등기관이 등기를 마친 뒤 등기원인증서를 돌려주는데 신청인이 3개월 안에 받아가지 않으면 폐기할 수 있다. 매매계약서라고 달리 보지 않는다.","c":"상","v":1},"법무사2022_28-03-2":{"w":"국유재산 관리청 명칭 첨기 등기에 관한 등기예규는 총괄청이 국유재산법 제22조 제3항으로 직권 용도폐지해 인계받은 재산이면 총괄청이나 위임·위탁 기관이 용도폐지 공문 사본을 붙여 관리청 명칭 변경등기를 촉탁하게 한다.","c":"중","v":1},"법무사2022_28-03-3":{"w":"중앙관서의 장이 국유재산법 제40조에 따라 용도폐지해 총괄청에 인계하면 총괄청이나 위임·위탁 기관이 기존 관리청의 용도폐지 공문 사본과 국유재산대장 사본을 붙여 촉탁한다(관리청 명칭 첨기 등기에 관한 등기예규).","c":"중","v":1},"법무사2022_28-03-4":{"w":"조선총독부 명의 재산은 정부수립으로 국가에 귀속되었다. 관리청 지정서를 붙여 「1948. 8. 15. 대한민국정부수립」을 원인으로 「국, 관리청 ○○부」로 명의인표시변경을 촉탁하면 국 명의 변경과 관리청 첨기를 함께 한다(등기예규).","c":"중","v":1},"법무사2022_28-03-5":{"w":"관리청끼리 소관을 다투면 국유재산법상 총괄청이 결정한다. 그래서 총괄청의 관리청 결정서를 붙여 관리청 명칭 변경등기를 촉탁한다(등기예규).","c":"중","v":1},"법무사2022_28-10-1":{"w":"말소되는 등기의 명의인 표시는 말소로 사라지므로 변경 증명서면이 있으면 명의인표시 변경 없이 말소할 수 있다. 부동산등기법 제29조 제7호 나목처럼 동일인임이 확인되므로 각하하지 않는다(등기예규).","c":"중","v":1},"법무사2022_28-10-3":{"w":"해방공탁(민사집행법 제282조)은 가압류 집행취소 사유일 뿐이다. 가압류등기는 법원 촉탁으로만 말소하므로 채무자가 해방공탁서로 말소를 신청하면 「사건이 등기할 것이 아닌 경우」(부동산등기법 제29조 제2호)로 각하한다(등기예규).","c":"중","v":1},"법무사2022_28-10-4":{"w":"가압류가 본압류로 이행되면 가압류 효력은 본집행에 흡수된다는 것이 판례다. 본집행이 진행 중인데 가압류등기만 말소하는 촉탁은 법률상 허용되지 않아 부동산등기법 제29조 제2호로 각하한다(등기예규).","c":"중","v":1},"법무사2022_28-10-5":{"w":"전세금이 줄면 전세권을 목적으로 한 근저당권자의 담보가 줄어 그는 등기상 이해관계인이다. 그 근저당권은 전세권 자체에 붙어 있어 감액을 주등기로 따로 공시할 수 없으므로 승낙서가 없으면 필요한 첨부정보 미제공(부동산등기법 제29조 제9호)으로 각하한다(등기선례).","c":"중","v":1},"법무사2022_28-13-1":{"w":"부동산등기규칙 제67조 제1항 단서: 법인 아닌 사단이나 재단은 전자신청을 할 수 없다. 전자증명서를 받은 법인은 사용자등록을 한 것으로 보아(제68조 제5항) 전자신청을 할 수 있다.","c":"상","v":1},"법무사2022_28-13-2":{"w":"전자신청에 관한 등기예규는 보정 통지를 전자우편 외에 구두·전화 등으로도 할 수 있게 한다(부동산등기규칙 제52조).","c":"중","v":1},"법무사2022_28-13-3":{"w":"부동산등기규칙 제68조 제1항은 최초 전자신청 전에 사용자등록을 하게 한다. 제69조는 유효기간을 3년으로 하며 만료일 3개월 전부터 만료일까지 연장을 신청할 수 있게 한다.","c":"상","v":1},"법무사2022_28-13-4":{"w":"부동산등기규칙 제67조 제1항: 전자신청은 당사자가 직접 하거나 자격자대리인이 대리한다. 자격자대리인이 아닌 사람은 다른 사람을 대리해 전자신청할 수 없다.","c":"상","v":1},"법무사2023_29-06-1":{"w":"대위로 된 등기가 채무자 신청으로 말소되면 대위채권자는 그 말소로 권리 보전 이익을 잃으므로 등기상 이해관계인으로서 이의신청을 할 수 있다(이의신청에 관한 등기예규).","c":"중","v":1},"법무사2023_29-06-3":{"w":"부동산등기법 제103조 제3항: 등기를 마친 뒤 이의신청이 있으면 3일 이내에 의견을 붙여 이의신청서를 관할 지방법원에 보내고 등기상 이해관계 있는 자에게 이의신청 사실을 알린다.","c":"상","v":1},"법무사2023_29-06-4":{"w":"저당권 이전의 부기등기로 저당권설정자의 권리나 의무에는 변동이 없다. 그래서 설정자는 그 부기등기에 이해관계가 없어 이의신청을 할 수 없다(이의신청에 관한 등기예규).","c":"중","v":1},"법무사2023_29-06-5":{"w":"제3자 승낙서 누락은 그 제3자의 이익에 관한 사유다. 말소등기의무자는 그 사유를 주장할 이해관계인이 아니어서 이의신청을 할 수 없다(이의신청에 관한 등기예규).","c":"중","v":1},"법무사2023_29-25-1":{"w":"주택도시기금법 제8조와 시행령 별표는 시가표준액이 일정 금액 이상인 토지의 소유권보존등기·이전등기에 국민주택채권 매입 의무를 둔다.","c":"중","v":1},"법무사2023_29-25-2":{"w":"인지세법 제3조는 부동산 소유권이전 계약서 등 과세문서를 작성하는 자에게 기재금액에 따른 인지세 납부 의무를 지운다.","c":"중","v":1},"법무사2023_29-25-3":{"w":"부동산등기법 제22조 제3항: 등기를 신청하려는 자는 대법원규칙으로 정하는 수수료를 내야 한다. 구체적 금액은 등기사항증명서 등 수수료규칙 제5조의2가 정한다.","c":"상","v":1},"법무사2023_29-25-4":{"w":"지방세법 제28조 제1항 제1호 마목은 그 밖의 등기에 건당 정액 등록면허세를 매긴다. 등기명의인표시변경등기도 이에 해당한다(행정구역 변경 등 제26조 제2항 제2호의 비과세 사유는 제외).","c":"중","v":1},"법무사2023_29-27-2":{"w":"농어촌정비법 시행령은 환지계획 인가 고시 후 종전 토지에 대한 등기를 제한한다. 그 뒤 마쳐진 이전등기는 「사건이 등기할 것이 아닌 경우」에 해당해 부동산등기법 제58조로 직권말소한다(농어촌정비법 환지등기 처리 등기예규).","c":"중","v":1},"법무사2023_29-27-3":{"w":"농어촌정비법 환지등기 처리 등기예규는 여러 종전 토지에 하나 또는 여럿의 환지를 준 경우 종전 토지 중 미등기가 있으면 그 취지를 촉탁정보로 내게 한다.","c":"중","v":1},"법무사2023_29-27-4":{"w":"환지등기 촉탁에는 환지계획서와 환지처분 증명정보 등 정해진 첨부정보가 필요하다. 토지대장만 내면 「환지」 등이 적혀 있어도 수리하지 않는다(환지등기 등기예규).","c":"중","v":1},"법무사2023_29-27-5":{"w":"환지등기 등기예규는 권리 설정·이전 등을 해야 할 때 등 특별한 사유가 아니면 사업지역 안 토지 전부에 대해 동시에 환지등기를 촉탁하게 한다.","c":"중","v":1},"법무사2024_30-07-3":{"w":"도시정비법 제86조 제1항 단서는 공사가 전부 끝나기 전이라도 완공된 부분에 준공인가를 받아 이전고시를 할 수 있게 한다. 그 부분만 등기를 신청할 수 있다(도시정비법 제88조).","c":"중","v":1},"법무사2024_30-29-1":{"w":"등기신청수수료 납부에 관한 등기예규는 전자신청에서 과·오납하면 사건 처리 완료 전에 기존 결제를 전부 취소하고 다시 결제하게 한다.","c":"중","v":1},"법무사2024_30-29-2":{"w":"등기사항증명서 등 수수료규칙 제5조의2 제4항 제5호는 부동산의 분할·구분·합병·멸실등기(대지권 등기 제외)에 신청수수료를 받지 않는다.","c":"상","v":1},"법무사2024_30-29-3":{"w":"등기명의인표시변경은 명의인마다 하는 등기여서 등기신청수수료 징수에 관한 예규는 공유자의 주소가 똑같이 바뀌어도 명의인 수만큼 수수료를 받게 한다.","c":"중","v":1},"법무사2024_30-29-5":{"w":"수수료는 변경되는 등기의 수만큼 낸다(등기신청수수료 징수에 관한 예규). 순위번호가 다른 합유등기 2건을 한 원인으로 변경해도 2건의 수수료를 낸다.","c":"중","v":1},"법무사2025_31-11-1":{"w":"부동산등기법 제29조 제7호 가목: 등기의무자 표시가 등기기록과 다르더라도 제27조에 따라 포괄승계인이 신청하면 각하사유에서 제외된다.","c":"상","v":1},"법무사2025_31-11-2":{"w":"부동산등기법 제29조 제7호 나목: 신청정보와 등기기록의 등기의무자가 동일인임을 대법원규칙으로 정하는 바에 따라 확인할 수 있으면 각하사유에서 제외된다.","c":"상","v":1},"법무사2025_31-11-4":{"w":"부동산등기규칙 제52조의2 제3항: 등기 당시 주소가 잘못 기록되는 등 명의인 표시에 경정사유가 있으면 주소 변경에 따른 동일성 인정(제1항)을 적용하지 않는다. 그래서 경정등기 없이 신청하면 부동산등기법 제29조 제7호로 각하한다.","c":"상","v":1},"법무사2025_31-11-5":{"w":"부동산등기규칙 제52조의2 제1항은 주민등록번호가 등기기록과 일치하고 주소증명정보로 주소 변경이 확인될 때만 동일성을 인정한다. 등기기록에 주민등록번호가 없으면 이 요건을 갖출 수 없어 부동산등기법 제29조 제7호로 각하한다.","c":"상","v":1},"법무사2025_31-18-5":{"w":"등기사항증명서 등 수수료규칙 제5조의5 제2항: 상속등기를 전자표준양식으로 신청하면 부동산마다 17,000원이다. 토지 1필지와 건물 1개이면 34,000원이다.","c":"상","v":1},"법무사2025_31-29-3":{"w":"제3자 승낙서 누락은 그 제3자의 이익에 관한 것이어서 말소등기의무자는 이를 이유로 이의신청을 할 이해관계인이 아니다(이의신청에 관한 등기예규).","c":"중","v":1},"법무사2026_32-08-1":{"w":"주차장법상 시설물·부설주차장 부기등기는 용도 변경을 제한하는 취지일 뿐 처분을 금지하지 않는다. 그래서 양도·담보제공 등 다른 등기를 수리한다(특약사항 등기에 관한 등기예규).","c":"중","v":1},"법무사2026_32-08-2":{"w":"한국주택금융공사법상 금지사항은 제한물권 설정, 압류·가압류·가처분, 임대차 등 소유권 제한 행위다. 소유권이전청구권가등기는 그 열거 대상이 아니어서 공사 동의가 필요 없다(등기선례).","c":"중","v":1},"법무사2026_32-08-3":{"w":"토지보상법 제91조의 환매권은 법률에 따라 생기는 권리이고 등기 규정이 없다. 민법상 환매특약과 달라 환매특약등기를 할 수 없다(등기선례).","c":"중","v":1},"법무사2026_32-08-5":{"w":"민간임대주택법 제5조의2 제3항 등은 등록 말소 시 임대사업자가 부기등기 말소를 신청하게 하고 시장·군수·구청장도 말소를 촉탁할 수 있게 한다.","c":"중","v":1},"법무사2026_32-10-2":{"w":"환지처분은 공고로 효력이 생기므로 일부 토지에 환지·청산금 지정이 빠진 위법이 있어도 효력이 발생한 이상 청산금 지급과 관계없이 환지등기를 촉탁할 수 있다(등기선례).","c":"중","v":1},"법무사2026_32-10-3":{"w":"농어촌정비법 환지등기 등기예규는 환지계획 인가 고시 후 종전 토지에 권리 등기와 표시 등기를 모두 제한한다. 환지 내용과 어긋나는 등기를 막기 위해서다.","c":"중","v":1},"법무사2026_32-10-4":{"w":"공유토지에 각 단독소유로 환지를 주는 것은 공유물분할을 겸하는 것이어서 환지처분만으로 할 수 없다는 것이 판례·등기예규다. 그래서 그런 환지등기는 할 수 없다.","c":"중","v":1},"법무사2026_32-10-5":{"w":"환지는 종전 토지로 보므로 종전 토지에 관한 계약은 환지에 그대로 미친다. 그래서 종전 토지 계약서를 원인증서로 낸 환지 등기신청도 수리한다(등기선례).","c":"중","v":1},"법무사2026_32-24-1":{"w":"부동산등기규칙 제51조 제2항 제1호는 방문신청 취하를 신청인이나 대리인이 출석해 취하서를 내게 한다. 등기예규는 지방법원장 허가를 받은 자격자대리인 사무원도 취하서를 낼 수 있게 한다(제58조).","c":"중","v":1},"법무사2026_32-24-2":{"w":"일괄신청은 여러 신청을 한 신청서로 한 것이어서 그중 일부 부동산만 취하할 수 있다(등기신청 취하에 관한 등기예규).","c":"중","v":1},"법무사2026_32-24-4":{"w":"부동산등기법 제29조 단서는 보정명령 다음 날까지 보정해야 각하를 면하게 한다. 각하결정을 한 뒤에는 고지 전에 보정되어도 결정 효력에 영향이 없다(보정에 관한 등기예규).","c":"중","v":1},"법무사2026_32-24-5":{"w":"각하결정문에 관한 등기예규는 인터넷등기소에서 결정문 하단의 발급확인번호와 접수정보를 입력해 진위를 확인할 수 있게 한다.","c":"중","v":1},"법무사2016_22-32-1":{"w":"공탁규칙 제69조 단서: 금전공탁사건은 전자문서로 신청·청구할 수 있지만 5천만 원을 넘는 공탁금의 출급·회수 청구는 예외다.","c":"상","v":1},"법무사2016_22-32-3":{"w":"추심 및 처분금지가처분이 송달되고 가처분권자가 채권 귀속을 다투면 제3채무자는 누가 진정한 채권자인지 알 수 없다. 그래서 민법 제487조 후단의 상대적 불확지 공탁으로 피공탁자를 「가처분채무자 또는 가처분채권자」로 할 수 있다(공탁선례).","c":"하","v":1},"법무사2016_22-32-4":{"w":"수용보상금 공탁은 토지소유자에 대한 보상금 지급에 갈음하는 것이다. 담보물권자 등은 물상대위로 권리를 행사하므로(토지보상법 제47조) 피공탁자란에는 토지소유자만 적는다(토지수용 보상금 공탁 사무처리지침).","c":"중","v":1},"법무사2016_22-32-5":{"w":"채권자에게 반대급부 의무가 없는데 이를 조건으로 하면 채무 내용에 맞는 변제가 아니어서 변제공탁은 무효라는 것이 판례다. 채권자가 그 조건을 수락하면 유효하게 된다.","c":"중","v":1},"법무사2016_22-39-1":{"w":"판례는 공탁이 공탁자의 책임과 판단으로 하는 것이어서 공탁자가 변제공탁·집행공탁·혼합공탁 가운데 선택할 수 있다고 본다. 공탁관은 공탁서 기재로 공탁 종류를 판단한다.","c":"중","v":1},"법무사2016_22-39-2":{"w":"이해관계 없는 제3자는 채무자의 의사에 반해 변제할 수 없다(민법 제469조 제2항). 그래서 공탁원인사실에 채무자의 동의를 얻어 채무자 대신 공탁한다는 뜻을 적는다(공탁 실무 예규).","c":"중","v":1},"법무사2016_22-39-4":{"w":"「전자공탁시스템에 의한 공탁사무처리지침」(행정예규)은 법인 아닌 사단·재단은 대표자와 단체의 관계를 전자적으로 증명할 수 없어 전자공탁시스템을 이용할 수 없게 한다.","c":"중","v":1},"법무사2016_22-39-5":{"w":"공탁규칙 제70조 제2항: 전자공탁 사용자등록 신청인(법인은 대표자)이 외국인이면 출입국관리법상 외국인등록이나 재외동포법상 국내거소신고 요건을 갖추어야 한다.","c":"상","v":1},"법무사2016_22-41-1":{"w":"공탁규칙 제30조 제1항은 공탁의 동일성을 해치지 않는 범위에서 정정을 허용한다. 반대급부 철회는 채권자에게 유리해 동일성을 해치지 않으므로 허용된다(공탁선례).","c":"중","v":1},"법무사2016_22-41-2":{"w":"압류명령 일부를 빠뜨린 것은 공탁원인사실의 기재 누락일 뿐이고 집행공탁이라는 동일성은 유지된다. 그래서 누락된 압류명령을 추가하는 정정은 허용된다(공탁선례).","c":"중","v":1},"법무사2016_22-41-3":{"w":"절대적 불확지 공탁은 나중에 피공탁자를 알게 되면 특정해야 출급할 수 있다. 그래서 사업시행자가 피공탁자를 지정하는 정정신청을 할 수 있다(토지수용 보상금 공탁 사무처리지침).","c":"중","v":1},"법무사2016_22-41-5":{"w":"수령불능(민법 제487조 전단)과 채권자 불확지(후단)는 공탁원인이 다르다. 후단 공탁에 전단 사유를 추가하는 것은 동일성을 해치는 정정이어서 허용되지 않는다(공탁규칙 제30조 제1항, 공탁선례).","c":"중","v":1},"법무사2016_22-43-2":{"w":"판례는 등기부상 소유자를 피공탁자로 한 보상금 공탁에서 그가 이미 사망했으면 그 공탁은 상속인들에 대한 공탁으로 유효하다고 본다. 상속인은 상속증명으로 출급한다.","c":"중","v":1},"법무사2016_22-43-3":{"w":"청산종결등기가 되어도 청산사무가 남아 있으면 그 범위에서 법인은 존속한다는 것이 판례다. 그래서 공탁당사자능력이 인정된다.","c":"중","v":1},"법무사2016_22-43-4":{"w":"미성년자는 법정대리인의 동의를 얻어야 법률행위를 할 수 있다(민법 제5조). 공탁물 출급청구는 권리 행사여서 피공탁자로 지정되었더라도 법정대리인의 동의나 대리가 필요하다(공탁선례).","c":"중","v":1},"법무사2016_22-43-5":{"w":"물상보증인과 제3취득자는 변제에 법률상 이해관계가 있는 제3자여서 채무자의 의사에 반해서도 변제할 수 있다(민법 제469조 제2항 반대해석). 변제공탁도 같다.","c":"중","v":1},"법무사2016_22-44-1":{"w":"공탁규칙 제2조는 시·군법원 공탁관 직무를 소액사건 관련 변제공탁, 열거된 재판상 보증공탁, 가압류해방금 집행공탁, 몰취공탁으로 한정한다. 민사집행법 제248조 제1항의 집행공탁은 포함되지 않는다.","c":"상","v":1},"법무사2016_22-44-2":{"w":"공탁법 제5조 제1항과 공탁규칙 제66조: 국내에 주소·거소가 없는 외국인이나 재외국민을 위한 변제공탁은 지참채무이면 다른 법령이나 특약이 없는 한 서울중앙지방법원 공탁관에게 할 수 있다.","c":"상","v":1},"법무사2016_22-44-3":{"w":"변제공탁은 채무이행지 공탁소에 하는데(민법 제488조 제1항) 지참채무는 채권자 주소가 이행지다(제467조 제2항). 상속으로 채권자가 여럿이 되면 각 상속인 주소지 공탁소에 나누어 공탁한다(공탁선례).","c":"중","v":1},"법무사2016_22-44-4":{"w":"토지보상법 제40조 제2항은 보상금 공탁을 토지 소재지 공탁소에 할 수 있게 한다. 그래서 채권자 현주소지 공탁소 외에 토지 소재지 공탁소에서도 공탁할 수 있다.","c":"중","v":1},"법무사2016_22-47-1":{"w":"공탁법 제12조의 이의 대상은 불복할 이익이 있는 처분이다. 공탁선례는 공탁신청이나 지급청구에 대한 불수리처분만 대상으로 보고 수리·인가처분은 제외한다.","c":"중","v":1},"법무사2016_22-47-2":{"w":"공탁법 제12조 제1항·제2항: 공탁관의 처분에 불복하면 관할 지방법원에 이의신청을 할 수 있고 그 신청은 공탁소에 이의신청서를 제출하는 방법으로 한다.","c":"상","v":1},"법무사2016_22-47-3":{"w":"이의신청의 관할 지방법원은 공탁관이 소속한 법원이다. 시·군법원은 그 시·군법원이 속한 본원이나 지원이 관할한다(공탁 이의신청에 관한 예규·선례).","c":"중","v":1},"법무사2016_22-47-5":{"w":"공탁관은 형식적 심사권만 있으므로 불수리가 부당한지는 그 형식적 심사권을 전제로 불수리 당시를 기준으로 판단한다는 것이 판례다. 공탁법 제12조 이의에서도 같다.","c":"중","v":1},"법무사2016_22-48-1":{"w":"공탁금 이자는 원금에 붙는 것이어서(공탁법 제6조, 공탁규칙 제52조) 원금을 받는 자에게 귀속된다. 회수하면 공탁자에게, 출급하면 피공탁자에게 간다.","c":"중","v":1},"법무사2017_23-31-2":{"w":"공탁규칙 제21조 제3항은 변제공탁에서 피공탁자 주소를 적으면 그 주소소명서면을 붙이게 한다. 상대적 불확지 공탁은 피공탁자로 적힌 자 모두의 주소를 소명해야 한다.","c":"중","v":1},"법무사2017_23-31-3":{"w":"주소불명 변제공탁은 주소불명 소명서면을 붙이고(공탁규칙 제21조 제3항) 통지할 곳이 없으므로 공탁통지서를 내지 않는다. 나중에 주소를 알면 정정신청을 하며 공탁통지서를 붙인다(제30조 제6항, 제23조 준용).","c":"상","v":1},"법무사2017_23-31-4":{"w":"공탁규칙 제21조 제3항의 주소소명서면은 주민등록표 등 주소를 직접 증명하는 공문서여야 한다. 재결서나 판결문의 주소는 그 사건에 적힌 것일 뿐이어서 직접 소명서면이 아니다(공탁선례).","c":"중","v":1},"법무사2017_23-31-5":{"w":"「재외국민 등의 공탁에 관한 업무처리지침」(행정예규 제1431호) 제7조: 재외국민·외국인 피공탁자의 주소가 불명이면 공탁 원인 서면상 주소를 최종주소지로 적고 그곳에 거주하지 않는다는 소명서면(반송된 배달증명 등)을 낸다.","c":"상","v":1},"법무사2017_23-32-1":{"w":"전자공탁 사무처리지침은 미성년자가 법정대리인 동의 없이 공탁행위능력이 있는지 시스템으로 확인할 수 없어 미성년자의 전자신청을 허용하지 않는다.","c":"중","v":1},"법무사2017_23-32-2":{"w":"공탁규칙 제76조: 전자공탁시스템에 의한 공탁사건의 정정신청이나 보정은 전자공탁시스템을 이용하여 한다.","c":"상","v":1},"법무사2017_23-32-3":{"w":"전자공탁 사무처리지침은 전자신청 대리를 변호사·법무사 회원만 하게 한다(공탁규칙 제70조 제1항의 회원 구분). 자격자가 아닌 사람은 대리할 수 없다.","c":"중","v":1},"법무사2017_23-32-4":{"w":"공탁규칙 제79조 제2항: 변호사회원·법무사회원이 전자문서로 공탁금 출급·회수를 청구하면 청구인의 전자서명도 함께 제출한다.","c":"상","v":1},"법무사2017_23-33-1":{"w":"납세담보공탁은 징수유예 등 허가를 받으려는 납세자 자신이 공탁하는 것이다. 영업보증공탁은 영업자 자신의 거래상 손해를 담보하는 것이어서 제3자 공탁이 허용되지 않는다고 보는 것이 공탁 실무다.","c":"중","v":1},"법무사2017_23-33-2":{"w":"영업보증공탁은 장래 영업 거래로 손해를 입을 불특정 채권자를 위한 것이어서 공탁 당시 피공탁자를 알 수 없다. 그래서 공탁서에 피공탁자란을 두지 않는다(공탁 실무).","c":"하","v":1},"법무사2017_23-33-4":{"w":"보관공탁은 무기명식 채권 소지인 등 권리자 스스로 목적물 보관을 위해 하는 것이다. 성질상 제3자가 그를 대신해 공탁할 수 없다(공탁 실무).","c":"중","v":1},"법무사2017_23-33-5":{"w":"몰취공탁은 제재로 국가가 몰수할 수 있도록 하는 것이어서 피공탁자는 국가다. 공탁자는 민사소송법 제299조 제2항의 소명 당사자나 법정대리인, 상업등기법상 신청인 등 법령이 정한다.","c":"중","v":1},"법무사2017_23-36-3":{"w":"피공탁자 변경은 공탁의 동일성을 해쳐 공탁규칙 제30조 제1항상 정정할 수 없다. 확지공탁을 상대적 불확지공탁으로 바꾸는 것도 피공탁자를 바꾸는 것이어서 허용되지 않는다(공탁선례).","c":"중","v":1},"법무사2018_24-33-1":{"w":"집행공탁과 혼합공탁은 공탁 근거와 성질이 다르다. 집행공탁을 혼합공탁으로 바꾸는 것은 동일성을 해쳐 정정할 수 없다는 것이 판례·공탁선례다.","c":"중","v":1},"법무사2018_24-33-3":{"w":"저작권법 제50조 제1항은 저작재산권자를 알 수 없으면 보상금을 공탁하고 이용할 수 있게 한다. 그 공탁은 공탁자 주소지 공탁소에 하고 피공탁자를 특정하지 않는다(같은 법 시행령, 공탁선례).","c":"하","v":1},"법무사2018_24-33-4":{"w":"민사집행법상 압류가 있으면 채무자에게 변제할 수 없어 채무자를 피공탁자로 한 변제공탁은 할 수 없다. 체납처분 압류가 함께 있어도 제3채무자는 민사집행법 제248조 제1항으로 압류된 채권 전액을 공탁할 수 있다(판례·공탁선례).","c":"중","v":1},"법무사2018_24-33-5":{"w":"혼합공탁은 채권자 불확지 변제공탁과 집행공탁이 결합한 것이다. 선행 전부명령 유효 여부를 몰라 집행공탁을 했다면 압류채권자 사이 문제여서 혼합공탁이 아니라 집행공탁이다(판례).","c":"중","v":1},"법무사2018_24-38-1":{"w":"공탁규칙 제30조 제1항: 공탁 수리 후 공탁서 착오를 발견하면 공탁의 동일성을 해치지 않는 범위에서 정정할 수 있다. 판례는 표현상 착오가 명백한 경우로 본다.","c":"상","v":1},"법무사2018_24-38-2":{"w":"이름·주민등록번호가 일치하면 공탁자는 같은 사람이고 주소만 잘못 적은 것은 표현상 착오다. 주민등록초본을 소명서면으로 내 주소를 정정할 수 있다(공탁규칙 제30조 제2항).","c":"중","v":1},"법무사2018_24-38-3":{"w":"압류명령 일부 누락은 원인사실 기재의 누락일 뿐 집행공탁의 동일성에 영향이 없다. 그래서 누락된 압류명령을 추가하는 정정은 허용된다(공탁선례).","c":"중","v":1},"법무사2018_24-38-4":{"w":"공탁규칙 제30조 제3항은 정정신청에 제22조를 준용한다. 같은 사람이 같은 법원에 동시에 여러 건 정정신청을 하면 같은 첨부서면은 1건에만 붙이고 나머지에는 그 뜻을 적는다.","c":"상","v":1},"법무사2018_24-46-1":{"w":"공탁규칙은 공탁서 제출(제20조)과 지급청구에 출석을 전제하고 우편 신청 규정을 두지 않는다. 공탁 실무는 우편에 의한 공탁신청·정정신청·지급청구를 허용하지 않는다.","c":"중","v":1},"법무사2018_24-46-3":{"w":"수용보상금 확지공탁의 피공탁자는 토지소유자다. 담보물권자나 압류채권자는 물상대위로 보상금청구권에 권리를 행사하므로 피공탁자란에 적지 않는다(토지수용 보상금 공탁 사무처리지침).","c":"중","v":1},"법무사2018_24-46-4":{"w":"공탁규칙 제12조 제2항은 공탁서 등에 적은 금전 숫자의 정정·추가·삭제를 금지한다. 다만 공탁서의 공탁원인사실란에 적은 숫자는 그 대상에서 제외한다.","c":"상","v":1},"법무사2018_24-46-5":{"w":"공탁규칙 제16조: 공탁관에게 내는 관공서 발급 자격증명서면·주소소명서면과 인감증명서는 발급일부터 3개월 이내의 것이어야 한다.","c":"상","v":1},"법무사2018_24-48-1":{"w":"공탁규칙 제75조: 전자문서에 의한 신청은 신청정보가 전자공탁시스템에 저장된 때 접수된 것으로 본다.","c":"상","v":1},"법무사2018_24-48-2":{"w":"공탁규칙 제79조 제1항: 전자문서로 공탁금 출급·회수를 청구하면 제37조 제1항·제2항의 인감증명서를 붙이지 않는다. 전자서명이 본인 확인을 대신한다.","c":"상","v":1},"법무사2018_24-48-3":{"w":"전자공탁 사무처리지침은 법인 아닌 사단·재단은 대표자와 단체의 관계를 전자적으로 증명할 수 없어 전자공탁시스템을 쓸 수 없게 한다.","c":"중","v":1},"법무사2018_24-48-4":{"w":"공탁규칙 제79조 제3항: 전자문서에 의한 출급·회수청구로 예금계좌에 입금할 때 그 계좌는 청구인 본인의 계좌여야 한다.","c":"상","v":1},"법무사2018_24-49-1":{"w":"「관할공탁소 이외의 공탁소에서의 공탁사건처리 지침」은 접수공탁소와 관할공탁소가 모두 지방법원 본원이나 지원인 경우에만 적용한다. 시·군법원은 제외된다.","c":"상","v":1},"법무사2018_24-49-3":{"w":"관할공탁소 이외 공탁소 처리 지침은 접수공탁소와 관할공탁소가 같은 특별시나 광역시에 있으면 적용하지 않는다. 직접 가기 어렵지 않기 때문이다.","c":"상","v":1},"법무사2018_24-49-4":{"w":"관할공탁소 이외 공탁소 처리 지침은 접수공탁소 공탁관이 공탁서 기재와 첨부서류로 관할 등 형식 사항을 조사하고 흠결이 있으면 보정하게 하도록 정한다.","c":"상","v":1},"법무사2019_25-34-1":{"w":"민법 제487조 전단(수령불능)과 후단(채권자 불확지)은 공탁원인이 다르다. 후단 공탁에 전단 사유를 추가하면 동일성을 해쳐 정정할 수 없다(공탁규칙 제30조 제1항, 공탁선례).","c":"중","v":1},"법무사2019_25-34-2":{"w":"반대급부 조건을 새로 붙이면 피공탁자에게 불리해져 동일성을 해친다. 기존 조건을 철회하는 것은 피공탁자에게 유리하고 공탁의 동일성에 영향이 없어 허용된다(공탁선례).","c":"중","v":1},"법무사2019_25-34-4":{"w":"피공탁자를 일부 삭제하거나 확지공탁을 상대적 불확지공탁으로 바꾸는 것은 모두 피공탁자를 바꾸는 것이어서 동일성을 해친다. 그래서 정정이 허용되지 않는다(공탁선례).","c":"중","v":1},"법무사2019_25-34-5":{"w":"절대적 불확지 수용보상금 공탁은 피공탁자를 알게 되면 특정해야 출급할 수 있다. 그래서 사업시행자가 피공탁자를 지정하는 정정신청을 할 수 있다(토지수용 보상금 공탁 사무처리지침).","c":"중","v":1},"법무사2019_25-48-1":{"w":"관할공탁소 이외의 공탁소에서의 공탁사건처리 지침(행정예규 제1167호) 3. 나.: 접수공탁소와 관할공탁소가 모두 지방법원 본원 또는 지원인 경우에만 적용한다.","c":"상","v":1},"법무사2019_25-48-2":{"w":"행정예규 제1167호 3. 다.는 토지수용·사용 관련 보상금 공탁신청에는 이 지침을 적용하지 않는다.","c":"상","v":1},"법무사2019_25-48-3":{"w":"행정예규 제1167호 3. 가.는 지급청구에서 공탁규칙 제37조 제3항 각 호(본인이 직접 1천만 원 이하를 청구하는 경우 등)와 법인의 위임을 받은 대리인의 1천만 원 이하 청구에만 적용한다. 개인의 위임을 받은 대리인 청구는 대상이 아니다.","c":"상","v":1},"법무사2019_25-48-4":{"w":"행정예규 제1167호 3. 가.: 공탁신청은 금전변제공탁에만 적용한다. 재판상 담보공탁이나 집행공탁 신청에는 적용하지 않는다.","c":"상","v":1},"법무사2020_26-34-2":{"w":"공탁규칙 제21조 제1항은 법인 아닌 사단·재단이 공탁하면 정관·규약과 대표자 자격 증명서면을 붙이게 한다. 대표자나 관리인이 있으면 공탁당사자능력이 있다는 전제다(민사소송법 제52조 참조).","c":"중","v":1},"법무사2020_26-34-3":{"w":"판례는 등기부상 소유자를 피공탁자로 한 보상금 공탁에서 그가 이미 사망했으면 상속인들에 대한 공탁으로 유효하다고 본다.","c":"중","v":1},"법무사2020_26-34-4":{"w":"민사집행법 제248조 제1항의 집행공탁은 배당절차로 수령권자가 정해진다. 공탁 당시 피공탁자를 적지 않아도 유효하고 적었더라도 법원을 구속하지 않는다는 것이 판례다.","c":"중","v":1},"법무사2020_26-34-5":{"w":"물상보증인과 연대채무자는 변제할 법률상 이해관계가 있는 제3자 또는 채무자 자신이어서 채무자 의사에 반해서도 변제할 수 있다(민법 제469조). 변제공탁도 같다.","c":"중","v":1},"법무사2020_26-43-1":{"w":"공탁규칙 제53조: 공탁금 이자는 출급·회수청구서에 따라 공탁금보관자가 계산해 지급한다. 이자를 따로 청구하려면 공탁관에게 공탁금이자청구서 2통을 낸다.","c":"상","v":1},"법무사2020_26-43-2":{"w":"판례는 압류·추심명령의 효력이 압류 전에 생긴 공탁금 이자에는 미치지 않는다고 본다. 그 이자는 별개 채권이어서 따로 압류·추심명령을 받아야 한다.","c":"중","v":1},"법무사2020_26-43-3":{"w":"공탁금의 이자에 관한 규칙 제2조는 공탁금 이자를 연 1만분의 35로 정한다. 2018. 5. 29. 개정 이후 2020년·2022년 개정을 거쳐서도 같은 이율이다.","c":"상","v":1},"법무사2020_26-43-4":{"w":"공탁규칙 제52조: 공탁금 이자는 원금과 함께 지급하되 공탁금과 이자의 수령자가 다르면 원금을 지급한 뒤 이자를 지급할 수 있다.","c":"상","v":1},"법무사2020_26-45-1":{"w":"대공탁은 공탁 유가증권의 상환금을 보관자가 받아 그 금전을 계속 공탁하는 것이다(공탁법 제7조, 공탁규칙 제31조). 목적물만 금전으로 바뀌고 같은 공탁이 이어진다.","c":"중","v":1},"법무사2020_26-45-2":{"w":"공탁규칙 제31조 제5항: 공탁유가증권이 기명식이면 대공탁청구서에 공탁물보관자 앞으로 작성한 상환금 추심 위임장을 붙인다.","c":"상","v":1},"법무사2020_26-45-3":{"w":"공탁규칙 제31조 제6항: 대공탁과 부속공탁 청구절차의 추심비용은 청구인이 부담한다.","c":"상","v":1},"법무사2020_26-45-5":{"w":"대공탁으로 공탁은 동일성을 유지하지만 금전공탁으로 새로 관리되므로 공탁선례는 대공탁 상환금 회수청구권의 소멸시효를 대공탁일부터 기산한다고 본다.","c":"중","v":1},"법무사2020_26-47-1":{"w":"공탁규칙 제69조: 금전공탁사건의 신청·청구는 전자문서로 할 수 있고 5천만 원을 넘는 공탁금의 출급·회수 청구만 제외된다. 5천만 원 이하이면 전자청구할 수 있다.","c":"상","v":1},"법무사2020_26-47-3":{"w":"공탁규칙 제66조(공탁법 제5조 제1항): 국내에 주소·거소가 없는 외국인이나 재외국민을 위한 지참채무 변제공탁은 다른 법령이나 특약이 없으면 서울중앙지방법원 공탁관에게 할 수 있다.","c":"상","v":1},"법무사2020_26-47-4":{"w":"파산관재인의 배당액 공탁(채무자회생법 제528조)은 파산관재인이 직무를 하는 곳이 이행지다. 그래서 그곳을 관할하는 지방법원 공탁소에 공탁할 수 있다(공탁선례).","c":"중","v":1},"법무사2020_26-47-5":{"w":"공탁 실무 예규는 공탁당사자가 달라도 공탁원인사실·관할공탁소·공탁종류가 같으면 1건의 공탁서로 일괄 공탁할 수 있게 한다.","c":"중","v":1},"법무사2020_26-48-1":{"w":"적용 법조를 바로잡거나 반대급부를 철회하는 것은 피공탁자에게 불리하지 않고 공탁의 동일성에 영향이 없다. 그래서 공탁규칙 제30조 제1항에 따라 정정할 수 있다(공탁선례).","c":"중","v":1},"법무사2020_26-48-2":{"w":"집행공탁과 혼합공탁은 성질과 지급 절차가 달라 서로 바꾸는 정정은 동일성을 해친다. 그래서 허용되지 않는다(판례·공탁선례).","c":"중","v":1},"법무사2020_26-48-4":{"w":"공탁규칙 제76조: 전자공탁시스템으로 처리한 공탁사건의 정정신청은 전자공탁시스템을 이용하여 한다.","c":"상","v":1},"법무사2020_26-48-5":{"w":"공탁 정정에 관한 예규는 위임 대리인이 정정신청을 하면 대리권 증명서면에 인감을 찍고 인감증명서를 붙이게 한다. 정정은 공탁 내용을 바꾸는 행위여서 본인 의사를 엄격히 확인한다.","c":"중","v":1},"법무사2021_27-34-2":{"w":"공탁법 제3조는 대법원장이 공탁물 보관자를 지정하게 한다. 지정된 보관자가 특수한 물건을 보관할 능력이 없으면 민법 제488조 제2항에 따라 채무이행지 법원에 보관자 선임을 청구할 수 있다.","c":"중","v":1},"법무사2021_27-34-3":{"w":"공탁규칙 제20조 제2항 제5호는 피공탁자의 성명(명칭)·주소(본점·주사무소)·주민등록번호(법인등록번호)만 적게 한다. 법인 피공탁자의 대표자 성명·주소는 기재사항이 아니다.","c":"상","v":1},"법무사2021_27-34-4":{"w":"「공탁 신청 및 출급·회수에 대한 불수리결정 업무처리지침」(행정예규 제1013호)은 불수리결정등본을 신청인에게 교부하거나 배달증명우편으로 송달하게 한다(공탁규칙 제48조).","c":"중","v":1},"법무사2021_27-34-5":{"w":"불수리결정 업무처리지침은 불수리결정 원본과 공탁서·첨부서류를 공탁기록에 철해 보관하게 한다(공탁규칙 제48조 제2항 위임).","c":"중","v":1},"법무사2021_27-35-2":{"w":"공탁자를 바꾸는 것은 공탁의 주체를 바꾸는 것이어서 동일성을 해친다. 공탁규칙 제30조 제1항상 정정할 수 없다(공탁선례).","c":"중","v":1},"법무사2021_27-35-3":{"w":"유가증권공탁과 금전공탁은 목적물이 달라 동일성이 없다. 그래서 유가증권 공탁을 현금 공탁으로 바꾸는 정정은 허용되지 않는다(공탁선례).","c":"중","v":1},"법무사2021_27-35-4":{"w":"정정은 처음 공탁서의 착오를 바로잡는 것이어서 정정이 수리되면 최초 공탁 때부터 정정된 내용으로 공탁한 것이 된다는 것이 공탁선례다.","c":"중","v":1},"법무사2021_27-35-5":{"w":"수용보상금은 반대급부 없이 지급해야 하는 것이어서 서류 제공 조건을 붙인 공탁은 부당하다. 그 조건을 철회하는 정정은 피공탁자에게 유리해 허용된다(공탁선례).","c":"중","v":1},"법무사2021_27-42-1":{"w":"공탁규칙 제79조 제2항: 변호사·법무사 회원이 전자문서로 지급청구를 하면 청구인 본인의 전자서명도 함께 제출해야 한다.","c":"상","v":1},"법무사2021_27-42-2":{"w":"공탁규칙 제70조 제1항은 인증서로 전자공탁시스템에서 사용자등록을 하게 한다. 제3항은 대법원예규로 정하는 법인회원만 공탁소 출석을 요구한다. 법인 전자증명서를 쓰는 법인회원은 출석 없이 등록할 수 있다(전자공탁 사무처리지침).","c":"중","v":1},"법무사2021_27-42-4":{"w":"전자공탁 사무처리지침은 공동의 이해관계가 있는 여러 당사자나 대리인이 함께 출급을 신청하면 전원이 전자서명한 하나의 전자문서로 제출할 수 있게 한다.","c":"중","v":1},"법무사2021_27-42-5":{"w":"공탁규칙 제78조와 전자공탁 사무처리지침은 전자신청 공탁을 수리하면 납입기한을 정해 가상계좌로 공탁금(공탁통지 우편료 포함)을 납입하게 한다.","c":"중","v":1},"법무사2021_27-43-1":{"w":"「계좌입금에 의한 공탁금 납입 업무처리지침」은 가상계좌로 납입되기 전까지는 공탁자가 가상계좌 납입 신청을 철회하고 공탁금보관자에게 직접 납입할 수 있게 한다.","c":"중","v":1},"법무사2021_27-43-2":{"w":"가상계좌 납입 지침은 납입마감일 통상 업무시간까지 납입하지 않으면 사유를 묻지 않고 그 공탁사건을 실효처리하는 것을 원칙으로 한다. 공탁은 납입으로 성립하기 때문이다.","c":"중","v":1},"법무사2021_27-43-4":{"w":"공탁규칙 제28조 제2항·제3항: 가상계좌로 납입되면 공탁금보관자가 공탁관에게 전송하고 공탁관은 공탁서에 납입 사실을 적어 공탁자에게 내주거나 배달증명 우편으로 보낸다.","c":"상","v":1},"법무사2021_27-43-5":{"w":"가상계좌 납입 지침은 착오로 납입한 경우 납입 당일 통상 업무시간 전까지 납입취소신청서에 공탁관 확인을 받아 공탁금보관자에게 취소를 요청할 수 있게 한다.","c":"중","v":1},"법무사2021_27-48-1":{"w":"여러 공탁자가 공탁금액을 나누지 않고 하나로 적었으면 각자의 출연 비율을 알 수 없다. 공탁선례는 민법 제408조(분할채권관계) 취지에 따라 균등 비율로 공탁한 것으로 본다.","c":"하","v":1},"법무사2021_27-48-2":{"w":"변제공탁의 피공탁자는 공탁자가 공탁서에 지정한다(공탁규칙 제20조 제2항 제5호). 판례는 피공탁자가 공탁서 기재로 형식적으로 정해진다고 본다.","c":"중","v":1},"법무사2021_27-48-4":{"w":"공탁규칙 제21조 제2항은 대리인이 공탁하면 대리권 증명서면을 붙이게 한다. 공탁도 대리로 할 수 있다는 전제다.","c":"상","v":1},"법무사2021_27-48-5":{"w":"공탁물보관자는 은행·창고업자이고(공탁법 제3조) 부동산은 보관할 수 없다. 그래서 부동산 자체는 변제공탁의 목적물이 될 수 없고 민법 제490조의 자조매각으로 대금을 공탁한다.","c":"중","v":1},"법무사2021_27-50-4":{"w":"공탁규칙 제23조 제1항: 공탁자가 피공탁자에게 공탁통지를 해야 하면 피공탁자 수만큼 공탁통지서를 첨부한다.","c":"상","v":1},"법무사2022_28-34-1":{"w":"공탁규칙 제55조에 따라 지방법원장·지원장이 지정한 대리공탁관은 대직 기간 자기 명의로 공탁사무를 처리하는 독립한 공탁관이다. 그 사무에 대한 책임도 스스로 진다(공탁 실무).","c":"중","v":1},"법무사2022_28-34-2":{"w":"판례는 공탁관의 심사 방법을 공탁서·청구서와 첨부서면에 의한 형식적 심사로 제한하되, 그 서면 범위 안에서 절차적 요건과 실체적 요건을 모두 심사한다고 본다.","c":"중","v":1},"법무사2022_28-34-4":{"w":"상법 제491조 제4항 등에 따라 무기명사채권자가 의결권을 행사하려면 채권을 공탁해야 한다. 시·군법원은 공탁규칙 제2조상 직무가 아니어서 제외된다. 공탁관 외에 대법원장이 지정한 은행·신탁회사에도 공탁할 수 있다(공탁 실무).","c":"중","v":1},"법무사2022_28-34-5":{"w":"변제공탁은 채무이행지 공탁소에 해야 하므로(민법 제488조 제1항) 관할 없는 공탁은 원칙적으로 무효이고 착오공탁으로 회수할 수 있다. 판례는 피공탁자가 수락하거나 출급하면 흠이 치유되어 처음부터 유효하다고 본다.","c":"중","v":1},"법무사2022_28-37-1":{"w":"대공탁은 유가증권 상환금으로 금전공탁이 되는 경우뿐이다(공탁규칙 제31조). 담보물변경(민사소송법 제126조)은 유가증권→금전, 금전→유가증권, 유가증권→다른 유가증권 변경을 모두 포함한다.","c":"중","v":1},"법무사2022_28-37-2":{"w":"대공탁은 공탁의 동일성을 유지하므로 담보 관계도 그대로 유지된다. 그래서 담보를 명한 관청의 승인이 필요 없다(공탁 실무).","c":"중","v":1},"법무사2022_28-37-3":{"w":"공탁규칙 제31조 제3항에 따라 공탁관이 대공탁청구서와 출급의뢰서를 내주면 공탁물보관자는 영수인을 찍어 돌려주고 유가증권을 출급해 상환금을 추심한 뒤 공탁관 계좌에 대공탁금으로 입금한다(공탁 실무 예규).","c":"중","v":1},"법무사2022_28-37-4":{"w":"공탁규칙 제31조 제4항은 대공탁·부속공탁 청구에 제22조를 준용한다. 같은 사람이 동시에 같은 법원에 여러 건을 청구하면 같은 첨부서면은 1건에만 붙이고 나머지에는 그 뜻을 적는다.","c":"상","v":1},"법무사2022_28-45-1":{"w":"민법 제488조 제1항·제2항: 변제공탁은 채무이행지 공탁소에 한다. 공탁소에 관한 특별규정이 없으면 법원이 변제자의 청구로 공탁소를 지정하고 공탁물보관자를 선임한다.","c":"상","v":1},"법무사2022_28-45-2":{"w":"「관할공탁소 이외의 공탁소에서의 공탁사건처리 지침」(행정예규 제1167호)은 관할공탁소와 멀리 떨어진 당사자가 가까운 다른 공탁소에서 금전변제공탁 신청을 할 수 있게 한다.","c":"상","v":1},"법무사2022_28-45-4":{"w":"여신전문금융업법상 선불카드 발행 신용카드업자의 보증공탁은 그 업자의 본점이나 주된 사무소 소재지 공탁소에 하도록 정해져 있다(같은 법 시행령, 공탁 실무).","c":"중","v":1},"법무사2022_28-45-5":{"w":"공탁규칙 제2조 제1호: 해당 시·군법원에 계속 중이거나 처리한 소액사건·화해·독촉·조정사건의 채무 이행으로 하는 민법 제487조·제488조 변제공탁은 시·군법원 공탁관 직무에 속한다.","c":"상","v":1},"법무사2022_28-46-1":{"w":"공탁금액은 공탁의 핵심 내용이어서 이를 바꾸면 동일성을 해치며 공탁규칙 제12조 제2항도 금액 숫자 정정을 금지한다. 착오 공탁은 착오를 증명해 회수(공탁법 제9조 제2항 제2호)한 뒤 다시 공탁한다.","c":"중","v":1},"법무사2022_28-46-3":{"w":"공탁원인사실의 근거 법령 조항을 바로잡는 것은 표현상 착오 정정이어서 공탁의 동일성에 영향이 없다. 공탁규칙 제30조 제1항으로 허용된다(공탁선례).","c":"중","v":1},"법무사2022_28-46-4":{"w":"부당한 반대급부 조건을 붙인 공탁은 무효지만 그 조건을 철회하는 정정은 피공탁자에게 유리해 허용된다. 정정이 수리되면 그때부터 조건 없는 공탁으로 효력이 있다(판례·공탁선례).","c":"중","v":1},"법무사2022_28-46-5":{"w":"이름·주민등록번호가 같으면 동일인이고 주소만 잘못 적은 것은 표현상 착오다. 주민등록초본을 붙여 주소를 정정할 수 있다(공탁규칙 제30조).","c":"중","v":1},"법무사2022_28-49-1":{"w":"판례는 피공탁자가 아닌 제3자는 공탁물 출급청구권 귀속을 직접 다툴 지위에 없어 특별한 사정이 없으면 피공탁자를 상대로 출급청구권 확인을 구할 이익이 없다고 본다.","c":"중","v":1},"법무사2022_28-49-2":{"w":"판례는 상대적 불확지공탁 피공탁자 1인의 출급청구권을 압류·추심한 채권자가 자기 이름으로 다른 피공탁자를 상대로 그 출급청구권이 자기 채무자에게 있다는 확인의 소를 낼 수 있다고 본다.","c":"중","v":1},"법무사2022_28-49-4":{"w":"대항력 있는 주택 양수인은 임대인 지위를 승계해 보증금반환채무를 진다(주택임대차보호법 제3조 제4항). 판례는 가압류된 보증금채권의 제3채무자 지위도 승계되어 양수인이 등기사항증명서를 붙여 집행공탁을 할 수 있다고 본다.","c":"중","v":1},"법무사2022_28-49-5":{"w":"해방공탁금은 가압류채무자가 낸 경우에 그의 공탁금 회수청구권에 가압류 효력이 미친다. 판례는 제3자가 낸 해방공탁금에는 가압류채무자에 대한 집행권원으로 집행할 수 없다고 본다.","c":"중","v":1},"법무사2022_28-50-5":{"w":"공탁규칙 제21조 제3항의 주소불명 소명서면은 최종주소 소명서면과 그곳에 살지 않는다는 소명자료다. 공탁 실무는 공탁 원인이 된 계약서도 최종주소 소명서면으로 인정한다.","c":"중","v":1},"법무사2023_29-36-1":{"w":"민사집행법 제282조는 가압류해방금액을 금전으로 정하게 한다. 그래서 해방공탁은 금전으로만 한다(판례).","c":"중","v":1},"법무사2023_29-36-2":{"w":"민법 제490조: 변제 목적물이 공탁에 적당하지 않거나 멸실·훼손 염려가 있거나 공탁 비용이 과다하면 변제자는 법원 허가를 얻어 경매하거나 시가로 팔아 대금을 공탁할 수 있다.","c":"상","v":1},"법무사2023_29-36-4":{"w":"공탁규칙 제24조: 기명식 유가증권을 공탁하면 수령하는 자가 즉시 권리를 얻을 수 있도록 배서하거나 양도증서를 첨부한다.","c":"상","v":1},"법무사2023_29-36-5":{"w":"토지보상법 제63조는 현금 보상을 원칙으로 하고 법이 정한 경우에만 채권 보상을 허용한다. 현금으로 지급하게 되어 있으면 채권으로 지급하거나 공탁할 수 없다(공탁선례).","c":"중","v":1},"법무사2023_29-38-1":{"w":"지급위탁서 송부와 자격증명서 교부는 배당절차에서 집행법원이 하는 집행처분이다. 그래서 불복은 공탁법 제12조 이의가 아니라 민사집행법 제16조 집행에 관한 이의로 한다(공탁선례).","c":"중","v":1},"법무사2023_29-38-2":{"w":"불수리결정 업무처리지침은 불수리 후 이의신청이 없으면 불수리결정 연도 다음 해부터, 이의가 기각·각하되면 그 결정 다음 해부터 5년간 공탁기록을 보존하게 한다.","c":"중","v":1},"법무사2023_29-38-4":{"w":"공탁법 제12조 제2항: 이의신청은 공탁소에 이의신청서를 제출함으로써 한다. 관할은 지방법원이다(제1항).","c":"상","v":1},"법무사2023_29-38-5":{"w":"판례는 공탁관이 형식적 심사권만 가지므로 법원도 이의를 심리할 때 처분 당시 제출된 서류로 처분이 정당했는지 판단해야 한다고 본다.","c":"중","v":1},"법무사2023_29-39-1":{"w":"공탁관은 형식적 심사권만 있어 피공탁자에게 조건 이행 의무가 있는지 같은 실체 관계를 따질 수 없다. 조건부 공탁의 효력은 소송에서 다툰다(공탁선례).","c":"중","v":1},"법무사2023_29-39-2":{"w":"공탁관은 형식적 심사권만 있어 전부명령의 유효 여부를 판단할 수 없다. 서류상 회수청구권이 압류·전부되었으면 회수청구를 불수리한 것은 정당하다는 것이 판례다.","c":"중","v":1},"법무사2023_29-39-3":{"w":"판례는 피담보채무 변제가 말소등기보다 먼저여서 특약 없이 말소서류 교부를 반대급부로 한 변제공탁은 효력이 없다고 본다. 공탁관은 특약 유무를 심사할 수 없어 그런 공탁신청도 수리할 수밖에 없다.","c":"중","v":1},"법무사2023_29-39-4":{"w":"형식적 심사권 안에서도 공탁서와 첨부서면 자체로 공탁 사유가 없거나 채무 부존재가 명백하면 불수리할 수 있다는 것이 판례·공탁선례다.","c":"중","v":1},"법무사2023_29-40-1":{"w":"사해행위취소 원상회복을 위한 채권처분금지가처분은 채무자의 처분만 막을 뿐 변제 수령을 금지하지 않는다. 공탁선례는 이 경우 제3채무자가 수령불능을 원인으로 가처분채무자를 피공탁자로 확지공탁을 한다고 본다.","c":"중","v":1},"법무사2023_29-40-2":{"w":"민법 제353조 제3항: 입질채권의 변제기가 질권자 채권의 변제기보다 먼저 오면 질권자는 제3채무자에게 공탁을 청구할 수 있다. 이 공탁의 피공탁자는 채권자인 질권설정자다.","c":"중","v":1},"법무사2023_29-40-3":{"w":"가압류해방공탁은 가압류채무자가 집행을 풀기 위해 자기 돈을 맡기는 것이다(민사집행법 제282조). 수령할 자가 정해지지 않아 공탁서에 피공탁자를 적지 않는다.","c":"중","v":1},"법무사2023_29-40-5":{"w":"민사집행법상 압류와 체납처분 압류가 있고 총액이 채권액을 넘지 않아도 제3채무자는 제248조 제1항으로 압류 관련 채권 전액을 공탁할 수 있다. 이때 피공탁자는 압류채무자로 적는다(판례·공탁선례).","c":"중","v":1},"법무사2023_29-45-1":{"w":"공탁규칙 제78조 제1항: 전자공탁시스템으로 공탁하면 공탁관은 공탁물보관자에게 가상계좌번호를 요청해 그 계좌로 공탁금을 납입하게 한다.","c":"상","v":1},"법무사2023_29-45-2":{"w":"공탁법 제4조는 공탁서를 내고 공탁물을 보관자에게 납입하게 한다. 판례·통설은 공탁이 공탁물 납입으로 성립한다고 본다. 수리만으로는 공탁 효력이 없다.","c":"중","v":1},"법무사2023_29-45-4":{"w":"공탁규칙 제28조 제3항: 가상계좌 납입 전송을 받은 공탁관은 공탁서에 납입 사실을 적어 공탁자에게 내주거나 배달증명 우편으로 보낸다.","c":"상","v":1},"법무사2023_29-45-5":{"w":"가상계좌 납입 지침은 납입마감일 업무시간까지 납입하지 않으면 사유를 묻지 않고 실효처리를 원칙으로 한다. 공탁은 납입으로 성립하기 때문이다.","c":"중","v":1},"법무사2023_29-46-1":{"w":"공탁규칙 제59조 제1항은 열람을 공탁당사자와 이해관계인에게만 허용한다. 압류할 목적만 가진 피공탁자의 채권자는 이해관계인이 아니어서 열람할 수 없다(공탁선례).","c":"중","v":1},"법무사2023_29-46-2":{"w":"공탁규칙 제59조 제2항: 위임 대리인이 열람을 청구하면 대리권 증명서면에 인감을 찍고 인감증명서를 붙인다. 자격자대리인이 직접 청구하면 예외다(제3항).","c":"상","v":1},"법무사2023_29-46-3":{"w":"공탁선례와 공탁금 소멸시효에 관한 예규는 지급되지 않은 사건에서 공탁 확인 목적으로 공탁관계 서류를 열람시키면 공탁관이 채무를 승인한 것으로 보아 소멸시효가 중단된다고 본다.","c":"중","v":1},"법무사2023_29-46-5":{"w":"전자공탁 사무처리지침은 전자문서로 제출된 공탁관계서류 열람과 전자공탁으로 처리한 사무의 사실증명을 전자공탁시스템으로 청구할 수 있게 한다.","c":"중","v":1},"법무사2023_29-50-3":{"w":"행정예규 제1167호 4.는 공탁자와 지급청구인이 접수공탁소에 서류와 함께 원본 송부용 우표 붙인 봉투를 내게 한다. 현행 지침 문구는 송부 방법을 「등기속달 우편」으로 적고 있다.","c":"중","v":1},"법무사2024_30-31-2":{"w":"가압류를 원인으로 한 집행공탁은 가압류채무자가 피공탁자다. 공탁 실무 예규는 공탁관이 피공탁자에게 공탁통지서를 보내고 가압류채권자에게는 공탁사실을 통지하게 한다.","c":"중","v":1},"법무사2024_30-31-3":{"w":"공탁규칙 제85조는 형사공탁(공탁법 제5조의2)이 있으면 공탁관이 그 형사사건이 계속 중인 법원과 검찰에 형사공탁 사실을 통지하게 한다.","c":"상","v":1},"법무사2024_30-31-4":{"w":"가압류 후 채권양도통지를 받아 한 혼합공탁은 양도인·양수인이 피공탁자다. 공탁관은 피공탁자에게 공탁통지서를 보내고 가압류채권자에게 공탁사실을 통지한다(공탁 실무 예규).","c":"중","v":1},"법무사2024_30-31-5":{"w":"가압류와 체납처분 압류의 경합으로 한 집행공탁에서 공탁관은 피공탁자에게 공탁통지서를, 가압류채권자와 체납처분권자에게 공탁사실 통지를 한다(공탁 실무 예규).","c":"중","v":1},"법무사2024_30-40-1":{"w":"공탁규칙 제30조 제1항: 공탁신청이 수리된 뒤 착오 기재를 발견하면 공탁의 동일성을 해치지 않는 범위에서만 정정할 수 있다.","c":"상","v":1},"법무사2024_30-40-2":{"w":"집행공탁과 혼합공탁은 성질과 지급 절차가 달라 서로 바꾸는 정정은 동일성을 해친다(판례·공탁선례).","c":"중","v":1},"법무사2024_30-40-3":{"w":"피공탁자(공탁물 수령자)는 공탁의 요건이어서 이를 추가하면 공탁 내용이 달라진다. 그래서 공탁규칙 제30조 제1항상 허용되지 않는다(공탁선례).","c":"중","v":1},"법무사2024_30-40-4":{"w":"판례는 부당한 반대급부 조건부 공탁이라도 조건 철회 정정이 수리되면 다른 유효요건을 갖춘 이상 그때부터 조건 없는 변제공탁으로 효력이 있다고 본다. 소급하지 않는다.","c":"중","v":1},"법무사2025_31-35-1":{"w":"대공탁은 공탁 유가증권의 상환금을 계속 공탁하는 것이어서 목적물만 금전으로 바뀌고 같은 공탁이 이어진다(공탁규칙 제31조, 공탁 실무).","c":"중","v":1},"법무사2025_31-35-3":{"w":"민사소송법 제126조: 담보제공 명령 법원은 담보제공자 신청으로 공탁한 담보물을 바꾸도록 명할 수 있다. 다만 당사자가 계약으로 다른 담보로 바꾸기로 했으면 그에 따른다.","c":"상","v":1},"법무사2025_31-35-4":{"w":"민사소송법 제126조는 담보물변경을 담보제공 결정을 한 법원이 하게 한다. 공탁 실무는 그 기록을 보관하는 법원도 관할한다고 본다.","c":"중","v":1},"법무사2025_31-35-5":{"w":"민사소송법 제126조의 담보물변경은 법원의 결정으로 하므로 변경 허가 여부는 법원 재량이다. 금전 담보를 유가증권으로 바꾸는 것도 같다.","c":"중","v":1},"법무사2025_31-38-1":{"w":"유가증권 일부를 현금으로 바꾸는 것은 일부 회수 후 새 공탁을 하는 것과 같아 목적물의 동일성이 없다. 그래서 정정으로 할 수 없다(공탁선례).","c":"중","v":1},"법무사2025_31-38-2":{"w":"상대적 불확지공탁을 확지공탁으로 바꾸는 것은 피공탁자를 바꾸는 것이어서 동일성을 해친다. 나중에 피보전권리가 밝혀져도 정정할 수 없다(공탁선례).","c":"중","v":1},"법무사2025_31-38-4":{"w":"정정의 효력은 원칙적으로 최초 공탁 때로 소급하지만 판례는 반대급부 조건 철회 정정은 그때부터 조건 없는 공탁으로 효력이 생길 뿐 소급하지 않는다고 본다.","c":"중","v":1},"법무사2025_31-38-5":{"w":"집행공탁 전에 송달된 압류·가압류를 공탁원인사실에서 빠뜨린 것은 기재 누락이어서 집행공탁의 동일성에 영향이 없다. 그래서 추가 정정을 수리할 수 있다(공탁선례).","c":"중","v":1},"법무사2025_31-44-1":{"w":"「재외국민 등의 공탁에 관한 업무처리지침」(행정예규 제1431호) 제5조 제1항: 공탁당사자가 재외국민이면 공탁서의 주민등록번호란에 여권번호를 적을 수 있다.","c":"상","v":1},"법무사2025_31-44-2":{"w":"행정예규 제1431호 제5조 제2항: 공탁당사자가 외국인이면 주민등록번호란에 여권번호·외국인등록번호·국내거소신고번호를 적을 수 있다.","c":"상","v":1},"법무사2025_31-44-4":{"w":"행정예규 제1431호 제7조: 재외국민·외국인 피공탁자의 주소가 불명이면 공탁 원인 서면상 주소를 최종주소지로 적고 그곳에 살지 않는다는 소명서면(반송된 최근 배달증명서 등)을 낸다.","c":"상","v":1},"법무사2025_31-44-5":{"w":"행정예규 제1431호 제2조 제1항: 외국 공문서나 외국 공증 문서는 재외공관 공증법 제30조 제1항의 영사 확인이나 아포스티유를 받되, 미수교·비가입국 등 부득이한 경우는 예외다.","c":"상","v":1},"법무사2025_31-47-1":{"w":"공탁법 제12조 제1항: 공탁관의 처분에 불복하는 자는 관할 지방법원에 이의신청을 할 수 있다.","c":"상","v":1},"법무사2025_31-47-2":{"w":"공탁법 제13조: 공탁관은 이의가 이유 있으면 신청 취지대로 처분하고 신청인에게 알린다. 이유 없으면 이의신청서를 받은 날부터 5일 안에 의견을 붙여 관할 지방법원에 보낸다.","c":"상","v":1},"법무사2025_31-47-3":{"w":"공탁법 제14조 제1항: 관할 지방법원은 이의신청에 이유를 붙인 결정으로 하고 공탁관과 이의신청인에게 결정문을 송부한다.","c":"상","v":1},"법무사2025_31-47-5":{"w":"공탁법 제14조 제2항: 이의신청인은 관할 지방법원의 결정에 대하여 비송사건절차법에 따라 항고할 수 있다.","c":"상","v":1},"법무사2026_32-31-1":{"w":"공탁법 제5조 제1항과 공탁규칙 제66조: 국내에 주소·거소가 없는 외국인·재외국민을 위한 지참채무 변제공탁은 다른 법령이나 특약이 없으면 서울중앙지방법원 공탁관에게 할 수 있다.","c":"상","v":1},"법무사2026_32-31-2":{"w":"지참채무는 채권자의 현주소가 이행지이고(민법 제467조 제2항) 변제공탁은 이행지 공탁소에 한다(제488조 제1항). 상속인이 여럿이면 각 상속인 주소지 공탁소에 할 수 있다(공탁선례).","c":"중","v":1},"법무사2026_32-31-3":{"w":"추심채무는 채무자의 주소나 영업소가 이행지다. 그래서 상속인을 피공탁자로 하더라도 공탁자(채무자)의 주소지나 영업소 소재지 공탁소에 공탁한다(민법 제488조 제1항, 공탁선례).","c":"중","v":1},"법무사2026_32-31-5":{"w":"변제공탁은 채무 내용에 따라 이행지 공탁소에 해야 하므로(민법 제488조 제1항) 관할 없는 공탁소에 한 공탁은 원칙적으로 무효다. 공탁자는 착오공탁으로 회수할 수 있다(공탁법 제9조 제2항 제2호, 판례).","c":"중","v":1},"법무사2026_32-41-2":{"w":"청산종결등기 후에도 청산사무가 남아 있으면 그 범위에서 회사는 존속한다는 것이 판례다. 그래서 공탁당사자능력이 있다.","c":"중","v":1},"법무사2026_32-41-3":{"w":"민법 제5조 제1항 단서는 권리만 얻거나 의무만 면하는 행위를 미성년자가 단독으로 하게 한다. 그 범위에서는 공탁행위능력도 인정된다(공탁 실무).","c":"중","v":1},"법무사2026_32-41-4":{"w":"판례는 피공탁자가 실체법상 채권자가 누구인지와 관계없이 공탁서 기재에 따라 형식적으로 정해진다고 본다.","c":"중","v":1},"법무사2026_32-41-5":{"w":"공탁규칙 제21조 제1항은 법인 아닌 사단·재단이 공탁하면 정관·규약과 대표자 자격 증명서면을 내게 한다. 대표자나 관리인이 있으면 공탁당사자능력이 있다는 전제다.","c":"중","v":1},"법무사2026_32-44-1":{"w":"공탁규칙 제48조 제1항: 공탁관이 공탁신청이나 출급·회수청구를 불수리할 때에는 이유를 적은 결정으로 한다.","c":"상","v":1},"법무사2026_32-44-2":{"w":"「공탁 신청 및 출급·회수에 대한 불수리결정 업무처리지침」은 불수리결정등본을 신청인·청구인에게 교부하거나 배달증명우편으로 송달하게 한다.","c":"중","v":1},"법무사2026_32-44-3":{"w":"불수리결정 업무처리지침은 불수리결정 원본과 공탁서(또는 출급·회수청구서) 및 그 밖의 첨부서류를 공탁기록에 철해 보관하게 한다.","c":"중","v":1},"법무사2026_32-44-5":{"w":"불수리결정 업무처리지침은 신청인 등이 첨부서류 반환을 청구하면 복사본과 영수증을 공탁기록에 철하고 원본을 돌려주게 한다.","c":"중","v":1},"법무사2016_22-33-2":{"w":"양도통지 뒤 철회 등으로 양도가 적법한지 의문이 있으면 채무자는 과실 없이 채권자를 알 수 없는 경우(민법 제487조 후단)에 해당한다는 것이 판례다. 그래서 채권자 불확지 변제공탁을 할 수 있다.","c":"하","v":1},"법무사2016_22-33-3":{"w":"사해행위취소 원상회복을 위한 처분금지가처분은 채무자의 처분만 막고 채권 귀속 자체를 다투는 것이 아니다. 공탁선례는 이 경우 수령불능을 원인으로 가처분채무자를 피공탁자로 한 확지공탁을 하고 불확지공탁은 할 수 없다고 본다.","c":"중","v":1},"법무사2016_22-33-4":{"w":"판례는 보상금 총액은 정해졌으나 수령권자가 불분명하고 배분 금액까지 다투는 경우 다투는 자 전원을 피공탁자로 한 채권자 불확지 변제공탁을 허용한다.","c":"중","v":1},"법무사2016_22-33-5":{"w":"판례는 예금주 사망 후 금융기관이 선관주의를 다해도 상속인 전부나 일부를 알 수 없으면 과실 없이 채권자를 알 수 없는 경우로 보아 불확지 변제공탁을 허용한다(민법 제487조 후단).","c":"하","v":1},"법무사2016_22-49-1":{"w":"차임은 사용·수익의 대가여서 그 기간이 지나야 발생한다. 그래서 장래 차임은 기한의 이익을 포기하고 미리 공탁할 수 없다는 것이 공탁선례다.","c":"중","v":1},"법무사2016_22-49-2":{"w":"불법행위 손해배상채무는 불법행위일부터 지체책임이 생긴다는 것이 판례다. 그래서 채무자는 스스로 인정하는 원금에 불법행위일부터 제공일까지의 지연손해금을 더해 공탁할 수 있다.","c":"중","v":1},"법무사2016_22-49-3":{"w":"가집행선고부 판결 금액은 확정 전이라도 채무자가 변제제공할 수 있고 채권자가 수령을 거절하면 민법 제487조 전단의 수령거절에 해당한다. 그래서 변제공탁을 할 수 있다(공탁선례).","c":"중","v":1},"법무사2016_22-49-5":{"w":"제한능력자인 채권자에게 법정대리인이 없으면 유효하게 변제를 수령할 사람이 없다. 이는 법률상 수령불능이어서 민법 제487조 전단에 따라 변제공탁을 할 수 있다(공탁선례).","c":"중","v":1},"법무사2017_23-45-4":{"w":"판례는 근저당권 피담보채무의 일부만 공탁하면 계속적 거래에서 생긴 다수 채무의 집합체라도 공탁 금액만큼 채무가 소멸하지 않는다고 본다. 일부공탁은 채권자가 수락하지 않는 한 효력이 없다.","c":"중","v":1},"법무사2017_23-50-1":{"w":"판례는 채권자가 공탁금을 약정이율 기준으로 충당하고 나머지를 청구하는 취지의 청구취지감축서를 채무자에게 송달한 뒤 수령했다면 일부로 수령한다는 묵시적 이의유보가 있다고 본다.","c":"중","v":1},"법무사2017_23-50-2":{"w":"판례는 공탁원인이 법률상 효력이 없어 공탁이 부적법해도 피공탁자가 이의를 유보하지 않고 수령하면 공탁자가 주장한 원인대로 법률효과가 생긴다고 본다.","c":"중","v":1},"법무사2017_23-50-3":{"w":"판례는 채무자가 충당할 채무를 지정해 공탁하고 채권자가 이의 없이 수령하면 그 지정대로 변제충당된다고 본다(민법 제476조 참조).","c":"중","v":1},"법무사2017_23-50-4":{"w":"판례는 이의유보 의사표시의 상대방이 공탁관에 한정되지 않고 공탁자에게 해도 된다고 본다.","c":"중","v":1},"법무사2018_24-31-5":{"w":"분할 전 대장에는 甲, 분할 후 대장에는 乙로 되어 있으면 누가 진정한 소유자인지 알 수 없어 공탁선례는 「甲 또는 乙」을 피공탁자로 한 상대적 불확지공탁(토지보상법 제40조 제2항 제2호)을 인정했다. 다만 2023. 6. 1. 개정된 토지수용 보상금 공탁 사무처리지침 제5조 제1항의 열거 사유에는 이 경우가 따로 적혀 있지 않다.","c":"하","v":1},"법무사2019_25-33-1":{"w":"토지수용 보상금 공탁 사무처리지침은 보상금이 소득세법 제156조나 법인세법 제98조의 원천징수 대상이면 원천징수세액을 공제한 나머지를 공탁할 수 있게 한다. 원천징수는 법률상 의무이기 때문이다.","c":"중","v":1},"법무사2019_25-33-2":{"w":"절대적 불확지 공탁 후 피공탁자를 알면 사업시행자가 피공탁자를 지정하는 정정을 할 수 있다(토지수용 보상금 공탁 사무처리지침). 정정은 원칙적으로 최초 공탁 때로 소급한다(공탁선례).","c":"중","v":1},"법무사2019_25-33-3":{"w":"판례는 공탁서상 피공탁자로 지정된 자는 공탁관에게 직접 출급청구권을 행사하면 되므로 소유권 분쟁 상대방에게 출급청구권 확인을 구할 이익이 없다고 본다.","c":"중","v":1},"법무사2019_25-33-4":{"w":"수용 개시일에 등기명의인인 매도인에게 보상금을 공탁하면 수용 효력이 생기고 출급청구권은 피공탁자인 매도인에게 있다. 판례는 매수인이 그 뒤 이전등기를 해도 출급청구권을 양수받지 않으면 직접 출급할 수 없다고 본다.","c":"중","v":1},"법무사2019_25-37-1":{"w":"매월 지급하는 손해보상금은 매월 이행기가 오므로 이미 지난 여러 달 분은 모아서 공탁할 수 있다. 아직 이행기가 오지 않은 장래분은 미리 공탁할 수 없다(공탁선례).","c":"중","v":1},"법무사2019_25-37-2":{"w":"변제공탁은 금전 등 채무 일반에 대해 할 수 있고 공법상 채무도 수령거절 등 공탁 사유가 있으면 할 수 있다. 공탁선례는 조세채무와 국민연금 보험료 채무도 변제공탁 대상으로 본다.","c":"중","v":1},"법무사2019_25-37-3":{"w":"판례는 채무자 겸 설정자는 채무 전액을 갚아야 근저당권 말소를 구할 수 있으므로 채권최고액과 비용만 공탁하면 일부공탁이어서 원칙적으로 무효라고 본다.","c":"중","v":1},"법무사2019_25-37-5":{"w":"판례는 근저당 피담보채무의 일부만 공탁하면 계속적 거래로 생긴 채무 집합체라도 그 금액만큼 채무가 소멸하지 않는다고 본다.","c":"중","v":1},"법무사2020_26-42-3":{"w":"공탁법 제10조는 반대급부 증명서면으로 공탁자의 서면·판결문·공정증서·관공서 공문서 등을 든다. 피공탁자가 반대급부를 변제공탁하고 받은 공탁서도 이에 해당한다(공탁선례).","c":"중","v":1},"법무사2020_26-50-1":{"w":"판례는 근저당 피담보채무의 일부 공탁은 채무 집합체라도 그 금액만큼 채무소멸 효과가 없다고 본다. 일부공탁은 채권자가 수락하지 않으면 효력이 없다.","c":"중","v":1},"법무사2020_26-50-2":{"w":"판례는 공탁금이 채무 총액보다 아주 조금 부족한 경우에는 신의칙상 그 변제공탁을 유효로 본다.","c":"중","v":1},"법무사2020_26-50-3":{"w":"제3취득자는 채권최고액까지만 책임을 지므로(민법 제364조) 최고액과 경매비용을 공탁하면 근저당권 소멸을 청구할 수 있다는 것이 판례다. 그래서 그 변제공탁은 유효하다.","c":"중","v":1},"법무사2020_26-50-4":{"w":"판례는 채무자 겸 설정자는 최고액을 넘는 채무 전부를 갚아야 하므로 최고액·지연손해금·집행비용만 공탁하면 일부공탁으로 원칙적으로 무효라고 본다.","c":"중","v":1},"법무사2021_27-41-1":{"w":"공탁통지서는 피공탁자에게 출급청구권을 알리는 것이다. 공탁 실무 예규는 발송 전이라도 피공탁자가 공탁소에 출석해 교부를 청구할 수 있게 한다.","c":"중","v":1},"법무사2021_27-41-3":{"w":"반송된 공탁통지서를 대리인이 받으려면 본인 의사 확인이 필요하다. 공탁 실무 예규는 피공탁자 본인 인감을 찍은 위임장과 인감증명서를 내게 한다.","c":"하","v":1},"법무사2021_27-41-4":{"w":"주소불명으로 반송되면 공탁서의 피공탁자 주소가 잘못된 것이어서 공탁자가 주소 정정신청을 할 수 있다(공탁규칙 제30조 제6항, 「공탁통지서가 반송된 경우의 업무처리지침」).","c":"중","v":1},"법무사2021_27-41-5":{"w":"전자공탁시스템으로 제출된 공탁통지서는 전자적으로 보관되어 있어 반송된 출력물은 공탁관이 폐기할 수 있다(전자공탁 사무처리지침, 공탁통지서 반송 처리지침).","c":"중","v":1},"법무사2021_27-46-1":{"w":"개인회생 변제금 공탁에 관한 예규(「개인회생절차에서 회생위원의 공탁」 관련 행정예규)는 계좌번호를 회생위원에게 신고하지 않은 개인회생채권자에게 줄 변제액을 변제계획에 따라 회생위원이 공탁할 수 있게 한다. 받을 계좌를 몰라 지급할 수 없기 때문이다.","c":"중","v":1},"법무사2021_27-46-2":{"w":"개인회생절차 공탁 예규는 변제계획 불인가·폐지 등으로 회생위원이 임치금을 채무자에게 돌려줄 수 없는 경우 채무자를 위해 공탁할 수 있게 한다.","c":"중","v":1},"법무사2021_27-46-3":{"w":"개인회생절차 공탁 예규는 회생위원이 공탁할 때 계좌입금에 의한 공탁금 납입(공탁규칙 제28조)을 신청하게 한다.","c":"중","v":1},"법무사2021_27-46-5":{"w":"개인회생절차 공탁 예규는 공탁금을 출급하려는 채권자나 채무자에게 회생위원이 자격증명서를 주게 한다. 출급할 때 공탁규칙 제33조의 권리 증명서면으로 쓴다.","c":"중","v":1},"법무사2022_28-35-2":{"w":"판례는 대리 수령권자에게 수령을 최고하고 그를 피공탁자로 한 공탁은 본인에게 지급한 효력이 있다고 본다. 반대급부 이행을 요구받는 상대방도 매도인 본인이다.","c":"중","v":1},"법무사2022_28-35-3":{"w":"판례는 공탁관이 서류만으로 진정한 상속인인지 심사할 수 없다며 불수리했다면 정당한 수령권자는 공탁자를 상대로 출급청구권 확인의 소를 제기할 이익이 있다고 본다. 그 판결로 출급한다.","c":"중","v":1},"법무사2022_28-35-4":{"w":"보증금은 임대차에서 생긴 연체차임 등 모든 채무를 담보하므로 반환할 때 당연히 공제된다는 것이 판례다. 그래서 공제한 나머지를 공탁하면 유효하다.","c":"중","v":1},"법무사2022_28-35-5":{"w":"보증금 반환과 건물 인도는 동시이행이므로 인도 확인서를 조건으로 하면 인도의 선이행을 요구하는 것이 된다. 판례는 그런 공탁은 변제 효력이 없다고 본다.","c":"중","v":1},"법무사2022_28-42-2":{"w":"분할 전후 대장의 소유명의인이 다르면 진정한 소유자를 알 수 없어 공탁선례는 상대적 불확지공탁(토지보상법 제40조 제2항 제2호)을 인정했다. 다만 2023. 6. 1. 개정된 토지수용 보상금 공탁 사무처리지침 제5조 제1항의 열거 사유(가처분, 중복 등기기록, 공유지분 합계 오류, 상속지분 불명)에는 이 경우가 따로 적혀 있지 않다.","c":"하","v":1},"법무사2022_28-42-3":{"w":"공유지분 합계가 1을 넘거나 모자라면 각자의 정당한 지분을 알 수 없다. 그래서 피보상자 불확지를 이유로 공탁할 수 있다(토지수용 보상금 공탁 사무처리지침).","c":"하","v":1},"법무사2022_28-42-4":{"w":"일반채권자의 압류·가압류는 보상금 귀속을 다투는 것이 아니라 집행 문제여서 불확지 사유가 아니다. 이 경우 토지보상법 제40조 제2항 제4호로 집행공탁을 한다(토지수용 보상금 공탁 사무처리지침).","c":"중","v":1},"법무사2022_28-42-5":{"w":"대장에 성명만 있고 주소가 없으면 그 사람을 특정할 수 없어 보상받을 자를 전혀 알 수 없는 경우가 된다. 그래서 절대적 불확지공탁을 할 수 있다(토지수용 보상금 공탁 사무처리지침).","c":"하","v":1},"법무사2022_28-47-1":{"w":"경매개시결정 기입등기가 있어도 경매신청인은 물상대위 등으로 권리를 행사할 뿐이다. 그래서 수용보상금 공탁의 피공탁자는 토지소유자로 적는다(토지수용 보상금 공탁 사무처리지침).","c":"중","v":1},"법무사2022_28-47-2":{"w":"보상금채권이 압류되면 토지보상법 제40조 제2항 제4호(압류·가압류로 지급 금지)와 민사집행법 제248조 제1항을 근거로 집행공탁을 한다. 공탁서 근거법령도 두 조항을 함께 적는다(토지수용 보상금 공탁 사무처리지침).","c":"중","v":1},"법무사2022_28-47-4":{"w":"수용보상금 지급과 소유권이전등기는 동시이행관계가 아니다. 그래서 등기서류 교부를 반대급부로 적을 수 없다(토지수용 보상금 공탁 사무처리지침).","c":"중","v":1},"법무사2022_28-47-5":{"w":"공탁규칙 제2조의 시·군법원 공탁관 직무에 수용보상금 공탁은 없다. 그래서 시·군법원 공탁관에게 할 수 없다.","c":"상","v":1},"법무사2023_29-31-1":{"w":"판례는 매도인이 해제하면서 받은 중도금을 공탁하고 매수인이 이의 없이 수령하면 실제 채무불이행 여부와 관계없이 공탁 취지대로 해제의 효과가 생긴다고 본다.","c":"중","v":1},"법무사2023_29-31-2":{"w":"판례는 공탁금이 채권액에 못 미칠 때 피공탁자가 일부 충당한다는 뜻을 공탁자에게 통지하거나 출급청구서의 이의유보란에 적고 출급하면 전액 변제 효과가 생기지 않는다고 본다.","c":"중","v":1},"법무사2023_29-31-3":{"w":"판례는 피수용자가 재결을 다투는 중이라도 이의를 유보하지 않고 공탁금을 수령하면 수령거절을 철회하고 재결에 승복해 전액을 받은 것으로 본다.","c":"중","v":1},"법무사2023_29-31-5":{"w":"판례·공탁선례는 이의유보를 피공탁자뿐 아니라 출급청구권의 양수인·전부채권자·추심채권자도 할 수 있다고 본다. 이들도 피공탁자의 권리를 행사하기 때문이다.","c":"중","v":1},"법무사2023_29-37-1":{"w":"판례는 채권자가 현금 보상을 예상하고 압류했더라도 토지보상법 제63조의 채권보상 요건을 갖추고 공탁 사유가 있으면 채권으로 공탁할 수 있다고 본다.","c":"중","v":1},"법무사2023_29-37-2":{"w":"압류된 보상금 중 현금 부분은 토지보상법 제40조 제2항 제4호와 민사집행법 제248조 제1항으로 집행공탁을 한다. 채권 보상 부분은 제40조 제2항 사유가 있으면 유가증권공탁 절차로 한다(공탁선례).","c":"중","v":1},"법무사2023_29-37-3":{"w":"토지수용 보상금 공탁 사무처리지침은 보상금이 소득세법·법인세법상 원천징수 대상이면 그 세액을 공제한 나머지를 공탁할 수 있게 한다.","c":"중","v":1},"법무사2023_29-37-4":{"w":"공탁규칙 제2조는 시·군법원 공탁관의 직무를 열거하며 수용보상금 공탁은 넣지 않았다.","c":"상","v":1},"법무사2023_29-44-1":{"w":"임차권등기명령에 따른 임차권등기 말소보다 보증금 반환이 먼저라는 것이 판례다(주택임대차보호법 제3조의3). 그래서 그 말소를 반대급부로 한 보증금 공탁은 할 수 없다.","c":"중","v":1},"법무사2023_29-44-2":{"w":"민법 제317조는 전세금 반환과 전세권설정등기 말소서류 교부를 동시이행으로 한다. 그래서 전세권 말소를 반대급부로 한 전세금 공탁은 유효하다.","c":"중","v":1},"법무사2023_29-44-3":{"w":"공탁자가 반대급부 수령을 거절하면 피공탁자는 그 반대급부를 변제공탁할 수 있다. 그 공탁서는 공탁법 제10조의 반대급부 증명서면이 되어 출급청구에 붙일 수 있다(공탁선례).","c":"중","v":1},"법무사2023_29-44-4":{"w":"부당한 조건이라도 피공탁자가 수락하고 출급하려면 공탁법 제10조에 따라 그 반대급부를 이행했음을 증명해야 한다(공탁선례).","c":"중","v":1},"법무사2023_29-49-4":{"w":"공탁규칙 제88조: 군사법원에 계속 중인 형사사건에도 형사공탁 특례(제8장)를 적용하고 법원은 군사법원으로, 검찰은 군검찰로 본다.","c":"상","v":1},"법무사2024_30-33-1":{"w":"공탁법 제5조의2 제1항: 피고인이 법령 등에 따라 피해자 인적사항을 알 수 없을 때 하는 변제공탁(형사공탁)은 그 형사사건이 계속 중인 법원 소재지 공탁소에 할 수 있다.","c":"하","v":1},"법무사2024_30-33-2":{"w":"공탁규칙 제85조 제1항과 형사공탁 업무처리지침은 납입 사실을 전송받으면 공탁관이 지체 없이 피공탁자별 형사공탁사실통지서를 만들어 해당 법원과 검찰에 원본을 우편·사송으로 보내고 사본은 기록에 철하게 한다. 2026. 10. 2.부터 공탁법 문언상 검찰은 공소청이다.","c":"중","v":1},"법무사2024_30-33-3":{"w":"공탁규칙 제86조 제1항: 형사공탁 피공탁자 동일인 확인은 형사공탁 통지를 받은 법원이나 검찰(2026. 10. 2.부터 공탁법상 공소청)이 지체 없이 동일인 증명서를 발급해 공탁소에 보내는 방식으로 한다(공탁법 제5조의2 제4항).","c":"상","v":1},"법무사2024_30-33-5":{"w":"공탁법 제5조의2 제2항: 형사공탁 공탁서에는 피공탁자 인적사항 대신 법원과 사건번호·사건명, 조서·진술서·공소장 등에 적힌 피해자를 특정할 명칭을 적고 공탁원인사실은 피해 발생시점과 채무 성질로 특정할 수 있다.","c":"상","v":1},"법무사2024_30-35-1":{"w":"판례는 공탁자를 상대로 한 전부금소송의 조정조서는 공탁관에 대한 출급청구권을 증명하는 서면이 아니어서 그것만으로 전부채권자가 공탁된 보상금 채권을 직접 출급할 수 없다고 본다.","c":"중","v":1},"법무사2024_30-35-2":{"w":"수용보상금 지급과 소유권이전등기는 동시이행관계가 아니라는 것이 판례다. 그래서 등기서류 교부나 제한물권·처분제한 등기 말소를 반대급부로 적을 수 없다(토지수용 보상금 공탁 사무처리지침).","c":"중","v":1},"법무사2024_30-35-3":{"w":"판례는 근저당권자가 물상대위로 압류하지 않았으면 압류한 것으로 취급하지 않는다고 본다. 제3자 압류로 지급이 금지되었으므로 그 압류를 이유로 공탁한다(토지보상법 제40조 제2항 제4호).","c":"중","v":1},"법무사2024_30-35-4":{"w":"토지보상법 제42조 제1항: 사업시행자가 수용 개시일까지 보상금을 지급하거나 공탁하지 않으면 재결은 효력을 잃는다. 판례는 무효인 공탁은 공탁하지 않은 것과 같다고 본다.","c":"중","v":1},"법무사2024_30-41-1":{"w":"피보전권리가 공시되지 않은 가처분은 소유권 귀속 분쟁일 수 있으므로 토지수용 보상금 공탁 사무처리지침은 일단 상대적 불확지 사유로 보아 공탁할 수 있게 한다.","c":"중","v":1},"법무사2024_30-41-3":{"w":"양도통지 뒤 철회 등으로 양도의 효력에 의문이 생기면 판례는 과실 없이 채권자를 알 수 없는 경우로 보아 채권자 불확지공탁을 허용한다(민법 제487조 후단).","c":"하","v":1},"법무사2024_30-41-4":{"w":"판례는 보상금 총액은 확정되었지만 수령권자와 배분 금액을 다투는 경우 다투는 자 전원을 피공탁자로 한 불확지공탁을 허용한다.","c":"중","v":1},"법무사2024_30-41-5":{"w":"상속인들 사이에 기여분·유언으로 상속지분을 다투어 은행이 지분을 알 수 없으면 판례는 과실 없이 채권자를 알 수 없는 경우로 본다. 상속인들을 피공탁자로 하고 지분을 알 수 없는 이유를 구체적으로 적어 불확지공탁을 할 수 있다.","c":"하","v":1},"법무사2025_31-31-1":{"w":"공탁규칙 제82조: 형사공탁 공탁서에는 공소장·조서·진술서·판결서에 적힌 피해자 성명(성·가명 포함), 법원과 사건번호·사건명, 공소장의 검찰청과 사건번호를 적고 피공탁자 주소와 주민등록번호는 적지 않는다.","c":"상","v":1},"법무사2025_31-31-2":{"w":"공탁규칙 제83조 제1호: 형사공탁 공탁서에는 해당 형사사건이 계속 중인 법원을 확인할 수 있는 서면을 첨부한다.","c":"상","v":1},"법무사2025_31-31-3":{"w":"공탁법 제5조의2 제3항과 공탁규칙 제84조 제1항: 형사공탁 피공탁자에 대한 공탁통지는 공탁관이 전자공탁홈페이지에 공고하는 방법으로 할 수 있다.","c":"상","v":1},"법무사2025_31-31-5":{"w":"공탁규칙 제87조: 피공탁자 등의 인적사항이 적힌 공탁 서류와 전자기록의 열람·사실증명 청구가 있으면 공탁관은 인적사항이 드러나지 않도록 비실명 처리한 뒤 열람시키거나 증명서를 발급한다.","c":"상","v":1},"법무사2025_31-36-2":{"w":"판례는 채무액에 다툼이 있어도 채무자가 전액 변제임을 밝혀 공탁하고 채권자가 이의를 유보하지 않고 수령하면 채권 전액에 대한 변제공탁 효력을 인정한다.","c":"중","v":1},"법무사2025_31-36-3":{"w":"담보 목적 가등기·본등기 말소보다 피담보채무 변제가 먼저라는 것이 판례다. 그래서 그 말소를 반대급부로 한 변제공탁은 무효다.","c":"중","v":1},"법무사2025_31-36-4":{"w":"보증금 반환과 건물 명도는 동시이행이어서 명도 확인서를 조건으로 하면 명도 선이행을 요구하는 셈이 된다. 판례는 그 공탁에 변제 효력이 없다고 본다.","c":"중","v":1},"법무사2025_31-36-5":{"w":"판례는 공탁으로 채무를 면하려면 채무 전액을 공탁해야 하며 일부 제공이 유효한 제공으로 인정될 특별한 사정이 없으면 채권자가 수락하지 않는 한 일부공탁은 효력이 없다고 본다.","c":"중","v":1},"법무사2025_31-37-1":{"w":"판례는 채권자가 이의 없이 공탁금을 수령하면 공탁 취지대로 수령한 것이어서 채무자가 지정한 충당 채무에 그대로 충당된다고 본다.","c":"중","v":1},"법무사2025_31-37-3":{"w":"판례는 공탁원인이 법률상 효력이 없어 부적법한 공탁이라도 피공탁자가 이의를 유보하지 않고 수령하면 그 원인을 수락한 것으로 보아 공탁자가 주장한 대로 법률효과가 생긴다고 본다.","c":"중","v":1},"법무사2025_31-37-4":{"w":"판례는 수용재결 보상금을 이의유보하고 받았더라도 이의재결 증액분을 이의유보 없이 받으면 이의재결에 승복한 것으로 본다. 행정소송 계속만으로 이의유보가 있다고 보지 않는다.","c":"중","v":1},"법무사2025_31-37-5":{"w":"집행공탁 후 배당으로 채무자 잉여금이 정해졌을 때 공탁원인을 다투는 채무자는 이의를 유보하고 출급할 수 있다는 것이 판례다. 이의를 유보하면 공탁원인을 승인한 것이 되지 않는다.","c":"중","v":1},"법무사2025_31-41-1":{"w":"판례는 수용 효과를 생기게 하는 공탁은 재결 보상금 전액이어야 한다고 본다. 사업시행자가 대납한 전기요금 등을 빼고 차액만 공탁하면 유효한 공탁이 아니다.","c":"중","v":1},"법무사2025_31-41-2":{"w":"수용 공탁은 재결 보상금 전액이어야 하므로(판례) 대위 상속등기 비용인 등록면허세 등을 공제하고 공탁하면 무효다(토지수용 보상금 공탁 사무처리지침).","c":"중","v":1},"법무사2025_31-41-4":{"w":"판례는 피수용자에게 의무 없는 반대급부나 조건을 붙인 공탁은 피수용자가 수락하지 않으면 효력이 없다고 본다.","c":"중","v":1},"법무사2025_31-41-5":{"w":"조건 철회 정정은 그때부터 효력이 있을 뿐 소급하지 않는다는 것이 판례다. 수용 개시일 전에 정정하면 유효한 공탁이 되지만 개시일 후 정정하면 개시일까지 공탁이 없었던 것이 되어 재결이 실효된다(토지보상법 제42조).","c":"중","v":1},"법무사2026_32-33-1":{"w":"「개인정보 보호조치 사건의 공탁에 관한 업무처리지침」(행정예규)은 피공탁자가 개인정보 보호조치 대상자여서 공탁자가 성명 외에 주민등록번호나 주소를 알 수 없는 사건에 적용된다.","c":"하","v":1},"법무사2026_32-33-3":{"w":"개인정보 보호조치 사건 공탁 지침은 공탁원인사실란에 일반 공탁원인 외에 관련 사건이 개인정보 보호조치 사건이라는 취지를 함께 적게 한다.","c":"중","v":1},"법무사2026_32-33-4":{"w":"개인정보 보호조치 사건 공탁 지침은 피공탁자 주소란에 본안사건 법원과 사건번호를 적고 주민등록번호란 기재를 생략할 수 있게 한다.","c":"중","v":1},"법무사2026_32-33-5":{"w":"개인정보 보호조치 사건 공탁 지침은 본안사건 법원 소재지의 관할공탁소에 공탁할 수 있게 한다. 피공탁자 주소를 몰라 채무이행지 공탁소를 정할 수 없기 때문이다.","c":"중","v":1},"법무사2026_32-34-1":{"w":"공탁규칙 제23조 제1항은 피공탁자에게 공탁통지를 해야 할 때 피공탁자 수만큼 통지서를 첨부하게 한다. 민법 제487조 외 법령에 의한 변제공탁과 상대적 불확지공탁도 같다(공탁 실무).","c":"중","v":1},"법무사2026_32-34-2":{"w":"절대적 불확지나 주소불명 공탁은 통지할 곳이 없어 신청 때 공탁통지서가 필요 없다. 나중에 피공탁자나 주소를 알아 정정할 때 통지서를 낸다(공탁규칙 제30조 제6항, 제23조 준용).","c":"중","v":1},"법무사2026_32-34-3":{"w":"공탁은 공탁물 납입으로 성립한다. 공탁규칙 제29조 제1항은 공탁관이 납입 전송이나 물품납입통지서를 받으면 공탁통지서를 피공탁자에게 발송하게 한다.","c":"상","v":1},"법무사2026_32-34-5":{"w":"판례는 공탁통지가 출급청구권 행사의 편의를 위한 것일 뿐 공탁의 유효요건이 아니라고 본다. 통지가 되지 않아도 변제공탁 효력에는 원칙적으로 영향이 없다.","c":"중","v":1},"법무사2026_32-39-1":{"w":"판례는 채권자가 미리 수령을 거절하면 구두 제공 없이 바로 변제공탁을 할 수 있다고 본다. 민법 제460조 단서의 구두 제공도 필요 없을 만큼 수령 의사가 없는 것으로 보기 때문이다.","c":"중","v":1},"법무사2026_32-39-3":{"w":"판례는 대리 수령권자를 피공탁자로 한 잔대금 공탁이 본인에게 지급한 효력이 있다고 본다. 잔대금과 등기서류 교부는 동시이행이어서 그 서류 교부를 반대급부로 한 공탁도 유효하다.","c":"중","v":1},"법무사2026_32-39-4":{"w":"판례는 공탁관이 서류만으로 진정한 상속인을 심사할 수 없다며 불수리했으면 정당한 수령권자가 공탁자를 상대로 출급청구권 확인을 구할 이익이 있다고 본다.","c":"중","v":1},"법무사2026_32-39-5":{"w":"판례는 상대적 불확지 공탁에서 누가 출급청구권을 가지는지를 공탁자와의 본래 법률관계에서 진정한 채권자가 누구인지로 판단한다.","c":"중","v":1},"법무사2026_32-46-1":{"w":"채권자가 이자 일부에 충당한다는 이의를 유보하고 수령하면 공탁 취지와 달리 법정충당(민법 제479조)에 따라 비용·이자 순으로 충당된다는 것이 판례다. 그래서 원금채권은 소멸하지 않는다.","c":"중","v":1},"법무사2026_32-46-2":{"w":"판례는 차임채무가 매월 사용·수익의 대가로 따로 생기는 것이어서 연체가 여러 달이라도 그중 1개월분과 지연손해금을 공탁하면 채무 내용에 따른 유효한 공탁이라고 본다.","c":"중","v":1},"법무사2026_32-46-4":{"w":"판례는 채무자 겸 설정자가 최고액을 넘는 채무를 지고 있는데 최고액과 비용만 공탁하면 일부공탁이어서 원칙적으로 무효라고 본다.","c":"중","v":1},"법무사2026_32-46-5":{"w":"판례는 공탁금이 채무 총액보다 아주 근소하게 부족하면 신의칙상 그 변제공탁을 유효로 본다.","c":"중","v":1},"법무사2026_32-47-1":{"w":"민법 제449조 제2항 단서에 따라 악의·중과실 양수인에 대한 양도는 무효다. 판례는 채무자가 양수인의 선의 여부를 알 수 없어 양도의 적법성에 의문이 있으면 채권자 불확지공탁을 할 수 있다고 본다.","c":"하","v":1},"법무사2026_32-47-2":{"w":"판례는 이중양도 양수인 사이 우열을 확정일자 있는 통지·승낙이 채무자에게 도달한 일시 선후로 정한다. 도달에 선후가 분명하면 채무자는 먼저 도달한 양수인에게 갚으면 되므로 불확지공탁을 할 수 없다.","c":"중","v":1},"법무사2026_32-47-4":{"w":"판례는 출연자와 예금명의자가 달라 둘 다 권리를 주장하고 금융기관이 선관주의를 다해도 진정한 예금주에 의문이 있으면 채권자 불확지공탁을 허용한다.","c":"중","v":1},"법무사2026_32-47-5":{"w":"체납처분 압류의 유효 여부를 예금주와 국가가 소송으로 다투면 은행은 과실 없이 진정한 권리자를 알 수 없다. 판례에 따라 「국가(소관 체납처분청) 또는 예금주」를 피공탁자로 불확지공탁을 할 수 있다.","c":"하","v":1},"법무사2026_32-49-1":{"w":"판례는 부적법한 조건부 공탁이라도 조건 철회 정정이 인가되고 수령자가 이를 알았다면 그때부터 적법한 공탁이 된다고 본다.","c":"중","v":1},"법무사2026_32-49-2":{"w":"판례는 반대급부란이 비어 있고 원인사실란의 내용이 수령 조건이 아니라 수령 후 할 의무를 환기하는 정도라면 조건부 공탁이 아니어서 유효하다고 본다.","c":"중","v":1},"법무사2026_32-49-3":{"w":"채무 이행 확보를 위해 어음을 발행했으면 채무 이행과 어음 반환은 동시이행이라는 것이 판례다. 그래서 어음 반환을 반대급부로 한 공탁은 유효하다.","c":"중","v":1},"법무사2026_32-49-5":{"w":"보증금 반환과 명도는 동시이행이어서 명도 확인서 조건은 명도 선이행을 요구하는 것이 된다. 판례는 그 공탁을 무효로 본다.","c":"중","v":1},"법무사2026_32-50-1":{"w":"공탁법 제5조의2 제4항: 형사공탁물 수령을 위한 동일인 확인은 법원이나 공소청(2026. 10. 2. 개정 전 문언은 검찰)이 발급한 증명서로 한다.","c":"상","v":1},"법무사2026_32-50-2":{"w":"형사공탁 업무처리지침은 동일인 증명서를 법원이 발급할 때 형사공탁의 원인이 된 형사사건(상소로 다른 법원에 계속되면 그 사건) 담당재판부 참여사무관 등이 처리하게 한다(공탁규칙 제86조 제2항).","c":"중","v":1},"법무사2026_32-50-3":{"w":"형사공탁 업무처리지침은 동일인 증명서가 접수되면 공탁관이 기재사항을 피공탁자 개인정보관리에 전산등록해 인적사항이 공개되지 않게 한다(공탁규칙 제87조 취지).","c":"중","v":1},"법무사2026_32-50-4":{"w":"형사공탁 업무처리지침은 사망한 피해자의 상속인 중 1인이 피해자 인적사항이 적힌 동일인 증명서를 이미 냈으면 다른 상속인은 출급 때 다시 낼 필요가 없게 한다. 피해자 동일성은 이미 확인되었기 때문이다.","c":"중","v":1},"법무사2016_22-35-1":{"w":"판례는 혼합공탁이 채권자 불확지 변제공탁과 집행공탁이 결합한 것이어서 변제공탁 관련 채권자에게는 변제공탁, 집행공탁 관련 채권자에게는 집행공탁의 효력이 있다고 본다.","c":"중","v":1},"법무사2016_22-35-2":{"w":"혼합공탁의 집행공탁 부분은 민사집행법 제248조 제1항에 근거하므로 압류 경합이 없어도 단일 압류나 가압류(제291조)만으로 할 수 있다(판례·공탁선례).","c":"중","v":1},"법무사2016_22-35-4":{"w":"판례는 혼합공탁의 피공탁자가 출급하려면 다른 피공탁자에 대한 관계뿐 아니라 집행채권자에 대한 관계에서도 출급청구권이 있음을 증명하는 서면을 내야 한다고 본다.","c":"중","v":1},"법무사2016_22-35-5":{"w":"채권 전액이 압류된 뒤의 양도는 압류채권자에게 대항할 수 없어 채권자를 알 수 없는 사정이 생기지 않는다. 그래서 불확지 변제공탁 사유가 없고 혼합공탁을 할 수 없으며 집행공탁을 한다(공탁선례).","c":"하","v":1},"법무사2016_22-37-1":{"w":"체납처분 압류는 국세징수법상 압류채권자의 추심권만 생기게 할 뿐 민사집행법 제248조의 공탁 근거가 아니다. 그래서 체납처분 압류만으로는 변제공탁이나 집행공탁을 할 수 없다(「민사집행법상 압류와 체납처분 압류가 있는 경우의 공탁절차 등에 관한 업무처리지침」).","c":"중","v":1},"법무사2016_22-37-2":{"w":"민사집행법상 압류와 체납처분 압류 총액이 채권액을 넘으면 공탁금 전액이 배당 대상이 되어 피공탁자를 정할 수 없다. 그래서 피공탁자란을 비운다(민사집행법 압류·체납처분 압류 경합 공탁 업무처리지침).","c":"중","v":1},"법무사2016_22-37-3":{"w":"총액이 채권액을 넘지 않으면 각 압류 범위가 나뉜다. 민사집행법 압류가 미치는 부분은 집행법원의 지급위탁으로 출급한다(민사집행법 압류·체납처분 압류 경합 공탁 업무처리지침).","c":"중","v":1},"법무사2016_22-37-5":{"w":"민사집행법상 압류가 있으면 채무자에게 변제할 수 없으므로 체납자를 피공탁자로 한 민법 제487조 변제공탁은 할 수 없다. 제248조 제1항의 집행공탁만 가능하다(공탁 업무처리지침).","c":"중","v":1},"법무사2016_22-40-1":{"w":"행정예규 제1225호(공탁관의 사유신고) 1. 나. (1): 가압류를 원인으로 공탁한 뒤 가압류를 본압류로 이전하는 압류명령이 있으면 공탁관은 사유신고를 한다.","c":"상","v":1},"법무사2016_22-40-2":{"w":"행정예규 제1225호 1. 나. (2): 공탁금 지급청구권에 민사집행법상 압류와 체납처분 압류가 있고 총액이 피압류채권액을 넘으면 공탁관은 집행법원에 사유신고를 한다.","c":"상","v":1},"법무사2016_22-40-4":{"w":"행정예규 제1225호는 재판상 보증공탁금 회수청구권에 압류가 경합하면 담보취소결정정본과 확정증명서가 제출된 때 사유신고를 하게 한다. 그때 회수 요건이 갖추어지기 때문이다.","c":"상","v":1},"법무사2016_22-40-5":{"w":"행정예규 제1225호는 공탁금 지급청구권이 양도되어 대항요건을 갖춘 뒤의 압류 경합을 사유신고 대상에서 제외한다. 이미 양수인의 권리여서 양도인의 채권자 압류는 효력이 없기 때문이다.","c":"상","v":1},"법무사2016_22-42-1":{"w":"압류된 부분을 넘는 금액은 채무자에게 변제할 수 있어 공탁금 전체를 압류채무자 앞으로 공탁한다. 그래서 피공탁자란에 압류채무자를 적고 공탁통지서를 붙인다(공탁 업무처리 예규, 공탁규칙 제23조).","c":"중","v":1},"법무사2016_22-42-2":{"w":"압류된 금액을 넘는 부분은 변제공탁 성질이어서 배당 대상이 아니다. 그래서 제3채무자는 압류금액 부분만 집행법원에 사유신고를 한다(민사집행법 제248조 제4항, 공탁선례).","c":"중","v":1},"법무사2016_22-42-3":{"w":"압류금액을 넘는 부분은 변제공탁 성질이어서 민법 제489조 제1항에 따라 공탁자가 회수할 수 있다(공탁선례). 집행공탁 부분은 회수할 수 없다.","c":"중","v":1},"법무사2016_22-42-5":{"w":"압류금액을 넘는 부분은 변제공탁이므로 피공탁자인 압류채무자가 공탁통지서를 붙여 변제공탁의 예에 따라 출급할 수 있다(공탁선례).","c":"중","v":1},"법무사2017_23-38-1":{"w":"담보공탁 피공탁자는 질권자와 같은 권리가 있어(민사소송법 제123조) 공탁자 회수청구권에 대한 일반 압류보다 우선한다. 담보취소결정과 확정증명이 먼저 제출되었으면 담보권이 소멸해 회수 쪽이 우선한다(공탁 실무 예규).","c":"중","v":1},"법무사2017_23-38-3":{"w":"피공탁자의 출급청구권이 그의 채권자에게 압류되면 피공탁자 본인은 처분·수령이 금지된다. 그래서 담보권을 실행해도 피공탁자에게 지급하지 않는다(공탁 실무 예규).","c":"중","v":1},"법무사2017_23-38-4":{"w":"판례는 보전처분 집행 후 본안에서 패소 확정되면 집행채권자에게 고의·과실이 추정되어 부당 집행으로 인한 손해를 배상할 책임이 있다고 본다. 그 손해가 담보공탁의 피담보채권이다.","c":"중","v":1},"법무사2017_23-38-5":{"w":"판례는 제1심 담보는 항소심에서 다시 담보를 냈다고 소멸하지 않으며 담보제공자 승소판결 확정이나 이에 준하는 경우에만 담보사유가 소멸한다고 본다(민사소송법 제125조).","c":"중","v":1},"법무사2017_23-42-1":{"w":"양도 효력에 다툼이 있어 채권자를 알 수 없고 가압류도 있으므로 민법 제487조 후단 불확지 공탁과 민사집행법 제291조·제248조 제1항 집행공탁을 합한 혼합공탁을 할 수 있다. 피공탁자는 양도인 또는 양수인으로 적는다(판례·공탁선례).","c":"하","v":1},"법무사2017_23-42-2":{"w":"혼합공탁은 불확지 변제공탁과 가압류에 따른 집행공탁의 결합이어서 근거 법조는 민법 제487조 후단과 민사집행법 제291조·제248조 제1항이다(공탁 실무).","c":"중","v":1},"법무사2017_23-42-3":{"w":"혼합공탁의 피공탁자(양도인·양수인)에게는 공탁통지서를, 가압류채권자에게는 공탁사실통지서를 보낸다(공탁 실무 예규).","c":"중","v":1},"법무사2017_23-42-5":{"w":"양도가 무효로 판명되면 채권은 양도인에게 있고 가압류가 유효해 집행공탁 부분이 작동한다. 그래서 가압류채권자는 본압류 이전 후 집행법원의 배당과 지급위탁으로 출급한다(판례·공탁 실무).","c":"중","v":1},"법무사2017_23-46-1":{"w":"해방공탁은 가압류 집행을 풀기 위한 것이고 가압류 효력은 공탁금 회수청구권에 옮겨 붙는다. 그래서 피보전채권을 변제한 것이 아니어서 채무 소멸을 주장할 수 없다(판례).","c":"중","v":1},"법무사2017_23-46-2":{"w":"민사집행법 제282조의 해방금액은 금전으로 정하게 되어 있다. 판례는 실질적 통용가치가 있는 유가증권이라도 해방공탁을 허용하지 않는다.","c":"중","v":1},"법무사2017_23-46-3":{"w":"판례는 해방금액이 가압류 전체를 위한 하나의 금액이어서 채무자가 여럿이라도 자기 채무액만 공탁하고 가압류 일부 취소를 구할 수 없다고 본다.","c":"중","v":1},"법무사2017_23-46-5":{"w":"가압류채권자의 채권자가 받은 가압류는 가압류채권자가 장차 받을 권리에 대한 것일 뿐이다. 해방공탁 원인인 가압류가 효력을 잃었음을 증명해 공탁자가 회수청구하면 공탁관은 인가해야 한다(공탁선례).","c":"중","v":1},"법무사2017_23-47-1":{"w":"행정예규 제1225호 1. 가.: 공탁금 지급청구권에 채권자 경합이 생기고 집행채권 총액이 피압류채권 총액을 넘어 배당이 필요하면 공탁관은 사유신고를 한다.","c":"상","v":1},"법무사2017_23-47-2":{"w":"행정예규 제1225호 1. 나. (4): 법률적으로 압류 경합이 아니어도 우선순위 판단이 곤란한 객관적 사정이 있으면 공탁관은 사유신고를 할 수 있다.","c":"상","v":1},"법무사2017_23-47-3":{"w":"행정예규 제1225호는 금전공탁이 아닌 유가증권·물품공탁을 사유신고 대상에서 뺀다. 민사집행법 제248조의 공탁은 금전채권에 관한 것이기 때문이다.","c":"상","v":1},"법무사2017_23-47-4":{"w":"행정예규 제1225호는 상대적 불확지공탁 피공탁자 한쪽의 출급청구권에 압류 경합이 있으면 그 피공탁자에게 출급청구권이 있다는 증명서면이 제출된 때 사유신고를 하게 한다.","c":"상","v":1},"법무사2017_23-48-1":{"w":"채권 일부만 압류되면 나머지는 채무자에게 변제할 수 있어 채권 전액을 공탁할 때 압류채무자를 피공탁자로 적고 공탁통지서를 붙인다(공탁규칙 제23조, 공탁 실무 예규).","c":"중","v":1},"법무사2017_23-48-2":{"w":"압류 효력이 미치지 않는 부분은 변제공탁 성질이므로 압류채무자가 변제공탁의 예에 따라 출급할 수 있다(공탁선례).","c":"중","v":1},"법무사2017_23-48-3":{"w":"압류가 미치지 않는 부분은 변제공탁이어서 공탁자는 민법 제489조 제1항에 따라 회수할 수 있다(공탁선례).","c":"중","v":1},"법무사2017_23-48-5":{"w":"배당가입 차단효(민사집행법 제247조 제1항)는 압류된 범위에만 생긴다. 전액에 대해 사유신고를 했더라도 압류가 미치지 않는 부분에는 생기지 않는다는 것이 판례다.","c":"중","v":1},"법무사2018_24-37-1":{"w":"총액이 채권액을 넘지 않으면 압류 범위가 나뉜다. 체납처분 압류만 미치는 부분은 체납처분 압류채권자가 공탁관에게 직접 출급(추심)청구할 수 있다(민사집행법 압류·체납처분 압류 경합 공탁 업무처리지침).","c":"중","v":1},"법무사2018_24-43-1":{"w":"공탁관의 사유신고 지침은 경합된 압류명령을 발령한 법원이 다르면 먼저 송달된 압류명령을 발령한 법원에 사유신고를 하게 한다(민사집행규칙 제172조 참조).","c":"중","v":1},"법무사2018_24-43-2":{"w":"행정예규 제1225호는 가압류와 체납처분 압류가 있는 경우를 선후와 관계없이 사유신고 대상에서 뺀다. 가압류만으로는 배당을 실시할 수 없기 때문이다.","c":"상","v":1},"법무사2018_24-43-3":{"w":"행정예규 제1225호는 재판상 보증공탁금 출급청구권에 압류가 경합하면 담보권 실행요건을 갖춘 때(출급청구권 증명서면 제출이나 질권실행 압류·현금화명령 효력 발생 시) 사유신고를 하게 한다.","c":"상","v":1},"법무사2018_24-43-5":{"w":"행정예규 제1225호 1. 나. (2): 민사집행법상 압류와 체납처분 압류의 총액이 피압류채권액을 넘으면 공탁관은 집행법원에 사유신고를 한다.","c":"상","v":1},"법무사2018_24-47-1":{"w":"마약류불법거래방지법·공무원범죄몰수특례법 등은 몰수보전된 채권에 강제집행 압류명령이 송달되면 제3채무자가 채권 전액을 이행지 관할 지방법원·지원 공탁소에 공탁해 면책받을 수 있게 한다.","c":"중","v":1},"법무사2018_24-47-3":{"w":"공무원범죄몰수특례법 등 몰수·추징보전 규정은 추징보전명령에 집행정지나 집행처분 취소를 위해 피고인이 공탁할 금액(추징보전해방금)을 정하게 한다.","c":"중","v":1},"법무사2018_24-47-4":{"w":"추징보전해방금은 추징을 담보하는 것이어서 추징이 선고되면 그 금액만큼 추징에 충당되고 넘는 금액은 피고인에게 돌려준다(몰수특례법 관련 규정).","c":"중","v":1},"법무사2018_24-47-5":{"w":"몰수특례법 관련 규정은 추징보전 집행된 금전채권의 제3채무자가 채권액을 공탁할 수 있게 하며 그 경우 피고인의 공탁금 출급청구권에 추징보전 집행이 된 것으로 본다.","c":"중","v":1},"법무사2019_25-31-2":{"w":"판례는 강제집행정지 담보공탁금의 피담보채권에 담보권리자가 권리행사최고에 따라 제기한 소송의 소송비용도 포함된다고 본다. 그 비용도 집행정지로 생긴 손해이기 때문이다.","c":"중","v":1},"법무사2019_25-31-3":{"w":"재판상 담보공탁은 제3자도 당사자를 대신해 할 수 있고 법원 허가나 담보권리자 동의가 필요 없다. 다만 제3자가 대신 공탁한다는 뜻을 공탁서에 적는다(공탁 실무 예규).","c":"중","v":1},"법무사2019_25-31-4":{"w":"판례는 강제집행정지 담보가 집행정지로 채권자가 입을 손해를 담보할 뿐 집행 대상인 기본채권 자체를 담보하지 않는다고 본다.","c":"중","v":1},"법무사2019_25-31-5":{"w":"판례는 건물인도 집행정지 담보의 피담보채권에 정지 기간 중 생긴 차임 상당 손해배상청구권이 포함된다고 본다. 인도 지연으로 생긴 손해이기 때문이다.","c":"중","v":1},"법무사2019_25-39-1":{"w":"민사집행법 제291조·제248조 제4항: 가압류를 원인으로 공탁한 제3채무자는 공탁서를 붙여 그 사실을 가압류 발령법원에 서면으로 신고해야 한다.","c":"중","v":1},"법무사2019_25-39-2":{"w":"가압류는 배당을 하지 않으므로 공탁금 출급청구권은 가압류채무자에게 있다. 그래서 피공탁자란에 가압류채무자를 적고 근거 법조는 민사집행법 제291조·제248조 제1항이다(공탁 실무 예규).","c":"중","v":1},"법무사2019_25-39-3":{"w":"가압류 원인 집행공탁의 피공탁자는 가압류채무자여서 그에게 공탁통지서를 보내고 가압류채권자에게는 공탁사실을 통지한다(공탁 실무 예규).","c":"중","v":1},"법무사2019_25-39-4":{"w":"가압류 효력은 공탁금 출급청구권에 옮겨 붙으므로 가압류가 효력을 잃지 않는 한 가압류채무자는 출급할 수 없다(판례·공탁선례).","c":"중","v":1},"법무사2019_25-40-5":{"w":"민사집행법 제160조 제2항은 배당기일에 출석하지 않은 채권자의 배당액을 공탁하게 한다. 확정된 전부명령의 전부채권자가 불출석하면 그 배당액을 이 조항으로 공탁할 수 있다(배당액 공탁에 관한 예규).","c":"중","v":1},"법무사2019_25-43-4":{"w":"판례는 민사집행법 제248조의 공탁에 따른 변제 효과가 압류 대상에 포함된 채권에 대해서만 생긴다고 본다. 압류되지 않은 다른 채권까지 소멸하지는 않는다.","c":"중","v":1},"법무사2020_26-35-1":{"w":"판례는 해방공탁금 회수청구권에 가압류 효력이 미치므로 다른 채권자의 전부명령은 압류 경합 상태에서 효력이 없다고 본다. 그래서 사유신고로 시작된 배당에서 지급 자격 증명서를 받아야 회수할 수 있다.","c":"중","v":1},"법무사2020_26-35-2":{"w":"판례는 선행 양도에 다툼이 없어 불확지 공탁 사유가 없는데 혼합공탁을 했다면 요건을 갖추지 못해 유효한 공탁이 아니라고 본다. 공탁자는 착오공탁으로 회수할 수 있다(공탁법 제9조 제2항 제2호).","c":"중","v":1},"법무사2020_26-35-4":{"w":"민사집행법상 압류가 있으면 채무자에게 변제할 수 없어 압류채무자를 피공탁자로 한 변제공탁은 할 수 없다. 체납처분 압류가 함께 있어도 제3채무자는 제248조 제1항으로 압류 관련 채권 전액을 공탁할 수 있다(판례·공탁 업무처리지침).","c":"중","v":1},"법무사2020_26-35-5":{"w":"판례는 해방금액 일부만 공탁하면 가압류 집행을 취소할 효력이 없어 해방공탁이 아니라고 본다. 그래서 착오공탁에 해당해 회수할 수 있다.","c":"중","v":1},"법무사2020_26-37-2":{"w":"담보공탁 피공탁자는 질권자와 같은 권리(민사소송법 제123조)가 있어 회수청구권을 압류·추심·전부하고 담보취소로 회수하더라도 선행 일반 채권자의 압류에 우선한다는 것이 판례다.","c":"중","v":1},"법무사2020_26-37-3":{"w":"행정예규 제1225호는 보증공탁금 출급청구권 압류 경합 시 담보권 실행요건을 갖춘 때 사유신고를 하게 한다. 공탁관 사유신고 지침은 먼저 송달된 압류명령 법원에 신고하게 한다.","c":"중","v":1},"법무사2020_26-37-4":{"w":"담보공탁 피공탁자의 질권자 지위는 회수청구권 양도보다 우선한다. 담보권을 실행하면 피공탁자에게 지급하되 담보취소결정과 확정증명이 먼저 제출되었으면 담보권이 소멸해 그렇지 않다(공탁 실무 예규).","c":"중","v":1},"법무사2020_26-37-5":{"w":"판례는 보전처분 담보가 본안 계속 중에는 소멸하지 않고 채권자가 본안에서 승소 확정되어야 담보사유가 소멸한다고 본다(민사소송법 제125조 제1항).","c":"중","v":1},"법무사2020_26-39-1":{"w":"양도 효력에 다툼이 있어 채권자를 알 수 없고 가압류도 있으므로 민법 제487조 후단과 민사집행법 제291조·제248조 제1항의 혼합공탁을 할 수 있다(판례).","c":"하","v":1},"법무사2020_26-39-3":{"w":"배당가입 차단효는 압류에 따른 사유신고가 있어야 생긴다(민사집행법 제247조). 가압류만 있는 혼합공탁은 배당절차가 시작되지 않아 차단효가 없다(판례).","c":"중","v":1},"법무사2020_26-39-4":{"w":"양도가 유효하면 채권은 양수인에게 넘어가고 그 뒤 양도인을 채무자로 한 가압류는 효력이 없다. 그래서 양수인이 진정한 채권자가 된다(판례).","c":"중","v":1},"법무사2020_26-39-5":{"w":"혼합공탁 피공탁자는 다른 피공탁자와 집행채권자 모두에 대해 출급권을 증명해야 한다(판례). 양수인은 양도인 승낙서와 가압류채권자 승낙서(각 인감증명 첨부)로 증명할 수 있다(공탁선례).","c":"중","v":1},"법무사2020_26-40-3":{"w":"판례는 공탁청구를 받은 제3채무자가 공탁 대신 추심채권자 한 사람에게 지급하면 공탁청구 채권자에게는 대항할 수 없지만 그 밖의 채권자에게는 채무 소멸을 주장할 수 있다고 본다(민사집행법 제248조 제3항 참조).","c":"중","v":1},"법무사2021_27-33-1":{"w":"가압류된 금액만 공탁해도 가압류 원인 집행공탁의 피공탁자는 가압류채무자다(공탁 실무 예규). 가압류는 배당을 하지 않아 출급청구권이 채무자에게 남는다.","c":"중","v":1},"법무사2021_27-36-1":{"w":"판례는 혼합공탁이 변제공탁 관련 새 채권자(양수인)에게는 변제공탁, 압류채권자에게는 집행공탁 효력이 있고 적법하면 채무자의 채무는 소멸한다고 본다.","c":"중","v":1},"법무사2021_27-36-2":{"w":"판례는 공탁의 종류를 피공탁자 지정 여부, 근거 조문, 공탁사유, 사유신고 등을 종합해 합리적으로 판단해야 한다고 본다.","c":"중","v":1},"법무사2021_27-36-3":{"w":"판례는 혼합공탁금으로 배당이 실시되고 배당받을 자와 금액에 다툼이 있으면 배당받지 못했다고 주장하는 자가 배당표상 다른 채권자를 상대로 배당이의의 소를 낼 수 있다고 본다.","c":"중","v":1},"법무사2021_27-36-5":{"w":"배당가입 차단효는 집행공탁에 따른 사유신고에서 생긴다. 판례는 혼합공탁의 변제공탁 부분에는 차단효가 생길 여지가 없다고 본다.","c":"중","v":1},"법무사2021_27-37-1":{"w":"공탁규칙 제58조 제1항: 공탁금 지급청구권에 압류 경합 등 사유신고 사정이 생기면 공탁관은 지체 없이 사유신고서를 집행법원에 보내야 한다. 판례도 이를 공탁관의 직무상 의무로 본다.","c":"상","v":1},"법무사2021_27-37-2":{"w":"행정예규 제1225호 1. 나. (2): 민사집행법상 압류와 체납처분 압류의 총액이 피압류채권액을 넘으면 공탁관은 집행법원에 사유신고를 한다.","c":"상","v":1},"법무사2021_27-37-3":{"w":"공탁규칙 제58조는 지체 없이 사유신고를 하게 한다. 공탁관의 사유신고 지침은 그 기한을 사유 발생 다음 날부터 3일 이내로 정한다.","c":"중","v":1},"법무사2021_27-37-4":{"w":"가압류는 배당절차를 진행할 수 없으므로 가압류와 압류가 경합하면 공탁관은 압류명령을 발령한 법원에 사유신고를 한다(공탁관 사유신고 지침).","c":"중","v":1},"법무사2021_27-44-1":{"w":"민사집행법 제282조의 해방금액은 금전으로 정하므로 해방공탁은 금전만 허용되고 유가증권은 허용되지 않는다(판례).","c":"중","v":1},"법무사2021_27-44-2":{"w":"판례는 해방금 공탁 후 가압류 효력이 공탁금 자체가 아니라 공탁자인 채무자의 공탁금 회수청구권에 미친다고 본다.","c":"중","v":1},"법무사2021_27-44-3":{"w":"가압류 효력이 회수청구권에 미치므로 다른 채권자가 같은 회수청구권을 압류하면 집행 대상이 같아 압류가 경합한다(판례).","c":"중","v":1},"법무사2021_27-44-4":{"w":"판례는 가압류채권자가 본안 승소판결로 회수청구권에 대한 본압류 이전 압류·전부명령을 받아 해방공탁금을 회수청구할 수 있다고 본다.","c":"중","v":1},"법무사2021_27-47-3":{"w":"담보권리자의 출급에는 피담보채권 발생 증명서면이 필요하다(공탁규칙 제33조). 공탁 실무는 확정판결 외에 공탁자의 동의서(인감증명서 첨부)도 그 서면으로 인정한다.","c":"중","v":1},"법무사2021_27-49-1":{"w":"재판상 담보공탁 피공탁자는 질권자와 같은 권리가 있다(민사소송법 제123조). 질권자는 별제권자이므로 담보제공자가 파산해도 파산절차에 의하지 않고 권리를 행사할 수 있다(채무자회생법 제411조).","c":"중","v":1},"법무사2022_28-32-2":{"w":"체납처분 압류는 국세징수법상 압류채권자가 제3채무자인 국가에 직접 추심할 수 있다. 그래서 출급청구권에 체납처분 압류가 송달되고 추심청구가 있으면 공탁관은 응해야 한다(공탁 업무처리지침).","c":"중","v":1},"법무사2022_28-36-1":{"w":"판례는 채권자 불확지 사유와 집행공탁 사유가 함께 생기면 혼합공탁을 할 수 있으며 그 공탁은 양수인에게는 변제공탁, 압류채권자에게는 집행공탁 효력이 있다고 본다.","c":"중","v":1},"법무사2022_28-36-2":{"w":"지참채무의 이행지는 채권자 주소지다(민법 제467조 제2항). 혼합공탁 피공탁자가 여럿이면 그중 1인의 주소지 공탁소가 관할공탁소가 된다(공탁선례).","c":"중","v":1},"법무사2022_28-36-3":{"w":"판례는 혼합공탁 피공탁자가 출급하려면 다른 피공탁자와 집행채권자 모두에 대한 관계에서 출급청구권을 증명하는 서면을 내야 한다고 본다.","c":"중","v":1},"법무사2022_28-36-4":{"w":"판례는 혼합공탁 요건을 갖추지 못해 유효한 공탁이 아니면 공탁자가 착오공탁을 이유로 회수할 수 있다고 본다(공탁법 제9조 제2항 제2호).","c":"중","v":1},"법무사2022_28-38-2":{"w":"물상대위 압류·추심명령이 여럿이면 담보권 순위에 따라 우열이 달라져 공탁관이 판단하기 어렵다. 행정예규 제1225호 1. 나. (4)에 따라 사유신고를 할 수 있다.","c":"중","v":1},"법무사2022_28-38-3":{"w":"행정예규 제1225호 1. 나. (1): 가압류 원인 공탁 뒤 출급청구권에 압류 경합이 생기거나 가압류를 본압류로 이전하는 압류명령이 국가에 송달되면 공탁관은 사유신고를 한다.","c":"상","v":1},"법무사2022_28-38-4":{"w":"행정예규 제1225호는 압류 경합과 배당 필요가 있을 때 사유신고를 하게 한다. 경합이 없으면 압류채권자가 추심이나 전부로 직접 받으므로 공탁관은 공탁과 사유신고를 하지 않는다.","c":"중","v":1},"법무사2022_28-38-5":{"w":"일부 가압류 뒤 전부에 대한 압류·전부명령이 있으면 집행채권 총액이 채권 총액을 넘어 압류가 경합하고 전부명령은 효력이 없다(민사집행법 제229조 제5항). 그래서 공탁관은 사유신고를 하고 배당에 따라 지급한다(행정예규 제1225호).","c":"중","v":1},"법무사2022_28-39-1":{"w":"판례는 해방공탁으로 가압류 집행이 취소되어도 가압류명령 자체는 효력을 잃지 않고 그 효력이 공탁자인 채무자의 회수청구권에 미친다고 본다.","c":"중","v":1},"법무사2022_28-39-2":{"w":"가압류채권자의 채권자가 받은 가압류는 가압류채권자가 장래 받을 권리에 대한 것이어서 공탁자의 회수권을 막지 못한다. 해방공탁 원인 가압류가 효력을 잃었음을 증명해 회수청구하면 인가해야 한다(공탁선례).","c":"중","v":1},"법무사2022_28-39-3":{"w":"가압류 효력이 회수청구권에 미치므로 다른 채권자가 같은 회수청구권을 압류·추심하면 경합한다(판례). 그래서 공탁관은 지체 없이 집행법원에 사유신고를 한다(공탁규칙 제58조).","c":"중","v":1},"법무사2022_28-39-5":{"w":"해방공탁금에는 가압류채권자의 출급청구권이 없고 채무자의 회수청구권만 있다. 그래서 가압류채권자의 국가에 대한 출급청구권을 대상으로 한 압류·전부명령은 대상 채권이 없어 무효이고 사유신고나 지급을 할 수 없다(공탁선례).","c":"중","v":1},"법무사2023_29-33-1":{"w":"민사집행법 제248조 제1항으로 일부 압류된 채권 전액을 공탁하면 압류가 미치지 않는 부분은 변제공탁 성질이다. 그래서 압류채무자가 변제공탁 예에 따라 출급하고 공탁자도 민법 제489조 제1항으로 회수할 수 있다(판례·공탁선례).","c":"중","v":1},"법무사2023_29-33-3":{"w":"가압류 취하는 취하통지가 제3채무자에게 도달해야 효력이 생긴다는 것이 판례다. 도달 전에 같은 채권에 압류·전부명령이 송달되면 가압류와 압류가 경합해 집행공탁을 할 수 있다.","c":"중","v":1},"법무사2023_29-33-4":{"w":"민사집행법 제236조 제2항: 추심 신고 전에 다른 압류·배당요구가 있으면 추심채권자는 추심한 금액을 바로 공탁하고 사유를 신고해야 한다. 체납처분 압류와 경합한 경우에도 같다(공탁 업무처리지침).","c":"중","v":1},"법무사2023_29-33-5":{"w":"판례는 제3채무자가 집행공탁을 하면 그 채권은 소멸하므로 그 뒤 송달된 압류·가압류는 발령이 먼저였어도 효력이 생기지 않는다고 본다.","c":"중","v":1},"법무사2023_29-35-1":{"w":"판례는 보전명령이 집행되지 않았거나 집행불능이어도 명령 존재만으로 명예·신용 훼손 등 정신적 손해가 생길 수 있어 그 배상청구권과 보전명령을 다투는 소송비용도 피담보채권에 포함된다고 본다.","c":"중","v":1},"법무사2023_29-35-3":{"w":"재판상 담보공탁의 출급에 관한 공탁 실무 예규는 이행·확인 판결, 화해·조정조서·공정증서 등, 공탁자 동의서(인감증명 첨부)를 피담보채권 발생 증명서면으로 본다.","c":"중","v":1},"법무사2023_29-35-4":{"w":"판례는 가압류 담보가 부당한 가압류로 인한 손해를 담보할 뿐이어서 본안소송 응소 비용은 가압류로 인한 손해가 아니라고 본다. 그래서 담보 범위에 들지 않는다.","c":"중","v":1},"법무사2023_29-35-5":{"w":"민사집행법 제307조의 특별사정 가처분취소 담보는 채권자가 본안에서 이겨도 목적물이 없어져 입는 손해를 담보한다. 판례는 채권자가 그 손해배상 승소판결을 받으면 질권자와 같은 권리로 우선변제를 받는다고 본다.","c":"중","v":1},"법무사2024_30-32-1":{"w":"가압류 원인 집행공탁은 민사집행법 제291조·제248조 제1항이 근거이고 피공탁자는 가압류채무자다. 제3채무자는 같은 조 제4항에 따라 공탁 후 공탁서를 붙여 가압류 발령법원에 신고한다.","c":"중","v":1},"법무사2024_30-32-2":{"w":"판례는 가압류된 금전채권액을 공탁하면 가압류 효력이 그 청구채권액에 해당하는 공탁금에 대한 가압류채무자의 출급청구권에 존속한다고 본다.","c":"중","v":1},"법무사2024_30-32-4":{"w":"가압류는 배당을 하지 않으므로 가압류채권자는 본압류 이전 압류명령을 받아야 배당이 열린다. 그 뒤 집행법원의 지급위탁으로 출급한다(공탁 실무 예규).","c":"중","v":1},"법무사2024_30-32-5":{"w":"가압류가 취소·취하로 효력을 잃으면 공탁금 출급청구권의 제한이 풀린다. 피공탁자인 가압류채무자는 실효 증명서면을 붙여 공탁관에게 바로 출급청구할 수 있다(공탁 실무 예규).","c":"중","v":1},"법무사2024_30-34-1":{"w":"혼합공탁의 피공탁자는 변제공탁 관련 채권자인 양도인 또는 양수인이고 가압류채권자는 적지 않는다. 다만 집행공탁 부분 근거를 위해 공탁원인사실에 가압류 사실을 구체적으로 적는다(공탁 실무 예규).","c":"중","v":1},"법무사2024_30-34-2":{"w":"혼합공탁 신청에는 가압류결정문 사본과 피공탁자 수만큼의 공탁통지서를 붙이고 공탁통지서·공탁사실통지서 발송 우편료를 함께 낸다(공탁규칙 제23조, 공탁 실무 예규).","c":"중","v":1},"법무사2024_30-34-3":{"w":"혼합공탁 피공탁자는 다른 피공탁자와 집행채권자 모두에 대해 출급권을 증명해야 한다(판례). 양수인은 양도인 승낙서나 그에 대한 승소확정판결과 가압류채권자 승낙서나 그에 대한 승소확정판결을 낸다(공탁선례).","c":"중","v":1},"법무사2024_30-34-5":{"w":"혼합공탁은 양도 효력 문제가 해소되어야 집행공탁 부분이 확정된다. 그래서 그 뒤 압류 경합이나 본압류 이전이 있어도 혼합해소문서가 제출된 뒤 압류 발령법원에 해소문서 사본을 붙여 사유신고를 한다(행정예규 제1225호).","c":"중","v":1},"법무사2024_30-36-1":{"w":"판례는 공탁자가 자기 책임과 판단으로 변제공탁·집행공탁·혼합공탁 중 하나를 선택할 수 있다고 본다.","c":"중","v":1},"법무사2024_30-36-2":{"w":"판례는 공탁 종류를 피공탁자 지정, 근거 조문, 공탁사유, 사유신고 등을 종합해 합리적으로 판단한다.","c":"중","v":1},"법무사2024_30-36-3":{"w":"판례는 일부 압류된 채권 전액을 민사집행법 제248조 제1항으로 공탁하면 압류된 부분은 집행공탁, 압류를 넘는 부분은 변제공탁으로 본다.","c":"중","v":1},"법무사2024_30-36-5":{"w":"민사집행법 제247조 제1항의 배당가입 차단효는 배당을 전제로 한 집행공탁에만 생긴다. 판례는 혼합공탁의 변제공탁 부분에는 생길 여지가 없다고 본다.","c":"중","v":1},"법무사2024_30-37-1":{"w":"양도통지와 가압류결정이 동시에 송달되면 우열을 알 수 없어 채권자 불확지와 가압류 집행공탁 사유가 함께 생긴다. 피공탁자는 「양도인 또는 양수인」, 근거는 민법 제487조 후단과 민사집행법 제291조·제248조 제1항으로 한다(판례·공탁선례).","c":"하","v":1},"법무사2024_30-37-2":{"w":"제3취득자는 근저당권 소멸을 위해 변제해야 하는데 근저당권부 채권에 압류가 경합하면 채권자에게 바로 줄 수 없다. 공탁선례는 이때 근저당권자를 피공탁자로 한 혼합공탁을 하게 한다.","c":"중","v":1},"법무사2024_30-37-3":{"w":"가처분권자가 패소 확정되면 불확지 변제공탁 부분은 토지소유자에게 귀속이 정해지고 가압류가 실효되면 집행공탁 부분도 해소된다. 그래서 토지소유자는 확정판결과 가압류 실효 증명서면으로 출급할 수 있다(공탁선례).","c":"중","v":1},"법무사2024_30-37-5":{"w":"하도급법 제14조의 직접청구권 발생 여부나 압류와의 우열을 알 수 없으면 발주자는 채권자 불확지 변제공탁과 집행공탁을 결합한 혼합공탁을 할 수 있다는 것이 판례다.","c":"하","v":1},"법무사2024_30-38-1":{"w":"판례는 해방금 공탁 후 가압류 효력이 공탁금 자체가 아니라 공탁자인 채무자의 공탁금 회수청구권에 미친다고 본다.","c":"중","v":1},"법무사2024_30-38-3":{"w":"해방공탁금은 채무자의 회수청구권 형태로 남으므로 가압류채권자가 받으려면 본안 승소판결 등 집행권원으로 회수청구권에 대한 압류와 추심·전부 같은 현금화명령을 받아야 한다(판례·공탁 실무).","c":"중","v":1},"법무사2024_30-38-4":{"w":"본압류 이전 형식이 아닌 별도 압류·전부명령으로 지급청구하면 그것이 해방공탁의 원인인 가압류의 본집행인지 알 수 없다. 그래서 피보전권리와 집행채권이 같다는 것을 소명해야 한다(공탁선례).","c":"하","v":1},"법무사2024_30-38-5":{"w":"해방공탁금 회수는 공탁원인 소멸(공탁법 제9조 제2항 제3호)에 해당하므로 가압류 취소판결과 확정증명이나 취하·해제 증명서 등 원인 소멸 증명서면을 붙인다(공탁 실무 예규).","c":"중","v":1},"법무사2024_30-39-2":{"w":"판례는 해방공탁 후 집행취소를 받은 채무자는 가압류로 적어도 해방공탁금에 대한 민사 법정이율(연 5%)과 공탁금 이율의 차액만큼 손해를 입었다고 본다.","c":"중","v":1},"법무사2024_30-39-3":{"w":"판례는 심급별 집행정지 담보가 각 심급의 정지로 인한 손해를 담보하므로 항소심에서 다시 담보를 냈다고 1심 담보사유가 소멸하지 않는다고 본다.","c":"중","v":1},"법무사2024_30-39-4":{"w":"판례는 금전 지급이나 명도·차임을 명한 가집행 판결의 집행정지 담보에 정지 기간 중 생긴 지연손해금이나 차임 상당 손해가 포함된다고 본다.","c":"중","v":1},"법무사2024_30-39-5":{"w":"판례는 강제집행정지 담보가 정지 자체로 채권자가 입은 손해배상채권을 담보하고 집행 대상인 본래 채권은 담보하지 않는다고 본다.","c":"중","v":1},"법무사2024_30-47-1":{"w":"행정예규 제1225호는 재판상 담보공탁금 회수청구권에 압류가 경합하면 공탁원인 소멸 증명서면이 제출된 때 사유신고를 하게 한다. 법원이 다르면 먼저 송달된 압류명령의 집행법원에 한다(사유신고 지침).","c":"중","v":1},"법무사2024_30-47-2":{"w":"물상대위 압류·추심명령이 여럿이면 담보권 순위로 우열이 정해져 공탁관이 판단하기 어렵다. 행정예규 제1225호 1. 나. (4)에 따라 사유신고를 할 수 있다.","c":"중","v":1},"법무사2024_30-47-3":{"w":"행정예규 제1225호는 복수의 가압류만 있는 경우를 집행채권 총액이 넘더라도 사유신고 대상에서 뺀다. 가압류만으로는 배당을 할 수 없기 때문이다.","c":"상","v":1},"법무사2024_30-47-5":{"w":"사유신고 사정이 생기면 공탁규칙 제58조에 따라 공탁관은 지체 없이 집행법원에 신고해야 하고 배당으로 지급해야 한다. 추심채권자 등의 개별 지급청구는 수리하지 않는다(행정예규 제1225호).","c":"중","v":1},"법무사2024_30-48-2":{"w":"민사소송법 제125조 제2항: 담보제공자가 담보취소에 대한 담보권리자의 동의를 받았음을 증명하면 법원은 담보취소결정을 한다.","c":"상","v":1},"법무사2024_30-48-3":{"w":"판례는 이의에 따라 가처분을 취소하며 명한 담보는 가처분 취소 자체로 채권자가 입은 손해를 담보한다고 본다.","c":"중","v":1},"법무사2024_30-48-4":{"w":"판례는 가집행선고부 항소심 판결이 상고심에서 파기·환송되면 그 판결의 효력이 없어지므로 집행정지 담보의 원인도 소멸한다고 본다.","c":"중","v":1},"법무사2024_30-48-5":{"w":"민사소송법 제125조와 실무는 담보취소 신청을 담보제공을 명한 법원 또는 그 기록을 보관하는 법원이 관할하게 한다.","c":"중","v":1},"법무사2025_31-33-1":{"w":"민사집행법 제248조 제2항: 배당요구서를 송달받은 제3채무자는 배당에 참가한 채권자의 청구가 있으면 압류된 부분 금액을 공탁해야 한다.","c":"상","v":1},"법무사2025_31-33-2":{"w":"민사집행법 제248조 제3항: 압류되지 않은 부분을 넘어 거듭 압류·가압류가 내려진 경우 이를 송달받은 제3채무자는 압류·가압류채권자의 청구가 있으면 채권 전액을 공탁해야 한다.","c":"상","v":1},"법무사2025_31-33-3":{"w":"민사집행법 제248조 제4항: 제3채무자가 채무액을 공탁하면 그 사유를 법원에 신고해야 한다.","c":"상","v":1},"법무사2025_31-33-5":{"w":"민사집행법 제249조 제1항: 제3채무자가 추심 절차에 따른 의무를 이행하지 않으면 압류채권자는 소로써 그 이행을 청구할 수 있다. 판례는 공탁을 명하는 추심소송도 이에 포함된다고 본다.","c":"중","v":1},"법무사2025_31-39-1":{"w":"판례는 해방금액이 가압류 전체를 위한 하나의 금액이어서 공동채무자 일부가 자기 몫만 공탁하고 그 공유 부동산의 가압류 일부 취소를 구할 수 없다고 본다.","c":"중","v":1},"법무사2025_31-39-2":{"w":"해방공탁금은 채무자가 회수하는 형태로만 남고 가압류 효력도 그 회수청구권에 미친다(판례). 그래서 가압류채권자의 출급청구권은 없다.","c":"중","v":1},"법무사2025_31-39-3":{"w":"공탁 실무는 해방공탁을 가압류채권자나 채무자의 보통재판적 소재지 지방법원 또는 가압류를 발령한 집행법원 공탁소에 할 수 있게 한다.","c":"중","v":1},"법무사2025_31-39-4":{"w":"판례는 압류·전부명령의 효력이 송달 전에 생긴 공탁금 이자에 당연히 미치지 않는다고 본다. 이자에 대한 언급이 없으면 공탁일부터 송달 전날까지의 이자는 전부채권자에게 줄 수 없다.","c":"중","v":1},"법무사2025_31-40-1":{"w":"판례는 체납처분 압류가 있는 채권에도 민사집행법상 압류·추심명령을 할 수 있고 그 추심채권자는 제3채무자를 상대로 추심의 소를 낼 수 있다고 본다.","c":"중","v":1},"법무사2025_31-40-2":{"w":"판례와 공탁 업무처리지침은 체납처분 압류와 민사집행법상 압류가 경합하면 선후와 관계없이 제3채무자가 제248조에 따라 집행공탁을 할 수 있다고 본다.","c":"중","v":1},"법무사2025_31-40-3":{"w":"민사집행법 제248조 제1항의 「압류」는 민사집행법상 압류를 말한다. 체납처분 압류는 이에 포함되지 않아 그것만으로는 집행공탁을 할 수 없다(판례·공탁 업무처리지침).","c":"중","v":1},"법무사2025_31-40-5":{"w":"공탁 업무처리지침은 가압류와 체납처분 압류가 경합하면 선후와 관계없이 민사집행법 제291조·제248조 제1항의 공탁을 허용한다.","c":"중","v":1},"법무사2025_31-45-2":{"w":"혼합공탁의 집행공탁 부분은 민사집행법 제248조 제4항의 사유신고 대상이다. 그래서 제3채무자는 지체 없이 압류 발령법원에 신고한다(공탁 실무 예규).","c":"중","v":1},"법무사2025_31-45-3":{"w":"혼합공탁의 집행공탁 부분은 배당절차로 지급되므로 집행채권자는 집행법원의 지급위탁으로 출급한다(공탁 실무 예규).","c":"중","v":1},"법무사2025_31-45-4":{"w":"장래 채권을 포함한 양도는 그 효력과 가압류와의 우열에 의문이 생길 수 있다. 판례는 이 경우 양도인 또는 양수인을 피공탁자로 민법 제487조, 민사집행법 제291조·제248조 제1항에 근거한 혼합공탁을 허용한다.","c":"중","v":1},"법무사2025_31-45-5":{"w":"압류·가압류가 미치지 않는 부분은 순수한 변제공탁이어서 공탁자는 민법 제489조 제1항에 따라 회수할 수 있다(공탁선례).","c":"중","v":1},"법무사2025_31-48-1":{"w":"가압류만으로는 배당을 할 수 없으므로 가압류와 압류가 경합하면 공탁관은 압류명령을 발령한 법원에 사유신고를 한다(공탁관 사유신고 지침).","c":"중","v":1},"법무사2025_31-48-2":{"w":"행정예규 제1225호 1. 나. (2): 민사집행법상 압류와 체납처분 압류의 총액이 피압류채권을 넘으면 공탁관은 집행법원에 사유신고를 한다.","c":"상","v":1},"법무사2025_31-48-3":{"w":"행정예규 제1225호는 금전공탁이 아닌 유가증권·물품공탁을 사유신고 대상에서 뺀다.","c":"상","v":1},"법무사2025_31-48-5":{"w":"행정예규 제1225호는 지급청구권이 양도되어 대항요건을 갖춘 뒤의 압류 경합을 사유신고 대상에서 뺀다. 이미 양수인의 권리여서 양도인 채권자의 압류는 효력이 없다.","c":"상","v":1},"법무사2025_31-49-1":{"w":"민사집행법 제248조 제1항은 압류에 관련된 금전채권 전액을 공탁할 수 있게 한다. 그래서 일부 압류이면 압류된 금액만 공탁하거나 채권 전액을 공탁할 수 있다(판례).","c":"중","v":1},"법무사2025_31-49-2":{"w":"대위채권자에게 직접 이행하라는 판결이 있어도 피대위권리는 여전히 채무자의 채권이어서 압류할 수 있다는 것이 판례다. 압류·추심명령이 순차 송달되면 제3채무자는 제248조 제1항으로 공탁할 수 있다.","c":"중","v":1},"법무사2025_31-49-3":{"w":"압류금지채권 부분의 압류는 무효인데 이를 배당하면 채무자 몫을 다른 채권자가 받은 것이 된다. 판례는 채무자가 그 채권자들을 상대로 배당이의의 소를 낼 수 있다고 본다.","c":"중","v":1},"법무사2025_31-49-4":{"w":"집행공탁 사유를 증명하기 위해 공탁신청 때 압류결정문 사본을 붙인다(공탁 실무 예규).","c":"중","v":1},"법무사2025_31-50-1":{"w":"가압류 원인 집행공탁을 수리하면 공탁관은 피공탁자인 가압류채무자에게 공탁통지서를, 가압류채권자에게 공탁사실통지를 한다(공탁 실무 예규).","c":"중","v":1},"법무사2025_31-50-2":{"w":"배당가입 차단효(민사집행법 제247조 제1항 제1호)는 압류에 따른 사유신고에서 생긴다. 가압류만을 원인으로 한 공탁과 신고로는 배당절차가 시작되지 않아 차단효가 없다(판례).","c":"중","v":1},"법무사2025_31-50-4":{"w":"가압류 원인 공탁의 피공탁자는 가압류채무자이므로 공탁규칙 제23조에 따라 공탁통지서를 첨부한다.","c":"중","v":1},"법무사2025_31-50-5":{"w":"해방공탁으로 가압류 1건이 집행취소되면 그 가압류의 효력은 공탁금에서 빠진다. 남은 가압류 청구금액을 넘는 부분은 제한이 풀려 가압류채무자가 출급할 수 있다(공탁선례).","c":"중","v":1},"법무사2026_32-36-1":{"w":"판례는 권리행사최고에 따라 담보권리자가 제기한 소송의 비용을 강제집행정지로 인한 통상손해로 보아 집행정지 담보공탁금의 피담보채권에 넣는다.","c":"중","v":1},"법무사2026_32-36-2":{"w":"판례는 가압류 담보가 부당 가압류로 인한 손해를 담보할 뿐이어서 본안 응소 비용은 가압류로 인한 손해가 아니라고 본다.","c":"중","v":1},"법무사2026_32-36-3":{"w":"판례는 경매절차 정지 담보가 정지로 채권자가 입은 손해배상청구권만 담보하고 근저당권 피담보채권이나 말소소송 비용에는 미치지 않는다고 본다.","c":"중","v":1},"법무사2026_32-36-5":{"w":"판례는 가압류 담보가 부당 가압류로 인한 손해를 담보하므로 가압류 취소를 위해 든 소송비용은 그 손해에 포함된다고 본다. 본안 응소 비용과 구별된다.","c":"중","v":1},"법무사2026_32-37-2":{"w":"혼합공탁의 피공탁자는 변제공탁 관련 채권자(양도인·양수인 등)이고 압류·가압류채권자는 배당으로 지급받으므로 피공탁자란에 적지 않는다(공탁 실무 예규).","c":"중","v":1},"법무사2026_32-37-3":{"w":"판례는 혼합공탁 피공탁자가 출급하려면 다른 피공탁자와 집행채권자 모두에 대해 출급청구권이 있음을 증명하는 서면을 내야 한다고 본다.","c":"중","v":1},"법무사2026_32-37-4":{"w":"판례는 선행 양도에 다툼이 없어 불확지 사유가 없는데 혼합공탁을 했다면 요건을 갖추지 못해 유효한 공탁이 아니라고 본다.","c":"중","v":1},"법무사2026_32-37-5":{"w":"혼합공탁의 변제공탁 부분은 채무이행지(지참채무는 채권자 주소) 공탁소에 해야 한다(민법 제488조). 채권자 불확지이면 피공탁자 중 1인의 주소지 공탁소에 할 수 있다(공탁선례).","c":"중","v":1},"법무사2026_32-38-2":{"w":"판례는 가처분 집행에 착수했으면 집행불능 후 신청을 취하해도 채무자가 명예·신용 등 손해를 입었을 수 있어 그것만으로 담보사유가 소멸하지 않는다고 본다.","c":"중","v":1},"법무사2026_32-38-3":{"w":"판례는 본안이 계속 중이면 보전처분이 이의로 취소 확정되고 집행이 해제되어도 민사소송법 제125조의 「소송이 완결된 뒤」가 아니고 본안까지 확정되어야 완결로 본다.","c":"중","v":1},"법무사2026_32-38-4":{"w":"판례는 담보 대상 손해에 통상손해뿐 아니라 배상의무자가 알았거나 알 수 있었던 특별손해도 포함된다고 본다(민법 제393조).","c":"중","v":1},"법무사2026_32-38-5":{"w":"민사소송법 제125조 제3항은 권리행사기간 안에 권리를 행사하지 않으면 담보취소에 동의한 것으로 본다. 판례는 소를 냈다가 취하하는 등 처음부터 권리행사가 없던 것으로 되면 기간 경과로 동의가 간주된다고 본다.","c":"중","v":1},"법무사2026_32-45-1":{"w":"민사집행법 제248조 제3항은 거듭 압류된 채권의 제3채무자가 채권자의 청구가 있으면 전액을 공탁하게 한다. 판례는 「공탁하여야 한다」를 공탁하지 않고는 면책받을 수 없다는 의미로 본다.","c":"중","v":1},"법무사2026_32-45-2":{"w":"판례는 민사집행법 제248조 제3항의 공탁의무가 집행절차상 제3채무자의 협력의무일 뿐 그의 실체법상 지위를 바꾸지 않는다고 본다.","c":"중","v":1},"법무사2026_32-45-3":{"w":"판례는 공탁의무가 있는 제3채무자가 한 추심채권자에게 임의 변제하거나 일부 채권자가 추심했더라도 공탁청구한 채권자 외의 채권자에게는 채무 소멸을 주장할 수 있다고 본다.","c":"중","v":1},"법무사2026_32-45-4":{"w":"판례는 공탁청구 채권자가 제3채무자에게 추심할 수 있는 금액을 전액이 공탁되었다면 배당받았을 금액으로 한정한다. 그보다 많이 추심하게 하면 정당한 기대를 넘기 때문이다.","c":"중","v":1},"법무사2026_32-48-1":{"w":"민사집행법 제236조 제2항: 추심 신고 전에 다른 압류·가압류·배당요구가 있으면 채권자는 추심한 금액을 바로 공탁하고 그 사유를 신고해야 한다.","c":"상","v":1},"법무사2026_32-48-3":{"w":"민사집행법 제252조 제2호: 추심채권자가 제236조에 따라 공탁하거나 제3채무자가 제248조에 따라 공탁하면 법원은 배당절차를 개시한다.","c":"상","v":1},"법무사2026_32-48-4":{"w":"민사집행규칙 제162조 제2항: 민사집행법 제236조 제2항의 신고는 사건·채권자·채무자·제3채무자 표시, 지급받은 금액과 날짜(제1항 사항)에 공탁사유와 공탁 금액을 적은 서면에 공탁서를 붙여서 한다.","c":"상","v":1},"법무사2026_32-48-5":{"w":"판례는 추심채권자가 지체 없이 공탁·신고하지 않으면 상당한 기간이 지난 때부터 실제 공탁 때까지 법정지연손해금 상당액도 손해배상으로 공탁할 의무가 있다고 본다.","c":"중","v":1},"법무사2016_22-31-1":{"w":"공탁규칙 제34조 제2호 단서: 회수청구권 증명서면은 공탁서 내용으로 회수청구권이 명백하면 내지 않아도 된다. 민법 제489조 제1항의 회수는 공탁서상 공탁자가 하는 것이어서 원칙적으로 따로 증명서면이 필요 없다.","c":"상","v":1},"법무사2016_22-31-2":{"w":"공탁법 제10조는 「공탁물을 수령할 자」가 반대급부를 하여야 하는 경우만 규정한다. 그래서 반대급부는 피공탁자의 출급을 제한할 뿐 공탁자의 회수에는 제한사유가 아니다(공탁선례).","c":"상","v":1},"법무사2016_22-31-3":{"w":"판례는 배당 실시 전에 공탁자가 착오 집행공탁을 이유로 사유신고를 철회하고 그 공탁이 원인 없는 무효임이 명백하면 집행법원이 사유신고 불수리결정을 할 수 있다고 본다. 공탁자는 그 결정을 내고 착오공탁으로 회수한다(공탁법 제9조 제2항 제2호).","c":"중","v":1},"법무사2016_22-31-5":{"w":"판례는 선행 양도에 다툼이 없어 불확지 사유가 없는데 혼합공탁을 했다면 요건을 갖추지 못한 무효 공탁이어서 공탁자가 착오공탁으로 회수할 수 있다고 본다(공탁법 제9조 제2항 제2호).","c":"중","v":1},"법무사2016_22-34-1":{"w":"피공탁자는 공탁서 기재로 형식적으로 정해진다(판례). 「甲과 乙」 2인이 피공탁자이면 甲 단독소유 증명서류를 내도 甲 혼자 전액을 출급할 수 없다는 것이 공탁선례다.","c":"중","v":1},"법무사2016_22-34-2":{"w":"「토지수용 등의 보상금의 공탁에 관한 사무처리지침」(행정예규 제1345호) 제10조 제2항: 수용개시일 전에 피공탁자로부터 소유권을 승계한 사람은 공탁서 정정 없이 승계 사실 증명서면을 붙여 출급할 수 있다.","c":"상","v":1},"법무사2016_22-34-4":{"w":"행정예규 제1345호 제12조: 절대적 불확지공탁의 정당한 권리자는 공탁자에게 자신을 피공탁자로 지정하는 정정을 하게 하거나 출급청구권이 자신에게 있다는 확인판결정본과 확정증명을 붙여 출급할 수 있다.","c":"상","v":1},"법무사2016_22-34-5":{"w":"합유자가 사망하면 특약이 없는 한 지분은 잔존 합유자에게 귀속되고 상속되지 않는다(판례). 그래서 합유 토지 보상금 공탁금 출급청구권도 사망자의 상속인에게 승계되지 않는다(공탁선례).","c":"중","v":1},"법무사2016_22-36-3":{"w":"채권양도 통지는 양도인이 하지만 사자나 대리인을 통해서도 할 수 있다는 것이 판례다. 그래서 양수인이 양도인에게서 통지 권한을 위임받아 대리인으로 통지할 수 있다.","c":"중","v":1},"법무사2016_22-38-1":{"w":"판례는 저당권자의 물상대위(민법 제370조, 제342조)에 압류가 필요하지만 담보권에 기한 것이어서 집행권원이 필요 없다고 본다. 담보권 존재 증명서류로 압류를 신청한다(민사집행법 제273조).","c":"중","v":1},"법무사2016_22-38-2":{"w":"판례는 물상대위의 압류를 저당권자가 직접 할 필요가 없고 제3자의 압류로 목적물이 특정되었으면 스스로 압류하지 않아도 물상대위권을 행사할 수 있다고 본다.","c":"중","v":1},"법무사2016_22-38-3":{"w":"제3채무자가 공탁하고 사유신고를 하면 배당요구 종기가 지나 배당가입이 차단된다(민사집행법 제247조 제1항). 판례는 그 뒤에는 저당권자가 물상대위로 우선변제를 받을 수 없다고 본다.","c":"중","v":1},"법무사2016_22-38-4":{"w":"물상대위 압류 없이 일반채권으로 가압류만 했다면 담보권자로서 우선변제권을 행사한 것이 아니다. 판례는 다른 채권자 압류로 사유신고가 되면 근저당권자는 가압류채권자로서 안분배당만 받는다고 본다.","c":"중","v":1},"법무사2016_22-45-2":{"w":"공탁규칙 제37조 제1항은 출급·회수청구서나 위임장에 찍힌 인감의 인감증명서를 내게 하고 공증인 인증으로 갈음하는 규정이 없다. 그래서 위임장 공증으로 인감증명서를 대신할 수 없다(공탁선례).","c":"중","v":1},"법무사2016_22-45-4":{"w":"「재외국민 등의 공탁에 관한 업무처리지침」(행정예규 제1431호) 제9조 제1항: 재외국민의 상속재산분할협의서에 붙일 인감증명은 재외공관 공증법에 따른 인증이나 체류국 또는 대한민국 공증인의 공정증서로 대신할 수 있다.","c":"상","v":1},"법무사2016_22-45-5":{"w":"공탁규칙 제37조 제3항 제2호: 관공서가 출급·회수청구를 하면 금액과 관계없이 인감증명서 제출 규정을 적용하지 않는다.","c":"상","v":1},"법무사2016_22-46-1":{"w":"소멸시효는 권리를 행사할 수 있는 때부터 진행한다(민법 제166조, 공탁법 제9조 제3항). 판례는 상대적 불확지 공탁에서 출급청구권자가 확정된 때부터 출급청구권 시효가 진행한다고 본다.","c":"중","v":1},"법무사2016_22-46-2":{"w":"착오 공탁의 회수청구권은 공탁 때부터 행사할 수 있으므로 공탁일부터 공탁법 제9조 제3항의 10년 시효가 진행한다(판례). 10년이 지나면 회수할 수 없다.","c":"중","v":1},"법무사2016_22-46-3":{"w":"공탁으로 소멸한 원래 채권과 공탁금 지급청구권은 별개의 권리다. 그래서 원래 채권의 시효는 공탁금 지급청구권 시효(공탁법 제9조 제3항)와 관계가 없다(판례).","c":"중","v":1},"법무사2016_22-46-4":{"w":"공탁금 지급청구는 권리 행사여서 첨부서면 불비로 불수리되었더라도 청구 자체로 시효가 중단된다는 것이 공탁선례(공탁금 소멸시효 관련 예규)다.","c":"중","v":1},"법무사2016_22-50-1":{"w":"전자공탁 사무처리지침은 전자공탁시스템으로 출급·회수를 청구하면 공탁규칙 제35조의 일괄청구를 할 수 없고 사건별로 청구하게 한다.","c":"중","v":1},"법무사2016_22-50-3":{"w":"대공탁·부속공탁은 기본 유가증권공탁과 동일성이 있으므로 출급·회수청구서는 기본공탁에 포함시켜 공탁 종류별로 1건으로 쓸 수 있다(공탁 실무 예규, 공탁규칙 제35조).","c":"중","v":1},"법무사2016_22-50-4":{"w":"공탁규칙 제35조의 일괄청구는 청구 사유가 같아야 하므로 분할 지급이 필요한 공탁이 섞여 있으면 일괄청구할 수 없다(공탁 실무 예규).","c":"중","v":1},"법무사2016_22-50-5":{"w":"일괄청구 중 일부가 불수리 대상이면 하나의 청구서로 함께 처리할 수 없다. 그래서 그런 경우 일괄청구를 할 수 없다(공탁 실무 예규).","c":"중","v":1},"법무사2017_23-34-1":{"w":"「계좌입금에 의한 공탁금 출급·회수절차에 관한 업무처리지침」(행정예규 제1391호)은 신청인이 보관은행을 거쳐 이자소득세 원천징수 사항을 등록하고 신청서 하단에 등록확인인을 받게 하며 입금계좌는 신청인 명의여야 한다고 정한다.","c":"중","v":1},"법무사2017_23-34-3":{"w":"계좌입금 지침은 출급·회수청구자가 계좌입금을 신청하면 청구서를 1통만 내게 한다. 은행에 직접 제시할 청구서가 필요 없기 때문이다.","c":"중","v":1},"법무사2017_23-34-4":{"w":"계좌입금 지침은 신청인이 출급지시 전에 신청을 철회하거나 포괄계좌 신청을 해지하지 않는 한 계좌로만 지급하고 신청인이나 대리인에게 직접 지급하지 못하게 한다.","c":"중","v":1},"법무사2017_23-34-5":{"w":"공탁규칙 제79조 제3항은 전자 청구로 예금계좌에 입금하면 그 계좌가 청구인 본인 계좌여야 한다고 정한다. 전자청구에서도 본인 계좌 입금 방식을 쓸 수 있다는 전제다.","c":"상","v":1},"법무사2017_23-35-1":{"w":"판례는 저당권자의 물상대위권 행사를 민사집행법 제273조에 따라 담보권 증명서류를 내 채권압류·전부명령을 신청하거나 제247조 제1항에 따라 배당요구를 하는 방법으로 본다.","c":"중","v":1},"법무사2017_23-35-2":{"w":"판례는 물상대위의 압류가 목적물 특정을 위한 것이어서 제3자 압류로 이미 특정되었으면 저당권자가 다시 압류하지 않아도 물상대위권을 행사할 수 있다고 본다.","c":"중","v":1},"법무사2017_23-35-3":{"w":"판례는 저당권자가 물상대위권을 행사하지 않으면 등기만으로는 보상금에서 우선변제를 받을 수 없어 다른 채권자가 받아 가도 부당이득반환을 청구할 수 없다고 본다.","c":"중","v":1},"법무사2017_23-35-4":{"w":"판례는 사업인정 고시가 있으면 보상금 지급이 확실해져 재결 전이라도 보상금청구권에 물상대위권을 행사할 수 있다고 본다.","c":"중","v":1},"법무사2017_23-37-1":{"w":"판례는 양도통지를 양도인이 사자나 대리인을 통해 할 수 있으므로 양수인도 양도인으로부터 권한을 위임받아 대리인으로 통지할 수 있다고 본다.","c":"중","v":1},"법무사2017_23-37-3":{"w":"판례·공탁선례는 피공탁자의 출급청구권 양도통지가 공탁관에게 도달하면 불수락 의사가 적혀 있지 않은 한 공탁을 수락한 것으로 보아 민법 제489조 제1항의 회수청구권이 소멸한다고 본다.","c":"중","v":1},"법무사2017_23-37-4":{"w":"공탁 실무는 양도통지서의 인영에 인감증명이 없어도 적법한 양도통지로 취급해 양도인의 회수청구에 응하지 않는다. 대신 양수인이 청구할 때 양도인의 인감증명서를 내게 한다(공탁선례).","c":"중","v":1},"법무사2017_23-37-5":{"w":"양도 의사표시와 통지를 명하는 판결이 확정되면 그 의사표시가 있는 것으로 본다(민사집행법 제263조 제1항). 양수인은 판결과 확정증명을 국가(공탁관)에 송부·제시하고 출급받을 수 있다(공탁선례).","c":"중","v":1},"법무사2017_23-41-1":{"w":"공동 공탁에서 각자 금액을 나누지 않았으면 균등 비율로 공탁한 것으로 본다(민법 제408조 취지, 공탁선례). 그래서 담보취소 후 공탁자 1인은 1/2을 회수할 수 있다.","c":"중","v":1},"법무사2017_23-41-3":{"w":"채무가 처음부터 없었으면 변제공탁은 효력이 없어 착오로 공탁한 경우에 해당한다. 공탁자는 공탁법 제9조 제2항 제2호에 따라 회수할 수 있다(공탁선례).","c":"중","v":1},"법무사2017_23-41-4":{"w":"수용재결 실효 확정판결은 공탁원인 소멸을 증명한다(행정예규 제1345호 제9조 단서). 공탁 실무는 사업시행자 명의 이전등기 말소 등기사항증명서까지 요구하지 않는다(공탁선례).","c":"중","v":1},"법무사2017_23-41-5":{"w":"공탁규칙 제38조 제1항은 출급·회수청구에 제22조를 준용한다. 같은 사람이 동시에 같은 법원에 여러 건 청구하면 같은 첨부서면은 1건에만 붙이고 나머지 청구서에는 그 뜻을 적는다.","c":"상","v":1},"법무사2017_23-43-2":{"w":"행정예규 제1431호 제8조 제1항은 재외국민이 공탁규칙 제37조의 인감증명서를 낼 때 인감증명법에 따른 인감증명서를 내게 한다. 2025. 6. 1. 시행 지침은 위임장에 재외공관 공증법상 인증을 받는 방법도 허용한다(같은 조 제2항).","c":"중","v":1},"법무사2017_23-43-3":{"w":"행정예규 제1431호 제10조 제2항: 본국에 인감제도가 없는 외국인은 위임장 등의 서명이 본인 것이라는 본국 관공서 증명이나 본국 또는 대한민국 공증인의 공증(재외공관 인증 포함)으로 인감증명을 갈음한다.","c":"상","v":1},"법무사2017_23-43-4":{"w":"행정예규 제1431호 제11조: 외국국적 취득으로 성명이 바뀌면 변경 전후 성명이 동일인이라는 본국 관공서 증명이나 본국 공증인의 공증을 낸다.","c":"상","v":1},"법무사2017_23-43-5":{"w":"행정예규 제1431호 제10조 제1항은 외국인이 인감증명법에 따른 인감증명서나 본국 관공서 인감증명을 낼 수 있게 한다. 인감증명법 제3조 제3항상 외국인등록을 한 외국인은 인감을 신고할 수 있다.","c":"상","v":1},"법무사2017_23-44-1":{"w":"재판상 담보공탁 회수청구권은 담보취소결정 확정 등으로 행사할 수 있게 된 때부터 시효가 진행한다(민법 제166조). 공탁선례는 집행하지 않았거나 집행불능이면 담보취소결정 확정일, 재판 전 취하이면 취하일부터 기산한다.","c":"중","v":1},"법무사2018_24-35-1":{"w":"공탁규칙 제37조 제3항 제1호: 본인이 1천만 원 이하를 직접 청구하고 공탁관이 신분증으로 본인임을 확인할 수 있으면 인감증명서를 내지 않아도 된다.","c":"상","v":1},"법무사2018_24-35-2":{"w":"공탁규칙 제37조 제3항 제1호의 1천만 원은 청구하는 금액 기준이다. 공탁 실무는 피공탁자가 여럿이면 해당 피공탁자 몫의 공탁금이 1천만 원 이하인지로 판단한다.","c":"중","v":1},"법무사2018_24-35-3":{"w":"공탁규칙 제37조 제3항 제2호: 관공서가 출급·회수를 청구하면 금액과 관계없이 인감증명서 제출 규정을 적용하지 않는다.","c":"상","v":1},"법무사2018_24-35-4":{"w":"공탁규칙 제79조 제1항: 전자문서로 출급·회수를 청구하면 제37조 제1항·제2항의 인감증명서를 첨부하지 않는다.","c":"상","v":1},"법무사2018_24-39-2":{"w":"판례는 공탁원인이 소멸하면 공탁자의 회수권만 남고 피공탁자의 출급청구권은 없으므로 그 출급청구권에 대한 전부명령으로 공탁물을 받은 자는 공탁자에게 부당이득을 반환해야 한다고 본다.","c":"중","v":1},"법무사2018_24-41-2":{"w":"공탁규칙 제33조 제1호 다목: 강제집행이나 체납처분으로 출급청구하면 공탁통지서를 붙이지 않아도 된다. 추심·전부채권자의 청구가 이에 해당한다.","c":"상","v":1},"법무사2018_24-44-1":{"w":"판례는 피공탁자가 공탁서 기재로 형식적으로 정해지므로 실체상 채권자라도 피공탁자로 지정되지 않았으면 출급청구권을 행사할 수 없다고 본다.","c":"중","v":1},"법무사2018_24-44-2":{"w":"행정예규 제1345호 제10조 제3항 제4호와 판례는 피공탁자를 상대로 출급청구권 확인판결을 받은 제3자도 피공탁자가 아니어서 직접 출급할 수 없다고 본다.","c":"중","v":1},"법무사2018_24-44-4":{"w":"판례는 양도금지특약이 있는 채권도 전부명령으로는 전부채권자의 선의·악의와 관계없이 이전된다고 본다. 그래서 채권자를 알 수 없는 사정이 없어 불확지 변제공탁을 할 수 없다.","c":"하","v":1},"법무사2018_24-44-5":{"w":"행정예규 제1345호 제11조 제3항과 공탁선례는 상대적 불확지공탁에서 공탁자의 승낙서나 공탁자·국가를 상대로 한 판결을 출급청구권 증명서면으로 보지 않는다. 귀속은 피공탁자들 사이에서 정해야 하기 때문이다.","c":"중","v":1},"법무사2018_24-50-1":{"w":"담보권리자의 출급청구권은 담보권을 행사할 수 있게 된 때부터 행사할 수 있다. 그래서 그때부터 공탁법 제9조 제3항의 시효가 진행한다(민법 제166조, 공탁선례).","c":"중","v":1},"법무사2018_24-50-3":{"w":"시효 중단 사유인 승인은 채무를 인식하고 있다는 표시여야 한다. 지급절차를 일반적으로 설명한 것만으로는 승인이 아니어서 시효가 중단되지 않는다(공탁선례).","c":"중","v":1},"법무사2018_24-50-4":{"w":"시효 중단은 당사자와 그 승계인 사이에서만 효력이 있다(민법 제169조). 그래서 피공탁자 1인에 대한 중단 사유는 다른 피공탁자의 시효에 영향이 없다.","c":"중","v":1},"법무사2018_24-50-5":{"w":"공탁규칙 제61조: 소멸시효가 완성된 공탁금에 출급·회수청구가 있으면 공탁관은 국고수입 납부 전이라도 인가하지 않는다.","c":"상","v":1},"법무사2019_25-46-1":{"w":"판례는 공탁금 지급은 공탁법이 정한 청구와 이의·항고 절차(공탁법 제12조~제14조)로 다투어야 하고 국가를 상대로 민사소송으로 지급을 청구할 수 없다고 본다.","c":"중","v":1},"법무사2019_25-46-3":{"w":"판례는 착오공탁이나 공탁원인 소멸로 회수권만 남은 상태에서 피공탁자 출급청구권에 대한 전부명령으로 공탁물을 받은 자는 법률상 원인 없이 받은 것이어서 공탁자에게 부당이득반환 의무가 있다고 본다.","c":"중","v":1},"법무사2019_25-46-4":{"w":"판례는 피공탁자가 아닌 제3자가 피공탁자를 상대로 출급청구권 확인판결을 받아도 직접 출급할 수 없다고 본다. 피공탁자는 공탁서로 형식적으로 정해지기 때문이다.","c":"중","v":1},"법무사2019_25-46-5":{"w":"판례는 지분 각 1/2로 피공탁자를 정한 공탁은 그 기재대로 출급청구권이 정해지므로 내부 실질 지분이 달라도 각자 1/2만 출급할 수 있다고 본다.","c":"중","v":1},"법무사2019_25-49-2":{"w":"계좌입금 지침은 실명 확인을 위해 주민등록번호나 사업자등록번호를 소명할 자료를 내게 하되 이미 포괄계좌 입금신청을 했으면 내지 않아도 되게 한다.","c":"중","v":1},"법무사2019_25-49-3":{"w":"계좌입금 지침은 출급지시 전에 신청을 철회하거나 포괄계좌 신청을 해지하지 않는 한 계좌로만 지급하고 신청인이나 대리인에게 직접 지급하지 못하게 한다.","c":"중","v":1},"법무사2019_25-49-4":{"w":"계좌입금 지침은 입금계좌를 반드시 신청인 명의로 하게 한다. 공탁규칙 제40조 제1항도 「자신의 예금계좌」에 입금하게 한다.","c":"상","v":1},"법무사2019_25-49-5":{"w":"계좌입금 지침은 신청인이 먼저 보관은행을 거쳐 이자소득세 원천징수 사항을 등록하고 신청서 하단에 등록확인인을 받게 한다.","c":"중","v":1},"법무사2019_25-50-3":{"w":"공탁규칙 제34조 제2호 단서는 공탁서 내용으로 회수청구권이 명백하면 증명서면을 요구하지 않는다. 민법 제489조 제1항 회수는 공탁서상 공탁자의 회수여서 원칙적으로 증명서면이 필요 없다.","c":"상","v":1},"법무사2020_26-32-1":{"w":"공탁규칙 제33조 제1호 가목: 출급청구하는 공탁금액이 5천만 원 이하이면 공탁통지서를 붙이지 않아도 된다(관공서·법인 아닌 사단·재단은 1천만 원 이하).","c":"상","v":1},"법무사2020_26-32-2":{"w":"전부채권자는 원래 회수청구권자의 지위를 넘지 못한다. 그래서 공탁규칙 제34조 제2호의 회수청구권 증명서면(착오나 원인 소멸 증명 등)을 붙여야 한다(공탁선례).","c":"중","v":1},"법무사2020_26-32-3":{"w":"공탁법 제10조는 수령할 자의 반대급부만 규정하므로 반대급부는 피공탁자의 출급만 제한하고 공탁자의 회수에는 제한사유가 아니다.","c":"상","v":1},"법무사2020_26-32-5":{"w":"피공탁자 전원이 함께 출급을 청구하면 서로 승낙한 것으로 볼 수 있어 따로 증명서면이 필요 없다. 행정예규 제1345호 제11조 제1항 단서도 같은 취지다.","c":"상","v":1},"법무사2020_26-36-2":{"w":"국가에 대한 채권양도 통지는 그 채권을 관리하는 공무원에게 도달하면 된다. 판례·공탁선례는 공탁금 지급청구권 양도통지가 검찰청을 거치지 않고 공탁관에게 직접 도달해도 유효하다고 본다.","c":"중","v":1},"법무사2020_26-36-3":{"w":"민법 제452조 제2항은 양도통지를 양수인 동의 없이 철회하지 못하게 한다. 판례는 양도인의 일방적 해제 통지도 양수인 동의가 없으면 효력이 없다고 본다.","c":"중","v":1},"법무사2020_26-36-4":{"w":"공탁 실무는 양도통지서 인영에 인감증명이 없으면 양수인 청구 때 양도인 인감증명을 내게 한다. 양도증서를 공증받아 내면 진정성이 확인되어 인감증명 없이 청구할 수 있다(공탁선례).","c":"중","v":1},"법무사2020_26-36-5":{"w":"판례·공탁선례는 출급청구권 양도통지가 공탁관에게 도달하면 불수락 의사가 적혀 있지 않은 한 공탁을 수락한 것으로 보아 민법 제489조 제1항 회수청구권이 소멸한다고 본다.","c":"중","v":1},"법무사2020_26-44-1":{"w":"계좌입금 지침은 전국공통 포괄계좌 입금신청을 국가와 지방자치단체만 할 수 있게 하고 금융기관은 제외한다.","c":"중","v":1},"법무사2020_26-44-3":{"w":"계좌입금 지침은 계좌입금 신청이 있으면 출급·회수청구서를 1통만 내게 한다.","c":"중","v":1},"법무사2020_26-44-4":{"w":"계좌입금 지침은 청구서에 계좌입금 신청 취지와 입금계좌번호·실명번호를 적고 실명 확인 자료(주민등록번호·사업자등록번호 소명자료)를 내게 한다.","c":"중","v":1},"법무사2020_26-44-5":{"w":"계좌입금 지침은 출급지시 전 철회나 포괄계좌 해지가 없으면 계좌로만 지급하고 신청인이나 대리인에게 직접 지급하지 못하게 한다.","c":"중","v":1},"법무사2020_26-46-1":{"w":"피공탁자를 알 수 없어 통지도 못 한 상태에서는 출급청구권을 행사할 수 있다고 볼 수 없다. 판례·공탁선례는 그동안 시효가 진행하지 않는다고 본다(민법 제166조).","c":"하","v":1},"법무사2020_26-46-2":{"w":"착오 공탁의 회수청구권은 공탁 때부터 행사할 수 있으므로 공탁일부터 10년(공탁법 제9조 제3항)이 지나면 시효로 소멸한다(판례).","c":"중","v":1},"법무사2020_26-46-3":{"w":"시효는 권리를 행사할 수 있는 때부터 진행하므로(민법 제166조 제1항) 반대급부 조건이 있으면 반대급부 이행 때부터, 정지조건·시기부이면 조건 성취나 기한 도래 때부터 기산한다(공탁금 소멸시효 관련 예규).","c":"중","v":1},"법무사2020_26-46-5":{"w":"지급절차의 일반적 설명은 채무 승인이 아니어서 시효를 중단시키지 않는다(공탁선례).","c":"중","v":1},"법무사2020_26-49-1":{"w":"「소멸시효 완성 전 공탁금 출급 및 회수청구 안내에 관한 업무처리지침」(행정예규 제1403호) 제2조와 공탁규칙 제60조의2 제2항: 안내 업무는 법원행정처 사법등기국에서 하고 사법등기심의관이 담당한다.","c":"상","v":1},"법무사2020_26-49-2":{"w":"행정예규 제1403호 제3조는 안내를 우편발송이나 앱메시지 등 전자적 방법으로 할 수 있게 한다. 공탁규칙 제60조의2 제1항도 「우편 등으로」 안내하게 한다.","c":"상","v":1},"법무사2020_26-49-3":{"w":"행정예규 제1403호 제4조: 직전 연도 말 기준 만 2년·4년·6년·8년 전 해에 수리된 사건 중 잔액 10만 원 이상인 변제·집행공탁 피공탁자와 재판상 보증공탁 공탁자를 우편안내 대상으로 한다(현재는 개인회생 공탁 피공탁자도 포함).","c":"상","v":1},"법무사2020_26-49-4":{"w":"안내는 시효 완성 전에 권리 행사를 알려 주려는 것이다(공탁법 제9조 제4항). 행정예규 제1403호는 지급제한사유 유무와 관계없이 대상 사건 권리자에게 안내문을 보낼 수 있게 한다.","c":"중","v":1},"법무사2021_27-32-1":{"w":"주소불명을 이유로 공탁되었는데 공탁관이 서류로 수령권을 인정하지 않아 출급을 거부하면 정당한 권리자는 공탁자인 사업시행자를 상대로 출급청구권 확인의 소를 낼 이익이 있다는 것이 판례다.","c":"중","v":1},"법무사2021_27-38-1":{"w":"변제공탁의 출급청구권은 공탁서에 지정된 피공탁자에게 생기므로 출급청구권자는 피공탁자나 그 승계인이다(판례, 공탁규칙 제33조).","c":"중","v":1},"법무사2021_27-38-2":{"w":"판례는 피공탁자가 실체 관계와 관계없이 공탁서 기재에 따라 형식적으로 정해진다고 본다.","c":"중","v":1},"법무사2021_27-38-3":{"w":"판례는 피공탁자가 공탁서로 형식적으로 정해지므로 실체법상 채권자라도 피공탁자가 아니면 출급청구권을 행사할 수 없다고 본다.","c":"중","v":1},"법무사2021_27-38-4":{"w":"판례는 착오공탁이나 공탁원인 소멸이 있으면 공탁자의 회수권만 남고 피공탁자의 출급청구권은 존재하지 않는다고 본다(공탁법 제9조 제2항 제2호·제3호).","c":"중","v":1},"법무사2021_27-39-2":{"w":"공탁선례는 형사재판 중 피공탁자가 수령을 거절했다는 사정만으로 회수에 동의한 것으로 보지 않는다. 현행 공탁법 제9조의2 제1항 제1호는 회수 동의와 함께 「공탁소에」 수령거절 의사를 통고한 경우를 회수 예외로 따로 정한다.","c":"중","v":1},"법무사2021_27-39-4":{"w":"공탁법 제9조의2 제1항 제1호: 형사사건 피해자를 위한 변제공탁이라도 피공탁자가 회수에 동의하면 그 사실을 증명해 회수할 수 있다. 형사사건 결과와는 관계가 없다.","c":"상","v":1},"법무사2021_27-45-2":{"w":"「장기미제 공탁사건 등의 공탁금 지급시 유의사항」(행정예규 제1390호) 제9조는 토지보상법 제40조 제2항 제1호·제2호 공탁 중 공탁 당시 1천만 원 이상이고 공탁 후 만 3년이 지난 사건에도 인가 전 소속과장 결재(제5조)를 적용한다. 절대적 불확지공탁도 제2호에 해당한다.","c":"중","v":1},"법무사2022_28-43-1":{"w":"판례는 피공탁자가 공탁서 기재로 형식적으로 정해지므로 실체법상 채권자라도 피공탁자가 아니면 출급할 수 없다고 본다.","c":"중","v":1},"법무사2022_28-43-2":{"w":"판례는 공유자 전원을 피공탁자로 한 수용보상금 공탁금을 가분채권으로 보아 공유자 각자가 등기기록상 지분만큼 출급청구할 수 있다고 본다.","c":"중","v":1},"법무사2022_28-43-4":{"w":"행정예규 제1345호 제11조 제3항: 상대적 불확지 수용보상금 공탁에서 공탁자의 승낙서나 공탁자·국가를 상대로 한 판결은 출급청구권 증명서면이 아니다. 귀속은 피공탁자들 사이에서 정해야 하기 때문이다.","c":"상","v":1},"법무사2022_28-43-5":{"w":"행정예규 제1345호 제11조 제1항 단서: 상대적 불확지공탁에서 피공탁자 전원이 공동으로 출급을 청구하면 별도 서면을 첨부하지 않아도 된다.","c":"상","v":1},"법무사2022_28-48-1":{"w":"시효는 권리를 행사할 수 있는 때부터 진행한다(민법 제166조 제1항). 판례는 상대적 불확지 변제공탁 출급청구권의 시효를 출급청구권자가 확정된 때부터 기산한다.","c":"중","v":1},"법무사2022_28-48-2":{"w":"민사집행법 제160조 제2항의 불출석 채권자 배당액 공탁은 공탁 즉시 그 채권자가 출급할 수 있으므로 공탁일부터 시효를 기산한다(공탁금 소멸시효 관련 예규).","c":"중","v":1},"법무사2022_28-48-3":{"w":"공탁원인이 소멸해야 회수청구권을 행사할 수 있으므로 그 회수청구권 시효는 원인이 소멸한 때부터 진행한다(민법 제166조, 공탁금 소멸시효 관련 예규).","c":"중","v":1},"법무사2022_28-48-4":{"w":"착오공탁의 회수청구권은 공탁한 때부터 행사할 수 있어 공탁일부터 시효를 기산한다(판례, 공탁금 소멸시효 관련 예규).","c":"중","v":1},"법무사2023_29-43-1":{"w":"공탁관이 권리자에게 공탁사건 완결 여부 문의서를 보내는 것은 국가가 채무를 인식하고 있음을 표시한 승인이다(민법 제168조 제3호). 그래서 시효가 중단된다(공탁금 소멸시효 관련 예규).","c":"중","v":1},"법무사2023_29-43-2":{"w":"공탁관이 지급할 수 있다는 취지를 구두로 답하면 채무 승인이 되어 시효가 중단된다(공탁금 소멸시효 관련 예규). 일반적 절차 설명과는 구별된다.","c":"중","v":1},"법무사2023_29-43-4":{"w":"압류·가압류·가처분은 그 채권자가 채무자에게 가지는 채권의 시효를 중단할 뿐 압류된 채권(공탁금 지급청구권) 자체의 시효를 중단시키지 않는다는 것이 판례·공탁선례다.","c":"중","v":1},"법무사2023_29-43-5":{"w":"출급청구권과 회수청구권은 별개의 권리여서 한쪽의 시효 중단은 다른 쪽에 영향이 없다(민법 제169조, 공탁선례).","c":"중","v":1},"법무사2023_29-47-1":{"w":"판례는 공유자 전원을 피공탁자로 한 수용보상금 공탁금을 가분채권으로 보아 각자 등기부상 지분만큼 출급청구할 수 있다고 본다.","c":"중","v":1},"법무사2023_29-47-2":{"w":"판례는 추심채권자 지위가 집행채권 양도에 따라 양수인에게 이전된다고 본다. 그래서 양수인은 승계집행문 등으로 그 지위를 이어받을 뿐 국가를 제3채무자로 다시 압류·추심명령을 받을 필요가 없다.","c":"중","v":1},"법무사2023_29-47-3":{"w":"판례는 여러 취소채권자를 피공탁자로 한 상대적 불확지공탁에서 각 피공탁자가 각자의 확정판결 등에서 인정된 가액배상금 비율에 따라 출급할 수 있다고 본다.","c":"중","v":1},"법무사2023_29-47-5":{"w":"판례는 착오공탁 후 회수 전에 피공탁자 출급청구권에 대한 전부명령으로 공탁물을 받은 자는 출급청구권이 존재하지 않았으므로 공탁자에게 부당이득을 반환해야 한다고 본다.","c":"중","v":1},"법무사2024_30-42-1":{"w":"공탁규칙 제34조 제1호 나목: 회수청구서에는 공탁서를 붙여야 하지만 이해관계인의 승낙서를 붙이면 공탁서를 첨부하지 않아도 된다.","c":"상","v":1},"법무사2024_30-43-1":{"w":"판례는 적법한 변제공탁이면 피공탁자가 불수락을 표시해도 출급청구권 존재에 영향이 없다고 본다. 그래서 피공탁자의 채권자는 그 출급청구권을 강제집행할 수 있다.","c":"중","v":1},"법무사2024_30-43-2":{"w":"판례는 부당한 반대급부 조건부 공탁이 채권자가 수락하지 않는 한 무효라고 본다. 수락해서 출급하려면 공탁법 제10조에 따라 반대급부 이행 증명서면을 내야 한다.","c":"중","v":1},"법무사2024_30-43-4":{"w":"토지보상법 제40조 제2항 제3호: 사업시행자가 재결에 불복하면 자기 산정액을 지급하고 차액을 공탁한다. 행정예규 제1345호 제13조 제1항은 피공탁자가 불복절차가 끝날 때까지 출급할 수 없게 한다.","c":"상","v":1},"법무사2024_30-43-5":{"w":"상대적 불확지공탁에서 출급하려면 다른 피공탁자와의 관계에서 출급권을 증명해야 한다. 공탁 뒤 가처분이 취하되었다는 증명은 가처분권자가 보상금 귀속을 포기했다는 증명이 아니어서 승낙서(인감증명 첨부) 등이 필요하다(공탁선례).","c":"중","v":1},"법무사2024_30-44-1":{"w":"양수인은 피공탁자 지위를 이어받은 승계인이어서 원래 지급청구권의 요건사실과 양수 사실을 함께 증명하는 서면을 내야 한다(공탁규칙 제33조·제34조, 공탁선례).","c":"중","v":1},"법무사2024_30-44-2":{"w":"국가에 대한 양도통지는 채권을 관리하는 공무원에게 도달하면 된다. 공탁금 지급청구권은 공탁관이 관리하므로 검찰청을 거치지 않고 공탁관에게 직접 도달해도 유효하다(판례·공탁선례).","c":"중","v":1},"법무사2024_30-44-4":{"w":"양도통지가 공탁관에게 도달하면 인감증명이 없어도 적법한 통지로 다룬다. 그래서 양도인은 더 이상 지급청구를 할 수 없다(공탁선례).","c":"중","v":1},"법무사2024_30-44-5":{"w":"판례·공탁선례는 출급청구권 양도통지서가 도달하면 불수락 표시가 없는 한 그때 공탁을 수락한 것으로 보아 민법 제489조 제1항 회수청구권이 소멸한다고 본다.","c":"중","v":1},"법무사2024_30-46-1":{"w":"가분채권은 채권자마다 이행지 공탁소에 공탁하는 것이 원칙이지만 원인과 공탁소가 같으면 1건으로 공탁할 수 있다. 이 경우 각 채권자는 자기 몫만 출급한다(공탁선례).","c":"중","v":1},"법무사2024_30-46-3":{"w":"확정된 전부명령은 국가에 송달된 때로 소급해 효력이 생긴다(민사집행법 제229조 제7항, 제231조). 그래서 송달 뒤 확정 전에 온 다른 압류는 경합하지 않고 전부채권자는 승계인으로 출급할 수 있다(판례).","c":"중","v":1},"법무사2024_30-46-4":{"w":"조합재산 수용보상금은 지분을 특정했더라도 조합원 전체의 합유다(민법 제704조). 그래서 출급은 조합원 전원이 청구해야 한다(공탁선례).","c":"중","v":1},"법무사2024_30-46-5":{"w":"행정예규 제1345호 제5조 제1항 제1호는 소유권등기말소청구권 가처분이 있으면 「소유자 또는 가처분채권자」로 상대적 불확지공탁을 하게 한다. 가처분채권자의 본안 패소 확정판결은 토지소유자의 출급청구권을 증명하는 서면이다(같은 지침 제11조 제2항 취지).","c":"중","v":1},"법무사2024_30-50-1":{"w":"공탁법 제10조는 수령할 자의 반대급부만 정하므로 반대급부는 피공탁자의 출급만 제한하고 공탁자의 회수는 제한하지 않는다.","c":"상","v":1},"법무사2024_30-50-2":{"w":"재판상 담보공탁은 법원의 담보제공명령이 있어야 하는 것이어서 명령 없이 임의로 한 공탁은 원인이 없는 착오 공탁이다. 공탁법 제9조 제2항 제2호로 회수할 수 있다(공탁선례).","c":"중","v":1},"법무사2024_30-50-3":{"w":"판례는 선행 양도에 다툼이 없어 불확지 사유가 없는데 혼합공탁을 했다면 무효이고 공탁자가 착오공탁으로 회수할 수 있다고 본다.","c":"중","v":1},"법무사2024_30-50-5":{"w":"행정예규 제1345호 제9조: 수용보상금 공탁자는 민법 제489조 제1항에 따라 회수할 수 없고 착오나 재결 무효·취소 등 공탁원인 소멸이 있을 때만 회수한다. 수용 효과를 지키기 위해서다.","c":"상","v":1},"법무사2025_31-42-1":{"w":"판례는 상대적 불확지 공탁의 진정한 출급청구권자를 공탁자인 채무자와의 본래 법률관계에서 누가 진정한 채권자인지로 판단한다.","c":"중","v":1},"법무사2025_31-42-3":{"w":"판례는 피공탁자의 출급청구권을 압류·추심한 채권자 같은 특별한 사정이 없으면 제3자는 피공탁자를 상대로 출급청구권 확인을 구할 이익이 없다고 본다.","c":"중","v":1},"법무사2025_31-42-4":{"w":"피공탁자 전원이 함께 출급을 청구하면 청구서 기재로 서로 승낙한 것으로 볼 수 있다. 그래서 별도 증명서면이 필요 없다(공탁 실무, 행정예규 제1345호 제11조 제1항 단서).","c":"중","v":1},"법무사2025_31-42-5":{"w":"상대적 불확지공탁의 귀속은 피공탁자들 사이에서 정해야 한다. 그래서 공탁자의 승낙서나 공탁자·국가를 상대로 한 판결은 출급청구권 증명서면이 아니다(판례·공탁선례).","c":"중","v":1},"법무사2025_31-43-1":{"w":"행정예규 제1390호 제5조: 공탁 당시 1천만 원 이상인 장기미제 공탁사건이나 지급청구금액 10억 원 이상 고액공탁사건의 출급·회수청구를 받으면 공탁관은 인가 전에 전자결재로 소속과장 결재를 받는다.","c":"상","v":1},"법무사2025_31-43-2":{"w":"판례는 공탁관의 인가로 출급되었다면 진정한 권리자는 잘못 받은 자에게 부당이득을 청구할 수 있을 뿐 국가를 상대로 민사소송으로 다시 지급을 구할 수 없다고 본다.","c":"중","v":1},"법무사2025_31-43-3":{"w":"공탁규칙 제48조는 불수리를 이유를 적은 결정으로 하게 한다. 공탁관은 보정·취하를 권할 수 있지만 응하지 않으면 불수리결정을 해야 하고 접수 자체를 거부할 수 없다(불수리결정 업무처리지침).","c":"중","v":1},"법무사2025_31-43-4":{"w":"공탁규칙 제41조의 보증지급은 공탁통지서나 공탁서를 첨부할 수 없을 때 보증서로 갈음하는 제도다. 주소 불일치로 동일인을 증명하는 데까지 넓혀 쓸 수 없다(공탁선례).","c":"중","v":1},"법무사2025_31-46-1":{"w":"시효는 권리를 행사할 수 있는 때부터 진행하므로(민법 제166조 제1항) 반대급부 조건이 있으면 이행 때부터, 정지조건·시기부이면 조건 성취나 기한 도래 때부터 기산한다(공탁금 소멸시효 관련 예규).","c":"중","v":1},"법무사2025_31-46-2":{"w":"담보제공자의 회수청구권은 담보 원인이 소멸해야 행사할 수 있다. 그래서 본안 승소면 재판 확정일이나 종국일부터, 패소면 담보취소결정 확정일부터 시효를 기산한다(공탁금 소멸시효 관련 예규).","c":"중","v":1},"법무사2025_31-46-3":{"w":"배당 등 관공서 결정에 따라 지급하는 공탁금은 지급위탁에 따른 증명서를 받아야 청구할 수 있으므로 증명서 교부일부터 시효를 기산한다(공탁금 소멸시효 관련 예규).","c":"중","v":1},"법무사2025_31-46-4":{"w":"공탁사실증명서 교부는 국가가 채무를 인식한다는 표시여서 승인으로 시효가 중단된다(민법 제168조 제3호). 다만 지급청구권자 등 권리자에게 교부한 경우에 한한다(공탁금 소멸시효 관련 예규).","c":"중","v":1},"법무사2026_32-32-1":{"w":"대공탁·부속공탁은 상환금이나 이자를 금전으로 공탁한 것이어서 공탁법 제9조 제3항의 금전 공탁금 시효 대상이 된다. 같은 항은 유가증권상환금·배당금 공탁도 금전공탁에 포함한다.","c":"상","v":1},"법무사2026_32-32-2":{"w":"착오공탁 회수청구권은 공탁 때부터 행사할 수 있으므로 공탁일부터 10년(공탁법 제9조 제3항)이 지나면 시효로 소멸한다(판례).","c":"중","v":1},"법무사2026_32-32-4":{"w":"행정예규 제1403호 제6조의2 제2항: 소멸시효가 진행 중인 사건의 공탁자나 피공탁자에게 안내문이 송달되면 시효가 중단되고 송달일부터 다시 10년이 진행한다.","c":"상","v":1},"법무사2026_32-32-5":{"w":"반대급부가 이행되지 않으면 출급청구권을 행사할 수 없어 시효가 진행하지 않는다(민법 제166조). 그런데 국고귀속되었으면 착오이므로 공탁관은 반환받아 공탁절차를 회복한다(공탁규칙 제64조, 공탁선례).","c":"중","v":1},"법무사2026_32-35-1":{"w":"판례는 출급청구권과 회수청구권이 같은 공탁물에 대한 별개의 독립한 권리여서 한쪽의 양도·질권·압류는 다른 쪽에 영향이 없고 한쪽 양도 뒤에도 다른 쪽을 처분할 수 있다고 본다.","c":"중","v":1},"법무사2026_32-35-3":{"w":"담보공탁 회수청구권은 담보권이 소멸해야 행사할 수 있으므로 양수인이나 전부채권자도 그 전에는 권리를 행사할 수 없다. 피공탁자는 질권자와 같은 권리로 여전히 출급할 수 있다(민사소송법 제123조, 판례).","c":"중","v":1},"법무사2026_32-35-4":{"w":"민사집행법 제130조 제6항에 따라 항고가 기각되면 항고보증은 배당할 금액에 포함되어 공탁자는 회수할 수 없다. 판례는 그 전에 회수청구권을 압류·전부해도 배당채권자의 출급청구권에는 영향이 없어 공탁관이 출급을 거부할 수 없다고 본다.","c":"중","v":1},"법무사2026_32-35-5":{"w":"변제공탁에서는 회수청구권이 소멸하지 않는 한 공탁자가 언제든 회수할 수 있다(민법 제489조 제1항). 그래서 두 권리 사이에 우열이 없고 먼저 행사한 쪽이 우선한다(판례·공탁선례).","c":"중","v":1},"법무사2026_32-40-2":{"w":"판례는 피공탁자가 아닌 제3자가 피공탁자를 상대로 출급청구권 확인판결을 받아도 직접 출급청구할 수 없다고 본다. 피공탁자는 공탁서로 형식적으로 정해진다.","c":"중","v":1},"법무사2026_32-40-3":{"w":"피공탁자는 공탁서 기재로 정해지므로 불가분채권자 2인을 피공탁자로 적었으면 공탁자 동의서가 있어도 1인 단독으로 출급할 수 없다. 전원이 청구하거나 나머지의 위임을 받아야 한다(공탁선례).","c":"중","v":1},"법무사2026_32-40-4":{"w":"채권자 사망 후 상속인을 알 수 없으면 민법 제487조 후문의 불확지공탁을 할 수 있다. 상속인은 가족관계증명서·제적등본 등 상속 증명서면으로 출급청구권을 증명해 출급한다(공탁규칙 제33조 제2호).","c":"하","v":1},"법무사2026_32-40-5":{"w":"피공탁자로부터 상속·양도·전부명령 등으로 출급청구권을 승계한 자는 승계 사실 증명서면을 붙여 승계인으로 출급할 수 있다(공탁규칙 제33조, 행정예규 제1345호 제10조 제1항 취지).","c":"중","v":1},"법무사2026_32-42-1":{"w":"공탁규칙 제33조 제1호 다목: 강제집행이나 체납처분으로 출급청구하면 공탁통지서를 붙이지 않아도 된다.","c":"상","v":1},"법무사2026_32-42-2":{"w":"공탁규칙 제33조 제1호 나목: 공탁서나 이해관계인의 승낙서를 첨부하면 공탁통지서를 붙이지 않아도 된다.","c":"상","v":1},"법무사2026_32-42-3":{"w":"공탁규칙 제33조 제1호 가목: 출급청구 금액이 5천만 원 이하이면 공탁통지서를 붙이지 않아도 된다. 5천만 원은 「이하」에 들어간다.","c":"상","v":1},"법무사2026_32-42-4":{"w":"공탁규칙 제33조 제1호 가목의 면제는 5천만 원 이하일 때만이어서 법인이 6천만 원을 출급청구하면 다른 면제사유가 없는 한 공탁통지서를 붙인다.","c":"상","v":1},"법무사2026_32-43-1":{"w":"피공탁자는 공탁서 기재로 형식적으로 정해지므로 「甲과 乙」이 피공탁자이면 甲 단독소유 증명서류를 내도 공탁관은 甲 단독 출급청구를 불수리할 수밖에 없다(판례·공탁선례).","c":"중","v":1},"법무사2026_32-43-3":{"w":"수용 효력은 수용 개시일에 등기명의인 앞으로 보상금을 공탁하면서 생긴다. 판례는 매수인이 그 뒤 이전등기를 해도 매도인으로부터 출급청구권을 양수받지 않으면 직접 출급할 수 없다고 본다(행정예규 제1345호 제10조 제3항 제2호).","c":"중","v":1},"법무사2026_32-43-4":{"w":"사업시행자는 수용 개시일에 소유권을 원시취득하고 다른 권리는 소멸한다(토지보상법 제45조). 판례는 가처분권자가 개시일 후 승소해도 이전등기를 할 수 없고 보상금 수령권자도 아니라고 본다.","c":"중","v":1},"법무사2026_32-43-5":{"w":"명의신탁을 해지했어도 수용 개시일 전에 등기를 회복하지 못했으면 보상금청구권은 수용 당시 소유자가 취득한다는 것이 판례다. 종중은 출급청구권을 양수받아야 출급할 수 있다(행정예규 제1345호 제10조 제3항 제2호).","c":"중","v":1},"법무사2021_27-09-5":{"old":1,"ow":"출제 당시 정답 O. 2024 개정(2025.1.31 시행)으로 요역지가 다른 등기소 관할일 때 그 등기소에 통지하도록 한 제71조 제2항·제3항이 삭제되었고, 지금은 승역지에 등기한 등기관이 관할이 달라도 요역지 등기기록에 직접 기록하므로 틀린 문장이다(부동산등기법 제7조의2 제2항, 제71조 제1항)."},"법무사2019_25-18-2":{"old":1,"ow":"출제 당시 정답 O. 2024.11.29 개정 부동산등기규칙(2025.1.31 시행)으로 지금은 등기소에 이의신청서를 내는 방법 외에 전산정보처리조직(인터넷등기소)으로 이의신청정보를 보내는 방법도 있으므로, 반드시 서면으로 등기소에 제출해야 한다는 부분이 틀린 문장이다(부동산등기법 제101조, 부동산등기규칙 제158조)."},"법무사2018_24-49-2":{"old":1,"ow":"출제 당시 정답 O. 이후 개정으로 지금은 공탁자가 접수공탁소 공탁관에게서 받은 공탁금계좌납입 안내문에 적힌 가상계좌로 공탁금을 내는 것이 원칙이고, 관할공탁소 공탁관의 보통예금계좌는 가상계좌를 쓸 수 없는 부득이한 경우에만 쓰므로 틀린 문장이다(관할공탁소 이외의 공탁소에서의 공탁사건처리 지침 4.가.2), 10.)."},"법무사2021_27-39-5":{"old":1,"ow":"출제 당시 정답 O. 2024.10.16 개정으로 신설된 공탁법 제9조의2 제1항에 따라 형사사건 피해자를 위한 변제공탁은 공탁원인 소멸(제9조 제2항 제3호)을 이유로 회수할 수 없고 착오공탁만 회수 사유로 남았으므로 틀린 문장이다(공탁법 제9조의2 제1항)."},"법무사2016_22-45-3":{"old":1,"ow":"출제 당시 정답 O. 2025. 4. 29. 발령되어 2025. 6. 1. 시행된 「재외국민 등의 공탁에 관한 업무처리지침」(행정예규 제1431호)은 종전 「재외국민 등의 공탁금지급청구시 첨부서면에 관한 예규」를 폐지했다(부칙 제2조). 이 지침 제8조는 재외국민이 인감증명법에 따른 인감증명서를 내거나 위임장에 재외공관 공증법에 따른 인증을 받는 방법만 정한다. 일본 인감증명서에 영사 확인을 받는 방식은 지금 규정에 없다."},"법무사2021_27-39-3":{"old":1,"ow":"출제 당시 정답 O. 2024. 10. 16. 개정되어 2025. 1. 17. 시행된 공탁법 제9조의2 제1항은 형사사건 피해자를 위한 변제공탁의 회수를 회수제한신고 여부와 관계없이 법으로 제한한다. 다만 피공탁자가 회수에 동의한 경우뿐 아니라 공탁소에 수령거절 의사를 통고한 경우(제1호)와 무죄판결 확정·불기소 결정(기소유예 제외)이 있는 경우(제2호)에도 회수를 허용한다. 지금은 유죄가 확정되었더라도 피공탁자가 공탁소에 수령거절을 통고했으면 동의서 없이 회수할 수 있다."}};
